const isValidOmsWarehouseValue = (value) => {
  const normalized = String(value || '').replace(/\s+/g, '').replace(/^[：:]|[：:]$/g, '');
  if (!normalized || invalidOmsWarehouseValues.has(normalized)) return false;
  if (/^(?:发货|下单|创建|订单)?时间(?:[:：].*)?$/.test(normalized)) return false;
  if (/^(?:仓库|发货仓库|推荐仓库|物流|物流信息)$/.test(normalized)) return false;
  return true;
};
const lowValuePattern = /低值(?:品|商品|货品)?|低价(?:品|商品|货品)?/;
