const adoptLivePddAnchor = async () => {
  const selected = selectLivePddPage(context.pages(), pddPage);
  if (!selected || selected === pddPage || selected.isClosed()) return pddPage;
  const previous = pddPage;
  derivedPages.delete(selected);
  derivedPageMeta.delete(selected);
  pddPage = monitorSystemPage('pdd', selected);
  if (previous && !previous.isClosed()) registerDerivedPage(previous, 'replaced-pdd-anchor');
  persistSystemTabs('pdd');
  return pddPage;
};

const adoptLiveSystemAnchor = async (system) => {
  if (system === 'pdd') return adoptLivePddAnchor();
  const currentPage = system === 'oms' ? omsPage : tmsPage;
  const selected = selectLiveSystemPage(system, context.pages(), currentPage);
  if (!selected || selected === currentPage || selected.isClosed()) return currentPage;
  derivedPages.delete(selected);
  derivedPageMeta.delete(selected);
  const monitored = monitorSystemPage(system, selected);
  if (system === 'oms') omsPage = monitored;
  else tmsPage = monitored;
  if (currentPage && !currentPage.isClosed()) {
    registerDerivedPage(currentPage, `replaced-${system}-anchor`);
  }
  persistSystemTabs(system);
  return monitored;
};

const assignRecoveredSystemPage = (system, targetPage) => {
  // createBackgroundPage emits the context "page" event before it resolves,
  // so a replacement anchor is briefly registered as a derived popup.
  derivedPages.delete(targetPage);
  derivedPageMeta.delete(targetPage);
  const monitored = monitorSystemPage(system, targetPage);
  if (system === 'pdd') pddPage = monitored;
  else if (system === 'oms') omsPage = monitored;
  else if (system === 'tms') tmsPage = monitored;
  else throw new Error(`Unknown system anchor: ${system}`);
  return monitored;
};


const updateManagedBrowserTitle = (system, status, targetPage) => {
  if (!targetPage || targetPage.isClosed()) return;
  const systemLabel = { pdd: 'PDD', oms: 'OMS', tms: 'TMS' }[system] || String(system || '').toUpperCase();
  const statusLabel = {
    authenticated: '已登录',
    expired: '需登录',
    unreachable: '连接异常',
    'verification-required': '待验证',
    'identity-pending': '身份待确认',
    'identity-mismatch': '身份不符',
  }[status] || '待检测';
  const identity = readProgress().pddShopIdentity || {};
  const detectedShopName = normalizePddShopNameCandidate(identity.mallName || identity.actualShopName);
  const detectedMallId = normalizePddMallId(identity.mallId);
  const expectedAccountLabel = expectedShopName || '账号待识别';
  const currentAccountLabel = detectedShopName && !isMaskedPddShopIdentityName(detectedShopName)
    ? detectedShopName
    : null;
  const identityLabel = detectedMallId ? `mall:${detectedMallId}` : 'mall:待识别';
  const accountLabel = currentAccountLabel
    && canonicalPddShopIdentityName(currentAccountLabel) !== canonicalPddShopIdentityName(expectedAccountLabel)
    ? `应登录：${expectedAccountLabel}｜当前：${currentAccountLabel}`
    : `应登录：${expectedAccountLabel}`;
  const shopLabel = `${accountLabel}（${shopId}｜${identityLabel}）`;
  void targetPage.evaluate(installManagedPageTitle, {
    prefix: `【PDD店铺：${shopLabel}｜${systemLabel}${statusLabel}】`,
    fallbackTitle: '业务页面',
  }).catch(() => {});
};

const managedTitleSystemForPage = (targetPage) => {
  if (!targetPage || targetPage.isClosed()) return null;
  const url = String(targetPage.url?.() || '');
  if (/^https:\/\/mms\.pinduoduo\.com(?:\/|$)/u.test(url)) return 'pdd';
  if (/^https:\/\/www\.jeoms\.com(?:\/|$)/u.test(url)) return 'oms';
  if (/^https?:\/\/tms\.aipro123\.top(?:\/|$)/u.test(url)) return 'tms';
  return null;
};

const attachManagedBrowserTitle = (targetPage, system = null) => {
  if (!targetPage || targetPage.isClosed()) return;
  const pageState = targetPage.__pddManagedTitleState || {};
  if (!pageState.navigationListenerAttached) {
    targetPage.on('framenavigated', (frame) => {
      if (frame !== targetPage.mainFrame()) return;
      const resolvedSystem = system || managedTitleSystemForPage(targetPage);
      if (!resolvedSystem) return;
      const progress = readProgress();
      updateManagedBrowserTitle(
        resolvedSystem,
        progress.authHealth?.[resolvedSystem]?.status || 'checking',
        targetPage,
      );
    });
    targetPage.__pddManagedTitleState = { ...pageState, navigationListenerAttached: true };
  }
  const resolvedSystem = system || managedTitleSystemForPage(targetPage);
  if (!resolvedSystem) return;
  const progress = readProgress();
  updateManagedBrowserTitle(
    resolvedSystem,
    progress.authHealth?.[resolvedSystem]?.status || 'checking',
    targetPage,
  );
};

const pddLoginNetworkDiagnosticsEnabled = /^(?:1|true|yes)$/iu.test(
  String(process.env.WORKFLOW_PDD_LOGIN_NETWORK_DIAGNOSTICS || ''),
) && (!String(process.env.WORKFLOW_PDD_LOGIN_NETWORK_DIAGNOSTICS_SHOP_ID || '').trim()
  || String(process.env.WORKFLOW_PDD_LOGIN_NETWORK_DIAGNOSTICS_SHOP_ID).trim() === shopId);
const pddLoginNetworkDiagnosticsPath = path.join(diagnosticsDir, 'pdd-login-network.jsonl');
const sanitizeDiagnosticUrl = (value) => {
  try {
    const parsed = new URL(value);
    return `${parsed.protocol}//${parsed.host}${parsed.pathname}`;
  } catch {
    return String(value || '').split('?')[0].slice(0, 1000);
  }
};
const isRelevantPddLoginDiagnosticRequest = (value) => {
  const sanitized = sanitizeDiagnosticUrl(value);
  return /(?:\/janus\/api\/scan\/login\/qrcode|beast\.pdd\.net|risk|fingerprint|captcha|verify)/iu
    .test(sanitized);
};
const appendPddLoginNetworkDiagnostic = (entry) => {
  if (!pddLoginNetworkDiagnosticsEnabled) return;
  fs.mkdirSync(diagnosticsDir, { recursive: true, mode: 0o700 });
  fs.appendFileSync(pddLoginNetworkDiagnosticsPath, `${JSON.stringify({
    at: new Date().toISOString(),
    shopId,
    ...entry,
  })}\n`, { encoding: 'utf8', mode: 0o600 });
};
const attachPddLoginNetworkDiagnostics = (targetPage) => {
  if (!pddLoginNetworkDiagnosticsEnabled || !targetPage || targetPage.isClosed()) return;
  if (targetPage.__pddLoginNetworkDiagnosticsAttached) return;
  targetPage.__pddLoginNetworkDiagnosticsAttached = true;
  targetPage.on('requestfailed', (request) => {
    const pageUrl = targetPage.url();
    if (!/mms\.pinduoduo\.com\/login/iu.test(pageUrl)
      && !isRelevantPddLoginDiagnosticRequest(request.url())) return;
    appendPddLoginNetworkDiagnostic({
      event: 'requestfailed',
      pageUrl: sanitizeDiagnosticUrl(pageUrl),
      requestUrl: sanitizeDiagnosticUrl(request.url()),
      method: request.method(),
      resourceType: request.resourceType(),
      failure: String(request.failure()?.errorText || 'unknown request failure').slice(0, 500),
    });
  });
  targetPage.on('response', (response) => {
    const requestUrl = response.url();
    if (response.ok() && !isRelevantPddLoginDiagnosticRequest(requestUrl)) return;
    const pageUrl = targetPage.url();
    if (!/mms\.pinduoduo\.com\/login/iu.test(pageUrl)
      && !isRelevantPddLoginDiagnosticRequest(requestUrl)) return;
    const base = {
      event: 'response',
      pageUrl: sanitizeDiagnosticUrl(pageUrl),
      requestUrl: sanitizeDiagnosticUrl(requestUrl),
      method: response.request().method(),
      resourceType: response.request().resourceType(),
      status: response.status(),
      ok: response.ok(),
    };
    const responsePath = new URL(requestUrl).pathname;
    if (/\/api\/phantom\/obtain_captcha(?:$|\/)/iu.test(responsePath)) {
      void response.json().then((payload) => {
        appendPddLoginNetworkDiagnostic({
          ...base,
          result: {
            code: payload?.code ?? null,
            type: payload?.type ?? null,
            pictureCount: Array.isArray(payload?.pictures) ? payload.pictures.length : null,
            hasContent: Boolean(payload?.content),
          },
        });
      }).catch(() => appendPddLoginNetworkDiagnostic(base));
      return;
    }
    if (!/\/janus\/api\/scan\/login\/qrcode(?:$|\/)/iu.test(responsePath)) {
      appendPddLoginNetworkDiagnostic(base);
      return;
    }
    void response.json().then((payload) => {
      appendPddLoginNetworkDiagnostic({
        ...base,
        result: {
          success: payload?.success ?? null,
          errorCode: payload?.errorCode ?? payload?.error_code ?? payload?.code ?? null,
          errorMsg: String(payload?.errorMsg || payload?.error_msg || payload?.message || payload?.msg || '')
            .slice(0, 500),
          hasQrUri: Boolean(payload?.result?.uri || payload?.uri),
        },
      });
    }).catch(() => appendPddLoginNetworkDiagnostic(base));
  });
};

// Label every permanent anchor immediately, including the about:blank pages
// used while OMS/TMS are warming up. This keeps each resident shop window
// identifiable without activating it or stealing the operator's foreground.
for (const [system, targetPage] of [
  ['pdd', pddPage],
  ['oms', omsPage],
  ['tms', tmsPage],
]) {
  attachManagedBrowserTitle(targetPage, system);
}

// Derived order/detail/login tabs must carry the same shop identity as their
// permanent anchors. Otherwise Windows groups them under generic platform
// titles such as “工单登记” or “商家后台”, making the shop impossible to tell.
for (const page of context.pages()) {
  attachPddPostLoginBarrierListener(page);
  attachManagedBrowserTitle(page);
}
context.on('page', (page) => attachManagedBrowserTitle(page));
for (const page of context.pages()) attachPddLoginNetworkDiagnostics(page);
context.on('page', (page) => attachPddLoginNetworkDiagnostics(page));

const updateAuthHealth = (system, status, targetPage, extra = {}) => {
  const progress = readProgress();
  const checkedAt = new Date().toISOString();
  const observedUrl = targetPage?.isClosed() ? null : targetPage?.url() || null;
  const networkErrorObserved = status === 'authenticated'
    && isBrowserNetworkErrorUrl(observedUrl);
  const effectiveStatus = networkErrorObserved ? 'unreachable' : status;
  const observation = {
    status: effectiveStatus,
    url: observedUrl,
    checkedAt,
    confidence: extra.confidence || (effectiveStatus === 'unknown' ? 'weak' : 'confirmed'),
    source: extra.source || (effectiveStatus === 'unknown'
      ? 'resident-runtime-observer'
      : 'controlled-workflow-auth-check'),
    evidence: extra.evidence || (effectiveStatus === 'authenticated'
      ? 'rendered-business-session'
      : effectiveStatus === 'expired' ? 'controlled-login-check' : effectiveStatus),
    ...extra,
  };
  if (networkErrorObserved) {
    Object.assign(observation, {
      status: 'unreachable',
      confidence: 'confirmed',
      source: 'controlled-workflow-connectivity-check',
      evidence: 'browser-network-error-page',
    });
  }
  const mergedHealth = mergeSystemAuthHealth(progress.authHealth?.[system], observation);
  let titleStatus = mergedHealth?.status || effectiveStatus;
  if (system === 'pdd' && effectiveStatus === 'authenticated') {
    const observedShopName = progress.pddShopIdentity?.actualShopName;
    const observedCanonical = canonicalPddShopIdentityName(observedShopName);
    const expectedCanonical = canonicalPddShopIdentityName(expectedShopName);
    if (isMaskedPddShopIdentityName(observedShopName)) titleStatus = 'identity-pending';
    else if (observedCanonical && expectedCanonical && observedCanonical !== expectedCanonical) {
      titleStatus = 'identity-mismatch';
    }
  }
  updateManagedBrowserTitle(system, titleStatus, targetPage);
  return writeProgress({
    authHealth: {
      ...(progress.authHealth || {}),
      [system]: mergedHealth,
    },
    ...(effectiveStatus === 'authenticated' ? { manualReview: null, error: null } : {}),
  });
};

const maybeBringToFront = async (targetPage, { manual = false, verification = false, force = false } = {}) => {
  await waitForPddPostLoginBarrier(targetPage, 'browser-window-operation');
  const shouldActivate = force
    || workflowForegroundMode === 'always'
    || (verification && workflowAutoFocusVerification)
    || (workflowForegroundMode === 'manual-only' && manual);
  if (!shouldActivate || !targetPage || targetPage.isClosed()) return false;
  await targetPage.bringToFront();
  return true;
};

// Login is an operator-action surface just like a CAPTCHA. The resident
// workers normally stay in the background, so a plain maybeBringToFront call
// can leave the actual login tab hidden behind another shop. Use this helper
// only once manual login is required; automatic credential-based recovery
// keeps running in the background and does not steal the foreground.
const focusManualLoginPage = async (targetPage) => {
  if (!targetPage || targetPage.isClosed()) return false;
  const activation = await activateVerificationPage(targetPage, { force: true }).catch(() => null);
  return Boolean(activation?.activated);
};

// Select through the installed extension's tab API. Do not fall back to CDP
// window activation, including when the extension is temporarily unavailable.
const recentVerificationActivations = new WeakMap();

const activateVerificationPage = async (
  targetPage,
  { force = false, backgroundOnly = false, purpose = 'verification' } = {},
) => {
  await waitForPddPostLoginBarrier(targetPage, 'verification-tab-selection');
  if (!targetPage || targetPage.isClosed()) return {
    activated: false,
    visibilityState: null,
    windowState: null,
  };
  if (!backgroundOnly && !force && !workflowAutoFocusVerification) {
    return { selected: false, activated: false, reason: 'automatic-tab-selection-disabled' };
  }
  const result = await selectVerificationTab({
    page: targetPage,
    extensionIds: requiredBrowserExtensionIds,
    canSelect: async () => {
      if (targetPage.isClosed()) return false;
      if (purpose === 'business-restore') {
        return !verificationFocusCoordinator.ownsLock()
          && !['detected', 'waiting-human', 'verification-required']
            .includes(readProgress().verificationLocation?.status);
      }
      return force || Boolean(await detectHumanVerification(targetPage).catch(() => null));
    },
  });
  const previous = recentVerificationActivations.get(targetPage);
  if (result.activated || (!result.selected && (!previous || Date.now() - previous.at >= 30_000))) {
    console.log(`[验证码标签驻留] ${shopId} ${JSON.stringify(result)}`);
    recentVerificationActivations.set(targetPage, { at: Date.now(), ...result });
  }
  const visibilityState = await targetPage.evaluate(() => document.visibilityState).catch(() => null);
  return { ...result, visibilityState, windowState: null };
};

// Chromium selects a newly opened popup by default, even when the popup is a
// normal business-detail page and no operator action is required. Restore the
// opener's tab after the popup settles, but only when the new page is clearly
// not a login or verification surface. CAPTCHA/login pages remain selected by
// the existing cross-tab detector and focus lease.
async function restoreNonVerificationPopupTab(popupPage, openerPage) {
  if (workflowForegroundMode !== 'never'
    || !popupPage
    || popupPage.isClosed()
    || !openerPage
    || openerPage.isClosed()
    || backgroundPopupRestorePending.has(popupPage)) return false;
  backgroundPopupRestorePending.add(popupPage);
  try {
    const pddPopup = String(openerPage.url()).startsWith('https://mms.pinduoduo.com/');
    await popupPage.waitForTimeout(pddPopup
      ? Math.max(backgroundPopupRestoreDelayMs, pddTabSettleMs)
      : backgroundPopupRestoreDelayMs).catch(() => {});
    if (popupPage.isClosed() || openerPage.isClosed()) return false;
    const popupUrl = String(popupPage.url() || '');
    const loginSurface = ['pdd', 'oms', 'tms'].some((system) => (
      isSystemLoginUrl(system, popupUrl)
    ));
    if (loginSurface) return false;
    const challenge = await detectHumanVerification(popupPage).catch(() => null);
    if (challenge) return false;
    const activation = await activateVerificationPage(openerPage, {
      backgroundOnly: true,
      purpose: 'business-restore',
    });
    if (activation?.activated) {
      console.log(`[后台标签保护] ${shopId} 新标签不是登录或验证码，已保持原业务标签。`);
    }
    return Boolean(activation?.activated);
  } finally {
    backgroundPopupRestorePending.delete(popupPage);
  }
}

const focusSystemPage = async (system, targetPage) => {
  await waitForPddPostLoginBarrier(targetPage, 'browser-window-operation');
  if (!targetPage || targetPage.isClosed()) throw new Error(`${system} 标签页不可用`);
  await maybeBringToFront(targetPage);
  persistSystemTabs(system);
  if (system === 'pdd') await settlePddBusinessTab(targetPage);
  return targetPage;
};

const activePageForOperatorRefresh = () => {
  const progress = readProgress();
  const sharedOmsPage = activeSharedOmsPage && !activeSharedOmsPage.isClosed()
    ? activeSharedOmsPage
    : null;
  const expectedUrl = progress.verificationLocation?.url || progress.currentUrl || null;
  const candidatePages = [
    ...context.pages(),
    ...(sharedOmsPage ? activeSharedOmsContext?.pages() || [sharedOmsPage] : []),
  ];
  const matchingPage = expectedUrl
    ? candidatePages.find((page) => !page.isClosed() && page.url() === expectedUrl)
    : null;
  if (matchingPage) return { page: matchingPage, system: progress.verificationLocation?.system || null };
  const activeSystem = progress.verificationLocation?.system
    || progress.systemTabs?.activeSystem
    || resumeActiveSystem(progress);
  const page = activeSystem === 'oms'
    ? sharedOmsPage || omsPage
    : activeSystem === 'tms' ? tmsPage : pddPage;
  return { page, system: activeSystem };
};

process.on('message', (message) => {
  if (message?.type !== 'runtime-control'
    || !['refresh-active-page', 'refresh-pdd-identity', 'focus-system-login', 'reset-pdd-login'].includes(message.action)
    || !message.requestId) return;
  const respond = (payload) => {
    if (typeof process.send === 'function') {
      process.send({ type: 'runtime-control-result', requestId: message.requestId, ...payload });
    }
  };
  void (async () => {
    if (message.action === 'reset-pdd-login') {
      while (workflowBusy || maintenanceBusy) await pddPage.waitForTimeout(250);
      const targetPage = await adoptLivePddAnchor();
      const pddPages = context.pages().filter((page) => (
        !page.isClosed() && page.url().includes('mms.pinduoduo.com')
      ));
      // Remove only PDD session data. OMS/TMS storage and their anchor tabs
      // remain untouched, so correcting one shop cannot affect other systems.
      await context.clearCookies({ domain: 'mms.pinduoduo.com' }).catch(() => {});
      for (const page of pddPages) {
        await page.evaluate(async () => {
          try { localStorage.clear(); } catch {}
          try { sessionStorage.clear(); } catch {}
          try {
            const databases = typeof indexedDB === 'object'
              && typeof indexedDB.databases === 'function'
              ? await indexedDB.databases() : [];
            for (const database of databases) {
              if (database?.name) indexedDB.deleteDatabase(database.name);
            }
          } catch {}
        }).catch(() => {});
      }
      for (const page of [...derivedPages]) {
        if (!page.isClosed() && page.url().includes('mms.pinduoduo.com')) {
          // An explicit owner reset intentionally invalidates the PDD session,
          // including a verification recovery that was still waiting.
          await closeDerivedPage(page, { allowVerificationRecoveryClose: true });
        }
      }
      verificationRecoveryProtectedPages.clear();
      await navigateSystemPage(targetPage, loginUrl, 'operator-reset-pdd-login');
      writeProgress({
        pddShopIdentity: null,
        systemLogin: {
          system: 'pdd',
          status: 'required',
          stage: 'operator-reset-pdd-login',
          requestedAt: new Date().toISOString(),
        },
        operatorPddLoginReset: {
          status: 'completed',
          resetAt: new Date().toISOString(),
          clearedPages: pddPages.length,
        },
        error: null,
      });
      updateAuthHealth('pdd', 'expired', targetPage, {
        stage: 'operator-reset-pdd-login',
        confidence: 'confirmed',
        source: 'owner-pdd-login-reset',
        evidence: 'pdd-session-cleared-and-login-page-opened',
      });
      await maybeBringToFront(targetPage, { manual: true, force: true });
      respond({
        ok: true,
        system: 'pdd',
        authenticationStatus: 'expired',
        url: targetPage.url(),
        resetAt: new Date().toISOString(),
      });
      return;
    }
    if (message.action === 'focus-system-login') {
      const system = String(message.system || '').trim().toLowerCase();
      if (!['oms', 'tms'].includes(system)) throw new Error(`不支持的系统登录入口: ${system || 'unknown'}`);
      const sharedOmsPage = activeSharedOmsPage && !activeSharedOmsPage.isClosed()
        ? activeSharedOmsPage
        : null;
      const targetPage = system === 'oms' ? sharedOmsPage || omsPage : tmsPage;
      if (!targetPage || targetPage.isClosed()) throw new Error(`${system.toUpperCase()} 登录页不可用`);
      const progress = readProgress();
      const authenticationStatus = progress.authHealth?.[system]?.status || 'unknown';
      const loginUrl = system === 'oms' ? omsLoginUrl : tmsLoginUrl;
      const currentUrl = targetPage.url();
      if (['about:blank', 'chrome://newtab/'].includes(currentUrl)
        && loginUrl) {
        await navigateSystemPage(targetPage, loginUrl, `operator-open-${system}-login`);
      }
      if (system === 'oms'
        && process.env.JEOMS_ACCOUNT
        && process.env.JEOMS_PASSWORD) {
        await ensureOmsLogin(
          targetPage,
          sharedOmsPage ? activeSharedOmsContext : context,
        );
      }
      if (system === 'tms') {
        await ensureTmsLoginOnce(targetPage, context);
      }
      await maybeBringToFront(targetPage, { manual: true, force: true });
      let observedAuthenticationStatus = readProgress().authHealth?.[system]?.status
        || authenticationStatus;
      if (isSystemLoginUrl(system, targetPage.url())) {
        updateAuthHealth(system, 'expired', targetPage, {
          stage: `${system}-operator-login`,
          confidence: 'confirmed',
          source: 'owner-login-request',
          evidence: 'rendered-login-page',
        });
        observedAuthenticationStatus = 'expired';
      } else if (isAuthenticatedSystemUrl(system, targetPage.url())) {
        if (system === 'oms') await confirmOmsBusinessPage(targetPage, 'oms-operator-login-confirm');
        updateAuthHealth(system, 'authenticated', targetPage, {
          stage: `${system}-operator-login`,
          confidence: 'confirmed',
          source: 'owner-login-request',
          evidence: 'rendered-business-session',
        });
        observedAuthenticationStatus = 'authenticated';
        await persistBrowserAuth(sharedOmsPage ? activeSharedOmsContext : context).catch(() => {});
      }
      updateManagedBrowserTitle(system, observedAuthenticationStatus, targetPage);
      persistSystemTabs(system);
      const focusedAt = new Date().toISOString();
      writeProgress({
        operatorSystemLogin: {
          requestId: message.requestId,
          system,
          status: 'focused',
          url: targetPage.url(),
          focusedAt,
        },
        error: null,
      });
      respond({
        ok: true,
        system,
        authenticationStatus: observedAuthenticationStatus,
        url: targetPage.url(),
        focusedAt,
      });
      return;
    }
    if (message.action === 'refresh-pdd-identity') {
      while (workflowBusy || maintenanceBusy) await pddPage.waitForTimeout(250);
      await focusSystemPage('pdd', pddPage);
      const targetUrl = pddPage.url().includes('mms.pinduoduo.com') ? pddPage.url() : listUrl;
      await ensurePddLogin(pddPage, context, targetUrl);
      const identity = readProgress().pddShopIdentity || null;
      respond({
        ok: Boolean(identity?.actualShopName),
        identity,
        url: pddPage.url(),
        refreshedAt: new Date().toISOString(),
      });
      return;
    }
    const target = activePageForOperatorRefresh();
    if (!target.page || target.page.isClosed()) throw new Error('当前业务页面不可用');
    const previousUrl = target.page.url();
    await maybeBringToFront(target.page, { manual: true }).catch(() => {});
    await target.page.reload({ waitUntil: 'domcontentloaded', timeout: 45_000 });
    const refreshedAt = new Date().toISOString();
    writeProgress({
      step: 'operator-page-refreshed',
      currentUrl: target.page.url(),
      operatorRefresh: {
        requestId: message.requestId,
        system: target.system,
        previousUrl,
        url: target.page.url(),
        refreshedAt,
      },
      error: null,
    });
    respond({ ok: true, system: target.system, previousUrl, url: target.page.url(), refreshedAt });
  })().catch((error) => respond({ ok: false, error: error.message }));
});

const clearTmsDynamicTransportSecurityPolicy = async () => {
  let maintenancePage = null;
  const host = new URL(tmsBaseUrl).hostname;
  try {
    maintenancePage = registerDerivedPage(
      await createBackgroundPage(),
      'tms-transport-security-recovery',
    );
    await maintenancePage.goto('chrome://net-internals/#hsts', {
      waitUntil: 'domcontentloaded',
      timeout: 10_000,
    });
    const domainInput = maintenancePage.locator('#domain-security-policy-view-delete-input');
    const deleteButton = maintenancePage.locator('#domain-security-policy-view-delete-submit');
    await domainInput.waitFor({ state: 'visible', timeout: 5_000 });
    await domainInput.fill(host);
    await deleteButton.click({ timeout: 5_000 });
    await maintenancePage.waitForTimeout(250);
    writeProgress({
      tmsTransportSecurityRecovery: {
        host,
        status: 'dynamic-policy-cleared',
        recoveredAt: new Date().toISOString(),
      },
    });
    console.warn(`[tms-navigation] cleared stale dynamic HSTS policy for ${host}; retrying HTTP navigation once`);
    return true;
  } catch (error) {
    writeProgress({
      tmsTransportSecurityRecovery: {
        host,
        status: 'failed',
        error: error.message,
        failedAt: new Date().toISOString(),
      },
    });
    console.warn(`[tms-navigation] failed to clear dynamic HSTS policy for ${host}: ${error.message}`);
    return false;
  } finally {
    if (maintenancePage && !maintenancePage.isClosed()) {
      await closeDerivedPage(maintenancePage).catch(() => {});
    }
  }
};

// Persistent contexts start with an about:blank page. Commit navigation first
// so a slow service cannot leave the business tab blank after a DOM timeout.
const navigateSystemPage = async (
  targetPage,
  url,
  stage,
  {
    commitTimeoutMs = Math.max(5_000, Math.min(30_000, pddRenderWaitMs)),
    domContentTimeoutMs = Math.max(5_000, Math.min(30_000, pddRenderWaitMs)),
  } = {},
) => {
  if (workflowSystemForAction(targetPage, stage) === 'pdd'
    || String(url || '').includes('mms.pinduoduo.com')) {
    await waitForPddPostLoginBarrier(targetPage, stage, {
      source: 'system-navigation',
    });
  }
  let lastError = null;
  for (let attempt = 1; attempt <= 2; attempt++) {
    try {
      await targetPage.goto(url, { waitUntil: 'commit', timeout: commitTimeoutMs });
      await targetPage.waitForLoadState('domcontentloaded', { timeout: domContentTimeoutMs }).catch(() => {});
      if (isBrowserNetworkErrorUrl(targetPage.url())) {
        throw new Error(`browser network error page: ${targetPage.url()}`);
      }
      await settlePddBusinessTab(targetPage);
      return targetPage;
    } catch (error) {
      lastError = error;
      const observedUrl = targetPage.url();
      const navigationNetworkFailure = isBrowserNetworkErrorUrl(observedUrl)
        || /(?:net::)?ERR_[A-Z0-9_]+/iu.test(String(error?.message || ''));
      if (navigationNetworkFailure) {
        const targetIsTms = (() => {
          try {
            return new URL(url).hostname === new URL(tmsBaseUrl).hostname;
          } catch {
            return false;
          }
        })();
        if (targetIsTms && attempt === 1) {
          await clearTmsDynamicTransportSecurityPolicy();
          await targetPage.goto('about:blank', { waitUntil: 'commit', timeout: 5_000 }).catch(() => {});
          await targetPage.waitForTimeout(250).catch(() => {});
          continue;
        }
        if (attempt === 1) {
          await targetPage.waitForTimeout(1_000).catch(() => {});
          continue;
        }
        const unavailable = new Error(
          `${targetIsTms ? 'TMS_NAVIGATION_TEMPORARILY_UNAVAILABLE' : 'BROWSER_NAVIGATION_TEMPORARILY_UNAVAILABLE'}: ${stage} 打开网络错误页 ${observedUrl}`,
        );
        unavailable.cause = error;
        throw unavailable;
      }
      if (observedUrl && observedUrl !== 'about:blank') {
        console.warn(`[${stage}] 页面已提交但加载较慢，继续使用 ${observedUrl}`);
        return targetPage;
      }
      if (attempt === 1) await targetPage.waitForTimeout(1000).catch(() => {});
    }
  }
  throw lastError || new Error(`${stage} 导航失败: ${url}`);
};

const openPddDetailWithoutForegroundPopup = async (
  anchorPage,
  action,
  stage,
  actionOptions = {},
) => {
  const previousUrl = anchorPage.url();
  const popupPromise = context.waitForEvent('page', {
    predicate: (candidate) => candidate !== anchorPage,
    timeout: 15_000,
  }).catch(() => null);
  const sameTabNavigationPromise = anchorPage.waitForURL(
    (url) => url.href !== previousUrl,
    { timeout: 15_000 },
  ).then(() => null).catch(() => null);

  await pacedAction(
    anchorPage,
    stage,
    () => clickPddActionWithoutForegroundPopup(anchorPage, action),
    actionOptions,
  );
  return Promise.race([popupPromise, sameTabNavigationPromise]);
};

const adoptPddDetailPage = async (candidate) => {
  if (candidate && candidate !== pddPage) {
    registerDerivedPage(candidate, 'pdd-work-order-detail');
    await maybeBringToFront(candidate);
    await settlePddBusinessTab(candidate);
    persistSystemTabs('pdd');
    return candidate;
  }

  // Some PDD deployments reuse the current tab instead of opening a popup.
  // Clone the committed detail URL into a derived tab, then return the anchor
  // tab to the work-order list so it remains available for the next order.
  if (pddPage.url().includes('/aftersales/work_order/tododetail')) {
    const detailUrl = pddPage.url();
    const detailPage = registerDerivedPage(
      await createBackgroundPage(),
      'pdd-work-order-detail',
    );
    await navigateSystemPage(detailPage, detailUrl, 'open-derived-pdd-detail');
    await navigateSystemPage(pddPage, listUrl, 'restore-pdd-anchor-list');
    await maybeBringToFront(detailPage);
    persistSystemTabs('pdd');
    return detailPage;
  }
  return pddPage;
};

const openSavedPddDetailPage = async (detailUrl) => {
  if (!detailUrl) throw new Error('缺少可恢复的拼多多工单详情地址');
  if (!isPddDetailUrl(detailUrl)) {
    throw new Error(`已保存的拼多多地址不是工单详情页: ${detailUrl}`);
  }
  const existing = [...derivedPages].find((page) => !page.isClosed() && page.url() === detailUrl);
  if (existing) return existing;
  // Never turn the permanent PDD anchor into a detail tab. If an older
  // progress file left the anchor on the detail URL, first restore the anchor
  // to the list and then open a separate derived detail page.
  if (!pddPage.isClosed() && pddPage.url() === detailUrl) {
    await navigateSystemPage(pddPage, listUrl, 'restore-pdd-anchor-before-detail');
  }
  const detailPage = registerDerivedPage(
    await createBackgroundPage(),
    'pdd-work-order-detail-resume',
  );
  await navigateSystemPage(detailPage, detailUrl, 'open-derived-pdd-detail-resume');
  return detailPage;
};

const pddSavedDetailNeedsFreshLookup = (progress = {}) => {
  const error = typeof progress.error === 'string'
    ? progress.error
    : progress.error?.message || '';
  return (progress.detailUrl && !isPddDetailUrl(progress.detailUrl))
    || progress.pddStaleDetailRecovery?.strategy === 'fresh-exact-order-query'
    || needsFreshPddDetailLookup(progress)
    || (progress.step === 'flow-paused'
      && (/进入了错误工单/u.test(error)
        || (/locator\.waitFor/.test(error) && /订单编号|订单号/u.test(error))));
};

const verifiedPddDetailRecoveryUrl = (progress = {}, expectedOrderNumber = null) => {
  const orderNumber = String(progress.orderNumber || '').trim();
  if (!orderNumber || (expectedOrderNumber && orderNumber !== String(expectedOrderNumber).trim())) return null;
  const platformWorkOrderId = String(progress.platformWorkOrderId || '').trim();
  const platformCaseId = String(progress.platformCaseKey || '')
    .match(/^pdd-work-order:(\d{6,30})$/)?.[1] || null;
  if (!progress.ordinaryInstanceId
    || !/^\d{6,30}$/.test(platformWorkOrderId)
    || platformCaseId !== platformWorkOrderId) return null;
  const candidates = [
    progress.detailUrl,
    progress.latestDiscovery?.detailUrl,
  ].map((value) => String(value || '').trim()).filter(Boolean);
  const matching = candidates.find((candidate) => parsePlatformWorkOrderId(candidate) === platformWorkOrderId);
  return matching
    || `https://mms.pinduoduo.com/aftersales/work_order/tododetail?id=${platformWorkOrderId}`;
};

const closeCompletedPddDetailTabs = async () => {
  const completedDetailPages = [...derivedPages].filter((page) => {
    if (page.isClosed()) return false;
    const purpose = derivedPageMeta.get(page)?.purpose || '';
    return purpose.startsWith('pdd-work-order-detail') || isPddDetailUrl(page.url());
  });
  for (const page of completedDetailPages) await closeDerivedPage(page);
  if (!pddPage.isClosed() && isPddDetailUrl(pddPage.url())) {
    await navigateSystemPage(pddPage, listUrl, 'restore-pdd-anchor-after-completion');
  }
  if (!pddPage.isClosed()) await maybeBringToFront(pddPage);
  persistSystemTabs('pdd');
};

const currentSystemPage = () => {
  const activeSystem = readProgress().systemTabs?.activeSystem;
  if (activeSystem === 'oms') {
    return activeSharedOmsPage && !activeSharedOmsPage.isClosed()
      ? activeSharedOmsPage
      : omsPage;
  }
  if (activeSystem === 'tms') return tmsPage;
  return pddPage;
};

persistSystemTabs('pdd');

// The screenshot's X is a Chromium-native permission bubble, so it is not a DOM
// element. Set the origin permission to denied through the Browser CDP domain.
try {
  const browserCdp = await browser.newBrowserCDPSession();
  await browserCdp.send('Browser.setPermission', {
    origin: 'https://mms.pinduoduo.com',
    permission: { name: 'local-network-access' },
    setting: 'denied',
  });
} catch (error) {
  console.warn(`设备访问权限拒绝设置不可用，将检查网页内关闭提示: ${error.message}`);
}

// Login verification belongs to the operator, including expired/error prompts.
// Keep this policy separate from business-page CAPTCHA dismissal.
console.log(`[pdd-login-policy] manual-only; same-page post-login wait ${pddPostLoginStabilityMs}ms; business policy unchanged`);
const pddLoginVerificationOrigins = new WeakMap();
const isManualPddLoginSurface = (page) => {
  if (!page || page.isClosed()) return false;
  if (isSystemLoginUrl('pdd', page.url())) return true;
  const origin = pddLoginVerificationOrigins.get(page);
  return Boolean(origin && !origin.page.isClosed()
    && isSystemLoginUrl('pdd', origin.page.url()) && origin.url === page.url());
};

const closeDeviceAccessIfPrompted = async (targetPage) => {
  if (isManualPddLoginSurface(targetPage)) return false;
  const candidates = [
    targetPage.getByRole('button', { name: '关闭', exact: true }),
    targetPage.getByRole('button', { name: '取消', exact: true }),
    targetPage.getByRole('button', { name: '拒绝', exact: true }),
    targetPage.getByText('关闭', { exact: true }),
    targetPage.getByText('取消', { exact: true }),
    targetPage.getByText('拒绝', { exact: true }),
  ];
  for (const candidate of candidates) {
    const count = await candidate.count().catch(() => 0);
    for (let i = 0; i < count; i++) {
      const button = candidate.nth(i);
      if (await button.isVisible().catch(() => false)) {
        await pacedAction(targetPage, 'close-device-access-prompt', () => button.click({ force: true }));
        console.log('已关闭网页内设备访问权限提示。');
        return true;
      }
    }
  }
  return false;
};

// Close only a verified CAPTCHA/security modal after its business wait budget
// expires. This never closes a browser window or changes Windows foreground.
const verificationExpiredSurfacePattern = /(?:验证时间过长|验证(?:已)?(?:超时|过期|失效)|验证码(?:已)?(?:过期|失效)|安全验证(?:已)?(?:过期|失效)|请重新验证)/iu;
// Image-selection challenges use several short target descriptions. Keep the
// same strict vocabulary as the detector so an image challenge can be closed
// immediately only when its own X is present; sliders and login pages remain
// human-handled until their normal timeout/recovery path.
const imageClickVerificationTextPattern = /请点击[^。！？\n]{1,160}/u;

const readVerificationSurfaceText = async (targetPage) => {
  if (!targetPage || targetPage.isClosed()) return '';
  const texts = [];
  for (const frame of targetPage.frames()) {
    const text = await frame.locator('body').innerText({ timeout: 1_500 }).catch(() => '');
    if (text) texts.push(text);
  }
  return texts.join('\n').replace(/\s+/gu, ' ').slice(0, 12_000);
};

const verificationSurfaceHasExpired = async (targetPage) => {
  const text = await readVerificationSurfaceText(targetPage);
  return {
    expired: verificationExpiredSurfacePattern.test(text),
    text,
  };
};

const closeHumanVerificationPrompt = async (targetPage, detection = null) => {
  if (isManualPddLoginSurface(targetPage)) {
    return { closed: false, expired: false, reason: 'pdd-login-manual-only' };
  }
  if (!targetPage || targetPage.isClosed()) return { closed: false, reason: 'page-closed' };
  const expiration = await verificationSurfaceHasExpired(targetPage);
  // This function is reached only at the hard verification deadline. The
  // worker must release the shop at that boundary even when PDD does not
  // render an explicit "expired" message; otherwise a live challenge can
  // leave the shop permanently stuck in human-verification-required.
  const modalSelector = [
    '[data-testid="beast-core-modal-container"]',
    '[data-testid="beast-core-modal"]',
    '.beast-core-modal',
    '.ant-modal',
    '[role="dialog"]',
    '[class*="modal" i]',
  ].join(', ');
  const closeSelector = [
    '[data-testid="beast-core-modal-close-button"]',
    '[data-testid*="close" i]',
    '[aria-label="关闭"]',
    '[title="关闭"]',
    '[aria-label="Close"]',
    '[title="Close"]',
    '[id*="close" i]',
    '[class*="close" i]',
    'button:has-text("关闭")',
    'button:has-text("×")',
  ].join(', ');
  const challengeSelector = [
    '[data-testid*="captcha" i]',
    '[data-testid*="verify" i]',
    '[data-testid*="slider" i]',
    '[data-testid*="puzzle" i]',
    '[class*="captcha" i]',
    '[class*="slider" i]',
    '[class*="puzzle" i]',
    '[id*="captcha" i]',
    '[id*="slider" i]',
    '[id*="puzzle" i]',
    'iframe[src*="captcha" i]',
    'iframe[src*="verify" i]',
    '[role="slider"]',
    '[draggable="true"]',
  ].join(', ');
  const verificationText = new RegExp(
    `(?:安全验证|人机验证|风险验证|滑块验证|滑动验证|拖动.*滑块|完成拼图|验证码|${imageClickVerificationTextPattern.source}|验证时间过长|验证超时)`,
    'u',
  );
  const frames = [...targetPage.frames()].sort((left, right) => {
    const expected = String(detection?.frameUrl || '');
    return Number(right.url() === expected) - Number(left.url() === expected);
  });
  for (const frame of frames) {
    const visibleModalSelector = modalSelector.split(', ').map((selector) => `${selector}:visible`).join(', ');
    const modals = frame.locator(visibleModalSelector);
    for (let index = 0; index < await modals.count().catch(() => 0); index += 1) {
      const modal = modals.nth(index);
      const challengeModal = await modal.evaluate((element, args) => {
        const text = String(element.innerText || '');
        return new RegExp(args.verificationText, 'u').test(text)
          || args.imageClickDetection === true
          || Boolean(element.querySelector(args.challengeSelector));
      }, {
        verificationText: verificationText.source,
        challengeSelector,
        imageClickDetection: isImageClickVerificationDetection(detection),
      })
        .catch(() => false);
      if (!challengeModal) continue;
      const closeButtons = modal.locator(closeSelector);
      for (let closeIndex = 0; closeIndex < await closeButtons.count().catch(() => 0); closeIndex += 1) {
        const button = closeButtons.nth(closeIndex);
        if (!await button.isVisible().catch(() => false)) continue;
        const clicked = await button.click({ force: true, timeout: 5_000 })
          .then(() => true).catch(() => false);
        if (clicked) {
          return {
            closed: true,
            expired: true,
            selector: closeSelector,
            frameUrl: frame.url(),
            closedAt: new Date().toISOString(),
          };
        }
      }
    }

    // Some PDD image-selection challenges mount the captcha layer and its X
    // as sibling nodes, so neither is below a standard dialog container. Use
    // the detector's exact close bounding box as a second, still strict,
    // lookup. The coordinate match prevents an unrelated page close button
    // from being clicked.
    if (isImageClickVerificationDetection(detection) && detection?.closeBoundingBox) {
      const expected = detection.closeBoundingBox;
      const expectedCenter = {
        x: Number(expected.x) + Number(expected.width) / 2,
        y: Number(expected.y) + Number(expected.height) / 2,
      };
      const fallbackCandidates = frame.locator([
        closeSelector,
        'button',
        '[role="button"]',
      ].join(', '));
      let best = null;
      for (let index = 0; index < await fallbackCandidates.count().catch(() => 0); index += 1) {
        const candidate = fallbackCandidates.nth(index);
        if (!await candidate.isVisible().catch(() => false)) continue;
        const box = await candidate.boundingBox().catch(() => null);
        if (!box) continue;
        const identity = await candidate.evaluate((element) => ({
          metadata: [
            element.innerText,
            element.getAttribute('aria-label'),
            element.getAttribute('title'),
            element.id,
            element.className,
          ].filter(Boolean).join(' '),
          tagName: String(element.tagName || '').toLowerCase(),
          role: String(element.getAttribute('role') || '').toLowerCase(),
        })).catch(() => ({ metadata: '', tagName: '', role: '' }));
        const center = { x: box.x + box.width / 2, y: box.y + box.height / 2 };
        const distance = Math.abs(center.x - expectedCenter.x) + Math.abs(center.y - expectedCenter.y);
        if (distance > 80) continue;
        const compactButton = box.width >= 12 && box.width <= 72 && box.height >= 12 && box.height <= 72
          && (identity.tagName === 'button' || identity.role === 'button');
        if (!/(?:关闭|close|×)/iu.test(identity.metadata) && !(compactButton && distance <= 48)) continue;
        if (!best || distance < best.distance) best = { candidate, distance };
      }
      if (best) {
        const clicked = await best.candidate.click({ force: true, timeout: 5_000 })
          .then(() => true).catch(() => false);
        if (clicked) {
          return {
            closed: true,
            expired: true,
            selector: closeSelector,
            frameUrl: frame.url(),
            closedAt: new Date().toISOString(),
          };
        }
      }
      if (!best) {
        // The grey circular X used by PDD is sometimes an anonymous div/SVG.
        // A DOM-dispatched MouseEvent is untrusted and newer challenge builds
        // ignore it, so translate the frame-local detector coordinate into a
        // page coordinate and send a real Playwright mouse click instead.
        const body = frame.locator('body');
        const bodyBox = await body.boundingBox().catch(() => null);
        const bodyRect = await body.evaluate((element) => {
          const rect = element.getBoundingClientRect();
          return { x: rect.x, y: rect.y };
        }).catch(() => null);
        const clickPoint = bodyBox && bodyRect ? {
          x: bodyBox.x + expectedCenter.x - bodyRect.x,
          y: bodyBox.y + expectedCenter.y - bodyRect.y,
        } : null;
        const clicked = clickPoint
          ? await targetPage.mouse.click(clickPoint.x, clickPoint.y, { delay: 35 })
            .then(() => true).catch(() => false)
          : false;
        if (clicked) {
          return {
            closed: true,
            expired: true,
            selector: 'image-click-coordinate-close',
            frameUrl: frame.url(),
            closedAt: new Date().toISOString(),
          };
        }
      }
    }

    // Some PDD slider/puzzle dialogs render the grey circular X as an
    // anonymous SVG/div (no aria-label, title, class or role).  The detector
    // still gives us a trusted verification surface, so find only a compact
    // control at that surface's upper-right corner.  This is deliberately
    // geometry-bounded: it cannot select an unrelated page button.
    if (!isSystemLoginUrl(workflowSystemForAction(targetPage, 'verification-close'), targetPage.url())) {
      const body = frame.locator('body');
      const closePoint = await body.evaluate((element, args) => {
        const visible = (node) => {
          const rect = node.getBoundingClientRect();
          const style = getComputedStyle(node);
          const viewportWidth = document.documentElement.clientWidth || innerWidth;
          const viewportHeight = document.documentElement.clientHeight || innerHeight;
          return rect.width >= 8 && rect.height >= 8
            && rect.right > 0 && rect.bottom > 0
            && rect.left < viewportWidth && rect.top < viewportHeight
            && style.display !== 'none' && style.visibility !== 'hidden'
            && Number(style.opacity || 1) > 0;
        };
        const verificationText = /安全验证|人机验证|风险验证|滑块验证|滑动验证|拖动.*滑块|向右滑|完成拼图|验证码|请点击/u;
        const all = [...element.querySelectorAll('*')].filter(visible);
        const detectionBox = args?.boundingBox && Number.isFinite(Number(args.boundingBox.x))
          ? args.boundingBox : null;
        const roots = all.filter((node) => {
          const rect = node.getBoundingClientRect();
          const text = String(node.innerText || node.textContent || '');
          const hasDetectionPoint = detectionBox
            && detectionBox.x + detectionBox.width / 2 >= rect.left - 4
            && detectionBox.x + detectionBox.width / 2 <= rect.right + 4
            && detectionBox.y + detectionBox.height / 2 >= rect.top - 4
            && detectionBox.y + detectionBox.height / 2 <= rect.bottom + 4;
          return rect.width >= 200 && rect.width <= 1_200
            && rect.height >= 100 && rect.height <= 900
            && (verificationText.test(text) || hasDetectionPoint)
            && (node.getAttribute('role') === 'dialog'
              || /modal|captcha|verify|slider|puzzle|challenge/iu.test(
                `${node.id || ''} ${node.className || ''} ${node.getAttribute('data-testid') || ''}`,
              )
              || ['fixed', 'absolute'].includes(getComputedStyle(node).position));
        }).sort((left, right) => {
          const a = left.getBoundingClientRect();
          const b = right.getBoundingClientRect();
          return a.width * a.height - b.width * b.height;
        });
        const surface = roots[0];
        if (!surface) return null;
        const surfaceRect = surface.getBoundingClientRect();
        const hint = /关闭|close|×/iu;
        const candidates = all.map((node) => ({ node, rect: node.getBoundingClientRect(), style: getComputedStyle(node) }))
          .filter(({ rect }) => rect.width >= 12 && rect.width <= 72
            && rect.height >= 12 && rect.height <= 72
            && rect.right >= surfaceRect.right - 56
            && rect.left <= surfaceRect.right + 64
            && rect.bottom >= surfaceRect.top - 64
            && rect.top <= surfaceRect.top + 96)
          .map((candidate) => {
            const { node, rect, style } = candidate;
            const metadata = [
              node.innerText, node.getAttribute('aria-label'), node.getAttribute('title'),
              node.id, node.className,
            ].filter(Boolean).join(' ');
            const tag = String(node.tagName || '').toLowerCase();
            const explicit = hint.test(metadata);
            const icon = ['svg', 'path', 'button'].includes(tag)
              || node.getAttribute('role') === 'button'
              || style.cursor === 'pointer'
              || style.borderRadius === '50%';
            if (!explicit && !icon) return null;
            const centerX = rect.x + rect.width / 2;
            const centerY = rect.y + rect.height / 2;
            const distance = Math.abs(centerX - surfaceRect.right)
              + Math.abs(centerY - surfaceRect.top);
            return { centerX, centerY, distance, explicit, area: rect.width * rect.height };
          })
          .filter(Boolean)
          .sort((left, right) => Number(right.explicit) - Number(left.explicit)
            || left.distance - right.distance || left.area - right.area);
        const best = candidates[0];
        if (!best) return null;
        const bodyRect = element.getBoundingClientRect();
        return { x: best.centerX - bodyRect.left, y: best.centerY - bodyRect.top };
      }, { boundingBox: detection?.boundingBox || null }).catch(() => null);
      if (closePoint) {
        const clicked = await body.click({
          position: closePoint,
          force: true,
          timeout: 5_000,
        }).then(() => true).catch(() => false);
        if (clicked) {
          return {
            closed: true,
            expired: true,
            selector: 'verification-surface-upper-right-close',
            frameUrl: frame.url(),
            closedAt: new Date().toISOString(),
          };
        }
      }
    }
  }
  return {
    closed: false,
    expired: true,
    reason: expiration.expired
      ? 'verification-expired-close-button-not-found'
      : 'verification-time-budget-expired-close-button-not-found',
  };
};

// Some PDD challenges are full-page or hosted in an iframe without a usable
// close control. The close helper remains available for a future, explicitly
// approved opt-in, but production keeps it disabled. The resident observer
// and business waiter can notice the same modal at nearly the same time, so
// close attempts are still serialized per page.
const verificationCloseInFlight = new WeakSet();

const closeHumanVerificationSurface = async (targetPage, detection = null) => {
  if (isManualPddLoginSurface(targetPage)) {
    return { closed: false, expired: false, reason: 'pdd-login-manual-only' };
  }
  if (!targetPage || targetPage.isClosed()) return { closed: false, reason: 'page-closed' };
  // A timed-out modal is still an unsolved challenge. Leave its tab and modal
  // with the operator instead of treating an automatic X as a cleared gate.
  if (!imageClickVerificationAutoCloseEnabled && !businessVerificationAutoCloseEnabled) {
    return { closed: false, expired: false, reason: 'verification-auto-close-disabled' };
  }
  const verificationUrl = targetPage.url();
  const loginSurface = /(?:mms\.pinduoduo\.com\/login|www\.jeoms\.com\/xianma\/login|tms\.aipro123\.top\/login)/iu
    .test(verificationUrl);
  if (!loginSurface) {
    const timedOutModal = await closeTimedOutVerificationModal(targetPage, detection)
      .catch((error) => ({ closed: false, reason: `timed-out-modal-close-failed:${error.message}` }));
    if (timedOutModal.closed) return timedOutModal;
  }
  // Do not dismiss any CAPTCHA or verification surface unless this feature is
  // explicitly re-enabled in code after an operator decision.
  if (verificationCloseInFlight.has(targetPage)) {
    return { closed: false, expired: false, reason: 'verification-close-in-flight' };
  }
  if (isImageClickVerificationDetection(detection) && !imageClickVerificationAutoCloseEnabled) {
    return { closed: false, expired: false, reason: 'image-click-auto-close-disabled' };
  }
  verificationCloseInFlight.add(targetPage);
  try {
  // Business-page challenges may be dismissed immediately. A PDD challenge
  // can redraw between detection and the close attempt, so re-read the exact
  // live surface before allowing the X branch to proceed.
  const immediateClose = !loginSurface && (
    (imageClickVerificationAutoCloseEnabled && isImageClickVerificationDetection(detection))
    || (businessVerificationAutoCloseEnabled && Boolean(detection))
  );
  if (immediateClose) {
    const liveDetection = await detectHumanVerification(targetPage).catch(() => null);
    if (!liveDetection) {
      return {
        closed: false,
        expired: false,
        reason: liveDetection ? 'verification-surface-changed' : 'verification-surface-gone',
        detection: liveDetection,
      };
    }
    // The challenge can redraw between the observer and the close attempt.
    // Never apply an old image-modal detection to a replacement slider (or
    // any other verification surface): doing so clicks the wrong X and can
    // invalidate a challenge before the operator has touched it. The live
    // surface must remain in the same dismissibility class as the original
    // detection before the close action is allowed.
    if (isImageClickVerificationDetection(liveDetection)
      !== isImageClickVerificationDetection(detection)) {
      return {
        closed: false,
        expired: false,
        reason: 'verification-surface-changed',
        detection: liveDetection,
      };
    }
    detection = liveDetection;
  }
  const persistedDetectedAt = Date.parse(String(readProgress().verificationLocation?.detectedAt || ''));
  if (!immediateClose
    && Number.isFinite(persistedDetectedAt)
    && Date.now() - persistedDetectedAt < humanVerificationMaxTimeoutMs) {
    return {
      closed: false,
      expired: false,
      reason: 'verification-timeout-not-reached',
    };
  }
  const promptResult = await closeHumanVerificationPrompt(targetPage, detection);
  if (promptResult.closed || !targetPage || targetPage.isClosed()) return promptResult;
  if (promptResult.expired !== true) return promptResult;
  if (!derivedPages.has(targetPage)) {
    // A full-page PDD login challenge has no modal X. Reset only the
    // permanent PDD anchor tab at the hard deadline; the browser window and
    // all other system tabs remain untouched.
    const isPddLoginAnchor = targetPage === pddPage
      && /mms\.pinduoduo\.com\/login/iu.test(targetPage.url());
    if (!isPddLoginAnchor && /mms\.pinduoduo\.com/iu.test(targetPage.url())) {
      // A full-page/business-detail challenge may have no modal X and may be
      // hosted by the permanent PDD anchor. Navigate that exact page back to
      // the work-order list at the hard deadline so the shop is released
      // without closing its authenticated browser profile.
      try {
        await navigateSystemPage(targetPage, listUrl, 'pdd-business-verification-recovery');
        return {
          ...promptResult,
          closed: true,
          method: 'pdd-business-verification-navigated-to-list',
          closedAt: new Date().toISOString(),
        };
      } catch (error) {
        return {
          ...promptResult,
          closed: false,
          reason: `pdd-business-verification-navigation-failed:${error.message}`,
        };
      }
    }
    if (!isPddLoginAnchor) return promptResult;
    // The permanent PDD login anchor is also held by the login wait loop.
    // Closing it invalidates that loop's page reference and makes the
    // supervisor restart the whole shop after an otherwise harmless timeout.
    // Reload the same tab instead: the expired full-page challenge is removed,
    // the login surface remains available for the operator, and no other tab or
    // browser window is changed.
    try {
      await navigateSystemPage(targetPage, loginUrl, 'pdd-login-challenge-reload');
      return {
        ...promptResult,
        closed: true,
        method: 'pdd-login-challenge-reloaded',
        suppressVerification: false,
        closedAt: new Date().toISOString(),
      };
    } catch (error) {
      return {
        ...promptResult,
        closed: false,
        reason: `pdd-login-challenge-reload-failed:${error.message}`,
      };
    }
  }
  const pageRole = verificationPageRole(targetPage);
  await closeDerivedPage(targetPage).catch(() => {});
  if (!targetPage.isClosed()) return promptResult;
  return {
    ...promptResult,
    closed: true,
    method: 'derived-verification-tab-closed',
    pageRole,
    closedAt: new Date().toISOString(),
  };
  } finally {
    verificationCloseInFlight.delete(targetPage);
  }
};

// The image-selection modal is intentionally handled by this helper only when
// an operator explicitly opts in. Production does not dismiss a challenge or
// clear the shop checkpoint from this path, because an X click is not proof
// that PDD accepted the challenge.
const releaseImageClickVerificationAfterClose = async ({
  system,
  stage,
  page,
  detection,
  location = null,
  allowBusinessVerification = false,
} = {}) => {
  if (isManualPddLoginSurface(page)) {
    return { closed: false, released: false, reason: 'pdd-login-manual-only' };
  }
  const imageClickEligible = imageClickVerificationAutoCloseEnabled
    && isImageClickVerificationDetection(detection);
  const businessEligible = allowBusinessVerification
    && businessVerificationAutoCloseEnabled
    && Boolean(detection)
    && !isSystemLoginUrl(system, page?.url?.() || '');
  if (!imageClickEligible && !businessEligible) {
    return { closed: false, released: false, reason: 'verification-auto-close-not-applicable' };
  }
  const closeResult = await closeHumanVerificationSurface(page, detection);
  if (!closeResult.closed) return { ...closeResult, released: false };
  // Give the modal animation a short settle window, then verify the exact page
  // no longer exposes the image-selection detector signal.
  if (page && !page.isClosed()) {
    await page.waitForTimeout(Math.max(100, Math.min(1_000, humanVerificationClearStableMs)))
      .catch(() => {});
  }
  const remainingDetection = page && !page.isClosed()
    ? await detectHumanVerification(page).catch(() => null)
    : null;
  if (remainingDetection) {
    return {
      ...closeResult,
      closed: false,
      released: false,
      reason: 'image-click-modal-still-visible',
      detection: remainingDetection,
    };
  }
  const current = readProgress();
  const currentLocation = current.verificationLocation;
  const locationMatches = !currentLocation
    || (currentLocation.system === system
      && (!location?.id || currentLocation.id === location.id));
  if (!locationMatches) {
    return { ...closeResult, released: false, reason: 'newer-verification-location-present' };
  }
  const releasedAt = new Date().toISOString();
  const verificationId = location?.id || currentLocation?.id || null;
  const wasVerificationStep = /^(?:human-verification-required|manual-login-required)$/u
    .test(String(current.step || ''));
  writeProgress({
    step: wasVerificationStep ? 'challenge-cleared' : current.step,
    verificationStage: null,
    verificationLocation: null,
    verificationFocus: null,
    verificationRecovery: null,
    verificationTimeout: null,
    verificationRecheck: {
      ...(current.verificationRecheck || {}),
      trigger: imageClickEligible ? 'image-click-modal-close' : 'business-verification-modal-close',
      status: 'cleared',
      verificationId,
      requestedAt: releasedAt,
      completedAt: releasedAt,
      closeResult,
    },
    manualReview: null,
    currentUrl: page && !page.isClosed() ? page.url() : current.currentUrl || null,
    error: null,
  });
  updateAuthHealth(system, 'unknown', page, {
    stage: null,
    source: imageClickEligible ? 'image-click-modal-close' : 'business-verification-modal-close',
    evidence: imageClickEligible
      ? 'image-click-challenge-dismissed-not-solved'
      : 'business-verification-challenge-dismissed-not-solved',
  });
  console.warn(`[业务页验证码] ${shopId} 已点击右上角 X，确认弹窗关闭，当前工单交回队列继续尝试。`);
  return {
    ...closeResult,
    released: true,
    verificationId,
    releasedAt,
  };
};

// A manual-login loop can own the verification focus while its normal wait is
// interrupted by a navigation or a slow detector. The resident observer keeps
// the exact challenge tab selected and leaves the checkpoint in place until
// the operator clears it; it does not close or release the blocked shop.
const expireResidentVerificationIfOverdue = async ({
  system,
  stage,
  located,
  progress,
  observedAt = new Date().toISOString(),
} = {}) => {
  if (isManualPddLoginSurface(located?.page)) return false;
  const location = progress?.verificationLocation;
  if (!location || location.system !== system || !located?.page || located.page.isClosed()) return false;
  const detectedAtMs = Date.parse(String(location.detectedAt || ''));
  if (!Number.isFinite(detectedAtMs) || Date.now() - detectedAtMs < humanVerificationMaxTimeoutMs) {
    return false;
  }

  const targetPage = located.page;
  const targetUrl = targetPage.url();
  const pageRole = located.pageRole || verificationPageRole(targetPage);
  const fingerprint = verificationSurfaceFingerprint({
    system,
    page: targetPage,
    detection: located.detection,
    pageRole,
  });
  const closeResult = await closeHumanVerificationSurface(targetPage, located.detection).catch((error) => ({
    closed: false,
    reason: error.message,
  }));
  const timedOutAt = new Date().toISOString();
  const current = readProgress();
  const stillCurrent = current.verificationLocation?.system === system
    && (!location.id || current.verificationLocation?.id === location.id);
  if (!stillCurrent) return false;

  const loginRequired = system === 'pdd' && isSystemLoginUrl(system, targetUrl);
  if (!closeResult.closed) {
    if (closeResult.reason === 'verification-auto-close-disabled') {
      console.warn(`[驻留验证码] ${shopId} 验证码仍在当前标签页，自动关闭已禁用，继续保留店铺闸门等待人工完成。`);
      return false;
    }
    // The challenge can remain visible for the plugin, but the scheduler
    // gate must still be released at the hard two-minute boundary.
    writeVerificationTimeoutRelease({
      system,
      stage,
      page: targetPage,
      location,
      detection: located.detection,
      closeResult,
      login: loginRequired,
    });
    console.warn(`[驻留验证码超时] ${shopId} 已等待 ${humanVerificationMaxTimeoutMs / 1000} 秒，未找到可关闭控件，保留验证码给插件但已释放验证闸门和当前工单队列。`);
    return true;
  }

  writeProgress({
    step: loginRequired ? 'manual-login-required' : 'verification-timeout-closed',
    verificationStage: loginRequired
      ? current.verificationStage || stage
      : null,
    currentUrl: targetPage.isClosed() ? targetUrl : targetPage.url(),
    verificationLocation: null,
    verificationFocus: null,
    verificationRecovery: null,
    verificationTimeout: {
      status: 'closed',
      stage,
      system,
      timeoutMs: humanVerificationMaxTimeoutMs,
      verificationId: location.id || null,
      fingerprint,
      detectedAt: location.detectedAt || null,
      timedOutAt,
      suppressUntil: new Date(
        Date.parse(timedOutAt) + humanVerificationPostTimeoutSuppressionMs,
      ).toISOString(),
      closeResult,
      externalActionsReplayed: false,
    },
    verificationRecheck: {
      ...(current.verificationRecheck || {}),
      trigger: 'resident-verification-timeout-close',
      status: 'closed',
      requestedAt: timedOutAt,
      completedAt: timedOutAt,
    },
    manualReview: null,
    error: null,
  });
  updateAuthHealth(system, 'unknown', targetPage, {
    stage: null,
    source: 'resident-verification-timeout-close',
    evidence: closeResult.closed ? 'challenge-surface-closed' : 'challenge-close-unavailable',
  });
  console.warn(`[驻留验证码超时] ${shopId} 已等待 ${humanVerificationMaxTimeoutMs / 1000} 秒，${closeResult.closed ? '已关闭验证码页面' : '未找到可关闭控件'}，释放店铺队列。`);
  return true;
};

class HumanVerificationRequiredError extends Error {
  constructor(stage, url) {
    super(browserHeadless
      ? `检测到人工验证，请在有界面维护环境恢复登录状态后重新运行（阶段: ${stage}，URL: ${url}）`
      : `检测到人工验证，请在可视化浏览器中完成后重新运行流程（阶段: ${stage}，URL: ${url}）`);
    this.name = 'HumanVerificationRequiredError';
  }
}

class HumanVerificationTimeoutError extends HumanVerificationRequiredError {
  constructor(stage, url, closeResult = null, timeoutMs = claimedHumanVerificationTimeoutMs) {
    super(stage, url);
    this.name = 'HumanVerificationTimeoutError';
    this.code = 'HUMAN_VERIFICATION_TIMEOUT';
    this.verificationTimedOut = true;
    this.verificationCloseResult = closeResult;
    this.verificationTimeoutMs = timeoutMs;
  }
}

class PddLoginRequiredError extends Error {
  constructor(stage, url, reason = '拼多多登录状态已失效') {
    super(`${reason}（阶段: ${stage}，URL: ${url}）`);
    this.name = 'PddLoginRequiredError';
    this.code = 'PDD_LOGIN_REQUIRED';
    this.stage = stage;
    this.url = url;
  }
}

const recordPddLoginRequired = (
  targetPage,
  { stage = 'pinduoduo-login', reason = '拼多多登录状态已失效' } = {},
) => {
  const url = targetPage.url();
  const detectedAt = new Date().toISOString();
  updateAuthHealth('pdd', 'expired', targetPage, {
    stage,
    confidence: 'confirmed',
    source: 'ensure-pdd-login',
    evidence: 'rendered-login-url',
  });
  writeProgress({
    step: 'manual-login-required',
    verificationStage: stage,
    currentUrl: url,
    error: null,
    systemLogin: {
      system: 'pdd',
      status: 'required',
      stage,
      url,
      reason,
      detectedAt,
    },
  });
  return new PddLoginRequiredError(stage, url, reason);
};

class RateLimitPauseError extends Error {
  constructor(stage, url) {
    super(`平台仍提示操作太过频繁，已停止继续操作（阶段: ${stage}，URL: ${url}）`);
    this.name = 'RateLimitPauseError';
  }
}

class ManualReviewRequiredError extends Error {
  constructor(stage, reason) {
    super(`流程需要人工复核（阶段: ${stage}）：${reason}`);
    this.name = 'ManualReviewRequiredError';
    this.stage = stage;
  }
}

class LogisticsRetryRequiredError extends Error {
  constructor(stage, reason, retryAfterMs = emptyQueuePollMs, details = {}) {
    super(reason);
    this.name = 'LogisticsRetryRequiredError';
    this.stage = stage;
    this.retryAfterMs = retryAfterMs;
    Object.assign(this, details);
  }
}

class PddSubmitRejectedError extends Error {
  constructor(stage, receipt) {
    super(`拼多多提交被平台拒绝（阶段: ${stage}）：${receipt.errorMsg || `HTTP ${receipt.httpStatus}`}`);
    this.name = 'PddSubmitRejectedError';
    this.stage = stage;
    this.errorCode = receipt.errorCode ?? null;
    this.errorMsg = receipt.errorMsg || null;
    this.externalEffectStatus = 'failed';
    this.externalEffectReceipt = receipt;
  }
}

class TmsOmsQueryAuthorizationError extends Error {
  constructor(httpStatus, responseUrl) {
    super(`TMS OMS 查询返回 HTTP ${httpStatus}`);
    this.name = 'TmsOmsQueryAuthorizationError';
    this.httpStatus = httpStatus;
    this.responseUrl = responseUrl || null;
  }
}

class PddSubmitButtonRenderError extends Error {
  constructor(stage, timeoutMs, visibleCount) {
    super(`拼多多${stage}提交按钮等待 ${Math.ceil(timeoutMs / 1000)} 秒仍未渲染（可见数量: ${visibleCount}）`);
    this.name = 'PddSubmitButtonRenderError';
    this.stage = stage;
    this.externalEffectStatus = 'failed';
    this.externalEffectReceipt = {
      clickAttempted: false,
      reason: 'submit-button-not-rendered',
      stage,
      timeoutMs,
      visibleCount,
    };
  }
}

class PddResolutionDetailContextLostError extends Error {
  constructor(stage, currentUrl, observedOrderNumber = null) {
    super(`拼多多${stage}提交前目标工单详情上下文已丢失`);
    this.name = 'PddResolutionDetailContextLostError';
    this.code = 'PDD_RESOLUTION_DETAIL_CONTEXT_LOST';
    this.stage = stage;
    this.currentUrl = currentUrl;
    this.observedOrderNumber = observedOrderNumber;
    this.externalEffectStatus = 'failed';
    this.externalEffectReceipt = {
      clickAttempted: false,
      reason: 'resolution-detail-context-lost',
      stage,
      currentUrl,
      observedOrderNumber,
    };
  }
}

class PddWorkOrderAlreadyCompletedError extends Error {
  constructor(stage, completedState) {
    super('拼多多工单已完结，跳过重复提交');
    this.name = 'PddWorkOrderAlreadyCompletedError';
    this.stage = stage;
    this.completedState = completedState;
    this.externalEffectStatus = 'failed';
    this.externalEffectReceipt = {
      clickAttempted: false,
      reason: 'work-order-already-completed',
      stage,
      confirmationMethod: completedState?.confirmationMethod || 'detail-completed',
    };
  }
}

const isVisuallyRendered = async (locator) => locator.evaluate((element) => {
  const rect = element.getBoundingClientRect();
  const viewportWidth = document.documentElement.clientWidth || window.innerWidth;
  const viewportHeight = document.documentElement.clientHeight || window.innerHeight;
  if (rect.width <= 4 || rect.height <= 4
    || rect.right <= 0 || rect.bottom <= 0
    || rect.left >= viewportWidth || rect.top >= viewportHeight) return false;

  let current = element;
  while (current) {
    const style = window.getComputedStyle(current);
    const opacity = Number.parseFloat(style.opacity || '1');
    if (style.display === 'none'
      || style.visibility === 'hidden'
      || style.visibility === 'collapse'
      || style.contentVisibility === 'hidden'
      || (Number.isFinite(opacity) && opacity <= 0.05)) return false;
    current = current.parentElement || current.getRootNode()?.host || null;
  }

  const left = Math.max(0, rect.left);
  const right = Math.min(viewportWidth - 1, rect.right);
  const top = Math.max(0, rect.top);
  const bottom = Math.min(viewportHeight - 1, rect.bottom);
  const points = [
    [(left + right) / 2, (top + bottom) / 2],
    [left + Math.min(4, (right - left) / 2), top + Math.min(4, (bottom - top) / 2)],
    [right - Math.min(4, (right - left) / 2), bottom - Math.min(4, (bottom - top) / 2)],
  ];
  return points.some(([x, y]) => {
    const topElement = document.elementFromPoint(x, y);
    return topElement === element
      || Boolean(topElement && (element.contains(topElement) || topElement.contains(element)));
  });
}).catch(() => false);

const anyVisibleText = async (targetPage, patterns) => {
  for (const pattern of patterns) {
    const matches = targetPage.getByText(pattern);
    const count = await matches.count().catch(() => 0);
    for (let index = 0; index < count; index++) {
      const match = matches.nth(index);
      if (!await isVisuallyRendered(match)) continue;
      const renderedText = await match.innerText().catch(() => '');
      if (pattern.test(renderedText)) return true;
    }
  }
  return false;
};

// Persist a human-readable location for the dashboard. Verification surfaces
// remain manual except for the separately classified image-selection modal,
// which is dismissed by its own strict close-and-release path.
const locateHumanVerification = async (
  targetPage,
  system,
  stage,
  diagnostics,
  detection,
  extra = {},
) => {
  if (!detection) return null;
  const existing = readProgress().verificationLocation;
  const currentUrl = targetPage.url();
  const reusable = existing
    && ['detected', 'waiting-human', 'verification-required'].includes(existing.status)
    && existing.system === system
    && existing.stage === stage
    && existing.url === currentUrl;
  return {
    ...(reusable ? existing : {}),
    id: reusable ? existing.id : crypto.randomUUID(),
    shopId,
    system,
    stage,
    status: 'waiting-human',
    url: currentUrl,
    frameUrl: detection.frameUrl || undefined,
    selector: detection.selector,
    boundingBox: detection.boundingBox,
    screenshotFileId: diagnostics?.screenshot || existing?.screenshotFileId || null,
    confidence: detection.confidence,
    detectedAt: reusable ? existing.detectedAt : new Date().toISOString(),
    lastSeenAt: new Date().toISOString(),
    ...extra,
  };
};

const verificationPageRole = (page) => {
  if (!page || page.isClosed()) return null;
  if (page === pddPage) return 'pdd-anchor';
  if (page === omsPage) return 'oms-anchor';
  if (page === tmsPage) return 'tms-anchor';
  return derivedPageMeta.get(page)?.purpose || 'derived-tab';
};

const verificationSurfaceFingerprint = ({
  system,
  page,
  detection,
  pageRole = null,
} = {}) => JSON.stringify([
  String(system || ''),
  page?.isClosed?.() ? '' : String(page?.url?.() || ''),
  String(pageRole || verificationPageRole(page) || ''),
  String(detection?.frameUrl || ''),
  String(detection?.selector || ''),
]);

const verificationTimeoutSuppressesSurface = (progress, {
  system,
  page,
  detection,
  pageRole = null,
} = {}) => {
  if (isManualPddLoginSurface(page)) return false;
  const timeout = progress?.verificationTimeout;
  if (timeout?.status !== 'closed' || timeout.system !== system || !timeout.fingerprint) return false;
  // Reloading the permanent PDD login anchor creates a fresh challenge surface
  // in the same tab. Do not suppress that new challenge just because its URL
  // and selector happen to match the expired one.
  if (timeout.closeResult?.suppressVerification === false) return false;
  const timedOutAtMs = Date.parse(String(timeout.timedOutAt || ''));
  if (!Number.isFinite(timedOutAtMs)) return false;
  const suppressionUntilMs = Date.parse(String(timeout.suppressUntil || ''))
    || timedOutAtMs + humanVerificationPostTimeoutSuppressionMs;
  if (Date.now() >= suppressionUntilMs) return false;
  return timeout.fingerprint === verificationSurfaceFingerprint({
    system,
    page,
    detection,
    pageRole,
  });
};

// A wait deadline is a scheduler boundary, not permission to discard a live
// challenge. If PDD has not rendered its explicit expired/retry message, keep
// the location and let the verification plugin or operator finish it later.
const preserveVerificationSurfaceForPlugin = ({
  system,
  stage,
  page,
  location = null,
  detection = null,
  closeResult = null,
  login = false,
} = {}) => {
  const current = readProgress();
  const now = new Date().toISOString();
  const activeLocation = current.verificationLocation || location || null;
  const fingerprint = page
    ? verificationSurfaceFingerprint({
      system,
      page,
      detection,
      pageRole: verificationPageRole(page),
    })
    : null;
  const timeoutStage = activeLocation?.stage || stage || null;
  const timeoutVerificationId = activeLocation?.id || null;
  const timeoutCloseResult = JSON.stringify(closeResult || null);
  const existingTimeoutCloseResult = JSON.stringify(current.verificationTimeout?.closeResult || null);
  const alreadyPreserved = current.step === (login ? 'manual-login-required' : 'human-verification-required')
    && current.verificationLocation?.id === timeoutVerificationId
    && current.verificationLocation?.system === system
    && current.verificationLocation?.url === activeLocation?.url
    && current.verificationStage === timeoutStage
    && current.verificationFocus?.pluginOwned === true
    && current.verificationFocus?.status === 'waiting'
    && current.verificationTimeout?.status === 'waiting'
    && current.verificationTimeout?.system === system
    && current.verificationTimeout?.stage === timeoutStage
    && current.verificationTimeout?.verificationId === timeoutVerificationId
    && current.verificationTimeout?.fingerprint === fingerprint
    && current.verificationRecheck?.status === 'waiting'
    && existingTimeoutCloseResult === timeoutCloseResult
    && current.authHealth?.[system]?.status === 'verification-required';
  // The resident observer runs every few seconds. Once the same challenge has
  // already been handed to the plugin, rewriting the checkpoint only changes
  // volatile timestamps and emits a duplicate workflow event.
  if (alreadyPreserved) {
    return {
      preserved: true,
      at: current.verificationTimeout?.lastTimeoutAt || now,
      fingerprint,
      deduplicated: true,
    };
  }
  writeProgress({
    step: login ? 'manual-login-required' : 'human-verification-required',
    verificationStage: activeLocation?.stage || stage || null,
    currentUrl: page && !page.isClosed() ? page.url() : current.currentUrl || null,
    verificationLocation: activeLocation,
    verificationFocus: {
      ...(current.verificationFocus || {}),
      status: 'waiting',
      stage: activeLocation?.stage || stage || null,
      ownerShopId: shopId,
      pluginOwned: true,
      lastTimeoutAt: now,
    },
    verificationTimeout: {
      ...(current.verificationTimeout || {}),
      status: 'waiting',
      system,
      stage: activeLocation?.stage || stage || null,
      verificationId: activeLocation?.id || null,
      fingerprint,
      detectedAt: activeLocation?.detectedAt || null,
      lastTimeoutAt: now,
      closeResult,
      externalActionsReplayed: false,
    },
    verificationRecheck: {
      ...(current.verificationRecheck || {}),
      trigger: 'verification-timeout-preserved-for-plugin',
      status: 'waiting',
      requestedAt: now,
      verificationId: activeLocation?.id || null,
    },
    manualReview: null,
    error: null,
  });
  updateAuthHealth(system, 'verification-required', page || null, {
    stage: activeLocation?.stage || stage || null,
    source: 'verification-timeout-preserved-for-plugin',
    evidence: 'active-challenge-retained',
  });
  return { preserved: true, at: now, fingerprint };
};

// Release the scheduler gate when the two-minute budget is exhausted even if
// PDD did not render an explicit expired message or a usable close button.
// The live page is intentionally retained for the verification plugin, but
// the blocking verificationLocation is removed so the worker can hand the
// order back to PostgreSQL and continue with other work. The fingerprint is
// kept in verificationTimeout so the same observer result is suppressed for
// a bounded cooldown instead of immediately recreating the gate.
const writeVerificationTimeoutRelease = ({
  system,
  stage,
  page = null,
  location = null,
  detection = null,
  closeResult = null,
  login = false,
} = {}) => {
  // A disabled auto-close result means the live challenge is still present.
  // No caller may translate that result into a released scheduler gate: doing
  // so lets business navigation move away from the page the operator must use.
  if (isManualPddLoginSurface(page)
    || closeResult?.reason === 'pdd-login-manual-only'
    || closeResult?.reason === 'verification-auto-close-disabled') {
    return preserveVerificationSurfaceForPlugin({
      system,
      stage,
      page,
      location,
      detection,
      closeResult,
      login,
    });
  }
  const current = readProgress();
  const timedOutAt = new Date().toISOString();
  const activeLocation = current.verificationLocation || location || null;
  const pageUrl = page && !page.isClosed() ? page.url() : current.currentUrl || activeLocation?.url || '';
  const pageRole = page ? verificationPageRole(page) : activeLocation?.pageRole || null;
  const fingerprint = page
    ? verificationSurfaceFingerprint({ system, page, detection, pageRole })
    : JSON.stringify([
      String(system || ''),
      String(pageUrl || ''),
      String(pageRole || ''),
      String(activeLocation?.frameUrl || ''),
      String(activeLocation?.selector || ''),
    ]);
  const verificationId = activeLocation?.id || current.verificationTimeout?.verificationId || null;
  const detectedAt = activeLocation?.detectedAt
    || current.verificationTimeout?.detectedAt
    || null;
  const releaseStep = login ? 'manual-login-required' : 'verification-timeout-closed';
  const releaseFocus = login
    ? {
      ...(current.verificationFocus || {}),
      status: 'released-timeout',
      stage: stage || activeLocation?.stage || null,
      ownerShopId: shopId,
      releasedAt: timedOutAt,
      pluginOwned: true,
    }
    : null;
  writeProgress({
    step: releaseStep,
    verificationStage: login ? current.verificationStage || stage || null : null,
    currentUrl: pageUrl || null,
    verificationLocation: null,
    verificationFocus: releaseFocus,
    verificationRecovery: null,
    verificationTimeout: {
      ...(current.verificationTimeout || {}),
      status: 'closed',
      system,
      stage: stage || activeLocation?.stage || null,
      timeoutMs: humanVerificationMaxTimeoutMs,
      verificationId,
      fingerprint,
      detectedAt,
      timedOutAt,
      suppressUntil: new Date(
        Date.parse(timedOutAt) + humanVerificationPostTimeoutSuppressionMs,
      ).toISOString(),
      // The challenge may still be visible; "closed" describes the
      // scheduler gate, not a claim that PDD accepted the verification.
      closeResult,
      releaseReason: 'verification-timeout-release',
      pluginOwned: true,
      surface: activeLocation
        ? { ...activeLocation, status: 'plugin-owned-timeout' }
        : null,
      externalActionsReplayed: false,
    },
    verificationRecheck: {
      ...(current.verificationRecheck || {}),
      trigger: 'verification-timeout-release',
      status: 'closed',
      verificationId,
      requestedAt: timedOutAt,
      completedAt: timedOutAt,
      externalActionsReplayed: false,
    },
    manualReview: null,
    error: null,
  });
  if (!login) {
    updateAuthHealth(system, 'unknown', page || null, {
      stage: null,
      source: 'verification-timeout-release',
      evidence: closeResult?.closed ? 'challenge-surface-closed' : 'challenge-surface-retained-for-plugin',
    });
  }
  return {
    released: true,
    status: 'closed',
    verificationId,
    fingerprint,
    timedOutAt,
    closeResult,
  };
};

// A challenge can be rendered in a popup/detail tab while the permanent
// anchor is already back on a list page. Scan every live page in the relevant
// browser context, preferring the page the workflow is currently using. This
// helper is read-only; foreground activation happens only after the focus
// lock is acquired by checkForHumanVerification.
const pagesForVerificationScan = (preferredPage, system, stage = '') => {
  const pageContexts = [];
  try {
    const preferredContext = preferredPage?.context?.();
    if (preferredContext) pageContexts.push(preferredContext);
  } catch {}
  pageContexts.push(context);
  const candidates = [preferredPage];
  for (const pageContext of pageContexts) {
    try {
      candidates.push(...(pageContext.pages?.() || []));
    } catch {}
  }
  candidates.push(...derivedPages);
  const unique = [...new Set(candidates)];
  return unique.filter((page) => {
    if (!page || page.isClosed()) return false;
    const inferredSystem = workflowSystemForAction(page, stage);
    if (inferredSystem === system) return true;
    if (inferredSystem !== 'workflow') return false;
    if (system === 'pdd' && page === pddPage) return true;
    if (system === 'oms' && (page === omsPage || page === activeSharedOmsPage)) return true;
    if (system === 'tms' && page === tmsPage) return true;
    return false;
  });
};

const loginSystemForStage = (stage = '') => {
  const value = String(stage || '').trim().toLowerCase();
  if (/(?:^|-)pdd(?:-|$)|pinduoduo/.test(value)) return 'pdd';
  if (/(?:^|-)oms(?:-|$)|jeoms/.test(value)) return 'oms';
  if (/(?:^|-)tms(?:-|$)/.test(value)) return 'tms';
  return null;
};

// Login can be left in a popup/derived tab while the permanent system anchor
// has already returned to a business page. Locate the actual login tab before
// waiting so manual input and automatic recovery always operate on the same
// page the operator can see.
const locateSystemLoginAcrossPages = async (
  preferredPage,
  system,
  isLoginUrl,
  stage = '',
) => {
  const candidates = pagesForVerificationScan(preferredPage, system, stage);
  for (const page of candidates) {
    if (!page || page.isClosed()) continue;
    let url = '';
    try { url = page.url(); } catch { continue; }
    if (!isLoginUrl(url)) continue;
    const urlSystem = ['pdd', 'oms', 'tms']
      .find((candidate) => isSystemLoginUrl(candidate, url)) || null;
    if (urlSystem && urlSystem !== system) continue;
    if (!urlSystem && workflowSystemForAction(page, stage) !== system) continue;
    return { page, url };
  }
  return null;
};

// A QR/CAPTCHA recovery can leave an old login popup alive after the anchor
// has authenticated. Once a business page is confirmed, close only those
// derived login tabs so a later cross-tab scan cannot pull the workflow back
// into a stale login session. Permanent anchor tabs remain untouched.
const closeStaleSystemLoginPages = async (
  keepPage,
  system,
  isLoginUrl,
  stage = '',
) => {
  // A business URL alone does not prove the PDD session is still valid.
  // Any cleanup during an exact verification recovery can close the login
  // page that the operator is using and trigger another recovery attempt.
  // Normal stale-tab cleanup resumes after the command has ended.
  if (system === 'pdd' && activeVerificationRecoveryCommand) return;
  if (system === 'pdd') {
    await waitForPddPostLoginBarrier(keepPage, stage, {
      source: 'stale-login-tab-cleanup',
    });
  }
  for (const page of pagesForVerificationScan(keepPage, system, stage)) {
    // An observer already in flight must also respect the login owner's wait.
    if (system === 'pdd' && (pddManualLoginWaits > 0 || pddPostLoginStabilityWaits > 0)) return;
    if (!page || page === keepPage || page.isClosed() || !derivedPages.has(page)) continue;
    let url = '';
    try { url = page.url(); } catch { continue; }
    if (!isLoginUrl(url)) continue;
    await closeDerivedPage(page).catch(() => {});
  }
};

// Resolve the operator-facing login tab before acquiring the foreground lock.
// A login route can be opened by a popup while the permanent anchor remains
// on a business page; focusing the anchor first makes the desktop appear to
// jump and can leave the operator typing into the wrong shop.
const resolveSystemLoginPage = async (preferredPage, system, isLoginUrl, stage = '') => {
  const located = await locateSystemLoginAcrossPages(
    preferredPage,
    system,
    isLoginUrl,
    stage,
  );
  return located?.page || preferredPage;
};

const locateHumanVerificationAcrossPages = async (
  preferredPage,
  system,
  stage = '',
  { requireStable = false, stableDelayMs = 250 } = {},
) => {
  for (const page of pagesForVerificationScan(preferredPage, system, stage)) {
    const detection = await detectHumanVerification(page).catch(() => null);
    if (detection) {
      const pageRole = verificationPageRole(page);
      // A timeout can race with this scan. Re-read the progress after the DOM
      // detector returns so a stale in-flight result cannot recreate the same
      // active gate that was just closed.
      if (verificationTimeoutSuppressesSurface(readProgress(), {
        system,
        page,
        detection,
        pageRole,
      })) continue;
      if (requireStable) {
        // Do not claim a challenge from a one-frame loading shell. Confirm the
        // same page and detector signal after the iframe/slider has had time to
        // finish mounting. This prevents an immediate tab switch while the
        // operator is starting a drag.
        await new Promise((resolve) => setTimeout(resolve, Math.max(50, stableDelayMs)));
        if (page.isClosed()) continue;
        const confirmation = await detectHumanVerification(page).catch(() => null);
        if (!confirmation) continue;
        const confirmedFingerprint = verificationSurfaceFingerprint({
          system,
          page,
          detection: confirmation,
          pageRole,
        });
        const initialFingerprint = verificationSurfaceFingerprint({
          system,
          page,
          detection,
          pageRole,
        });
        if (confirmedFingerprint !== initialFingerprint) continue;
      }
      return {
        page,
        detection,
        pageRole,
      };
    }
  }
  return null;
};

// A single shop can invoke the detector from several concurrent Playwright
// callbacks (action guards, cross-tab observer, and resident recovery). They
// must share one in-flight check. Without this coalescing, one caller can
// clear the persisted challenge while another caller is still publishing the
// same challenge, producing a tight challenge-cleared -> verification-required
// loop and wasting the worker on duplicate state writes.
const activeHumanVerificationChecks = new Map();

const checkForHumanVerificationUnsafe = async (targetPage, stage) => {
  // Security challenges take precedence over any stale-page recovery. The
  // recovery modal can be mounted at the same time as a PDD challenge; clicking
  // it first would redraw the page and invalidate a drag that just started.
  const requestedPage = targetPage;
  const inferredSystem = workflowSystemForAction(requestedPage, stage);
  const verificationSystem = ['pdd', 'oms', 'tms'].includes(inferredSystem)
    ? inferredSystem
    : requestedPage === activeSharedOmsPage || requestedPage === omsPage
      ? 'oms'
      : requestedPage === tmsPage ? 'tms' : 'pdd';
  let locatedVerification = await locateHumanVerificationAcrossPages(
    requestedPage,
    verificationSystem,
    stage,
    { requireStable: true },
  );
  if (!locatedVerification && !isManualPddLoginSurface(requestedPage)) {
    const current = readProgress();
    const activeChallengeForSystem = current.verificationLocation?.system === verificationSystem
      || current.authHealth?.[verificationSystem]?.status === 'verification-required';
    // If a challenge is already persisted for this system, do not run any
    // page-refresh recovery while its iframe is temporarily redrawing.
    if (!activeChallengeForSystem) {
      const stalePageRefresh = await clickVisiblePddStalePageRefresh(requestedPage).catch((error) => ({
        handled: false,
        reason: 'stale-page-refresh-check-failed',
        error: error.message,
      }));
      if (stalePageRefresh.handled) {
        logRunStep('pdd-stale-page-refresh-clicked', {
          stage,
          beforeUrl: stalePageRefresh.beforeUrl,
          afterUrl: stalePageRefresh.afterUrl,
          handledAt: stalePageRefresh.handledAt,
        });
        writeProgress({
          transientWorkflowRecovery: {
            kind: 'pdd-stale-page-refresh',
            stage,
            beforeUrl: stalePageRefresh.beforeUrl,
            afterUrl: stalePageRefresh.afterUrl,
            handledAt: stalePageRefresh.handledAt,
          },
          error: null,
        });
        // A stale-page refresh is an in-place navigation. Re-scan only after
        // it settles so the new challenge, if any, is treated as authoritative.
        locatedVerification = await locateHumanVerificationAcrossPages(
          requestedPage,
          verificationSystem,
          stage,
          { requireStable: true, stableDelayMs: 300 },
        );
      }
    }
  }
  let verificationPage = locatedVerification?.page || requestedPage;
  let verificationDetection = locatedVerification?.detection || null;
  let verificationPresent = Boolean(locatedVerification);
  if (!verificationPresent) {
    const progress = readProgress();
    const staleLocation = progress.verificationLocation;
    const staleSystem = staleLocation?.system
      || Object.entries(progress.authHealth || {})
        .find(([, health]) => health?.status === 'verification-required')?.[0];
    const staleBelongsToCurrentSystem = staleSystem === verificationSystem
      || (!staleSystem && !staleLocation && progress.verificationStage);
    if (staleBelongsToCurrentSystem) {
      if (humanVerificationAbsenceGraceMs > 0) {
        await new Promise((resolve) => setTimeout(resolve, humanVerificationAbsenceGraceMs));
        locatedVerification = await locateHumanVerificationAcrossPages(
          requestedPage,
          verificationSystem,
          stage,
          { requireStable: true, stableDelayMs: 300 },
        );
        if (locatedVerification) {
          verificationPage = locatedVerification.page;
          verificationDetection = locatedVerification.detection;
          verificationPresent = true;
        }
      }
    }
    if (!verificationPresent && staleBelongsToCurrentSystem) {
      const authHealth = { ...(progress.authHealth || {}) };
      if (staleSystem && authHealth[staleSystem]?.status === 'verification-required') {
        authHealth[staleSystem] = {
          ...authHealth[staleSystem],
          status: 'unknown',
          stage: null,
          checkedAt: new Date().toISOString(),
        };
      }
      writeProgress({
        step: progress.step === 'human-verification-required' ? 'challenge-cleared' : progress.step,
        verificationStage: null,
        verificationLocation: null,
        verificationFocus: null,
        authHealth,
        manualReview: null,
        error: null,
      });
      console.log(`[人工验证已解除] 阶段: ${stage}，页面当前没有验证码，流程继续。`);
    }
  }
  if (!verificationPresent && requestedPage.url().includes('mms.pinduoduo.com/login')) {
    const refreshed = await refreshExpiredPddQr(requestedPage).catch((error) => {
      console.warn(`[PDD 登录] 刷新失效二维码失败，将继续等待人工操作: ${error.message}`);
      return false;
    });
    if (refreshed) return false;
  }
  if (!verificationPresent) return false;

  // PDD's image-selection prompt is the one explicitly non-actionable
  // challenge that may be dismissed. Confirm the X click and release only
  // this shop before entering the normal manual-verification wait path.
  if (isImageClickVerificationDetection(verificationDetection)) {
    const closeResult = await releaseImageClickVerificationAfterClose({
      system: verificationSystem,
      stage,
      page: verificationPage,
      detection: verificationDetection,
    }).catch((error) => ({
      closed: false,
      released: false,
      reason: error.message,
    }));
    if (closeResult.released) return false;
  }
  // Business-page slider/puzzle challenges are also disposable for this
  // worker. Close only the rendered challenge surface, clear this shop's
  // checkpoint, and let the current order go back through the normal queue.
  // Login pages deliberately remain on the manual-login path.
  if (businessVerificationAutoCloseEnabled
    && !isSystemLoginUrl(verificationSystem, verificationPage.url())) {
    const closeResult = await releaseImageClickVerificationAfterClose({
      system: verificationSystem,
      stage,
      page: verificationPage,
      detection: verificationDetection,
      location: null,
      allowBusinessVerification: true,
    }).catch((error) => ({
      closed: false,
      released: false,
      reason: error.message,
    }));
    if (closeResult.released) return false;
  }

  const originUrl = requestedPage.isClosed() ? null : requestedPage.url();
  const originPageRole = verificationPageRole(requestedPage);
  let lastVerificationPageSignature = `${verificationPage.url()}|${verificationPageRole(verificationPage)}`;
  let lastVerificationPageUrl = verificationPage.url();
  let verificationPageMissingSince = null;
  const verificationStillRequired = async () => {
    // Keep the originally selected challenge tab authoritative while it is
    // still rendering. A transient detector miss during a drag must not cause
    // a cross-tab scan to select another tab or release the shop gate.
    if (verificationPage && !verificationPage.isClosed()) {
      const currentDetection = await detectHumanVerification(verificationPage).catch(() => null);
      if (currentDetection) {
        verificationPageMissingSince = null;
        verificationDetection = currentDetection;
        return true;
      }
      verificationPageMissingSince ||= Date.now();
      const missingForMs = Date.now() - verificationPageMissingSince;
      if (missingForMs < humanVerificationAbsenceGraceMs) return true;
      // Keep the original tab authoritative while a slider iframe is being
      // redrawn. Only after this longer window may another challenge tab be
      // considered for rebinding.
      if (!verificationPage.isClosed()
        && verificationPage.url() === lastVerificationPageUrl
        && missingForMs < verificationPageRebindGraceMs) return true;
    }
    const located = await locateHumanVerificationAcrossPages(
      requestedPage,
      verificationSystem,
      stage,
      { requireStable: true, stableDelayMs: 300 },
    );
    if (located) {
      verificationPage = located.page;
      verificationDetection = located.detection;
      verificationPageMissingSince = null;
      const nextSignature = `${verificationPage.url()}|${verificationPageRole(verificationPage)}`;
      if (nextSignature !== lastVerificationPageSignature) {
        lastVerificationPageSignature = nextSignature;
        lastVerificationPageUrl = verificationPage.url();
        const current = readProgress();
        const location = await locateHumanVerification(
          verificationPage,
          verificationSystem,
          current.verificationLocation?.stage || stage,
          null,
          verificationDetection,
          {
            source: 'cross-tab-scan',
            pageRole: verificationPageRole(verificationPage),
            originUrl,
            originPageRole,
          },
        );
        writeProgress({
          step: 'human-verification-required',
          currentUrl: verificationPage.url(),
          verificationLocation: location,
          error: null,
        });
      }
      return true;
    }
    if (!requestedPage.isClosed()
      && isSystemLoginUrl(verificationSystem, requestedPage.url())
      && requestedPage !== activeSharedOmsPage) {
      const livePage = await adoptLiveSystemAnchor(verificationSystem);
      if (livePage !== requestedPage
        && isAuthenticatedSystemUrl(verificationSystem, livePage.url())
        && !await hasHumanVerification(livePage)) return false;
    }
    return false;
  };
  const diagnostics = await saveWorkflowDiagnostics(verificationPage, `human-verification-${stage}`);
  const verificationLocation = await locateHumanVerification(
    verificationPage,
    verificationSystem,
    stage,
    diagnostics,
    verificationDetection,
    {
      source: 'cross-tab-scan',
      pageRole: verificationPageRole(verificationPage),
      originUrl,
      originPageRole,
    },
  );
  writeProgress({
    step: 'human-verification-required',
    verificationStage: stage,
    currentUrl: verificationPage.url(),
    verificationLocation,
    verificationFocus: {
      status: 'queued',
      stage,
      queuedAt: new Date().toISOString(),
    },
    verificationRecheck: null,
    // A challenge supersedes an old parse/review message; retain only the
    // current verification location as the actionable pause reason.
    manualReview: null,
    error: null,
  });
  updateAuthHealth(verificationSystem, 'verification-required', verificationPage, {
    stage,
    source: 'cross-tab-verification-scan',
    evidence: 'challenge-rendered-in-live-page',
  });
  console.error(`\n[需要人工处理] 页面出现验证码/滑块/安全验证。阶段: ${stage}`);
  console.error(browserHeadless
    ? `[需要人工处理] 无头流程已停止，请在本地有界面环境恢复认证状态。URL: ${verificationPage.url()}\n`
    : `[需要人工处理] 浏览器保持打开，请在页面中手动完成验证。URL: ${verificationPage.url()}\n`);
  if (browserHeadless) throw new HumanVerificationRequiredError(stage, verificationPage.url());

  const verificationUrl = verificationPage.url();
  // A claimed order must not wait behind an idle discovery/refund scan. Give
  // ordinary work the first business turn because its page flow is shorter;
  // the current owner is never preempted, so an active refund remains safe.
  const returnRefundCommand = activeReturnRefundCommand;
  const activeRefundWork = activeAssignmentId
    && returnRefundCommand?.action === 'run-refund';
  const activeRefundReconciliation = activeRefundWork
    && ['reserved', 'unknown'].includes(returnRefundCommand?.existingEffectStatus);
  const verificationQueuePriority = !activeAssignmentId
    ? 10
    : activeRefundWork && !activeRefundReconciliation ? 1 : 0;
  const verificationWorkClass = !activeAssignmentId
    ? 'background-scan'
    : activeRefundReconciliation
      ? 'active-refund-reconciliation'
      : activeRefundWork ? 'active-refund' : 'active-ordinary';
  // Start the budget at first detection, including any overlap between this
  // shop's resident observer and its current business operation.
  const persistedDetectedAtMs = Date.parse(String(verificationLocation?.detectedAt || ''));
  const verificationDetectedAtMs = Number.isFinite(persistedDetectedAtMs)
    ? Math.min(Date.now(), persistedDetectedAtMs)
    : Date.now();
  let verificationBudgetWindow = null;
  let deadline = null;
  if (returnRefundCommand && returnRefundCommand.verificationBudgetMs > 0) {
    verificationBudgetWindow = beginVerificationBudgetWindow({
      limitMs: Math.min(humanVerificationMaxTimeoutMs, returnRefundCommand.verificationBudgetMs),
      consumedMs: returnRefundCommand.verificationWaitConsumedMs,
      now: verificationDetectedAtMs,
    });
    deadline = verificationBudgetWindow.deadline;
  } else {
    const effectiveVerificationTimeoutMs = activeAssignmentId
      ? claimedHumanVerificationTimeoutMs
      : humanVerificationTimeoutMs;
    deadline = effectiveVerificationTimeoutMs > 0
      ? verificationDetectedAtMs + effectiveVerificationTimeoutMs
      : null;
  }
  // The business wait budget must never dismiss or release a login challenge.
  if (isManualPddLoginSurface(verificationPage)) {
    deadline = null;
    verificationBudgetWindow = null;
  }
  let pendingManualRefresh = null;
  let automaticVerificationRefreshInProgress = false;
  const recordPddManualRefresh = (frame) => {
    if (verificationSystem !== 'pdd'
      || automaticVerificationRefreshInProgress
      || frame !== verificationPage.mainFrame()) return;
    const current = readProgress();
    if (current.step !== 'human-verification-required') return;
    pendingManualRefresh = {
      trigger: 'pdd-manual-refresh',
      url: frame.url() || verificationPage.url(),
      detectedAt: new Date().toISOString(),
    };
  };
  if (verificationSystem === 'pdd') verificationPage.on('framenavigated', recordPddManualRefresh);
  let verificationWait;
  try {
    const focus = await verificationFocusCoordinator.acquire({
      stage,
      priority: verificationQueuePriority,
      isStillRequired: verificationStillRequired,
      timeoutMs: deadline === null ? null : Math.max(1, deadline - Date.now()),
      onWaiting: async ({ owner, waitingSince }) => {
        const current = readProgress();
        writeProgress({
          step: 'human-verification-required',
          verificationFocus: {
            status: 'waiting',
            stage,
            waitingSince,
            ownerShopId: owner?.shopId || null,
            ownerStage: owner?.stage || null,
            priority: verificationQueuePriority,
            workClass: verificationWorkClass,
          },
          error: null,
        });
      },
    });
    if (!focus.acquired) {
      if (focus.status === 'timeout') {
        verificationWait = { status: 'timeout', queued: true, waitedMs: focus.waitedMs };
      } else if (verificationPage.isClosed()) {
        throw new HumanVerificationRequiredError(stage, verificationUrl);
      } else {
        verificationWait = { status: 'cleared', queued: true };
      }
    } else {
      // The challenge can disappear while this shop waits behind another
      // verifier. Re-check the exact page immediately before activation so a
      // stale detector result never causes a visible tab jump.
      const preActivationVerification = await locateHumanVerificationAcrossPages(
        verificationPage,
        verificationSystem,
        stage,
        { requireStable: true, stableDelayMs: 300 },
      );
      if (!preActivationVerification) {
        verificationWait = { status: 'cleared', queued: false };
      } else {
        verificationPage = preActivationVerification.page;
        verificationDetection = preActivationVerification.detection;
        // Select only this browser's challenge tab. Other shops and native
        // window focus remain independent while this shop pauses its actions.
        const activation = await activateVerificationPage(verificationPage, {
          backgroundOnly: true,
        });
        writeProgress({
        step: 'human-verification-required',
        verificationFocus: {
          status: 'active',
          stage,
          acquiredAt: focus.owner?.acquiredAt || new Date().toISOString(),
          ownerShopId: shopId,
          priority: verificationQueuePriority,
          workClass: verificationWorkClass,
          pageVisibilityState: activation?.visibilityState || null,
          tabSelected: activation?.selected === true,
          selectionMethod: activation?.method || null,
          selectionReason: activation?.reason || null,
          activatedAt: new Date().toISOString(),
          commandBudgetRemainingMs: verificationBudgetWindow?.remainingMs ?? null,
        },
        error: null,
        });
        // A CDP tab activation is an operator-visible browser operation. Keep
      // the selected challenge tab stable while the operator is clicking or
      // dragging; re-activate only when the detector finds a different tab.
      let lastFocusedVerificationPage = activation?.selected ? verificationPage : null;
        verificationWait = await waitForStableVerificationClear({
        page: verificationPage,
        hasVerification: async () => verificationStillRequired(),
        resolvePage: async () => {
          const stillRequired = await verificationStillRequired();
          if (stillRequired && verificationPage && !verificationPage.isClosed()) return verificationPage;
          return requestedPage && !requestedPage.isClosed() ? requestedPage : null;
        },
        pollMs: humanVerificationPollMs,
        stableMs: humanVerificationClearStableMs,
        deadline,
        // Business navigation is paused while the challenge remains. Re-select
        // the exact challenge tab periodically through CDP so another shop's
        // browser activity cannot leave the operator on the wrong tab. This
        // path never calls Playwright bringToFront and preserves minimized
        // window bounds.
        maintainFocus: async () => {
          if (verificationPage && !verificationPage.isClosed()) {
            const samePageDetection = await detectHumanVerification(verificationPage).catch(() => null);
            if (samePageDetection) {
              verificationPageMissingSince = null;
              verificationDetection = samePageDetection;
              // Already-selected tabs are untouched; actual changes are paced.
              const selection = await activateVerificationPage(verificationPage, { backgroundOnly: true });
              if (selection?.selected) lastFocusedVerificationPage = verificationPage;
              return verificationPage;
            }
            verificationPageMissingSince ||= Date.now();
            const missingForMs = Date.now() - verificationPageMissingSince;
            if (missingForMs < verificationPageRebindGraceMs) return verificationPage;
          }
          const located = await locateHumanVerificationAcrossPages(
            requestedPage,
            verificationSystem,
            stage,
            { requireStable: true, stableDelayMs: 300 },
          );
          if (located) {
            verificationPage = located.page;
            verificationDetection = located.detection;
            const nextActivation = await activateVerificationPage(verificationPage, {
              backgroundOnly: true,
            });
            if (nextActivation?.selected) {
              lastFocusedVerificationPage = verificationPage;
            }
            return verificationPage;
          }
          return null;
        },
        focusIntervalMs: humanVerificationFocusKeepAliveMs,
        focusQuantumMs: verificationFocusQuantumMs,
        shouldYieldFocus: () => verificationFocusCoordinator.hasWaiters(),
        autoRefreshAfterMs: verificationSystem === 'pdd'
          ? humanVerificationAutoRefreshMs
          : 0,
        maxAutoRefreshes: verificationSystem === 'pdd'
          ? humanVerificationAutoRefreshMaxAttempts
          : 0,
        isExternallyCleared: verificationSystem === 'pdd' ? async () => {
          const current = readProgress();
          const recheck = current.verificationRecheck || {};
          const expectedVerificationId = current.verificationLocation?.id
            || verificationLocation.id;
          const completedAtMs = Date.parse(String(recheck.completedAt || recheck.clearedAt || ''));
          const detectedAtMs = Date.parse(String(verificationLocation.detectedAt || ''));
          return !current.verificationLocation
            && recheck.status === 'cleared'
            && recheck.trigger === 'resident-browser-live-pages'
            && recheck.verificationId === expectedVerificationId
            && current.authHealth?.pdd?.status === 'authenticated'
            && Number.isFinite(completedAtMs)
            && (!Number.isFinite(detectedAtMs) || completedAtMs >= detectedAtMs);
        } : null,
        autoRefresh: verificationSystem === 'pdd' ? async ({ attempt, triggeredAt }) => {
          automaticVerificationRefreshInProgress = true;
          const refresh = {
            trigger: 'pdd-auto-refresh',
            attempt,
            requestedAt: new Date(triggeredAt).toISOString(),
            url: verificationPage.url(),
            status: 'reloading',
          };
          try {
            await verificationPage.reload({
              waitUntil: 'domcontentloaded',
              timeout: Math.max(5_000, Math.min(30_000, pddRenderWaitMs || 30_000)),
            });
            return {
              ...refresh,
              status: 'reloaded',
              url: verificationPage.url(),
              completedAt: new Date().toISOString(),
            };
          } catch (error) {
            return {
              ...refresh,
              status: 'failed',
              error: error.message,
              completedAt: new Date().toISOString(),
            };
          } finally {
            automaticVerificationRefreshInProgress = false;
          }
        } : null,
        onAutoRefresh: async (refresh) => {
          const current = readProgress();
          if (current.step !== 'human-verification-required') return;
          writeProgress({
            step: 'human-verification-required',
            currentUrl: verificationPage.url(),
            verificationRecheck: refresh,
            error: null,
          });
          console.log(refresh.status === 'reloaded'
            ? `[人工验证自动复检] 验证码持续 ${Math.round(humanVerificationAutoRefreshMs / 1000)} 秒未解除，已刷新一次供插件重新处理。阶段: ${stage}`
            : `[人工验证自动复检] 拼多多页面刷新失败，继续等待当前验证码并按时释放队列。阶段: ${stage}`);
        },
        consumeRefresh: () => {
          const refresh = pendingManualRefresh;
          pendingManualRefresh = null;
          return refresh;
        },
        onRefresh: async (refresh) => {
          const current = readProgress();
          if (current.step !== 'human-verification-required') return;
          writeProgress({
            step: 'human-verification-required',
            currentUrl: verificationPage.url(),
            verificationRecheck: {
              trigger: 'pdd-manual-refresh',
              status: 'checking',
              url: refresh.url || verificationPage.url(),
              requestedAt: refresh.detectedAt || new Date().toISOString(),
            },
            error: null,
          });
          console.log(`[人工验证复检] 检测到 VNC 内刷新拼多多页面，正在复检并准备继续当前订单。阶段: ${stage}`);
        },
        });
      }
    }
  } finally {
    if (verificationBudgetWindow && returnRefundCommand) {
      returnRefundCommand.verificationWaitConsumedMs = consumeVerificationBudgetWindow(
        verificationBudgetWindow,
      );
    }
    verificationFocusCoordinator.release();
    if (verificationSystem === 'pdd') verificationPage.off('framenavigated', recordPddManualRefresh);
  }
  if (verificationWait.status !== 'cleared') {
    if (verificationWait.status === 'timeout') {
      const closeResult = await closeHumanVerificationSurface(
        verificationPage,
        verificationDetection,
      );
      if (closeResult.reason === 'verification-auto-close-disabled') {
        console.warn(`[人工验证] ${shopId} 验证码等待超时但未关闭，自动 X 已禁用，保留当前标签页和工单闸门等待人工完成。`);
        throw new HumanVerificationRequiredError(
          stage,
          verificationPage.isClosed() ? verificationUrl : verificationPage.url(),
        );
      }
      if (!closeResult.closed) {
        writeVerificationTimeoutRelease({
          system: verificationSystem,
          stage,
          page: verificationPage,
          location: verificationLocation,
          detection: verificationDetection,
          closeResult,
        });
        throw new HumanVerificationTimeoutError(
          stage,
          verificationPage.isClosed() ? verificationUrl : verificationPage.url(),
          closeResult,
          verificationBudgetWindow?.limitMs
            || (activeAssignmentId ? claimedHumanVerificationTimeoutMs : humanVerificationTimeoutMs),
        );
      }
      const timedOutAt = new Date().toISOString();
      const current = readProgress();
      // Clear the active location in the checkpoint so the worker can release
      // this order. The adapter records the location as expired, not completed.
      writeProgress({
        step: 'verification-timeout-closed',
        verificationStage: null,
        verificationLocation: null,
        verificationFocus: null,
        verificationRecovery: null,
        verificationTimeout: {
          status: 'closed',
          stage,
          system: verificationSystem,
          timeoutMs: verificationBudgetWindow?.limitMs
            || (activeAssignmentId ? claimedHumanVerificationTimeoutMs : humanVerificationTimeoutMs),
          verificationId: verificationLocation?.id || null,
          fingerprint: verificationSurfaceFingerprint({
            system: verificationSystem,
            page: verificationPage,
            detection: verificationDetection,
            pageRole: verificationPageRole(verificationPage),
          }),
          detectedAt: verificationLocation?.detectedAt || null,
          timedOutAt,
          suppressUntil: new Date(
            Date.parse(timedOutAt) + humanVerificationPostTimeoutSuppressionMs,
          ).toISOString(),
          closeResult,
          externalActionsReplayed: false,
        },
        verificationRecheck: {
          ...(current.verificationRecheck || {}),
          trigger: 'verification-timeout-close',
          status: 'closed',
          requestedAt: timedOutAt,
          completedAt: timedOutAt,
        },
        manualReview: null,
        error: null,
        currentUrl: verificationPage.isClosed() ? verificationUrl : verificationPage.url(),
      });
      updateAuthHealth(verificationSystem, 'unknown', verificationPage, {
        stage: null,
        source: 'verification-timeout-close',
        evidence: closeResult.closed ? 'challenge-modal-closed' : 'challenge-close-unavailable',
      });
      console.warn(`[人工验证超时] ${Math.ceil((verificationBudgetWindow?.limitMs
        || (activeAssignmentId ? claimedHumanVerificationTimeoutMs : humanVerificationTimeoutMs)) / 1000)} 秒未通过，${closeResult.closed ? '已点击验证码 X 关闭弹窗' : '未找到验证码 X'}，当前工单交还队列重试。`);
      throw new HumanVerificationTimeoutError(
        stage,
        verificationPage.isClosed() ? verificationUrl : verificationPage.url(),
        closeResult,
        verificationBudgetWindow?.limitMs
          || (activeAssignmentId ? claimedHumanVerificationTimeoutMs : humanVerificationTimeoutMs),
      );
    }
    throw new HumanVerificationRequiredError(
      stage,
      verificationWait.status === 'closed' ? verificationUrl : verificationPage.url(),
    );
  }

  // Pace the first restored navigation and clicks after a business CAPTCHA.
  // A manual login has its own post-login barrier.
  if (verificationSystem === 'pdd' && !isManualPddLoginSurface(verificationPage)) {
    pddPostLoginRecoveryPacing.start();
  }
  // PDD can clear a slider by redirecting the challenge tab back to a list
  // page. If the challenge was in a different tab, keep the original business
  // tab intact and let the caller resume it. Only restore a URL when the
  // challenge replaced the original tab (or when the original tab was closed).
  let resumePage = requestedPage && !requestedPage.isClosed() ? requestedPage : null;
  if (!resumePage && originUrl) {
    resumePage = pagesForVerificationScan(verificationPage, verificationSystem, stage)
      .find((page) => !page.isClosed() && page.url() === originUrl) || null;
  }
  const clearedUrl = verificationPage.isClosed() ? '' : verificationPage.url();
  const restorePage = resumePage || verificationPage;
  const shouldRestorePddPage = verificationSystem === 'pdd'
    && restorePage === verificationPage
    && !verificationPage.isClosed()
    && originUrl
    && !originUrl.includes('mms.pinduoduo.com/login')
    && originUrl !== clearedUrl
    && isAuthenticatedSystemUrl('pdd', clearedUrl);
  let verificationPageRestore = null;
  if (shouldRestorePddPage) {
    const requestedAt = new Date().toISOString();
    writeProgress({
      step: 'verification-page-restoring',
      verificationStage: null,
      verificationLocation: null,
      verificationFocus: null,
      currentUrl: clearedUrl,
      verificationPageRestore: {
        status: 'restoring',
        fromUrl: clearedUrl,
        toUrl: originUrl,
        requestedAt,
      },
      error: null,
    });
    try {
      await navigateSystemPage(restorePage, originUrl, 'pdd-verification-page-restore');
      verificationPageRestore = {
        status: 'restored',
        fromUrl: clearedUrl,
        toUrl: restorePage.url(),
        requestedAt,
        completedAt: new Date().toISOString(),
      };
    } catch (error) {
      verificationPageRestore = {
        status: 'failed',
        fromUrl: clearedUrl,
        toUrl: verificationUrl,
        requestedAt,
        completedAt: new Date().toISOString(),
        error: error.message,
      };
      writeProgress({
        step: 'verification-page-restore-failed',
        verificationPageRestore,
        currentUrl: restorePage.isClosed() ? clearedUrl : restorePage.url(),
        error: error.message,
      });
      throw error;
    }
  }

  if (isSystemLoginUrl(verificationSystem, verificationPage.url())) {
    const previousPage = verificationPage;
    const livePage = await adoptLiveSystemAnchor(verificationSystem);
    if (livePage !== previousPage
      && isAuthenticatedSystemUrl(verificationSystem, livePage.url())
      && !await hasHumanVerification(livePage)) {
      verificationPage = livePage;
      if (previousPage !== requestedPage) await closeDerivedPage(previousPage);
    }
  }

  const statusPage = resumePage && !resumePage.isClosed() ? resumePage : verificationPage;
  const stillOnPddLogin = verificationSystem === 'pdd'
    && statusPage.url().includes('mms.pinduoduo.com/login');
  writeProgress({
    step: stillOnPddLogin ? 'manual-login-required' : 'human-verification-completed',
    verificationStage: null,
    verificationLocation: null,
    verificationFocus: null,
    verificationRecovery: null,
    verificationPageRestore,
    verificationRecheck: verificationWait.refresh ? {
      trigger: 'pdd-manual-refresh',
      status: 'cleared',
      url: verificationWait.refresh.url || statusPage.url(),
      requestedAt: verificationWait.refresh.detectedAt || null,
      completedAt: new Date().toISOString(),
    } : verificationWait.autoRefresh ? {
      ...verificationWait.autoRefresh,
      status: 'cleared',
      url: statusPage.url(),
      clearedAt: new Date().toISOString(),
    } : null,
    manualReview: null,
    currentUrl: statusPage.url(),
    error: null,
  });
  updateAuthHealth(
    verificationSystem,
    stillOnPddLogin ? 'expired' : 'authenticated',
    statusPage,
    { stage: null },
  );
  console.error(stillOnPddLogin
    ? `[人工验证完成] 阶段: ${stage}；仍在拼多多登录页，继续等待扫码登录。`
    : `[人工验证完成] 阶段: ${stage}，流程继续。`);
  return true;
};

// The resident observer can discover a CAPTCHA while the business loop is
// idle, in which case checkForHumanVerification is not on the call stack to
// select the tab. Share the shop's lock with its business loop, so overlapping
// observers cannot move its tab while other shops remain independent.
const ensureResidentVerificationFocus = ({ page, system, stage }) => {
  if (isManualPddLoginSurface(page)) return Promise.resolve(false);
  if (residentVerificationFocusPromise) return residentVerificationFocusPromise;
  // A login/verification wait in this workflow already owns the shop lock.
  // The resident observer runs concurrently while
  // that wait is active; attempting to acquire the same lock again would
  // queue behind itself and overwrite the active login state as "waiting".
  // Leave the existing owner in control and let its loop keep the exact tab
  // selected until the challenge is resolved.
  if (verificationFocusCoordinator.ownsLock()) return Promise.resolve(false);
  const task = (async () => {
    const persistedDetectedAt = Date.parse(String(readProgress().verificationLocation?.detectedAt || ''));
    const detectedAt = Number.isFinite(persistedDetectedAt)
      ? Math.min(Date.now(), persistedDetectedAt)
      : Date.now();
    const deadline = businessVerificationAutoCloseEnabled
      ? detectedAt + humanVerificationMaxTimeoutMs : null;
    const focus = await verificationFocusCoordinator.acquire({
      stage,
      priority: 10,
      timeoutMs: deadline === null ? null : Math.max(1, deadline - Date.now()),
      isStillRequired: async () => Boolean(
        // A resident observer can see PDD's one-frame loading shell while a
        // detail popup is mounting. Do not enqueue or activate a tab until
        // the same rendered challenge survives the stability window.
        await locateHumanVerificationAcrossPages(page, system, stage, {
          requireStable: true,
          stableDelayMs: 300,
        }),
      ),
    });
    if (!focus.acquired) {
      if (focus.status === 'timeout') {
        const located = await locateHumanVerificationAcrossPages(page, system, stage);
        const closeResult = located
          ? await closeHumanVerificationSurface(located.page, located.detection)
          : { closed: false, reason: 'verification-page-not-found' };
        if (!closeResult.closed) {
          writeVerificationTimeoutRelease({
            system,
            stage,
            page: located?.page || page,
            location: readProgress().verificationLocation,
            detection: located?.detection || null,
            closeResult,
          });
          return false;
        }
        const timedOutAt = new Date().toISOString();
        const current = readProgress();
        writeProgress({
          step: 'verification-timeout-closed',
          verificationStage: null,
          verificationLocation: null,
          verificationFocus: null,
          verificationTimeout: {
            status: 'closed',
            stage,
            system,
            timeoutMs: humanVerificationMaxTimeoutMs,
            verificationId: current.verificationLocation?.id || located?.detection?.id || null,
            fingerprint: located
              ? verificationSurfaceFingerprint({
                system,
                page: located.page,
                detection: located.detection,
                pageRole: located.pageRole,
              })
              : null,
            detectedAt: current.verificationLocation?.detectedAt || null,
            timedOutAt,
            suppressUntil: new Date(
              Date.parse(timedOutAt) + humanVerificationPostTimeoutSuppressionMs,
            ).toISOString(),
            closeResult,
            externalActionsReplayed: false,
          },
          verificationRecheck: {
            ...(current.verificationRecheck || {}),
            trigger: 'resident-verification-timeout-close',
            status: 'closed',
            requestedAt: timedOutAt,
            completedAt: timedOutAt,
          },
          manualReview: null,
          error: null,
        });
        updateAuthHealth(system, 'unknown', located?.page || page, {
          stage: null,
          source: 'resident-verification-timeout-close',
          evidence: closeResult.closed ? 'challenge-page-closed' : 'challenge-close-unavailable',
        });
        console.warn(`[驻留验证码超时] ${shopId} 已等待 ${humanVerificationMaxTimeoutMs / 1000} 秒，${closeResult.closed ? '已关闭验证码页面' : '未找到可关闭控件'}，释放店铺队列。`);
      }
      return false;
    }
    try {
      let activePage = page;
      let lastFocusedResidentPage = null;
      let residentPageMissingSince = null;
      while (!workflowStopping && !browserFailureExiting && browser.isConnected()) {
        if (deadline !== null && Date.now() >= deadline) {
          const located = await locateHumanVerificationAcrossPages(activePage, system, stage);
          const closeResult = located
            ? await closeHumanVerificationSurface(located.page, located.detection)
            : { closed: false, reason: 'verification-page-not-found' };
          if (!closeResult.closed) {
            writeVerificationTimeoutRelease({
              system,
              stage,
              page: located?.page || activePage,
              location: readProgress().verificationLocation,
              detection: located?.detection || null,
              closeResult,
            });
            return false;
          }
          const timedOutAt = new Date().toISOString();
          const current = readProgress();
          writeProgress({
            step: 'verification-timeout-closed',
            verificationStage: null,
            verificationLocation: null,
            verificationFocus: null,
            verificationTimeout: {
              status: 'closed',
              stage,
              system,
              timeoutMs: humanVerificationMaxTimeoutMs,
              verificationId: current.verificationLocation?.id || located?.detection?.id || null,
              fingerprint: located
                ? verificationSurfaceFingerprint({
                  system,
                  page: located.page,
                  detection: located.detection,
                  pageRole: located.pageRole,
                })
                : null,
              detectedAt: current.verificationLocation?.detectedAt || null,
              timedOutAt,
              suppressUntil: new Date(
                Date.parse(timedOutAt) + humanVerificationPostTimeoutSuppressionMs,
              ).toISOString(),
              closeResult,
              externalActionsReplayed: false,
            },
            verificationRecheck: {
              ...(current.verificationRecheck || {}),
              trigger: 'resident-verification-timeout-close',
              status: 'closed',
              requestedAt: timedOutAt,
              completedAt: timedOutAt,
            },
            manualReview: null,
            error: null,
          });
          updateAuthHealth(system, 'unknown', located?.page || activePage, {
            stage: null,
            source: 'resident-verification-timeout-close',
            evidence: closeResult.closed ? 'challenge-page-closed' : 'challenge-close-unavailable',
          });
          console.warn(`[驻留验证码超时] ${shopId} 已等待 ${humanVerificationMaxTimeoutMs / 1000} 秒，${closeResult.closed ? '已关闭验证码页面' : '未找到可关闭控件'}，释放店铺队列。`);
          return false;
        }
        // The resident observer runs while PDD is mounting and tearing down
        // detail dialogs. Keep the current challenge tab authoritative while
        // its iframe is redrawing; otherwise a transient detector miss can
        // steal focus from the operator's in-progress drag.
        let located = null;
        if (lastFocusedResidentPage
          && activePage === lastFocusedResidentPage
          && !activePage.isClosed()) {
          const samePageDetection = await detectHumanVerification(activePage).catch(() => null);
          if (samePageDetection) {
            residentPageMissingSince = null;
            located = {
              page: activePage,
              detection: samePageDetection,
              pageRole: verificationPageRole(activePage),
            };
          } else {
            residentPageMissingSince ||= Date.now();
            if (Date.now() - residentPageMissingSince < verificationPageRebindGraceMs) {
              await new Promise((resolve) => setTimeout(resolve, humanVerificationFocusKeepAliveMs));
              continue;
            }
          }
        }
        if (!located) {
          located = await locateHumanVerificationAcrossPages(
            activePage,
            system,
            stage,
            { requireStable: true, stableDelayMs: 300 },
          );
        }
        if (!located) return true;
        residentPageMissingSince = null;
        activePage = located.page;
        // Inspect actual tab selection, not temporary document visibility.
        // A selected CAPTCHA tab is not reactivated during a click or drag.
        const activation = await activateVerificationPage(activePage, { backgroundOnly: true });
        if (activation?.selected) {
          lastFocusedResidentPage = activePage;
        }
        const current = readProgress();
        if (current.verificationLocation?.system === system
          && current.verificationLocation?.url === activePage.url()) {
          writeProgress({
            step: 'human-verification-required',
            currentUrl: activePage.url(),
            verificationFocus: {
              ...(current.verificationFocus || {}),
              status: 'active',
              stage: current.verificationStage || stage,
              ownerShopId: shopId,
              pageRole: verificationPageRole(activePage),
              tabSelected: activePage === lastFocusedResidentPage,
              selectionMethod: activePage === lastFocusedResidentPage ? 'chrome-tabs-update' : null,
              activatedAt: new Date().toISOString(),
            },
            error: null,
          });
        }
        await new Promise((resolve) => setTimeout(resolve, humanVerificationFocusKeepAliveMs));
      }
      return false;
    } finally {
      verificationFocusCoordinator.release();
    }
  })();
  const wrappedTask = task.finally(() => {
    if (residentVerificationFocusPromise === wrappedTask) residentVerificationFocusPromise = null;
  });
  residentVerificationFocusPromise = wrappedTask;
  return residentVerificationFocusPromise;
};

// Manual PDD QR login keeps one focus lock for the whole login so the
// operator does not see the browser jump between shops. A security challenge
// can nevertheless be opened in a derived PDD tab; temporarily expose that
// exact tab to the extension, then return to the original login tab.
const locatePddLoginVerificationInOtherPages = async (
  loginPage,
  stage,
  { preferredPage = null, requireStable = false, stableDelayMs = 250 } = {},
) => {
  const candidates = pagesForVerificationScan(loginPage, 'pdd', stage);
  if (preferredPage && candidates.includes(preferredPage)) {
    candidates.splice(candidates.indexOf(preferredPage), 1);
    candidates.unshift(preferredPage);
  }
  for (const page of candidates) {
    if (page === loginPage) continue;
    const detection = await detectHumanVerification(page).catch(() => null);
    if (!detection) continue;
    if (requireStable) {
      await new Promise((resolve) => setTimeout(resolve, Math.max(50, stableDelayMs)));
      if (page.isClosed()) continue;
      const confirmation = await detectHumanVerification(page).catch(() => null);
      if (!confirmation) continue;
    }
    pddLoginVerificationOrigins.set(page, { page: loginPage, url: page.url() });
    return {
      page,
      detection,
      pageRole: verificationPageRole(page),
    };
  }
  return null;
};

const waitForPddLoginVerificationInOtherPage = async (loginPage, stage) => {
  let located = await locatePddLoginVerificationInOtherPages(loginPage, stage, {
    requireStable: true,
  });
  if (!located) return false;

  let verificationPage = located.page;
  const originUrl = loginPage.isClosed() ? null : loginPage.url();
  const originPageRole = verificationPageRole(loginPage);
  const diagnostics = await saveWorkflowDiagnostics(
    verificationPage,
    `human-verification-${stage}-cross-tab`,
  );
  let verificationLocation = await locateHumanVerification(
    verificationPage,
    'pdd',
    stage,
    diagnostics,
    located.detection,
    {
      source: 'cross-tab-login-scan',
      pageRole: located.pageRole,
      originUrl,
      originPageRole,
    },
  );
  writeProgress({
    step: 'human-verification-required',
    verificationStage: stage,
    currentUrl: verificationPage.url(),
    verificationLocation,
    verificationFocus: {
      status: 'active',
      stage,
      ownerShopId: shopId,
      workClass: 'pdd-manual-login-cross-tab',
      pageRole: located.pageRole,
      activatedAt: new Date().toISOString(),
    },
    error: null,
  });
  const initialActivation = await activateVerificationPage(verificationPage, { force: true });
  let lastFocusedLoginPage = verificationPage;
  let verificationPageMissingSince = null;

  const waitResult = await waitForStableVerificationClear({
    page: verificationPage,
    hasVerification: async () => {
      const currentDetection = verificationPage && !verificationPage.isClosed()
        ? await detectHumanVerification(verificationPage).catch(() => null)
        : null;
      if (currentDetection) {
        verificationPageMissingSince = null;
        located = { page: verificationPage, detection: currentDetection };
        return true;
      }
      verificationPageMissingSince ||= Date.now();
      if (Date.now() - verificationPageMissingSince < humanVerificationAbsenceGraceMs) return true;
      located = await locatePddLoginVerificationInOtherPages(loginPage, stage, {
        preferredPage: verificationPage,
      });
      if (!located) return false;
      verificationPage = located.page;
      verificationPageMissingSince = null;
      const previousLocation = verificationLocation;
      verificationLocation = await locateHumanVerification(
        verificationPage,
        'pdd',
        stage,
        null,
        located.detection,
        {
          source: 'cross-tab-login-scan',
          pageRole: located.pageRole,
          originUrl,
          originPageRole,
        },
      );
      if (previousLocation?.id !== verificationLocation?.id
        || previousLocation?.url !== verificationLocation?.url) {
        writeProgress({
          step: 'human-verification-required',
          verificationStage: stage,
          currentUrl: verificationPage.url(),
          verificationLocation,
          error: null,
        });
      }
      return true;
    },
    resolvePage: async () => {
      located = await locatePddLoginVerificationInOtherPages(loginPage, stage, {
        preferredPage: verificationPage,
      });
      if (located) {
        verificationPage = located.page;
        return verificationPage;
      }
      return loginPage && !loginPage.isClosed() ? loginPage : null;
    },
    pollMs: humanVerificationPollMs,
    stableMs: humanVerificationClearStableMs,
    deadline: null, // Login CAPTCHA waits only for the operator.
    maintainFocus: async () => {
      located = await locatePddLoginVerificationInOtherPages(loginPage, stage, {
        preferredPage: verificationPage,
      });
      if (!located) return null;
      verificationPage = located.page;
      const pageChanged = verificationPage !== lastFocusedLoginPage;
      if (pageChanged) {
        const nextActivation = await activateVerificationPage(verificationPage, { force: true })
          .catch(() => null);
        if (nextActivation?.activated) {
          lastFocusedLoginPage = verificationPage;
        }
      }
      return verificationPage;
    },
    focusIntervalMs: humanVerificationFocusKeepAliveMs,
    // The exact challenge tab was selected above and navigation is paused.
    shouldYieldFocus: () => false,
  });
  if (waitResult.status !== 'cleared') {
    throw new HumanVerificationRequiredError(
      stage,
      verificationPage.isClosed() ? originUrl : verificationPage.url(),
    );
  }

  writeProgress({
    step: 'manual-login-required',
    verificationStage: 'pinduoduo-login',
    currentUrl: loginPage.isClosed() ? null : loginPage.url(),
    verificationLocation: null,
    verificationFocus: {
      status: 'active',
      stage,
      ownerShopId: shopId,
      workClass: 'pdd-manual-login',
      restoredPageRole: originPageRole,
      restoredAt: new Date().toISOString(),
    },
    verificationRecheck: {
      trigger: 'cross-tab-login-verification',
      status: 'cleared',
      completedAt: new Date().toISOString(),
    },
    error: null,
  });
  if (!loginPage.isClosed()) await activateVerificationPage(loginPage, { force: true });
  return true;
};

const waitForPddPostLoginStability = async (targetPage, stage) => {
  if (!targetPage || targetPage.isClosed()) {
    throw new Error(`PDD 登录完成后的稳定等待页面已关闭: ${stage}`);
  }
  pddPostLoginStabilityWaits += 1;
  try {
    return await waitForPddPostLoginBarrier(targetPage, stage, {
      force: true,
      source: 'explicit-login-exit',
    });
  } finally {
    pddPostLoginStabilityWaits -= 1;
  }
};

const waitForPddManualLoginExit = async (initialPage, isLoginUrl, stage) => {
  let targetPage = initialPage;
  const loginSystem = 'pdd';
  const adoptUsableBusinessTab = async () => {
    const candidate = selectLivePddPage(context.pages(), pddPage);
    if (!await pddBusinessPageMatchesExpectedMall(candidate)) return false;
    await adoptLivePddAnchor();
    targetPage = pddPage;
    return true;
  };
  if (await adoptUsableBusinessTab()) {
    return waitForPddPostLoginStability(targetPage, stage);
  }
  targetPage = await resolveSystemLoginPage(targetPage, loginSystem, isLoginUrl, stage);
  const focus = await verificationFocusCoordinator.acquire({
    stage,
    priority: -10,
    isStillRequired: async () => {
      if (targetPage && !targetPage.isClosed() && isLoginUrl(targetPage.url())) return true;
      return Boolean(await locateSystemLoginAcrossPages(
        targetPage,
        loginSystem,
        isLoginUrl,
        stage,
      ));
    },
    onWaiting: async ({ owner, waitingSince }) => {
      writeProgress({
        step: 'manual-login-required',
        verificationStage: 'pinduoduo-login',
        verificationFocus: {
          status: 'waiting',
          stage,
          waitingSince,
          ownerShopId: owner?.shopId || null,
          ownerStage: owner?.stage || null,
          priority: -10,
          workClass: 'pdd-manual-login',
        },
        error: null,
      });
    },
  });

  if (!focus.acquired) {
    // The focus lock may observe the login disappearing while another local
    // login waiter still owns the lock. That path must receive the same full
    // post-login barrier before it returns to the workflow.
    if (isPddBusinessPageForBarrier(targetPage)) {
      await waitForPddPostLoginBarrier(targetPage, stage, {
        force: true,
        source: 'manual-login-focus-queue-exit',
      });
    }
    return targetPage;
  }
  // A manual login must remain available for the operator, but it must not
  // monopolize this shop's verification selection forever. Once the normal
  // two-minute human-action budget has elapsed and another shop is waiting,
  // release only the focus lock; keep polling this exact login tab in place.
  // This lets the next shop present its CAPTCHA without closing or recreating
  // the current login surface.
  let focusYielded = false;
  const focusLeaseStartedAt = Date.now();
  let lastFocusedLoginPage = null;
  const yieldFocusForWaitingShops = (reason = 'manual-login-focus-lease-expired') => {
    if (focusYielded) return false;
    focusYielded = true;
    verificationFocusCoordinator.release();
    const releasedAt = new Date().toISOString();
    const current = readProgress();
    writeProgress({
      step: 'manual-login-required',
      verificationFocus: {
        ...(current.verificationFocus || {}),
        status: 'released-timeout',
        stage,
        ownerShopId: shopId,
        workClass: 'pdd-manual-login',
        releaseReason: reason,
        releasedAt,
      },
      error: null,
    });
    console.warn(`[PDD 登录焦点租约] ${shopId} 已等待 ${humanVerificationMaxTimeoutMs / 1000} 秒且存在其它等待店铺，释放焦点锁并保留登录页。`);
    return true;
  };
  pddManualLoginWaits += 1;
  try {
    const activation = await activateVerificationPage(targetPage, { force: true });
    lastFocusedLoginPage = targetPage;
    writeProgress({
      step: 'manual-login-required',
      verificationStage: 'pinduoduo-login',
      verificationFocus: {
        status: 'active',
        stage,
        ownerShopId: shopId,
        priority: -10,
        workClass: 'pdd-manual-login',
        pageVisibilityState: activation?.visibilityState || null,
        acquiredAt: focus.owner?.acquiredAt || new Date().toISOString(),
        activatedAt: new Date().toISOString(),
      },
      error: null,
    });

    while (true) {
      if (await adoptUsableBusinessTab()) break;
      if (!focusYielded
        && Date.now() - focusLeaseStartedAt >= humanVerificationMaxTimeoutMs
        && verificationFocusCoordinator.hasWaiters()) {
        yieldFocusForWaitingShops();
      }
      if (targetPage && !targetPage.isClosed() && !isLoginUrl(targetPage.url())) {
        break;
      }
      const located = await locateSystemLoginAcrossPages(targetPage, loginSystem, isLoginUrl, stage);
      if (located?.page && located.page !== targetPage) {
        targetPage = located.page;
        if (!focusYielded) await activateVerificationPage(targetPage, { force: true }).catch(() => {});
        updateAuthHealth('pdd', 'expired', targetPage, {
          stage,
          source: 'cross-tab-login-scan',
          evidence: 'rendered-login-page',
          confidence: 'confirmed',
        });
        writeProgress({
          step: 'manual-login-required',
          verificationStage: 'pinduoduo-login',
          currentUrl: located.url,
          error: null,
        });
        // Both login tabs remain available; the operator chooses which to use.
      }
      if (!targetPage || targetPage.isClosed()) {
        throw new Error(`PDD 登录标签页已关闭: ${stage}`);
      }
      if (!isLoginUrl(targetPage.url())) break;
      const detectedSamePageLoginVerification = await detectHumanVerification(targetPage).catch(() => null);
      const samePageLoginVerification = detectedSamePageLoginVerification
        && !verificationTimeoutSuppressesSurface(readProgress(), {
          system: 'pdd',
          page: targetPage,
          detection: detectedSamePageLoginVerification,
          pageRole: verificationPageRole(targetPage),
        })
        ? detectedSamePageLoginVerification
        : null;
      if (samePageLoginVerification) {
        const timeoutState = readProgress().verificationTimeout;
        const currentFingerprint = verificationSurfaceFingerprint({
          system: 'pdd',
          page: targetPage,
          detection: samePageLoginVerification,
          pageRole: verificationPageRole(targetPage),
        });
        const surfaceExpiry = await verificationSurfaceHasExpired(targetPage);
        if (timeoutState?.status === 'waiting'
          && timeoutState.fingerprint === currentFingerprint
          && !surfaceExpiry.expired) {
          // The plugin still owns this live challenge after the scheduler
          // budget. Keep the login tab in place without reusing the old
          // deadline on every observer tick.
          await targetPage.waitForTimeout(Math.max(1_000, humanVerificationPollMs));
          continue;
        }
        const verificationWait = await waitForStableVerificationClear({
          page: targetPage,
          hasVerification: async (activePage) => {
            const detection = await detectHumanVerification(activePage).catch(() => null);
            return Boolean(detection && !verificationTimeoutSuppressesSurface(readProgress(), {
              system: 'pdd',
              page: activePage,
              detection,
              pageRole: verificationPageRole(activePage),
            }));
          },
          resolvePage: async () => {
            await adoptUsableBusinessTab();
            return targetPage && !targetPage.isClosed() ? targetPage : null;
          },
          pollMs: humanVerificationPollMs,
          stableMs: humanVerificationClearStableMs,
          deadline: null, // Expired login challenges remain available for manual retry.
          maintainFocus: async () => {
            if (focusYielded) return targetPage;
            const pageChanged = targetPage !== lastFocusedLoginPage;
            if (pageChanged) {
              const nextActivation = await activateVerificationPage(targetPage, { force: true })
                .catch(() => null);
              if (nextActivation?.activated) {
                lastFocusedLoginPage = targetPage;
              }
            }
            return targetPage;
          },
          focusIntervalMs: humanVerificationFocusKeepAliveMs,
          focusQuantumMs: humanVerificationMaxTimeoutMs,
          shouldYieldFocus: () => verificationFocusCoordinator.hasWaiters(),
        });
        if (verificationWait.status === 'yielded') {
          yieldFocusForWaitingShops('manual-login-verification-focus-lease-expired');
        }
        continue;
      }
      if (!focusYielded) {
        await waitForPddLoginVerificationInOtherPage(targetPage, stage);
        const pageChanged = targetPage !== lastFocusedLoginPage;
        if (pageChanged) {
          const nextActivation = await activateVerificationPage(targetPage, { force: true })
            .catch(() => null);
          if (nextActivation?.activated) {
            lastFocusedLoginPage = targetPage;
          }
        }
      }
      await targetPage.waitForTimeout(actionDelayFor(targetPage, stage));
    }
    return await waitForPddPostLoginStability(targetPage, stage);
  } finally {
    pddManualLoginWaits -= 1;
    verificationFocusCoordinator.release();
    writeProgress({
      verificationFocus: null,
      verificationStage: null,
      error: null,
    });
  }
};

const waitForLoginExit = async (targetPage, isLoginUrl, stage, { timeoutMs = null } = {}) => {
  // Automatic OMS/TMS login must fail fast so the bounded retry loop can
  // refresh the page. Manual PDD/verification waits remain unbounded in a
  // headed browser unless the caller supplies a timeout.
  const deadline = timeoutMs != null
    ? Date.now() + timeoutMs
    : (browserKeepsAlive ? null : Date.now() + 300000);
  let observedPage = targetPage;
  const loginSystem = ['pdd', 'oms', 'tms']
    .find((system) => isSystemLoginUrl(system, observedPage?.url?.() || ''))
    || loginSystemForStage(stage);
  if (loginSystem) {
    observedPage = await resolveSystemLoginPage(
      observedPage,
      loginSystem,
      isLoginUrl,
      stage,
    );
  }
  // PDD QR login has its own long-lived focus lock because the login page is
  // also detected as a security surface. Do not acquire the generic lock
  // before delegating or the same process would queue behind itself.
  if (loginSystem === 'pdd' && stage === 'pdd-manual-login') {
    return waitForPddManualLoginExit(observedPage, isLoginUrl, stage);
  }
  const manualLoginWait = /(?:^|-)manual-login(?:-|$)|login-captcha|login-phone|pinduoduo-login/u.test(stage);
  const focus = manualLoginWait
    ? await verificationFocusCoordinator.acquire({
      stage,
      priority: -10,
      isStillRequired: async () => {
        if (observedPage && !observedPage.isClosed() && isLoginUrl(observedPage.url())) return true;
        return Boolean(loginSystem && await locateSystemLoginAcrossPages(
          observedPage,
          loginSystem,
          isLoginUrl,
          stage,
        ));
      },
      onWaiting: async ({ owner, waitingSince }) => {
        writeProgress({
          step: 'manual-login-required',
          verificationStage: `${loginSystem || 'system'}-login`,
          verificationFocus: {
            status: 'waiting',
            stage,
            waitingSince,
            ownerShopId: owner?.shopId || null,
            ownerStage: owner?.stage || null,
            priority: -10,
            workClass: 'system-manual-login',
          },
          error: null,
        });
      },
  })
    : null;
  if (manualLoginWait && !focus?.acquired) {
    if (loginSystem === 'pdd') await waitForPddPostLoginStability(observedPage, stage);
    return observedPage;
  }
  if (manualLoginWait && focus?.acquired) {
    await activateVerificationPage(observedPage, { force: true }).catch(() => {});
  }
  try {
    while (true) {
    if (observedPage && !observedPage.isClosed() && !isLoginUrl(observedPage.url())) {
      await closeStaleSystemLoginPages(observedPage, loginSystem, isLoginUrl, stage);
      break;
    }
    if (loginSystem) {
      const located = await locateSystemLoginAcrossPages(observedPage, loginSystem, isLoginUrl, stage);
      if (located?.page && located.page !== observedPage) {
        const previousPage = observedPage;
        observedPage = located.page;
        // Login is an operator-action surface. Bring the exact tab forward so
        // the user does not have to hunt through rapidly changing tabs.
        if (manualLoginWait) {
          await activateVerificationPage(observedPage, { force: true }).catch(() => {});
        }
        updateAuthHealth(loginSystem, 'expired', observedPage, {
          stage,
          source: 'cross-tab-login-scan',
          evidence: 'rendered-login-page',
          confidence: 'confirmed',
        });
        writeProgress({
          step: 'manual-login-required',
          verificationStage: `${loginSystem}-login`,
          currentUrl: located.url,
          systemLogin: {
            system: loginSystem,
            status: 'waiting-human',
            updatedAt: new Date().toISOString(),
          },
          error: null,
        });
        if (previousPage && previousPage !== observedPage) await closeDerivedPage(previousPage).catch(() => {});
      }
    }
    if (!observedPage || observedPage.isClosed()) {
      const replacement = loginSystem
        ? await locateSystemLoginAcrossPages(null, loginSystem, isLoginUrl, stage)
        : null;
      if (replacement?.page) {
        observedPage = replacement.page;
        await maybeBringToFront(observedPage, {
          manual: manualLoginWait,
          force: manualLoginWait,
        }).catch(() => {});
      } else {
        throw new Error(`${loginSystem ? loginSystem.toUpperCase() : '系统'} 登录标签页已关闭: ${stage}`);
      }
    }
    if (!isLoginUrl(observedPage.url())) {
      await closeStaleSystemLoginPages(observedPage, loginSystem, isLoginUrl, stage);
      break;
    }
    // Manual login stages already own this shop's lock. Running the
    // verification detector here would try to acquire the same lock again
    // (notably for OMS/TMS captcha pages) and deadlock this worker.
    if (!manualLoginWait) {
      await checkForHumanVerification(observedPage, stage);
      if (!isLoginUrl(observedPage.url())) break;
    }
    if (stage.startsWith('pdd-') || stage === 'pinduoduo-login') {
      await refreshExpiredPddQr(observedPage).catch((error) => {
        console.warn(`[PDD 登录] 刷新失效二维码失败，将继续等待人工操作: ${error.message}`);
      });
    }
    if (deadline && Date.now() >= deadline) {
      throw new Error(`${stage} 登录等待超过 ${Math.ceil((timeoutMs || 300000) / 60000)} 分钟`);
    }
    await observedPage.waitForTimeout(actionDelayFor(observedPage, stage));
    }
    if (loginSystem === 'pdd') {
      observedPage = await waitForPddPostLoginStability(observedPage, stage);
    }
    return observedPage;
  } finally {
    if (focus?.acquired) verificationFocusCoordinator.release();
  }
};

const isRateLimited = (targetPage) => anyVisibleText(targetPage, [
  /操作太过频繁[，,！!\s]*请稍后再试/,
]);

const pacedAction = async (targetPage, stage, action, { retryOnRateLimit = false } = {}) => {
  let attempt = 0;
  while (true) {
    attempt += 1;
    if (workflowSystemForAction(targetPage, stage) === 'pdd') {
      await waitForPddPostLoginBarrier(targetPage, stage, {
        source: 'paced-action',
      });
    }
    await checkForHumanVerification(targetPage, stage);
    await waitForPddPostLoginBarrier(targetPage, stage);
    try {
      await action();
    } catch (error) {
      const verificationHandled = await checkForHumanVerification(targetPage, `${stage}-action-error`);
      if (!verificationHandled) throw error;
    }
    const settleDelayMs = actionDelayFor(targetPage, stage);
    if (settleDelayMs > 0) await targetPage.waitForTimeout(settleDelayMs);
    await checkForHumanVerification(targetPage, stage);

    if (!await isRateLimited(targetPage)) {
      if (attempt > 1) {
        writeProgress({
          step: 'rate-limit-recovered',
          rateLimitStage: null,
          rateLimitAttempt: null,
          rateLimitWaitMs: null,
          retryAfterAt: null,
          error: null,
        });
        console.warn(`[平台限流恢复] ${stage} 已恢复正常，继续当前流程。`);
      }
      return;
    }

    await maybeBringToFront(targetPage).catch(() => {});
    const currentWaitMs = Math.min(
      rateLimitWaitMs * (2 ** Math.min(attempt - 1, 8)),
      rateLimitMaxWaitMs,
    );
    const retryAfterAt = new Date(Date.now() + currentWaitMs).toISOString();
    writeProgress({
      step: retryOnRateLimit ? 'rate-limited-waiting' : 'rate-limited',
      rateLimitStage: stage,
      rateLimitAttempt: attempt,
      rateLimitWaitMs: currentWaitMs,
      currentUrl: targetPage.url(),
      retryAfterAt: retryOnRateLimit ? retryAfterAt : null,
      error: null,
    });
    if (!retryOnRateLimit) {
      await saveWorkflowDiagnostics(targetPage, `rate-limited-${stage}`);
      throw new RateLimitPauseError(stage, targetPage.url());
    }

    if (attempt === 1) await saveWorkflowDiagnostics(targetPage, `rate-limited-${stage}`);
    console.warn(`[平台限流] ${stage} 出现“操作太过频繁”，暂停操作至 ${retryAfterAt} 后自动重试。`);
    await targetPage.waitForTimeout(currentWaitMs);
    await checkForHumanVerification(targetPage, `${stage}-retry`);
  }
};

const firstVisible = async (candidates) => {
  for (const candidate of candidates) {
    const count = await candidate.count().catch(() => 0);
    for (let index = 0; index < count; index++) {
      const element = candidate.nth(index);
      if (await element.isVisible().catch(() => false)) return element;
    }
  }
  return null;
};

// PDD's QR code expires while the headed worker is waiting for an operator.
// Refresh the QR in-place instead of rebuilding the profile or browser. The
// cooldown prevents a stale expiry label from causing a click on every poll.
const pddQrRefreshState = new WeakMap();
const refreshExpiredPddQr = async (targetPage) => {
  // QR expiry, a blank panel and resource errors are also operator-controlled.
  if (isManualPddLoginSurface(targetPage)) return false;
  if (!targetPage.url().includes('mms.pinduoduo.com')) return false;
  const qrState = await targetPage.evaluate(() => {
    const visible = (element) => {
      const rect = element.getBoundingClientRect();
      const style = window.getComputedStyle(element);
      return rect.width > 0
        && rect.height > 0
        && rect.right > 0
        && rect.bottom > 0
        && rect.left < (document.documentElement.clientWidth || window.innerWidth)
        && rect.top < (document.documentElement.clientHeight || window.innerHeight)
        && style.display !== 'none'
        && style.visibility !== 'hidden'
        && Number(style.opacity || 1) > 0;
    };
    const bodyText = String(document.body?.innerText || '').replace(/\s+/gu, ' ');
    const prompt = [...document.querySelectorAll('*')]
      .filter((element) => visible(element)
        && /打开.*拼多多商家版App.*扫码登录/u.test(
          String(element.innerText || element.textContent || '').replace(/\s+/gu, ' '),
        ))
      .sort((left, right) => String(left.innerText || left.textContent || '').length
        - String(right.innerText || right.textContent || '').length)[0];
    let panel = prompt || null;
    for (let depth = 0; panel && depth < 8; depth += 1, panel = panel.parentElement) {
      if (panel === document.body || panel === document.documentElement) break;
      const rect = panel.getBoundingClientRect();
      if (visible(panel) && rect.width >= 180 && rect.width <= 520
        && rect.height >= 180 && rect.height <= 700) break;
    }
    const candidates = panel ? [...panel.querySelectorAll([
      'img',
      'canvas',
      'svg',
      '[class*="qrcode" i]',
      '[class*="qr-code" i]',
      '[data-testid*="qrcode" i]',
    ].join(','))] : [];
    const qrReady = candidates.some((element) => {
      if (!visible(element)) return false;
      const rect = element.getBoundingClientRect();
      if (rect.width < 80 || rect.height < 80 || rect.width > 320 || rect.height > 320) return false;
      if (Math.abs(rect.width - rect.height) > Math.max(rect.width, rect.height) * 0.25) return false;
      if (String(element.tagName || '').toLowerCase() === 'img') {
        return element.complete && element.naturalWidth >= 80 && element.naturalHeight >= 80;
      }
      return true;
    });
    return {
      bodyText,
      qrReady,
      promptVisible: Boolean(prompt),
      resourceFailure: /验证资源获取失败\s*[,，]\s*请重试/u.test(bodyText),
    };
  }).catch(() => ({
    bodyText: '',
    qrReady: false,
    promptVisible: false,
    resourceFailure: false,
  }));
  const expiredQrPattern = /二维码(?:已)?(?:失效|过期)/;
  const expired = expiredQrPattern.test(qrState.bodyText);
  const previous = pddQrRefreshState.get(targetPage) || {
    lastAttemptAt: 0,
    attempts: 0,
    blankSince: null,
  };
  if (qrState.qrReady && !expired && !qrState.resourceFailure) {
    pddQrRefreshState.delete(targetPage);
    return false;
  }
  const now = Date.now();
  if (qrState.resourceFailure && previous.attempts >= 1) {
    pddQrRefreshState.set(targetPage, { ...previous, blankSince: previous.blankSince || now });
    return false;
  }
  const blankSince = !qrState.qrReady && qrState.promptVisible
    ? (previous.blankSince || now)
    : null;
  const blankPersisted = blankSince != null && now - blankSince >= 3_000;
  if (!expired && !qrState.resourceFailure && !blankPersisted) {
    pddQrRefreshState.set(targetPage, { ...previous, blankSince });
    return false;
  }

  // A slider or security challenge invalidates the login attempt independently
  // of the QR lifetime. Never replace the QR while the operator is solving it.
  const liveDetection = await detectHumanVerification(targetPage).catch(() => null);
  if (liveDetection && !isVerificationResourceFailureDetection(liveDetection)) return false;

  if (now - previous.lastAttemptAt < 8_000) {
    pddQrRefreshState.set(targetPage, { ...previous, blankSince });
    return false;
  }

  const qrFingerprint = await targetPage.locator('img').evaluateAll((images) => images
    .map((image) => image.currentSrc || image.src || image.getAttribute('data-src') || '')
    .filter(Boolean)
    .join('|')).catch(() => '');
  let recoveryMethod = 'login-page-reload';
  if (expired && !qrState.resourceFailure) {
    await maybeBringToFront(targetPage).catch(() => {});
    if (await clickVisiblePddQrRefreshControl(targetPage)) recoveryMethod = 'expired-qr-refresh-control';
  }
  pddQrRefreshState.set(targetPage, {
    lastAttemptAt: now,
    attempts: previous.attempts + 1,
    blankSince,
  });
  await targetPage.waitForTimeout(1800);
  let refreshedText = await targetPage.locator('body').innerText().catch(() => '');
  let refreshedFingerprint = await targetPage.locator('img').evaluateAll((images) => images
    .map((image) => image.currentSrc || image.src || image.getAttribute('data-src') || '')
    .filter(Boolean)
    .join('|')).catch(() => '');

  // Some PDD builds render the refresh label as a React overlay whose click
  // handler only updates after a full login-page navigation. If the QR image
  // and expiry label are unchanged, reload this login page once in-place.
  if (recoveryMethod === 'login-page-reload'
    || expiredQrPattern.test(refreshedText)
    || qrFingerprint === refreshedFingerprint) {
    const loginRefreshUrl = new URL(targetPage.url());
    loginRefreshUrl.searchParams.set('codexQrRefresh', String(now));
    await navigateSystemPage(targetPage, loginRefreshUrl.toString(), 'pdd-login-qr-refresh')
      .catch(() => {});
    await targetPage.waitForTimeout(1800);
    refreshedText = await targetPage.locator('body').innerText().catch(() => '');
    refreshedFingerprint = await targetPage.locator('img').evaluateAll((images) => images
      .map((image) => image.currentSrc || image.src || image.getAttribute('data-src') || '')
      .filter(Boolean)
      .join('|')).catch(() => '');
  }
  if (!expiredQrPattern.test(refreshedText)
    || qrFingerprint !== refreshedFingerprint) {
    pddQrRefreshState.set(targetPage, {
      lastAttemptAt: now,
      attempts: previous.attempts + 1,
      blankSince: null,
    });
  }
  const trigger = qrState.resourceFailure
    ? '二维码资源获取失败'
    : expired ? '二维码失效' : '二维码区域持续空白';
  writeProgress({
    pddLoginQrRecovery: {
      status: 'reloaded',
      trigger,
      method: recoveryMethod,
      attempt: previous.attempts + 1,
      refreshedAt: new Date().toISOString(),
      url: targetPage.url(),
    },
    error: null,
  });
  console.log(`[PDD 登录] 检测到${trigger}，已在当前登录标签重新获取二维码: ${targetPage.url()}`);
  return true;
};

const ensurePddLogin = async (targetPage, browserContext, targetUrl = listUrl) => {
  if (targetPage === pddPage) targetPage = await adoptLivePddAnchor();
  const targetAlreadyAuthenticated = isAuthenticatedSystemUrl('pdd', targetPage.url());
  if (targetAlreadyAuthenticated) {
    await waitForPddPostLoginBarrier(targetPage, 'ensure-pdd-login', {
      source: 'ensure-pdd-login-entry',
    });
  }
  const existingPddLogin = targetAlreadyAuthenticated
    ? null
    : await locateSystemLoginAcrossPages(
      targetPage,
      'pdd',
      (url) => url.includes('/login'),
      'pdd-login-recovery',
    );
  if (targetAlreadyAuthenticated) {
    await closeStaleSystemLoginPages(
      targetPage,
      'pdd',
      (url) => url.includes('/login'),
      'pdd-login-recovery',
    );
  }
  if (existingPddLogin?.page && existingPddLogin.page !== targetPage) {
    targetPage = existingPddLogin.page;
    console.log(`[PDD 登录] 已切换到实际登录标签页: ${existingPddLogin.url}`);
  }
  if (!targetPage.url().includes('mms.pinduoduo.com')) {
    await pacedAction(targetPage, 'open-pinduoduo', () => navigateSystemPage(targetPage, targetUrl, 'open-pinduoduo'));
  }
  await closeDeviceAccessIfPrompted(targetPage);
  if (targetPage.url().includes('/login')) {
    const pddAccount = pddLoginMode === 'auto' ? process.env.PDD_ACCOUNT : null;
    const pddPassword = pddLoginMode === 'auto' ? process.env.PDD_PASSWORD : null;
    if (!pddAccount || !pddPassword) {
      const loginRequired = recordPddLoginRequired(targetPage);
      await focusManualLoginPage(targetPage);
      await saveWorkflowDiagnostics(targetPage, 'manual-login-pinduoduo');
      if (browserHeadless) {
        throw loginRequired;
      }
      console.error('\n[需要人工登录] 拼多多登录状态已失效，请在当前浏览器完成登录。');
      targetPage = await waitForLoginExit(targetPage, (url) => url.includes('/login'), 'pdd-manual-login');
    } else {
      const tab = targetPage.getByText('账号登录', { exact: true });
      if (await tab.isVisible().catch(() => false)) {
        await pacedAction(targetPage, 'select-account-login', () => tab.click({ force: true }));
      }
      const accountInput = await firstVisible([
        targetPage.getByPlaceholder('请输入账号名/手机号', { exact: true }),
        targetPage.locator('input[placeholder*="账号名"], input[placeholder*="手机号"]'),
        targetPage.getByRole('textbox', { name: /账号名|手机号/ }),
      ]);
      const passwordInput = await firstVisible([
        targetPage.getByPlaceholder('请输入密码', { exact: true }),
        targetPage.locator('input[type="password"], input[placeholder*="密码"]'),
      ]);
      if (!accountInput || !passwordInput) throw new Error('拼多多账号登录页未找到账号或密码输入框');
      await pacedAction(targetPage, 'fill-account', () => accountInput.fill(pddAccount));
      await pacedAction(targetPage, 'fill-password', () => passwordInput.fill(pddPassword));
      await pacedAction(
        targetPage,
        'submit-login',
        () => targetPage.getByRole('button', { name: '登录' }).click(),
        { retryOnRateLimit: true },
      );
      const otp = targetPage.getByRole('textbox', { name: '请输入短信验证码' });
      if (await otp.isVisible().catch(() => false)) {
        await checkForHumanVerification(targetPage, 'sms-verification');
      }
      targetPage = await waitForLoginExit(targetPage, (url) => url.includes('/login'), 'pdd-login-result');
    }
  }
  if (targetPage.url() !== targetUrl) {
    await pacedAction(
      targetPage,
      'open-pinduoduo-target',
      () => navigateSystemPage(targetPage, targetUrl, 'open-pinduoduo-target'),
      { retryOnRateLimit: true },
    );
  }
  await closeDeviceAccessIfPrompted(targetPage);
  if (targetPage.url().includes('/login')) {
    throw recordPddLoginRequired(targetPage, {
      reason: '拼多多登录后仍返回登录页',
    });
  }
  const identityConfirmed = await capturePddShopIdentity(targetPage);
  if (!identityConfirmed && (activeAssignmentId || activeReturnRefundCommand)) {
    throw new Error('PDD_SHOP_IDENTITY_UNCONFIRMED: 当前店铺身份未核对，禁止执行工单或退款');
  }
  updateAuthHealth('pdd', 'authenticated', targetPage);
  await persistBrowserAuth(browserContext, { pddAuthenticated: true });
  persistSystemTabs('pdd');
  return targetPage;
};

const capturePddShopIdentity = async (targetPage) => {
  await waitForPddPostLoginBarrier(targetPage, 'pdd-shop-identity-capture', {
    source: 'identity-capture',
  });
  const { candidates, detected: headerDetected } = await collectRevealedPddShopIdentity(targetPage);
  const mallIdentity = await collectPddMallIdentity(targetPage);
  const expectedConfiguredIdentity = canonicalPddShopIdentityName(expectedShopName);
  const observedIdentityNames = pddIdentityNameSet(
    headerDetected?.name,
    mallIdentity?.mallName,
  );
  const headerMatchesConfiguredShop = Boolean(
    headerDetected
    && pddIdentityMatches(configuredPddIdentityNames, headerDetected.name),
  );
  const mallMatchesConfiguredShop = Boolean(
    mallIdentity?.mallName
    && pddIdentityMatches(configuredPddIdentityNames, mallIdentity.mallName),
  );
  // A revealed, exact configured-shop match is authoritative for PDD's
  // display variant. `new_userinfo.mall_name` may contain the parent merchant
  // name even when the active shop is shown in the smaller account label.
  const detected = headerMatchesConfiguredShop
    ? headerDetected
    : mallIdentity?.mallName && !isMaskedPddShopIdentityName(mallIdentity.mallName)
      ? { name: mallIdentity.mallName, source: mallIdentity.source }
      : headerDetected;
  const detectedMatchesConfiguredShop = Boolean(
    detected
    && pddIdentityMatches(configuredPddIdentityNames, detected.name),
  );
  const marker = exists(browserProfileMarker)
    ? JSON.parse(fs.readFileSync(browserProfileMarker, 'utf8'))
    : {};
  const checkedAt = new Date().toISOString();
  const diagnosticCandidates = candidates.slice(-80).map((candidate) => ({
    kind: candidate.kind,
    attribute: candidate.attribute || null,
    value: normalizePddShopNameCandidate(candidate.value).slice(0, 120),
    context: String(candidate.context || '').slice(0, 160),
  }));
  if (normalizePddMallId(expectedMallId)
    && mallIdentity?.mallId !== expectedMallId) {
    writeProgress({
      pddShopIdentity: {
        configured: expectedShopName || null,
        actualShopName: detected?.name || mallIdentity?.mallName || null,
        headerShopName: headerDetected?.name || null,
        mallId: mallIdentity?.mallId || null,
        mallName: mallIdentity?.mallName || null,
        expectedMallId,
        status: mallIdentity?.mallId ? 'mismatch' : 'unresolved',
        source: mallIdentity?.mallId
          ? 'confirmed-mall-id-conflict' : 'confirmed-mall-id-unavailable',
        profileFingerprint: marker.profileFingerprint || null,
        loginRequestedAt: loginRequestedAt || null,
        detectedAt: checkedAt,
        candidates: diagnosticCandidates,
      },
    });
    return false;
  }
  if (!headerMatchesConfiguredShop
    && !mallMatchesConfiguredShop
    && !detectedMatchesConfiguredShop
    && pddIdentitySourcesConflict(headerDetected?.name, mallIdentity?.mallName)) {
    writeProgress({
      pddShopIdentity: {
        configured: expectedShopName || null,
        actualShopName: headerDetected.name,
        headerShopName: headerDetected.name,
        mallId: mallIdentity.mallId,
        mallName: mallIdentity.mallName,
        status: 'identity-source-conflict',
        source: `${headerDetected.source}+${mallIdentity.source}`,
        profileFingerprint: marker.profileFingerprint || null,
        loginRequestedAt: loginRequestedAt || null,
        detectedAt: checkedAt,
        candidates: diagnosticCandidates,
      },
    });
    return false;
  }
  if (!detected) {
    writeProgress({
      pddShopIdentity: {
        configured: expectedShopName || null,
        actualShopName: null,
        headerShopName: headerDetected?.name || null,
        mallId: mallIdentity?.mallId || null,
        mallName: mallIdentity?.mallName || null,
        status: 'unresolved',
        profileFingerprint: marker.profileFingerprint || null,
        loginRequestedAt: loginRequestedAt || null,
        checkedAt,
        candidates: diagnosticCandidates,
      },
    });
    return true;
  }
  const configuredIdentity = canonicalPddShopIdentityName(expectedShopName);
  const detectedIdentity = canonicalPddShopIdentityName(detected.name);
  if (!dynamicPddShopBinding
    && configuredIdentity
    && !pddIdentityMatches(configuredPddIdentityNames, observedIdentityNames)
    && configuredIdentity !== detectedIdentity) {
    writeProgress({
      pddShopIdentity: {
        configured: expectedShopName,
        configuredNames: configuredPddIdentityNames,
        actualShopName: detected.name,
        headerShopName: headerDetected?.name || null,
        mallId: mallIdentity?.mallId || null,
        mallName: mallIdentity?.mallName || null,
        status: 'mismatch',
        source: detected.source,
        profileFingerprint: marker.profileFingerprint || null,
        loginRequestedAt: loginRequestedAt || null,
        detectedAt: checkedAt,
        candidates: diagnosticCandidates,
      },
    });
    return false;
  }
  const detectedShopNameMasked = isMaskedPddShopIdentityName(detected.name);
  const existingBindingShopName = marker.identityBinding?.status === 'confirmed'
    && identityBindingMatchesLoginRequest(marker.identityBinding)
    && !isMaskedPddShopIdentityName(marker.identityBinding.expectedShopName)
    ? marker.identityBinding.expectedShopName
    : null;
  const configuredBindingShopName = expectedShopName
    && !isMaskedPddShopIdentityName(expectedShopName)
    ? expectedShopName
    : null;
  const markerBindingShopName = detectedShopNameMasked
    ? existingBindingShopName || configuredBindingShopName
    : detected.name;
  const nextMarker = {
    ...marker,
    shopId,
    profileFingerprint: marker.profileFingerprint || crypto.randomUUID(),
    loginRequestedAt: loginRequestedAt || marker.loginRequestedAt || null,
    updatedAt: checkedAt,
  };
  if (!detectedShopNameMasked) {
    nextMarker.lastUnmaskedIdentityObservation = {
      actualShopName: detected.name,
      headerShopName: headerDetected?.name || null,
      mallId: mallIdentity?.mallId || null,
      mallName: mallIdentity?.mallName || null,
      source: detected.source,
      profileFingerprint: nextMarker.profileFingerprint,
      loginRequestedAt: loginRequestedAt || null,
      detectedAt: checkedAt,
    };
  }
  if (markerBindingShopName) {
    nextMarker.identityBinding = {
      shopId,
      expectedShopName: markerBindingShopName,
      mallId: mallIdentity?.mallId || null,
      loginRequestedAt: loginRequestedAt || null,
      status: 'confirmed',
      source: detectedShopNameMasked ? 'preserved-confirmed-binding' : detected.source,
      confirmedAt: detectedShopNameMasked
        ? marker.identityBinding?.confirmedAt || checkedAt
        : checkedAt,
    };
  } else if (detectedShopNameMasked) {
    delete nextMarker.identityBinding;
  }
  writeJsonAtomic(browserProfileMarker, nextMarker);
  writeProgress({
    pddShopIdentity: {
      configured: expectedShopName || null,
      actualShopName: detected.name,
      headerShopName: headerDetected?.name || null,
      mallId: mallIdentity?.mallId || null,
      mallName: mallIdentity?.mallName || null,
      status: 'detected',
      source: detected.source,
      profileFingerprint: nextMarker.profileFingerprint || null,
      loginRequestedAt: loginRequestedAt || null,
      detectedAt: checkedAt,
      candidates: diagnosticCandidates,
    },
  });
  return true;
};

function extractLabeledValue(text, label, { isValid = isValidOmsWarehouseValue } = {}) {
  const lines = String(text || '').split(/\r?\n/).map((line) => line.trim()).filter(Boolean);
  const labelIndex = lines.findIndex((line) => line === label || line.startsWith(`${label}：`)
    || line.startsWith(`${label}:`));
  if (labelIndex < 0) return null;
  const labelLine = lines[labelIndex];
  const escapedLabel = String(label).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const inline = labelLine.replace(new RegExp(`^${escapedLabel}\\s*[：:]?\\s*`), '').trim();
  if (isValid(inline)) return inline;
  for (let index = labelIndex + 1; index < lines.length; index++) {
    const candidate = lines[index];
    if (/^(?:发货时间|下单时间|订单时间|创建时间|物流信息|运单号|快递公司|收货信息|发货地址)/.test(candidate)) break;
    if (isValid(candidate)) return candidate;
  }
  return null;
}

function extractOmsWarehouseValue(text) {
  const source = String(text || '');
  for (const label of omsWarehouseLabels) {
    const inlineValue = (() => {
      const flattened = source.replace(/\s+/g, ' ').trim();
      const escapedLabel = String(label).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      const match = new RegExp(`(?:^|\\s)${escapedLabel}\\s*[：:]\\s*`, 'u').exec(flattened);
      if (!match) return null;
      const tail = flattened.slice(match.index + match[0].length);
      const nextField = /(?:^|\s)[\p{Script=Han}A-Za-z][\p{Script=Han}A-Za-z0-9_/（）()#-]{0,23}\s*[：:]\s*/u.exec(tail);
      const candidate = tail.slice(0, nextField?.index ?? tail.length).trim();
      return isValidOmsWarehouseValue(candidate) ? candidate : null;
    })();
    if (inlineValue) return inlineValue;
    const labeledValue = extractLabeledValue(source, label);
    if (labeledValue) return labeledValue;
  }
  const flattenedWarehouse = source.match(/(?:^|\s)(代发聚水潭-[^\s：:]{1,80})(?=\s|$)/u)?.[1] || null;
  if (isValidOmsWarehouseValue(flattenedWarehouse)) return flattenedWarehouse;
  const matched = omsWarehouseKeywords.find((keyword) => source.includes(keyword));
  if (matched) {
    const line = source.split(/\r?\n/).map((value) => value.trim())
      .find((value) => value.includes(matched));
    return line || matched;
  }
  const lines = source.split(/\r?\n/).map((value) => value.trim()).filter(Boolean);
  const warehouseHeaderIndex = lines.findIndex((value) => omsWarehouseLabels.includes(value));
  if (warehouseHeaderIndex < 0) return null;
  const searchEnd = Math.min(lines.length, warehouseHeaderIndex + 80);
  for (let index = warehouseHeaderIndex + 1; index < searchEnd; index++) {
    if (!/^\d{4}-\d{2}-\d{2}\s+\d{2}:\d{2}:\d{2}$/.test(lines[index])) continue;
    const candidate = lines[index - 1];
    if (isValidOmsWarehouseValue(candidate)) return candidate;
  }
  return null;
};

const readOmsWarehouseCandidates = async (scope) => {
  if (!scope) return [];
  return scope.evaluate((root) => {
    const candidates = [];
    const labels = [...root.querySelectorAll('*')].filter((element) => {
      const text = (element.innerText || '').replace(/\s+/g, '').trim();
      return ['发货仓库', '推荐仓库'].some((label) => (
        text === label || text.startsWith(`${label}：`) || text.startsWith(`${label}:`)
      ));
    });
    for (const label of labels) {
      const parent = label.closest('.el-form-item, .el-descriptions-item, tr, [role="row"], .ant-form-item')
        || label.parentElement;
      if (!parent) continue;
      const values = [
        ...[...parent.querySelectorAll('input, textarea')].map((field) => field.value || field.getAttribute('value') || ''),
        ...[...parent.querySelectorAll('.el-select__selected-item, .el-input__inner, td, dd, .value, [class*="value" i]')]
          .map((element) => element.innerText || ''),
        parent.innerText || '',
      ].map((value) => String(value).replace(/\s+/g, ' ').trim()).filter(Boolean);
      candidates.push(...values);
    }
    return candidates;
  }).catch(() => []);
}

const readOmsLowerShippingDetail = async (targetPage) => targetPage.evaluate(() => {
  const visible = (element) => {
    const style = getComputedStyle(element);
    const rect = element.getBoundingClientRect();
    return style.display !== 'none' && style.visibility !== 'hidden'
      && Number.parseFloat(style.opacity || '1') > 0 && rect.width > 0 && rect.height > 0;
  };
  const compact = (value) => String(value || '').replace(/\s+/g, ' ').trim();
  const labels = [...document.querySelectorAll('*')].filter((element) => {
    if (!visible(element)) return false;
    const value = compact(element.innerText);
    return ['发货仓库', '推荐仓库'].some((label) => (
      value === label || value.startsWith(`${label}：`) || value.startsWith(`${label}:`)
    ));
  });
  const panels = [];
  const candidates = [];
  const rowWarehouses = [];
  for (const label of labels) {
    let panel = null;
    let current = label.parentElement;
    for (let depth = 0; current && depth < 8; depth += 1, current = current.parentElement) {
      if (current === document.body || current === document.documentElement) break;
      const text = compact(current.innerText);
      if (text.length <= 12000
        && /发货信息|物流信息|配送信息/.test(text)
        && /(?:发货|推荐)仓库/.test(text)) {
        panel = current;
      }
    }
    const valueRoot = label.closest('.el-form-item, .el-descriptions-item, tr, [role="row"], .ant-form-item')
      || label.parentElement;
    const values = valueRoot ? [
      ...[...valueRoot.querySelectorAll('input, textarea')].map((field) => field.value || field.getAttribute('value') || ''),
      ...[...valueRoot.querySelectorAll('.el-select__selected-item, .el-input__inner, td, dd, .value, [class*="value" i]')]
        .map((element) => element.innerText || ''),
      valueRoot.innerText || '',
    ] : [];
    candidates.push(...values.map(compact).filter(Boolean));
    const headerCell = label.closest('th, [role=columnheader]');
    const headerRow = headerCell?.closest('tr, [role=row]');
    if (headerCell && headerRow) {
      const headerCells = [...headerRow.children].filter((element) => (
        element.matches('th, td, [role=columnheader], [role=cell]')
      ));
      const warehouseColumnIndex = headerCells.indexOf(headerCell);
      const tableRoot = headerCell.closest('.el-table, [role=grid]')
        || headerCell.closest('table')?.parentElement
        || panel;
      if (warehouseColumnIndex >= 0 && tableRoot) {
        const rows = [...tableRoot.querySelectorAll('tbody tr, .el-table__body tr, [role=row]')];
        for (const row of rows) {
          if (!visible(row) || row === headerRow || row.closest('thead')) continue;
          const cells = [...row.children].filter((element) => (
            element.matches('th, td, [role=columnheader], [role=cell]')
          ));
          const warehouseCell = cells[warehouseColumnIndex];
          const warehouseValue = compact(warehouseCell?.innerText);
          if (warehouseValue && !['发货仓库', '推荐仓库'].includes(warehouseValue)) {
            rowWarehouses.push(warehouseValue);
          }
        }
      }
    }
    if (panel) panels.push(compact(panel.innerText));
  }
  return {
    found: labels.length > 0,
    text: [...new Set(panels)].join('\n'),
    candidates: [...new Set(candidates)],
    rowWarehouses: [...new Set(rowWarehouses)],
  };
}).catch(() => ({ found: false, text: '', candidates: [], rowWarehouses: [] }));

function uniqueOmsWarehouseCandidates(values) {
  const unique = new Map();
  for (const value of values || []) {
    const warehouse = extractOmsWarehouseValue(value);
    if (!isValidOmsWarehouseValue(warehouse)) continue;
    const key = normalizeBusinessText(warehouse, { warehouse: true });
    if (key && !unique.has(key)) unique.set(key, warehouse);
  }
  return [...unique.values()];
}

function selectFirstOmsWarehouseCandidate(values) {
  const candidates = uniqueOmsWarehouseCandidates(values);
  return {
    value: candidates[0] || null,
    candidates,
    strategy: candidates.length > 1 ? 'first-candidate' : 'unique-candidate',
  };
}

const saveOmsDiagnostics = async (targetPage, stage) => {
  const diagnostics = await targetPage.evaluate(() => ({
    url: location.href,
    title: document.title,
    bodyText: (document.body?.innerText || '').slice(0, 30000),
    controls: [...document.querySelectorAll('a, button, input, [role="menuitem"], [role="tab"]')]
      .filter((element) => {
        const style = getComputedStyle(element);
        const rect = element.getBoundingClientRect();
        return style.visibility !== 'hidden' && style.display !== 'none' && rect.width > 0 && rect.height > 0;
      })
      .slice(0, 500)
      .map((element) => ({
        tag: element.tagName,
        text: (element.innerText || element.value || '').trim().slice(0, 200),
        placeholder: element.getAttribute('placeholder'),
        ariaLabel: element.getAttribute('aria-label'),
        role: element.getAttribute('role'),
        className: String(element.className || '').slice(0, 300),
      })),
    guideMarkup: [...document.querySelectorAll('*')]
      .filter((element) => (element.innerText || '').trim() === '点击这里也可搜索数据哦')
      .slice(0, 3)
      .map((element) => {
        const ancestors = [];
        let current = element;
        for (let depth = 0; current && depth < 6; depth++, current = current.parentElement) {
          ancestors.push(current.outerHTML.slice(0, 10000));
        }
        return ancestors;
      }),
  })).catch((error) => ({ url: targetPage.url(), error: error.message }));
  fs.mkdirSync(diagnosticsDir, { recursive: true, mode: 0o700 });
  fs.writeFileSync(path.join(diagnosticsDir, 'oms-diagnostics.json'), JSON.stringify({ stage, ...diagnostics }, null, 2), { mode: 0o600 });
};

// The OMS shell is mounted asynchronously.  DOMContentLoaded only means the
// HTML bootstrap finished; it does not mean Vue/Element Plus has rendered the
// login form or the order menu.  Wait for one of those concrete states and do
// not reload the page on every poll.
const readOmsAppState = async (targetPage) => targetPage.evaluate(() => {
  const visible = (element) => {
    const style = getComputedStyle(element);
    const rect = element.getBoundingClientRect();
    return style.display !== 'none'
      && style.visibility !== 'hidden'
      && Number.parseFloat(style.opacity || '1') > 0
      && rect.width > 0
      && rect.height > 0;
  };
  const bodyText = (document.body?.innerText || '').replace(/\s+/g, ' ').trim();
  const passwordInput = [...document.querySelectorAll('input[type="password"]')].some(visible);
  const accountInput = [...document.querySelectorAll(
    'input[placeholder*="账号"], input[placeholder*="用户名"], input[name*="account" i], input[name*="username" i]',
  )].some(visible);
  const loginButton = [...document.querySelectorAll('button, [role="button"]')]
    .some((element) => visible(element) && (element.innerText || '').trim() === '登录');
  const loginForm = passwordInput && (accountInput || loginButton);
  const loggedOut = /当前用户已被登出|无权限访问当前资源|请重新登录/.test(bodyText);
  const businessMenu = [...document.querySelectorAll(
    '[role="menuitem"], .el-menu-item, .el-submenu, a, button',
  )].some((element) => visible(element) && /^(订单|订单管理|交易管理|销售订单|配货单)$/.test(
    (element.innerText || '').replace(/\s+/g, '').trim(),
  ));
  const businessText = /订单管理|交易管理|销售订单|配货单/.test(bodyText);
  const businessPath = /\/xianma\/(?:dashboard|trade|order|home)/.test(location.pathname);
  // The OMS shell keeps a hidden/global Loading node in the DOM even after
  // the route is usable. Only treat a loading marker as blocking when it is
  // visible and there is no business control yet.
  const visibleLoading = [...document.querySelectorAll('[class*="loading" i], [aria-busy="true"]')]
    .some(visible);
  const loadingTextOnly = /^L\s*o\s*a\s*d\s*i\s*n\s*g(?:\s*[.．…]*)?$/i.test(bodyText)
    || /^加载中(?:[.．…]*)?$/.test(bodyText);
  const loading = (visibleLoading || loadingTextOnly) && !businessMenu && !businessText;
  return {
    url: location.href,
    bodyText: bodyText.slice(0, 1000),
    loginForm,
    loggedOut,
    // A URL alone is not enough: the OMS route can be committed while the SPA
    // still displays its Loading splash. Require a visible menu/control and no
    // loading marker before business actions are allowed.
    // The login form can remain mounted over a dashboard route after an
    // expired session. A route/menu match alone must never authenticate it.
    businessShell: !loggedOut && !loginForm && !loading
      && (businessMenu || businessText || businessPath),
    businessMenu,
    loading,
  };
}).catch((error) => ({
  url: targetPage.url(),
  error: error.message,
}));

const waitForOmsAppReady = async (targetPage, stage, { allowLoginForm = true } = {}) => {
  const deadline = Date.now() + omsReadyTimeoutMs;
  let lastState = null;
  while (Date.now() < deadline) {
    if (targetPage.isClosed()) throw new Error(`OMS 标签页已关闭: ${stage}`);
    lastState = await readOmsAppState(targetPage);
    if (lastState.loggedOut) return { ...lastState, state: 'logged-out' };
    if (allowLoginForm && lastState.loginForm) return { ...lastState, state: 'login-form' };
    if (lastState.businessShell) return { ...lastState, state: 'business' };
    await targetPage.waitForTimeout(omsReadyPollMs);
  }
  await saveOmsDiagnostics(targetPage, `${stage}-timeout`);
  throw new Error(`OMS 页面 ${stage} 在 ${Math.ceil(omsReadyTimeoutMs / 1000)} 秒内仍未完成挂载${lastState?.loading ? '（仍显示 Loading）' : ''}`);
};

const waitForOmsAppReadyWithRecovery = async (
  targetPage,
  stage,
  { allowLoginForm = true, recoveryUrl = null } = {},
) => {
  try {
    return await waitForOmsAppReady(targetPage, stage, { allowLoginForm });
  } catch (error) {
    // A single controlled reload recovers a stale SPA bootstrap.  Callers do
    // not loop this helper, so a genuinely unavailable OMS is reported rather
    // than refreshed forever.
    if (!recoveryUrl || !/仍未完成挂载/.test(error.message || '')) throw error;
    console.warn(`[OMS] ${stage} 仍在 Loading，执行一次受控恢复导航: ${recoveryUrl}`);
    await navigateSystemPage(targetPage, recoveryUrl, `${stage}-recovery-navigation`, {
      commitTimeoutMs: omsNavigationTimeoutMs,
      domContentTimeoutMs: omsReadyTimeoutMs,
    });
    return waitForOmsAppReady(targetPage, `${stage}-after-recovery`, { allowLoginForm });
  }
};

// Playwright cannot press the browser chrome refresh button, but reloading the
// page is the same navigation operation and preserves the persistent profile.
// Use one controlled reload before each automatic OMS retry so a stale SPA
// bootstrap or expired session is not mistaken for a healthy login.
const refreshOmsPage = async (targetPage, stage) => {
  await maybeBringToFront(targetPage).catch(() => {});
  await targetPage.reload({ waitUntil: 'commit', timeout: omsNavigationTimeoutMs });
  await targetPage.waitForLoadState('domcontentloaded', { timeout: omsReadyTimeoutMs }).catch(() => {});
  persistSystemTabs('oms');
  writeProgress({
    step: 'oms-page-refreshed',
    currentUrl: targetPage.url(),
    omsRecovery: {
      stage,
      refreshedAt: new Date().toISOString(),
      url: targetPage.url(),
    },
    error: null,
  });
};

const waitForManualOmsLogin = async (targetPage, stage, { timeoutMs = null } = {}) => {
  const verificationLabel = /phone|mobile|sms/iu.test(stage) ? '手机验证' : '验证码';
  targetPage = await resolveSystemLoginPage(
    targetPage,
    'oms',
    (url) => url.includes('/xianma/login'),
    stage,
  );
  await focusManualLoginPage(targetPage);
  await saveWorkflowDiagnostics(targetPage, `human-verification-${stage}`);
  writeProgress({
    step: 'human-verification-required',
    verificationStage: stage,
    currentUrl: targetPage.url(),
    error: null,
  });
  updateAuthHealth('oms', 'verification-required', targetPage, { stage });
  if (browserHeadless) {
    console.error(`\n[需要人工处理] 无头 OMS 流程出现${verificationLabel}，已保存诊断并停止。URL: ${targetPage.url()}\n`);
    throw new HumanVerificationRequiredError(stage, targetPage.url());
  }
  console.error(`\n[需要人工处理] OMS 页面出现${verificationLabel}。请在当前可视化浏览器中完成验证并登录。`);
  console.error(`[需要人工处理] 自动操作已暂停，登录成功后会继续。URL: ${targetPage.url()}\n`);
  targetPage = await waitForLoginExit(
    targetPage,
    (url) => url.includes('/xianma/login'),
    stage,
    { timeoutMs },
  );
  return targetPage;
};

const waitForManualSystemLogin = async (targetPage, system, stage) => {
  const loginPattern = system === 'oms' ? (url) => url.includes('/xianma/login') : (url) => url.includes('/login');
  targetPage = await resolveSystemLoginPage(targetPage, system, loginPattern, stage);
  await focusManualLoginPage(targetPage);
  await saveWorkflowDiagnostics(targetPage, `manual-login-${system}-${stage}`);
  writeProgress({
    step: 'manual-login-required',
    verificationStage: `${system}-login`,
    currentUrl: targetPage.url(),
    systemLogin: {
      system,
      attempts: systemLoginAttempts[system] || 0,
      maxAttempts: systemLoginMaxAttempts,
      status: 'waiting-human',
      updatedAt: new Date().toISOString(),
    },
    error: null,
  });
  updateAuthHealth(system, 'verification-required', targetPage, { stage });
  if (browserHeadless) throw new HumanVerificationRequiredError(`${system}-login`, targetPage.url());
  console.error(`[需要人工登录] ${system.toUpperCase()} 自动登录连续失败三次，请在当前浏览器页面完成登录，成功后自动继续。URL: ${targetPage.url()}`);
  targetPage = await waitForLoginExit(targetPage, loginPattern, `${system}-manual-login`);
  await targetPage.waitForTimeout(actionDelayFor(targetPage, `${system}-manual-login`));

  // Leaving the login URL is not sufficient: both OMS and TMS can briefly
  // redirect to a shell and then send an unauthenticated session back to the
  // login route. Confirm the rendered business page before resuming and do
  // not mark a failed redirect as an authenticated recovery.
  if (system === 'oms') {
    const appState = await waitForOmsAppReadyWithRecovery(targetPage, `${stage}-business-shell`, {
      allowLoginForm: false,
      recoveryUrl: targetPage.url(),
    });
    if (appState.state !== 'business') {
      throw new Error(`OMS 人工登录后未进入业务页面: ${targetPage.url()}`);
    }
    assertOmsBusinessSession(targetPage);
  } else {
    if (loginPattern(targetPage.url())) {
      throw new Error(`TMS 人工登录后仍停留在登录页: ${targetPage.url()}`);
    }
    await checkForHumanVerification(targetPage, `${stage}-post-login`);
  }
  updateAuthHealth(system, 'authenticated', targetPage, { stage: null });
  persistSystemTabs(system);
  writeProgress({
    step: 'manual-login-completed',
    verificationStage: null,
    currentUrl: targetPage.url(),
    systemLogin: {
      system,
      attempts: systemLoginAttempts[system] || 0,
      maxAttempts: systemLoginMaxAttempts,
      status: 'authenticated',
      completedAt: new Date().toISOString(),
    },
    error: null,
  });
  return targetPage;
};

const closeUnexpectedOmsPopups = async (targetPage) => {
  const omsSearchTipClose = await firstVisible([
    targetPage.locator('.tips-wrapper:visible i.cursor-pointer'),
  ]);
  if (omsSearchTipClose) {
    await omsSearchTipClose.click({ force: true, timeout: 5000 }).catch(() => {});
    console.log('已点击 X 关闭 OMS 搜索条件新手引导。');
  }
  const searchGuide = await firstVisible([
    targetPage.locator('.el-popper:visible').filter({ hasText: '点击这里也可搜索数据哦' }),
    targetPage.locator('[role="tooltip"]:visible').filter({ hasText: '点击这里也可搜索数据哦' }),
    targetPage.locator('[class*="popover" i]:visible').filter({ hasText: '点击这里也可搜索数据哦' }),
    targetPage.locator('[class*="guide" i]:visible').filter({ hasText: '点击这里也可搜索数据哦' }),
  ]);
  if (searchGuide) {
    const guideClose = await firstVisible([
      searchGuide.locator('[class*="close" i]'),
      searchGuide.locator('button'),
      searchGuide.locator('[aria-label*="关闭"]'),
      searchGuide.locator('[aria-label*="close" i]'),
    ]);
    if (guideClose) {
      await guideClose.click();
      console.log('已点击 X 关闭 OMS 搜索条件新手引导。');
    }
  }
  const closeButtons = targetPage.locator([
    '.el-message-box__headerbtn:visible',
    '.el-notification__closeBtn:visible',
    '.el-dialog__headerbtn:visible',
    '.el-tour__close-btn:visible',
    '.driver-popover-close-btn:visible',
    '.introjs-skipbutton:visible',
    '.shepherd-cancel-icon:visible',
    'button[aria-label*="Close" i]:visible',
    'button[aria-label*="关闭"]:visible',
    '[class*="tour" i] [class*="close" i]:visible',
    '[class*="guide" i] [class*="close" i]:visible',
  ].join(', '));
  let closed = 0;
  for (let attempt = 0; attempt < 5; attempt++) {
    const button = await firstVisible([closeButtons]);
    if (!button) break;
    const clicked = await button.click({ force: true, timeout: 5000 }).then(() => true).catch(() => false);
    if (!clicked) break;
    closed++;
  }
  if (closed) console.log(`已点击 X 关闭 ${closed} 个 OMS 无关提示弹窗。`);
  return closed;
};

const ensureOmsLoginOnce = async (
  targetPage,
  browserContext,
  { residentWarmup = false, manualLoginTimeoutMs = null } = {},
) => {
  const existingOmsLogin = await locateSystemLoginAcrossPages(
    targetPage,
    'oms',
    (url) => url.includes('/xianma/login'),
    'oms-login-recovery',
  );
  if (existingOmsLogin?.page && existingOmsLogin.page !== targetPage) {
    targetPage = existingOmsLogin.page;
    console.log(`[OMS 登录] 已切换到实际登录标签页: ${existingOmsLogin.url}`);
  }
  // Do not navigate an already authenticated business tab back to the login
  // page. That used to make the visible OMS tab appear logged out during every
  // health check and could race the order workflow.
  let omsOrigin = false;
  try {
    omsOrigin = new URL(targetPage.url()).origin === 'https://www.jeoms.com';
  } catch {
    omsOrigin = false;
  }
  if (!omsOrigin) {
    await pacedAction(targetPage, 'open-oms-login', () => navigateSystemPage(
      targetPage,
      omsLoginUrl,
      'open-oms-login',
      { commitTimeoutMs: omsNavigationTimeoutMs, domContentTimeoutMs: omsReadyTimeoutMs },
    ));
  }
  if (omsOrigin && !targetPage.url().includes('/xianma/login')) {
    const appState = await waitForOmsAppReadyWithRecovery(targetPage, 'business-shell', {
      allowLoginForm: true,
      recoveryUrl: targetPage.url(),
    });
    // An expired session may leave the login form mounted over the dashboard
    // route. Treat that the same as an explicit login URL; otherwise the
    // worker would mark OMS authenticated while the visible tab still shows
    // the login screen.
    if (appState.state === 'logged-out' || appState.state === 'login-form') {
      await pacedAction(targetPage, 'reopen-oms-login-after-expiry', () => navigateSystemPage(
        targetPage,
        omsLoginUrl,
        'reopen-oms-login-after-expiry',
        { commitTimeoutMs: omsNavigationTimeoutMs, domContentTimeoutMs: omsReadyTimeoutMs },
      ));
    }
  }
  if (targetPage.url().includes('/xianma/login')) {
    if (residentWarmup) {
      console.log(`[resident-oms] ${shopId}: automatic login check started`);
    } else {
      logRunStep('oms-auto-login-attempt', { omsUrl: targetPage.url(), credentialsConfigured: Boolean(process.env.JEOMS_ACCOUNT && process.env.JEOMS_PASSWORD) });
    }
    await targetPage.waitForLoadState('domcontentloaded', { timeout: 30000 }).catch(() => {});
    await waitForOmsAppReadyWithRecovery(targetPage, 'login-shell', {
      allowLoginForm: true,
      recoveryUrl: omsLoginUrl,
    });
    updateAuthHealth('oms', 'expired', targetPage);
    const omsAccount = process.env.JEOMS_ACCOUNT;
    const omsPassword = process.env.JEOMS_PASSWORD;
    if (!omsAccount || !omsPassword) {
      if (residentWarmup) {
        const deferred = new Error('OMS resident startup login requires configured shop credentials');
        deferred.code = 'OMS_RESIDENT_WARMUP_LOGIN_REQUIRED';
        throw deferred;
      }
      await focusManualLoginPage(targetPage);
      await saveWorkflowDiagnostics(targetPage, 'manual-login-oms');
      writeProgress({
        step: browserHeadless ? 'human-verification-required' : 'manual-login-required',
        verificationStage: 'oms-login',
        currentUrl: targetPage.url(),
        error: null,
      });
      if (browserHeadless) {
        console.error('\n[需要人工登录] OMS 登录状态已失效；无头服务器没有可操作窗口，流程已停止。');
        console.error('[需要人工登录] 请在本地有界面环境恢复认证状态后再续跑。\n');
        throw new HumanVerificationRequiredError('oms-login', targetPage.url());
      }
      console.error('\n[需要人工登录] OMS 登录状态已失效，请在当前可视化浏览器中手动登录。');
      console.error(`[需要人工登录] 登录成功后流程会自动继续。URL: ${targetPage.url()}\n`);
      const claimYieldTimeoutMs = omsMode === 'per-shop'
        && residentCommandMode
        && externalEffectGuardEnabled
        ? omsManualLoginClaimYieldMs
        : null;
      targetPage = await waitForLoginExit(
        targetPage,
        (url) => url.includes('/xianma/login'),
        'oms-manual-login',
        { timeoutMs: manualLoginTimeoutMs ?? claimYieldTimeoutMs },
      );
    } else {
      // The OMS login form is rendered asynchronously and its labels vary by
      // deployment. Wait for the form, then fall back to the first visible
      // non-hidden input instead of failing while the SPA is still mounting.
      const loginDeadline = Date.now() + 20000;
      let account = null;
      let password = null;
      while (Date.now() < loginDeadline && (!account || !password)) {
        account = await firstVisible([
          targetPage.getByRole('textbox', { name: '登录账号' }),
          targetPage.locator('input[placeholder*="账号"]'),
          targetPage.locator('input[placeholder*="用户名"]'),
          targetPage.locator('input[name*="account" i], input[name*="username" i]'),
          targetPage.locator('input:not([type="hidden"]):not([type="password"]):not([type="submit"])').first(),
        ]);
        password = await firstVisible([
          targetPage.getByRole('textbox', { name: '登录密码' }),
          targetPage.locator('input[placeholder*="密码"]'),
          targetPage.locator('input[type="password"]'),
        ]);
        if (!account || !password) await targetPage.waitForTimeout(500);
      }
      if (!account || !password) {
        await navigateSystemPage(targetPage, omsLoginUrl, 'reload-oms-login-form', {
          commitTimeoutMs: omsNavigationTimeoutMs,
          domContentTimeoutMs: omsReadyTimeoutMs,
        });
        await targetPage.waitForTimeout(2000);
        account = await firstVisible([
          targetPage.getByRole('textbox', { name: '登录账号' }),
          targetPage.locator('input[placeholder*="账号"], input[placeholder*="用户名"]'),
          targetPage.locator('input[name*="account" i], input[name*="username" i]').first(),
        ]);
        password = await firstVisible([
          targetPage.getByRole('textbox', { name: '登录密码' }),
          targetPage.locator('input[placeholder*="密码"], input[type="password"]').first(),
        ]);
      }
      if (!account || !password) {
        throw new Error('OMS 登录页控件未加载完成，自动恢复后重试');
      }

      await account.fill(omsAccount);
      await password.fill(omsPassword);
      const captcha = await firstVisible([
        targetPage.getByRole('textbox', { name: /验证码/ }),
        targetPage.locator('input[placeholder*="验证码"]'),
        targetPage.locator('input[name*="captcha" i], input[id*="captcha" i]'),
        targetPage.getByRole('textbox', { name: /验证码/ }),
        targetPage.locator('input[placeholder*="验证码"]'),
      ]);
      if (captcha) {
        if (residentWarmup) {
          updateAuthHealth('oms', 'verification-required', targetPage, {
            stage: 'resident-oms-startup-verification',
          });
          await saveWorkflowDiagnostics(targetPage, 'resident-oms-startup-verification');
          const deferred = new Error('OMS resident startup verification requires operator action');
          deferred.code = 'OMS_RESIDENT_WARMUP_VERIFICATION_REQUIRED';
          throw deferred;
        }
        targetPage = await waitForManualOmsLogin(targetPage, 'oms-login-captcha', {
          timeoutMs: manualLoginTimeoutMs,
        });
      } else {
        const loginButton = await firstVisible([
          targetPage.getByRole('button', { name: '登录', exact: true }),
          targetPage.locator('button[type="submit"]'),
          targetPage.locator('form button').last(),
          targetPage.getByRole('button', { name: '登录', exact: true }),
          targetPage.getByText('登录', { exact: true }),
        ]);
        if (!loginButton) throw new Error('OMS 登录页未找到登录按钮');
        await loginButton.click({ force: true, timeout: 10000 });
        await targetPage.waitForTimeout(1500);
        const phoneVerification = await firstVisible([
          targetPage.getByText(/手机验证|短信验证|安全验证/, { exact: true }),
          targetPage.locator('.el-dialog:visible, [role="dialog"]:visible')
            .filter({ hasText: /手机验证|短信验证|安全验证/ }),
        ]);
        if (phoneVerification) {
          if (residentWarmup) {
            updateAuthHealth('oms', 'verification-required', targetPage, {
              stage: 'resident-oms-startup-phone-verification',
            });
            await saveWorkflowDiagnostics(targetPage, 'resident-oms-startup-phone-verification');
            const deferred = new Error('OMS resident startup phone verification requires operator action');
            deferred.code = 'OMS_RESIDENT_WARMUP_VERIFICATION_REQUIRED';
            throw deferred;
          }
          targetPage = await waitForManualOmsLogin(targetPage, 'oms-login-phone-verification', {
            timeoutMs: manualLoginTimeoutMs,
          });
        }
        targetPage = await waitForLoginExit(targetPage, (url) => url.includes('/xianma/login'), 'oms-login-result', {
          timeoutMs: 45000,
        });
        await waitForOmsAppReadyWithRecovery(targetPage, 'post-login-business-shell', {
          allowLoginForm: false,
          recoveryUrl: targetPage.url(),
        });
      }
    }
  }

  const persistedAuthState = await persistBrowserAuth(browserContext);
  await waitForOmsAppReadyWithRecovery(targetPage, 'authenticated-business-shell', {
    allowLoginForm: false,
    recoveryUrl: targetPage.url(),
  });
  await closeUnexpectedOmsPopups(targetPage);
  assertOmsBusinessSession(targetPage);
  persistSharedOmsStorageState(persistedAuthState);
  updateAuthHealth('oms', 'authenticated', targetPage);
  // Keep the permanent OMS anchor's persisted URL in sync with the actual
  // authenticated business page after login or recovery.
  persistSystemTabs('oms');
  if (residentWarmup) {
    console.log(`[resident-oms] ${shopId}: authenticated business shell ready at ${targetPage.url()}`);
  } else {
    writeProgress({ error: null, systemLogin: { system: 'oms', attempts: 0, maxAttempts: systemLoginMaxAttempts, status: 'authenticated', completedAt: new Date().toISOString() } });
    logRunStep('oms-login-complete', { omsUrl: targetPage.url() });
  }
};

const ensureOmsLoginUnlocked = async (targetPage, browserContext, options = {}) => {
  try {
    const result = await ensureOmsLoginOnce(targetPage, browserContext, options);
    systemLoginAttempts.oms = 0;
    return result;
  } catch (error) {
    systemLoginAttempts.oms += 1;
    if (!options.residentWarmup) {
      updateAuthHealth('oms', 'expired', targetPage, {
        stage: 'oms-login-retry',
        lastError: error.message,
      });
    }
    if (await hasHumanVerification(targetPage)) {
      updateAuthHealth('oms', 'verification-required', targetPage, {
        stage: options.residentWarmup ? 'resident-oms-startup-verification' : 'oms-login-captcha',
      });
      if (options.residentWarmup) {
        const deferred = new Error(`OMS resident startup verification requires operator action: ${error.message}`, {
          cause: error,
        });
        deferred.code = 'OMS_RESIDENT_WARMUP_VERIFICATION_REQUIRED';
        throw deferred;
      }
      targetPage = await waitForManualSystemLogin(targetPage, 'oms', 'oms-login-captcha');
      systemLoginAttempts.oms = 0;
      return ensureOmsLoginOnce(targetPage, browserContext, options);
    }

    // Keep the retry bounded so one shop-specific OMS profile cannot hold its
    // business claim through repeated Loading/login recovery loops. The next
    // normal retry resumes with the same isolated browser profile.
    if (!options.residentWarmup) {
      writeProgress({
        step: 'oms-login-retry-deferred',
        verificationStage: null,
        systemLogin: {
          system: 'oms',
          attempts: systemLoginAttempts.oms,
          maxAttempts: systemLoginMaxAttempts,
          status: 'retry-ready',
          lastError: error.message,
          updatedAt: new Date().toISOString(),
        },
        currentUrl: targetPage.url(),
        error: null,
      });
    }
    const deferred = new Error(`OMS automatic login recovery deferred for this shop profile: ${error.message}`, {
      cause: error,
    });
    deferred.code = 'OMS_LOGIN_RETRY_DEFERRED';
    throw deferred;
  }
};

const refreshOmsFromLatestSharedSnapshot = async (targetPage, browserContext) => {
  if (omsMode !== 'shared') return false;
  const snapshotIdentity = storageSnapshotIdentity(sharedOmsStatePath);
  if (!snapshotIdentity || snapshotIdentity === lastAppliedSharedOmsSnapshotIdentity) return false;

  // Never replace a rendered, authenticated OMS session with another
  // profile's snapshot. The shared snapshot is only a recovery source for a
  // logged-out or blank resident OMS tab; PDD and TMS storage stay untouched.
  const appState = await readOmsAppState(targetPage).catch(() => null);
  if (appState?.state === 'business') {
    lastAppliedSharedOmsSnapshotIdentity = snapshotIdentity;
    return false;
  }

  const sharedState = readSavedStorageState(sharedOmsStatePath);
  if (!hasSystemStorageData(sharedState, 'oms')) return false;
  const restored = await restoreBrowserAuthFromSnapshots(
    browserContext,
    sharedState,
    { replaceSystems: ['oms'] },
  );
  lastAppliedSharedOmsSnapshotIdentity = snapshotIdentity;
  if (!restored.restoredSystems.includes('oms')) return false;

  writeProgress({
    step: 'oms-shared-session-refreshing',
    omsSession: {
      status: 'refreshing',
      stage: 'runtime-shared-auth-refresh',
      ownerShopId: shopId,
      snapshotIdentity,
      refreshedAt: new Date().toISOString(),
    },
    error: null,
  });
  await navigateSystemPage(
    targetPage,
    omsOrdersUrl,
    'oms-shared-session-runtime-refresh',
    { commitTimeoutMs: omsNavigationTimeoutMs, domContentTimeoutMs: omsReadyTimeoutMs },
  );
  console.log(`[browser-auth] ${shopId} applied the latest shared OMS snapshot at runtime`);
  return true;
};

const ensureOmsLogin = async (targetPage, browserContext, options = {}) => withOmsSessionLock(
  'oms-login',
  async (sharedPage, sharedContext) => {
    const executionPage = sharedPage || targetPage;
    const executionContext = sharedContext || browserContext;
    if (!sharedPage) {
      await refreshOmsFromLatestSharedSnapshot(executionPage, executionContext);
    }
    return ensureOmsLoginUnlocked(executionPage, executionContext, options);
  },
);

const normalizeOmsOrderStatus = (value) => {
  const text = String(value || '').normalize('NFKC').replace(/\s+/g, '').trim();
  if (!text) return null;
  const known = [
    '已配货', '部分配货', '待配货', '未配货', '新建', '已审核', '待审核',
    '已发货', '已完成', '已关闭', '已取消', '作废',
  ].find((status) => text === status || text.includes(status));
  return known || text;
};

const findVisibleOmsOrderCell = async (targetPage, orderNumber) => {
  const escapedOrderNumber = String(orderNumber).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const exactOrderNumber = new RegExp(`^\\s*${escapedOrderNumber}\\s*$`);
  const renderedRows = targetPage.locator([
    '.ag-center-cols-container .ag-row',
    '.ag-body-viewport .ag-row',
    '[role="row"]',
    'tbody tr',
  ].join(','));
  return firstVisible([
    renderedRows.getByText(orderNumber, { exact: true }),
    targetPage.locator('.ag-cell, [role="gridcell"], td').filter({ hasText: exactOrderNumber }),
  ]);
};

const findVisibleOmsOrderRow = async (targetPage, orderNumber, {
  timeoutMs = 45000,
  pollIntervalMs = 500,
} = {}) => {
  const deadline = Date.now() + timeoutMs;
  do {
    // Re-acquire both locators in the same polling iteration. OMS redraws its
    // AG Grid after a query, so a cell from the previous render can detach
    // before its row is resolved.
    const orderCell = await findVisibleOmsOrderCell(targetPage, orderNumber);
    if (orderCell) {
      const rowScope = orderCell.locator(
        'xpath=ancestor::*[self::tr or @role="row" or contains(concat(" ", normalize-space(@class), " "), " ag-row ")][1]',
      );
      if (await rowScope.count().catch(() => 0)
        && await rowScope.isVisible().catch(() => false)) {
        return { orderCell, rowScope };
      }
    }
    await targetPage.waitForTimeout(pollIntervalMs);
  } while (Date.now() < deadline);
  return null;
};

const readOmsRowCellByHeader = async (targetPage, rowScope, headerPattern) => {
  const rowId = await rowScope.getAttribute('row-id').catch(() => null);
  const rowIndex = await rowScope.getAttribute('row-index').catch(() => null);
  const matchingRowSelector = rowId != null
    ? `.ag-row[row-id=${JSON.stringify(rowId)}]`
    : rowIndex != null ? `.ag-row[row-index=${JSON.stringify(rowIndex)}]` : null;
  const findRenderedCell = async () => {
    const headers = targetPage.locator('.ag-header-cell');
    for (let index = 0; index < await headers.count().catch(() => 0); index++) {
      const header = headers.nth(index);
      if (!await header.isVisible().catch(() => false)) continue;
      const headerText = (await header.innerText().catch(() => '')).replace(/\s+/g, '').trim();
      if (!headerPattern.test(headerText)) continue;
      const colId = await header.getAttribute('col-id').catch(() => null);
      const ariaColIndex = await header.getAttribute('aria-colindex').catch(() => null);
      const cell = await firstVisible([
        ...(colId ? [rowScope.locator(`.ag-cell[col-id="${colId}"]`)] : []),
        ...(ariaColIndex ? [rowScope.locator(`[role="gridcell"][aria-colindex="${ariaColIndex}"]`)] : []),
        ...(matchingRowSelector && colId
          ? [targetPage.locator(`${matchingRowSelector} .ag-cell[col-id="${colId}"]`)]
          : []),
        ...(matchingRowSelector && ariaColIndex
          ? [targetPage.locator(`${matchingRowSelector} [role="gridcell"][aria-colindex="${ariaColIndex}"]`)]
          : []),
      ]);
      if (cell) return cell;
    }
    return null;
  };

  const renderedCell = await findRenderedCell();
  if (renderedCell) return renderedCell;

  const horizontalViewport = await firstVisible([
    targetPage.locator('.ag-body-horizontal-scroll-viewport'),
    targetPage.locator('.ag-center-cols-viewport'),
  ]);
  if (!horizontalViewport) return null;
  const dimensions = await horizontalViewport.evaluate((element) => ({
    current: element.scrollLeft,
    maximum: Math.max(0, element.scrollWidth - element.clientWidth),
    increment: Math.max(200, Math.floor(element.clientWidth * 0.75)),
  })).catch(() => null);
  if (!dimensions?.maximum) return null;
  const positions = [];
  for (let offset = 0; offset < dimensions.maximum; offset += dimensions.increment) positions.push(offset);
  positions.push(dimensions.maximum);
  for (const offset of [...new Set(positions)]) {
    await horizontalViewport.evaluate((element, left) => {
      element.scrollLeft = left;
      element.dispatchEvent(new Event('scroll', { bubbles: true }));
    }, offset).catch(() => {});
    await targetPage.waitForTimeout(150);
    const cell = await findRenderedCell();
    if (cell) return cell;
  }
  return null;
};

const waitForFirstVisible = async (targetPage, candidates, {
  timeoutMs = tmsNavigationTimeoutMs,
  pollIntervalMs = tmsNavigationPollIntervalMs,
} = {}) => {
  const deadline = Date.now() + timeoutMs;
  do {
    const element = await firstVisible(candidates);
    if (element) return element;
    await targetPage.waitForTimeout(pollIntervalMs);
  } while (Date.now() < deadline);
  return null;
};

const readOmsOrderStatus = async (targetPage, rowScope) => {
  const horizontalViewport = await firstVisible([
    targetPage.locator('.ag-body-horizontal-scroll-viewport'),
    targetPage.locator('.ag-center-cols-viewport'),
  ]);
  const startingScrollLeft = horizontalViewport
    ? await horizontalViewport.evaluate((element) => element.scrollLeft).catch(() => null)
    : null;
  try {
    const statusCell = await readOmsRowCellByHeader(targetPage, rowScope, /^订单状态$/);
    if (statusCell) return normalizeOmsOrderStatus(await statusCell.innerText().catch(() => ''));
    const fallback = await firstVisible([
      rowScope.locator('.ag-cell[col-id*="orderStatus" i]'),
      rowScope.locator('.ag-cell[col-id*="tradeStatus" i]'),
      rowScope.locator('.ag-cell[col-id*="salesStatus" i]'),
    ]);
    return normalizeOmsOrderStatus(fallback ? await fallback.innerText().catch(() => '') : '');
  } finally {
    if (horizontalViewport && startingScrollLeft != null) {
      const restored = await horizontalViewport.evaluate((element, left) => {
        if (element.scrollLeft === left) return false;
        element.scrollLeft = left;
        element.dispatchEvent(new Event('scroll', { bubbles: true }));
        return true;
      }, startingScrollLeft).catch(() => false);
      if (restored) await targetPage.waitForTimeout(150);
    }
  }
};

const readOmsOrderMark = async (
  targetPage,
  orderNumber,
  currentOrderCell,
  currentRowScope,
  renderedCells = [],
) => {
  const refreshedOrder = await findVisibleOmsOrderRow(targetPage, orderNumber, {
    timeoutMs: 10_000,
    pollIntervalMs: 250,
  });
  const orderCell = refreshedOrder?.orderCell || currentOrderCell;
  const rowScope = refreshedOrder?.rowScope || currentRowScope;
  const rowId = await rowScope.getAttribute('row-id').catch(() => null);
  const rowIndex = await rowScope.getAttribute('row-index').catch(() => null);
  const matchingRowSelector = rowId != null
    ? `.ag-row[row-id=${JSON.stringify(rowId)}]`
    : rowIndex != null ? `.ag-row[row-index=${JSON.stringify(rowIndex)}]` : null;
  const markHeader = await firstVisible([
    targetPage.locator('.ag-header-cell').filter({ hasText: /^标记$/ }),
    targetPage.getByText('标记', { exact: true })
      .locator('xpath=ancestor::*[contains(@class,"ag-header-cell")][1]'),
  ]);
  const markColId = markHeader ? await markHeader.getAttribute('col-id') : null;
  const markCellCandidates = [
    rowScope.locator('.ag-cell[col-id="tags"]'),
    ...(markColId ? [rowScope.locator(`.ag-cell[col-id="${markColId}"]`)] : []),
    ...(matchingRowSelector ? [targetPage.locator(`${matchingRowSelector} .ag-cell[col-id="tags"]`)] : []),
    ...(matchingRowSelector && markColId
      ? [targetPage.locator(`${matchingRowSelector} .ag-cell[col-id="${markColId}"]`)]
      : []),
    rowScope.locator('.ag-cell').filter({ hasText: /^(补|手|低值品|补发|补单)/ }),
  ];
  const markCell = await firstVisible(markCellCandidates);
  if (markCell) {
    const cellText = (await markCell.innerText().catch(() => '')).trim();
    let clicked = false;
    try {
      await markCell.click({ force: true });
      clicked = true;
      await targetPage.waitForTimeout(100);
    } catch {}
    const markOverlay = await firstVisible([
      targetPage.locator('[role="tooltip"]:visible'),
      targetPage.locator('.el-popover:visible, .el-popper:visible, .ant-popover:visible'),
      targetPage.locator('[role="dialog"]:visible'),
    ]);
    const overlayText = markOverlay ? await markOverlay.innerText().catch(() => '') : '';
    const capturedMarkText = String(renderedCells.find((cell) => (
      String(cell?.colId || '') === 'tags'
      || (markColId && String(cell?.colId || '') === markColId)
    ))?.text || '').trim();
    if (!clicked && !cellText && !overlayText.trim() && !capturedMarkText) {
      throw new Error('OMS 当前订单行“标记”单元格存在，但无法读取内容');
    }
    const liveMarkText = (overlayText || cellText).trim();
    const markText = liveMarkText || capturedMarkText;
    return {
      orderCell,
      rowScope,
      markText,
      isLowValue: lowValuePattern.test(markText),
      isReissueOrder: reissuePattern.test(markText),
      source: liveMarkText ? (overlayText ? 'mark-overlay' : 'visible-mark-cell')
        : 'captured-row-dom',
    };
  }

  for (const candidate of markCellCandidates) {
    if (!await candidate.count().catch(() => 0)) continue;
    const markText = (await candidate.first().textContent().catch(() => '') || '').trim();
    return {
      orderCell,
      rowScope,
      markText,
      isLowValue: lowValuePattern.test(markText),
      isReissueOrder: reissuePattern.test(markText),
      source: 'rendered-mark-cell',
    };
  }

  const capturedMarkCell = renderedCells.find((cell) => (
    String(cell?.colId || '') === 'tags'
    || (markColId && String(cell?.colId || '') === markColId)
  ));
  if (capturedMarkCell) {
    const markText = String(capturedMarkCell.text || '').trim();
    return {
      orderCell,
      rowScope,
      markText,
      isLowValue: lowValuePattern.test(markText),
      isReissueOrder: reissuePattern.test(markText),
      source: 'captured-row-dom',
    };
  }
  throw new Error('OMS 当前订单行未找到“标记”单元格');
};

const findOmsSalesOrderCodeCell = async (targetPage, rowScope, renderedCells, orderNumber) => {
  const currentRowCandidates = [
    rowScope.locator('.ag-cell[col-id="salesOrderCode"]'),
    rowScope.getByText(/^SO\d+$/u, { exact: true }),
  ];
  const deadline = Date.now() + 2_000;
  do {
    const cell = await firstVisible(currentRowCandidates);
    if (cell) return cell;
    await targetPage.waitForTimeout(250);
  } while (Date.now() < deadline);

  // AG Grid can redraw the pinned sales-code cell outside the row locator
  // after the mark popover closes. Reuse only the unique code captured from the
  // exact order row before that redraw; never guess a code from another row.
  if (!renderedCells.some((cell) => cell.colId === 'tradeId'
    && String(cell.text || '').trim() === orderNumber)) return null;
  const capturedCodes = [...new Set(renderedCells
    .filter((cell) => cell.colId === 'salesOrderCode'
      && /^SO\d{8,}$/u.test(String(cell.text || '').trim()))
    .map((cell) => String(cell.text).trim()))];
  if (capturedCodes.length !== 1) return null;
  const matchingCells = targetPage.getByText(capturedCodes[0], { exact: true });
  const visible = [];
  for (let index = 0; index < Math.min(10, await matchingCells.count()); index += 1) {
    const candidate = matchingCells.nth(index);
    if (await candidate.isVisible().catch(() => false)) visible.push(candidate);
  }
  return visible.length === 1 ? visible[0] : null;
};

const analyzeOmsOrderUnlocked = async (targetPage, browserContext, orderNumber) => {
  try {
    const salesInput = await ensureOmsOrderManagementPage(targetPage, browserContext, {
      maxAttempts: 2,
      timeoutMs: 30_000,
    });
    await closeUnexpectedOmsPopups(targetPage);
    logRunStep('oms-orders-opened', { omsUrl: targetPage.url() });

    await closeUnexpectedOmsPopups(targetPage);

    const submitOmsOrderQuery = async (input, pass) => {
      const readyInput = await fillReadyOmsOrderQueryInput(targetPage, orderNumber, {
        preferredInput: input,
        timeoutMs: 30_000,
      });
      const queryButton = await firstVisible([
        targetPage.getByRole('button', { name: /^(查询|搜索)$/ }),
        targetPage.getByText(/^(查询|搜索)$/, { exact: true }),
      ]);
      if (!queryButton) throw new Error('OMS 订单页未找到查询按钮');
      await queryButton.click({ force: true });
      logRunStep('oms-order-query-submitted', {
        orderNumber,
        pass,
        timeoutMs: 30_000,
        omsUrl: targetPage.url(),
      });
      return findVisibleOmsOrderRow(targetPage, orderNumber, {
        timeoutMs: 30_000,
        pollIntervalMs: 500,
      });
    };

    let orderResult = null;
    let lastQueryError = null;
    let currentInput = salesInput;
    for (let pass = 1; pass <= 2 && !orderResult; pass++) {
      try {
        orderResult = await submitOmsOrderQuery(currentInput, pass);
      } catch (error) {
        lastQueryError = error;
      }
      if (orderResult || pass >= 2) break;
      writeProgress({
        step: 'oms-order-query-refreshing',
        omsOrderQueryRecovery: {
          orderNumber,
          status: 'refreshing',
          completedPasses: pass,
          timeoutMsPerPass: 30_000,
          lastError: lastQueryError?.message || null,
          refreshedAt: new Date().toISOString(),
        },
        error: null,
      });
      await targetPage.reload({ waitUntil: 'domcontentloaded', timeout: 45_000 }).catch(() => {});
      const recoveredInput = await ensureOmsOrderManagementPage(targetPage, browserContext, {
        maxAttempts: 1,
        timeoutMs: 30_000,
      });
      await closeUnexpectedOmsPopups(targetPage);
      currentInput = recoveredInput;
    }
    if (!orderResult) {
      const queryError = new LogisticsRetryRequiredError(
        'oms-order-query-transient',
        `OMS_QUERY_TEMPORARILY_UNAVAILABLE: OMS 查询刷新后仍未返回订单号: ${orderNumber}${lastQueryError ? `；${lastQueryError.message}` : ''}`,
        30_000,
        { orderNumber, transientSystem: 'OMS' },
      );
      queryError.code = 'OMS_QUERY_TEMPORARILY_UNAVAILABLE';
      writeProgress({
        step: 'oms-order-query-retry-ready',
        omsOrderQueryRecovery: {
          orderNumber,
          status: 'retry-ready',
          completedPasses: 2,
          timeoutMsPerPass: 30_000,
          lastError: lastQueryError?.message || null,
          retryAfterMs: queryError.retryAfterMs,
          failedAt: new Date().toISOString(),
        },
        manualReview: null,
      });
      throw queryError;
    }
    let { orderCell, rowScope } = orderResult;
    await orderCell.waitFor({ state: 'visible', timeout: 30000 });
    const gridCells = await rowScope.locator('.ag-cell, td').evaluateAll((cells) => cells.map((cell) => ({
      colId: cell.getAttribute('col-id'),
      text: (cell.innerText || '').trim(),
      className: String(cell.className || ''),
    }))).catch(() => []);
    const orderStatus = await readOmsOrderStatus(targetPage, rowScope);
    const refreshedOrderResult = await findVisibleOmsOrderRow(targetPage, orderNumber, {
      timeoutMs: 10_000,
      pollIntervalMs: 250,
    });
    if (refreshedOrderResult) {
      orderCell = refreshedOrderResult.orderCell;
      rowScope = refreshedOrderResult.rowScope;
    }
    writeProgress({ omsGridCells: gridCells, omsOrderStatus: orderStatus });

    const currentProgress = readProgress();
    const scenarioCode = currentProgress.scenarioCode || activeScenarioCode;
    if (scenarioCode === ORDINARY_SCENARIO_CODES.PROMISE_REISSUE) {
      // This scenario only needs a read-only scan of all OMS sub-orders. Do
      // not open the shipping-detail tab or mutate OMS allocation state.
      return queryOmsPromiseReissueSuborder(targetPage, browserContext, orderNumber);
    }
    const abnormalNetworkUnshipped = scenarioCode === 'abnormal-network-warning'
      && isAbnormalNetworkUnshipped(currentProgress.logisticsAnalysis);
    const abnormalNetworkRequiresWarehouse = abnormalNetworkUnshipped
      && !omsOrderStatusIsTerminalWithoutShipment(orderStatus)
      && !omsOrderStatusHasPassedAllocation(orderStatus);
    if (scenarioCode === 'abnormal-network-warning' && !abnormalNetworkRequiresWarehouse) {
      const omsAnalysis = {
        orderNumber,
        shippingWarehouse: null,
        warehouseStatus: 'not-applicable',
        warehouseSource: null,
        warehouseSelectionStrategy: null,
        warehouseCandidates: [],
        matchedWarehouse: null,
        isTargetWarehouse: null,
        isLowValue: null,
        isReissueOrder: null,
        orderStatus,
        markText: null,
      };
      writeProgress({
        step: 'oms-order-status-analyzed',
        omsAnalysis,
        omsMarkText: null,
        isLowValue: null,
        isReissueOrder: null,
        omsWarehouseParse: {
          status: 'not-applicable',
          orderNumber,
          parsedValue: null,
          candidates: [],
          selectionStrategy: null,
          checkedAt: new Date().toISOString(),
          source: null,
        },
        manualReview: null,
        error: null,
        currentUrl: targetPage.url(),
        verificationStage: null,
      });
      console.log(JSON.stringify({
        OMS订单状态: orderStatus,
        OMS标记: '异常网点不适用',
        发货仓库: '当前分支不执行 OMS/TMS 仓库操作，不适用',
        发货状态: abnormalNetworkUnshipped ? '未发货' : '已发货',
      }, null, 2));
      return omsAnalysis;
    }
    if (scenarioCode === ORDINARY_SCENARIO_CODES.GOOD_DEED_EXPEDITED_SHIPPING) {
      const omsAnalysis = {
        orderNumber,
        shippingWarehouse: null,
        warehouseStatus: 'not-applicable',
        warehouseSource: null,
        warehouseSelectionStrategy: null,
        warehouseCandidates: [],
        matchedWarehouse: null,
        isTargetWarehouse: null,
        isLowValue: null,
        isReissueOrder: null,
        orderStatus,
        markText: null,
      };
      writeProgress({
        step: 'oms-order-status-analyzed',
        omsAnalysis,
        omsWarehouseParse: {
          status: 'not-applicable',
          orderNumber,
          parsedValue: null,
          candidates: [],
          selectionStrategy: null,
          checkedAt: new Date().toISOString(),
          source: null,
        },
        manualReview: null,
        error: null,
        currentUrl: targetPage.url(),
        verificationStage: null,
      });
      console.log(JSON.stringify({
        OMS订单状态: orderStatus,
        发货仓库: '好人好事工单不适用',
      }, null, 2));
      return omsAnalysis;
    }

    let markText = null;
    let isLowValue = null;
    let isReissueOrder = null;
    if (scenarioCode !== 'abnormal-network-warning') {
      const markAnalysis = await readOmsOrderMark(
        targetPage,
        orderNumber,
        orderCell,
        rowScope,
        gridCells,
      );
      orderCell = markAnalysis.orderCell;
      rowScope = markAnalysis.rowScope;
      markText = markAnalysis.markText;
      isLowValue = markAnalysis.isLowValue;
      isReissueOrder = markAnalysis.isReissueOrder;
      writeProgress({ omsMarkSource: markAnalysis.source });
    }
    writeProgress({ step: 'oms-mark-analyzed', omsMarkText: markText, isLowValue, isReissueOrder });

    const firstOrderNumber = await findOmsSalesOrderCodeCell(
      targetPage, rowScope, gridCells, orderNumber,
    );
    if (!firstOrderNumber) throw new Error('OMS 查询结果没有可点击的订单号');
    await firstOrderNumber.click();

    const shippingDeadline = Date.now() + 30000;
    let shippingInfo = null;
    let lowerShippingDetail = { found: false, text: '', candidates: [] };
    while (Date.now() < shippingDeadline && !shippingInfo && !lowerShippingDetail.found) {
      shippingInfo = await firstVisible([
        targetPage.getByRole('tab', { name: /发货信息|物流信息|配送信息/ }),
        targetPage.getByText(/^(发货信息|物流信息|配送信息)$/, { exact: true }),
        targetPage.locator('[role="tab"]').filter({ hasText: /发货|物流|配送/ }),
      ]);
      if (!shippingInfo) {
        lowerShippingDetail = await readOmsLowerShippingDetail(targetPage);
        if (!lowerShippingDetail.found) await targetPage.waitForTimeout(1000);
      }
    }
    if (!shippingInfo && !lowerShippingDetail.found) throw new Error('OMS 订单详情未找到发货/物流信息区域');
    if (shippingInfo) {
      await shippingInfo.click({ force: true }).catch(async () => {
        // The order modal can re-render its tabs after the first lookup. Re-find
        // the live tab once instead of retrying a detached locator indefinitely.
        const liveShippingInfo = await firstVisible([
          targetPage.getByRole('tab', { name: /发货信息|物流信息|配送信息/ }),
          targetPage.getByText(/^(发货信息|物流信息|配送信息)$/, { exact: true }),
          targetPage.locator('[role="tab"]').filter({ hasText: /发货|物流|配送/ }),
        ]);
        if (!liveShippingInfo) throw new Error('OMS 订单弹窗发货/物流信息标签在重绘后不可用');
        await pacedAction(targetPage, 'open-oms-shipping-info', () => liveShippingInfo.click({ force: true }));
      });
    }

    const detailState = await readOmsAppState(targetPage);
    if (detailState.loginForm || detailState.loggedOut) {
      throw new Error('OMS 打开订单发货信息后返回登录页，仓库读取失败');
    }

    const shippingScope = await firstVisible([
      targetPage.locator('[role="dialog"]:visible'),
      targetPage.locator('.el-drawer:visible, .ant-drawer:visible'),
    ]);
    const shippingRoot = shippingScope || targetPage.locator('body');
    const warehouseDeadline = Date.now() + 30000;
    let shippingText = '';
    let warehouseText = null;
    let warehouseCandidates = [];
    let warehouseSelectionStrategy = null;
    while (Date.now() < warehouseDeadline && !warehouseText) {
      lowerShippingDetail = await readOmsLowerShippingDetail(targetPage);
      shippingText = shippingScope
        ? await shippingRoot.innerText().catch(() => '')
        : lowerShippingDetail.text || await shippingRoot.innerText().catch(() => '');
      const domWarehouseCandidates = await readOmsWarehouseCandidates(shippingRoot);
      const domWarehouse = domWarehouseCandidates.find((candidate) => (
        isValidOmsWarehouseValue(candidate)
        && omsWarehouseKeywords.some((keyword) => candidate.includes(keyword))
      ));
      const warehouseSelection = selectFirstOmsWarehouseCandidate(
        lowerShippingDetail.rowWarehouses.length
          ? lowerShippingDetail.rowWarehouses
          : (!shippingScope && lowerShippingDetail.candidates.length
              ? lowerShippingDetail.candidates
              : domWarehouseCandidates),
      );
      warehouseCandidates = warehouseSelection.candidates;
      warehouseSelectionStrategy = warehouseSelection.value
        ? warehouseSelection.strategy
        : 'text-fallback';
      warehouseText = warehouseSelection.value
        || domWarehouse
        || extractOmsWarehouseValue(shippingText);
      if (!warehouseText) await targetPage.waitForTimeout(1000);
    }
    const matchedWarehouse = omsWarehouseKeywords.find((keyword) => (
      warehouseText && warehouseText.includes(keyword)
    )) || null;
    const warehouseScope = inspectOmsWarehouseScope(warehouseText);
    const warehouseStatus = !isValidOmsWarehouseValue(warehouseText)
      ? 'read-failed'
      : warehouseScope.status === 'confirmed' ? 'confirmed' : 'out-of-scope';
    if (warehouseStatus !== 'confirmed') {
      writeProgress({
        omsWarehouseParse: {
          status: warehouseStatus,
          orderNumber,
          rawShippingText: shippingText.slice(0, 12000),
          parsedValue: warehouseText,
          candidates: warehouseCandidates,
          selectionStrategy: warehouseSelectionStrategy,
          checkedAt: new Date().toISOString(),
          source: shippingScope ? 'dialog-or-drawer' : 'lower-shipping-detail',
        },
        manualReview: null,
      });
      if (warehouseStatus === 'out-of-scope') {
        await pauseForManualReview(
          targetPage,
          'oms-warehouse-out-of-scope',
          `OMS 发货仓库“${warehouseText}”不在业务处理范围，已禁止进入 TMS 和拼多多提交`,
        );
      }
      await pauseForTransientRetry(
        targetPage,
        'oms-order-analysis',
        'OMS_WAREHOUSE_TEMPORARILY_UNAVAILABLE',
        'OMS 已有物流信息，但未能读取发货仓库',
      );
    }
    const omsAnalysis = {
      orderNumber,
      shippingWarehouse: warehouseText,
      warehouseStatus,
      warehouseSource: shippingScope ? 'dialog-or-drawer' : 'lower-shipping-detail',
      warehouseSelectionStrategy,
      warehouseCandidates,
      matchedWarehouse,
      isTargetWarehouse: Boolean(matchedWarehouse),
      isLowValue,
      isReissueOrder,
      orderStatus,
      markText,
    };
    writeProgress({
      step: 'oms-order-analyzed',
      omsAnalysis,
      omsWarehouseParse: {
        status: 'confirmed',
        orderNumber,
        parsedValue: warehouseText,
        candidates: warehouseCandidates.length ? warehouseCandidates : [warehouseText],
        selectionStrategy: warehouseSelectionStrategy,
        checkedAt: new Date().toISOString(),
        source: omsAnalysis.warehouseSource,
      },
      manualReview: null,
      error: null,
      currentUrl: targetPage.url(),
      verificationStage: null,
    });
    console.log(JSON.stringify({
      发货仓库: warehouseText,
      命中指定仓库: matchedWarehouse,
      是否是低值品: isLowValue,
      是否是补发单: isReissueOrder,
      OMS订单状态: orderStatus,
    }, null, 2));
    return omsAnalysis;
  } catch (error) {
    await saveOmsDiagnostics(targetPage, error.message);
    throw error;
  }
};

const analyzeOmsOrder = async (targetPage, browserContext, orderNumber) => withOmsSessionLock(
  `oms-order-analysis:${orderNumber}`,
  (sharedPage, sharedContext) => analyzeOmsOrderUnlocked(
    sharedPage || targetPage,
    sharedContext || browserContext,
    orderNumber,
  ),
);

const ensureOmsWarehouseMutationAllowed = async (targetPage, orderNumber, operation) => {
  const progress = readProgress();
  const analysis = progress.omsAnalysis?.orderNumber === orderNumber
    ? progress.omsAnalysis : null;
  const parsed = progress.omsWarehouseParse?.orderNumber === orderNumber
    ? progress.omsWarehouseParse : null;
  const warehouse = analysis?.shippingWarehouse || parsed?.parsedValue || null;
  const scope = inspectOmsWarehouseScope(warehouse);
  if (scope.status === 'confirmed') return scope;
  if (scope.status === 'read-failed') {
    await pauseForTransientRetry(
      targetPage,
      'oms-order-analysis',
      'OMS_WAREHOUSE_TEMPORARILY_UNAVAILABLE',
      `OMS 发货仓库尚未可靠读取，禁止执行${operation}`,
    );
  }
  const reason = scope.status === 'ambiguous'
    ? `OMS 发货仓库“${warehouse}”匹配多个业务仓库，已禁止执行${operation}`
    : `OMS 发货仓库“${warehouse}”不在业务处理范围，已禁止执行${operation}`;
  writeProgress({
    omsAnalysis: analysis ? { ...analysis, warehouseStatus: 'out-of-scope' } : progress.omsAnalysis,
    omsWarehouseParse: {
      ...(parsed || {}),
      status: 'out-of-scope',
      orderNumber,
      parsedValue: warehouse,
      checkedAt: new Date().toISOString(),
      source: parsed?.source || 'pre-mutation-scope-guard',
    },
  });
  await pauseForManualReview(
    targetPage,
    'oms-warehouse-out-of-scope',
    reason,
    { omsWarehouseScope: scope, blockedOperation: operation },
  );
  throw new Error(reason);
};

const findOmsOrderQueryInput = async (targetPage) => firstVisible([
  targetPage.getByRole('textbox', { name: /OMS编号/i }),
  targetPage.getByPlaceholder(/OMS编号|请输入.*OMS/i),
  targetPage.getByPlaceholder('订单编号/交易号/配货单号', { exact: true }),
  targetPage.locator('input[placeholder*="OMS" i], input[name*="oms" i]'),
]);

const fillReadyOmsOrderQueryInput = async (
  targetPage,
  orderNumber,
  { preferredInput = null, timeoutMs = 30_000 } = {},
) => {
  const boundedTimeoutMs = Math.max(1_000, Math.min(30_000, timeoutMs));
  const deadline = Date.now() + boundedTimeoutMs;
  let input = preferredInput;
  let lastError = null;
  while (Date.now() < deadline) {
    await closeUnexpectedOmsPopups(targetPage);
    if (!input
      || !await input.isVisible().catch(() => false)
      || !await input.isEditable().catch(() => false)) {
      input = await findOmsOrderQueryInput(targetPage);
    }
    if (input
      && await input.isVisible().catch(() => false)
      && await input.isEditable().catch(() => false)) {
      try {
        await input.fill(orderNumber, {
          timeout: Math.max(500, Math.min(3_000, deadline - Date.now())),
        });
        if (String(await input.inputValue().catch(() => '')).trim() === orderNumber) return input;
        lastError = new Error('OMS 订单查询输入框填值后未保持订单号');
      } catch (error) {
        lastError = error;
      }
    }
    input = null;
    await targetPage.waitForTimeout(Math.min(250, Math.max(1, deadline - Date.now())));
  }
  const error = new LogisticsRetryRequiredError(
    'oms-order-query-input-transient',
    `OMS_QUERY_INPUT_TEMPORARILY_UNAVAILABLE: OMS 订单查询输入框等待 ${boundedTimeoutMs}ms 后仍不可编辑${lastError ? `：${lastError.message}` : ''}`,
    30_000,
    { orderNumber, transientSystem: 'OMS' },
  );
  error.code = 'OMS_QUERY_INPUT_TEMPORARILY_UNAVAILABLE';
  throw error;
};

const ensureOmsOrderManagementPage = async (
  targetPage,
  browserContext,
  { maxAttempts = 2, timeoutMs = 45000 } = {},
) => {
  let input = await findOmsOrderQueryInput(targetPage);
  if (input) return input;

  let lastError = null;
  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      await ensureOmsLogin(targetPage, browserContext);
      await closeUnexpectedOmsPopups(targetPage);
      input = await findOmsOrderQueryInput(targetPage);
      if (input) return input;

      const orderMenu = await firstVisible([
        targetPage.getByRole('menuitem', { name: /^订单$/ }),
        targetPage.getByRole('link', { name: /^订单$/ }),
        targetPage.getByText(/^订单$/, { exact: true }),
      ]);
      if (!orderMenu) throw new Error('OMS 首页未找到“订单”入口');
      await orderMenu.hover().catch(() => {});
      await orderMenu.click();

      const menuDeadline = Date.now() + 10000;
      let orderManagement = null;
      while (Date.now() < menuDeadline && !orderManagement) {
        const visibleSubMenu = targetPage.locator('.sub-menu-wrapper:visible');
        orderManagement = await firstVisible([
          visibleSubMenu.getByText(/^订单管理$/, { exact: true }),
          visibleSubMenu.getByText(/订单管理/),
          targetPage.getByRole('menuitem', { name: /^订单管理$/ }),
          targetPage.getByText(/^订单管理$/, { exact: true }),
        ]);
        if (!orderManagement) await targetPage.waitForTimeout(250);
      }
      if (!orderManagement) throw new Error('OMS“订单”子菜单未找到“订单管理”');
      await orderManagement.click();

      const inputDeadline = Date.now() + timeoutMs;
      while (Date.now() < inputDeadline) {
        input = await findOmsOrderQueryInput(targetPage);
        if (input) return input;
        const state = await readOmsAppState(targetPage);
        if (targetPage.url().includes('/xianma/login') || state.loginForm || state.loggedOut) {
          throw new Error('OMS 点击订单管理后返回登录页，登录状态已失效');
        }
        await targetPage.waitForTimeout(500);
      }
      throw new Error('OMS 订单管理页面未渲染订单查询输入框');
    } catch (error) {
      lastError = error;
      if (attempt < maxAttempts) {
        const previousUrl = targetPage.url();
        const refreshStartedAt = new Date().toISOString();
        writeProgress({
          step: 'oms-order-management-render-recovering',
          omsOrderManagementRecovery: {
            attempt,
            maxAttempts,
            previousUrl,
            trigger: error.message,
            refreshStartedAt,
          },
          manualReview: null,
          error: null,
        });
        logRunStep('oms-order-management-render-refresh', {
          attempt,
          maxAttempts,
          previousUrl,
          trigger: error.message,
        });
        const refreshError = await targetPage.reload({
          waitUntil: 'domcontentloaded',
          timeout: 30_000,
        }).then(() => null).catch((reloadError) => reloadError);
        writeProgress({
          omsOrderManagementRecovery: {
            attempt,
            maxAttempts,
            previousUrl,
            trigger: error.message,
            refreshStartedAt,
            refreshCompletedAt: new Date().toISOString(),
            refreshError: refreshError?.message || null,
          },
        });
        await targetPage.waitForTimeout(500);
      }
    }
  }

  throw lastError || new Error('OMS 无法进入订单管理页面');
};

const queryOmsOrderRow = async (
  targetPage,
  orderNumber,
  { timeoutMs = 45000, browserContext = context } = {},
) => {
  let loginRecoveryAttempted = false;
  let lastQueryError = null;
  for (let attempt = 1; attempt <= 2; attempt++) {
    try {
      let input = await findOmsOrderQueryInput(targetPage);
      const initialState = await readOmsAppState(targetPage);
      if (targetPage.url().includes('/xianma/login')
        || initialState.loginForm
        || initialState.loggedOut) {
        loginRecoveryAttempted = true;
        writeProgress({
          step: 'oms-query-login-recovering',
          omsQueryLoginRecovery: {
            orderNumber,
            status: 'recovering',
            attemptedAt: new Date().toISOString(),
          },
        });
        await ensureOmsLogin(targetPage, browserContext);
        input = await ensureOmsOrderManagementPage(targetPage, browserContext, {
          maxAttempts: 1,
          timeoutMs: 30_000,
        });
      }
      input = await fillReadyOmsOrderQueryInput(targetPage, orderNumber, {
        preferredInput: input,
        timeoutMs: Math.min(30_000, timeoutMs),
      });
      const queryButton = await firstVisible([
        targetPage.getByRole('button', { name: /^(查询|搜索)$/ }),
        targetPage.getByText(/^(查询|搜索)$/, { exact: true }),
      ]);
      if (!queryButton) throw new Error('OMS 订单页未找到查询按钮');
      const queryResponsePromise = targetPage.waitForResponse((response) => {
        if (response.request().method() !== 'POST'
          || !response.url().includes('/trade/sales/v2/postListPage')) return false;
        return String(response.request().postData() || '').includes(orderNumber);
      }, { timeout: Math.min(15000, timeoutMs) }).catch(() => null);
      await queryButton.click({ force: true });
      const queryResponse = await queryResponsePromise;
      let omsApiOrderState = null;
      if (queryResponse) {
        const responsePayload = await queryResponse.json().catch(() => null);
        const responseRows = Array.isArray(responsePayload?.data?.data)
          ? responsePayload.data.data
          : [];
        const responseOrder = responseRows.find((row) => (
          String(row?.tradeId || '').trim() === String(orderNumber).trim()
        ));
        if (responseOrder) {
          omsApiOrderState = {
            orderNumber: String(responseOrder.tradeId || '').trim(),
            salesOrderId: responseOrder.salesOrderId || null,
            status: responseOrder.status || null,
            dispatchStatus: responseOrder.dispatchStatus || null,
            deliveryStatus: responseOrder.deliveryStatus || null,
            payStatus: responseOrder.payStatus || null,
            prerefund: Boolean(responseOrder.prerefund),
            riskControl: Boolean(responseOrder.riskControl),
            productAbnormal: Boolean(responseOrder.productAbnormal),
            changeWarehouseStatus: responseOrder.changeWarehouseStatus || null,
            modifiedTime: responseOrder.modifiedTime || null,
          };
        }
      } else {
        // A cached row can still be present for the same order number. Give the
        // grid a bounded redraw window before reading it as a fallback.
        await targetPage.waitForTimeout(800);
      }
      const deadline = Date.now() + timeoutMs;
      let orderResult = null;
      while (Date.now() < deadline && !orderResult) {
        const state = await readOmsAppState(targetPage);
        if (targetPage.url().includes('/xianma/login') || state.loginForm || state.loggedOut) {
          loginRecoveryAttempted = true;
          throw new Error('OMS 查询过程中登录态失效');
        }
        orderResult = await findVisibleOmsOrderRow(targetPage, orderNumber, {
          timeoutMs: Math.min(1500, Math.max(1, deadline - Date.now())),
          pollIntervalMs: 250,
        });
      }
      if (!orderResult) throw new Error(`OMS 查询未返回订单号: ${orderNumber}`);
      const { orderCell, rowScope } = orderResult;
      return { input, queryButton, orderCell, rowScope, omsApiOrderState };
    } catch (error) {
      lastQueryError = error;
      if (attempt >= 2) break;
      const previousUrl = targetPage.url();
      writeProgress({
        step: 'oms-order-query-refreshing',
        omsOrderQueryRecovery: {
          orderNumber,
          status: 'refreshing',
          completedPasses: attempt,
          timeoutMsPerPass: Math.min(30_000, timeoutMs),
          previousUrl,
          lastError: error.message,
          refreshedAt: new Date().toISOString(),
        },
        manualReview: null,
        error: null,
      });
      await targetPage.reload({ waitUntil: 'domcontentloaded', timeout: 45_000 }).catch(() => {});
      if (loginRecoveryAttempted) await ensureOmsLogin(targetPage, browserContext);
      await ensureOmsOrderManagementPage(targetPage, browserContext, {
        maxAttempts: 1,
        timeoutMs: 30_000,
      }).catch((recoveryError) => {
        lastQueryError = recoveryError;
      });
      await closeUnexpectedOmsPopups(targetPage);
    }
  }
  const queryError = new LogisticsRetryRequiredError(
    'oms-order-query-transient',
    `OMS_QUERY_TEMPORARILY_UNAVAILABLE: OMS 查询等待并刷新后仍未返回订单号: ${orderNumber}${lastQueryError ? `；${lastQueryError.message}` : ''}`,
    30_000,
    { orderNumber, transientSystem: 'OMS', loginRecoveryAttempted },
  );
  queryError.code = 'OMS_QUERY_TEMPORARILY_UNAVAILABLE';
  writeProgress({
    step: 'oms-order-query-retry-ready',
    omsOrderQueryRecovery: {
      orderNumber,
      status: 'retry-ready',
      completedPasses: 2,
      timeoutMsPerPass: Math.min(30_000, timeoutMs),
      lastError: lastQueryError?.message || null,
      retryAfterMs: queryError.retryAfterMs,
      failedAt: new Date().toISOString(),
    },
    manualReview: null,
  });
  throw queryError;
};

const closeOmsManualAllocationDialog = async (targetPage) => {
  const dialog = await firstVisible([
    targetPage.getByRole('dialog').filter({ hasText: /手工配货/ }),
    targetPage.locator('.el-dialog:visible').filter({ hasText: /手工配货/ }),
  ]);
  if (!dialog) return false;
  const close = await firstVisible([
    dialog.getByRole('button', { name: /关闭/ }),
    dialog.locator('.el-dialog__headerbtn'),
    dialog.locator('[aria-label="Close"], [aria-label="关闭"]'),
  ]);
  if (!close) return false;
  await close.click({ force: true }).catch(() => {});
  await dialog.waitFor({ state: 'hidden', timeout: 10000 }).catch(() => {});
  return true;
};

const selectOmsOrderRow = async (rowScope, orderCell, targetPage = null) => {
  const rowIndex = await rowScope.getAttribute('row-index').catch(() => null);
  const ariaRowIndex = await rowScope.getAttribute('aria-rowindex').catch(() => null);
  const escapeAttribute = (value) => String(value).replace(/\\/g, '\\\\').replace(/"/g, '\\"');
  const findRowCheckbox = async () => {
    const relatedRows = [rowScope];
    if (targetPage && rowIndex !== null) {
      const escaped = escapeAttribute(rowIndex);
      relatedRows.push(
        targetPage.locator(`.ag-pinned-left-cols-container .ag-row[row-index="${escaped}"]`),
        targetPage.locator(`.ag-pinned-right-cols-container .ag-row[row-index="${escaped}"]`),
      );
    }
    if (targetPage && ariaRowIndex !== null) {
      const escaped = escapeAttribute(ariaRowIndex);
      relatedRows.push(targetPage.locator(`[role="row"][aria-rowindex="${escaped}"]`));
    }
    const checkbox = await firstVisible([
      ...relatedRows.map((row) => row.getByRole('checkbox')),
      ...relatedRows.map((row) => row.locator('.el-checkbox')),
      ...relatedRows.map((row) => row.locator('input[type="checkbox"]')),
    ]);
    return { checkbox, relatedRows };
  };
  const rowIsSelected = async (checkbox, relatedRows) => {
    if (!checkbox) return false;
    const checkboxSelected = await checkbox.evaluate((node) => {
      const input = node.matches('input[type="checkbox"]')
        ? node
        : node.querySelector('input[type="checkbox"]');
      return Boolean(
        input?.checked
        || node.getAttribute('aria-checked') === 'true'
        || input?.getAttribute('aria-checked') === 'true'
        || node.classList.contains('is-checked')
        || node.classList.contains('ag-checked')
        || node.closest('.is-checked, .ag-checked'),
      );
    }).catch(() => false);
    if (checkboxSelected) return true;
    for (const relatedRow of relatedRows) {
      const selected = await relatedRow.evaluate((node) => (
        node.getAttribute('aria-selected') === 'true'
        || node.classList.contains('ag-row-selected')
      )).catch(() => false);
      if (selected) return true;
    }
    return false;
  };
  let checkbox = null;
  let relatedRows = [];
  let selected = false;
  for (let attempt = 1; attempt <= 3 && !selected; attempt += 1) {
    ({ checkbox, relatedRows } = await findRowCheckbox());
    if (!checkbox) {
      if (attempt < 3 && targetPage) await targetPage.waitForTimeout(250);
      continue;
    }
    if (!await rowIsSelected(checkbox, relatedRows)) {
      await checkbox.click({ force: true, noWaitAfter: true });
    }
    const deadline = Date.now() + 2_000;
    while (Date.now() < deadline) {
      ({ checkbox, relatedRows } = await findRowCheckbox());
      if (await rowIsSelected(checkbox, relatedRows)) {
        selected = true;
        break;
      }
      if (targetPage) await targetPage.waitForTimeout(100);
      else break;
    }
  }
  if (!selected) {
    const error = new LogisticsRetryRequiredError(
      'oms-order-row-selection-transient',
      'OMS_ORDER_ROW_SELECTION_TEMPORARILY_UNAVAILABLE: OMS 目标订单行选择框重渲染后仍未保持选中',
      30_000,
      { transientSystem: 'OMS' },
    );
    error.code = 'OMS_ORDER_ROW_SELECTION_TEMPORARILY_UNAVAILABLE';
    throw error;
  }
  // The row is already selected by the checkbox. OMS sometimes starts a SPA
  // transition from this focus click and never settles Playwright's navigation
  // wait even though the row selection succeeded.
  await orderCell.click({ force: true, noWaitAfter: true, timeout: 10_000 }).catch(async (error) => {
    ({ checkbox, relatedRows } = await findRowCheckbox());
    const stillSelected = await rowIsSelected(checkbox, relatedRows);
    if (!stillSelected) throw error;
  });
};

const closeOmsBatchResendDialog = async (targetPage) => {
  const dialog = await firstVisible([
    targetPage.getByRole('dialog').filter({ hasText: /批量补发/ }),
    targetPage.locator('.el-dialog:visible').filter({ hasText: /批量补发/ }),
  ]);
  if (!dialog) return false;
  const close = await firstVisible([
    dialog.locator('.el-dialog__headerbtn'),
    dialog.getByRole('button', { name: /关闭/ }),
    dialog.locator('[aria-label="Close"], [aria-label="关闭"]'),
  ]);
  if (!close) throw new Error('OMS 批量补发弹窗已打开，但未找到关闭按钮');
  await close.click({ force: true });
  await dialog.waitFor({ state: 'hidden', timeout: 10000 }).catch(() => {});
  return true;
};

const openOmsManualAllocationDialog = async (targetPage, orderCell) => {
  const findAction = () => firstVisible([
    targetPage.getByRole('menuitem', { name: '手工配货', exact: true }),
    targetPage.getByText('手工配货', { exact: true }),
  ]);
  const waitForAction = async () => {
    const deadline = Date.now() + 3_000;
    do {
      const candidate = await findAction();
      if (candidate) return candidate;
      await targetPage.waitForTimeout(100);
    } while (Date.now() < deadline);
    return null;
  };
  await closeOmsBatchResendDialog(targetPage);
  let action = await findAction();
  if (!action) {
    const moreActions = await firstVisible([
      targetPage.getByRole('button', { name: /^更多操作/ }),
      targetPage.locator('.el-dropdown').filter({ hasText: /^更多操作/ }),
      targetPage.getByText('更多操作', { exact: true }),
    ]);
    if (moreActions) {
      await moreActions.click({ force: true });
      action = await waitForAction();
    }
  }
  if (!action && orderCell) {
    // OMS exposes per-order actions through AG Grid's row context menu. The
    // top toolbar's “补发” button is a separate batch-resend operation.
    await orderCell.click({ button: 'right', force: true });
    action = await waitForAction();
    if (!action) {
      const contextMenu = await firstVisible([
        targetPage.locator('[role="menu"]:visible').last(),
        targetPage.locator('.el-popper:visible').last(),
        targetPage.locator('.context-menu:visible, .ag-menu:visible').last(),
      ]);
      if (contextMenu) {
        const nestedMenus = contextMenu.locator([
          '[role="menuitem"]',
          '.el-dropdown-menu__item',
          '.el-menu-item',
          'li',
        ].join(',')).filter({ hasText: /^(?:商品操作|采购业务操作|更多操作|配货操作)$/ });
        for (let index = 0; index < await nestedMenus.count().catch(() => 0); index++) {
          const nestedMenu = nestedMenus.nth(index);
          if (!await nestedMenu.isVisible().catch(() => false)) continue;
          await nestedMenu.hover();
          action = await waitForAction();
          if (action) break;
        }
      }
    }
  }
  if (!action) throw new Error('OMS 订单行右键菜单未找到“手工配货”');
  await action.click({ force: true });
  const dialog = await firstVisible([
    targetPage.getByRole('dialog').filter({ hasText: /手工配货/ }),
    targetPage.locator('.el-dialog:visible').filter({ hasText: /手工配货/ }),
  ]);
  if (!dialog) {
    const candidate = targetPage.locator('.el-dialog:visible').filter({ hasText: /手工配货/ }).first();
    await candidate.waitFor({ state: 'visible', timeout: 30000 }).catch(() => {});
    if (await candidate.isVisible().catch(() => false)) return candidate;
    throw new Error('OMS 点击手工配货后弹窗未出现');
  }
  return dialog;
};

const addAllOmsManualAllocationItems = async (targetPage, dialog) => {
  const sourceTable = dialog.locator('.el-table').first();
  const sourceAddButtons = sourceTable.getByText('添加', { exact: true });
  const renderTimeoutMs = Math.max(
    5000,
    Math.min(120_000, Number(process.env.OMS_MANUAL_ALLOCATION_RENDER_TIMEOUT_MS || 30_000)),
  );
  const loadingIndicators = dialog.locator([
    '.el-loading-mask:visible',
    '.el-loading-spinner:visible',
    '.el-icon-loading:visible',
    '[aria-busy="true"]:visible',
  ].join(','));
  const dialogIsLoading = async () => {
    for (let index = 0; index < await loadingIndicators.count().catch(() => 0); index += 1) {
      if (await loadingIndicators.nth(index).isVisible().catch(() => false)) return true;
    }
    return false;
  };
  const sourceReadyDeadline = Date.now() + renderTimeoutMs;
  let visibleSourceItemCount = 0;
  while (Date.now() < sourceReadyDeadline && !visibleSourceItemCount) {
    if (!await dialogIsLoading()) {
      for (let index = 0; index < await sourceAddButtons.count().catch(() => 0); index += 1) {
        const candidate = sourceAddButtons.nth(index);
        if (await candidate.isVisible().catch(() => false)
          && await candidate.isEnabled().catch(() => true)) visibleSourceItemCount += 1;
      }
    }
    if (!visibleSourceItemCount) await targetPage.waitForTimeout(300);
  }
  if (!visibleSourceItemCount) {
    throw new Error(`OMS 手工配货商品明细在 ${Math.round(renderTimeoutMs / 1000)} 秒内未加载完成`);
  }
  const targetTable = dialog.locator('.el-table').nth(1);
  const selectedRows = targetTable
    .locator('.el-table__body-wrapper tbody tr, tbody .el-table__row')
    .filter({ hasNotText: '暂无数据' });
  const readSelectedItemCount = async () => {
    const rowCount = await selectedRows.count().catch(() => 0);
    const summaryText = await dialog.getByText(/已选配货数量/).first().innerText().catch(() => '');
    const summaryCount = Number(summaryText.match(/已选配货数量\s*[：:]?\s*(\d+)/)?.[1] || 0);
    return Math.max(rowCount, summaryCount);
  };
  for (let attempt = 0; attempt < 20; attempt += 1) {
    let nextAddButton = null;
    for (let index = (await sourceAddButtons.count().catch(() => 0)) - 1; index >= 0; index -= 1) {
      const candidate = sourceAddButtons.nth(index);
      if (await candidate.isVisible().catch(() => false)
        && await candidate.isEnabled().catch(() => true)) {
        nextAddButton = candidate;
        break;
      }
    }
    if (!nextAddButton) break;
    const selectedBeforeClick = await readSelectedItemCount();
    await nextAddButton.click({ timeout: 10_000 });
    const updateDeadline = Date.now() + 5000;
    let itemAdded = false;
    while (Date.now() < updateDeadline && !itemAdded) {
      const selectedAfterClick = await readSelectedItemCount();
      itemAdded = selectedAfterClick > selectedBeforeClick
        || !await nextAddButton.isVisible().catch(() => false);
      if (!itemAdded) await targetPage.waitForTimeout(250);
    }
    if (!itemAdded) throw new Error('OMS 手工配货点击“添加”后配货明细未更新');
  }
  const selectedDeadline = Date.now() + 5000;
  let selectedItemCount = 0;
  while (Date.now() < selectedDeadline && !selectedItemCount) {
    selectedItemCount = await readSelectedItemCount();
    if (!selectedItemCount) await targetPage.waitForTimeout(300);
  }
  if (!selectedItemCount) {
    throw new Error('OMS 手工配货未将任何商品加入配货明细，禁止生成空配货单');
  }
  const remainingText = await dialog.getByText(/原商品剩余数量/).first().innerText().catch(() => '');
  const remainingMatch = remainingText.match(/原商品剩余数量\s*[：:]?\s*(\d+)/);
  const remainingItemCount = remainingMatch ? Number(remainingMatch[1]) : null;
  if (remainingItemCount !== 0) {
    throw new Error(
      `OMS 手工配货仍有未添加商品（剩余: ${remainingItemCount == null ? '未读取到' : remainingItemCount}）`,
    );
  }
  return { selectedItemCount, remainingItemCount };
};

const enableOmsManualAllocationWithoutInventoryCheck = async (dialog) => {
  const label = dialog.getByText('不校验库存', { exact: true }).first();
  if (!await label.count().catch(() => 0)) throw new Error('OMS 手工配货弹窗未找到“不校验库存”');
  const checkbox = await firstVisible([
    label.locator('xpath=ancestor::*[contains(concat(" ", normalize-space(@class), " "), " el-checkbox ")][1]'),
    label.locator('xpath=preceding::input[@type="checkbox"][1]'),
  ]);
  if (!checkbox) throw new Error('OMS 手工配货弹窗未找到“不校验库存”选择框');
  const input = checkbox.locator('input[type="checkbox"]').first();
  const isChecked = async () => (
    input.isChecked().catch(() => (
      checkbox.getAttribute('aria-checked').then((value) => value === 'true').catch(() => false)
    ))
  );
  if (!await isChecked()) await checkbox.click({ force: true });
  if (!await isChecked()) throw new Error('OMS 手工配货无法启用“不校验库存”');
  return { inventoryCheckBypassed: true };
};

const chooseOmsManualAllocationCarrier = async (
  targetPage,
  dialog,
  recommendedCarriers,
  { allowFirstAvailable = false } = {},
) => {
  const carrierLabel = dialog.getByText('发货快递', { exact: true }).first();
  if (!await carrierLabel.count().catch(() => 0)) throw new Error('OMS 手工配货弹窗未找到“发货快递”');
  const carrierFormItem = carrierLabel.locator(
    'xpath=ancestor::*[contains(concat(" ", normalize-space(@class), " "), " el-form-item ")][1]',
  );
  const carrierSelect = await firstVisible([
    carrierFormItem.locator('.el-select').first(),
    carrierFormItem.getByRole('combobox').first(),
    carrierLabel.locator('xpath=following::*[contains(@class,"el-select")][1]'),
    carrierLabel.locator('xpath=following::input[@placeholder="请选择"][1]'),
  ]);
  if (!carrierSelect) throw new Error('OMS 手工配货弹窗未找到发货快递下拉框');
  const carrierTrigger = await firstVisible([
    carrierSelect.locator('.el-select__wrapper').first(),
    carrierSelect.getByRole('combobox').first(),
    carrierSelect,
  ]);
  const carrierCombobox = carrierSelect.getByRole('combobox').first();
  const controlledListId = await carrierCombobox.getAttribute('aria-controls').catch(() => null);
  const controlledOptions = controlledListId
    ? targetPage.locator(`[id="${controlledListId}"] [role="option"]:visible:not([aria-disabled="true"])`)
    : null;
  const optionLocators = [
    controlledOptions,
    targetPage.locator('.el-popper:visible .el-select-dropdown__item:not(.is-disabled)'),
    targetPage.locator('.el-select-dropdown:visible .el-select-dropdown__item:not(.is-disabled)'),
    targetPage.locator('[role="listbox"]:visible [role="option"]:not([aria-disabled="true"])'),
  ].filter(Boolean);
  const deadline = Date.now() + 15000;
  let options = [];
  let lastOpenAttemptAt = 0;
  while (Date.now() < deadline && !options.length) {
    for (const locator of optionLocators) {
      const texts = await locator.allInnerTexts().catch(() => []);
      options.push(...texts.map((value) => value.trim()).filter((value) => value && value !== '暂无数据'));
    }
    options = [...new Set(options)];
    if (!options.length && Date.now() - lastOpenAttemptAt >= 2000) {
      const expanded = await carrierCombobox.getAttribute('aria-expanded').catch(() => null);
      if (expanded === 'true') {
        await carrierCombobox.press('Escape').catch(() => {});
        await targetPage.waitForTimeout(100);
      }
      await carrierTrigger.click({ force: true }).catch(() => {});
      if (await carrierCombobox.getAttribute('aria-expanded').catch(() => null) !== 'true') {
        await carrierCombobox.press('ArrowDown').catch(() => {});
      }
      lastOpenAttemptAt = Date.now();
    }
    if (!options.length) await targetPage.waitForTimeout(500);
  }
  const selected = selectRecommendedOmsCarrier(recommendedCarriers, options) || (
    allowFirstAvailable && options.length
      ? {
          recommendedCarrier: null,
          omsCarrier: options[0],
          selectionStrategy: 'first-available-by-business-rule',
        }
      : null
  );
  if (!selected) {
    const expanded = await carrierCombobox.getAttribute('aria-expanded').catch(() => null);
    throw new Error(
      `OMS 发货快递没有平台建议选项，可用快递: ${options.join('、') || '无'}`
      + `（下拉展开: ${expanded || '未知'}，列表: ${controlledListId || '未绑定'}）`,
    );
  }
  let selectedOption = null;
  for (let attempt = 0; attempt < 3 && !selectedOption; attempt += 1) {
    for (const locator of optionLocators) {
      for (let index = 0; index < await locator.count().catch(() => 0); index++) {
        const option = locator.nth(index);
        if ((await option.innerText().catch(() => '')).trim() !== selected.omsCarrier) continue;
        if (await option.isVisible().catch(() => false)) {
          selectedOption = option;
          break;
        }
      }
      if (selectedOption) break;
    }
    if (!selectedOption) {
      if (await carrierCombobox.getAttribute('aria-expanded').catch(() => null) === 'true') {
        await carrierCombobox.press('Escape').catch(() => {});
        await targetPage.waitForTimeout(100);
      }
      await carrierTrigger.click({ force: true }).catch(() => {});
      await targetPage.waitForTimeout(500);
    }
  }
  if (!selectedOption) throw new Error(`OMS 无法点击已匹配的发货快递: ${selected.omsCarrier}`);
  await selectedOption.click({ force: true });
  await targetPage.waitForTimeout(500);
  return selected;
};

const verifyOmsOrderAllocated = async (targetPage, orderNumber, {
  timeoutMs = Math.max(45_000, Number(process.env.OMS_ALLOCATION_VERIFY_TIMEOUT_MS || 120_000)),
} = {}) => {
  const deadline = Date.now() + timeoutMs;
  let lastStatus = null;
  let lastError = null;
  while (Date.now() < deadline) {
    try {
      const { rowScope, omsApiOrderState } = await queryOmsOrderRow(targetPage, orderNumber, {
        timeoutMs: Math.min(10000, Math.max(1000, deadline - Date.now())),
      });
      lastStatus = omsOrderStatusFromApiState(omsApiOrderState)
        || await readOmsOrderStatus(targetPage, rowScope);
      lastError = null;
      if (omsApiOrderStateHasPassedAllocation(omsApiOrderState)
        || omsOrderStatusHasPassedAllocation(lastStatus)) {
        return { status: lastStatus, rowScope, omsApiOrderState };
      }
    } catch (error) {
      lastError = error;
    }
    await targetPage.waitForTimeout(1500);
  }
  throw new Error(
    `OMS 生成配货单后未确认订单状态已越过配货阶段（当前: ${lastStatus || '未读取到'}`
    + `${lastError ? `，回查错误: ${lastError.message}` : ''}）`,
  );
};

const runOmsManualAllocation = async (
  targetPage,
  browserContext,
  orderNumber,
  recommendedCarriers,
  {
    effectOrderNumber = orderNumber,
    effectStage = 'generate-allocation-all-remaining-items-v3',
    progressField = 'omsManualAllocation',
    updatePrimaryOmsAnalysis = true,
    allowFirstAvailableCarrier = false,
  } = {},
) => {
  await ensureOmsWarehouseMutationAllowed(targetPage, orderNumber, 'OMS 配货操作');
  await ensureOmsOrderManagementPage(targetPage, browserContext);
  let { orderCell, rowScope, omsApiOrderState } = await queryOmsOrderRow(targetPage, orderNumber);
  let liveOrderStatus = omsOrderStatusFromApiState(omsApiOrderState)
    || await readOmsOrderStatus(targetPage, rowScope);
  if (liveOrderStatus) {
    const currentProgress = readProgress();
    writeProgress({
      omsOrderStatus: liveOrderStatus,
      omsAnalysis: {
        ...currentProgress.omsAnalysis,
        orderStatus: liveOrderStatus,
      },
      omsLiveOrderState: omsApiOrderState,
    });
  }
  if (omsApiOrderStateHasPassedAllocation(omsApiOrderState)
    || omsOrderStatusHasPassedAllocation(liveOrderStatus)) {
    const completed = {
      shopId,
      orderNumber,
      recommendedCarrier: recommendedCarriers[0] || null,
      omsCarrier: null,
      status: liveOrderStatus === '已配货' ? 'already-allocated' : 'already-past-allocation',
      verifiedOrderStatus: liveOrderStatus,
      completedAt: new Date().toISOString(),
    };
    writeProgress({
      step: 'oms-manual-allocation-not-required',
      [progressField]: completed,
      error: null,
    });
    await persistBrowserAuth(browserContext);
    return completed;
  }
  let dialog = null;
  let itemPreparation = null;
  for (let renderAttempt = 1; renderAttempt <= 2; renderAttempt += 1) {
    await selectOmsOrderRow(rowScope, orderCell, targetPage);
    dialog = await openOmsManualAllocationDialog(targetPage, orderCell);
    try {
      itemPreparation = await addAllOmsManualAllocationItems(targetPage, dialog);
      break;
    } catch (error) {
      const retryableRenderFailure = /OMS 手工配货(?:商品明细在 \d+ 秒内未加载完成|点击“添加”后配货明细未更新|未将任何商品加入配货明细)/u
        .test(String(error?.message || ''));
      if (!retryableRenderFailure || renderAttempt >= 2) throw error;
      writeProgress({
        step: 'oms-manual-allocation-render-reloading',
        omsManualAllocationRenderRecovery: {
          orderNumber,
          attempt: renderAttempt,
          error: error.message,
          reloadingAt: new Date().toISOString(),
        },
        error: null,
      });
      await closeOmsManualAllocationDialog(targetPage).catch(() => {});
      await targetPage.reload({ waitUntil: 'domcontentloaded', timeout: 60_000 });
      await ensureOmsOrderManagementPage(targetPage, browserContext);
      ({ orderCell, rowScope, omsApiOrderState } = await queryOmsOrderRow(targetPage, orderNumber));
      liveOrderStatus = omsOrderStatusFromApiState(omsApiOrderState)
        || await readOmsOrderStatus(targetPage, rowScope);
      if (omsApiOrderStateHasPassedAllocation(omsApiOrderState)
        || omsOrderStatusHasPassedAllocation(liveOrderStatus)) {
        const completed = {
          shopId,
          orderNumber,
          recommendedCarrier: recommendedCarriers[0] || null,
          omsCarrier: null,
          status: liveOrderStatus === '已配货' ? 'already-allocated' : 'already-past-allocation',
          verifiedOrderStatus: liveOrderStatus,
          completedAt: new Date().toISOString(),
        };
        writeProgress({
          step: 'oms-manual-allocation-not-required',
          [progressField]: completed,
          error: null,
        });
        await persistBrowserAuth(browserContext);
        return completed;
      }
    }
  }
  const inventoryPreparation = await enableOmsManualAllocationWithoutInventoryCheck(dialog);
  const selected = await chooseOmsManualAllocationCarrier(
    targetPage,
    dialog,
    recommendedCarriers,
    { allowFirstAvailable: allowFirstAvailableCarrier },
  );
  const generate = await firstVisible([
    dialog.getByRole('button', { name: '生成配货单', exact: true }),
    dialog.getByText('生成配货单', { exact: true }),
  ]);
  if (!generate) throw new Error('OMS 手工配货弹窗未找到“生成配货单”');
  if (!await generate.isEnabled().catch(() => true)) {
    throw new Error('OMS 手工配货商品或发货快递未准备完成，“生成配货单”仍不可用');
  }
  writeProgress({
    step: 'oms-manual-allocation-submitting',
    [progressField]: {
      shopId,
      orderNumber,
      ...selected,
      ...itemPreparation,
      ...inventoryPreparation,
      status: 'submitting',
      startedAt: new Date().toISOString(),
    },
  });
  const result = await guardedExternalEffect({
    effectType: 'oms-manual-allocation',
    orderNumber: effectOrderNumber,
    stage: effectStage,
    request: {
      queryOrderNumber: orderNumber,
      recommendedCarriers,
      ...selected,
      ...itemPreparation,
      ...inventoryPreparation,
    },
  }, async () => {
    await generate.click({ force: true });
    await targetPage.waitForTimeout(250);
    const confirmationCandidates = targetPage.locator(
      '.el-message-box:visible, [role="alertdialog"]:visible, .el-dialog:visible',
    );
    let confirmation = null;
    for (let index = 0; index < await confirmationCandidates.count().catch(() => 0); index++) {
      const candidate = confirmationCandidates.nth(index);
      const text = await candidate.innerText().catch(() => '');
      if (/手工配货/.test(text) && /订单明细|发货快递/.test(text)) continue;
      if (/确认|确定|生成配货单/.test(text)) {
        confirmation = candidate;
        break;
      }
    }
    if (confirmation) {
      const confirm = await firstVisible([
        confirmation.getByRole('button', { name: /^(确定|确认)$/ }),
        confirmation.getByText(/^(确定|确认)$/, { exact: true }),
      ]);
      if (confirm) await confirm.click({ force: true });
    }
    return { ...selected, submittedAt: new Date().toISOString() };
  });
  await closeOmsManualAllocationDialog(targetPage).catch(() => {});
  await ensureOmsOrderManagementPage(targetPage, browserContext);
  const verification = await verifyOmsOrderAllocated(targetPage, orderNumber);
  const completed = {
    shopId,
    orderNumber,
    ...selected,
    ...itemPreparation,
    ...inventoryPreparation,
    status: 'succeeded',
    alreadySucceeded: Boolean(result?.alreadySucceeded),
    verifiedOrderStatus: verification.status,
    completedAt: new Date().toISOString(),
  };
  writeProgress({
    step: 'oms-manual-allocation-succeeded',
    [progressField]: completed,
    ...(updatePrimaryOmsAnalysis ? {
      omsAnalysis: {
        ...readProgress().omsAnalysis,
        orderStatus: verification.status,
      },
    } : {}),
    error: null,
  });
  await persistBrowserAuth(browserContext);
  return completed;
};

const clickOmsWizardButton = async (targetPage, labels) => {
  const patterns = labels.map((label) => new RegExp(`^\\s*${label}\\s*$`, 'u'));
  const candidates = patterns.flatMap((pattern) => [
    targetPage.getByRole('button', { name: pattern }),
    targetPage.getByText(pattern).last(),
  ]);
  const button = await firstVisible(candidates);
  if (!button) throw new Error(`OMS 补发页面未找到按钮: ${labels.join(' / ')}`);
  await button.click({ force: true });
  return button;
};

const findOmsFlatBatchReissueDialog = async (targetPage) => {
  const heading = await firstVisible([
    targetPage.getByText('批量补发', { exact: true }),
  ]);
  if (!heading) return null;
  return firstVisible([
    heading.locator(
      'xpath=ancestor::*[@role="dialog"'
        + ' or contains(concat(" ",normalize-space(@class)," ")," el-dialog ")][1]',
    ),
    targetPage.locator('.el-dialog:visible')
      .filter({ hasText: '批量补发' }),
  ]);
};

const assertSingleOmsBatchReissueSelection = async (targetPage) => {
  const deadline = Date.now() + 2_000;
  let selectedCount = NaN;
  do {
    const bodyText = String(await targetPage.locator('body').innerText().catch(() => ''));
    selectedCount = Number(bodyText.match(/已选择\s*(\d+)\s*条/u)?.[1] || NaN);
    if (selectedCount === 1) return selectedCount;
    // A zero/missing count can lag behind a rerendered grid. Never accept the
    // checkbox appearance alone, or wait past an explicit multi-order count.
    if (selectedCount > 1 || Date.now() >= deadline) break;
    await targetPage.waitForTimeout(100);
  } while (Date.now() < deadline);
  if (selectedCount !== 1) {
    throw new Error(`OMS 批量补发已选择数量异常: ${Number.isFinite(selectedCount) ? selectedCount : '未读取到'}`);
  }
  return selectedCount;
};

const omsGridRowsForOrder = async (targetPage, orderNumber) => {
  const rows = targetPage.locator(
    '.ag-center-cols-container .ag-row, .el-table__body-wrapper tbody tr, tbody .el-table__row',
  );
  const matches = [];
  for (let index = 0; index < await rows.count().catch(() => 0); index++) {
    const row = rows.nth(index);
    if (!await row.isVisible().catch(() => false)) continue;
    const text = String(await row.innerText().catch(() => '')).trim();
    if (!text.includes(orderNumber)) continue;
    const salesOrderCode = text.match(/\bSO[0-9A-Z-]{6,40}\b/u)?.[0] || null;
    const trackingCell = await firstVisible([
      row.locator('[col-id*="express" i], [col-id*="logistics" i], [col-id*="waybill" i], [col-id*="tracking" i], [col-id*="deliveryNo" i]'),
    ]);
    const shippingTimeCell = await firstVisible([
      row.locator('[col-id*="ship" i], [col-id*="deliveryTime" i], [col-id*="shippedAt" i], [col-id*="发货" i]'),
    ]);
    const trackingText = String(await trackingCell?.innerText().catch(() => '') || '').trim();
    const shippingTimeText = String(await shippingTimeCell?.innerText().catch(() => '') || '').trim();
    const trackingNumber = trackingText.match(/\b[0-9A-Z][0-9A-Z-]{7,39}\b/iu)?.[0] || null;
    matches.push({ row, text, salesOrderCode, trackingNumber, shippingTimeText });
  }
  return matches;
};

const omsSalesOrderCodeFromRow = async (rowScope, fallbackCell = null) => {
  const salesOrderCell = await firstVisible([
    rowScope.locator('.ag-cell[col-id="salesOrderCode"]'),
    rowScope.locator('[col-id="salesOrderCode"]'),
    rowScope.getByText(/^SO[0-9A-Z-]{6,40}$/u, { exact: true }),
  ]);
  const candidates = [
    await salesOrderCell?.innerText().catch(() => ''),
    await rowScope.innerText().catch(() => ''),
    await fallbackCell?.innerText().catch(() => ''),
  ];
  for (const candidate of candidates) {
    const code = String(candidate || '').match(/\bSO[0-9A-Z-]{6,40}\b/u)?.[0] || null;
    if (code) return code;
  }
  return null;
};

const compactOmsReissueApiRow = (row, orderNumber) => {
  const tradeId = String(
    row?.tradeId || row?.tradeNo || row?.platformOrderNo || row?.externalOrderNumber || '',
  ).trim();
  if (tradeId !== String(orderNumber || '').trim()) return null;
  const salesOrderCode = String(
    row?.salesOrderCode || row?.salesOrderNo || row?.orderCode || '',
  ).trim().match(/\bSO[0-9A-Z-]{6,40}\b/u)?.[0] || null;
  const trackingText = String(
    row?.trackingNumber || row?.trackingNo || row?.expressNo || row?.waybillNo || '',
  ).trim();
  const markerText = JSON.stringify(row || {});
  return {
    tradeId,
    salesOrderCode,
    trackingNumber: trackingText.match(/\b[0-9A-Z][0-9A-Z-]{7,39}\b/iu)?.[0] || null,
    isReissue: reissuePattern.test(markerText),
    text: markerText,
    shippingTimeText: String(row?.shippingTime || row?.shippingAt || row?.deliveryTime || row?.shippedAt || ''),
  };
};

const inspectOmsReissueQueryPass = async (
  targetPage,
  browserContext,
  orderNumber,
  pass,
) => {
  const preferredInput = await ensureOmsOrderManagementPage(targetPage, browserContext, {
    maxAttempts: 1,
    timeoutMs: 30_000,
  });
  await closeUnexpectedOmsPopups(targetPage);
  const input = await fillReadyOmsOrderQueryInput(targetPage, orderNumber, {
    preferredInput,
    timeoutMs: 30_000,
  });
  const queryButton = await firstVisible([
    targetPage.getByRole('button', { name: /^(查询|搜索)$/ }),
    targetPage.getByText(/^(查询|搜索)$/, { exact: true }),
  ]);
  if (!queryButton) throw new Error('OMS 补发只读回查未找到查询按钮');
  const queryResponsePromise = targetPage.waitForResponse((response) => (
    response.request().method() === 'POST'
      && response.url().includes('/trade/sales/v2/postListPage')
      && String(response.request().postData() || '').includes(orderNumber)
  ), { timeout: 20_000 }).catch(() => null);
  await queryButton.click({ force: true });
  const queryResponse = await queryResponsePromise;
  const responsePayload = queryResponse
    ? await queryResponse.json().catch(() => null)
    : null;
  const rawApiRows = Array.isArray(responsePayload?.data?.data)
    ? responsePayload.data.data
    : [];
  const apiRows = rawApiRows
    .map((row) => compactOmsReissueApiRow(row, orderNumber))
    .filter(Boolean);
  const deadline = Date.now() + 30_000;
  let domRows = [];
  while (Date.now() < deadline) {
    domRows = await omsGridRowsForOrder(targetPage, orderNumber);
    if (domRows.length) break;
    await targetPage.waitForTimeout(500);
  }
  const compactDomRows = domRows.map((row) => ({
    salesOrderCode: row.salesOrderCode,
    trackingNumber: row.trackingNumber,
    isReissue: reissuePattern.test(row.text),
    text: row.text,
    shippingTimeText: row.shippingTimeText,
  }));
  const reissueByCode = new Map();
  for (const row of [...apiRows, ...compactDomRows]) {
    if (row.isReissue && row.salesOrderCode) reissueByCode.set(row.salesOrderCode, row);
  }
  const apiTotalCandidate = responsePayload?.data?.total
    ?? responsePayload?.data?.totalCount
    ?? responsePayload?.data?.count;
  const apiTotal = Number.isFinite(Number(apiTotalCandidate))
    ? Number(apiTotalCandidate)
    : null;
  return {
    pass,
    queryResponseCaptured: Boolean(queryResponse),
    queryResponseOk: Boolean(queryResponse?.ok()),
    apiTotal,
    apiRows,
    domRows: compactDomRows,
    reissueRows: [...reissueByCode.values()],
    observedAt: new Date().toISOString(),
    readOnly: true,
    queryInputValue: await input.inputValue().catch(() => orderNumber),
  };
};

const queryOmsReissueOrder = async (
  targetPage,
  browserContext,
  orderNumber,
  { excludeSalesOrderCodes = [] } = {},
) => {
  const excluded = new Set(excludeSalesOrderCodes.filter(Boolean));
  let lastQueryError = null;
  for (let attempt = 1; attempt <= 2; attempt++) {
    try {
      const preferredInput = await ensureOmsOrderManagementPage(targetPage, browserContext, {
        maxAttempts: 1,
        timeoutMs: 30_000,
      });
      const input = await fillReadyOmsOrderQueryInput(targetPage, orderNumber, {
        preferredInput,
        timeoutMs: 30_000,
      });
      const queryButton = await firstVisible([
        targetPage.getByRole('button', { name: /^(查询|搜索)$/ }),
        targetPage.getByText(/^(查询|搜索)$/, { exact: true }),
      ]);
      if (!queryButton) throw new Error('OMS 补发回查未找到查询按钮');
      await queryButton.click({ force: true });
      const deadline = Date.now() + 45_000;
      while (Date.now() < deadline) {
        const rows = await omsGridRowsForOrder(targetPage, orderNumber);
        const reissue = rows.find((row) => row.salesOrderCode
          && !excluded.has(row.salesOrderCode)
          && reissuePattern.test(row.text));
        if (reissue) return reissue;
        await targetPage.waitForTimeout(750);
      }
      lastQueryError = new Error('OMS 补发回查未显示新的补发订单');
    } catch (error) {
      lastQueryError = error;
    }
    if (attempt >= 2) break;
    writeProgress({
      step: 'oms-reissue-query-refreshing',
      ordinaryReissueQueryRecovery: {
        orderNumber,
        status: 'refreshing',
        completedPasses: attempt,
        lastError: lastQueryError?.message || null,
        refreshedAt: new Date().toISOString(),
      },
      error: null,
    });
    await targetPage.reload({ waitUntil: 'domcontentloaded', timeout: 45_000 }).catch(() => {});
  }
  writeProgress({
    step: 'oms-reissue-query-unconfirmed',
    ordinaryReissueQueryRecovery: {
      orderNumber,
      status: 'unconfirmed',
      completedPasses: 2,
      lastError: lastQueryError?.message || null,
      failedAt: new Date().toISOString(),
    },
  });
  return null;
};

const promiseReissueDateFromText = (text) => {
  const matches = String(text || '').match(/20\d{2}[-/.年]\d{1,2}[-/.月]\d{1,2}(?:日)?\s+\d{1,2}:\d{2}(?::\d{2})?/gu) || [];
  return matches.map((value) => parseOrdinaryBeijingDateTime(value)).filter(Boolean).sort().at(-1) || null;
};

const queryOmsPromiseReissueSuborder = async (targetPage, browserContext, orderNumber) => {
  let lastError = null;
  for (let attempt = 1; attempt <= 2; attempt += 1) {
    try {
      const pass = await inspectOmsReissueQueryPass(targetPage, browserContext, orderNumber, attempt);
      const candidates = (pass.domRows || [])
        .filter((row) => row.isReissue && row.trackingNumber)
        .filter((row) => /无退款/u.test(String(row.text || '')))
        .map((row) => ({
          ...row,
          shippingTime: promiseReissueDateFromText(row.shippingTimeText || row.text),
          carrier: String(row.text || '').match(/(?:快递公司|物流公司|承运商)\s*[:：]?\s*([^\s]+)/u)?.[1] || null,
        }))
        .filter((row) => row.shippingTime)
        .sort((left, right) => String(right.shippingTime || '').localeCompare(String(left.shippingTime || '')));
      const selected = candidates[0];
      if (selected) {
        const result = {
          status: 'ready',
          orderNumber,
          salesOrderCode: selected.salesOrderCode || null,
          trackingNumber: selected.trackingNumber,
          carrier: selected.carrier,
          shippingTime: selected.shippingTime,
          refundStatus: '无退款',
          markerMatched: true,
          readOnly: true,
          candidateCount: candidates.length,
          checkedAt: new Date().toISOString(),
        };
        writeProgress({ step: 'promise-reissue-oms-read-only-ready', promiseReissueOms: result, error: null });
        return result;
      }
      const notFound = {
        status: 'not-found', orderNumber, candidateCount: 0, readOnly: true,
        checkedAt: new Date().toISOString(),
      };
      writeProgress({ step: 'promise-reissue-oms-reissue-not-ready', promiseReissueOms: notFound, error: null });
      return notFound;
    } catch (error) {
      lastError = error;
      if (attempt >= 2) break;
      await targetPage.reload({ waitUntil: 'domcontentloaded', timeout: 45_000 }).catch(() => {});
    }
  }
  throw lastError || new Error(`OMS 承诺补寄只读查询失败: ${orderNumber}`);
};

const openOmsReissueWizard = async (targetPage, browserContext, orderNumber) => {
  await ensureOmsOrderManagementPage(targetPage, browserContext);
  const { orderCell, rowScope } = await queryOmsOrderRow(targetPage, orderNumber, { browserContext });
  const originalSalesOrderCode = await omsSalesOrderCodeFromRow(rowScope, orderCell);
  if (!originalSalesOrderCode) {
    throw new Error('OMS 补发前未读取到原销售订单号，禁止进入补发提交');
  }
  await selectOmsOrderRow(rowScope, orderCell, targetPage);
  const findReissueAction = () => firstVisible([
    targetPage.getByRole('menuitem', { name: '补发', exact: true }),
    targetPage.getByText('补发', { exact: true }).last(),
  ]);
  let reissueAction = await findReissueAction();
  if (!reissueAction) {
    const moreActions = await firstVisible([
      targetPage.getByRole('button', { name: /^更多操作/ }),
      targetPage.locator('.el-dropdown').filter({ hasText: /^更多操作/ }),
      targetPage.getByText('更多操作', { exact: true }),
    ]);
    if (!moreActions) throw new Error('OMS 订单管理未找到“更多操作”');
    await moreActions.click({ force: true });
    reissueAction = await findReissueAction();
  }
  if (!reissueAction) throw new Error('OMS“更多操作”菜单未找到“补发”');
  await reissueAction.click({ force: true });
  const basicInfo = targetPage.getByText('基本信息', { exact: true }).first();
  const flatDialog = targetPage.locator('.el-dialog:visible, [role="dialog"]:visible')
    .filter({ hasText: '批量补发' });
  await waitForFirstVisible(targetPage, [basicInfo, flatDialog], {
    timeoutMs: 30_000,
    pollIntervalMs: 200,
  });
  const wizardText = await targetPage.locator('body').innerText({ timeout: 30_000 });
  if (!await firstVisible([flatDialog]) && !/销售订单-新增|补发订单/u.test(wizardText)) {
    throw new Error('OMS 点击补发后未进入“销售订单-新增”页面');
  }
  return { originalSalesOrderCode };
};

const runOmsReissueCreationUnlocked = async (targetPage, browserContext, orderNumber) => {
  await ensureOmsWarehouseMutationAllowed(targetPage, orderNumber, 'OMS 补发操作');
  const existing = ordinaryExecutionFor(orderNumber, ORDINARY_SCENARIO_CODES.DELIVERY_RISK_CONCERN)
    .reissueOrder;
  if (existing?.salesOrderCode && ['created', 'allocated', 'tracking-ready'].includes(existing.status)) {
    return existing;
  }
  let originalSalesOrderCode = null;
  let flatBatchReissueDialog = null;
  let productCount = 1;
  for (let renderAttempt = 1; renderAttempt <= 2; renderAttempt += 1) {
    ({ originalSalesOrderCode } = await openOmsReissueWizard(
      targetPage,
      browserContext,
      orderNumber,
    ));
    try {
      await selectOmsReissueReason(targetPage, '快递责任补发', { timeoutMs: 30_000 });
      flatBatchReissueDialog = await findOmsFlatBatchReissueDialog(targetPage);
      if (flatBatchReissueDialog) {
        productCount = await assertSingleOmsBatchReissueSelection(targetPage);
      }
      break;
    } catch (error) {
      const selectionNotReady = /^OMS 批量补发已选择数量异常: (?:0|未读取到)$/u.test(String(error?.message || ''));
      const retryableRenderFailure = /OMS 补发页面(?:等待 \d+ 毫秒仍未找到|下拉框未找到)|(?:选择|关闭字典弹层)后未保持|字典弹层未关闭/u
        .test(String(error?.message || '')) || selectionNotReady;
      if (selectionNotReady) {
        await saveWorkflowDiagnostics(targetPage, 'oms-reissue-selection-not-ready', error).catch(() => {});
      }
      if (!retryableRenderFailure || renderAttempt >= 2) throw error;
      writeProgress({
        step: 'oms-reissue-render-refreshing',
        ordinaryReissueRenderRecovery: {
          orderNumber,
          attempt: renderAttempt,
          error: error.message,
          refreshedAt: new Date().toISOString(),
        },
        error: null,
      });
      await targetPage.reload({ waitUntil: 'domcontentloaded', timeout: 60_000 }).catch(() => {});
      await ensureOmsOrderManagementPage(targetPage, browserContext);
    }
  }
  if (flatBatchReissueDialog) {
    writeProgress({
      step: 'oms-reissue-flat-batch-ready',
      ordinaryReissueWizard: {
        orderNumber,
        variant: 'flat-batch-reissue',
        selectedOrderCount: productCount,
        readyAt: new Date().toISOString(),
      },
      error: null,
    });
  } else {
    await clickOmsWizardButton(targetPage, ['下一步']);
    const productHeading = targetPage.getByText('商品明细', { exact: true }).first();
    await productHeading.waitFor({ state: 'visible', timeout: 30_000 }).catch(() => {});
    const productRows = targetPage.locator(
      '.ag-center-cols-container .ag-row, .el-table__body-wrapper tbody tr, tbody .el-table__row',
    ).filter({ hasNotText: /暂无数据/ });
    productCount = await productRows.count().catch(() => 0);
    if (!productCount) throw new Error('OMS 补发商品明细为空，禁止创建空补发单');
    for (let index = 0; index < productCount; index++) {
      const row = productRows.nth(index);
      const checkbox = await firstVisible([
        row.getByRole('checkbox'),
        row.locator('input[type="checkbox"]'),
        row.locator('.el-checkbox'),
      ]);
      if (!checkbox) continue;
      const checked = await checkbox.isChecked().catch(() => (
        checkbox.getAttribute('aria-checked').then((value) => value === 'true').catch(() => false)
      ));
      if (!checked) await checkbox.click({ force: true });
    }
    await clickOmsWizardButton(targetPage, ['下一步']);
    const paymentHeading = targetPage.getByText('支付信息', { exact: true }).first();
    await paymentHeading.waitFor({ state: 'visible', timeout: 30_000 }).catch(() => {});
  }
  writeProgress({
    step: 'oms-reissue-submitting',
    ordinaryReissueCreation: {
      orderNumber,
      businessType: '快递责任补发',
      productCount,
      paymentDefaultsPreserved: true,
      wizardVariant: flatBatchReissueDialog ? 'flat-batch-reissue' : 'multi-step',
      submissionStrategy: flatBatchReissueDialog
        ? 'footer-submit-request-observed-v2'
        : 'multi-step-confirmation-v1',
      originalSalesOrderCode,
      status: 'submitting',
      startedAt: new Date().toISOString(),
    },
  });
  const created = await guardedExternalEffect({
    effectType: 'oms-reissue-create',
    orderNumber,
    stage: 'ordinary-delivery-risk-reissue-create-v1',
    request: {
      orderNumber,
      businessType: '快递责任补发',
      productCount,
      paymentDefaultsPreserved: true,
      wizardVariant: flatBatchReissueDialog ? 'flat-batch-reissue' : 'multi-step',
      submissionStrategy: flatBatchReissueDialog
        ? 'footer-submit-request-observed-v2'
        : 'multi-step-confirmation-v1',
      originalSalesOrderCode,
    },
  }, async () => {
    let submissionObservation = null;
    if (flatBatchReissueDialog) {
      await assertSingleOmsBatchReissueSelection(targetPage);
      submissionObservation = await submitOmsFlatBatchReissue(
        targetPage,
        flatBatchReissueDialog,
        { orderNumber },
      );
    } else {
      await clickOmsWizardButton(targetPage, ['完成', '保存', '提交', '确认']);
    }
    const confirmation = await firstVisible([
      targetPage.locator('.el-message-box:visible, [role="alertdialog"]:visible'),
    ]);
    if (confirmation) {
      const confirm = await firstVisible([
        confirmation.getByRole('button', { name: /^(确定|确认)$/ }),
        confirmation.getByText(/^(确定|确认)$/, { exact: true }),
      ]);
      if (confirm) await confirm.click({ force: true });
    }
    writeProgress({
      step: 'oms-reissue-submit-observed',
      ordinaryReissueSubmission: submissionObservation || {
        strategy: 'multi-step-confirmation-v1',
        clickAttempted: true,
        observedAt: new Date().toISOString(),
      },
      error: null,
    });
    const reissue = await queryOmsReissueOrder(targetPage, browserContext, orderNumber, {
      excludeSalesOrderCodes: [originalSalesOrderCode],
    });
    if (!reissue?.salesOrderCode) {
      throw new Error('OMS 补发提交后未回查到新的补发订单标识，结果不确定，禁止重复创建');
    }
    return {
      salesOrderCode: reissue.salesOrderCode,
      trackingNumber: reissue.trackingNumber,
      identifiedAt: new Date().toISOString(),
    };
  });
  const createdAt = new Date().toISOString();
  const reissueOrder = {
    orderNumber,
    salesOrderCode: created.salesOrderCode,
    trackingNumber: created.trackingNumber || null,
    status: created.trackingNumber ? 'tracking-ready' : 'created',
    createdAt,
  };
  updateOrdinaryExecution(orderNumber, ORDINARY_SCENARIO_CODES.DELIVERY_RISK_CONCERN, {
    reissueOrder,
  });
  if (!created.trackingNumber) {
    const allocation = await runOmsManualAllocation(
      targetPage,
      browserContext,
      created.salesOrderCode,
      [],
      {
        effectOrderNumber: orderNumber,
        effectStage: 'ordinary-delivery-risk-reissue-allocation-v1',
        progressField: 'ordinaryReissueAllocation',
        updatePrimaryOmsAnalysis: false,
        allowFirstAvailableCarrier: true,
      },
    );
    reissueOrder.status = 'allocated';
    reissueOrder.allocation = allocation;
    updateOrdinaryExecution(orderNumber, ORDINARY_SCENARIO_CODES.DELIVERY_RISK_CONCERN, {
      reissueOrder,
    });
  }
  return reissueOrder;
};

const runOmsReissueCreation = async (targetPage, browserContext, orderNumber) => withOmsSessionLock(
  `oms-reissue-creation:${orderNumber}`,
  (sharedPage, sharedContext) => runOmsReissueCreationUnlocked(
    sharedPage || targetPage,
    sharedContext || browserContext,
    orderNumber,
  ),
);

const checkOmsReissueTrackingNumberUnlocked = async (targetPage, browserContext, orderNumber) => {
  const execution = ordinaryExecutionFor(orderNumber, ORDINARY_SCENARIO_CODES.DELIVERY_RISK_CONCERN);
  const reissueOrder = execution.reissueOrder;
  if (!reissueOrder?.salesOrderCode) throw new Error('OMS 补发单号复查缺少新补发订单标识');
  await ensureOmsOrderManagementPage(targetPage, browserContext);
  const { rowScope } = await queryOmsOrderRow(
    targetPage,
    reissueOrder.salesOrderCode,
    { browserContext },
  );
  const trackingCell = await firstVisible([
    rowScope.locator('[col-id*="express" i], [col-id*="logistics" i], [col-id*="waybill" i], [col-id*="tracking" i], [col-id*="deliveryNo" i]'),
  ]);
  const trackingText = String(await trackingCell?.innerText().catch(() => '') || '').trim();
  const trackingNumber = trackingText.match(/\b[0-9A-Z][0-9A-Z-]{7,39}\b/iu)?.[0] || null;
  const nextReissueOrder = {
    ...reissueOrder,
    trackingNumber,
    status: trackingNumber ? 'tracking-ready' : reissueOrder.status,
    trackingCheckedAt: new Date().toISOString(),
  };
  updateOrdinaryExecution(orderNumber, ORDINARY_SCENARIO_CODES.DELIVERY_RISK_CONCERN, {
    reissueOrder: nextReissueOrder,
    reissueTrackingLookupCompleted: true,
  });
  return nextReissueOrder;
};

const checkOmsReissueTrackingNumber = async (targetPage, browserContext, orderNumber) => withOmsSessionLock(
  `oms-reissue-tracking:${orderNumber}`,
  (sharedPage, sharedContext) => checkOmsReissueTrackingNumberUnlocked(
    sharedPage || targetPage,
    sharedContext || browserContext,
    orderNumber,
  ),
);

const ensureOmsScenarioPreparation = async (targetPage, browserContext, orderNumber) => {
  const progress = readProgress();
  const scenarioCode = progress.scenarioCode || activeScenarioCode;
  if (scenarioCode !== 'abnormal-network-warning'
    || !isAbnormalNetworkUnshipped(progress.logisticsAnalysis)) return null;
  const recommendations = (progress.logisticsAnalysis?.recommendedCarriers || [])
    .map((value) => String(value || '').trim())
    .filter(Boolean);
  if (!progress.omsAnalysis?.orderStatus) {
    await pauseForTransientRetry(
      targetPage,
      'oms-manual-allocation',
      'OMS_ORDER_STATUS_TEMPORARILY_UNAVAILABLE',
      'OMS 未读取到订单状态，无法判断是否需要手工配货',
    );
  }
  if (omsOrderStatusIsTerminalWithoutShipment(progress.omsAnalysis.orderStatus)
    || omsApiOrderStateIsTerminalWithoutShipment(progress.omsLiveOrderState)) {
    const completed = {
      shopId,
      orderNumber,
      recommendedCarrier: null,
      omsCarrier: null,
      status: 'not-applicable-terminal-order',
      verifiedOrderStatus: progress.omsAnalysis.orderStatus
        || omsOrderStatusFromApiState(progress.omsLiveOrderState),
      completedAt: new Date().toISOString(),
    };
    writeProgress({
      step: 'oms-manual-allocation-not-applicable-terminal-order',
      omsManualAllocation: completed,
      manualReview: null,
      error: null,
    });
    return completed;
  }
  if (omsOrderStatusHasPassedAllocation(progress.omsAnalysis.orderStatus)) {
    const completed = {
      shopId,
      orderNumber,
      recommendedCarrier: recommendations[0],
      omsCarrier: null,
      status: progress.omsAnalysis.orderStatus === '已配货'
        ? 'already-allocated'
        : 'already-past-allocation',
      verifiedOrderStatus: progress.omsAnalysis.orderStatus,
      completedAt: new Date().toISOString(),
    };
    writeProgress({ step: 'oms-manual-allocation-not-required', omsManualAllocation: completed });
    return completed;
  }
  const existing = progress.omsManualAllocation;
  if (existing?.orderNumber === orderNumber && existing.status === 'succeeded') return existing;
  return withOmsSessionLock(
    `oms-manual-allocation:${orderNumber}`,
    (sharedPage, sharedContext) => runOmsManualAllocation(
      sharedPage || targetPage,
      sharedContext || browserContext,
      orderNumber,
      recommendations,
      {
      allowFirstAvailableCarrier: true,
      },
    ),
  );
};

const persistBrowserAuth = async (browserContext, { pddAuthenticated = false } = {}) => {
  const storageState = await browserContext.storageState({ indexedDB: true });
  const pddState = scopeBrowserStorageState(storageState, AUTH_STORAGE_HOSTS.pdd);
  const omsState = scopeBrowserStorageState(storageState, AUTH_STORAGE_HOSTS.oms);
  const tmsState = scopeBrowserStorageState(storageState, AUTH_STORAGE_HOSTS.tms);
  const progress = readProgress();
  const pddHealthAuthenticated = progress.authHealth?.pdd?.status === 'authenticated';
  const observedShopName = normalizePddShopNameCandidate(
    progress.pddShopIdentity?.mallName || progress.pddShopIdentity?.actualShopName,
  );
  const configuredIdentity = canonicalPddShopIdentityName(expectedShopName);
  const observedIdentity = canonicalPddShopIdentityName(observedShopName);
  const pddIdentityMatchesExpected = !configuredIdentity || (
    progress.pddShopIdentity?.status === 'detected'
    && pddIdentityMatches(configuredPddIdentityNames, [
      observedShopName,
      progress.pddShopIdentity?.actualShopName,
      progress.pddShopIdentity?.headerShopName,
      progress.pddShopIdentity?.identityNames,
    ])
    && !isMaskedPddShopIdentityName(observedShopName)
  );
  const pddMallMatchesExpected = !expectedMallId || (
    normalizePddMallId(progress.pddShopIdentity?.mallId) === expectedMallId
    && pddStorageMatchesMallId(pddState, expectedMallId)
  );
  const livePddBusinessSession = await pddBusinessPageMatchesExpectedMall(pddPage);
  const pddSnapshotConfirmed = hasPddStorageData(pddState) && (
    (hasUsablePddSessionCookie(pddState) || livePddBusinessSession)
      && (pddAuthenticated || pddHealthAuthenticated)
  ) && pddIdentityMatchesExpected && pddMallMatchesExpected;
  if (pddSnapshotConfirmed) {
    writeJsonAtomic(statePath, pddState);
    writeJsonAtomic(pddLastKnownGoodStatePath, pddState);
  }
  if (omsState.cookies.length || omsState.origins.length) writeJsonAtomic(omsStatePath, omsState);
  // TMS clears its localStorage token when the SPA enters an unauthorized
  // login page. Never let that empty browser state replace the last usable
  // snapshot; the token is validated against this shop's account on restore.
  const tmsSessionToken = tmsState.origins
    ?.find((origin) => origin.origin === tmsBaseUrl)
    ?.localStorage?.find((entry) => entry.name === 'tms_auth_token')?.value;
  if (tmsSessionToken) writeJsonAtomic(tmsStatePath, tmsState);
  return storageState;
};

const pauseForManualReview = async (targetPage, stage, reason, patch = {}) => {
  writeProgress({
    ...patch,
    step: 'manual-review-required',
    manualReview: {
      stage,
      reason,
      orderNumber: readProgress().orderNumber || null,
      requiredAt: new Date().toISOString(),
    },
    currentUrl: targetPage.url(),
    error: null,
  });
  await saveWorkflowDiagnostics(targetPage, `manual-review-${stage}`).catch(() => {});
  console.error(`[需要人工复核] ${reason}`);
  throw new ManualReviewRequiredError(stage, reason);
};

const pauseForTransientRetry = async (
  targetPage, stage, code, reason, patch = {}, retryAfterMs = 30_000,
) => {
  const message = `${code}: ${reason}`;
  writeProgress({
    ...patch,
    step: 'flow-paused',
    transientWorkflowFailure: {
      stage,
      code,
      reason,
      retryAfterMs,
      failedAt: new Date().toISOString(),
    },
    manualReview: null,
    currentUrl: targetPage.url(),
    error: message,
  });
  await saveWorkflowDiagnostics(targetPage, `transient-${stage}`).catch(() => {});
  const error = new Error(message);
  error.name = 'TransientWorkflowRetryRequiredError';
  error.code = code;
  throw error;
};

const closeUnexpectedTmsPopups = async (targetPage) => {
  const closeButtons = targetPage.locator([
    '.el-message-box__headerbtn:visible',
    '.el-notification__closeBtn:visible',
    '.el-tour__close-btn:visible',
    '.driver-popover-close-btn:visible',
    '.introjs-skipbutton:visible',
    // The logistics-ticket dialog is a business form, not an unrelated popup.
    // Its close button can linger while Element Plus marks it is-closing.
    'button[aria-label*="Close" i]:not(.el-dialog__headerbtn):visible',
    'button[aria-label*="关闭"]:not(.el-dialog__headerbtn):visible',
    '[class*="tour" i] [class*="close" i]:visible',
    '[class*="guide" i] [class*="close" i]:visible',
  ].join(', '));
  let closed = 0;
  for (let attempt = 0; attempt < 5; attempt++) {
    const button = await firstVisible([closeButtons]);
    if (!button) break;
    await pacedAction(targetPage, 'close-tms-popup', () => button.click());
    closed++;
  }
  if (closed) console.log(`已点击 X 关闭 ${closed} 个 TMS 无关提示弹窗。`);
  return closed;
};

const validatedSavedTmsToken = async () => {
  const snapshot = readSavedStorageState(tmsStatePath);
  const token = snapshot?.origins
    ?.find((origin) => origin.origin === tmsBaseUrl)
    ?.localStorage?.find((entry) => entry.name === 'tms_auth_token')?.value;
  const configuredAccount = String(process.env.TMS_ACCOUNT || '').trim();
  if (!token || !configuredAccount) return null;
  try {
    const response = await fetch(`${tmsBaseUrl}/api/auth/me`, {
      method: 'GET',
      headers: { Authorization: `Bearer ${token}` },
      signal: AbortSignal.timeout(10_000),
    });
    if (!response.ok) return null;
    const result = await response.json();
    return result?.success === true
      && String(result.data?.username || '').trim() === configuredAccount
      ? token : null;
  } catch {
    return null;
  }
};

const restoreValidatedTmsSession = async (targetPage) => {
  try {
    const url = new URL(targetPage.url());
    if (url.origin !== tmsBaseUrl || !url.pathname.startsWith('/login')) return false;
  } catch {
    return false;
  }
  const token = await validatedSavedTmsToken();
  if (!token) return false;
  logRunStep('tms-saved-session-restoring', {
    tmsSessionRecovery: { method: 'same-shop-validated-snapshot', startedAt: new Date().toISOString() },
  });
  // Only this TMS origin changes. Keep the PDD/OMS tabs and their live browser
  // storage intact; a valid persisted token is safer than another login POST.
  await targetPage.evaluate((value) => localStorage.setItem('tms_auth_token', value), token);
  await navigateSystemPage(targetPage, tmsLogisticsUrl, 'restore-tms-validated-session');
  if (targetPage.url().includes('/login')
    || !await waitForTmsCustomerRegistration(targetPage, Math.min(tmsNavigationTimeoutMs, 20_000))) {
    throw new Error('TMS 已保存会话有效，但业务页恢复后仍未渲染');
  }
  return true;
};

const ensureTmsLoginOnce = async (targetPage, browserContext) => {
  const existingTmsLogin = await locateSystemLoginAcrossPages(
    targetPage,
    'tms',
    (url) => url.includes('/login'),
    'tms-login-recovery',
  );
  if (existingTmsLogin?.page && existingTmsLogin.page !== targetPage) {
    targetPage = existingTmsLogin.page;
    console.log(`[TMS 登录] 已切换到实际登录标签页: ${existingTmsLogin.url}`);
  }
  let tmsOrigin = false;
  try {
    tmsOrigin = new URL(targetPage.url()).origin === tmsBaseUrl;
  } catch {
    tmsOrigin = false;
  }
  // Reuse an authenticated TMS business page. Navigating to /login on every
  // retry made the customer-registration page appear to be stuck in a loop.
  if (!tmsOrigin) {
    await pacedAction(targetPage, 'open-tms-login', () => navigateSystemPage(targetPage, tmsLoginUrl, 'open-tms-login'));
  }
  await checkForHumanVerification(targetPage, 'tms-login-page');
  if (targetPage.url().includes('/login')) {
    if (await restoreValidatedTmsSession(targetPage)) {
      await persistBrowserAuth(browserContext);
      updateAuthHealth('tms', 'authenticated', targetPage);
      persistSystemTabs('tms');
      writeProgress({ error: null, systemLogin: { system: 'tms', attempts: 0,
        maxAttempts: systemLoginMaxAttempts, status: 'authenticated',
        completedAt: new Date().toISOString(), method: 'same-shop-validated-snapshot' } });
      logRunStep('tms-login-complete', { tmsUrl: targetPage.url(), verificationStage: null });
      return;
    }
    logRunStep('tms-auto-login-attempt', { tmsUrl: targetPage.url(), credentialsConfigured: Boolean(process.env.TMS_ACCOUNT && process.env.TMS_PASSWORD) });
    updateAuthHealth('tms', 'expired', targetPage);
    const accountValue = process.env.TMS_ACCOUNT;
    const passwordValue = process.env.TMS_PASSWORD;
    if (!accountValue || !passwordValue) {
      await focusManualLoginPage(targetPage);
      await saveWorkflowDiagnostics(targetPage, 'manual-login-tms');
      writeProgress({
        step: browserHeadless ? 'human-verification-required' : 'manual-login-required',
        verificationStage: 'tms-login',
        currentUrl: targetPage.url(),
        error: null,
      });
      if (browserHeadless) {
        throw new HumanVerificationRequiredError('tms-login', targetPage.url());
      }
      console.error('[需要人工登录] TMS 登录状态已失效，请在当前可视化浏览器中登录。');
      targetPage = await waitForLoginExit(targetPage, (url) => url.includes('/login'), 'tms-manual-login');
    } else {
      // A blank TMS SPA should trigger the single controlled reload quickly.
      const loginDeadline = Date.now() + 20000;
      let account = null;
      let password = null;
      while (Date.now() < loginDeadline && (!account || !password)) {
        account = await firstVisible([
          targetPage.getByPlaceholder('用户名', { exact: true }),
          targetPage.locator('input[placeholder*="用户"]'),
          targetPage.locator('input[name*="user" i], input[name*="account" i]'),
          targetPage.locator('input:not([type="hidden"]):not([type="password"]):not([type="submit"])').first(),
        ]);
        password = await firstVisible([
          targetPage.getByPlaceholder('密码', { exact: true }),
          targetPage.locator('input[type="password"]'),
        ]);
        if (!account || !password) await targetPage.waitForTimeout(500);
      }
      let loginButton = await firstVisible([
        targetPage.locator('button.login-button'),
        targetPage.getByRole('button', { name: '登录', exact: true }),
        targetPage.locator('button[type="submit"]'),
        targetPage.locator('form button').last(),
        targetPage.locator('button.el-button--primary'),
        targetPage.getByRole('button', { name: '登录', exact: true }),
        targetPage.getByText('登录', { exact: true }),
      ]);
      if (!account || !password || !loginButton) {
        await navigateSystemPage(targetPage, tmsLoginUrl, 'reload-tms-login-form');
        await targetPage.locator('input[type="password"]').waitFor({ state: 'visible', timeout: 30000 }).catch(() => {});
        account = await firstVisible([
          targetPage.getByPlaceholder('用户名', { exact: true }),
          targetPage.locator('input[placeholder*="用户"], input[placeholder*="账号"]').first(),
          targetPage.locator('input[name*="user" i], input[name*="account" i]').first(),
        ]);
        password = await firstVisible([
          targetPage.getByPlaceholder('密码', { exact: true }),
          targetPage.locator('input[type="password"]').first(),
        ]);
        loginButton = await firstVisible([
          targetPage.locator('button.login-button'),
          targetPage.getByRole('button', { name: '登录', exact: true }),
          targetPage.locator('button[type="submit"]'),
          targetPage.locator('form button').last(),
          targetPage.locator('button.el-button--primary'),
          targetPage.getByRole('button', { name: '登录', exact: true }),
          targetPage.getByText('登录', { exact: true }),
        ]);
      }
      if (!account || !password || !loginButton) {
        throw new Error('TMS 登录页控件未加载完成，自动恢复后重试');
      }
      await pacedAction(targetPage, 'fill-tms-account', () => account.fill(accountValue));
      await pacedAction(targetPage, 'fill-tms-password', () => password.fill(passwordValue));
      // Observe only the HTTP status of this form's login request. A timeout
      // alone cannot distinguish an API rejection from a failed SPA redirect;
      // never read or persist the request body, response body, or auth token.
      const loginPage = targetPage;
      let loginApiStatus = null;
      const observeLoginResponse = (response) => {
        try {
          const url = new URL(response.url());
          if (url.origin === tmsBaseUrl && url.pathname === '/api/auth/login'
            && response.request().method() === 'POST') {
            loginApiStatus = response.status();
          }
        } catch { /* unrelated or malformed response */ }
      };
      loginPage.on('response', observeLoginResponse);
      try {
        await pacedAction(targetPage, 'submit-tms-login', () => loginButton.click({ timeout: 10000 }));
        await targetPage.waitForTimeout(2000);
        if (loginApiStatus >= 400) {
          throw new Error(`TMS 自动登录接口 HTTP ${loginApiStatus}`);
        }
        const loginError = await firstVisible([
          targetPage.locator('.el-message--error'),
          targetPage.locator('.el-notification__content'),
          targetPage.locator('[role="alert"]'),
        ]);
        if (loginError) {
          const loginErrorText = (await loginError.innerText().catch(() => '')).trim();
          throw new Error(`TMS 自动登录失败${loginErrorText ? `: ${loginErrorText}` : ''}`);
        }
        try {
          targetPage = await waitForLoginExit(targetPage, (url) => url.includes('/login'), 'tms-login-result', {
            timeoutMs: 45000,
          });
        } catch (error) {
          if (!/^tms-login-result 登录等待超过/u.test(error.message)) throw error;
          const apiEvidence = loginApiStatus === null
            ? '未观察到登录接口响应' : `登录接口 HTTP ${loginApiStatus}`;
          throw new Error(`${error.message}（${apiEvidence}）`, { cause: error });
        }
        await checkForHumanVerification(targetPage, 'tms-login-result');
      } finally {
        loginPage.off('response', observeLoginResponse);
      }
    }
  }
  // Do not record an authenticated TMS session from the URL alone. A stale
  // SPA shell can keep /logistics while rendering the login form after an
  // expired cookie.
  const tmsBody = await targetPage.locator('body').innerText().catch(() => '');
  const tmsLoginShell = /账号登录|账户登录|用户名|登录密码/.test(tmsBody)
    && !/客服登记|物流快递工单|物流问题登记表|物流场景数据池|智能工单管理/.test(tmsBody);
  if (targetPage.url().includes('/login') || tmsLoginShell) {
    throw new Error(`TMS 登录后未进入真实业务页: ${targetPage.url()}`);
  }
  await persistBrowserAuth(browserContext);
  updateAuthHealth('tms', 'authenticated', targetPage);
  persistSystemTabs('tms');
  writeProgress({ error: null, systemLogin: { system: 'tms', attempts: 0, maxAttempts: systemLoginMaxAttempts, status: 'authenticated', completedAt: new Date().toISOString() } });
  logRunStep('tms-login-complete', { tmsUrl: targetPage.url(), verificationStage: null });
};

const ensureTmsLogin = async (targetPage, browserContext) => {
  try {
    const result = await ensureTmsLoginOnce(targetPage, browserContext);
    systemLoginAttempts.tms = 0;
    return result;
  } catch (error) {
    systemLoginAttempts.tms += 1;
    if (await hasHumanVerification(targetPage)) {
      writeProgress({
        step: 'human-verification-required',
        verificationStage: 'tms-login',
        systemLogin: { system: 'tms', attempts: systemLoginAttempts.tms,
          maxAttempts: systemLoginMaxAttempts, status: 'waiting-human',
          lastError: error.message, updatedAt: new Date().toISOString() },
        currentUrl: targetPage.url(),
        error: null,
      });
      targetPage = await waitForManualSystemLogin(targetPage, 'tms', 'tms-login-captcha');
      systemLoginAttempts.tms = 0;
      return ensureTmsLoginOnce(targetPage, browserContext);
    }
    // A failed TMS form must not hold a business claim in a login loop.
    // Yield it to the bounded worker retry with the same browser profile.
    writeProgress({
      step: 'tms-login-retry-deferred',
      verificationStage: null,
      systemLogin: { system: 'tms', attempts: systemLoginAttempts.tms,
        maxAttempts: systemLoginMaxAttempts, status: 'retry-ready',
        lastError: error.message, updatedAt: new Date().toISOString() },
      currentUrl: targetPage.url(),
      error: null,
    });
    const deferred = new Error(
      `TMS automatic login recovery deferred for this shop profile: ${error.message}`,
      { cause: error },
    );
    deferred.code = 'TMS_LOGIN_RETRY_DEFERRED';
    throw deferred;
  }
};

const tmsLoginPageRendered = async (targetPage) => {
  if (targetPage.url().includes('/login')) return true;
  const passwordInput = await firstVisible([
    targetPage.locator('input[type="password"]'),
  ]);
  if (!passwordInput) return false;
  const bodyText = await targetPage.locator('body').innerText().catch(() => '');
  return /账号登录|账户登录|用户名|登录密码/.test(bodyText)
    && !/客服登记|物流快递工单|物流问题登记表|物流场景数据池/.test(bodyText);
};

const tmsCustomerRegistrationReady = async (targetPage) => {
  if (!targetPage.url().includes('/logistics')) return false;
  if (await tmsLoginPageRendered(targetPage)) return false;
  return Boolean(await firstVisible([
    targetPage.locator('.el-dialog.logistics-dialog:visible, .logistics-dialog:visible'),
    targetPage.locator('.filter-panel:visible'),
    targetPage.getByRole('button', { name: /筛选|新建/ }),
  ]));
};

const waitForTmsCustomerRegistration = async (targetPage, timeoutMs = tmsNavigationTimeoutMs) => {
  const deadline = Date.now() + timeoutMs;
  do {
    if (await tmsCustomerRegistrationReady(targetPage)) return true;
    await targetPage.waitForTimeout(tmsNavigationPollIntervalMs);
  } while (Date.now() < deadline);
  return false;
};

const openTmsCustomerRegistration = async (targetPage, browserContext) => {
  if (targetPage === tmsPage && residentTmsWarmupPromise) {
    await residentTmsWarmupPromise;
  }
  await ensureTmsLogin(targetPage, browserContext);

  // /logistics is a stable authenticated route. Opening it directly avoids a
  // race where the dashboard parent menu is clicked before its lazy submenu
  // has rendered. Keep the menu path as a fallback for deployments that
  // redirect direct navigation back to the dashboard.
  if (!await tmsCustomerRegistrationReady(targetPage)) {
    for (let attempt = 1; attempt <= 2; attempt++) {
      await navigateSystemPage(
        targetPage,
        tmsLogisticsUrl,
        `open-tms-customer-registration-direct-${attempt}`,
      );
      if (await waitForTmsCustomerRegistration(targetPage)) break;
      await ensureTmsLogin(targetPage, browserContext);
    }
  }

  if (!await tmsCustomerRegistrationReady(targetPage)) {
    // TMS renamed this page from the old nested “物流快递工单 / 客服登记”
    // entry to “物流场景数据池 / 物流问题登记表（客服）”. Prefer the
    // concrete page entry and keep the old labels as a compatibility fallback.
    const customerRegistrationCandidates = [
      targetPage.getByRole('menuitem', { name: /物流问题登记表\s*[（(]\s*客服\s*[）)]/u }),
      targetPage.getByText(/物流问题登记表\s*[（(]\s*客服\s*[）)]/u),
      targetPage.getByRole('menuitem', { name: /客服登记/ }),
      targetPage.getByText('客服登记', { exact: true }),
    ];
    let customerRegistration = await firstVisible(customerRegistrationCandidates);
    if (!customerRegistration) {
      const parentMenuCandidates = [
        targetPage.getByRole('menuitem', { name: /物流场景数据池/ }),
        targetPage.getByText('物流场景数据池', { exact: true }),
        targetPage.getByRole('menuitem', { name: /智能工单管理/ }),
        targetPage.getByText('智能工单管理', { exact: true }),
      ];
      const parentMenu = await firstVisible(parentMenuCandidates);
      if (!parentMenu) throw new Error(`TMS 未找到“物流场景数据池”菜单: ${targetPage.url()}`);
      for (let attempt = 1; attempt <= 2 && !customerRegistration; attempt++) {
        await pacedAction(
          targetPage,
          `open-tms-logistics-scenario-menu-${attempt}`,
          () => parentMenu.click(),
        );
        customerRegistration = await waitForFirstVisible(targetPage, customerRegistrationCandidates);
        if (!customerRegistration && attempt === 1) {
          const legacyParent = await firstVisible([
            targetPage.getByRole('menuitem', { name: /物流快递工单/ }),
            targetPage.getByText('物流快递工单', { exact: true }),
          ]);
          if (legacyParent) {
            await pacedAction(targetPage, 'open-tms-legacy-logistics-work-orders', () => legacyParent.click());
            customerRegistration = await waitForFirstVisible(targetPage, customerRegistrationCandidates);
          }
        }
      }
    }
    if (!customerRegistration) {
      throw new Error(`TMS 未找到“物流问题登记表（客服）”菜单: ${targetPage.url()}`);
    }
    await pacedAction(targetPage, 'open-tms-customer-registration', () => customerRegistration.click());
  }

  if (!await waitForTmsCustomerRegistration(targetPage)) {
    throw new Error(`TMS 客服登记页未在 ${tmsNavigationTimeoutMs}ms 内就绪: ${targetPage.url()}`);
  }
  await closeUnexpectedTmsPopups(targetPage);
  persistSystemTabs('tms');
  logRunStep('tms-customer-registration-opened', { tmsUrl: targetPage.url() });
};

const restoredSystemTargets = (progress) => ({
  // Keep the PDD anchor on the queue/list. A saved order detail is restored
  // in a derived tab by processOneWorkOrder, so health checks never navigate
  // the permanent anchor away from its business home.
  pdd: listUrl,
  // OMS is a SPA: direct navigation to /trade/sales can redirect a valid
  // session back to /login. Restore the stable dashboard and let the order
  // workflow open sales through the rendered menu.
  oms: 'https://www.jeoms.com/xianma/dashboard',
  tms: tmsLogisticsUrl,
});

const restoreOmsBusinessRoute = async (targetPage, targetUrl, stage) => {
  // A successful dashboard login does not guarantee that the SPA will keep
  // the session when the sales route is opened. Some OMS deployments redirect
  // that route back to /login asynchronously. Observe the rendered page after
  // navigation and perform bounded automatic recovery instead of trusting the
  // first URL value.
  for (let attempt = 1; attempt <= systemLoginMaxAttempts; attempt++) {
    await navigateSystemPage(targetPage, targetUrl, `${stage}-${attempt}`);
    await targetPage.waitForTimeout(1500);
    const state = await readOmsAppState(targetPage);
    if (!targetPage.url().includes('/xianma/login')
      && !state.loginForm
      && !state.loggedOut
      && state.businessShell) {
      return;
    }
    updateAuthHealth('oms', 'expired', targetPage, {
      stage,
      reason: 'sales-route-redirected-to-login',
      attempt,
    });
    if (attempt < systemLoginMaxAttempts) {
      await ensureOmsLogin(targetPage, context);
    }
  }
  throw new Error(`OMS 订单业务页连续 ${systemLoginMaxAttempts} 次被重定向到登录页`);
};

const authenticatedSystemTabChecks = () => ([
    ['pdd', pddPage, 'https://mms.pinduoduo.com', /\/login(?:\/|\?|$)/],
    ['oms', omsPage, 'https://www.jeoms.com', /\/xianma\/login(?:\/|\?|$)/],
    ['tms', tmsPage, tmsBaseUrl, /\/login(?:\/|\?|$)/],
]);

const assertAuthenticatedSystemTabs = (requiredSystems = ['pdd', 'oms', 'tms']) => {
  const required = new Set(requiredSystems.map((value) => String(value || '').toLowerCase()));
  const checks = authenticatedSystemTabChecks().filter(([system]) => required.has(system));
  for (const [system, targetPage, expectedOrigin, loginPattern] of checks) {
    if (system === 'oms' && omsMode === 'shared' && !activeSharedOmsPage) {
      const health = readProgress().authHealth?.oms;
      if (health?.status === 'authenticated'
        && !isWeakAuthHealthEvidence(health)
        && health?.source === 'shared-oms-browser-session') continue;
      throw new Error('共享 OMS 浏览器尚未确认登录后的业务页面');
    }
    let parsed;
    try {
      parsed = new URL(targetPage.url());
    } catch {
      throw new Error(`${system} 标签 URL 无效: ${targetPage.url()}`);
    }
    if (parsed.origin !== expectedOrigin || loginPattern.test(parsed.pathname)) {
      updateAuthHealth(system, 'expired', targetPage, {
        reason: 'live-page-is-login-or-wrong-origin',
      });
      throw new Error(`${system} 标签未进入登录后的业务页面: ${targetPage.url()}`);
    }
  }
};

const ensureScenarioSystemDependencies = async (scenarioCode, requiredSystems = null) => {
  const dependencies = scenarioSystemDependencies(scenarioCode);
  const required = new Set((requiredSystems || [
    ...(dependencies.pdd === true ? ['PDD'] : []),
    ...(dependencies.oms === true ? ['OMS'] : []),
    ...(dependencies.tms === true ? ['TMS'] : []),
  ]).map((value) => String(value || '').toUpperCase()));

  if (required.has('OMS')) {
    if (residentOmsWarmupPromise) {
      residentOmsWarmupExpedited = true;
      residentOmsWarmupExpediteResolver?.();
      await residentOmsWarmupPromise;
    }
    await focusSystemPage('oms', omsPage);
    await ensureOmsLogin(omsPage, context);
    if (omsMode !== 'shared') updateAuthHealth('oms', 'authenticated', omsPage);
  }
  if (required.has('TMS')) {
    await focusSystemPage('tms', tmsPage);
    await openTmsCustomerRegistration(tmsPage, context);
    updateAuthHealth('tms', 'authenticated', tmsPage);
  }
  // The OMS SPA can redirect its otherwise authenticated anchor back to
  // /login while TMS navigation is in progress. Revalidate it after TMS so a
  // recoverable session expiry does not become a permanent login pause.
  if (required.has('OMS') && required.has('TMS')) {
    await focusSystemPage('oms', omsPage);
    await ensureOmsLogin(omsPage, context);
    if (omsMode !== 'shared') updateAuthHealth('oms', 'authenticated', omsPage);
  }
  if (required.has('PDD')) {
    assertAuthenticatedSystemTabs(['pdd']);
  }
  assertAuthenticatedSystemTabs([
    ...(required.has('PDD') ? ['pdd'] : []),
    ...(required.has('OMS') ? ['oms'] : []),
    ...(required.has('TMS') ? ['tms'] : []),
  ]);
  return { scenarioCode, requiredSystems: [...required] };
};

const assertOmsBusinessSession = (targetPage = omsPage) => {
  let parsed;
  try {
    parsed = new URL(targetPage.url());
  } catch {
    throw new Error(`OMS 标签 URL 无效: ${targetPage.url()}`);
  }
  if (parsed.origin !== 'https://www.jeoms.com'
    || /\/xianma\/login(?:\/|\?|$)/.test(parsed.pathname)) {
    updateAuthHealth('oms', 'expired', targetPage, { reason: 'login-page-detected-before-work-order' });
    throw new Error(`OMS 未登录，禁止继续自动处理工单: ${targetPage.url()}`);
  }
  return true;
};

// URL alone is not proof of an authenticated OMS session. After refresh or
// recovery, require the rendered business shell before updating authHealth.
const confirmOmsBusinessPage = async (targetPage, stage) => {
  const state = await waitForOmsAppReadyWithRecovery(targetPage, stage, {
    allowLoginForm: false,
    recoveryUrl: targetPage.url(),
  });
  if (state.state !== 'business') {
    updateAuthHealth('oms', 'expired', targetPage, {
      stage,
      reason: 'business-page-not-rendered-after-recovery',
    });
    throw new Error(`OMS 恢复后未进入业务页: ${targetPage.url()}`);
  }
  assertOmsBusinessSession(targetPage);
  return state;
};

const resumeActiveSystem = (progress) => {
  const orderNumber = progress.orderNumber;
  if (!orderNumber) return 'pdd';
  if (progress.pddResolutionSubmission?.status === 'succeeded') return 'pdd';
  const pddComplete = hasCompleteScenarioLogisticsAnalysis(
    progress.logisticsAnalysis,
    orderNumber,
    progress.scenarioCode,
  )
    && (hasConsumablePddEvidence(progress, orderNumber)
      || progress.pddEvidenceScreenshot?.status === 'deleted');
  if (!pddComplete) return 'pdd';
  if (!hasCompleteScenarioOmsAnalysis(
    progress.omsAnalysis,
    progress.logisticsAnalysis,
    orderNumber,
    progress.scenarioCode,
  ) || forceOmsRecheck) return 'oms';
  if (hasCompletedTmsBypass(progress, orderNumber)) return 'pdd';
  if (progress.tmsWorkOrder?.status === 'created'
    && progress.tmsWorkOrder.orderNumber === orderNumber
    && progress.tmsEvidenceScreenshot?.orderNumber === orderNumber) return 'pdd';
  return 'tms';
};

const restoreAndAuthenticateSystemTabs = async (
  progress,
  requiredSystems = ['pdd', 'oms', 'tms'],
) => {
  const required = new Set(requiredSystems.map((system) => String(system || '').toLowerCase()));
  const targets = restoredSystemTargets(progress);
  if (required.has('oms') && omsMode !== 'shared') {
    await navigateSystemPage(omsPage, targets.oms, 'restore-oms-tab');
    persistSystemTabs('oms');
  }
  if (required.has('tms')) {
    await navigateSystemPage(tmsPage, targets.tms, 'restore-tms-tab');
    persistSystemTabs('tms');
  }
  if (required.has('pdd')) {
    await pacedAction(pddPage, 'restore-pdd-tab', () => (
      navigateSystemPage(pddPage, targets.pdd, 'restore-pdd-tab')
    ));
  }
  persistSystemTabs(null);

  if (required.has('oms')) {
    await focusSystemPage('oms', omsPage);
    await ensureOmsLogin(omsPage, context);
    if (omsMode !== 'shared') {
      if (omsPage.url() !== targets.oms) {
        await restoreOmsBusinessRoute(omsPage, targets.oms, 'restore-oms-business');
      }
      await confirmOmsBusinessPage(omsPage, 'restore-oms-business-confirm');
      updateAuthHealth('oms', 'authenticated', omsPage);
    }
  }

  if (required.has('tms')) {
    await focusSystemPage('tms', tmsPage);
    await openTmsCustomerRegistration(tmsPage, context);
    updateAuthHealth('tms', 'authenticated', tmsPage);
  }

  if (required.has('pdd')) {
    await focusSystemPage('pdd', pddPage);
    await ensurePddLogin(pddPage, context, targets.pdd);
    updateAuthHealth('pdd', 'authenticated', pddPage);
  }
  assertAuthenticatedSystemTabs([...required]);

  const preferredSystem = resumeActiveSystem(readProgress());
  const visiblePreferredSystem = omsMode === 'shared' && preferredSystem === 'oms'
    ? (required.has('pdd') ? 'pdd' : required.has('tms') ? 'tms' : 'oms')
    : preferredSystem;
  const activeSystem = required.has(visiblePreferredSystem)
    ? visiblePreferredSystem
    : [...required][0] || 'pdd';
  const activePage = activeSystem === 'oms' ? omsPage : activeSystem === 'tms' ? tmsPage : pddPage;
  await focusSystemPage(activeSystem, activePage);
  persistSystemTabs(activeSystem);
  return { targets, activeSystem };
};

const refreshAuthenticatedSessions = async () => {
  const progress = readProgress();
  if (progress.step === 'human-verification-required') return false;
  const targets = restoredSystemTargets(progress);
  const activeSystem = progress.systemTabs?.activeSystem || resumeActiveSystem(progress);
  await ensureOmsLogin(omsPage, context);
  if (omsMode !== 'shared') {
    if (omsPage.url() !== targets.oms) await restoreOmsBusinessRoute(omsPage, targets.oms, 'health-oms-business');
    await confirmOmsBusinessPage(omsPage, 'health-oms-business-confirm');
  }
  await openTmsCustomerRegistration(tmsPage, context);
  await ensurePddLogin(pddPage, context, targets.pdd);
  assertAuthenticatedSystemTabs();
  const visibleActiveSystem = omsMode === 'shared' && activeSystem === 'oms' ? 'pdd' : activeSystem;
  const activePage = visibleActiveSystem === 'oms' ? omsPage : visibleActiveSystem === 'tms' ? tmsPage : pddPage;
  await focusSystemPage(visibleActiveSystem, activePage);
  persistSystemTabs(visibleActiveSystem);
  return true;
};

const escapeRegex = (value) => String(value).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

const tmsFormItem = (scope, label) => scope.locator('.el-form-item__label')
  .filter({ hasText: new RegExp(`^\\s*${escapeRegex(label)}\\s*$`) })
  .first()
  .locator('xpath=ancestor::*[contains(concat(" ", normalize-space(@class), " "), " el-form-item ")][1]');

const readTmsFormValue = async (dialog, label) => {
  let item = tmsFormItem(dialog, label);
  // Element Plus includes the required asterisk in the label's text, so an
  // exact label match can miss populated fields such as "发货仓库". Fall back
  // to a text match within the visible form item.
  if (!await item.count()) {
    item = dialog.locator('.el-form-item:visible').filter({ hasText: label }).first();
  }
  if (!await item.count()) return null;
  const field = item.locator('input, textarea').first();
  if (await field.count()) {
    const value = await field.inputValue().catch(() => '');
    if (value.trim()) return value.trim();
  }
  const selected = item.locator('.el-select__selected-item, .el-select__placeholder').first();
  const selectedText = await selected.innerText().catch(() => '');
  if (selectedText.trim() && !selectedText.includes(label)) return selectedText.trim();
  const contentText = await item.locator('.el-form-item__content').innerText().catch(() => '');
  const contentLines = contentText.split(/\r?\n/).map((line) => line.trim()).filter(Boolean)
    .filter((line) => line !== label && !line.includes(`${label}：`) && !line.includes(`${label}:`));
  return contentLines.at(-1) || selectedText.trim() || null;
};

const findDeepValue = (value, keys) => {
  const stack = [value];
  const seen = new Set();
  while (stack.length) {
    const current = stack.pop();
    if (!current || typeof current !== 'object' || seen.has(current)) continue;
    seen.add(current);
    for (const key of keys) {
      if (Object.hasOwn(current, key) && current[key] !== null
        && current[key] !== undefined && current[key] !== '') return current[key];
    }
    const children = Array.isArray(current) ? current : Object.values(current);
    for (let index = children.length - 1; index >= 0; index--) stack.push(children[index]);
  }
  return null;
};

const readSuccessfulApiResponse = async (response, stage) => {
  if (!response) throw new Error(`${stage} 未捕获到接口响应`);
  const json = await response.json().catch(() => null);
  if (!response.ok()) throw new Error(`${stage} 接口返回 HTTP ${response.status()}`);
  if (json?.success === false || (typeof json?.code === 'number' && json.code >= 400)) {
    throw new Error(`${stage} 接口返回失败: ${json?.message || json?.msg || json.code}`);
  }
  return json;
};

const findTmsFilterPanel = async (targetPage) => firstVisible([
  targetPage.locator('.filter-panel:visible'),
  targetPage.locator('.el-drawer:visible').filter({ hasText: '交易号' }),
  targetPage.locator('.el-popover:visible').filter({ hasText: '交易号' }),
  targetPage.locator('[role="dialog"]:visible').filter({ hasText: '交易号' }),
  targetPage.locator('.filter-form:visible').filter({ hasText: '交易号' }),
]);

const filterTmsTicketsByOrderOnce = async (
  targetPage,
  orderNumber,
  { browserContext = context, recoveryPasses = 2 } = {},
) => {
  const closeBlockingTmsDrawers = async () => {
    for (let attempt = 0; attempt < 4; attempt++) {
      const drawer = targetPage.locator('.el-drawer:visible, .el-overlay.is-drawer:visible').last();
      if (!await drawer.isVisible().catch(() => false)) break;
      const drawerPanel = await firstVisible([
        drawer.locator('.filter-panel:visible'),
        drawer.locator('.filter-form:visible'),
      ]);
      if (drawerPanel) return drawerPanel;
      if (await drawer.locator('.filter-panel:visible, .filter-form:visible').count()) {
        await drawer.locator('.filter-panel:visible, .filter-form:visible').first()
          .waitFor({ state: 'visible', timeout: 5000 }).catch(() => {});
        const renderedPanel = await findTmsFilterPanel(targetPage);
        if (renderedPanel) return renderedPanel;
      }
      const closeButton = await firstVisible([
        drawer.locator('.el-drawer__close-btn'),
        drawer.locator('.el-drawer__headerbtn'),
        drawer.locator('[aria-label="Close"], [aria-label="关闭"]'),
        drawer.getByRole('button', { name: /关闭/ }),
      ]);
      if (!closeButton) {
        throw new Error('TMS 筛选按钮被其他抽屉遮挡，且该抽屉没有安全关闭按钮');
      }
      await pacedAction(targetPage, 'close-stale-tms-drawer', () => closeButton.click({ force: true }));
      await drawer.waitFor({ state: 'hidden', timeout: 10000 });
      await targetPage.waitForTimeout(250);
    }
    const blockingDrawer = targetPage.locator('.el-drawer:visible, .el-overlay.is-drawer:visible').last();
    if (await blockingDrawer.isVisible().catch(() => false)) {
      throw new Error('TMS 筛选按钮仍被未完成过渡的抽屉遮挡');
    }
    return null;
  };

  const openFilterPanel = async () => {
    const stabilizePanel = async (candidate) => {
      if (!candidate) return null;
      return await candidate.waitFor({ state: 'visible', timeout: 10_000 })
        .then(() => candidate)
        .catch(() => null);
    };
    // A panel may be visible behind another drawer while its controls cannot
    // receive pointer events. Resolve the topmost drawer before accepting it.
    let panel = await closeBlockingTmsDrawers();
    panel = await stabilizePanel(panel);
    if (panel) return panel;
    panel = await stabilizePanel(await findTmsFilterPanel(targetPage));
    if (panel) return panel;
    // A committed /logistics navigation may take tens of seconds to render
    // its toolbar. Do not reload a valid, still-hydrating page immediately.
    let filterButton = null;
    const entryDeadline = Date.now() + 40_000;
    do {
      filterButton = await firstVisible([
        targetPage.locator('.toolbar:visible').getByRole('button', { name: /筛选/ }),
        targetPage.getByRole('button', { name: /筛选/ }),
        targetPage.getByText('筛选', { exact: true }),
      ]);
      if (filterButton) break;
      await targetPage.waitForTimeout(500);
    } while (Date.now() < entryDeadline);
    if (!filterButton) return null;
    // The toolbar may appear before the ticket list finishes loading.
    // Clicking during the mask can be ignored by the TMS application.
    const listLoading = targetPage.locator('.table-container .el-loading-mask').first();
    if (await listLoading.isVisible().catch(() => false)) {
      const listSettled = await listLoading.waitFor({ state: 'hidden', timeout: 30_000 })
        .then(() => true).catch(() => false);
      if (!listSettled) return null;
    }
    for (let openAttempt = 0; openAttempt < 2; openAttempt++) {
      if (openAttempt > 0) {
        // The toolbar click can be ignored while the SPA finishes mounting.
        // Retry this read-only toggle once before paying for a route reload.
        await targetPage.waitForTimeout(1000);
        panel = await stabilizePanel(await closeBlockingTmsDrawers());
        if (panel) return panel;
      }
      await filterButton.scrollIntoViewIfNeeded().catch(() => {});
      await pacedAction(targetPage, 'expand-tms-filter', async () => {
        // Pacing or verification may have waited while a previous click opened
        // the panel. Recheck at the actual click boundary so we never close it.
        panel = await stabilizePanel(await findTmsFilterPanel(targetPage));
        if (!panel) await filterButton.click();
      });
      const panelDeadline = Date.now() + 10_000;
      do {
        panel = await stabilizePanel(await findTmsFilterPanel(targetPage));
        if (panel) return panel;
        await targetPage.waitForTimeout(250);
      } while (Date.now() < panelDeadline);
    }
    return null;
  };

  let panel = null;
  let lastRecoveryError = null;
  for (let pass = 0; pass <= recoveryPasses; pass++) {
    panel = await openFilterPanel();
    if (panel) break;
    if (pass >= recoveryPasses) break;
    writeProgress({
      step: 'tms-filter-panel-recovery',
      tmsFilterRecovery: {
        orderNumber,
        pass: pass + 1,
        maxPasses: recoveryPasses,
        status: 'reloading-registration-page',
        attemptedAt: new Date().toISOString(),
      },
      error: null,
    });
    try {
      await navigateSystemPage(
        targetPage,
        tmsLogisticsUrl,
        `recover-tms-filter-panel-${pass + 1}`,
      );
      await openTmsCustomerRegistration(targetPage, browserContext);
      await closeUnexpectedTmsPopups(targetPage);
    } catch (error) {
      if (error instanceof HumanVerificationRequiredError
        || error instanceof PddLoginRequiredError
        || error instanceof RateLimitPauseError
        || error instanceof ManualReviewRequiredError
        || error instanceof LogisticsRetryRequiredError) throw error;
      lastRecoveryError = error;
    }
  }
  if (!panel) {
    const suffix = lastRecoveryError ? `: ${lastRecoveryError.message}` : '';
    throw new Error(`TMS 物流问题登记表（客服）筛选面板在有界恢复后仍未渲染${suffix}`);
  }
  const tradeItem = tmsFormItem(panel, '交易号');
  const tradeInput = tradeItem.locator('input').first();
  if (!await tradeInput.count()) throw new Error('TMS 筛选区未找到交易号输入框');
  await pacedAction(targetPage, 'fill-tms-ticket-filter', () => tradeInput.fill(orderNumber));
  // Element Plus can render the typed value before its filter model is ready.
  // Give the read-only query a human-sized pause before applying it; otherwise
  // /api/logistics/tickets may be requested without tradeId and look like a
  // missing ticket even though the exact created row exists.
  await targetPage.waitForTimeout(1000);
  // TMS can open a second drawer after the field is filled. The filter is
  // read-only, but do not click through an unrelated overlay or force-click.
  await closeBlockingTmsDrawers();
  const applyButton = await firstVisible([
    panel.getByRole('button', { name: '应用', exact: true }),
    panel.getByText('应用', { exact: true }),
  ]);
  if (!applyButton) throw new Error('TMS 筛选区未找到应用按钮');
  const responsePromise = targetPage.waitForResponse((response) => (
    response.request().method() === 'GET'
    && response.url().includes('/api/logistics/tickets')
    && !response.url().includes('/order-count')
  ), { timeout: 30000 }).catch(() => null);
  await pacedAction(targetPage, 'apply-tms-ticket-filter', () => applyButton.click());
  const response = await responsePromise;
  if (!response) {
    // Filtering is read-only. A missing response does not prove that the
    // ticket is absent, so release the order for a bounded, delayed retry
    // instead of leaving a zero-effect order permanently paused.
    await pauseForTransientRetry(
      targetPage,
      'tms-ticket-filter-response',
      'TMS_TICKET_FILTER_TEMPORARILY_UNAVAILABLE',
      'TMS 交易号筛选未收到查询响应',
      { tmsTicketFilterRecovery: { orderNumber, status: 'retry-ready',
        reason: 'no-query-response', checkedAt: new Date().toISOString() } },
      5 * 60_000,
    );
  }
  if (new URL(response.url()).searchParams.get('tradeId') !== orderNumber) {
    throw new Error('TMS 交易号筛选请求未携带目标交易号');
  }
  if (!response.ok()) {
    const error = new Error(`TMS 交易号筛选接口返回 HTTP ${response.status()}`);
    if (response.status() === 401) error.code = 'TMS_TICKET_FILTER_UNAUTHORIZED';
    throw error;
  }
  await targetPage.locator('.table-container .el-loading-mask').waitFor({ state: 'hidden', timeout: 30000 }).catch(() => {});
  const rows = targetPage.locator('.table-container .el-table__body-wrapper tbody tr');
  const exactRows = rows.filter({ has: targetPage.getByText(orderNumber, { exact: true }) });
  return { exactRows, count: await exactRows.count(), payload: null };
};

const filterTmsTicketsByOrder = async (
  targetPage,
  orderNumber,
  options = {},
) => {
  const browserContext = options.browserContext || context;
  for (let attempt = 0; attempt < 2; attempt++) {
    try {
      const result = await filterTmsTicketsByOrderOnce(targetPage, orderNumber, options);
      if (attempt > 0) {
        writeProgress({ tmsTicketFilterRecovery: { orderNumber, status: 'succeeded',
          reason: 'query-confirmed-after-page-refresh', readOnly: true,
          checkedAt: new Date().toISOString() } });
      }
      return result;
    } catch (error) {
      if (error.code !== 'TMS_TICKET_FILTER_UNAUTHORIZED') throw error;
      if (attempt === 1) {
        await pauseForTransientRetry(
          targetPage,
          'tms-ticket-filter-authorization',
          'TMS_TICKET_FILTER_TEMPORARILY_UNAVAILABLE',
          'TMS 交易号筛选刷新业务页后仍返回 HTTP 401',
          { tmsTicketFilterRecovery: { orderNumber, status: 'retry-ready',
            reason: 'authorization-recovery-exhausted', readOnly: true,
            checkedAt: new Date().toISOString() } },
          5 * 60_000,
        );
      }
      writeProgress({
        step: 'tms-ticket-filter-authorization-recovering',
        tmsTicketFilterRecovery: { orderNumber, status: 'refreshing-business-page',
          reason: 'http-401', readOnly: true, attempt: 1,
          checkedAt: new Date().toISOString() },
        error: null,
      });
      // Refresh only the read-only registration page. Its SPA may still hold
      // an older token after another TMS tab restores this profile's session.
      // Existing login recovery handles an actual login page; do not clear
      // storage or label PDD/OMS logged out based on this TMS response.
      await targetPage.waitForTimeout(1000);
      await navigateSystemPage(targetPage, tmsLogisticsUrl, 'recover-tms-ticket-filter-authorization');
      await openTmsCustomerRegistration(targetPage, browserContext);
      await closeUnexpectedTmsPopups(targetPage);
    }
  }
};

const readTmsRowIdentity = async (row) => row.evaluate((sourceRow) => {
  const table = sourceRow.closest('.el-table');
  const headers = [...(table?.querySelectorAll('.el-table__header-wrapper thead tr:last-child th') || [])]
    .map((header) => (header.innerText || '').replace(/\s+/g, ' ').trim());
  const cells = [...sourceRow.children].filter((element) => element.tagName === 'TD')
    .map((cell) => (cell.innerText || '').replace(/\s+/g, ' ').trim());
  const values = Object.fromEntries(headers.map((header, index) => [header, cells[index] || '']));
  const attrValue = sourceRow.getAttribute('data-id')
    || sourceRow.getAttribute('data-ticket-id')
    || sourceRow.querySelector('[data-id], [data-ticket-id]')?.getAttribute('data-id')
    || null;
  return { headers, cells, values, attrValue, text: (sourceRow.innerText || '').replace(/\s+/g, ' ').trim() };
}).catch(() => ({ headers: [], cells: [], values: {}, attrValue: null, text: '' }));

const firstDefinedTmsIdentityValue = (identity, labels) => {
  for (const label of labels) {
    const value = String(identity?.values?.[label] || '').trim();
    if (value) return value;
  }
  return '';
};

const existingTmsIdentityFields = (identity) => ({
  tracking: firstDefinedTmsIdentityValue(identity, ['运单号', '物流单号', '快递单号']),
  warehouse: firstDefinedTmsIdentityValue(identity, ['发货仓库', '仓库']),
  carrier: firstDefinedTmsIdentityValue(identity, ['责任快递', '快递公司', '承运商']),
});

const tmsExistingTicketSuborderComparison = ({
  identity,
  record,
  progress,
  orderNumber,
  candidateCount,
  tracking,
  warehouse,
  carrier,
}) => {
  const expectedOmsOrder = String(
    progress?.tmsAutofillCandidateSelection?.candidateEvaluation?.actual?.orderNumber
      || progress?.omsGridCells?.find((cell) => cell?.colId === 'salesOrderCode')?.text
      || '',
  ).trim();
  const existingOmsOrder = String(
    firstDefinedTmsIdentityValue(identity, ['\u8ba2\u5355\u53f7'])
      || findDeepValue(record, ['salesOrderCode', 'salesOrderNo', 'orderCode'])
      || '',
  ).trim();
  const expectedTracking = normalizeBusinessText(progress?.logisticsAnalysis?.trackingNumber);
  const existingTracking = normalizeBusinessText(
    tracking || firstDefinedTmsIdentityValue(identity, ['\u8fd0\u5355\u53f7']),
  );
  const existingWarehouse = String(
    warehouse || firstDefinedTmsIdentityValue(identity, ['\u53d1\u8d27\u4ed3\u5e93']),
  ).trim();
  const existingCarrier = String(
    carrier || firstDefinedTmsIdentityValue(identity, ['\u8d23\u4efb\u5feb\u9012']),
  ).trim();
  const sameTrade = Boolean(orderNumber && String(identity?.text || '').includes(orderNumber));
  const omsOrderDistinct = /^SO[\w-]+$/i.test(expectedOmsOrder)
    && /^SO[\w-]+$/i.test(existingOmsOrder)
    && expectedOmsOrder !== existingOmsOrder;
  const trackingDistinct = Boolean(
    expectedTracking && existingTracking && expectedTracking !== existingTracking,
  );
  return {
    provablyDifferent: Number(candidateCount) === 1
      && sameTrade
      && omsOrderDistinct
      && trackingDistinct,
    sameTrade,
    expectedOmsOrder: expectedOmsOrder || null,
    existingOmsOrder: existingOmsOrder || null,
    expectedTracking: expectedTracking || null,
    existingTracking: existingTracking || null,
    existingWarehouse: existingWarehouse || null,
    existingCarrier: existingCarrier || null,
    omsOrderDistinct,
    trackingDistinct,
  };
};

const identifyExistingTmsTicket = async (
  selection,
  orderNumber,
  progress,
  {
    allowMissingExpectedLogistics = false,
    allowReadableUnmappedValues = false,
    formDecision = null,
    knownTicket = null,
  } = {},
) => {
  const selectionAudit = {
    candidateCount: Number(selection?.count || 0),
    selectedIndex: Number.isInteger(selection?.selectedIndex) ? selection.selectedIndex : null,
    selectionStrategy: selection?.selectionStrategy || null,
  };
  if (!selection?.row) {
    return {
      status: 'manual',
      reason: 'TMS 同订单记录中没有可安全定位的工单',
      ...selectionAudit,
    };
  }
  const identity = await readTmsRowIdentity(selection.row);
  const identityFields = existingTmsIdentityFields(identity);
  const rowTicketNo = String(
    firstDefinedTmsIdentityValue(identity, ['工单号', '工单编号']) || identity.attrValue || '',
  ).trim();
  const canUseSavedTicketIdentity = Boolean(
    selectionAudit.candidateCount === 1
    && selectionAudit.selectionStrategy === 'api-created-exact-order-only-row'
    && knownTicket?.status === 'created'
    && knownTicket?.orderNumber === orderNumber
    && String(knownTicket?.ticketId || '').trim()
    && String(knownTicket?.ticketNo || '').trim()
    && identity.text.includes(orderNumber),
  );
  // The rendered exact row is the authoritative TMS record. The list API can
  // return excessively deep payloads, while every required business field is
  // already visible in this row; never deserialize or traverse that payload.
  const record = {};
  const tracking = String(findDeepValue(record, [
    'trackingNumber', 'waybillNumber', 'waybillNo', 'expressNo', 'logisticsNo',
  ]) || identityFields.tracking || '');
  const warehouse = String(findDeepValue(record, [
    'shippingWarehouse', 'warehouse', 'warehouseName', 'deliveryWarehouse',
  ]) || identityFields.warehouse || '');
  const carrier = String(findDeepValue(record, [
    'carrier', 'expressCompany', 'expressName', 'responsibleCarrier',
  ]) || identityFields.carrier || '');
  const ticketNo = String(rowTicketNo
    || findDeepValue(record, ['ticketNo', 'workOrderNo', 'orderNo'])
    || (canUseSavedTicketIdentity ? knownTicket.ticketNo : '')).trim();
  const ticketId = String(findDeepValue(record, ['ticketId', 'id'])
    || identity.attrValue
    || (canUseSavedTicketIdentity ? knownTicket.ticketId : '')
    || ticketNo).trim();
  const rowText = identity.text;
  const expectedTracking = normalizeBusinessText(progress.logisticsAnalysis?.trackingNumber);
  const authoritativeWarehouseReconciled = progress.tmsAutofillVerification?.warehouseVerification?.status === 'reconciled';
  const expectedWarehouseValue = authoritativeWarehouseReconciled
    ? progress.tmsAutofillVerification.warehouseVerification.authoritativeWarehouse
    : progress.omsAnalysis?.shippingWarehouse;
  const expectedWarehouse = matchBusinessCategories(expectedWarehouseValue, warehouseCategories, { warehouse: true });
  const expectedCarrier = matchCarrierCategories(progress.logisticsAnalysis?.carrier);
  const actualWarehouse = matchBusinessCategories(warehouse || rowText, warehouseCategories, { warehouse: true });
  const actualCarrier = matchCarrierCategories(carrier || rowText);
  const trackingMatches = expectedTracking
    ? normalizeBusinessText(tracking || rowText).includes(expectedTracking)
    : allowMissingExpectedLogistics;
  const warehouseMatches = (expectedWarehouse.matches.length === 1
    && actualWarehouse.matches.some(({ key }) => key === expectedWarehouse.matches[0].key))
    || ((allowReadableUnmappedValues || authoritativeWarehouseReconciled)
      && expectedWarehouse.normalized
      && actualWarehouse.normalized
      && (expectedWarehouse.normalized.includes(actualWarehouse.normalized)
        || actualWarehouse.normalized.includes(expectedWarehouse.normalized)));
  const carrierMatches = expectedCarrier.matches.length === 1
    ? actualCarrier.matches.some(({ key }) => key === expectedCarrier.matches[0].key)
    : allowMissingExpectedLogistics && Boolean(actualCarrier.normalized);
  const suborderComparison = tmsExistingTicketSuborderComparison({
    identity,
    record,
    progress,
    orderNumber,
    candidateCount: selectionAudit.candidateCount,
    tracking,
    warehouse,
    carrier,
  });
  if (suborderComparison.provablyDifferent) {
    return {
      status: 'unrelated',
      reason: '已有 TMS 工单属于同交易下的另一条 OMS 子订单',
      identity: { ...identity, tracking, warehouse, carrier, ticketId, ticketNo },
      suborderComparison,
      ...selectionAudit,
    };
  }
  const decisionComparison = compareExistingTmsTicketDecision({
    identity,
    formDecision,
    candidateCount: selectionAudit.candidateCount,
  });
  if (decisionComparison.required && !decisionComparison.matches) {
    return {
      status: 'unrelated',
      reason: '已有 TMS 工单的物流问题或客服备注与本次处理要求不一致',
      identity: { ...identity, tracking, warehouse, carrier, ticketId, ticketNo },
      decisionComparison,
      ...selectionAudit,
    };
  }
  const orderMatches = rowText.includes(orderNumber);
  const authoritativeExistingWarehouse = shouldUseUniqueExistingTmsWarehouseAsAuthoritative({
    candidateCount: selectionAudit.candidateCount,
    orderMatches,
    trackingMatches,
    carrierMatches,
    warehouseMatches,
    ticketId,
    ticketNo,
    existingWarehouse: warehouse,
    decisionComparison,
    suborderComparison,
  });
  const warehouseReconciliation = authoritativeExistingWarehouse ? {
    status: 'reconciled',
    source: 'unique-existing-tms-ticket',
    expectedOmsWarehouse: expectedWarehouseValue || null,
    authoritativeWarehouse: warehouse,
    reason: '唯一既有 TMS 工单核心身份一致，复用 TMS 已保存仓库',
  } : null;
  if (!orderMatches || !trackingMatches
    || (!warehouseMatches && !authoritativeExistingWarehouse) || !carrierMatches) {
    return {
      status: 'manual',
      reason: '已有 TMS 工单无法同时核对订单、运单号、仓库和快递',
      identity: { ...identity, tracking, warehouse, carrier, ticketId, ticketNo },
      decisionComparison,
      suborderComparison,
      ...selectionAudit,
    };
  }
  if (!ticketId || !ticketNo) {
    return {
      status: 'manual',
      reason: '已有 TMS 工单缺少可保存的工单标识',
      identity,
      ...selectionAudit,
    };
  }
  return {
    status: 'matched',
    row: selection.row,
    ticketId,
    ticketNo,
    identity: { ...identity, tracking, warehouse, carrier },
    decisionComparison,
    suborderComparison,
    warehouseReconciliation,
    ...selectionAudit,
  };
};

const withUnblockedTmsReadOnlyQueryPage = async (targetPage, orderNumber, query) => {
  const businessForm = targetPage.locator([
    '.el-overlay:visible form.logistics-form:visible',
    '.el-overlay-dialog:visible form.logistics-form:visible',
    '[role="dialog"]:visible form.logistics-form:visible',
  ].join(', ')).first();
  if (!await businessForm.isVisible().catch(() => false)) return query(targetPage);
  // An uncertain save can leave its form above the list. Keep that form and
  // its contents; neither a close click nor another save proves the outcome.
  await checkForHumanVerification(targetPage, 'tms-readonly-reconciliation-blocking-form');
  if (!await businessForm.isVisible().catch(() => false)) return query(targetPage);
  const queryPage = registerDerivedPage(await createBackgroundPage(), 'tms-create-readonly-query');
  writeProgress({ tmsReadOnlyQueryPage: {
    orderNumber, status: 'opening', reason: 'visible-business-form',
    originalUrl: targetPage.url(), openedAt: new Date().toISOString(),
    readOnly: true, externalActionsReplayed: false,
  } });
  try {
    await pacedAction(queryPage, 'open-tms-readonly-reconciliation-query', () => (
      navigateSystemPage(queryPage, tmsLogisticsUrl, 'tms-readonly-reconciliation-query')
    ));
    await queryPage.waitForTimeout(1_000);
    const observation = await query(queryPage);
    // After an exact existing ticket is confirmed, subsequent evidence and
    // follow-up steps also need an unobstructed anchor. Retain the old form
    // as a protected derived tab instead of discarding its uncertain input.
    if (targetPage === tmsPage && observation?.state === 'confirmed'
      && observation.effectType === 'tms-create' && observation.readOnly === true
      && observation.orderNumber === orderNumber) {
      tmsPage = monitorSystemPage('tms', queryPage);
      derivedPages.delete(queryPage);
      derivedPageMeta.delete(queryPage);
      registerDerivedPage(targetPage, 'tms-unconfirmed-form-preserved');
      derivedPageMeta.set(targetPage, {
        ...derivedPageMeta.get(targetPage), preserveUnconfirmedTmsForm: true,
      });
      persistSystemTabs('tms');
      writeProgress({ tmsReadOnlyQueryPage: {
        ...readProgress().tmsReadOnlyQueryPage, status: 'confirmed-query-anchor',
        confirmedAt: new Date().toISOString(), originalFormPreserved: true,
      } });
    }
    return observation;
  } finally {
    if (queryPage !== tmsPage && !queryPage.isClosed()) {
      const verification = await hasHumanVerification(queryPage).catch(() => true);
      const login = isSystemLoginUrl('tms', queryPage.url());
      if (verification || login) {
        const location = readProgress().verificationLocation;
        if (location?.system === 'tms' && location.id) {
          protectVerificationRecoveryPage(queryPage, location.id);
        }
        writeProgress({ tmsReadOnlyQueryPage: {
          ...readProgress().tmsReadOnlyQueryPage,
          status: verification ? 'waiting-verification' : 'waiting-login',
          url: queryPage.url(), originalFormPreserved: true,
        } });
      } else await closeDerivedPage(queryPage);
    }
  }
};

const reconcileTmsCreateStateOnPage = async (targetPage, orderNumber) => {
  const startedAt = new Date().toISOString();
  const progress = readProgress();
  const scenarioCode = progress.scenarioCode
    || activeScenarioCode
    || matchingScenarioForTitle(progress.workOrderType || activeWorkOrderType)?.code
    || null;
  const allowConditionalScenario = isExtendedOrdinaryScenario(scenarioCode);
  const formDecision = progress.tmsFormDecision || null;
  const effectStage = progress.tmsWorkOrder?.effectStage || 'create-ticket';
  const query = async (pass) => {
    await openTmsCustomerRegistration(targetPage, context);
    const filtered = await filterTmsTicketsByOrder(targetPage, orderNumber);
    const selectionPolicy = tmsCreateReconciliationSelectionPolicy({
      candidateCount: filtered.count,
      pass,
    });
    const selection = {
      ...filtered,
      row: selectionPolicy.selectedIndex === null
        ? null
        : filtered.exactRows.nth(selectionPolicy.selectedIndex),
      ...selectionPolicy,
    };
    writeProgress({
      step: `tms-create-reconciliation-query-pass-${pass}`,
      tmsCreateReconciliation: {
        orderNumber,
        effectStage,
        pass,
        candidateCount: filtered.count,
        startedAt,
        checkedAt: new Date().toISOString(),
        readOnly: true,
      },
      error: null,
    });
    return selection;
  };

  let selection = await query(1);
  let refreshed = false;
  if (selection.count === 0) {
    refreshed = true;
    writeProgress({
      step: 'tms-create-reconciliation-refreshing',
      tmsCreateReconciliation: {
        ...(readProgress().tmsCreateReconciliation || {}),
        status: 'refreshing-before-final-zero-result',
        refreshedAt: new Date().toISOString(),
      },
    });
    await targetPage.reload({ waitUntil: 'domcontentloaded', timeout: 30_000 });
    selection = await query(2);
  }

  const observedAt = new Date().toISOString();
  let observation;
  let recoveredWorkOrder = null;
  let duplicateCheck = null;
  if (selection.count >= 1 && selection.row) {
    const existing = await identifyExistingTmsTicket(selection, orderNumber, readProgress(), {
      allowMissingExpectedLogistics: allowConditionalScenario,
      allowReadableUnmappedValues: allowConditionalScenario
        || progress.tmsRoutingDecision?.precedence === 'fallback-intercept-return',
      formDecision,
    });
    const { row: _row, ...existingEvidence } = existing;
    duplicateCheck = {
      ...existingEvidence,
      orderNumber,
      checkedAt: observedAt,
      reconciliation: 'read-only-tms-create',
    };
    if (existing.status === 'matched') {
      const reconciliationMethod = selection.count === 1
        ? 'unique-exact-tms-ticket-and-identity-match'
        : 'first-exact-tms-ticket-user-authorized-and-identity-match';
      recoveredWorkOrder = {
        shopId,
        orderNumber,
        status: 'created',
        effectStage,
        ticketId: existing.ticketId,
        ticketNo: existing.ticketNo,
        problemType: formDecision?.problemType || null,
        customerRemark: formDecision?.customerRemark || null,
        existingDecisionComparison: existing.decisionComparison || null,
        existingWarehouseReconciliation: existing.warehouseReconciliation || null,
        createdAt: progress.tmsWorkOrder?.createdAt || observedAt,
        recovered: true,
        reconciledAt: observedAt,
        reconciliationMethod,
        error: null,
      };
      observation = {
        state: 'confirmed',
        effectType: 'tms-create',
        orderNumber,
        effectStage,
        ticketId: existing.ticketId,
        ticketNo: existing.ticketNo,
        candidateCount: selection.count,
        selectedIndex: selection.selectedIndex,
        selectionStrategy: selection.selectionStrategy,
        confirmationMethod: reconciliationMethod,
        identity: existing.identity || null,
        observedAt,
        readOnly: true,
      };
    } else {
      observation = {
        state: 'unresolved',
        effectType: 'tms-create',
        orderNumber,
        effectStage,
        candidateCount: selection.count,
        selectedIndex: selection.selectedIndex,
        selectionStrategy: selection.selectionStrategy,
        reason: existing.reason || 'TMS 唯一记录与当前订单身份字段不一致',
        confirmationMethod: null,
        identity: existing.identity || null,
        observedAt,
        readOnly: true,
      };
    }
  } else if (selection.count === 0 && refreshed) {
    observation = {
      state: 'not-applied',
      effectType: 'tms-create',
      orderNumber,
      effectStage,
      candidateCount: 0,
      confirmationMethod: 'refreshed-two-pass-exact-zero-result',
      observedAt,
      readOnly: true,
    };
  } else {
    observation = {
      state: 'unresolved',
      effectType: 'tms-create',
      orderNumber,
      effectStage,
      candidateCount: selection.count,
      reason: `TMS 精确查询到 ${selection.count} 条同订单记录，无法唯一核对中断前的创建结果`,
      confirmationMethod: null,
      observedAt,
      readOnly: true,
    };
  }

  writeProgress({
    step: observation.state === 'confirmed'
      ? 'tms-create-reconciled'
      : observation.state === 'not-applied'
        ? 'tms-create-not-applied'
        : 'external-state-unresolved',
    externalStateReconciliation: observation,
    tmsCreateReconciliation: {
      ...(readProgress().tmsCreateReconciliation || {}),
      status: observation.state,
      candidateCount: selection.count,
      refreshed,
      confirmationMethod: observation.confirmationMethod,
      reason: observation.reason || null,
      completedAt: observedAt,
      readOnly: true,
    },
    ...(duplicateCheck ? { tmsDuplicateCheck: duplicateCheck } : {}),
    ...(recoveredWorkOrder
      ? { tmsWorkOrder: recoveredWorkOrder }
      : observation.state === 'not-applied'
        ? { tmsWorkOrder: null }
        : {}),
    currentUrl: targetPage.url(),
    error: null,
  });
  logRunStep('external-state-reconciled', {
    orderNumber,
    externalStateReconciliation: observation,
  });
  return observation;
};

const reconcileTmsCreateState = async (targetPage, orderNumber) => (
  withUnblockedTmsReadOnlyQueryPage(targetPage, orderNumber,
    (queryPage) => reconcileTmsCreateStateOnPage(queryPage, orderNumber))
);

const selectKnownTmsRow = async (targetPage, orderNumber, workOrder = null) => {
  const knownCreatedTicket = workOrder?.orderNumber === orderNumber && workOrder?.status === 'created';
  let deadline = Date.now() + (knownCreatedTicket ? tmsCreatedRowVisibilityTimeoutMs : 0);
  let attempt = 0;
  let refreshAttempts = 0;
  while (true) {
    attempt++;
    const filtered = await filterTmsTicketsByOrder(targetPage, orderNumber);
    let row = null;
    let selectionStrategy = null;
    if (filtered.count === 1) {
      const soleRow = filtered.exactRows.first();
      const identifier = knownCreatedTicket
        ? String(workOrder.ticketNo || workOrder.ticketId || '').trim()
        : '';
      const soleRowText = knownCreatedTicket
        ? await soleRow.innerText().catch(() => '')
        : '';
      const savedIdentifierVisible = Boolean(identifier && soleRowText.includes(identifier));
      const apiCreatedExactOrderFallback = canUseApiCreatedTmsSoleRow({
        workOrder,
        candidateCount: filtered.count,
        rowText: soleRowText,
        orderNumber,
      });
      if (!knownCreatedTicket || savedIdentifierVisible || apiCreatedExactOrderFallback) {
        row = soleRow;
        selectionStrategy = !knownCreatedTicket
          ? 'only-row'
          : savedIdentifierVisible
            ? 'saved-ticket-identifier-only-row'
            : 'api-created-exact-order-only-row';
      }
    } else if (knownCreatedTicket && filtered.count > 1) {
      const identifier = String(workOrder.ticketNo || workOrder.ticketId || '');
      if (identifier) {
        const knownRows = filtered.exactRows.filter({ hasText: identifier });
        if (await knownRows.count() === 1) {
          row = knownRows.first();
          selectionStrategy = 'saved-ticket-identifier';
        }
      }
    } else if (!knownCreatedTicket && filtered.count > 1) {
      row = filtered.exactRows.first();
      selectionStrategy = 'first-row';
    }
    const selection = {
      row,
      count: filtered.count,
      selectionStrategy,
      payload: filtered.payload,
      attempts: attempt,
      refreshAttempts,
      waitedMs: knownCreatedTicket
        ? (refreshAttempts * tmsCreatedRowVisibilityTimeoutMs)
          + Math.max(0, tmsCreatedRowVisibilityTimeoutMs - Math.max(0, deadline - Date.now()))
        : 0,
    };
    if (row || !knownCreatedTicket) return selection;
    if (Date.now() >= deadline) {
      if (refreshAttempts >= 1) return selection;
      refreshAttempts++;
      const refreshStartedAt = new Date().toISOString();
      writeProgress({
        step: 'tms-created-row-refreshing',
        tmsCreatedRowVisibility: {
          orderNumber,
          ticketId: workOrder.ticketId || null,
          ticketNo: workOrder.ticketNo || null,
          status: 'refreshing',
          attempts: attempt,
          refreshAttempts,
          lastObservedCount: filtered.count,
          timeoutMs: tmsCreatedRowVisibilityTimeoutMs,
          refreshStartedAt,
        },
      });
      const refreshError = await targetPage.reload({
        waitUntil: 'domcontentloaded',
        timeout: tmsCreatedRowVisibilityTimeoutMs,
      }).then(() => null).catch((error) => error);
      writeProgress({
        tmsCreatedRowVisibility: {
          ...(readProgress().tmsCreatedRowVisibility || {}),
          status: 'waiting-after-refresh',
          refreshCompletedAt: new Date().toISOString(),
          refreshError: refreshError?.message || null,
        },
      });
      deadline = Date.now() + tmsCreatedRowVisibilityTimeoutMs;
      continue;
    }

    writeProgress({
      step: 'tms-created-row-waiting',
      tmsCreatedRowVisibility: {
        orderNumber,
        ticketId: workOrder.ticketId || null,
        ticketNo: workOrder.ticketNo || null,
        status: 'waiting',
        attempts: attempt,
        refreshAttempts,
        lastObservedCount: filtered.count,
        waitingForTicketId: workOrder.ticketId || null,
        waitingForTicketNo: workOrder.ticketNo || null,
        timeoutMs: tmsCreatedRowVisibilityTimeoutMs,
        checkedAt: new Date().toISOString(),
      },
    });
    await targetPage.waitForTimeout(Math.min(
      tmsCreatedRowPollIntervalMs,
      Math.max(0, deadline - Date.now()),
    ));
  }
};

const tmsAutofillCandidatesFromPayload = (payload) => {
  if (Array.isArray(payload)) return payload;
  if (Array.isArray(payload?.data)) return payload.data;
  if (Array.isArray(payload?.records)) return payload.records;
  if (Array.isArray(payload?.data?.records)) return payload.data.records;
  return [];
};

const reconcileTmsAutofillWarehouseMismatch = ({
  actual,
  orderNumber,
  logisticsAnalysis,
  omsAnalysis,
  warehouseMatches,
  sourceLookupConfirmed = false,
}) => {
  const actualOrderNumber = String(actual?.orderNumber || '').trim();
  const actualTradeId = String(actual?.tradeId || '').trim();
  const linkedOmsOrder = /^SO[\w-]+$/i.test(actualOrderNumber);
  const orderMatches = actualOrderNumber === orderNumber
    || actualTradeId === orderNumber
    || (sourceLookupConfirmed && linkedOmsOrder);
  const expectedTracking = normalizeBusinessText(logisticsAnalysis?.trackingNumber);
  const actualTracking = normalizeBusinessText(actual?.trackingNumber);
  const trackingMatches = Boolean(expectedTracking && actualTracking === expectedTracking);
  const expectedCarrier = matchCarrierCategories(logisticsAnalysis?.carrier);
  const actualCarrier = matchCarrierCategories(actual?.carrier);
  const carrierCategoryMatches = expectedCarrier.matches.length === 1
    && actualCarrier.matches.length === 1
    && expectedCarrier.matches[0].key === actualCarrier.matches[0].key;
  const carrierTextMatches = Boolean(
    expectedCarrier.normalized
    && actualCarrier.normalized
    && expectedCarrier.normalized === actualCarrier.normalized,
  );
  const carrierMatches = carrierCategoryMatches || carrierTextMatches;
  const expectedWarehouse = normalizeBusinessText(omsAnalysis?.shippingWarehouse, { warehouse: true });
  const actualWarehouse = normalizeBusinessText(actual?.warehouse, { warehouse: true });
  const accepted = warehouseMatches !== true
    && orderMatches
    && trackingMatches
    && carrierMatches
    && Boolean(expectedWarehouse)
    && Boolean(actualWarehouse);
  return {
    accepted,
    status: accepted ? 'reconciled' : 'rejected',
    strategy: accepted ? 'tms-linked-oms-exact-shipment-authoritative' : null,
    linkedOmsOrder,
    orderMatches,
    trackingMatches,
    carrierMatches,
    expectedWarehouse: omsAnalysis?.shippingWarehouse || null,
    authoritativeWarehouse: actual?.warehouse || null,
    expectedTracking: logisticsAnalysis?.trackingNumber || null,
    actualTracking: actual?.trackingNumber || null,
    expectedCarrier: logisticsAnalysis?.carrier || null,
    actualCarrier: actual?.carrier || null,
  };
};

const evaluateTmsAutofillCandidate = (
  candidate,
  orderNumber,
  logisticsAnalysis,
  omsAnalysis,
  {
    allowReadableUnmappedValues = false,
    allowMissingExpectedLogistics = false,
  } = {},
) => {
  const actual = {
    orderNumber: String(candidate?.orderNo || candidate?.salesOrderCode || '').trim(),
    tradeId: String(candidate?.tradeId || candidate?.externalOrderNumber || '').trim(),
    warehouse: String(candidate?.warehouse || candidate?.warehouseName || '').trim(),
    trackingNumber: String(candidate?.trackingNo || candidate?.trackingNumber || '').trim(),
    carrier: String(candidate?.logisticsCompany || candidate?.carrier || '').trim(),
  };
  const expectedTracking = normalizeBusinessText(logisticsAnalysis?.trackingNumber);
  const expectedWarehouse = matchBusinessCategories(
    omsAnalysis?.shippingWarehouse,
    warehouseCategories,
    { warehouse: true },
  );
  const actualWarehouse = matchBusinessCategories(actual.warehouse, warehouseCategories, { warehouse: true });
  const expectedCarrier = matchCarrierCategories(logisticsAnalysis?.carrier);
  const actualCarrier = matchCarrierCategories(actual.carrier);
  const orderMatches = actual.tradeId === orderNumber;
  const trackingMatches = expectedTracking
    ? normalizeBusinessText(actual.trackingNumber) === expectedTracking
    : allowMissingExpectedLogistics;
  const warehouseMatches = (expectedWarehouse.matches.length === 1
    && actualWarehouse.matches.length === 1
    && expectedWarehouse.matches[0].key === actualWarehouse.matches[0].key)
    || (allowReadableUnmappedValues
      && expectedWarehouse.normalized
      && actualWarehouse.normalized
      && (expectedWarehouse.normalized.includes(actualWarehouse.normalized)
        || actualWarehouse.normalized.includes(expectedWarehouse.normalized)));
  const carrierMatches = (expectedCarrier.matches.length === 1
    && actualCarrier.matches.length === 1
    && expectedCarrier.matches[0].key === actualCarrier.matches[0].key)
    || (allowMissingExpectedLogistics
      && !expectedCarrier.normalized
      && Boolean(actualCarrier.normalized))
    || (allowReadableUnmappedValues
      && expectedCarrier.normalized
      && actualCarrier.normalized
      && (expectedCarrier.normalized.includes(actualCarrier.normalized)
        || actualCarrier.normalized.includes(expectedCarrier.normalized)));
  const warehouseReconciliation = reconcileTmsAutofillWarehouseMismatch({
    actual,
    orderNumber,
    logisticsAnalysis,
    omsAnalysis,
    warehouseMatches: Boolean(warehouseMatches),
  });
  return {
    matches: Boolean(orderMatches && trackingMatches && warehouseMatches && carrierMatches),
    safeWarehouseReconciliation: Boolean(
      orderMatches && trackingMatches && carrierMatches && warehouseReconciliation.accepted
    ),
    orderMatches,
    trackingMatches: Boolean(trackingMatches),
    warehouseMatches: Boolean(warehouseMatches),
    carrierMatches: Boolean(carrierMatches),
    warehouseReconciliation,
    actual,
  };
};

const uniqueTmsEmptyCarrierCandidateIndex = (evaluations, expectedCarrier) => {
  if (matchCarrierCategories(expectedCarrier).matches.length !== 1) return -1;
  const matches = evaluations
    .map((candidate, index) => (
      candidate.orderMatches && candidate.trackingMatches && candidate.warehouseMatches
        && (!candidate.actual.carrier
          || candidate.actual.carrier === '优先自动带入，无匹配时请手动搜索选择')
        ? index : -1
    ))
    .filter((index) => index >= 0);
  return matches.length === 1 ? matches[0] : -1;
};

const selectTmsAutofillCandidate = async (
  targetPage,
  dialog,
  orderInput,
  queryMessage,
  {
    preferredIndex = 0,
    selectionStrategy = 'first-row-user-authorized',
    candidateEvaluation = null,
  } = {},
) => {
  const normalizedMessage = String(queryMessage || '').replace(/\s+/gu, ' ').trim();
  const multipleMatch = normalizedMessage.match(/^查询到\s*(\d+)\s*个订单，请选择对应订单$/u);
  if (!multipleMatch) return null;

  const candidateCount = Number(multipleMatch[1]);
  if (!Number.isInteger(candidateCount) || candidateCount < 2) return null;

  const orderFormItem = orderInput.locator(
    'xpath=ancestor::*[contains(concat(" ", normalize-space(@class), " "), " el-form-item ")][1]',
  );
  const candidateRows = orderFormItem.locator(
    '.el-table__body-wrapper tbody tr.el-table__row, .el-table__body-wrapper tbody tr',
  );
  const observedRowCount = await candidateRows.count();
  const selectedIndex = Number.isInteger(preferredIndex) && preferredIndex >= 0
    ? preferredIndex : 0;
  const selectedRow = candidateRows.nth(selectedIndex);
  if (observedRowCount <= selectedIndex || !await selectedRow.isVisible().catch(() => false)) {
    throw new Error(`TMS 查询到 ${candidateCount} 个订单，但无法定位第 ${selectedIndex + 1} 条候选订单`);
  }

  const selectedOrderNumber = await selectedRow.locator('td').first().innerText()
    .then((value) => value.replace(/\s+/gu, ' ').trim())
    .catch(() => '');
  const selection = {
    status: 'selecting',
    candidateCount,
    observedRowCount,
    selectedIndex,
    selectionStrategy,
    selectedOrderNumber: selectedOrderNumber || null,
    candidateEvaluation,
    selectedAt: null,
  };
  writeProgress({
    step: 'tms-autofill-candidate-selecting',
    tmsAutofillCandidateSelection: selection,
  });
  await pacedAction(targetPage, 'select-tms-autofill-candidate', () => selectedRow.click());

  const completedSelection = {
    ...selection,
    status: 'selected',
    selectedAt: new Date().toISOString(),
  };
  writeProgress({ tmsAutofillCandidateSelection: completedSelection });
  return completedSelection;
};

const selectTmsExactCarrierWhenAutofillIsEmpty = async (
  targetPage, dialog, orderNumber, logisticsAnalysis, actual,
) => {
  const expectedCarrier = String(logisticsAnalysis?.carrier || '').trim();
  const currentCarrier = String(actual?.carrier || '').trim();
  const missingCarrier = !currentCarrier
    || currentCarrier === '优先自动带入，无匹配时请手动搜索选择';
  const orderMatches = actual?.orderNumber === orderNumber
    || /^SO[\w-]+$/iu.test(String(actual?.orderNumber || '').trim());
  const expectedTracking = normalizeBusinessText(logisticsAnalysis?.trackingNumber);
  const trackingMatches = Boolean(expectedTracking
    && normalizeBusinessText(actual?.trackingNumber) === expectedTracking);
  // Only fill an empty TMS choice after the linked OMS order and tracking
  // match. An existing but different carrier remains a manual-review conflict.
  if (!missingCarrier || !orderMatches || !trackingMatches || !expectedCarrier
    || matchCarrierCategories(expectedCarrier).matches.length !== 1) return null;

  let item = tmsFormItem(dialog, '责任快递');
  if (!await item.count()) {
    item = dialog.locator('.el-form-item:visible').filter({ hasText: '责任快递' }).first();
  }
  const select = item.locator('.el-select__wrapper').first();
  if (!await select.isVisible().catch(() => false)) {
    return { status: 'carrier-control-unavailable', expectedCarrier };
  }
  await pacedAction(targetPage, 'open-tms-exact-carrier-search', () => select.click());
  // Some TMS select variants create their search input only after opening.
  // An unsearchable select may still expose one exact, visible option.
  const search = item.locator('input[role="combobox"], .el-select__wrapper input:not([type="hidden"])').first();
  if (await search.isVisible().catch(() => false)
    && await search.isEditable().catch(() => false)) {
    await pacedAction(targetPage, 'search-tms-exact-carrier', () => search.fill(expectedCarrier));
  }
  const exactOption = targetPage.locator('.el-select-dropdown__item:visible')
    .filter({ hasText: new RegExp(`^\\s*${escapeRegex(expectedCarrier)}\\s*$`, 'u') });
  await exactOption.first().waitFor({ state: 'visible', timeout: 8000 }).catch(() => {});
  const optionCount = await exactOption.count();
  if (optionCount !== 1) {
    return { status: 'exact-option-unavailable', expectedCarrier, optionCount };
  }
  await pacedAction(targetPage, 'select-tms-exact-carrier', () => exactOption.click());
  const committedChoice = item.locator(
    '.el-select__selected-item:not(.el-select__input-wrapper):not(.is-transparent)',
  ).first();
  await committedChoice.waitFor({ state: 'visible', timeout: 3000 }).catch(() => {});
  const selectedCarrier = await committedChoice.innerText().then((value) => value.trim()).catch(() => '');
  return {
    status: selectedCarrier === expectedCarrier ? 'selected' : 'selection-unconfirmed',
    expectedCarrier,
    selectedCarrier,
  };
};

const verifyTmsAutofill = async (
  targetPage,
  dialog,
  orderNumber,
  logisticsAnalysis,
  omsAnalysis,
  {
    allowReadableUnmappedValues = false,
    allowMissingExpectedLogistics = false,
  } = {},
) => {
  const orderInput = dialog.getByPlaceholder('请输入交易号，回车自动查询OMS', { exact: true });
  if (!await orderInput.count()) throw new Error('TMS 新建窗口未找到订单号输入框');
  await pacedAction(targetPage, 'fill-tms-order-number', () => orderInput.fill(orderNumber));
  const success = dialog.getByText('查询成功，已自动填充订单信息', { exact: true });
  const multipleCandidates = dialog.locator('.query-tip')
    .filter({ hasText: /^查询到\s*\d+\s*个订单，请选择对应订单$/u })
    .first();
  let queryOutcome = null;
  let queryPayload = null;
  let queryMessage = '';
  for (let attempt = 1; attempt <= 2 && !queryOutcome; attempt++) {
    const queryResponsePromise = targetPage.waitForResponse((response) => (
      response.request().method() === 'GET'
      && response.url().includes(`/api/logistics/orders/${encodeURIComponent(orderNumber)}`)
    ), { timeout: 30000 }).catch(() => null);
    await pacedAction(targetPage, `query-tms-order-${attempt}`, () => orderInput.press('Enter'));
    const queryResponse = await queryResponsePromise;
    if (queryResponse && !queryResponse.ok()) {
      const httpStatus = queryResponse.status();
      const message = `TMS OMS 查询返回 HTTP ${httpStatus}`;
      const failureClass = classifyTmsOmsQueryHttpStatus(httpStatus);
      if (failureClass === 'authorization-recovery') {
        throw new TmsOmsQueryAuthorizationError(httpStatus, queryResponse.url());
      }
      if (failureClass === 'transient-retry') {
        throw new LogisticsRetryRequiredError(
          'tms-oms-query-transient',
          message,
          tmsOmsQueryRetryAfterMs,
          {
            transientSystem: 'TMS',
            httpStatus,
            externalEffectStatus: 'failed',
            externalEffectReceipt: {
              clickAttempted: false,
              reason: 'tms-oms-query-transient-http-error',
              httpStatus,
            },
          },
        );
      }
      throw new Error(message);
    }
    if (queryResponse) queryPayload = await queryResponse.json().catch(() => null);
    queryOutcome = await Promise.race([
      success.waitFor({ state: 'visible', timeout: 30000 }).then(() => 'success'),
      multipleCandidates.waitFor({ state: 'visible', timeout: 30000 }).then(() => 'multiple'),
    ]).catch(() => null);
    if (queryOutcome) break;

    queryMessage = await dialog.locator('.query-tip').first().innerText()
      .then((value) => value.replace(/\s+/gu, ' ').trim())
      .catch(() => '未返回查询结果');
    const transient = isTransientTmsOmsQueryMessage(queryMessage);
    if (!transient) throw new Error(`TMS 订单无法唯一自动带出: ${queryMessage}`);
    if (attempt < 2) {
      writeProgress({
        step: 'tms-oms-query-retrying',
        tmsOmsQueryRecovery: {
          orderNumber,
          status: 'retrying-in-place',
          attempt,
          maxAttempts: 2,
          lastMessage: queryMessage,
          retriedAt: new Date().toISOString(),
        },
        manualReview: null,
        error: null,
      });
      await targetPage.waitForTimeout(1000);
    }
  }
  if (!queryOutcome) {
    throw new LogisticsRetryRequiredError(
      'tms-oms-query-transient',
      `OMS_QUERY_TEMPORARILY_UNAVAILABLE: TMS OMS 查询两轮后仍未完成: ${queryMessage || '未返回查询结果'}`,
      tmsOmsQueryRetryAfterMs,
      {
        transientSystem: 'TMS',
        externalEffectStatus: 'failed',
        externalEffectReceipt: {
          clickAttempted: false,
          reason: 'tms-oms-query-transient-render-timeout',
          queryMessage: queryMessage || null,
        },
      },
    );
  }
  const queryCandidates = tmsAutofillCandidatesFromPayload(queryPayload);
  let candidateSelection = null;
  if (queryOutcome === 'multiple') {
    const queryMessage = await multipleCandidates.innerText();
    const candidateEvaluations = queryCandidates.map((candidate) => evaluateTmsAutofillCandidate(
      candidate,
      orderNumber,
      logisticsAnalysis,
      omsAnalysis,
      { allowReadableUnmappedValues, allowMissingExpectedLogistics },
    ));
    const matchedIndex = candidateEvaluations.findIndex((candidate) => candidate.matches);
    const reconciledIndexes = candidateEvaluations
      .map((candidate, index) => (candidate.safeWarehouseReconciliation ? index : -1))
      .filter((index) => index >= 0);
    const reconciledIndex = matchedIndex < 0 && reconciledIndexes.length === 1
      ? reconciledIndexes[0] : -1;
    const emptyCarrierIndex = matchedIndex < 0 && reconciledIndex < 0
      ? uniqueTmsEmptyCarrierCandidateIndex(candidateEvaluations, logisticsAnalysis.carrier)
      : -1;
    const preferredIndex = matchedIndex >= 0 ? matchedIndex
      : reconciledIndex >= 0 ? reconciledIndex
        : emptyCarrierIndex >= 0 ? emptyCarrierIndex : 0;
    candidateSelection = await selectTmsAutofillCandidate(
      targetPage,
      dialog,
      orderInput,
      queryMessage,
      {
        preferredIndex,
        selectionStrategy: matchedIndex >= 0
          ? 'business-fields-matched-row'
          : reconciledIndex >= 0
            ? 'exact-shipment-warehouse-reconciled-row'
            : emptyCarrierIndex >= 0
              ? 'exact-shipment-empty-carrier-row'
              : 'first-row-user-authorized',
        candidateEvaluation: candidateEvaluations[preferredIndex] || null,
      },
    );
    if (!candidateSelection) {
      throw new Error(`TMS 订单无法唯一自动带出: ${queryMessage}`);
    }
    await success.waitFor({ state: 'visible', timeout: 30000 }).catch(async () => {
      const latestMessage = await dialog.locator('.query-tip').first().innerText()
        .catch(() => '选择第一条候选订单后未返回结果');
      throw new Error(`TMS 选择第一条候选订单后未完成自动填充: ${latestMessage}`);
    });
  }

  const actual = {
    orderNumber: await orderInput.inputValue(),
    warehouse: await readTmsFormValue(dialog, '发货仓库'),
    trackingNumber: await readTmsFormValue(dialog, '运单号'),
    carrier: await readTmsFormValue(dialog, '责任快递'),
  };
  const carrierSelection = await selectTmsExactCarrierWhenAutofillIsEmpty(
    targetPage, dialog, orderNumber, logisticsAnalysis, actual,
  );
  if (carrierSelection?.status === 'selected') actual.carrier = carrierSelection.selectedCarrier;
  const expectedWarehouse = matchBusinessCategories(omsAnalysis.shippingWarehouse, warehouseCategories, { warehouse: true });
  const actualWarehouse = matchBusinessCategories(actual.warehouse, warehouseCategories, { warehouse: true });
  const expectedCarrier = matchCarrierCategories(logisticsAnalysis.carrier);
  const actualCarrier = matchCarrierCategories(actual.carrier);
  const conflicts = [];
  // TMS accepts the PDD trade number as the lookup key but displays the
  // linked OMS sales order (SO...) after the lookup. Treat that linked value
  // as valid instead of reopening the same new-ticket dialog forever.
  const linkedOmsOrder = /^SO[\w-]+$/i.test(String(actual.orderNumber || '').trim());
  if (actual.orderNumber !== orderNumber && !linkedOmsOrder) conflicts.push('交易号不一致');
  const expectedTracking = normalizeBusinessText(logisticsAnalysis.trackingNumber);
  if ((!allowMissingExpectedLogistics || expectedTracking)
    && normalizeBusinessText(actual.trackingNumber) !== expectedTracking) {
    conflicts.push('运单号不一致');
  }
  const warehouseMatches = expectedWarehouse.matches.length === 1
    && actualWarehouse.matches.length === 1
    && expectedWarehouse.matches[0].key === actualWarehouse.matches[0].key;
  const readableWarehouseMatches = allowReadableUnmappedValues
    && expectedWarehouse.normalized
    && actualWarehouse.normalized
    && (expectedWarehouse.normalized.includes(actualWarehouse.normalized)
      || actualWarehouse.normalized.includes(expectedWarehouse.normalized));
  const carrierMatches = expectedCarrier.matches.length === 1
    ? actualCarrier.matches.length === 1
      && expectedCarrier.matches[0].key === actualCarrier.matches[0].key
    : allowMissingExpectedLogistics && Boolean(actualCarrier.normalized);
  const readableCarrierMatches = allowReadableUnmappedValues
    && expectedCarrier.normalized
    && actualCarrier.normalized
    && (expectedCarrier.normalized.includes(actualCarrier.normalized)
      || actualCarrier.normalized.includes(expectedCarrier.normalized));
  const warehouseReconciliation = reconcileTmsAutofillWarehouseMismatch({
    actual,
    orderNumber,
    logisticsAnalysis,
    omsAnalysis,
    warehouseMatches: Boolean(warehouseMatches || readableWarehouseMatches),
    sourceLookupConfirmed: true,
  });
  if (!carrierMatches && !readableCarrierMatches) {
    conflicts.push('责任快递不一致');
  }
  if (!warehouseMatches && !readableWarehouseMatches && !warehouseReconciliation.accepted) {
    conflicts.push('发货仓库不一致');
  }
  return {
    actual,
    sourceOrderNumber: orderNumber,
    linkedOmsOrder,
    candidateSelection,
    carrierSelection,
    warehouseVerification: {
      source: 'oms-tms-match',
      status: warehouseReconciliation.accepted ? 'reconciled' : 'verified',
      strategy: warehouseReconciliation.strategy,
      expectedWarehouse: omsAnalysis.shippingWarehouse || null,
      actualWarehouse: actual.warehouse || null,
      authoritativeWarehouse: warehouseReconciliation.accepted ? actual.warehouse || null : null,
      matchedWarehouse: actualWarehouse.matches[0]?.label || null,
      shipmentReconciliation: warehouseReconciliation,
    },
    conflicts,
    verifiedAt: new Date().toISOString(),
  };
};

const tmsAttachmentSuccessSelector = [
  '.el-upload-list__item.is-success:visible',
  '.el-upload-list--picture-card .el-upload-list__item.is-success:visible',
].join(', ');

const tmsAttachmentUnsettledSelector = [
  '.el-upload-list__item.is-ready:visible',
  '.el-upload-list__item.is-uploading:visible',
  '.el-upload-list__item.is-fail:visible',
].join(', ');

const isTmsAttachmentResponseTimeout = (value) => (
  /page\.waitForResponse: Timeout \d+ms exceeded while waiting for event ["']response["']/u
    .test(String(value || ''))
);

const isTmsAttachmentUploadRequest = (request) => {
  if (!['POST', 'PUT'].includes(request.method())) return false;
  let pathname = request.url();
  try {
    pathname = new URL(request.url()).pathname;
  } catch {}
  return /\/api\/logistics\/(?:files?|attachments?|uploads?)(?:\/|$)/iu.test(pathname);
};

const isTmsAttachmentUploadResponse = (response) => (
  isTmsAttachmentUploadRequest(response.request())
);

const tmsAttachmentRequestPath = (request) => {
  try {
    return new URL(request.url()).pathname;
  } catch {
    return request.url();
  }
};

const clearUnsettledTmsAttachments = async (dialog) => {
  const items = dialog.locator(tmsAttachmentUnsettledSelector);
  const observedCount = await items.count();
  let removedCount = 0;
  for (let index = observedCount - 1; index >= 0; index--) {
    const item = items.nth(index);
    await item.hover().catch(() => {});
    const remove = item.locator([
      '.el-upload-list__item-delete',
      '.el-icon--close',
      'button[aria-label*="remove" i]',
      'button[aria-label*="delete" i]',
      'button[aria-label*="删除"]',
    ].join(', ')).last();
    if (!await remove.count()) continue;
    if (await remove.click({ force: true }).then(() => true).catch(() => false)) removedCount++;
  }
  if (removedCount) {
    await dialog.locator(tmsAttachmentUnsettledSelector).first()
      .waitFor({ state: 'detached', timeout: 3000 })
      .catch(() => {});
  }
  return {
    observedCount,
    removedCount,
    remainingCount: await dialog.locator(tmsAttachmentUnsettledSelector).count(),
  };
};

const dismissTmsAttachmentDialogAfterFailure = async (dialog) => {
  if (!await dialog.isVisible().catch(() => false)) return false;
  const cancel = dialog.getByRole('button', { name: '取消', exact: true }).last();
  const close = await cancel.count()
    ? cancel
    : dialog.locator('.el-dialog__headerbtn').last();
  if (!await close.count()) return false;
  const clicked = await close.click({ force: true }).then(() => true).catch(() => false);
  if (clicked) await dialog.waitFor({ state: 'hidden', timeout: 5000 }).catch(() => {});
  return clicked;
};

const readTmsAttachmentDomReceipt = async (item, expectedFileName = null) => {
  if (!await item.isVisible().catch(() => false)) return null;
  const receipt = await item.evaluate((element) => {
    const image = element.querySelector('img');
    const link = element.querySelector('a[href]');
    const nameElement = element.querySelector(
      '.el-upload-list__item-name, [class*="upload-list__item-name"], [title]',
    );
    const firstAttribute = (...names) => names
      .map((name) => element.getAttribute(name))
      .find((value) => value && value.trim()) || null;
    return {
      fileName: (nameElement?.getAttribute('title') || nameElement?.textContent || '').trim() || null,
      reference: firstAttribute('data-file-id', 'data-id', 'data-uid', 'data-url')
        || image?.getAttribute('src')
        || link?.getAttribute('href')
        || null,
      text: (element.textContent || '').replace(/\s+/g, ' ').trim() || null,
      className: element.className || null,
    };
  });
  return {
    ...receipt,
    expectedFileName,
    fileNameMatched: receipt.fileName && expectedFileName
      ? receipt.fileName.includes(expectedFileName)
      : null,
    observedAt: new Date().toISOString(),
  };
};

const recoverTmsAttachmentFromVisibleThumbnail = async (dialog, orderNumber, previousTransfer) => {
  const recoverableStatus = previousTransfer?.status === 'uploaded'
    || previousTransfer?.status === 'uploading'
    || (previousTransfer?.status === 'failed'
      && isTmsAttachmentResponseTimeout(previousTransfer.error));
  if (!recoverableStatus || previousTransfer?.orderNumber !== orderNumber) return null;
  const successItem = dialog.locator(tmsAttachmentSuccessSelector).first();
  const domReceipt = await readTmsAttachmentDomReceipt(successItem);
  if (!domReceipt) return null;
  const transfer = {
    ...previousTransfer,
    orderNumber,
    mode: 'file-upload',
    status: 'uploaded',
    attachmentId: previousTransfer.attachmentId || domReceipt.reference || null,
    confirmationMethod: previousTransfer.status === 'uploaded'
      ? previousTransfer.confirmationMethod || 'existing-dom-success'
      : 'recovered-existing-dom-success',
    domReceipt,
    uploadedAt: previousTransfer.uploadedAt || domReceipt.observedAt,
    recoveredAt: previousTransfer.status === 'uploaded' ? null : new Date().toISOString(),
    error: null,
  };
  writeProgress({ step: 'tms-attachment-uploaded', tmsAttachmentTransfer: transfer });
  return transfer;
};

const uploadPddEvidenceToTms = async (targetPage, dialog, orderNumber) => {
  const evidence = resolveReadyEvidenceScreenshot(orderNumber, readProgress());
  const diagnostics = {
    cleanup: null,
    requestObserved: false,
    requestMethod: null,
    requestPath: null,
    requestFailed: false,
    requestFailure: null,
  };
  let uploadObservationActive = true;
  writeProgress({
    step: 'tms-attachment-uploading',
    tmsAttachmentTransfer: {
      orderNumber,
      mode: 'file-upload',
      status: 'uploading',
      sourceRelativePath: evidence.metadata.relativePath,
      startedAt: new Date().toISOString(),
      error: null,
    },
  });
  try {
    diagnostics.cleanup = await clearUnsettledTmsAttachments(dialog);
    if (diagnostics.cleanup.remainingCount > 0) {
      throw new Error(
        `TMS_ATTACHMENT_UPLOAD_TEMPORARILY_UNAVAILABLE: TMS 客服附件区仍有 ${diagnostics.cleanup.remainingCount} 个未完成文件项，已放弃当前脏表单`,
      );
    }
    const fileInput = dialog.locator('.el-upload input[type="file"], input[type="file"]').first();
    if (!await fileInput.count()) throw new Error('TMS 客服附件区域未找到文件输入框');
    const successItems = dialog.locator(tmsAttachmentSuccessSelector);
    const existingSuccessCount = await successItems.count();
    const uploadedItem = successItems.nth(existingSuccessCount);
    const uploadRequestPromise = targetPage.waitForRequest(
      isTmsAttachmentUploadRequest,
      { timeout: 60000 },
    ).then(
      (request) => {
        if (uploadObservationActive) {
          diagnostics.requestObserved = true;
          diagnostics.requestMethod = request.method();
          diagnostics.requestPath = tmsAttachmentRequestPath(request);
        }
        return request;
      },
      () => null,
    );
    const uploadResponsePromise = targetPage.waitForResponse(
      isTmsAttachmentUploadResponse,
      { timeout: 60000 },
    ).then(
      (response) => ({ kind: 'response', response }),
      (error) => ({ kind: 'response-timeout', error }),
    );
    const uploadRequestFailurePromise = targetPage.waitForEvent('requestfailed', {
      predicate: isTmsAttachmentUploadRequest,
      timeout: 60000,
    }).then(
      (request) => {
        if (uploadObservationActive) {
          diagnostics.requestObserved = true;
          diagnostics.requestMethod = request.method();
          diagnostics.requestPath = tmsAttachmentRequestPath(request);
          diagnostics.requestFailed = true;
          diagnostics.requestFailure = request.failure()?.errorText || 'unknown network failure';
        }
        return { kind: 'request-failed', request };
      },
      () => new Promise(() => {}),
    );
    const uploadErrorPromise = targetPage.getByText(
      /(?:客服)?附件上传失败|文件上传失败|上传请求超时|网络错误/u,
    ).last().waitFor({ state: 'visible', timeout: 60000 }).then(
      () => ({ kind: 'page-error' }),
      () => new Promise(() => {}),
    );
    await fileInput.evaluate((input) => { input.value = ''; }).catch(() => {});
    await pacedAction(targetPage, 'upload-tms-customer-attachment', () => fileInput.setInputFiles(evidence.absolutePath));
    const domSuccessPromise = uploadedItem.waitFor({ state: 'visible', timeout: 60000 }).then(
      () => ({ kind: 'dom-success' }),
      (error) => ({ kind: 'dom-timeout', error }),
    );
    const firstOutcome = await Promise.race([
      uploadResponsePromise,
      domSuccessPromise,
      uploadRequestFailurePromise,
      uploadErrorPromise,
    ]);
    if (firstOutcome.kind === 'request-failed') {
      throw new Error(
        `TMS_ATTACHMENT_UPLOAD_TEMPORARILY_UNAVAILABLE: TMS 客服附件上传请求失败: ${diagnostics.requestFailure}`,
      );
    }
    if (firstOutcome.kind === 'page-error') {
      throw new Error('TMS_ATTACHMENT_UPLOAD_TEMPORARILY_UNAVAILABLE: TMS 页面提示附件上传失败');
    }
    let responseOutcome = firstOutcome.kind === 'response' ? firstOutcome : null;
    let responseJson = null;
    if (firstOutcome.kind === 'response') {
      responseJson = await readSuccessfulApiResponse(responseOutcome.response, 'TMS 客服附件上传');
      await uploadedItem.waitFor({ state: 'visible', timeout: 30000 });
    } else if (firstOutcome.kind === 'dom-success') {
      responseOutcome = await Promise.race([
        uploadResponsePromise,
        targetPage.waitForTimeout(1500).then(() => null),
      ]);
    } else {
      const domReceiptAfterTimeout = await readTmsAttachmentDomReceipt(uploadedItem);
      if (!domReceiptAfterTimeout) {
        await Promise.race([uploadRequestPromise, targetPage.waitForTimeout(250)]);
        const phase = diagnostics.requestObserved ? '请求已发出但服务端未返回' : '页面没有发起上传请求';
        throw new Error(
          `TMS_ATTACHMENT_UPLOAD_TEMPORARILY_UNAVAILABLE: TMS 客服附件上传超时（${phase}）`,
        );
      }
    }
    const json = responseOutcome?.kind === 'response'
      ? responseJson ?? await readSuccessfulApiResponse(responseOutcome.response, 'TMS 客服附件上传')
      : null;
    const domReceipt = await readTmsAttachmentDomReceipt(
      uploadedItem,
      path.basename(evidence.absolutePath),
    );
    if (!domReceipt) throw new Error('TMS 客服附件上传后未显示成功缩略图');
    const attachmentId = findDeepValue(json, ['path', 'attachmentId', 'fileId', 'url', 'id'])
      || domReceipt.reference
      || null;
    let responsePath = null;
    if (responseOutcome?.kind === 'response') {
      try {
        responsePath = new URL(responseOutcome.response.url()).pathname;
      } catch {
        responsePath = responseOutcome.response.url();
      }
    }
    const transfer = {
      orderNumber,
      mode: 'file-upload',
      status: 'uploaded',
      attachmentId: attachmentId ? String(attachmentId) : null,
      confirmationMethod: responseOutcome?.kind === 'response'
        ? 'api-response-and-dom-success'
        : 'dom-success-without-captured-response',
      response: responseOutcome?.kind === 'response' ? {
        status: responseOutcome.response.status(),
        path: responsePath,
      } : null,
      domReceipt,
      diagnostics,
      sourceRelativePath: evidence.metadata.relativePath,
      uploadedAt: new Date().toISOString(),
      error: null,
    };
    uploadObservationActive = false;
    writeProgress({ step: 'tms-attachment-uploaded', tmsAttachmentTransfer: transfer });
    return transfer;
  } catch (error) {
    uploadObservationActive = false;
    const dismissedDirtyDialog = await dismissTmsAttachmentDialogAfterFailure(dialog);
    const previousTransfer = readProgress().tmsAttachmentTransfer || {};
    writeProgress({
      step: 'tms-attachment-upload-failed',
      tmsAttachmentTransfer: {
        ...previousTransfer,
        orderNumber,
        mode: 'file-upload',
        status: 'failed',
        sourceRelativePath: previousTransfer.sourceRelativePath || evidence.metadata.relativePath,
        failedAt: new Date().toISOString(),
        diagnostics: {
          ...diagnostics,
          dismissedDirtyDialog,
        },
        error: error.message,
      },
    });
    throw error;
  }
};

const stableTmsEffectFormDecision = (formDecision = {}) => {
  const { decidedAt: _decidedAt, autoFilledFields: _autoFilledFields, ...stable } = formDecision;
  return stable;
};

const createTmsTicket = async (targetPage, dialog, orderNumber, formDecision, {
  effectStage = 'create-ticket',
  progressField = 'tmsWorkOrder',
  stepPrefix = 'tms-ticket',
  requestContext = null,
} = {}) => {
  const problemChoice = dialog.locator('.el-radio').filter({ hasText: new RegExp(`^\\s*${escapeRegex(formDecision.problemType)}\\s*$`) }).first();
  if (!await problemChoice.count()) throw new Error(`TMS 未找到物流问题选项: ${formDecision.problemType}`);
  await pacedAction(targetPage, 'select-tms-logistics-problem', () => problemChoice.click());
  const remark = dialog.getByPlaceholder('请输入客服备注', { exact: true });
  if (!await remark.count()) throw new Error('TMS 未找到客服备注输入框');
  await pacedAction(targetPage, 'fill-tms-customer-remark', () => remark.fill(formDecision.customerRemark));
  const problemInput = problemChoice.locator('input[type="radio"]').first();
  const problemChecked = await problemInput.isChecked().catch(() => false)
    || await problemChoice.evaluate((element) => element.classList.contains('is-checked')).catch(() => false);
  if (!problemChecked) throw new Error(`TMS 物流问题选项未实际选中: ${formDecision.problemType}`);
  const actualRemark = await remark.inputValue();
  if (normalizeTmsDecisionText(actualRemark) !== normalizeTmsDecisionText(formDecision.customerRemark)) {
    throw new Error('TMS 客服备注填写后回读不一致');
  }

  const submit = dialog.getByRole('button', { name: '提交并新建', exact: true });
  if (!await submit.count()) throw new Error('TMS 未找到“提交并新建”按钮');
  writeProgress({ step: `${stepPrefix}-submitting` });
  try {
    const json = await guardedExternalEffect({
      effectType: 'tms-create',
      orderNumber,
      stage: effectStage,
      request: {
        formDecision: stableTmsEffectFormDecision(formDecision),
        requestContext,
      },
    }, async () => {
      const createResponsePromise = targetPage.waitForResponse((response) => (
        response.request().method() === 'POST'
        && /\/api\/logistics\/tickets(?:\?|$)/.test(response.url())
      ), { timeout: 60000 });
      await pacedAction(targetPage, 'submit-and-new-tms-ticket', () => submit.click());
      const response = await createResponsePromise;
      return readSuccessfulApiResponse(response, 'TMS 物流工单创建');
    });
    const ticketId = findDeepValue(json, ['ticketId']);
    const ticketNo = findDeepValue(json, ['ticketNo']);
    if (!ticketId || !ticketNo) throw new Error('TMS 创建响应缺少 ticketId 或 ticketNo');
    // The API response is the authoritative create result.  Some TMS builds
    // do not render the optional success toast (or replace it immediately
    // when "提交并新建" resets the form), so a missing toast must not turn a
    // successfully-created ticket into a failed one.
    await targetPage.getByText('创建成功，请继续新建', { exact: true })
      .waitFor({ state: 'visible', timeout: 5000 })
      .catch(() => {});
    const workOrder = {
      shopId,
      orderNumber,
      status: 'created',
      effectStage,
      ticketId: String(ticketId),
      ticketNo: String(ticketNo),
      problemType: formDecision.problemType,
      customerRemark: formDecision.customerRemark,
      createdAt: new Date().toISOString(),
      error: null,
    };
    writeProgress({ step: `${stepPrefix}-created`, [progressField]: workOrder });
    return workOrder;
  } catch (error) {
    writeProgress({
      step: `${stepPrefix}-create-failed`,
      [progressField]: {
        shopId,
        orderNumber,
        status: 'failed',
        failedAt: new Date().toISOString(),
        error: error.message,
      },
    });
    throw error;
  }
};

const expectedTmsEvidencePath = (orderNumber) => {
  if (!/^[0-9]+(?:-[0-9]+)+$/.test(orderNumber || '')) {
    throw new Error(`TMS 截图订单编号格式不安全: ${orderNumber}`);
  }
  return path.join(tmsEvidenceScreenshotDir, `${orderNumber}.png`);
};

const captureTmsRowEvidence = async (targetPage, row, orderNumber, workOrder, { rowSelection = null } = {}) => {
  const absolutePath = expectedTmsEvidencePath(orderNumber);
  const relativePath = toPortableRelativePath(workflowDataDir, absolutePath);
  const marker = `codex-tms-evidence-${Date.now()}`;
  try {
    const rowText = await row.innerText();
    const apiCreatedExactOrderFallback = canUseApiCreatedTmsSoleRow({
      workOrder,
      candidateCount: rowSelection?.count,
      rowText,
      orderNumber,
    }) && rowSelection?.selectionStrategy === 'api-created-exact-order-only-row';
    if (!rowText.includes(orderNumber)
      || (workOrder.ticketNo && !rowText.includes(workOrder.ticketNo) && !apiCreatedExactOrderFallback)) {
      throw new Error('TMS 截图目标行与已创建工单标识不一致');
    }
    const cloneInfo = await row.evaluate((sourceRow, { markerId }) => {
      const tableRoot = sourceRow.closest('.el-table');
      if (!tableRoot) return { error: '未找到表格根节点' };
      const headers = [...tableRoot.querySelectorAll('.el-table__header-wrapper thead tr:last-child th')];
      const cells = [...sourceRow.children].filter((element) => element.tagName === 'TD');
      const labels = headers.map((header) => (header.innerText || '').replace(/\s+/g, ' ').trim());
      const start = labels.findIndex((label) => label === '交易号');
      const end = labels.findIndex((label) => label === '客服备注');
      if (start < 0 || end < start || cells.length <= end) {
        return { error: `列范围异常: ${JSON.stringify({ labels, cellCount: cells.length, start, end })}` };
      }

      const container = document.createElement('div');
      container.id = markerId;
      Object.assign(container.style, {
        position: 'fixed',
        left: '8px',
        top: '8px',
        zIndex: '2147483647',
        background: '#ffffff',
        padding: '0',
        pointerEvents: 'none',
        boxShadow: 'none',
      });
      const table = document.createElement('table');
      table.style.borderCollapse = 'collapse';
      table.style.tableLayout = 'fixed';
      table.style.background = '#ffffff';
      const body = document.createElement('tbody');
      const clonedRow = document.createElement('tr');
      const includedColumns = [];
      const values = {};
      for (let index = start; index <= end; index++) {
        const original = cells[index];
        const clone = original.cloneNode(true);
        const width = Math.min(360, Math.max(original.getBoundingClientRect().width, index === end ? 300 : 120));
        clone.style.width = `${width}px`;
        clone.style.minWidth = `${width}px`;
        clone.style.maxWidth = `${width}px`;
        clone.style.height = 'auto';
        clone.style.padding = '10px 12px';
        clone.style.border = '1px solid #dcdfe6';
        clone.style.background = '#ffffff';
        clone.style.color = '#303133';
        clone.style.verticalAlign = 'middle';
        for (const child of clone.querySelectorAll('*')) {
          child.style.setProperty('white-space', 'normal', 'important');
          child.style.setProperty('overflow', 'visible', 'important');
          child.style.setProperty('text-overflow', 'clip', 'important');
          child.style.setProperty('word-break', 'break-word', 'important');
          child.style.setProperty('height', 'auto', 'important');
        }
        clonedRow.appendChild(clone);
        includedColumns.push(labels[index]);
        values[labels[index]] = (clone.innerText || '').replace(/\s+/g, ' ').trim();
      }
      body.appendChild(clonedRow);
      table.appendChild(body);
      container.appendChild(table);
      document.body.appendChild(container);
      return { includedColumns, values, text: (clonedRow.innerText || '').trim() };
    }, { markerId: marker });
    if (cloneInfo.error) throw new Error(cloneInfo.error);
    if (!cloneInfo.text.includes(orderNumber)) throw new Error('TMS 截图克隆区域缺少交易号');
    for (const requiredColumn of ['订单号', '运单号', '客服备注']) {
      if (!cloneInfo.includedColumns.includes(requiredColumn)) {
        throw new Error(`TMS 截图克隆区域缺少“${requiredColumn}”列`);
      }
    }
    const currentProgress = readProgress();
    const expectedTrackingNumber = String(
      currentProgress.tmsAutofillVerification?.actual?.trackingNumber
        || currentProgress.logisticsAnalysis?.trackingNumber
        || '',
    ).trim();
    if (!expectedTrackingNumber || !cloneInfo.text.includes(expectedTrackingNumber)) {
      throw new Error('TMS 截图克隆区域缺少当前订单运单号');
    }
    const actualProblemType = cloneInfo.values?.['物流问题'] || '';
    const actualRemark = cloneInfo.values?.['客服备注'] || '';
    const directDecisionMatch = tmsEvidenceDecisionMatches({
      expectedProblemType: workOrder.problemType,
      expectedRemark: workOrder.customerRemark,
      actualProblemType,
      actualRemark,
    });
    const existingComparison = workOrder.existingDecisionComparison;
    const compatibleExistingDecision = existingComparison?.matches === true
      && [
        'completed-return-covers-loss-decision',
        'completed-intercept-covers-low-value-refund',
      ].includes(existingComparison.matchMode)
      && normalizeTmsDecisionText(existingComparison.actualProblemType)
        === normalizeTmsDecisionText(actualProblemType)
      && normalizeTmsDecisionText(existingComparison.actualRemark).replace(/复制$/u, '')
        === normalizeTmsDecisionText(actualRemark).replace(/复制$/u, '');
    if (workOrder.customerRemark && !directDecisionMatch && !compatibleExistingDecision) {
      throw new Error(`TMS 截图克隆区域的物流问题或客服备注与本次要求不匹配: ${JSON.stringify({
        expectedProblemType: workOrder.problemType,
        actualProblemType,
        actualRemark,
        existingDecisionMatchMode: existingComparison?.matchMode || null,
      })}`);
    }
    const screenshotTarget = targetPage.locator(`#${marker}`);
    const buffer = await screenshotTarget.screenshot({ type: 'png', animations: 'disabled', caret: 'hide' });
    await screenshotTarget.evaluate((element) => element.remove()).catch(() => {});
    const inspection = inspectPngBuffer(buffer, { minWidth: 500, minHeight: 30 });
    fs.mkdirSync(tmsEvidenceScreenshotDir, { recursive: true, mode: 0o700 });
    fs.writeFileSync(absolutePath, buffer, { mode: 0o600 });
    fs.chmodSync(absolutePath, 0o600);
    const savedInspection = inspectPngBuffer(fs.readFileSync(absolutePath), { minWidth: 500, minHeight: 30 });
    const metadata = {
      shopId,
      orderNumber,
      ticketId: workOrder.ticketId,
      ticketNo: workOrder.ticketNo,
      relativePath,
      mimeType: 'image/png',
      width: savedInspection.width,
      height: savedInspection.height,
      sizeBytes: savedInspection.sizeBytes,
      includedColumns: cloneInfo.includedColumns,
      verifiedTrackingNumber: expectedTrackingNumber,
      verifiedReminderRequest: workOrder.customerRemark || null,
      verifiedProblemType: actualProblemType || null,
      verifiedCustomerRemark: actualRemark || null,
      createdAt: new Date().toISOString(),
      status: 'ready',
      purpose: 'pdd-work-order-reply',
    };
    if (inspection.width !== savedInspection.width || inspection.height !== savedInspection.height) {
      throw new Error('TMS 截图写入前后尺寸不一致');
    }
    writeProgress({ step: 'tms-evidence-screenshot-ready', tmsEvidenceScreenshot: metadata });
    return metadata;
  } catch (error) {
    await targetPage.locator(`#${marker}`).evaluate((element) => element.remove()).catch(() => {});
    writeProgress({
      step: 'tms-evidence-screenshot-failed',
      tmsEvidenceScreenshot: {
        shopId,
        orderNumber,
        ticketId: workOrder.ticketId,
        ticketNo: workOrder.ticketNo,
        relativePath,
        mimeType: 'image/png',
        status: 'failed',
        failedAt: new Date().toISOString(),
        error: error.message,
      },
    });
    throw error;
  }
};

const resolveReadyTmsEvidence = (orderNumber, progress = readProgress()) => {
  const metadata = progress.tmsEvidenceScreenshot;
  if (!metadata
    || metadata.status !== 'ready'
    || metadata.orderNumber !== orderNumber
    || (metadata.shopId && metadata.shopId !== shopId)
    || !metadata.relativePath) {
    throw new Error('TMS 截图元数据尚未就绪或与当前店铺订单不一致');
  }
  const absolutePath = path.resolve(workflowDataDir, metadata.relativePath);
  if (!isPathInside(tmsEvidenceScreenshotDir, absolutePath)) {
    throw new Error('TMS 截图路径超出当前店铺受控临时目录');
  }
  if (!exists(absolutePath)) throw new Error('TMS 截图元数据存在但文件已丢失');
  const inspection = inspectPngBuffer(fs.readFileSync(absolutePath), { minWidth: 500, minHeight: 30 });
  if (metadata.width && metadata.width !== inspection.width) throw new Error('TMS 截图宽度与元数据不一致');
  if (metadata.height && metadata.height !== inspection.height) throw new Error('TMS 截图高度与元数据不一致');
  return { metadata, absolutePath, inspection };
};

// Keep the visible uploader path reliable on slow pages. A very small
// environment override can make the chooser event lose a race with the
// click, which incorrectly sends a supported visible control to the hidden
// input fallback.
const pddEvidenceFileChooserTimeoutMs = Math.max(
  500,
  Number(process.env.PDD_EVIDENCE_FILE_CHOOSER_TIMEOUT_MS || '5000'),
);

const describePddEvidenceUploadElement = async (locator) => locator.evaluate((element) => ({
  tagName: element.tagName?.toLowerCase() || null,
  role: element.getAttribute?.('role') || null,
  className: String(element.className || '').slice(0, 200),
  text: String(element.innerText || element.textContent || '')
    .replace(/\s+/g, ' ').trim().slice(0, 200),
})).catch(() => null);

const setPddEvidenceUploadFile = async (targetPage, uploadFile, actionLabel) => {
  const fileInput = targetPage.locator('input[type="file"]');
  const fileCount = await fileInput.count().catch(() => 0);
  const fileInputs = await fileInput.evaluateAll((inputs) => inputs.map((input, index) => ({
    index,
    accept: input.getAttribute('accept'),
    multiple: input.hasAttribute('multiple'),
    disabled: input.disabled,
    nearbyText: String(input.parentElement?.innerText || input.parentElement?.textContent || '')
      .replace(/\s+/g, ' ').trim().slice(0, 200),
  }))).catch(() => []);
  const inputOwnedCandidates = fileCount ? [
    fileInput.first().locator('xpath=ancestor::label[1]'),
    fileInput.first().locator('xpath=ancestor::*[@role="button"][1]'),
  ] : [];
  const uploadTrigger = await firstVisible([
    ...inputOwnedCandidates,
    targetPage.getByRole('button', { name: /上传凭证|上传图片|上传附件/ }),
    targetPage.getByText(/^(上传凭证|上传图片|上传附件)$/, { exact: true }),
    targetPage.locator('label[for*="upload" i]').filter({ hasText: /上传/ }),
    targetPage.locator('[class*="upload" i]').filter({ hasText: /上传凭证|上传图片|上传附件/ }),
  ]);
  let visibleTriggerFailure = null;
  if (uploadTrigger) {
    const trigger = await describePddEvidenceUploadElement(uploadTrigger);
    const chooserResultPromise = targetPage
      .waitForEvent('filechooser', { timeout: pddEvidenceFileChooserTimeoutMs })
      .then((chooser) => ({ chooser, error: null }))
      .catch((error) => ({ chooser: null, error }));
    try {
      await pacedAction(targetPage, 'open-pdd-evidence-uploader', () => uploadTrigger.click());
      const chooserResult = await chooserResultPromise;
      if (chooserResult.chooser) {
        await chooserResult.chooser.setFiles(uploadFile);
        return {
          fileInputs,
          interaction: {
            method: 'visible-trigger-filechooser',
            trigger,
            fallbackReason: null,
          },
        };
      }
      visibleTriggerFailure = chooserResult.error?.message || '可见上传入口未触发文件选择器';
    } catch (error) {
      await chooserResultPromise;
      visibleTriggerFailure = error.message;
    }
  }
  if (!fileCount) {
    const error = new Error('拼多多未找到可用的凭证上传控件');
    error.pddEvidenceUploadInteraction = {
      method: 'unavailable',
      trigger: uploadTrigger ? await describePddEvidenceUploadElement(uploadTrigger) : null,
      fallbackReason: visibleTriggerFailure,
    };
    error.pddEvidenceUploadFileInputs = fileInputs;
    throw error;
  }
  await pacedAction(targetPage, `upload-pdd-${actionLabel}`, () => (
    fileInput.first().setInputFiles(uploadFile)
  ));
  return {
    fileInputs,
    interaction: {
      method: 'direct-file-input-fallback',
      trigger: uploadTrigger ? await describePddEvidenceUploadElement(uploadTrigger) : null,
      fallbackReason: visibleTriggerFailure || '未找到可见上传入口',
    },
  };
};

const pddEvidencePrimaryBucketTag = 'work-flow-ticket';
const pddEvidenceFallbackBucketTag = 'pdd_mms';
const pddEvidenceSignatureEndpointPattern = '**/galerie/business/get_signature';
const pddEvidenceImageUploadEndpointPattern = /\/v3\/store_image(?:\?|$)/u;

const parsePddEvidenceImageUploadReceipt = ({ requestUrl, status, body }) => {
  if (!pddEvidenceImageUploadEndpointPattern.test(String(requestUrl || ''))
    || Number(status) < 200
    || Number(status) >= 300
    || !body
    || typeof body !== 'object') return null;
  const remoteUrl = String(body.url || '').trim();
  let parsedUrl;
  try {
    parsedUrl = new URL(remoteUrl);
  } catch {
    return null;
  }
  if (parsedUrl.protocol !== 'https:'
    || !/(?:^|\.)pddpic\.com$/iu.test(parsedUrl.hostname)
    || !(Number(body.size) > 0)
    || !(Number(body.width) > 0)
    || !(Number(body.height) > 0)) return null;
  return {
    remoteUrl,
    host: parsedUrl.hostname,
    status: Number(status),
    etag: String(body.etag || '').trim() || null,
    size: Number(body.size),
    width: Number(body.width),
    height: Number(body.height),
  };
};

const publicPddEvidenceImageUploadReceipt = (receipt) => receipt ? ({
  host: receipt.host,
  status: receipt.status,
  etag: receipt.etag,
  size: receipt.size,
  width: receipt.width,
  height: receipt.height,
  remoteUrlSha256: crypto.createHash('sha256').update(receipt.remoteUrl).digest('hex'),
}) : null;

const pddEvidenceImageRetainedInDom = async (targetPage, remoteUrl) => {
  if (!remoteUrl) return false;
  for (const frame of targetPage.frames()) {
    const retained = await frame.locator('img[src], [style*="background-image"]').evaluateAll(
      (elements, expectedUrl) => {
        let expected;
        try {
          expected = new URL(expectedUrl);
        } catch {
          return false;
        }
        return elements.some((element) => {
          const candidates = [
            element.currentSrc,
            element.src,
            element.getAttribute?.('src'),
            element.style?.backgroundImage,
          ].filter(Boolean);
          return candidates.some((candidate) => {
            const raw = String(candidate).replace(/^url\(["']?|["']?\)$/gu, '');
            if (raw === expectedUrl || raw.startsWith(`${expectedUrl}?`)) return true;
            try {
              const parsed = new URL(raw, document.baseURI);
              return parsed.hostname === expected.hostname && parsed.pathname === expected.pathname;
            } catch {
              return false;
            }
          });
        });
      },
      remoteUrl,
    ).catch(() => false);
    if (retained) return true;
  }
  return false;
};

const pddEvidenceUploadedMarkerSelector = [
  '.ant-upload-list-item-done:visible',
  '.beast-core-upload-list-item-done:visible',
  '[class*="upload" i][class*="success" i]:visible',
].join(', ');

const pddEvidenceUploadedMarkerVisible = async (targetPage) => {
  for (const frame of targetPage.frames()) {
    if (await frame.locator(pddEvidenceUploadedMarkerSelector).first()
      .isVisible().catch(() => false)) return true;
  }
  return false;
};

const checkForHumanVerification = async (targetPage, stage) => {
  if (workflowSystemForAction(targetPage, stage) === 'pdd') {
    await waitForPddPostLoginBarrier(targetPage, stage, {
      source: 'verification-check',
    });
  }
  const key = workflowSystemForAction(targetPage, stage) || 'workflow';
  let shared = activeHumanVerificationChecks.get(key);
  if (!shared) {
    const current = checkForHumanVerificationUnsafe(targetPage, stage);
    shared = current.finally(() => {
      if (activeHumanVerificationChecks.get(key) === shared) activeHumanVerificationChecks.delete(key);
    });
    activeHumanVerificationChecks.set(key, shared);
  }
  const result = await shared;
  const progress = readProgress();
  const timeout = progress.verificationTimeout;
  const suppressionUntil = Date.parse(String(timeout?.suppressUntil || ''))
    || Date.parse(String(timeout?.timedOutAt || '')) + humanVerificationPostTimeoutSuppressionMs;
  if (timeout?.status !== 'closed' || timeout.system !== key
    || !(suppressionUntil > Date.now()) || targetPage.isClosed()
    || (timeout.surface?.url && timeout.surface.url !== targetPage.url())) return result;
  // Cooldown suppresses duplicate scheduler gates, not the live challenge.
  // Check each caller's exact page after a shared scan: a clear anchor must
  // not authorize clicks/scrolls in a detail tab still covered by a slider.
  const detection = await detectHumanVerification(targetPage);
  if (detection && verificationTimeoutSuppressesSurface(progress, {
    system: key, page: targetPage, detection,
  })) {
    throw new HumanVerificationTimeoutError(
      stage, targetPage.url(), timeout.closeResult || null,
      timeout.timeoutMs || humanVerificationMaxTimeoutMs,
    );
  }
  return result;
};

const pddSignaturePayload = (value) => {
  if (!value || typeof value !== 'object') return null;
  return value.result && typeof value.result === 'object' ? value.result : value;
};

const installPddEvidenceUploadBucketFallback = async (targetPage) => {
  const state = {
    primaryBucketTag: pddEvidencePrimaryBucketTag,
    fallbackBucketTag: pddEvidenceFallbackBucketTag,
    attempted: false,
    used: false,
    primaryErrorCode: null,
    fallbackErrorCode: null,
    fallbackErrorMessage: null,
    usedAt: null,
  };
  const handler = async (route) => {
    const request = route.request();
    if (request.method() !== 'POST') {
      await route.continue();
      return;
    }
    let requestPayload = null;
    try {
      requestPayload = JSON.parse(request.postData() || '{}');
    } catch {}
    if (requestPayload?.bucket_tag !== pddEvidencePrimaryBucketTag) {
      await route.continue();
      return;
    }

    let primaryResponse;
    try {
      primaryResponse = await route.fetch();
    } catch {
      await route.continue();
      return;
    }
    let primaryBody = null;
    try {
      primaryBody = JSON.parse(await primaryResponse.text());
    } catch {}
    const primaryErrorCode = Number(primaryBody?.error_code);
    const primaryErrorMessage = String(primaryBody?.error_msg || '').trim();
    if (primaryErrorCode !== 48143 && !/非法请求/u.test(primaryErrorMessage)) {
      await route.fulfill({ response: primaryResponse });
      return;
    }

    state.attempted = true;
    state.primaryErrorCode = Number.isFinite(primaryErrorCode) ? primaryErrorCode : 48143;
    let fallbackBody = null;
    try {
      fallbackBody = await targetPage.evaluate(async ({ bucketTag }) => {
        const response = await fetch('/galerie/business/get_signature', {
          method: 'POST',
          headers: { 'content-type': 'application/json' },
          credentials: 'include',
          body: JSON.stringify({ bucket_tag: bucketTag }),
        });
        return response.json();
      }, { bucketTag: pddEvidenceFallbackBucketTag });
    } catch (error) {
      state.fallbackErrorMessage = error.message;
    }
    const fallbackPayload = pddSignaturePayload(fallbackBody);
    if (fallbackBody?.success === true && String(fallbackPayload?.signature || '').trim()) {
      state.used = true;
      state.usedAt = new Date().toISOString();
      await route.fulfill({
        status: 200,
        contentType: 'application/json;charset=UTF-8',
        headers: {
          'cache-control': 'no-store',
          'x-pdd-evidence-bucket-fallback': pddEvidenceFallbackBucketTag,
        },
        body: JSON.stringify(fallbackBody),
      });
      return;
    }
    const fallbackErrorCode = Number(fallbackBody?.error_code);
    state.fallbackErrorCode = Number.isFinite(fallbackErrorCode) ? fallbackErrorCode : null;
    state.fallbackErrorMessage = state.fallbackErrorMessage
      || String(fallbackBody?.error_msg || '拼多多通用图片桶未返回上传签名');
    await route.fulfill({ response: primaryResponse });
  };

  await targetPage.route(pddEvidenceSignatureEndpointPattern, handler);
  return {
    snapshot: () => ({ ...state }),
    dispose: () => targetPage
      .unroute(pddEvidenceSignatureEndpointPattern, handler)
      .catch(() => {}),
  };
};

const uploadTmsEvidenceToPdd = async (targetPage, orderNumber, {
  evidence: suppliedEvidence = null,
  progressField = 'pddEvidenceUpload',
  actionLabel = 'tms-evidence',
} = {}) => {
  const progress = readProgress();
  const evidence = suppliedEvidence || resolveReadyTmsEvidence(orderNumber, progress);
  const uploadFile = preparePddEvidenceUpload(evidence.absolutePath, orderNumber);
  const uploadNetwork = [];
  const pendingResponseCaptures = new Set();
  let imageUploadReceipt = null;
  const redactUploadDiagnostic = (value, key = '') => {
    if (/(?:token|sign|secret|cookie|anti.?content|verify|auth)/i.test(key)) {
      return `<redacted:${String(value ?? '').length}>`;
    }
    if (Array.isArray(value)) return value.map((item) => redactUploadDiagnostic(item));
    if (value && typeof value === 'object') {
      return Object.fromEntries(Object.entries(value)
        .map(([childKey, childValue]) => [childKey, redactUploadDiagnostic(childValue, childKey)]));
    }
    return value;
  };
  const captureUploadResponse = async (response) => {
    const request = response.request();
    if (request.method() === 'GET' || request.method() === 'OPTIONS') return;
    let pathname = request.url();
    try {
      const parsed = new URL(request.url());
      pathname = `${parsed.origin}${parsed.pathname}`;
    } catch {}
    const contentType = String(response.headers()['content-type'] || '');
    let responsePreview = '';
    let responseJson = null;
    try {
      const body = await response.body();
      if (/json/i.test(contentType)) {
        const responseText = body.toString('utf8');
        try {
          responseJson = JSON.parse(responseText);
          responsePreview = JSON.stringify(redactUploadDiagnostic(responseJson)).slice(0, 1024);
        } catch {
          responsePreview = responseText.slice(0, 1024);
        }
      } else {
        responsePreview = /text|javascript|xml/i.test(contentType)
          ? body.toString('utf8').slice(0, 1024)
          : `<binary ${body.length} bytes>`;
      }
    } catch (error) {
      responsePreview = `<unavailable: ${error.message}>`;
    }
    let requestData = request.postData() || null;
    if (requestData) {
      try {
        requestData = redactUploadDiagnostic(JSON.parse(requestData));
        if (pathname.includes('xg.pinduoduo.com') && requestData && typeof requestData === 'object' && 'data' in requestData) {
          requestData.data = `<redacted:${String(requestData.data || '').length}>`;
        }
      } catch {
        requestData = requestData.slice(0, 2048);
      }
    }
    let requestHeaders = {};
    try {
      requestHeaders = Object.fromEntries(Object.entries(await request.allHeaders()).map(([header, value]) => [
        header,
        /(?:cookie|token|sign|secret|anti.?content|verify|auth)/i.test(header)
          ? `<redacted:${String(value || '').length}>`
          : String(value || '').slice(0, 512),
      ]));
    } catch {}
    const confirmedImageUpload = parsePddEvidenceImageUploadReceipt({
      requestUrl: pathname,
      status: response.status(),
      body: responseJson,
    });
    if (confirmedImageUpload) imageUploadReceipt = confirmedImageUpload;
    uploadNetwork.push({
      method: request.method(),
      url: pathname,
      status: response.status(),
      contentType: contentType || null,
      requestContentType: request.headers()['content-type'] || null,
      requestHeaders,
      requestData,
      response: responsePreview,
    });
  };
  const onUploadResponse = (response) => {
    const capture = captureUploadResponse(response)
      .catch(() => {})
      .finally(() => pendingResponseCaptures.delete(capture));
    pendingResponseCaptures.add(capture);
  };
  const finishUploadDiagnostics = async () => {
    targetPage.off('response', onUploadResponse);
    await Promise.allSettled([...pendingResponseCaptures]);
  };

  writeProgress({
    step: 'pdd-evidence-uploading',
    [progressField]: {
      shopId,
      orderNumber,
      relativePath: evidence.metadata.relativePath,
      status: 'uploading',
      uploadedAt: null,
      error: null,
      uploadImage: {
        sourceWidth: uploadFile.sourceWidth,
        sourceHeight: uploadFile.sourceHeight,
        width: uploadFile.width,
        height: uploadFile.height,
        padded: uploadFile.padded,
      },
    },
  });
  targetPage.on('response', onUploadResponse);
  let fileInputs = [];
  let uploadInteraction = null;
  let uploadAttempted = false;
  let bucketFallbackControl = null;
  try {
    bucketFallbackControl = await installPddEvidenceUploadBucketFallback(targetPage);
    const uploaded = await guardedExternalEffect({
      effectType: 'evidence-upload',
      orderNumber,
      stage: `pdd-evidence-upload-${actionLabel}`,
      request: {
        orderNumber,
        actionLabel,
        evidenceSource: evidence.metadata.relativePath,
        evidenceSha256: crypto.createHash('sha256').update(uploadFile.buffer).digest('hex'),
        width: uploadFile.width,
        height: uploadFile.height,
      },
    }, async () => {
      try {
        const fileSelection = await setPddEvidenceUploadFile(
          targetPage,
          uploadFile,
          actionLabel,
        );
        fileInputs = fileSelection.fileInputs;
        uploadInteraction = fileSelection.interaction;
        uploadAttempted = true;

        const deadline = Date.now() + 45000;
        let uploadConfirmed = false;
        let lastBodyText = '';
        while (Date.now() < deadline) {
          lastBodyText = await targetPage.locator('main').innerText()
            .catch(() => targetPage.locator('body').innerText());
          const failure = lastBodyText.match(
            new RegExp(`(?:Error\\s*[:：]\\s*)?${pddEvidenceUploadDefinitiveFailurePattern.source}`, 'u'),
          );
          if (failure) throw new Error(`拼多多凭证上传失败: ${failure[0]}`);
          const uploadPending = /请等待上传完毕|正在上传|上传中/.test(lastBodyText);
          await Promise.allSettled([...pendingResponseCaptures]);
          const successMarkerVisible = await pddEvidenceUploadedMarkerVisible(targetPage);
          const imageRetained = await pddEvidenceImageRetainedInDom(
            targetPage,
            imageUploadReceipt?.remoteUrl,
          );
          if (!uploadPending && (successMarkerVisible || imageRetained)) {
            uploadConfirmed = true;
            break;
          }
          await targetPage.waitForTimeout(500);
        }
        if (!uploadConfirmed) {
          throw new Error(`拼多多上传接口可能已成功，但当前表单未显示已附加凭证: ${lastBodyText.slice(-200)}`);
        }
        return {
          shopId,
          orderNumber,
          relativePath: evidence.metadata.relativePath,
          status: 'uploaded',
          uploadedAt: new Date().toISOString(),
          error: null,
          uploadImage: {
            sourceWidth: uploadFile.sourceWidth,
            sourceHeight: uploadFile.sourceHeight,
            width: uploadFile.width,
            height: uploadFile.height,
            padded: uploadFile.padded,
          },
          uploadInteraction,
          bucketFallback: bucketFallbackControl.snapshot(),
          imageUploadReceipt: publicPddEvidenceImageUploadReceipt(imageUploadReceipt),
        };
      } catch (error) {
        fileInputs = error.pddEvidenceUploadFileInputs || fileInputs;
        uploadInteraction = error.pddEvidenceUploadInteraction || uploadInteraction;
        await Promise.allSettled([...pendingResponseCaptures]);
        const { sessionExpiry, authorizationFailure } = decoratePddEvidenceUploadError(error, uploadNetwork);
        const effectStatus = classifyPddEvidenceUploadEffectStatus({
          uploadAttempted,
          authorizationFailure: authorizationFailure || sessionExpiry,
          message: error.message,
        });
        if (effectStatus === 'failed') error.externalEffectStatus = 'failed';
        throw error;
      }
    });
    await finishUploadDiagnostics();
    writeProgress({ step: 'pdd-evidence-uploaded', [progressField]: uploaded });
    return uploaded;
  } catch (error) {
    await finishUploadDiagnostics();
    const { sessionExpiry, authorizationFailure } = decoratePddEvidenceUploadError(error, uploadNetwork);
    const effectStatus = error.externalEffectStatus === 'failed' ? 'failed' : 'unknown';
    writeProgress({
      step: 'pdd-evidence-upload-failed',
      [progressField]: {
        shopId,
        orderNumber,
        relativePath: evidence.metadata.relativePath,
        status: effectStatus,
        uploadedAt: null,
        error: error.message,
        diagnostics: {
          fileInputs,
          uploadInteraction,
          bucketFallback: bucketFallbackControl?.snapshot() || null,
          imageUploadReceipt: publicPddEvidenceImageUploadReceipt(imageUploadReceipt),
          network: uploadNetwork,
          sessionExpiry,
          authorizationFailure,
        },
        uploadImage: {
          sourceWidth: uploadFile.sourceWidth,
          sourceHeight: uploadFile.sourceHeight,
          width: uploadFile.width,
          height: uploadFile.height,
          padded: uploadFile.padded,
        },
      },
    });
    throw error;
  } finally {
    await bucketFallbackControl?.dispose();
  }
};

const hasConsumableTmsEvidence = (progress, orderNumber) => {
  try {
    resolveReadyTmsEvidence(orderNumber, progress);
    return true;
  } catch {
    return false;
  }
};

const recoverMissingTmsEvidence = async (orderNumber, progress) => {
  const savedWorkOrder = progress?.tmsWorkOrder;
  if (savedWorkOrder?.status !== 'created'
    || savedWorkOrder.orderNumber !== orderNumber
    || !savedWorkOrder.ticketId
    || !savedWorkOrder.ticketNo) {
    throw new Error('TMS 截图缺失，但当前进度没有可安全复用的已创建工单标识');
  }
  const scenarioCode = progress.scenarioCode
    || activeScenarioCode
    || matchingScenarioForTitle(progress.workOrderType || activeWorkOrderType)?.code
    || null;
  writeProgress({
    step: 'tms-evidence-recovery-started',
    tmsEvidenceRecovery: {
      orderNumber,
      ticketId: savedWorkOrder.ticketId,
      ticketNo: savedWorkOrder.ticketNo,
      status: 'locating-existing-ticket-read-only',
      startedAt: new Date().toISOString(),
    },
    error: null,
  });
  await ensureScenarioSystemDependencies(scenarioCode, ['TMS']);
  const current = readProgress();
  const rowSelection = await selectKnownTmsRow(tmsPage, orderNumber, savedWorkOrder);
  if (!rowSelection.row) {
    const retryable = new LogisticsRetryRequiredError(
      'tms-evidence-row-recovery',
      'TMS 已创建工单的客服登记行暂未稳定显示，等待后只读重查，禁止重复建单',
      30_000,
      { orderNumber, ticketId: savedWorkOrder.ticketId, ticketNo: savedWorkOrder.ticketNo },
    );
    writeProgress({
      step: 'tms-evidence-recovery-retry-ready',
      tmsEvidenceRecovery: {
        ...(readProgress().tmsEvidenceRecovery || {}),
        status: 'retry-ready',
        retryAt: new Date(Date.now() + 30_000).toISOString(),
        checkedAt: new Date().toISOString(),
      },
      error: retryable.message,
    });
    throw retryable;
  }
  const existing = await identifyExistingTmsTicket(rowSelection, orderNumber, current, {
    allowMissingExpectedLogistics: isExtendedOrdinaryScenario(scenarioCode),
    allowReadableUnmappedValues: isExtendedOrdinaryScenario(scenarioCode),
    formDecision: current.tmsFormDecision || null,
    knownTicket: savedWorkOrder,
  });
  if (existing.status !== 'matched') {
    await pauseForManualReview(
      tmsPage,
      'tms-evidence-recovery',
      existing.reason || '已保存 TMS 工单标识无法与当前唯一记录安全对应，禁止重建工单',
      {
        tmsDuplicateCheck: { ...existing, orderNumber, checkedAt: new Date().toISOString() },
        tmsEvidenceRecovery: {
          ...(readProgress().tmsEvidenceRecovery || {}),
          status: 'manual-review-required',
        },
      },
    );
  }
  const workOrder = {
    ...savedWorkOrder,
    ticketId: existing.ticketId,
    ticketNo: existing.ticketNo,
    existingDecisionComparison: existing.decisionComparison || savedWorkOrder.existingDecisionComparison || null,
    existingWarehouseReconciliation:
      existing.warehouseReconciliation || savedWorkOrder.existingWarehouseReconciliation || null,
    recovered: true,
    evidenceRecoveredAt: new Date().toISOString(),
    error: null,
  };
  writeProgress({
    step: 'tms-evidence-recovery-row-confirmed',
    tmsWorkOrder: workOrder,
    tmsDuplicateCheck: { ...existing, orderNumber, checkedAt: new Date().toISOString(), readOnly: true },
    tmsEvidenceRecovery: {
      ...(readProgress().tmsEvidenceRecovery || {}),
      status: 'capturing-existing-ticket',
    },
  });
  const evidence = await captureTmsRowEvidence(tmsPage, rowSelection.row, orderNumber, workOrder, {
    rowSelection,
  });
  initializeTmsEvidenceDisposition(orderNumber, workOrder, evidence);
  writeProgress({
    step: 'tms-evidence-recovered',
    tmsEvidenceRecovery: {
      ...(readProgress().tmsEvidenceRecovery || {}),
      status: 'succeeded',
      completedAt: new Date().toISOString(),
      relativePath: evidence.relativePath,
    },
    error: null,
  });
  return evidence;
};

const initializeTmsEvidenceDisposition = (orderNumber, workOrder, tmsEvidence) => {
  const existing = readProgress().tmsEvidenceDisposition;
  if (existing?.orderNumber === orderNumber
    && existing.ticketId === workOrder.ticketId
    && existing.status !== 'deleted') return existing;
  const disposition = {
    shopId,
    orderNumber,
    ticketId: workOrder.ticketId,
    ticketNo: workOrder.ticketNo,
    usage: 'pending',
    status: 'ready',
    screenshotRelativePath: tmsEvidence.relativePath,
    createdAt: new Date().toISOString(),
    usedAt: null,
    pddCompletedAt: null,
    deletedAt: null,
    reason: '等待拼多多工单判断是否需要使用 TMS 截图',
  };
  writeProgress({ tmsEvidenceDisposition: disposition });
  return disposition;
};

const markTmsEvidenceUnused = (orderNumber, workOrderType) => {
  const progress = readProgress();
  const disposition = progress.tmsEvidenceDisposition;
  if (!disposition
    || disposition.orderNumber !== orderNumber
    || disposition.status === 'deleted') {
    throw new Error('TMS 截图生命周期状态与当前订单不一致');
  }
  const updated = {
    ...disposition,
    usage: 'unused',
    status: 'ready',
    workOrderType,
    decidedAt: new Date().toISOString(),
    reason: '在途无理由退款处理当前不上传 TMS 截图回拼多多',
  };
  writeProgress({ tmsEvidenceDisposition: updated });
  return updated;
};

const isDirectPddConsumerNegotiationFollowup = (progress, orderNumber) => {
  const submission = progress.pddResolutionSubmission || {};
  const disposition = progress.tmsEvidenceDisposition;
  const exactOrder = String(orderNumber || '').trim();
  const dispositionMayBeOmitted = !disposition
    || (disposition.orderNumber === exactOrder && disposition.status === 'deleted');
  return Boolean(
    exactOrder
      && progress.scenarioCode === 'in-transit-refund'
      && progress.consumerNegotiationFollowupRecovery?.strategy
        === 'resume-pdd-followup-without-oms-or-tms-replay'
      && submission.orderNumber === exactOrder
      && ['followup-waiting', 'followup-ready'].includes(submission.status)
      && submission.interceptProgressOutcome === '快递还在拦截中'
      && submission.consumerResponseWaitStartedAt
      && dispositionMayBeOmitted,
  );
};

const isDirectPddInTransitOutcomeFallback = (progress, orderNumber) => {
  const fallback = resolvePddInTransitOutcomeFallbackResume(progress, orderNumber);
  const disposition = progress.tmsEvidenceDisposition;
  const dispositionMayBeOmitted = !disposition
    || (disposition.orderNumber === orderNumber && disposition.status === 'deleted');
  return Boolean(
    fallback?.ready
      && progress.inTransitOutcomeFallbackRecovery?.strategy
        === 'resume-pdd-outcome-fallback-without-oms-or-tms-replay'
      && dispositionMayBeOmitted,
  );
};

const markTmsEvidenceUnusedForPddResolution = (orderNumber, workOrderType) => {
  const progress = readProgress();
  if (isDirectPddConsumerNegotiationFollowup(progress, orderNumber)) {
    return {
      shopId,
      orderNumber,
      usage: 'unused',
      status: 'omitted-after-consumer-negotiation-release',
      workOrderType,
      decidedAt: new Date().toISOString(),
      reason: '消费者协商续跑仅返回拼多多，OMS/TMS 已完成且截图元数据已释放',
    };
  }
  if (isDirectPddInTransitOutcomeFallback(progress, orderNumber)) {
    return {
      shopId,
      orderNumber,
      usage: 'unused',
      status: 'omitted-after-outcome-fallback-release',
      workOrderType,
      decidedAt: new Date().toISOString(),
      reason: '退款选项回退仅返回拼多多，OMS/TMS 已完成且截图元数据已释放',
    };
  }
  return markTmsEvidenceUnused(orderNumber, workOrderType);
};

const markTmsEvidenceUsed = (orderNumber, workOrderType) => {
  const progress = readProgress();
  const disposition = progress.tmsEvidenceDisposition;
  if (!disposition || disposition.orderNumber !== orderNumber || disposition.status === 'deleted') {
    throw new Error('TMS 截图生命周期状态与当前订单不一致');
  }
  const updated = {
    ...disposition,
    usage: 'used',
    status: 'ready',
    workOrderType,
    usedAt: new Date().toISOString(),
    decidedAt: new Date().toISOString(),
    reason: '拼多多主观原因拦截流程已上传 TMS 截图',
  };
  writeProgress({ tmsEvidenceDisposition: updated });
  return updated;
};

const markTmsEvidenceOmitted = (orderNumber, workOrderType, reason) => {
  const progress = readProgress();
  const disposition = progress.tmsEvidenceDisposition;
  if (!disposition || disposition.orderNumber !== orderNumber || disposition.status === 'deleted') {
    throw new Error('TMS 截图生命周期状态与当前订单不一致');
  }
  const updated = {
    ...disposition,
    usage: 'unused',
    status: 'ready',
    workOrderType,
    decidedAt: new Date().toISOString(),
    reason,
  };
  writeProgress({ tmsEvidenceDisposition: updated });
  return updated;
};

const currentScenarioIdentityForOrder = (orderNumber, { persist = false } = {}) => {
  const progress = readProgress();
  const claimMatches = Boolean(orderNumber && requestedOrderNumber === orderNumber);
  const identity = resolveScenarioIdentity({
    progressScenarioCode: progress.scenarioCode,
    progressWorkOrderType: progress.workOrderType,
    claimedScenarioCode: activeScenarioCode,
    claimedWorkOrderType: activeWorkOrderType,
    claimMatches,
  });
  if (persist && identity.scenarioCode && (
    progress.scenarioCode !== identity.scenarioCode
    || (claimMatches && identity.workOrderType && progress.workOrderType !== identity.workOrderType)
  )) {
    writeProgress({
      scenarioCode: identity.scenarioCode,
      ...(claimMatches && identity.workOrderType ? { workOrderType: identity.workOrderType } : {}),
    });
  }
  return { ...identity, progress };
};

const skipTmsForAbnormalNetwork = (orderNumber) => {
  const { scenarioCode, progress } = currentScenarioIdentityForOrder(orderNumber, { persist: true });
  if (scenarioCode !== 'abnormal-network-warning') {
    throw new Error('只有异常网点预警允许跳过 TMS');
  }
  if (progress.orderNumber !== orderNumber) throw new Error('TMS 跳过状态与当前订单不一致');
  if (progress.tmsWorkOrder?.status === 'created') return null;
  const skippedAt = new Date().toISOString();
  const bypass = {
    shopId,
    orderNumber,
    scenarioCode,
    status: 'skipped',
    reason: '异常网点预警按业务规则不创建 TMS 工单',
    skippedAt,
  };
  writeProgress({
    step: 'tms-skipped-abnormal-network',
    tmsBypass: bypass,
    tmsWorkOrder: { ...bypass, ticketId: null, ticketNo: null },
    tmsEvidenceScreenshot: {
      ...bypass,
      status: 'deleted',
      relativePath: null,
      deletedAt: skippedAt,
    },
    tmsEvidenceDisposition: {
      ...bypass,
      usage: 'unused',
      status: 'deleted',
      deletedAt: skippedAt,
    },
  });
  return bypass;
};

const deletePddEvidenceAfterTmsBypassCompletion = (orderNumber, completion) => {
  const progress = readProgress();
  const cleanupMode = bypassedTmsPddEvidenceCleanupMode(progress, completion, shopId);
  if (cleanupMode === 'not-applicable') return false;
  if (cleanupMode === 'unsafe') {
    throw new Error('异常网点预警的 TMS 跳过状态或拼多多截图身份与当前店铺订单不一致');
  }
  if (cleanupMode === 'already-deleted') return true;

  const evidence = cleanupMode === 'delete-ready'
    ? resolveReadyEvidenceScreenshot(orderNumber, progress)
    : null;
  if (evidence) fs.unlinkSync(evidence.absolutePath);
  const deletedAt = new Date().toISOString();
  writeProgress({
    pddEvidenceScreenshot: {
      ...(evidence?.metadata || {
        shopId,
        orderNumber,
        mimeType: 'image/png',
        purpose: 'tms-logistics-work-order',
      }),
      relativePath: null,
      status: 'deleted',
      consumedAt: deletedAt,
      deletedAt,
      reason: evidence
        ? '异常网点预警跳过 TMS，拼多多完成后清理临时截图'
        : '异常网点预警按规则跳过 TMS，未创建拼多多截图，无需清理文件',
    },
  });
  return true;
};

const deleteTmsEvidenceAfterPddCompletion = (orderNumber, completion) => {
  const progress = readProgress();
  const disposition = progress.tmsEvidenceDisposition;
  const uploadSucceeded = progress.pddEvidenceUpload?.status === 'uploaded'
    && progress.pddEvidenceUpload.orderNumber === orderNumber;
  if (!shouldDeleteTmsEvidence({
    usage: disposition?.usage,
    pddCompleted: completion?.status === 'succeeded',
    uploadSucceeded,
  })) return false;
  if (completion.orderNumber !== orderNumber || disposition.orderNumber !== orderNumber) {
    throw new Error('拼多多完成状态或 TMS 截图状态与当前订单不一致');
  }
  if (progress.tmsEvidenceScreenshot?.status === 'deleted') return true;
  const evidence = resolveReadyTmsEvidence(orderNumber, progress);
  fs.unlinkSync(evidence.absolutePath);
  const deletedAt = new Date().toISOString();
  writeProgress({
    tmsEvidenceScreenshot: {
      ...evidence.metadata,
      relativePath: null,
      status: 'deleted',
      consumedAt: deletedAt,
      deletedAt,
    },
    tmsEvidenceDisposition: {
      ...disposition,
      status: 'deleted',
      pddCompletedAt: completion.completedAt || deletedAt,
      deletedAt,
       reason: disposition.usage === 'used'
         ? '拼多多工单已完成且 TMS 截图已上传'
         : '拼多多工单已完成且未使用 TMS 截图',
    },
  });
  console.log(`拼多多工单已完成，已删除未使用的 TMS 临时截图: ${orderNumber}`);
  return true;
};

const discardRecoveredCompletionOrphanEvidence = (orderNumber, completion) => {
  const progress = readProgress();
  if (!canDiscardRecoveredCompletionOrphanEvidence(progress, completion)) return false;

  const metadata = progress.pddEvidenceScreenshot;
  if (!metadata.relativePath || path.isAbsolute(metadata.relativePath)) {
    throw new Error('Recovered completion PDD evidence relative path is invalid');
  }
  const absolutePath = path.resolve(workflowDataDir, ...metadata.relativePath.split('/'));
  if (!isPathInside(evidenceScreenshotDir, absolutePath)
    || path.basename(absolutePath) !== `${orderNumber}.png`) {
    throw new Error('Recovered completion PDD evidence path is outside the controlled directory');
  }
  if (exists(absolutePath)) {
    const evidence = resolveReadyEvidenceScreenshot(orderNumber, progress);
    fs.unlinkSync(evidence.absolutePath);
  }

  const deletedAt = new Date().toISOString();
  const reason = 'PDD completion was confirmed before TMS/upload evidence existed; orphan metadata removed';
  writeProgress({
    pddEvidenceScreenshot: {
      ...metadata,
      relativePath: null,
      status: 'deleted',
      consumedAt: deletedAt,
      deletedAt,
      reason,
    },
    tmsEvidenceScreenshot: {
      shopId,
      orderNumber,
      relativePath: null,
      status: 'deleted',
      deletedAt,
      reason,
    },
    tmsEvidenceDisposition: {
      shopId,
      orderNumber,
      usage: 'unused',
      status: 'deleted',
      deletedAt,
      reason,
    },
  });
  return true;
};

const discardConsumerNegotiationFollowupEvidence = (orderNumber, completion) => {
  const progress = readProgress();
  if (!canDiscardConsumerNegotiationFollowupEvidence(progress, completion)) return false;

  const metadataItems = [progress.pddEvidenceScreenshot, progress.tmsEvidenceScreenshot]
    .filter(Boolean);
  const deletedPaths = new Set();
  for (const metadata of metadataItems) {
    if (metadata.status === 'deleted') continue;
    if (metadata.status !== 'ready' || metadata.orderNumber !== orderNumber) {
      throw new Error('消费者协商完成证据与当前订单不一致');
    }
    if (!metadata.relativePath || path.isAbsolute(metadata.relativePath)) {
      throw new Error('消费者协商完成证据相对路径无效');
    }
    const absolutePath = path.resolve(workflowDataDir, ...metadata.relativePath.split('/'));
    const controlledPath = isPathInside(evidenceScreenshotDir, absolutePath)
      || isPathInside(tmsEvidenceScreenshotDir, absolutePath);
    if (!controlledPath || path.basename(absolutePath) !== `${orderNumber}.png`) {
      throw new Error('消费者协商完成证据超出受控临时目录');
    }
    if (!deletedPaths.has(absolutePath) && exists(absolutePath)) fs.unlinkSync(absolutePath);
    deletedPaths.add(absolutePath);
  }

  const deletedAt = new Date().toISOString();
  const reason = '消费者协商跟进已由拼多多详情页确认完成，旧临时证据已清理';
  writeProgress({
    pddEvidenceScreenshot: progress.pddEvidenceScreenshot ? {
      ...progress.pddEvidenceScreenshot,
      relativePath: null,
      status: 'deleted',
      consumedAt: deletedAt,
      deletedAt,
      reason,
    } : null,
    tmsEvidenceScreenshot: progress.tmsEvidenceScreenshot ? {
      ...progress.tmsEvidenceScreenshot,
      relativePath: null,
      status: 'deleted',
      consumedAt: deletedAt,
      deletedAt,
      reason,
    } : null,
    tmsEvidenceDisposition: {
      ...(progress.tmsEvidenceDisposition || { shopId, orderNumber, usage: 'unused' }),
      status: 'deleted',
      pddCompletedAt: completion.completedAt || deletedAt,
      deletedAt,
      reason,
    },
  });
  return true;
};

const discardVerifiedTerminalDetailEvidence = (orderNumber, completion) => {
  const progress = readProgress();
  const scenarioCode = completion?.scenarioCode || progress.scenarioCode;
  const verification = {
    progress,
    completion,
    scenarioCode,
    expectedOutcome: completion?.outcome,
    observedOutcome: completion?.completionEvidence,
    observedResultOption: completion?.completionResultOption,
  };
  const exactDetailVerified = verifiedProactiveSummaryMatchesCompletion({
    ...verification, proof: progress.pddProactiveTerminalDetailProof,
  }) || verifiedInterceptSummaryMatchesCompletion({
    ...verification, proof: progress.pddInterceptTerminalDetailProof,
  });
  if (!exactDetailVerified || completion?.status !== 'succeeded'
    || completion.orderNumber !== orderNumber
    || progress.ordinaryEvidenceUpload?.status !== 'uploaded'
    || progress.ordinaryEvidenceUpload.orderNumber !== orderNumber) return false;

  const pddMetadata = progress.pddEvidenceScreenshot;
  const tmsMetadata = progress.tmsEvidenceScreenshot;
  if ((pddMetadata && !['ready', 'deleted'].includes(pddMetadata.status))
    || (tmsMetadata && !['ready', 'deleted'].includes(tmsMetadata.status))
    || (pddMetadata?.status === 'ready' && pddMetadata.orderNumber !== orderNumber)
    || (tmsMetadata?.status === 'ready' && tmsMetadata.orderNumber !== orderNumber)) {
    throw new Error('精确平台终态证据与当前订单不一致，禁止清理截图');
  }
  // Resolve every ready artifact before deleting any file. A bad path must
  // leave all evidence untouched for manual inspection.
  const pddEvidence = pddMetadata?.status === 'ready'
    ? resolveReadyEvidenceScreenshot(orderNumber, progress) : null;
  const tmsEvidence = tmsMetadata?.status === 'ready'
    ? resolveReadyTmsEvidence(orderNumber, progress) : null;
  if (pddEvidence) {
    fs.unlinkSync(pddEvidence.absolutePath);
    const deletedAt = new Date().toISOString();
    writeProgress({ pddEvidenceScreenshot: {
      ...pddMetadata, relativePath: null, status: 'deleted',
      consumedAt: deletedAt, deletedAt,
      reason: '同单提交后平台终态已核实且凭证已上传，清理临时截图',
    } });
  }
  if (tmsEvidence) {
    fs.unlinkSync(tmsEvidence.absolutePath);
    const deletedAt = new Date().toISOString();
    writeProgress({
      tmsEvidenceScreenshot: {
        ...tmsMetadata, relativePath: null, status: 'deleted',
        consumedAt: deletedAt, deletedAt,
      },
      tmsEvidenceDisposition: {
        ...(progress.tmsEvidenceDisposition || { shopId, orderNumber }),
        status: 'deleted', pddCompletedAt: completion.completedAt || deletedAt,
        deletedAt, reason: '同单提交后平台终态已核实且凭证已上传，清理临时截图',
      },
    });
  }
  return Boolean(pddEvidence || tmsEvidence);
};

const finalizeEvidenceAfterPddCompletion = (orderNumber, completion) => (
  discardVerifiedTerminalDetailEvidence(orderNumber, completion)
  || deletePddEvidenceAfterTmsBypassCompletion(orderNumber, completion)
  || deleteTmsEvidenceAfterPddCompletion(orderNumber, completion)
  || discardConsumerNegotiationFollowupEvidence(orderNumber, completion)
  || discardRecoveredCompletionOrphanEvidence(orderNumber, completion)
);

const consumePddEvidenceAfterTmsSuccess = (orderNumber, workOrder, tmsEvidence) => {
  const progress = readProgress();
  if (workOrder.status !== 'created' || workOrder.orderNumber !== orderNumber) {
    throw new Error('TMS 工单尚未确认创建，禁止删除拼多多截图');
  }
  if (tmsEvidence.status !== 'ready'
    || tmsEvidence.orderNumber !== orderNumber
    || tmsEvidence.ticketId !== workOrder.ticketId) {
    throw new Error('TMS 行截图尚未验证，禁止删除拼多多截图');
  }
  const source = resolveReadyEvidenceScreenshot(orderNumber, progress);
  if (!isPathInside(evidenceScreenshotDir, source.absolutePath)) {
    throw new Error('待删除拼多多截图超出受控临时目录');
  }
  fs.unlinkSync(source.absolutePath);
  const deletedAt = new Date().toISOString();
  writeProgress({
    step: 'awaiting-pdd-resolution',
    pddEvidenceScreenshot: {
      ...source.metadata,
      relativePath: null,
      status: 'deleted',
      consumedAt: deletedAt,
      deletedAt,
    },
    tmsWorkOrder: workOrder,
    tmsEvidenceScreenshot: tmsEvidence,
    error: null,
  });
};

const findTmsNewTicketButton = async (targetPage) => firstVisible([
  targetPage.locator('.filter-panel:visible').getByRole('button', { name: '新建', exact: true }),
  targetPage.locator('.el-card:visible .el-card__header').getByRole('button', { name: '新建', exact: true }),
  targetPage.locator('main:visible').getByRole('button', { name: '新建', exact: true }),
  targetPage.locator('button[title*="新建"]:visible'),
  targetPage.locator('[role="button"][aria-label*="新建"]:visible'),
  targetPage.getByRole('button', { name: '新建', exact: true }),
  targetPage.locator('button:visible').filter({ hasText: /^\s*新建\s*$/u }),
]);

const openTmsNewTicketDialog = async (targetPage, browserContext) => {
  const dialogSelector = '.el-dialog.logistics-dialog:visible, .logistics-dialog:visible';
  for (let recoveryPass = 1; recoveryPass <= 2; recoveryPass++) {
    let newButtonClicked = false;
    const deadline = Date.now() + tmsNewTicketEntryTimeoutMs;
    do {
      const dialog = targetPage.locator(dialogSelector).first();
      if (await dialog.isVisible().catch(() => false)) {
        if (!newButtonClicked) console.log('复用已打开的 TMS 新建窗口，不重复点击“新建”。');
        return dialog;
      }
      if (await tmsLoginPageRendered(targetPage)) break;
      if (!newButtonClicked) {
        const newButton = await findTmsNewTicketButton(targetPage);
        if (newButton) {
          await pacedAction(targetPage, 'open-new-tms-ticket', () => newButton.click());
          newButtonClicked = true;
        }
      }
      await targetPage.waitForTimeout(tmsNavigationPollIntervalMs);
    } while (Date.now() < deadline);

    const postWaitDialog = targetPage.locator(dialogSelector).first();
    if (await postWaitDialog.isVisible().catch(() => false)) return postWaitDialog;
    if (recoveryPass === 2) break;
    const loginRedirected = await tmsLoginPageRendered(targetPage);
    logRunStep('tms-new-ticket-entry-recovering', {
      tmsUrl: targetPage.url(),
      reason: loginRedirected ? 'login-redirect' : 'new-button-render-timeout',
      recoveryPass,
    });
    if (!loginRedirected) {
      await navigateSystemPage(
        targetPage,
        tmsLogisticsUrl,
        'recover-tms-new-ticket-entry-render',
      );
    }
    await openTmsCustomerRegistration(targetPage, browserContext);
    await closeUnexpectedTmsPopups(targetPage);
  }

  const loginRendered = await tmsLoginPageRendered(targetPage);
  const visibleButtons = await targetPage.locator('button:visible').allTextContents().catch(() => []);
  throw new Error(
    `TMS 客服登记页两轮等待后仍未找到新建按钮或窗口: url=${targetPage.url()}; `
    + `loginRendered=${loginRendered}; visibleButtons=${visibleButtons.map((text) => text.trim()).filter(Boolean).slice(0, 12).join('|') || 'none'}`,
  );
};

const refreshTmsAuthorization = async (
  targetPage,
  browserContext,
  orderNumber,
  authorizationError,
) => {
  writeProgress({
    step: 'tms-oms-query-authorization-recovering',
    tmsOmsQueryAuthorizationRecovery: {
      orderNumber,
      status: 'clearing-current-tms-session',
      httpStatus: authorizationError.httpStatus,
      responseUrl: authorizationError.responseUrl,
      startedAt: new Date().toISOString(),
    },
    manualReview: null,
    error: null,
  });
  updateAuthHealth('tms', 'expired', targetPage, {
    stage: 'tms-oms-query-authorization-recovery',
    confidence: 'confirmed',
    source: 'controlled-tms-api-response',
    evidence: `http-${authorizationError.httpStatus}`,
  });

  await targetPage.evaluate(() => {
    window.localStorage.clear();
    window.sessionStorage.clear();
  }).catch(() => {});
  const tmsCookies = await browserContext.cookies([tmsBaseUrl]).catch(() => []);
  for (const cookie of tmsCookies) {
    await browserContext.clearCookies({
      name: cookie.name,
      domain: cookie.domain,
      path: cookie.path,
    });
  }
  await navigateSystemPage(targetPage, tmsLoginUrl, 'recover-tms-api-authorization');
  await ensureTmsLoginOnce(targetPage, browserContext);
  await openTmsCustomerRegistration(targetPage, browserContext);
  writeProgress({
    step: 'tms-oms-query-authorization-retry-ready',
    tmsOmsQueryAuthorizationRecovery: {
      ...readProgress().tmsOmsQueryAuthorizationRecovery,
      status: 'session-refreshed',
      refreshedAt: new Date().toISOString(),
    },
    error: null,
  });
  return targetPage;
};

const runTmsWorkflow = async (targetPage, browserContext, orderNumber, {
  allowConditionalScenario = false,
  formDecisionOverride = null,
  effectStage = 'create-ticket',
  ignoreUnrelatedExistingTickets = false,
} = {}) => {
  let progress = readProgress();
  const { scenarioCode } = currentScenarioIdentityForOrder(orderNumber, { persist: true });
  if (!scenarioRequiresTms(scenarioCode) && !allowConditionalScenario) {
    return skipTmsForAbnormalNetwork(orderNumber);
  }
  const conditionalLogisticsReadable = allowConditionalScenario
    && progress.ordinaryScenarioFacts?.bodyText
    && progress.logisticsAnalysis?.orderNumber === orderNumber;
  if (!hasCompleteLogisticsAnalysis(progress.logisticsAnalysis, orderNumber)
    && !conditionalLogisticsReadable) {
    await pauseForTransientRetry(
      targetPage,
      'tms-input-validation',
      'PDD_LOGISTICS_ANALYSIS_TEMPORARILY_UNAVAILABLE',
      '拼多多物流时间线或阶段分析不完整',
    );
  }
  if (!hasCompleteOmsAnalysis(progress.omsAnalysis, orderNumber)) {
    await pauseForTransientRetry(
      targetPage,
      'tms-input-validation',
      'OMS_ANALYSIS_TEMPORARILY_UNAVAILABLE',
      'OMS 发货仓库或低值品结果不完整',
    );
  }
  await ensureOmsWarehouseMutationAllowed(targetPage, orderNumber, 'TMS 建单或拼多多后续提交');
  progress = readProgress();

  const routingDecision = allowConditionalScenario
    ? {
        status: 'eligible',
        orderNumber,
        warehouse: progress.omsAnalysis.shippingWarehouse,
        carrier: progress.logisticsAnalysis.carrier,
        route: 'tms-public-flow',
        reason: '新增普通工单按统一 TMS 公共物流链路处理',
      }
    : decideTmsRouting({
        orderNumber,
        warehouse: progress.omsAnalysis.shippingWarehouse,
        carrier: progress.logisticsAnalysis.carrier,
      });
  writeProgress({ tmsRoutingDecision: routingDecision });
  if (routingDecision.status !== 'eligible') {
    await pauseForManualReview(targetPage, 'tms-routing', routingDecision.reason, { tmsRoutingDecision: routingDecision });
  }

  const formDecision = formDecisionOverride || decideTmsForm({
    orderNumber,
    logisticsAnalysis: progress.logisticsAnalysis,
    omsAnalysis: progress.omsAnalysis,
    scenarioCode,
  });
  writeProgress({ tmsFormDecision: formDecision });
  if (formDecision.status !== 'ready') {
    await pauseForManualReview(targetPage, 'tms-form-decision', formDecision.reason, { tmsFormDecision: formDecision });
  }

  if (progress.tmsWorkOrder?.status === 'created'
    && progress.tmsWorkOrder.orderNumber === orderNumber
    && (!allowConditionalScenario || progress.tmsWorkOrder.effectStage === effectStage)
    && progress.tmsEvidenceScreenshot?.status === 'ready'
    && progress.pddEvidenceScreenshot?.status === 'deleted'
    && hasConsumableTmsEvidence(progress, orderNumber)) {
    initializeTmsEvidenceDisposition(
      orderNumber,
      progress.tmsWorkOrder,
      progress.tmsEvidenceScreenshot,
    );
    logRunStep('awaiting-pdd-resolution', { error: null });
    return progress.tmsWorkOrder;
  }

  await openTmsCustomerRegistration(targetPage, browserContext);
  progress = readProgress();
  let workOrder = progress.tmsWorkOrder?.status === 'created'
    && progress.tmsWorkOrder.orderNumber === orderNumber
    && (!allowConditionalScenario || progress.tmsWorkOrder.effectStage === effectStage)
    ? progress.tmsWorkOrder
    : null;
  if (!workOrder) resolveReadyEvidenceScreenshot(orderNumber, progress);
  let rowSelection = await selectKnownTmsRow(targetPage, orderNumber, workOrder);
  if (workOrder && rowSelection.row) {
    const existing = await identifyExistingTmsTicket(rowSelection, orderNumber, progress, {
      allowMissingExpectedLogistics: allowConditionalScenario,
      allowReadableUnmappedValues: allowConditionalScenario
        || routingDecision.precedence === 'fallback-intercept-return',
      formDecision,
      knownTicket: workOrder,
    });
    const ticketIdentityMismatch = hasConflictingTmsTicketIdentity({
      savedTicketId: workOrder.ticketId,
      savedTicketNo: workOrder.ticketNo,
      visibleTicketId: existing.ticketId,
      visibleTicketNo: existing.ticketNo,
    });
    const visibleTicketRebindAllowed = ticketIdentityMismatch && canRebindToVisibleTmsTicket({
      existingStatus: existing.status,
      candidateCount: rowSelection.count,
      selectionStrategy: rowSelection.selectionStrategy,
      savedTicketId: workOrder.ticketId,
      savedTicketNo: workOrder.ticketNo,
      visibleTicketId: existing.ticketId,
      visibleTicketNo: existing.ticketNo,
    });
    if (existing.status !== 'matched' || (ticketIdentityMismatch && !visibleTicketRebindAllowed)) {
      await pauseForManualReview(targetPage, 'tms-ticket-recovery', existing.reason || '已保存 TMS 工单标识与页面记录不一致', {
        tmsDuplicateCheck: { ...existing, orderNumber, checkedAt: new Date().toISOString() },
      });
      if (verificationWait.status === 'yielded') {
        const current = readProgress();
        writeProgress({
          step: 'human-verification-required',
          verificationFocus: {
            ...(current.verificationFocus || {}),
            status: 'yielded',
            yieldedAt: new Date().toISOString(),
            heldMs: verificationWait.heldMs,
            reason: 'queued-verification-fairness',
          },
          error: null,
        });
        console.log(`[人工验证轮转] 当前店铺已获得 ${Math.round(verificationWait.heldMs / 1000)} 秒稳定前台时间，仍有其他店铺排队，已释放焦点并进入下一轮。阶段: ${stage}`);
      }
    }
    const previousTicket = visibleTicketRebindAllowed ? {
      ticketId: workOrder.ticketId || null,
      ticketNo: workOrder.ticketNo || null,
    } : null;
    workOrder = {
      ...workOrder,
      ticketId: existing.ticketId,
      ticketNo: existing.ticketNo,
      existingDecisionComparison: existing.decisionComparison || null,
      ...(visibleTicketRebindAllowed ? {
        recovered: true,
        reboundAt: new Date().toISOString(),
        previousTicket,
      } : {}),
    };
    writeProgress({
      tmsWorkOrder: workOrder,
      tmsDuplicateCheck: {
        ...existing,
        ...(visibleTicketRebindAllowed ? {
          recovery: 'unique-visible-ticket-rebound',
          previousTicket,
        } : {}),
      },
    });
  }
  if (!workOrder && rowSelection.count > 0 && !ignoreUnrelatedExistingTickets) {
    const existing = await identifyExistingTmsTicket(rowSelection, orderNumber, progress, {
      allowMissingExpectedLogistics: allowConditionalScenario,
      allowReadableUnmappedValues: allowConditionalScenario
        || routingDecision.precedence === 'fallback-intercept-return',
      formDecision,
    });
    if (existing.status === 'unrelated') {
      writeProgress({
        step: 'tms-unrelated-existing-ticket-ignored',
        tmsDuplicateCheck: { ...existing, orderNumber, checkedAt: new Date().toISOString() },
      });
      rowSelection = { ...rowSelection, row: null };
    } else if (existing.status !== 'matched') {
      await pauseForManualReview(targetPage, 'tms-duplicate-check', existing.reason, {
        tmsDuplicateCheck: { ...existing, orderNumber, checkedAt: new Date().toISOString() },
      });
    } else {
      workOrder = {
        shopId,
        orderNumber,
        status: 'created',
        effectStage,
        ticketId: existing.ticketId,
        ticketNo: existing.ticketNo,
        problemType: formDecision.problemType,
        customerRemark: formDecision.customerRemark,
        existingDecisionComparison: existing.decisionComparison || null,
        existingWarehouseReconciliation: existing.warehouseReconciliation || null,
        createdAt: readProgress().tmsWorkOrder?.createdAt || new Date().toISOString(),
        recovered: true,
        error: null,
      };
      writeProgress({ step: 'tms-existing-ticket-reused', tmsWorkOrder: workOrder, tmsDuplicateCheck: existing });
      rowSelection = { ...rowSelection, row: existing.row };
    }
  }
  if (workOrder && !rowSelection.row) {
    await pauseForManualReview(targetPage, 'tms-ticket-recovery', '已保存的 TMS 工单标识无法与列表中的唯一行对应');
  }

  if (!workOrder) {
    let dialog = await openTmsNewTicketDialog(targetPage, browserContext);

    const allowReadableUnmappedValues = allowConditionalScenario
      || routingDecision.precedence === 'fallback-intercept-return';
    const autofillOptions = {
      allowReadableUnmappedValues,
      allowMissingExpectedLogistics: allowConditionalScenario
        || !normalizeBusinessText(progress.logisticsAnalysis.carrier),
    };
    let autofill = null;
    for (let authorizationAttempt = 1; authorizationAttempt <= 2 && !autofill; authorizationAttempt++) {
      try {
        autofill = await verifyTmsAutofill(
          targetPage,
          dialog,
          orderNumber,
          progress.logisticsAnalysis,
          progress.omsAnalysis,
          autofillOptions,
        );
      } catch (error) {
        if (!(error instanceof TmsOmsQueryAuthorizationError)) throw error;
        if (authorizationAttempt >= 2) {
          throw new LogisticsRetryRequiredError(
            'tms-oms-query-authorization-transient',
            `${error.message}，自动刷新 TMS 登录态后仍未恢复`,
            tmsOmsQueryRetryAfterMs,
            {
              transientSystem: 'TMS',
              httpStatus: error.httpStatus,
              externalEffectStatus: 'failed',
              externalEffectReceipt: {
                clickAttempted: false,
                reason: 'tms-oms-query-authorization-recovery-exhausted',
                httpStatus: error.httpStatus,
              },
            },
          );
        }
        try {
          await refreshTmsAuthorization(targetPage, browserContext, orderNumber, error);
          dialog = await openTmsNewTicketDialog(targetPage, browserContext);
        } catch (recoveryError) {
          throw new LogisticsRetryRequiredError(
            'tms-oms-query-authorization-transient',
            `${error.message}，TMS 登录态自动刷新未完成: ${recoveryError.message}`,
            tmsOmsQueryRetryAfterMs,
            {
              transientSystem: 'TMS',
              httpStatus: error.httpStatus,
              externalEffectStatus: 'failed',
              externalEffectReceipt: {
                clickAttempted: false,
                reason: 'tms-oms-query-authorization-recovery-failed',
                httpStatus: error.httpStatus,
                recoveryError: recoveryError.message,
              },
            },
          );
        }
      }
    }
    if (readProgress().tmsOmsQueryAuthorizationRecovery?.status === 'session-refreshed') {
      writeProgress({
        tmsOmsQueryAuthorizationRecovery: {
          ...readProgress().tmsOmsQueryAuthorizationRecovery,
          status: 'succeeded',
          recoveredAt: new Date().toISOString(),
        },
      });
    }
    if (autofill.conflicts.length) {
      await pauseForManualReview(targetPage, 'tms-autofill-verification', autofill.conflicts.join('；'), {
        tmsAutofillVerification: autofill,
      });
    }
    writeProgress({
      tmsAutofillVerification: autofill,
      tmsFormDecision: { ...formDecision, autoFilledFields: autofill.actual },
    });

    const previousTransfer = readProgress().tmsAttachmentTransfer;
    const recoveredTransfer = await recoverTmsAttachmentFromVisibleThumbnail(
      dialog,
      orderNumber,
      previousTransfer,
    );
    if (!recoveredTransfer) {
      await uploadPddEvidenceToTms(targetPage, dialog, orderNumber);
    }
    workOrder = await createTmsTicket(targetPage, dialog, orderNumber, formDecision, {
      effectStage,
      stepPrefix: allowConditionalScenario ? 'ordinary-tms-ticket' : 'tms-ticket',
      requestContext: allowConditionalScenario ? { scenarioCode, effectStage } : null,
    });
    const cancel = await firstVisible([
      dialog.getByRole('button', { name: '取消', exact: true }),
      dialog.locator('.el-dialog__headerbtn'),
    ]);
    if (cancel) await pacedAction(targetPage, 'close-tms-new-dialog', () => cancel.click());
    rowSelection = await selectKnownTmsRow(targetPage, orderNumber, workOrder);
    if (!rowSelection.row) {
      const retryAt = new Date(Date.now() + tmsCreatedRowRetryAfterMs).toISOString();
      const reason = 'TMS_CREATED_ROW_NOT_VISIBLE: 创建成功后等待并刷新仍未显示唯一客服登记行';
      writeProgress({
        step: 'tms-created-row-retry-ready',
        tmsCreatedRowVisibility: {
          ...(readProgress().tmsCreatedRowVisibility || {}),
          orderNumber,
          ticketId: workOrder.ticketId || null,
          ticketNo: workOrder.ticketNo || null,
          status: 'retry-ready',
          attempts: rowSelection.attempts,
          refreshAttempts: rowSelection.refreshAttempts,
          lastObservedCount: rowSelection.count,
          retryAfterMs: tmsCreatedRowRetryAfterMs,
          retryAt,
          checkedAt: new Date().toISOString(),
        },
        manualReview: null,
        error: reason,
      });
      const retryable = new Error(reason);
      retryable.code = 'TMS_CREATED_ROW_NOT_VISIBLE';
      throw retryable;
    }
  }

  let tmsEvidence = readProgress().tmsEvidenceScreenshot;
  if (!(tmsEvidence?.status === 'ready'
    && tmsEvidence.orderNumber === orderNumber
    && tmsEvidence.ticketId === workOrder.ticketId
    && hasConsumableTmsEvidence(readProgress(), orderNumber))) {
    tmsEvidence = await captureTmsRowEvidence(targetPage, rowSelection.row, orderNumber, workOrder, {
      rowSelection,
    });
  }
  initializeTmsEvidenceDisposition(orderNumber, workOrder, tmsEvidence);
  if (readProgress().pddEvidenceScreenshot?.status === 'ready') {
    consumePddEvidenceAfterTmsSuccess(orderNumber, workOrder, tmsEvidence);
  } else if (readProgress().pddEvidenceScreenshot?.status !== 'deleted') {
    throw new Error('拼多多截图状态异常，无法确认 TMS 阶段清理结果');
  }
  await persistBrowserAuth(browserContext);
  logRunStep('awaiting-pdd-resolution', {
    error: null,
    currentUrl: targetPage.url(),
    tmsWorkOrder: workOrder,
    tmsEvidenceScreenshot: tmsEvidence,
  });
  console.log(JSON.stringify({
    TMS准入: routingDecision.status,
    TMS物流问题: formDecision.problemType,
    TMS客服备注: formDecision.customerRemark,
    TMS工单号: workOrder.ticketNo,
    TMS截图: tmsEvidence.relativePath,
  }, null, 2));
  return workOrder;
};

const readPddResolutionState = async (targetPage, orderNumber, { timeoutMs = 30000 } = {}) => {
  await targetPage.waitForLoadState('domcontentloaded', { timeout: 30000 }).catch(() => {});
  const bodyText = await targetPage.locator('body').innerText({ timeout: timeoutMs });
  const mainText = await targetPage.locator('main').innerText({ timeout: timeoutMs }).catch(() => bodyText);
  // The order card is rendered outside <main> on completed details. Use the
  // combined visible page text so completion recovery does not lose the order
  // number or status shown in the right-hand panel.
  const observedPlatformWorkOrderId = parsePlatformWorkOrderId(targetPage.url());
  return {
    ...parsePddResolutionStateText(`${mainText}\n${bodyText}`, orderNumber),
    ...(observedPlatformWorkOrderId ? { observedPlatformWorkOrderId } : {}),
  };
};

const waitForPddResolutionDetail = async (targetPage, orderNumber, {
  readTimeoutMs = 30000,
  settleMs = Math.max(pddDetailSettleMs, 15000),
} = {}) => {
  const deadline = Date.now() + settleMs;
  let state = await readPddResolutionState(targetPage, orderNumber, { timeoutMs: readTimeoutMs });
  while (!state.detailReady && Date.now() < deadline) {
    await targetPage.waitForTimeout(250);
    state = await readPddResolutionState(targetPage, orderNumber, { timeoutMs: readTimeoutMs });
  }
  return state;
};

const ensurePddResolutionDetailReady = async (targetPage, orderNumber, progress, {
  allowUnresolved = false,
  readTimeoutMs = 30000,
  settleMs = Math.max(pddDetailSettleMs, 15000),
} = {}) => {
  let state = await waitForPddResolutionDetail(targetPage, orderNumber, { readTimeoutMs, settleMs });
  if (state.detailReady && state.orderMatches) return assertPddDetailWorkOrderType(state);

  const recoveryUrl = progress.detailUrl || targetPage.url();
  if (targetPage.url().includes('mms.pinduoduo.com/login')) {
    await ensurePddLogin(targetPage, context, recoveryUrl);
    state = await waitForPddResolutionDetail(targetPage, orderNumber, { readTimeoutMs, settleMs });
    if (state.detailReady && state.orderMatches) return assertPddDetailWorkOrderType(state);
  }

  // A detail route can commit while its React/Vue content is still empty. One
  // reload of the saved URL is enough to recover a stale renderer; never loop
  // reloads because that can trigger PDD rate limiting.
  if (isPddDetailUrl(recoveryUrl)) {
    await saveWorkflowDiagnostics(targetPage, 'pdd-resolution-detail-loading').catch(() => {});
    writeProgress({
      step: 'pdd-resolution-detail-recovering',
      pddResolutionDetailRecovery: {
        orderNumber,
        recoveryUrl,
        attemptedAt: new Date().toISOString(),
      },
    });
    await pacedAction(targetPage, 'recover-pdd-resolution-detail', async () => {
      if (targetPage.url() === recoveryUrl) {
        await targetPage.reload({ waitUntil: 'commit', timeout: 90000 });
        await targetPage.waitForLoadState('domcontentloaded', { timeout: 30000 }).catch(() => {});
        return targetPage;
      }
      return navigateSystemPage(targetPage, recoveryUrl, 'recover-pdd-resolution-detail');
    }, { retryOnRateLimit: true });
    if (targetPage.url().includes('mms.pinduoduo.com/login')) {
      await ensurePddLogin(targetPage, context, recoveryUrl);
    }
    state = await waitForPddResolutionDetail(targetPage, orderNumber, { readTimeoutMs, settleMs });
  }
  if (!state.detailReady || !state.orderMatches) {
    if (allowUnresolved) return { ...state, readFailed: true };
    const reason = state.detailLoadingReason
      || (state.orderNumber ? `页面订单号 ${state.orderNumber} 与当前订单 ${orderNumber} 不一致` : '详情页未读取到订单号');
    await pauseForTransientRetry(targetPage, 'pdd-resolution-detail-loading', 'PDD_DETAIL_TEMPORARILY_UNAVAILABLE', reason, {
      pddResolutionDetail: {
        orderNumber,
        state,
        checkedAt: new Date().toISOString(),
      },
    });
  }
  return assertPddDetailWorkOrderType(state);
};

const waitForPddSubmitTransition = async (targetPage, stage, inspect) => {
  const deadline = Date.now() + pddSubmitSettleMs;
  do {
    await checkForHumanVerification(targetPage, `wait-submit-transition-${stage}`);
    if (await inspect().catch(() => false)) return true;
    const remainingMs = deadline - Date.now();
    if (remainingMs <= 0) return false;
    await targetPage.waitForTimeout(Math.min(500, remainingMs));
  } while (Date.now() < deadline);
  return false;
};

const nonRetryableManualReviewStages = new Set([
  'ordinary-scenario-manual-review',
  'ordinary-scenario-submit',
  'ordinary-scenario-evidence-upload',
  'ordinary-scenario-external-action',
  'in-transit-address-change-completion-unverified',
  'pdd-resolution-validation',
  'pdd-resolution-detail-loading',
  'pdd-resolution-decision',
  'pdd-resolution-state',
  'pdd-resolution-submit',
  'pdd-resolution-submit-confirmation',
  'pdd-resolution-rejected-absent-from-pending',
  'pdd-resolution-result',
  'pdd-resolution-outcome-mismatch',
  'pdd-order-remark',
  'oms-warehouse-out-of-scope',
  'oms-manual-allocation',
  'tms-routing',
  'tms-form-decision',
  'tms-duplicate-check',
  'tms-ticket-recovery',
  'tms-created-row-verification',
  'tms-autofill-verification',
]);

const blockManualReview = (error) => {
  const current = readProgress();
  writeProgress({
    step: 'manual-review-blocked',
    manualReview: {
      ...(current.manualReview || {}),
      status: 'blocked',
      stage: error.stage || current.manualReview?.stage || null,
      reason: error.message,
      blockedAt: new Date().toISOString(),
      lastRetryAt: null,
    },
    error: null,
  });
};

const uniqueVisibleElement = async (locator, description, { required: isRequired = true } = {}) => {
  const visible = [];
  const count = await locator.count().catch(() => 0);
  for (let index = 0; index < count; index++) {
    const candidate = locator.nth(index);
    if (await candidate.isVisible().catch(() => false)) visible.push(candidate);
  }
  if (!visible.length && !isRequired) return null;
  if (visible.length !== 1) {
    throw new Error(`${description} 可见控件数量应为 1，实际为 ${visible.length}`);
  }
  return visible[0];
};

const isPddOptionSelected = async (scope, label) => {
  const accessibleRadios = scope.getByRole('radio', { name: new RegExp(`${escapeRegex(label)}\\s*$`) });
  for (let index = 0; index < await accessibleRadios.count().catch(() => 0); index++) {
    if (await accessibleRadios.nth(index).isChecked().catch(() => false)) return true;
  }
  const rawRadios = scope.locator('input[type="radio"], [role="radio"]');
  for (let index = 0; index < await rawRadios.count().catch(() => 0); index++) {
    const radio = rawRadios.nth(index);
    const matchesLabel = await radio.evaluate((element, expectedLabel) => {
      const normalize = (value) => String(value || '')
        .normalize('NFKC')
        .replace(/[\s，,。；;：:、]/gu, '')
        .trim();
      const expected = normalize(expectedLabel);
      let current = element;
      for (let depth = 0; current && depth < 6; depth++, current = current.parentElement) {
        if (normalize(current.innerText) === expected) return true;
      }
      return false;
    }, label).catch(() => false);
    if (!matchesLabel) continue;
    if (await radio.isChecked().catch(() => false)) return true;
    if (await radio.getAttribute('aria-checked').catch(() => null) === 'true') return true;
  }
  const option = await firstVisible([
    scope.locator('label').filter({ hasText: new RegExp(`^\\s*${escapeRegex(label)}\\s*$`) }),
    scope.getByText(label, { exact: true }),
  ]) || await findNormalizedOrdinaryPddOption(scope, label);
  if (!option) return false;
  return option.evaluate((element, expectedLabel) => {
    const normalize = (value) => String(value || '')
      .normalize('NFKC')
      .replace(/[\s，,。；;：:、]/gu, '')
      .trim();
    const expected = normalize(expectedLabel);
    let current = element;
    for (let depth = 0; current && depth < 6; depth++, current = current.parentElement) {
      if (normalize(current.innerText) !== expected) continue;
      const control = current.matches('input[type="radio"], [role="radio"]')
        ? current
        : current.querySelector('input[type="radio"], [role="radio"]');
      if (control) return control.checked === true || control.getAttribute('aria-checked') === 'true';
      if (current.getAttribute('aria-checked') === 'true') return true;
      if (/(?:^|[-_\s])(?:checked|selected)(?:$|[-_\s])/i.test(String(current.className || ''))) return true;
    }
    return false;
  }, label).catch(() => false);
};

const selectPddRadioOnce = async (targetPage, scope, label, { required: isRequired = true } = {}) => {
  const roleRadio = scope.getByRole('radio', { name: new RegExp(`${escapeRegex(label)}\\s*$`) });
  const radioCount = await roleRadio.count().catch(() => 0);
  let visibleRadioCount = 0;
  for (let index = 0; index < radioCount; index++) {
    if (await roleRadio.nth(index).isVisible().catch(() => false)) visibleRadioCount++;
  }
  if (visibleRadioCount) {
    const radio = await uniqueVisibleElement(roleRadio, `拼多多“${label}”`, { required: isRequired });
    if (!radio) return false;
    if (!await radio.isChecked().catch(() => false)) {
      await radio.scrollIntoViewIfNeeded().catch(() => {});
      await pacedAction(targetPage, `select-pdd-${label}`, () => radio.click({ timeout: 8_000 }));
    }
    if (!await radio.isChecked().catch(() => false)) {
      throw new Error(`拼多多“${label}”选择后未保持选中状态`);
    }
    return true;
  }

  // Some PDD versions render custom option cards without role="radio". Use
  // the exact visible label as a DOM fallback and accept the custom checked
  // state instead of treating the missing ARIA role as an empty form.
  const textCandidates = [
    scope.locator('label').filter({ hasText: new RegExp(`^\\s*${escapeRegex(label)}\\s*$`) }),
    scope.getByText(label, { exact: true }),
  ];
  let option = await firstVisible(textCandidates)
    || await findNormalizedOrdinaryPddOption(scope, label);
  if (!option) return false;
  const tagName = await option.evaluate((element) => element.tagName.toLowerCase()).catch(() => '');
  const inputType = await option.getAttribute('type').catch(() => null);
  await option.scrollIntoViewIfNeeded().catch(() => {});
  let selected = false;
  let lastError = null;
  for (let attempt = 0; attempt < 2 && !selected; attempt += 1) {
    try {
      await pacedAction(targetPage, `select-pdd-${label}`, () => (
        tagName === 'input' && inputType === 'radio'
          ? option.check({ timeout: 8_000 })
          : option.click({ timeout: 8_000 })
      ));
    } catch (error) {
      if (error instanceof HumanVerificationRequiredError
        || error instanceof PddLoginRequiredError
        || error instanceof RateLimitPauseError) throw error;
      lastError = error;
      // The card can be replaced during async rendering. Re-resolve the live
      // visible option before the bounded retry instead of force-clicking a
      // detached/covered node.
      const refreshed = await firstVisible(textCandidates)
        || await findNormalizedOrdinaryPddOption(scope, label);
      if (refreshed) {
        option = refreshed;
        await option.scrollIntoViewIfNeeded().catch(() => {});
      }
    }
    await targetPage.waitForTimeout(350);
    selected = await isPddOptionSelected(scope, label);
  }
  if (!selected) {
    throw lastError || new Error(`拼多多“${label}”选择后未保持选中状态`);
  }
  return true;
};

const waitForPddOptionSelected = async (targetPage, scope, label, timeoutMs = 2500) => {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    if (await isPddOptionSelected(scope, label)) {
      await targetPage.waitForTimeout(500);
      if (await isPddOptionSelected(scope, label)) return true;
    }
    await targetPage.waitForTimeout(250);
  }
  return false;
};

const findMatchingPddRadio = async (scope, label) => {
  const radios = scope.locator('input[type="radio"], [role="radio"]');
  const count = await radios.count().catch(() => 0);
  for (let index = 0; index < count; index++) {
    const radio = radios.nth(index);
    const matches = await radio.evaluate((element, expectedLabel) => {
      const normalize = (value) => String(value || '')
        .normalize('NFKC')
        .replace(/[\s，,。；;：:、]/gu, '')
        .trim();
      const expected = normalize(expectedLabel);
      let current = element;
      for (let depth = 0; current && depth < 6; depth++, current = current.parentElement) {
        if (normalize(current.innerText) === expected) return true;
      }
      return false;
    }, label).catch(() => false);
    if (matches && await radio.isVisible().catch(() => false)) return radio;
  }
  return null;
};

const selectPddRadio = async (targetPage, scope, label, { required: isRequired = true } = {}) => {
  let optionFound = false;
  let lastError = null;
  for (let attempt = 1; attempt <= 3; attempt++) {
    await checkForHumanVerification(targetPage, `select-pdd-${label}-attempt-${attempt}`);
    if (await waitForPddOptionSelected(targetPage, scope, label, 750)) return true;
    try {
      if (attempt === 1) {
        const selected = await selectPddRadioOnce(targetPage, scope, label, { required: false });
        optionFound ||= selected;
      } else if (attempt === 2) {
        const option = await firstVisible([
          scope.locator('label').filter({ hasText: new RegExp(`^\\s*${escapeRegex(label)}\\s*$`) }),
          scope.getByText(label, { exact: true }),
        ]);
        if (option) {
          optionFound = true;
          await pacedAction(targetPage, `reselect-pdd-label-${label}`, () => option.click({ force: true }));
        }
      } else {
        const radio = await findMatchingPddRadio(scope, label);
        if (radio) {
          optionFound = true;
          const tagName = await radio.evaluate((element) => element.tagName.toLowerCase()).catch(() => '');
          await pacedAction(targetPage, `reselect-pdd-control-${label}`, () => (
            tagName === 'input' ? radio.check({ force: true }) : radio.click({ force: true })
          ));
        }
      }
    } catch (error) {
      if (error instanceof HumanVerificationRequiredError
        || error instanceof PddLoginRequiredError
        || error instanceof RateLimitPauseError) throw error;
      optionFound = true;
      lastError = error;
    }
    if (await waitForPddOptionSelected(targetPage, scope, label)) {
      if (attempt > 1) console.log(`[PDD选项自动恢复] “${label}”第 ${attempt} 次选择成功`);
      return true;
    }
    if (attempt < 3) await targetPage.waitForTimeout(500);
  }
  if (!optionFound || !isRequired) return false;
  throw new Error(`拼多多“${label}”自动选择 3 次后仍未保持选中状态${lastError?.message ? `：${lastError.message}` : ''}`);
};

const waitForPddOption = async (targetPage, scope, label, timeoutMs = 45000) => {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    await checkForHumanVerification(targetPage, `wait-option-${label}`);
    // PDD can show a blocking "页面停留时间过长" modal after the detail
    // page has already rendered. Its central refresh action is the safe
    // recovery path; a normal option lookup cannot reach the underlying
    // controls while the modal backdrop is present. Re-locate the option
    // after the in-place refresh instead of treating the page as missing
    // the requested logistics choice.
    const stalePageRefresh = await clickVisiblePddStalePageRefresh(targetPage, {
      cooldownMs: 3_000,
      settleMs: 700,
    }).catch(() => ({ handled: false }));
    if (stalePageRefresh.handled) {
      logRunStep('pdd-option-stale-page-refresh-clicked', {
        label,
        beforeUrl: stalePageRefresh.beforeUrl,
        afterUrl: stalePageRefresh.afterUrl,
      });
      continue;
    }
    if (await selectPddRadio(targetPage, scope, label, { required: false })) return true;
    await targetPage.waitForTimeout(1000);
  }
  return false;
};

const selectPddSubjectiveRefundFallback = async (targetPage, timeoutMs = 30000) => {
  const deadline = Date.now() + timeoutMs;
  let lastError = null;
  do {
    await checkForHumanVerification(targetPage, 'select-subjective-refund-fallback');
    const scopes = [
      targetPage.locator('main'),
      targetPage.locator('body'),
      ...targetPage.frames()
        .filter((frame) => frame !== targetPage.mainFrame())
        .map((frame) => frame.locator('body')),
    ];
    for (const scope of scopes) {
      const visibleOptions = [];
      for (const option of pddSubjectiveRefundFallbackOutcomeGroup) {
        if (await visibleExactText(scope, option).catch(() => false)) visibleOptions.push(option);
      }
      const fallbackOutcome = resolvePddSubjectiveRefundFallbackOutcome(visibleOptions);
      if (!fallbackOutcome) continue;
      try {
        if (await selectPddRadio(targetPage, scope, fallbackOutcome, { required: false })
          && await waitForPddOptionSelected(targetPage, scope, fallbackOutcome, 2500)) {
          return fallbackOutcome;
        }
      } catch (error) {
        lastError = error;
      }
    }
    const remainingMs = deadline - Date.now();
    if (remainingMs > 0) await targetPage.waitForTimeout(Math.min(500, remainingMs));
  } while (Date.now() < deadline);
  if (lastError) throw lastError;
  return null;
};

const isPddNetworkTarget = (url) => {
  try {
    const hostname = new URL(url).hostname;
    return hostname === 'mms.pinduoduo.com' || hostname.endsWith('.pinduoduo.com');
  } catch {
    return false;
  }
};

const isLikelyPddBusinessSubmit = (candidate = {}) => (
  String(candidate.url || '').includes('/latitude/mallTicket/submitForm')
  || (/(?:mall.?ticket|work.?order|aftersale|ticket)/iu.test(String(candidate.url || ''))
    && /(?:submit|confirm|handle|process|result|deal)/iu.test(String(candidate.url || '')))
);

const readPddSubmitUiFeedback = async (targetPage) => {
  const feedback = [];
  const seen = new Set();
  const selector = [
    '[role="alert"]',
    '[role="status"]',
    '.beast-core-message',
    '.beast-core-toast',
    '.ant-message-notice',
    '.ant-notification-notice',
    '.ant-form-item-explain-error',
    '.el-message',
    '.el-form-item__error',
  ].join(', ');
  for (const frame of targetPage.frames()) {
    const candidates = frame.locator(selector);
    const count = Math.min(50, await candidates.count().catch(() => 0));
    for (let index = 0; index < count; index += 1) {
      const candidate = candidates.nth(index);
      if (!await candidate.isVisible().catch(() => false)) continue;
      const text = String(await candidate.innerText().catch(() => ''))
        .replace(/\s+/gu, ' ')
        .trim()
        .slice(0, 500);
      if (!text || seen.has(text)) continue;
      seen.add(text);
      feedback.push({
        text,
        frameKind: frame === targetPage.mainFrame() ? 'main' : 'child',
        frameUrl: String(frame.url() || '').slice(0, 1000),
      });
    }
  }
  return feedback;
};

const clickPddSubmit = async (
  targetPage,
  stage,
  orderNumber = readProgress().orderNumber,
  {
    guard = true,
    postcondition = null,
    beforeClick = null,
    settleUntil = null,
    selectedPddOption = null,
    requiredSelectedPddOptions = [],
    allowTrustedConfirmation = false,
  } = {},
) => {
  const action = async () => {
    const submit = await waitForPddSubmitButton(
      targetPage,
      stage,
      30000,
      { selectedPddOption },
    );
    const submitContext = readPddSubmitButtonContext(submit);
    writeProgress({
      pddSubmitButtonContext: {
        orderNumber,
        stage,
        selectedPddOption,
        ...(submitContext || {}),
        locatedAt: new Date().toISOString(),
      },
    });
    const selectionProof = await verifyPddSubmitSelections(
      targetPage,
      [selectedPddOption, ...requiredSelectedPddOptions],
      {
        stage,
        orderNumber,
        submitContext,
      },
    );
    if (beforeClick) await beforeClick();
    const observedRequests = [];
    const observedResponses = [];
    const failedRequests = [];
    const frameNavigations = [];
    const collectPddRequest = (request) => {
      if (!isPddNetworkTarget(request.url())) return;
      const method = request.method();
      const resourceType = request.resourceType();
      if (['GET', 'HEAD'].includes(method) && resourceType !== 'document') return;
      if (observedRequests.length >= 50) return;
      observedRequests.push({
        url: request.url().slice(0, 1000),
        method,
        resourceType,
        navigationRequest: request.isNavigationRequest(),
        requestBody: String(request.postData() || '').slice(0, 2000),
      });
    };
    const collectPddResponse = (response) => {
      const request = response.request();
      if (!isPddNetworkTarget(response.url())) return;
      if (['GET', 'HEAD'].includes(request.method()) && request.resourceType() !== 'document') return;
      if (observedResponses.length < 50) observedResponses.push(response);
    };
    const collectPddRequestFailure = (request) => {
      if (!isPddNetworkTarget(request.url()) || failedRequests.length >= 30) return;
      failedRequests.push({
        url: request.url().slice(0, 1000),
        method: request.method(),
        resourceType: request.resourceType(),
        navigationRequest: request.isNavigationRequest(),
        requestBody: String(request.postData() || '').slice(0, 2000),
        failure: request.failure()?.errorText || 'unknown request failure',
      });
    };
    const collectPddFrameNavigation = (frame) => {
      if (!isPddNetworkTarget(frame.url()) || frameNavigations.length >= 30) return;
      frameNavigations.push({
        frameKind: frame === targetPage.mainFrame() ? 'main' : 'child',
        url: String(frame.url() || '').slice(0, 1000),
        observedAt: new Date().toISOString(),
      });
    };
    targetPage.on('request', collectPddRequest);
    targetPage.on('response', collectPddResponse);
    targetPage.on('requestfailed', collectPddRequestFailure);
    targetPage.on('framenavigated', collectPddFrameNavigation);
    try {
      await pacedAction(targetPage, `submit-pdd-${stage}`, () => submit.click(), { retryOnRateLimit: true });
      const initialUiFeedback = await readPddSubmitUiFeedback(targetPage);
      let confirmationClicked = false;
      if (allowTrustedConfirmation && selectedPddOption) {
        const confirmationDeadline = Date.now() + 1000;
        do {
          const confirmation = await findTrustedPddSubmitConfirmation(
            targetPage,
            selectedPddOption,
            submitContext,
          );
          if (confirmation) {
            await pacedAction(
              targetPage,
              `confirm-pdd-${stage}`,
              () => confirmation.button.click(),
              { retryOnRateLimit: true },
            );
            confirmationClicked = true;
            writeProgress({
              pddSubmitConfirmation: {
                orderNumber,
                stage,
                selectedPddOption,
                frameUrl: confirmation.frameUrl,
                dialogText: confirmation.dialogText.slice(0, 1000),
                confirmedAt: new Date().toISOString(),
              },
            });
            break;
          }
          const remainingMs = confirmationDeadline - Date.now();
          if (remainingMs > 0) await targetPage.waitForTimeout(Math.min(100, remainingMs));
        } while (Date.now() < confirmationDeadline);
      }
      let transitionConfirmed = null;
      if (postcondition) await postcondition();
      else if (settleUntil) {
        transitionConfirmed = await waitForPddSubmitTransition(targetPage, stage, settleUntil);
      }
      else {
        const fallbackDelayMs = Math.min(actionDelayFor(targetPage, `pdd-submit-${stage}`), 1_000);
        if (fallbackDelayMs > 0) await targetPage.waitForTimeout(fallbackDelayMs);
      }
      await targetPage.waitForTimeout(500);
      const finalUiFeedback = await readPddSubmitUiFeedback(targetPage);
      const uiFeedback = [...initialUiFeedback];
      for (const entry of finalUiFeedback) {
        if (!uiFeedback.some((existing) => existing.text === entry.text
          && existing.frameUrl === entry.frameUrl)) uiFeedback.push(entry);
      }
      const responseCandidates = [];
      for (const response of observedResponses) {
        const request = response.request();
        const responseText = await response.text().catch(() => '');
        let responsePayload = null;
        try { responsePayload = JSON.parse(responseText); } catch { /* retain bounded raw text */ }
        responseCandidates.push({
          url: response.url().slice(0, 1000),
          httpStatus: response.status(),
          ok: response.ok(),
          method: request.method(),
          resourceType: request.resourceType(),
          navigationRequest: request.isNavigationRequest(),
          requestBody: String(request.postData() || '').slice(0, 2000),
          responseText: responseText.slice(0, 2000),
          responsePayload,
        });
      }
      const likelySubmitRequest = observedRequests.find(isLikelyPddBusinessSubmit) || null;
      const likelySubmitResponse = responseCandidates.find(isLikelyPddBusinessSubmit) || null;
      const likelySubmitFailure = failedRequests.find(isLikelyPddBusinessSubmit) || null;
      let submitReceipt = null;
      if (likelySubmitResponse) {
        const responsePayload = likelySubmitResponse.responsePayload;
        const explicitSuccess = responsePayload?.success === true
          || Number(responsePayload?.errorCode) === 0
          || Number(responsePayload?.error_code) === 0
          || Number(responsePayload?.code) === 0;
        const explicitFailure = responsePayload?.success === false
          || (responsePayload?.errorCode != null && Number(responsePayload.errorCode) !== 0)
          || (responsePayload?.error_code != null && Number(responsePayload.error_code) !== 0)
          || (responsePayload?.code != null && Number(responsePayload.code) !== 0);
        submitReceipt = {
          httpStatus: likelySubmitResponse.httpStatus,
          success: explicitSuccess,
          errorCode: responsePayload?.errorCode
            ?? responsePayload?.error_code
            ?? responsePayload?.code
            ?? null,
          errorMsg: responsePayload?.errorMsg
            || responsePayload?.error_msg
            || responsePayload?.message
            || responsePayload?.msg
            || null,
          responseText: likelySubmitResponse.responseText,
          requestUrl: likelySubmitResponse.url,
          clickAttempted: true,
          requestCaptured: true,
          responseCaptured: true,
        };
        if (!likelySubmitResponse.ok || explicitFailure) {
          throw new PddSubmitRejectedError(stage, submitReceipt);
        }
      } else if (likelySubmitRequest || likelySubmitFailure) {
        const requestEvidence = likelySubmitFailure || likelySubmitRequest;
        submitReceipt = {
          httpStatus: null,
          success: null,
          errorCode: null,
          errorMsg: likelySubmitFailure?.failure || null,
          responseText: null,
          requestUrl: requestEvidence.url,
          requestMethod: requestEvidence.method,
          resourceType: requestEvidence.resourceType,
          clickAttempted: true,
          requestCaptured: true,
          requestFailed: Boolean(likelySubmitFailure),
          responseCaptured: false,
        };
      }
      return {
        submitReceipt,
        transitionConfirmed,
        confirmationClicked,
        selectionProof,
        requestCandidates: observedRequests,
        requestFailures: failedRequests,
        frameNavigations,
        uiFeedback,
        responseCandidates: responseCandidates.map(({ responsePayload, ...candidate }) => candidate),
      };
    } finally {
      targetPage.off('request', collectPddRequest);
      targetPage.off('response', collectPddResponse);
      targetPage.off('requestfailed', collectPddRequestFailure);
      targetPage.off('framenavigated', collectPddFrameNavigation);
    }
  };
  if (!guard) return action();
  const result = await guardedExternalEffect({
    effectType: 'pdd-submit',
    orderNumber,
    stage,
    request: { stage, orderNumber },
  }, action);
  // An existing success receipt skips the click callback. Re-check the page
  // anyway so an old false-positive receipt cannot advance the workflow.
  if (postcondition && result?.alreadySucceeded) await postcondition();
  return result;
};

const waitForPddSubmitButton = async (
  targetPage,
  stage,
  timeoutMs = 30000,
  { selectedPddOption = null, allowDisabled = false } = {},
) => {
  const deadline = Date.now() + timeoutMs;
  let lastCount = 0;
  let lastCandidates = [];
  while (Date.now() < deadline) {
    if (!isPddDetailUrl(targetPage.url())) {
      throw new PddResolutionDetailContextLostError(stage, targetPage.url());
    }
    await checkForHumanVerification(targetPage, `wait-submit-${stage}`);
    // Match only real button elements. The same button is also exposed as a
    // role locator and a nested text node, so combining locator families made
    // one DOM node look like three ambiguous controls.
    const visibleCandidates = [];
    const preferredContext = selectedPddOption
      ? findOrdinaryPddSelectionContext(targetPage, selectedPddOption)
      : null;
    const currentFrames = targetPage.frames();
    const preferredFrameAttached = preferredContext?.frame
      && currentFrames.includes(preferredContext.frame);
    const orderedFrames = preferredFrameAttached
      ? [preferredContext.frame, ...currentFrames.filter((frame) => frame !== preferredContext.frame)]
      : currentFrames;
    for (const frame of orderedFrames) {
      const candidate = frame.locator('button').filter({
        hasText: /^\s*(?:提交|提交并完结|确认)\s*$/,
      });
      for (let index = 0; index < await candidate.count().catch(() => 0); index++) {
        const item = candidate.nth(index);
        if (!await item.isVisible().catch(() => false)) continue;
        const enabled = await item.isEnabled().catch(() => false);
        if (!enabled && !allowDisabled) continue;
        const relationships = await item.evaluate((element, expectedLabel) => {
          const normalize = (value) => String(value || '')
            .normalize('NFKC')
            .replace(/[\s，,。；;：:、]/gu, '')
            .trim();
          const expected = normalize(expectedLabel);
          let belongsToResolutionForm = false;
          let belongsToSelectedOptionForm = false;
          for (let depth = 0, current = element;
            current && depth < 12;
            depth += 1, current = current.parentElement) {
            if (current === element.ownerDocument.body
              || current === element.ownerDocument.documentElement) break;
            const controls = [...current.querySelectorAll('input[type="radio"], [role="radio"]')];
            if (controls.length) belongsToResolutionForm = true;
            if (!expected) continue;
            for (const control of controls) {
              const selected = control.checked === true
                || control.getAttribute('aria-checked') === 'true';
              if (!selected) continue;
              const associated = control.matches('input[type="radio"]')
                ? control.labels?.[0] || control.closest('label') || control.parentElement
                : control;
              const text = associated?.innerText
                || associated?.getAttribute?.('aria-label')
                || control.getAttribute('aria-label')
                || control.getAttribute('value');
              if (normalize(text) === expected) {
                belongsToSelectedOptionForm = true;
                break;
              }
            }
            if (belongsToSelectedOptionForm) break;
          }
          return { belongsToResolutionForm, belongsToSelectedOptionForm };
        }, selectedPddOption).catch(() => ({
          belongsToResolutionForm: false,
          belongsToSelectedOptionForm: false,
        }));
        const buttonText = String(await item.innerText().catch(() => '')).trim();
        visibleCandidates.push({
          item,
          frame,
          frameIndex: currentFrames.indexOf(frame),
          frameUrl: String(frame.url() || '').slice(0, 1000),
          frameKind: frame === targetPage.mainFrame() ? 'main' : 'child',
          preferredFrame: preferredFrameAttached && frame === preferredContext.frame,
          buttonText,
          enabled,
          ...relationships,
        });
      }
    }
    lastCount = visibleCandidates.length;
    lastCandidates = visibleCandidates.map(({ item, frame, ...candidate }) => candidate);
    const returnCandidate = (candidate, selectionMode) => {
      rememberPddSubmitButtonContext(candidate.item, {
        frameUrl: candidate.frameUrl,
        frameIndex: candidate.frameIndex,
        frameKind: candidate.frameKind,
        buttonText: candidate.buttonText,
        selectedPddOption,
        selectionMode,
        candidateCount: visibleCandidates.length,
      });
      return candidate.item;
    };
    const selectedFormButtons = visibleCandidates.filter(
      (candidate) => candidate.belongsToSelectedOptionForm,
    );
    if (selectedFormButtons.length) {
      const preferred = selectedFormButtons.filter((candidate) => candidate.preferredFrame);
      return returnCandidate((preferred.length ? preferred : selectedFormButtons).at(-1), 'selected-option-form');
    }
    if (selectedPddOption && preferredFrameAttached) {
      const preferredFormButtons = visibleCandidates.filter(
        (candidate) => candidate.preferredFrame && candidate.belongsToResolutionForm,
      );
      if (preferredFormButtons.length) {
        return returnCandidate(preferredFormButtons.at(-1), 'selected-option-frame-form');
      }
    }
    // Once an ordinary option has been selected, never fall back to an
    // unrelated main-document button. Wait for its own frame/form to render.
    if (!selectedPddOption) {
      const formButtons = visibleCandidates.filter((candidate) => candidate.belongsToResolutionForm);
      if (formButtons.length) return returnCandidate(formButtons.at(-1), 'resolution-form');
      const submitFallbackButtons = visibleCandidates.filter(
        (candidate) => candidate.enabled && candidate.buttonText !== '确认',
      );
      if (submitFallbackButtons.length === 1) {
        return returnCandidate(submitFallbackButtons[0], 'unique-submit-fallback');
      }
    }
    const state = await readPddResolutionState(targetPage, readProgress().orderNumber).catch(() => null);
    if (state?.isCompleted && state.orderMatches) {
      throw new PddWorkOrderAlreadyCompletedError(stage, state);
    }
    if (state?.detailReady && !state.orderMatches) {
      throw new PddResolutionDetailContextLostError(
        stage,
        targetPage.url(),
        state.orderNumber || null,
      );
    }
    await targetPage.waitForTimeout(1000);
  }
  writeProgress({
    pddSubmitButtonLookupFailure: {
      orderNumber: readProgress().orderNumber || null,
      stage,
      selectedPddOption,
      candidateCount: lastCount,
      candidates: lastCandidates,
      failedAt: new Date().toISOString(),
    },
  });
  await saveWorkflowDiagnostics(targetPage, `pdd-submit-button-${stage}-not-rendered`).catch(() => {});
  throw new PddSubmitButtonRenderError(stage, timeoutMs, lastCount);
};

const readSelectedPddOptionProof = async (targetPage, label) => {
  const expected = normalizeOrdinaryPddOptionText(label);
  if (!expected) return null;
  const frames = targetPage.frames();
  for (let frameIndex = 0; frameIndex < frames.length; frameIndex += 1) {
    const frame = frames[frameIndex];
    const controls = frame.locator('input[type="radio"], [role="radio"]');
    const count = Math.min(300, await controls.count().catch(() => 0));
    for (let index = 0; index < count; index += 1) {
      const control = controls.nth(index);
      const proof = await control.evaluate((element, expectedLabel) => {
        const normalize = (value) => String(value || '')
          .normalize('NFKC')
          .replace(/[\s，,。；;：:、]/gu, '')
          .trim();
        const associated = element.matches('input[type="radio"]')
          ? element.labels?.[0] || element.closest('label') || element.parentElement
          : element;
        const actualLabel = String(
          associated?.innerText
          || associated?.getAttribute?.('aria-label')
          || element.getAttribute('aria-label')
          || element.getAttribute('value')
          || '',
        ).replace(/\s+/gu, ' ').trim();
        const selected = element.checked === true
          || element.getAttribute('aria-checked') === 'true';
        if (!selected || normalize(actualLabel) !== expectedLabel) return null;
        const form = element.closest('form')
          || element.closest('[class*="form"], [class*="Form"]');
        return {
          requestedLabel: expectedLabel,
          actualLabel,
          tagName: element.tagName.toLowerCase(),
          role: element.getAttribute('role'),
          name: element.getAttribute('name'),
          value: element.getAttribute('value'),
          formId: form?.id || null,
          formClass: String(form?.className || '').slice(0, 300) || null,
        };
      }, expected).catch(() => null);
      if (!proof) continue;
      return {
        ...proof,
        requestedLabel: label,
        frameIndex,
        frameKind: frame === targetPage.mainFrame() ? 'main' : 'child',
        frameUrl: String(frame.url() || '').slice(0, 1000),
      };
    }
  }
  return null;
};

const verifyPddSubmitSelections = async (
  targetPage,
  labels,
  { stage, orderNumber, submitContext = null } = {},
) => {
  const requiredLabels = [...new Set(labels.map((label) => String(label || '').trim()).filter(Boolean))];
  if (!requiredLabels.length) return null;
  const selections = [];
  const missingLabels = [];
  const wrongFrameLabels = [];
  for (const label of requiredLabels) {
    const proof = await readSelectedPddOptionProof(targetPage, label);
    if (!proof) {
      missingLabels.push(label);
      continue;
    }
    if (Number.isInteger(submitContext?.frameIndex)
      && proof.frameIndex !== submitContext.frameIndex) {
      wrongFrameLabels.push(label);
    }
    selections.push(proof);
  }
  const audit = {
    orderNumber: orderNumber || readProgress().orderNumber || null,
    stage,
    requiredLabels,
    selections,
    missingLabels,
    wrongFrameLabels,
    submitContext,
    verifiedAt: new Date().toISOString(),
  };
  writeProgress({
    pddSubmitSelectionProof: {
      ...audit,
      status: missingLabels.length || wrongFrameLabels.length ? 'failed' : 'verified',
    },
  });
  if (missingLabels.length || wrongFrameLabels.length) {
    const reasons = [
      missingLabels.length ? `缺少必选项：${missingLabels.join('、')}` : null,
      wrongFrameLabels.length ? `必选项不在提交按钮所在表单：${wrongFrameLabels.join('、')}` : null,
    ].filter(Boolean).join('；');
    const error = new Error(`拼多多提交前选项复核失败，${reasons}`);
    error.code = 'PDD_SUBMIT_SELECTION_PROOF_FAILED';
    error.selectionProof = audit;
    throw error;
  }
  return audit;
};

const visibleExactText = async (scope, label) => {
  const locators = [
    scope.getByText(label, { exact: true }),
    scope.getByRole('radio', { name: new RegExp(`${escapeRegex(label)}\\s*$`) }),
    scope.locator('label').filter({ hasText: new RegExp(`^\\s*${escapeRegex(label)}\\s*$`) }),
  ];
  for (const locator of locators) {
    for (let index = 0; index < await locator.count().catch(() => 0); index++) {
      if (await locator.nth(index).isVisible().catch(() => false)) return true;
    }
  }
  return false;
};

const visibleTextPattern = async (scope, pattern) => {
  const candidates = [scope.getByText(pattern), scope.getByRole('radio', { name: pattern })];
  for (const candidate of candidates) {
    for (let index = 0; index < await candidate.count().catch(() => 0); index++) {
      if (await candidate.nth(index).isVisible().catch(() => false)) return true;
    }
  }
  return false;
};

const isTransientPddOrderRemarkRenderFailure = (error) => {
  const message = String(error?.message || error || '');
  return error?.code === 'PDD_ORDER_REMARK_TEMPORARILY_UNAVAILABLE'
    || /拼多多订单详情未在限定时间内完成渲染/u.test(message)
    || /订单信息区域未找到查看详情/u.test(message)
    || /拼多多订单详情刷新并重新打开后仍未找到添加备注或修改备注入口/u.test(message)
    || /拼多多备注弹窗未找到(?:输入框|保存按钮)/u.test(message)
    || /拼多多备注.*标记选择后未保持选中/u.test(message)
    || /普通工单详情.*(?:渲染|加载|订单号).*未/u.test(message)
    || /page\.(?:waitForURL|goto): Timeout \d+ms exceeded/u.test(message)
    || (/locator\.(?:waitFor|innerText|click): Timeout \d+ms exceeded/u.test(message)
      && /订单详情|查看详情|订单编号|订单号/u.test(message));
};

const ensurePddOrderRemark = async (
  targetPage,
  orderNumber,
  { loginRecoveryAttempted = false } = {},
) => {
  const remarkPolicy = pddOrderRemarkPolicyFor(readProgress().scenarioCode || activeScenarioCode);
  const existing = readProgress().pddOrderRemark;
  if (existing?.status === 'saved'
    && existing.orderNumber === orderNumber
    && existing.text === remarkPolicy.text
    && existing.color === remarkPolicy.color) return existing;

  const finalizeVerificationFallback = async () => {
    await checkForHumanVerification(targetPage, 'pdd-order-remark-fallback-check');
    for (const page of context.pages()) {
      if (page === targetPage || page.isClosed()) continue;
      let pathname = '';
      try { pathname = new URL(page.url()).pathname; } catch {}
      if (/\/orders\/detail(?:\/|$)/i.test(pathname)) await closeDerivedPage(page);
    }
    await ensurePddResolutionDetailReady(targetPage, orderNumber, readProgress());
    const current = readProgress();
    const fallback = {
      ...current.pddOrderRemark,
      shopId,
      orderNumber,
      text: remarkPolicy.text,
      color: remarkPolicy.color,
      status: 'skipped-verification',
      optional: true,
      reasonCode: 'remark-verification-fallback',
      reason: 'Optional PDD order remark triggered verification; core work-order handling continued after the challenge cleared.',
      skippedAt: new Date().toISOString(),
    };
    writeProgress({
      step: 'pdd-order-remark-skipped-verification',
      pddOrderRemark: fallback,
      verificationStage: null,
      verificationLocation: null,
      verificationFocus: null,
      manualReview: null,
      error: null,
    });
    logRunStep('pdd-order-remark-skipped-verification', fallback);
    return fallback;
  };

  if (pddOrderRemarkVerificationFallbackEnabled
    && shouldFallbackFromPddOrderRemarkVerification({
      remark: existing,
      verificationStage: readProgress().verificationStage,
      orderNumber,
      maxChallenges: pddOrderRemarkVerificationMaxChallenges,
    })) {
    return finalizeVerificationFallback();
  }

  writeProgress({
    step: 'pdd-order-remark-starting',
    pddOrderRemark: {
      ...existing,
      shopId,
      orderNumber,
      text: remarkPolicy.text,
      color: remarkPolicy.color,
      status: 'starting',
      startedAt: new Date().toISOString(),
    },
  });
  let remarkSaveStarted = false;
  try {
    const result = await addPddOrderRemark({
      targetPage,
      orderNumber,
      remarkText: remarkPolicy.text,
      colorLabel: remarkPolicy.color,
      action: (name, callback, options) => pacedAction(targetPage, name, callback, options),
      onVerification: async (detailPage) => {
        const current = readProgress();
        const remark = current.pddOrderRemark || {};
        const verificationChallenges = Math.max(
          Number(remark.verificationChallenges || 0) + 1,
          current.verificationStage?.startsWith('pdd-order-remark') ? 1 : 0,
        );
        writeProgress({
          pddOrderRemark: {
            ...remark,
            shopId,
            orderNumber,
            text: remarkPolicy.text,
            color: remarkPolicy.color,
            status: 'starting',
            verificationChallenges,
            lastVerificationAt: new Date().toISOString(),
          },
        });
        const cleared = await checkForHumanVerification(detailPage, 'pdd-order-remark-detail');
        if (cleared
          && pddOrderRemarkVerificationFallbackEnabled
          && verificationChallenges >= pddOrderRemarkVerificationMaxChallenges) {
          const fallbackError = new Error('PDD_ORDER_REMARK_VERIFICATION_FALLBACK');
          fallbackError.code = 'PDD_ORDER_REMARK_VERIFICATION_FALLBACK';
          throw fallbackError;
        }
        return cleared;
      },
      onDetailFailure: (detailPage, stage) => saveWorkflowDiagnostics(detailPage, stage),
      guardSave: (callback) => {
        remarkSaveStarted = true;
        return guardedExternalEffect({
          effectType: 'pdd-note',
          orderNumber,
          stage: 'save',
          request: {
            orderNumber,
            text: remarkPolicy.text,
            color: remarkPolicy.color,
          },
        }, callback);
      },
    });
    if (result.remarkStatus !== 'saved') {
      throw new Error('拼多多订单详情没有可用的添加备注或修改备注入口');
    }
    await checkForHumanVerification(targetPage, 'pdd-order-remark-returned');
    await ensurePddResolutionDetailReady(targetPage, orderNumber, readProgress());
    const completed = {
      shopId,
      orderNumber,
      text: remarkPolicy.text,
      color: remarkPolicy.color,
      status: 'saved',
      detailMode: result.detailMode,
      alreadySucceeded: result.alreadySucceeded,
      savedAt: new Date().toISOString(),
    };
    writeProgress({ step: 'pdd-order-remark-saved', pddOrderRemark: completed });
    logRunStep('pdd-order-remark-saved', completed);
    return completed;
  } catch (error) {
    if (error?.code === 'PDD_ORDER_REMARK_VERIFICATION_FALLBACK') {
      return finalizeVerificationFallback();
    }
    if (isPddSessionExpiredError(error) && !loginRecoveryAttempted) {
      const current = readProgress();
      const recoveryUrl = isPddDetailUrl(current.detailUrl)
        ? current.detailUrl
        : targetPage.url();
      const recoveryStartedAt = new Date().toISOString();
      writeProgress({
        step: 'pdd-order-remark-login-recovering',
        error: null,
        pddOrderRemarkLoginRecovery: {
          orderNumber,
          status: 'waiting-login',
          attempt: 1,
          maxAttempts: 1,
          recoveryUrl,
          reason: error.message,
          sessionExpiry: error.pddSessionExpiry || null,
          startedAt: recoveryStartedAt,
        },
      });
      try {
        await pacedAction(targetPage, 'recover-pdd-order-remark-login', async () => {
          if (targetPage.url() === recoveryUrl) {
            await targetPage.reload({ waitUntil: 'domcontentloaded', timeout: 90_000 });
            return targetPage;
          }
          return navigateSystemPage(targetPage, recoveryUrl, 'recover-pdd-order-remark-login');
        }, { retryOnRateLimit: true });
        await ensurePddLogin(targetPage, context, recoveryUrl);
        const recoveredDetail = await ensurePddResolutionDetailReady(
          targetPage,
          orderNumber,
          readProgress(),
          { settleMs: Math.max(pddDetailSettleMs, 30_000) },
        );
        writeProgress({
          step: recoveredDetail.isCompleted
            ? 'pdd-order-remark-completed-page-recovered'
            : 'pdd-order-remark-login-retrying',
          pddOrderRemarkLoginRecovery: {
            ...readProgress().pddOrderRemarkLoginRecovery,
            status: recoveredDetail.isCompleted ? 'completed-page' : 'retrying',
            loginRecoveredAt: new Date().toISOString(),
          },
          error: null,
        });
        if (recoveredDetail.isCompleted) {
          return {
            status: 'skipped-completed-page',
            orderNumber,
            recoveredDetail,
          };
        }
        const recovered = await ensurePddOrderRemark(targetPage, orderNumber, {
          loginRecoveryAttempted: true,
        });
        writeProgress({
          pddOrderRemarkLoginRecovery: {
            ...readProgress().pddOrderRemarkLoginRecovery,
            status: 'succeeded',
            recoveredAt: new Date().toISOString(),
          },
        });
        return recovered;
      } catch (recoveryError) {
        if (recoveryError instanceof HumanVerificationRequiredError
          || recoveryError instanceof PddLoginRequiredError
          || recoveryError instanceof RateLimitPauseError
          || recoveryError instanceof ManualReviewRequiredError) throw recoveryError;
        error = recoveryError;
        writeProgress({
          pddOrderRemarkLoginRecovery: {
            ...readProgress().pddOrderRemarkLoginRecovery,
            status: 'failed',
            error: recoveryError.message,
            failedAt: new Date().toISOString(),
          },
        });
      }
    }
    if (!remarkSaveStarted && isTransientPddOrderRemarkRenderFailure(error)) {
      const transientError = error?.code === 'PDD_ORDER_REMARK_TEMPORARILY_UNAVAILABLE'
        ? error
        : new Error(`PDD_ORDER_REMARK_TEMPORARILY_UNAVAILABLE: ${error.message}`);
      transientError.code = 'PDD_ORDER_REMARK_TEMPORARILY_UNAVAILABLE';
      writeProgress({
        step: 'pdd-order-remark-retry-ready',
        pddOrderRemark: {
          ...readProgress().pddOrderRemark,
          status: 'retry-ready',
          reason: transientError.message,
          retryAfterMs: 30_000,
          failedAt: new Date().toISOString(),
        },
        manualReview: null,
        error: null,
      });
      throw transientError;
    }
    if (error instanceof HumanVerificationRequiredError
      || error instanceof PddLoginRequiredError
      || error instanceof RateLimitPauseError
      || error instanceof ManualReviewRequiredError
      || error?.code === 'PDD_ORDER_REMARK_TEMPORARILY_UNAVAILABLE') throw error;
    await pauseForManualReview(targetPage, 'pdd-order-remark', error.message, {
      pddOrderRemark: {
        ...readProgress().pddOrderRemark,
        status: 'failed',
        reason: error.message,
        failedAt: new Date().toISOString(),
      },
    });
  }
};

const resolveVisiblePddPrimaryRefundOutcome = async (scope, recommendedOutcome) => {
  const resolved = await resolvePddCoreVisibleSelection(
    scope,
    [recommendedOutcome],
    {
      strictResolver: (visibleOptions) => {
        const outcome = resolvePddPrimaryRefundOutcome(recommendedOutcome, visibleOptions);
        return visibleOptions.includes(outcome) ? outcome : null;
      },
    },
  );
  return resolved.selection?.label || null;
};

const resolvePddCoreVisibleSelection = async (
  scope,
  requestedLabels,
  { strictResolver = null } = {},
) => {
  const candidates = expandOrdinaryPddOptionAliases(requestedLabels);
  const visibleOptions = await listVisibleOrdinaryPddOptions([scope]);
  const strictLabel = strictResolver?.(visibleOptions) || null;
  if (strictLabel && visibleOptions.includes(strictLabel)) {
    return {
      candidates,
      visibleOptions,
      selection: {
        label: strictLabel,
        requestedLabel: String(requestedLabels[0] || ''),
        intent: 'strict-core-outcome',
        confidence: 'exact',
        reason: 'strict-visible-core-outcome-match',
        selectionMode: 'strict',
      },
    };
  }
  const semanticMatch = resolveOrdinaryPddSemanticOption(candidates, visibleOptions);
  if (semanticMatch) {
    return {
      candidates,
      visibleOptions,
      selection: { ...semanticMatch, selectionMode: 'semantic' },
    };
  }
  const judgmentMatch = resolveOrdinaryPddJudgmentOption(candidates, visibleOptions);
  if (!judgmentMatch
    || judgmentMatch.confidence === 'low'
    || judgmentMatch.representsRequestedIntent !== true) {
    return { candidates, visibleOptions, selection: null, judgmentMatch };
  }
  return {
    candidates,
    visibleOptions,
    selection: { ...judgmentMatch, selectionMode: 'judgment' },
  };
};

const selectPddCoreResolutionOption = async (
  targetPage,
  scope,
  requestedLabels,
  {
    stage,
    timeoutMs = 30000,
    strictResolver = null,
  } = {},
) => {
  const deadline = Date.now() + timeoutMs;
  let visibleSignature = null;
  let visibleStableSince = 0;
  let latestResolution = null;
  do {
    await checkForHumanVerification(targetPage, `wait-core-option-${stage || 'resolution'}`);
    const resolution = await resolvePddCoreVisibleSelection(
      scope,
      requestedLabels,
      { strictResolver },
    );
    latestResolution = resolution;
    const signature = resolution.visibleOptions
      .map((label) => normalizeOrdinaryPddOptionText(label))
      .sort()
      .join('|');
    if (signature && signature !== visibleSignature) {
      visibleSignature = signature;
      visibleStableSince = Date.now();
    }
    const selection = resolution.selection;
    const stableEnough = selection?.selectionMode !== 'judgment'
      || (signature && Date.now() - visibleStableSince >= 400);
    if (selection && stableEnough
      && await selectPddRadio(targetPage, scope, selection.label, { required: false })) {
      const audit = {
        orderNumber: readProgress().orderNumber || null,
        stage: stage || null,
        requestedLabels: resolution.candidates,
        visibleOptions: resolution.visibleOptions,
        selectedLabel: selection.label,
        requestedLabel: selection.requestedLabel,
        intent: selection.intent,
        confidence: selection.confidence,
        reason: selection.reason,
        selectionMode: selection.selectionMode,
        selectedAt: new Date().toISOString(),
        ...(selection.selectionMode === 'judgment'
          ? {
            score: selection.score,
            matchedFeatures: selection.matchedFeatures,
            representsRequestedIntent: selection.representsRequestedIntent,
            rejectedOptions: selection.rejectedOptions,
          }
          : {}),
      };
      writeProgress({
        step: 'pdd-core-resolution-option-selected',
        pddCoreOptionSelection: audit,
      });
      return selection.label;
    }
    const remainingMs = deadline - Date.now();
    if (remainingMs > 0) await targetPage.waitForTimeout(Math.min(250, remainingMs));
  } while (Date.now() < deadline);
  writeProgress({
    pddCoreOptionLookupFailure: {
      orderNumber: readProgress().orderNumber || null,
      stage: stage || null,
      requestedLabels: latestResolution?.candidates
        || expandOrdinaryPddOptionAliases(requestedLabels),
      visibleOptions: latestResolution?.visibleOptions || [],
      rejectedOptions: latestResolution?.judgmentMatch?.rejectedOptions || [],
      failedAt: new Date().toISOString(),
    },
  });
  await saveWorkflowDiagnostics(targetPage, 'pdd-core-option-selection-unavailable').catch(() => {});
  return null;
};

const waitForVisiblePddPrimaryRefundOutcome = async (
  targetPage,
  scope,
  recommendedOutcome,
  timeoutMs = 30000,
) => {
  return selectPddCoreResolutionOption(
    targetPage,
    scope,
    [recommendedOutcome],
    {
      stage: 'primary-refund',
      timeoutMs,
      strictResolver: (visibleOptions) => {
        const outcome = resolvePddPrimaryRefundOutcome(recommendedOutcome, visibleOptions);
        return visibleOptions.includes(outcome) ? outcome : null;
      },
    },
  );
};

const selectVisiblePddInTransitRefundOutcome = async (
  targetPage,
  scope,
  timeoutMs = 30000,
  rejectedOutcomes = [],
) => selectPddCoreResolutionOption(
  targetPage,
  scope,
  pddInTransitRefundOutcomePriority.filter((outcome) => (
    !normalizePddInTransitRejectedOutcomes(rejectedOutcomes).includes(outcome)
  )),
  {
    stage: 'in-transit-refund',
    timeoutMs,
    strictResolver: (visibleOptions) => resolvePddInTransitRefundOutcome(
      visibleOptions,
      rejectedOutcomes,
    ),
  },
);

const hasVisiblePddDirectRefundOutcome = async (scope) => {
  const resolved = await resolvePddCoreVisibleSelection(scope, ['同意退款']);
  return Boolean(resolved.selection);
};

const pddResolutionFormAnchorOptions = [
  '不同意修改地址',
  '协商退款重拍',
  ...pddPrimaryRefundOutcomeGroup,
  ...pddInTransitRefundOutcomePriority,
  ...pddInterceptProgressOutcomeGroup,
  ...pddConsumerNegotiationOutcomeGroup,
  '已进行召回',
  '消费者已收到货',
  '主观原因不想要',
  '降价/优惠券未用',
  '物流问题',
  '其他',
  '已交给快递',
  '未交给快递',
  '尝试拦截快递',
  '消费者撤销售后申请',
  pddSubjectiveDirectRefundOutcome,
];

const findVisiblePddResolutionFormScope = async (
  targetPage,
  { allowAnyVisibleOptions = false } = {},
) => {
  const anchorOptions = new Set(
    pddResolutionFormAnchorOptions.map((label) => normalizeOrdinaryPddOptionText(label)),
  );
  const frames = targetPage.frames();
  const candidates = [];
  for (let frameIndex = 0; frameIndex < frames.length; frameIndex += 1) {
    const frame = frames[frameIndex];
    const scope = frame.locator('body');
    const visibleOptions = await listVisibleOrdinaryPddOptions([scope]);
    if (!visibleOptions.length) continue;
    const anchorCount = visibleOptions.filter(
      (label) => anchorOptions.has(normalizeOrdinaryPddOptionText(label)),
    ).length;
    if (!anchorCount && !allowAnyVisibleOptions) continue;
    candidates.push({
      scope,
      visibleOptions,
      anchorCount,
      frameIndex,
      frameKind: frame === targetPage.mainFrame() ? 'main' : 'child',
      frameUrl: String(frame.url() || '').slice(0, 1000),
    });
  }
  candidates.sort((left, right) => (
    right.anchorCount - left.anchorCount
    || right.visibleOptions.length - left.visibleOptions.length
    || left.frameIndex - right.frameIndex
  ));
  return candidates[0] || null;
};

const ensurePddResolutionSubmissionDetail = async (targetPage, orderNumber) => {
  let currentState = null;
  if (!targetPage.isClosed() && isPddDetailUrl(targetPage.url())) {
    currentState = await waitForPddResolutionDetail(targetPage, orderNumber, {
      readTimeoutMs: Math.min(pddRenderWaitMs, 10_000),
      settleMs: Math.min(pddRenderWaitMs, 10_000),
    }).catch(() => null);
    if (currentState?.detailReady && currentState.orderMatches) {
      if (currentState.isCompleted) {
        throw new PddWorkOrderAlreadyCompletedError(
          'resolution-detail-revalidation',
          currentState,
        );
      }
      writeProgress({
        pddResolutionDetailRevalidation: {
          orderNumber,
          status: 'exact-detail-reused',
          detailUrl: targetPage.url(),
          confirmationMethod: currentState.confirmationMethod || 'rendered-detail-order-match',
          revalidatedAt: new Date().toISOString(),
        },
      });
      return targetPage;
    }
  }

  const reopenedPage = await reopenPddDetailForResolution(
    targetPage,
    orderNumber,
    readProgress(),
    { forcePendingList: true },
  );
  if (hasConfirmedPendingListAbsence(readProgress(), orderNumber)) {
    throw new PddWorkOrderAlreadyCompletedError(
      'resolution-detail-revalidation',
      completedPddStateFromPendingListAbsence(orderNumber),
    );
  }
  const reopenedState = await ensurePddResolutionDetailReady(
    reopenedPage,
    orderNumber,
    readProgress(),
    { settleMs: Math.max(pddDetailSettleMs, 30_000) },
  );
  if (reopenedState.isCompleted && reopenedState.orderMatches) {
    throw new PddWorkOrderAlreadyCompletedError(
      'resolution-detail-revalidation',
      reopenedState,
    );
  }
  writeProgress({
    step: 'pdd-resolution-detail-revalidated',
    pddResolutionDetailRevalidation: {
      orderNumber,
      status: 'reopened-exact-detail',
      previousUrl: targetPage.isClosed() ? null : targetPage.url(),
      detailUrl: reopenedPage.url(),
      confirmationMethod: reopenedState.confirmationMethod || 'rendered-detail-order-match',
      revalidatedAt: new Date().toISOString(),
    },
  });
  return reopenedPage;
};

const preparePddResolutionSubmissionPage = async (targetPage, decision) => {
  // The consumer-negotiation page continues an already submitted intercept
  // result. Its remark completed before the 12-hour wait, so do not repeat it.
  if (decision.flowCode !== 'consumer-negotiation-followup') {
    await ensurePddOrderRemark(targetPage, decision.orderNumber);
  }
  return ensurePddResolutionSubmissionDetail(targetPage, decision.orderNumber);
};

const submitPddResolution = async (targetPage, decision, { prepared = false } = {}) => {
  if (!prepared) {
    targetPage = await preparePddResolutionSubmissionPage(targetPage, decision);
  }
  const savedProgress = readProgress();
  const savedSubmission = savedProgress.pddResolutionSubmission;
  const inTransitRefundDecision = isPddInTransitRefundDecision(decision);
  const rejectedInTransitOutcomes = inTransitRefundDecision
    && savedSubmission?.orderNumber === decision.orderNumber
    ? normalizePddInTransitRejectedOutcomes(savedSubmission.rejectedOutcomeLabels)
    : [];
  let resolutionForm;
  for (let contextRecoveryAttempt = 0; contextRecoveryAttempt < 2; contextRecoveryAttempt++) {
    try {
      if (!isPddDetailUrl(targetPage.url())) {
        throw new PddResolutionDetailContextLostError('resolution', targetPage.url());
      }
      await checkForHumanVerification(targetPage, 'wait-resolution-form');
      resolutionForm = await findVisiblePddResolutionFormScope(targetPage, {
        allowAnyVisibleOptions: inTransitRefundDecision,
      });
      if (!resolutionForm) {
        const submit = await waitForPddSubmitButton(
          targetPage,
          'resolution',
          30000,
          { allowDisabled: true },
        );
        const formScope = await submit.locator(
          'xpath=ancestor::*[.//*[@role="radio"] or .//input[@type="radio"]][1]',
        ).first();
        const scope = await formScope.count().catch(() => 0)
          ? formScope
          : targetPage.locator('main');
        resolutionForm = {
          scope,
          visibleOptions: await listVisibleOrdinaryPddOptions([scope]),
          anchorCount: 0,
          frameIndex: 0,
          frameKind: 'submit-button-form',
          frameUrl: targetPage.url(),
        };
      }
      break;
    } catch (error) {
      if (!(error instanceof PddResolutionDetailContextLostError)
        || contextRecoveryAttempt >= 1) throw error;
      writeProgress({
        step: 'pdd-resolution-detail-context-reopening',
        pddResolutionDetailContextRecovery: {
          orderNumber: decision.orderNumber,
          status: 'reopening-exact-detail',
          previousUrl: error.currentUrl || targetPage.url(),
          observedOrderNumber: error.observedOrderNumber || null,
          attempt: contextRecoveryAttempt + 1,
          startedAt: new Date().toISOString(),
        },
      });
      targetPage = await ensurePddResolutionSubmissionDetail(
        targetPage,
        decision.orderNumber,
      );
      writeProgress({
        pddResolutionDetailContextRecovery: {
          ...readProgress().pddResolutionDetailContextRecovery,
          status: 'exact-detail-reopened',
          detailUrl: targetPage.url(),
          recoveredAt: new Date().toISOString(),
        },
      });
    }
  }
  const scope = resolutionForm.scope;
  const visibleCoreResolutionOptions = resolutionForm.visibleOptions?.length
    ? resolutionForm.visibleOptions
    : await listVisibleOrdinaryPddOptions([scope]);
  writeProgress({
    pddResolutionFormDiscovery: {
      orderNumber: decision.orderNumber,
      source: resolutionForm.frameKind === 'submit-button-form'
        ? 'submit-button-form'
        : 'visible-options-before-submit',
      visibleOptions: visibleCoreResolutionOptions,
      anchorCount: resolutionForm.anchorCount,
      frameIndex: resolutionForm.frameIndex,
      frameKind: resolutionForm.frameKind,
      frameUrl: resolutionForm.frameUrl,
      discoveredAt: new Date().toISOString(),
    },
  });
  const visibleInTransitRefundOutcome = inTransitRefundDecision
    ? resolvePddInTransitRefundOutcome(
      visibleCoreResolutionOptions,
      rejectedInTransitOutcomes,
    )
    : null;
  const initialInTransitPageVariant = inTransitRefundDecision
    ? resolvePddInTransitPageVariant(visibleCoreResolutionOptions, {
      ...savedProgress,
      pddResolutionDecision: savedProgress.pddResolutionDecision || decision,
    })
    : null;
  const hasRecallStatusStep = await visibleExactText(scope, '已进行召回')
    && await visibleExactText(scope, '消费者已收到货');
  if (hasRecallStatusStep && !visibleInTransitRefundOutcome) {
    if (decision.flowCode !== 'primary-refund'
      || !decision.tmsTicketId
      || !decision.tmsTicketNo) {
      throw new Error('拼多多出现收货状态步骤，但当前工单没有可核验的 TMS 召回记录');
    }
    const recallStatus = '已进行召回';
    if (!await waitForPddOption(targetPage, scope, recallStatus, 60000)) {
      throw new Error(`拼多多未找到收货状态选项: ${recallStatus}`);
    }
    writeProgress({
      pddResolutionFlow: {
        flowCode: 'primary-refund',
        detectedAt: new Date().toISOString(),
        recallStatus,
        recallTicketId: decision.tmsTicketId,
        recallTicketNo: decision.tmsTicketNo,
        primaryOutcome: null,
        secondaryReason: null,
        tertiaryOutcome: null,
      },
    });
    let recallCompletionState = null;
    await clickPddSubmit(targetPage, 'recall-status', decision.orderNumber, {
      postcondition: async () => {
        let postconditionPage = targetPage;
        let attemptedDetailRecovery = false;
        const deadline = Date.now() + 60_000;
        while (Date.now() < deadline) {
          await checkForHumanVerification(postconditionPage, 'pdd-recall-status-postcondition');
          const pageScope = postconditionPage.locator('body');
          const secondStepVisible = await hasVisiblePddDirectRefundOutcome(pageScope)
            || await visibleExactText(pageScope, '主观原因不想要')
            || await visibleExactText(pageScope, '尝试拦截快递');
          const resolutionState = await readPddResolutionState(
            postconditionPage,
            decision.orderNumber,
          ).catch(() => null);
          if (isPddRecallTransitionComplete({
            secondStepVisible,
            orderCompleted: resolutionState?.isCompleted,
          })) {
            if (resolutionState?.isCompleted) {
              recallCompletionState = {
                ...resolutionState,
                confirmationMethod: 'recall-status-detail-completed',
              };
            }
            targetPage = postconditionPage;
            return;
          }
          if (!attemptedDetailRecovery && !isPddDetailUrl(postconditionPage.url())) {
            attemptedDetailRecovery = true;
            postconditionPage = await reopenPddDetailForResolution(
              postconditionPage,
              decision.orderNumber,
              readProgress(),
            ).catch(() => postconditionPage);
            targetPage = postconditionPage;
            continue;
          }
          await postconditionPage.waitForTimeout(250);
        }
        if (!isPddDetailUrl(postconditionPage.url())) {
          const absent = await confirmOrderAbsentFromPendingList(
            postconditionPage,
            decision.orderNumber,
          ).catch(() => false);
          if (absent) {
            recallCompletionState = {
              isCompleted: true,
              isPending: false,
              orderMatches: true,
              orderNumber: decision.orderNumber,
              confirmationMethod: 'recall-status-absent-from-pending-list',
            };
            targetPage = postconditionPage;
            return;
          }
        }
        throw new Error('拼多多收货状态提交后未进入退款处理阶段');
      },
    });
    if (recallCompletionState?.isCompleted) {
      markTmsEvidenceUnusedForPddResolution(decision.orderNumber, decision.workOrderType);
      return {
        ...recallCompletionState,
        flowCode: 'primary-refund',
        expectedOutcome: decision.outcome,
      };
    }
    return submitPddResolution(targetPage, decision);
  }
  const hasPrimaryOutcome = await hasVisiblePddDirectRefundOutcome(scope);
  const hasSubjectiveReason = await visibleExactText(scope, '主观原因不想要')
    || await visibleTextPattern(scope, /主观原因/);
  const hasReasonGroup = [
    hasSubjectiveReason,
    await visibleExactText(scope, '降价/优惠券未用'),
    await visibleExactText(scope, '物流问题'),
    await visibleExactText(scope, '其他'),
  ].filter(Boolean).length >= 2;
  const hasTertiaryOutcome = await visibleExactText(scope, '尝试拦截快递')
    || await visibleExactText(scope, '消费者撤销售后申请')
    || await visibleExactText(scope, '同意消费者退款申请')
    || Boolean((await resolvePddCoreVisibleSelection(
      scope,
      [pddSubjectiveDirectRefundOutcome],
    )).selection);
  const visibleInterceptProgressOutcomes = [...new Set(
    pddInterceptProgressOutcomeGroup
      .map((outcome) => resolveOrdinaryPddSemanticOption(
        [outcome],
        visibleCoreResolutionOptions,
      )?.label)
      .filter(Boolean),
  )];
  const hasInterceptProgressStep = visibleInterceptProgressOutcomes.length >= 2;
  const visibleConsumerNegotiationOutcomes = [...new Set(
    pddConsumerNegotiationOutcomeGroup
      .map((outcome) => resolveOrdinaryPddSemanticOption(
        [outcome],
        visibleCoreResolutionOptions,
      )?.label)
      .filter(Boolean),
  )];
  const hasConsumerNegotiationStep = visibleConsumerNegotiationOutcomes.length >= 2;
  const resumedSubjectiveTertiaryStage = isPddSubjectiveTertiaryStageReady({
    hasTertiaryOutcome,
    hasReasonGroup,
    savedSubmission,
    orderNumber: decision.orderNumber,
  });
  const detectedFlowCode = hasReasonGroup && hasSubjectiveReason
    ? 'subjective-intercept'
    : classifyPddResolutionFlow({
      hasPrimaryOutcome,
      hasSecondaryReason: hasSubjectiveReason,
      hasTertiaryOutcome,
    });
  // Prefer the currently rendered controls; only use the saved decision when
  // the detail page has not exposed a unique branch yet.
  let flowCode = initialInTransitPageVariant?.flowCode
    || (visibleInTransitRefundOutcome
      ? 'primary-refund'
      : hasConsumerNegotiationStep
        ? 'consumer-negotiation-followup'
        : hasInterceptProgressStep
          ? 'intercept-progress'
          : ['shipped-no-tracking-refund', 'abnormal-network-warning'].includes(decision.flowCode)
            ? decision.flowCode
            : detectedFlowCode || decision.flowCode);
  if (!flowCode || (flowCode === 'primary-refund'
    && hasPrimaryOutcome
    && hasSubjectiveReason
    && !visibleInTransitRefundOutcome)) {
    throw new Error('拼多多处理页面无法唯一识别退款结果或主观原因拦截流程');
  }
  const flow = {
    flowCode,
    detectedAt: new Date().toISOString(),
    primaryOutcome: null,
    secondaryReason: null,
    tertiaryOutcome: null,
    interceptProgressOutcome: null,
    consumerNegotiationOutcome: null,
    handoverOutcome: null,
  };
  writeProgress({ pddResolutionFlow: flow });

  let expectedOutcome = decision.outcome;
  if (['shipped-no-tracking-refund', 'in-transit-handover'].includes(flowCode)) {
    const inTransitHandover = flowCode === 'in-transit-handover';
    const handoverLabel = inTransitHandover
      ? initialInTransitPageVariant?.outcome
        || (decision.merchantHandover === 'not-handed' ? '未交给快递' : '已交给快递')
      : decision.merchantHandover === 'handed-to-carrier'
        ? '已交给快递'
        : '未交给快递';
    let handoverCompletionState = null;
    const secondStepAlreadyVisible = await hasVisiblePddDirectRefundOutcome(scope);
    if (!secondStepAlreadyVisible) {
      if (!await waitForPddOption(targetPage, scope, handoverLabel, 60000)) {
        throw new Error(`拼多多未找到物流交接选项: ${handoverLabel}`);
      }
      // PDD uses a two-step form for this scenario. The first submit commits
      // the handover choice and only then renders the refund outcome controls.
      await clickPddSubmit(targetPage, 'handover', decision.orderNumber, {
        selectedPddOption: handoverLabel,
        postcondition: async () => {
          let postconditionPage = targetPage;
          let attemptedDetailRecovery = false;
          const deadline = Date.now() + 60_000;
          while (Date.now() < deadline) {
            await checkForHumanVerification(postconditionPage, 'pdd-handover-postcondition');
            const pageScope = postconditionPage.locator('body');
            const firstStepVisible = await visibleExactText(pageScope, handoverLabel);
            const secondStepVisible = await hasVisiblePddDirectRefundOutcome(pageScope);
            const resolutionState = await readPddResolutionState(
              postconditionPage,
              decision.orderNumber,
            ).catch(() => null);
            if (isPddHandoverTransitionComplete({
              firstStepVisible,
              secondStepVisible,
              orderCompleted: resolutionState?.isCompleted,
            })) {
              if (resolutionState?.isCompleted) {
                handoverCompletionState = {
                  ...resolutionState,
                  confirmationMethod: 'handover-detail-completed',
                };
              }
              targetPage = postconditionPage;
              return;
            }
            if (!attemptedDetailRecovery && !isPddDetailUrl(postconditionPage.url())) {
              attemptedDetailRecovery = true;
              postconditionPage = await reopenPddDetailForResolution(
                postconditionPage,
                decision.orderNumber,
                readProgress(),
              ).catch(() => postconditionPage);
              targetPage = postconditionPage;
              continue;
            }
            await postconditionPage.waitForTimeout(250);
          }
          if (!isPddDetailUrl(postconditionPage.url())) {
            const absent = await confirmOrderAbsentFromPendingList(
              postconditionPage,
              decision.orderNumber,
            ).catch(() => false);
            if (absent) {
              handoverCompletionState = {
                isCompleted: true,
                isPending: false,
                orderMatches: true,
                orderNumber: decision.orderNumber,
                confirmationMethod: 'handover-absent-from-pending-list',
              };
              targetPage = postconditionPage;
              return;
            }
          }
          throw new Error('拼多多第一阶段提交后页面未切换到退款处理阶段');
        },
      });
    }
    if (handoverCompletionState?.isCompleted) {
      flow.primaryOutcome = decision.outcome;
      writeProgress({ pddResolutionFlow: flow });
      markTmsEvidenceUnusedForPddResolution(decision.orderNumber, decision.workOrderType);
      return {
        ...handoverCompletionState,
        flowCode,
        expectedOutcome: decision.outcome,
      };
    }
    const refundOutcome = inTransitHandover
      ? await selectVisiblePddInTransitRefundOutcome(
        targetPage,
        targetPage.locator('body'),
        30000,
        rejectedInTransitOutcomes,
      )
      : await waitForVisiblePddPrimaryRefundOutcome(
        targetPage,
        targetPage.locator('body'),
        decision.outcome,
        30000,
      );
    if (!refundOutcome) {
      throw new Error(inTransitHandover
        ? `拼多多物流交接后未找到在途无理由退款结果选项: ${pddInTransitRefundOutcomePriority.join('、')}`
        : `拼多多未找到已发货无轨迹退款的${decision.outcome}选项`);
    }
    expectedOutcome = refundOutcome;
    flow.primaryOutcome = refundOutcome;
    flow.handoverOutcome = handoverLabel;
    if (inTransitHandover) {
      flowCode = 'primary-refund';
      flow.flowCode = flowCode;
    }
    markTmsEvidenceUnusedForPddResolution(decision.orderNumber, decision.workOrderType);
  } else if (flowCode === 'abnormal-network-warning') {
    const outcome = decision.outcome;
    if (!await waitForPddOption(targetPage, scope, outcome, 60000)) {
      throw new Error(`拼多多未找到异常网点处理选项: ${outcome}`);
    }
    if (decision.reasonText) {
      const reasonInput = await firstVisible([
        scope.locator('textarea').first(),
        scope.getByRole('textbox').last(),
      ]);
      if (!reasonInput) throw new Error('异常网点预警未找到原因说明输入框');
      await pacedAction(targetPage, 'fill-abnormal-network-reason', () => reasonInput.fill(decision.reasonText));
    }
    flow.primaryOutcome = outcome;
  } else if (flowCode === 'consumer-negotiation-followup') {
    const followup = resolvePddConsumerNegotiationFollowup(savedSubmission || {});
    writeProgress({
      step: followup.ready
        ? 'pdd-consumer-negotiation-followup-ready'
        : 'pdd-consumer-negotiation-followup-waiting',
      pddResolutionFlow: flow,
      pddResolutionSubmission: {
        ...(savedSubmission || {}),
        shopId,
        orderNumber: decision.orderNumber,
        status: followup.ready ? 'followup-ready' : 'followup-waiting',
        interceptProgressOutcome: savedSubmission?.outcome || '快递还在拦截中',
        consumerResponseWaitStartedAt: followup.startedAt,
        consumerResponseNextAttemptAt: followup.nextAttemptAt,
      },
    });
    if (!followup.ready) {
      throw new LogisticsRetryRequiredError(
        'pdd-consumer-negotiation-waiting',
        '拼多多正在等待消费者确认拦截后退款方案，满 12 小时仍无回复后再自动处理',
        followup.retryAfterMs,
        {
          orderNumber: decision.orderNumber,
          detailUrl: targetPage.url(),
          nextAttemptAt: followup.nextAttemptAt,
        },
      );
    }
    const consumerNegotiationOutcome = await selectPddCoreResolutionOption(
      targetPage,
      scope,
      [followup.outcome],
      { stage: 'consumer-negotiation-followup', timeoutMs: 60000 },
    );
    if (!consumerNegotiationOutcome) {
      throw new Error(`拼多多未找到消费者协商结果选项: ${followup.outcome}`);
    }
    expectedOutcome = consumerNegotiationOutcome;
    flow.primaryOutcome = expectedOutcome;
    flow.consumerNegotiationOutcome = expectedOutcome;
    markTmsEvidenceUnusedForPddResolution(decision.orderNumber, decision.workOrderType);
  } else if (flowCode === 'intercept-progress') {
    const interceptProgressOutcome = resolvePddInterceptProgressOutcome(readProgress());
    const selectedInterceptProgressOutcome = await selectPddCoreResolutionOption(
      targetPage,
      scope,
      [interceptProgressOutcome],
      { stage: 'intercept-progress', timeoutMs: 60000 },
    );
    if (!selectedInterceptProgressOutcome) {
      throw new Error(`拼多多未找到拦截进度选项: ${interceptProgressOutcome}`);
    }
    expectedOutcome = selectedInterceptProgressOutcome;
    flow.primaryOutcome = selectedInterceptProgressOutcome;
    flow.interceptProgressOutcome = selectedInterceptProgressOutcome;
    markTmsEvidenceUnusedForPddResolution(decision.orderNumber, decision.workOrderType);
  } else if (flowCode === 'primary-refund') {
    const primaryOutcome = inTransitRefundDecision
      ? await selectVisiblePddInTransitRefundOutcome(
        targetPage,
        scope,
        30000,
        rejectedInTransitOutcomes,
      )
      : await waitForVisiblePddPrimaryRefundOutcome(
        targetPage,
        scope,
        decision.outcome,
        30000,
      );
    if (!primaryOutcome) {
      throw new Error(inTransitRefundDecision
        ? `拼多多未找到在途无理由退款结果选项: ${pddInTransitRefundOutcomePriority.join('、')}`
        : `拼多多未找到必选处理结果: ${decision.outcome}`);
    }
    expectedOutcome = primaryOutcome;
    flow.primaryOutcome = primaryOutcome;
    markTmsEvidenceUnusedForPddResolution(decision.orderNumber, decision.workOrderType);
  } else {
    if (!hasSubjectiveReason && !resumedSubjectiveTertiaryStage) {
      throw new Error('拼多多主观原因拦截流程缺少必选原因: 主观原因不想要');
    }
    if (!resumedSubjectiveTertiaryStage
      && !await waitForPddOption(targetPage, scope, '主观原因不想要', 60000)) {
      throw new Error('拼多多未找到必选原因: 主观原因不想要');
    }
    flow.secondaryReason = '主观原因不想要';
    await checkForHumanVerification(targetPage, 'pdd-resolution-tertiary-options');
    const tertiaryScope = targetPage.locator('main');
    const tertiaryVisibleBeforeSubmit = resumedSubjectiveTertiaryStage
      || await visibleExactText(tertiaryScope, '尝试拦截快递')
      || await visibleExactText(tertiaryScope, '消费者撤销售后申请')
      || await visibleExactText(tertiaryScope, '同意消费者退款申请');
    // This PDD variant uses the blue 提交 button to commit the reason group
    // before it renders the three negotiation-result options.
    if (!tertiaryVisibleBeforeSubmit) {
      // This button only advances the form wizard. A refreshed page may render
      // this step again, so the visible form state decides whether to click it.
      await clickPddSubmit(targetPage, 'subjective-reason', decision.orderNumber, {
        guard: false,
        settleUntil: async () => {
          if (!isPddDetailUrl(targetPage.url())) return true;
          const pageScope = targetPage.locator('body');
          if (await visibleExactText(pageScope, '尝试拦截快递')) return true;
          if (inTransitRefundDecision) {
            const visibleOptions = await listVisibleOrdinaryPddOptions([pageScope]);
            if (resolvePddInTransitPageVariant(visibleOptions, readProgress())) return true;
          }
          const state = await readPddResolutionState(
            targetPage,
            decision.orderNumber,
            { timeoutMs: 2000 },
          ).catch(() => null);
          return Boolean(state?.isCompleted);
        },
      });
      await checkForHumanVerification(targetPage, 'pdd-resolution-tertiary-options-after-reason-submit');
    }
    const tertiaryVisibleOptions = inTransitRefundDecision
      ? await listVisibleOrdinaryPddOptions([tertiaryScope])
      : [];
    const inTransitPageVariant = inTransitRefundDecision
      ? resolvePddInTransitPageVariant(tertiaryVisibleOptions, readProgress())
      : null;
    let subjectiveRefundOutcome;
    if (inTransitPageVariant?.flowCode === 'intercept-progress') {
      subjectiveRefundOutcome = await selectPddCoreResolutionOption(
        targetPage,
        tertiaryScope,
        [inTransitPageVariant.outcome],
        { stage: 'intercept-progress-after-subjective-reason', timeoutMs: 60000 },
      );
      flowCode = 'intercept-progress';
      flow.flowCode = flowCode;
      flow.primaryOutcome = subjectiveRefundOutcome;
      flow.interceptProgressOutcome = subjectiveRefundOutcome;
    } else {
      subjectiveRefundOutcome = inTransitRefundDecision
        ? await selectVisiblePddInTransitRefundOutcome(
          targetPage,
          tertiaryScope,
          60000,
          rejectedInTransitOutcomes,
        )
        : await selectPddCoreResolutionOption(
        targetPage,
        tertiaryScope,
        [pddSubjectiveDirectRefundOutcome],
        { stage: 'subjective-refund-outcome', timeoutMs: 60000 },
      );
    }
    if (!subjectiveRefundOutcome) {
      throw new Error(inTransitRefundDecision
        ? `拼多多未找到在途无理由退款或拦截进度结果: ${pddInTransitRefundOutcomePriority.join('、')}`
        : `拼多多未找到必选协商结果: ${pddSubjectiveDirectRefundOutcome}`);
    }
    if (flowCode !== 'intercept-progress') {
      if (inTransitRefundDecision) {
        flowCode = 'primary-refund';
        flow.flowCode = flowCode;
        flow.primaryOutcome = subjectiveRefundOutcome;
      } else {
        flow.tertiaryOutcome = subjectiveRefundOutcome;
      }
    }
    expectedOutcome = subjectiveRefundOutcome;
    markTmsEvidenceUnusedForPddResolution(decision.orderNumber, decision.workOrderType);
  }
  writeProgress({ pddResolutionFlow: flow });
  if (!await isPddOptionSelected(targetPage.locator('body'), expectedOutcome)
    && !await selectPddRadio(targetPage, targetPage.locator('body'), expectedOutcome, { required: false })) {
    throw new Error(`拼多多最终处理结果“${expectedOutcome}”未保持选中，禁止提交`);
  }

  const submissionForAttempt = readProgress().pddResolutionSubmission || {};
  const previousSubmitAttemptCount = Math.max(
    Number(submissionForAttempt.submitAttemptCount || 0),
    submissionForAttempt.notAppliedRetryAuthorizedAt ? 1 : 0,
  );
  const historicalRefundFallback = Boolean(
    submissionForAttempt.historicalEvidenceRefundFallbackAuthorizedAt
    && previousSubmitAttemptCount >= 2,
  );
  const submitEffectStage = flowCode === 'consumer-negotiation-followup'
    ? submissionForAttempt.notAppliedRetryAuthorizedAt
      ? 'consumer-negotiation-followup-retry-v2'
      : 'consumer-negotiation-followup-v1'
    : inTransitRefundDecision
      && flowCode === 'primary-refund'
      && rejectedInTransitOutcomes.length > 0
      ? `resolution-in-transit-option-fallback-v${rejectedInTransitOutcomes.length + 1}`
    : historicalRefundFallback
      ? 'resolution-evidence-refund-fallback-v3'
    : submissionForAttempt.notAppliedRetryAuthorizedAt
      ? 'resolution-postcondition-retry-v2'
      : 'resolution';
  writeProgress({
    step: 'pdd-resolution-submitting',
    pddResolutionSubmission: {
      ...(submissionForAttempt.orderNumber === decision.orderNumber ? submissionForAttempt : {}),
      shopId,
      orderNumber: decision.orderNumber,
      outcome: expectedOutcome,
      secondaryReason: flow.secondaryReason,
      tertiaryOutcome: flow.tertiaryOutcome,
      flowCode,
      retryCount: Number(submissionForAttempt.retryCount || 0),
      submitAttemptCount: previousSubmitAttemptCount,
      submitEffectStage,
      status: 'submitting',
      startedAt: new Date().toISOString(),
    },
  });
  // For the shipped-no-tracking branch this is the second and final submit;
  // all other branches have only this one submit.
  let state;
  try {
    state = await guardedExternalEffect({
      effectType: 'pdd-submit',
      orderNumber: decision.orderNumber,
      stage: submitEffectStage,
      request: {
        flowCode,
        expectedOutcome,
        secondaryReason: flow.secondaryReason,
        tertiaryOutcome: flow.tertiaryOutcome,
        submitAttemptNumber: previousSubmitAttemptCount + 1,
      },
    }, async () => {
      const submitResult = await clickPddSubmit(targetPage, 'resolution', decision.orderNumber, {
        guard: false,
        selectedPddOption: expectedOutcome,
        beforeClick: () => {
          const beforeClickSubmission = readProgress().pddResolutionSubmission || {};
          writeProgress({
            pddResolutionSubmission: {
              ...beforeClickSubmission,
              submitAttemptCount: previousSubmitAttemptCount + 1,
              lastClickAttemptedAt: new Date().toISOString(),
            },
          });
        },
        settleUntil: async () => {
          if (!isPddDetailUrl(targetPage.url())) return true;
          if (await firstVisible([
            targetPage.locator('[role="dialog"]:visible'),
            targetPage.locator('.beast-core-modal:visible, .ant-modal:visible'),
          ])) return true;
          const state = await readPddResolutionState(
            targetPage,
            decision.orderNumber,
            { timeoutMs: 2000 },
          ).catch(() => null);
          if (state?.isCompleted) return true;
          if (flowCode === 'intercept-progress' && expectedOutcome === '快递还在拦截中') {
            if (state?.isPending && state.completedOutcome === expectedOutcome) return true;
            const visibleOptions = await listVisibleOrdinaryPddOptions([
              targetPage.locator('main'),
              targetPage.locator('body'),
            ]);
            return resolvePddInTransitPageVariant(visibleOptions, readProgress())?.flowCode
              === 'consumer-negotiation-followup';
          }
          return false;
        },
      });
      let submittedState = await readPddResolutionState(targetPage, decision.orderNumber);
      if (!submittedState.isCompleted && !submittedState.isPending
        && (!submittedState.orderNumber || !submittedState.isExpectedWorkOrderType)) {
        const reopened = await reopenPddDetailForResolution(targetPage, decision.orderNumber, readProgress());
        submittedState = hasConfirmedPendingListAbsence(readProgress(), decision.orderNumber)
          ? completedPddStateFromPendingListAbsence(decision.orderNumber)
          : await readPddResolutionState(reopened, decision.orderNumber);
      }
      if (!submittedState.isCompleted) {
        const confirmationDialog = await firstVisible([
          targetPage.locator('[role="dialog"]:visible'),
          targetPage.locator('.beast-core-modal:visible, .ant-modal:visible'),
        ]);
        if (confirmationDialog) {
          const dialogText = await confirmationDialog.innerText().catch(() => '');
          if (dialogText && !dialogText.includes(expectedOutcome) && flowCode === 'primary-refund') {
            throw new Error('拼多多最终确认弹窗未显示预期处理结果');
          }
          const confirm = await firstVisible([
            confirmationDialog.getByRole('button', { name: /^(?:确认|确定|确认提交)$/ }),
            confirmationDialog.getByText(/^(?:确认|确定|确认提交)$/, { exact: true }),
          ]);
          if (!confirm) throw new Error('拼多多最终确认弹窗未找到确认按钮');
          await pacedAction(targetPage, 'confirm-pdd-resolution', () => confirm.click(), { retryOnRateLimit: true });
          await waitForPddSubmitTransition(targetPage, 'confirm-resolution', async () => {
            if (!isPddDetailUrl(targetPage.url())) return true;
            const state = await readPddResolutionState(
              targetPage,
              decision.orderNumber,
              { timeoutMs: 2000 },
            ).catch(() => null);
            return Boolean(state?.isCompleted);
          });
        }
      }
      return {
        ...await readPddResolutionState(targetPage, decision.orderNumber),
        submitReceipt: submitResult?.submitReceipt || null,
        transitionConfirmed: submitResult?.transitionConfirmed === true,
      };
    });
  } catch (error) {
    // A submitForm response with 43001 means the platform rejected the
    // request because the PDD session expired.  The click was sent, but the
    // platform did not accept the submission, so this is safe to retry after
    // the shop is logged in again.  Route it through the normal login gate
    // instead of leaving the work order in permanent manual review.
    if (error instanceof PddSubmitRejectedError
      && (Number(error.errorCode) === 43001
        || /会话已过期|登录状态.*(?:过期|失效)|请重新登录/u.test(
          String(error.errorMsg || error.message || ''),
        ))) {
      const loginRequired = recordPddLoginRequired(
        targetPage,
        {
          stage: 'pdd-resolution-submit',
          reason: '拼多多提交返回会话已过期，重新登录后自动重试',
        },
      );
      loginRequired.externalEffectStatus = 'failed';
      loginRequired.externalEffectReceipt = error.externalEffectReceipt || null;
      loginRequired.pddSessionExpiry = {
        errorCode: Number(error.errorCode) || null,
        errorMessage: error.errorMsg || error.message || null,
      };
      throw loginRequired;
    }
    if (error instanceof PddSubmitRejectedError) {
      const rejectedAt = new Date().toISOString();
      const currentSubmission = readProgress().pddResolutionSubmission || {};
      const explicitUnshippedRejection = isExplicitPddUnshippedRejection(error);
      const rejectedOutcomeLabels = normalizePddInTransitRejectedOutcomes([
        ...(currentSubmission.rejectedOutcomeLabels || []),
        expectedOutcome,
      ]);
      const canTryNextInTransitOutcome = inTransitRefundDecision
        && flowCode === 'primary-refund'
        && isPddInTransitOutcomeNotApplicableRejection(error);
      const visibleOptionsAfterRejection = canTryNextInTransitOutcome
        ? await listVisibleOrdinaryPddOptions([
          targetPage.locator('main'),
          targetPage.locator('body'),
        ])
        : [];
      const nextInTransitOutcome = canTryNextInTransitOutcome
        ? resolvePddInTransitRefundOutcome(
          visibleOptionsAfterRejection,
          rejectedOutcomeLabels,
        )
        : null;
      const rejectionReceipts = [
        ...(Array.isArray(currentSubmission.rejectedOutcomeReceipts)
          ? currentSubmission.rejectedOutcomeReceipts
          : []),
        {
          outcome: expectedOutcome,
          rejectedAt,
          receipt: error.externalEffectReceipt,
        },
      ].slice(-pddInTransitRefundOutcomePriority.length);
      writeProgress({
        pddResolutionSubmission: {
          ...currentSubmission,
          status: explicitUnshippedRejection
            ? 'waiting-for-shipment'
            : nextInTransitOutcome
              ? 'outcome-rejected-fallback-ready'
              : 'submit-rejected',
          submitAttemptCount: nextInTransitOutcome
            ? previousSubmitAttemptCount + 1
            : previousSubmitAttemptCount,
          lastRejectedAt: rejectedAt,
          lastRejectedResponse: error.externalEffectReceipt,
          ...(canTryNextInTransitOutcome ? {
            rejectedOutcomeLabels,
            rejectedOutcomeReceipts: rejectionReceipts,
            nextOutcome: nextInTransitOutcome,
            outcomeFallbackAuthorizedAt: nextInTransitOutcome ? rejectedAt : null,
          } : {}),
        },
      });
      if (nextInTransitOutcome) {
        return submitPddResolution(targetPage, decision);
      }
      if (explicitUnshippedRejection) {
        throw new LogisticsRetryRequiredError(
          'pdd-awaiting-shipment',
          '拼多多明确返回订单未发货，等待实际发货后再提交处理结果',
          unshippedRetryMs,
          {
            orderNumber: decision.orderNumber,
            detailUrl: targetPage.url(),
            scenarioCode: decision.scenarioCode,
            workOrderType: decision.workOrderType,
          },
        );
      }
    }
    throw error;
  }
  if (shouldStartPddConsumerNegotiationWait({ flowCode, expectedOutcome, pageState: state })) {
    const submittedAt = new Date().toISOString();
    const followup = resolvePddConsumerNegotiationFollowup(
      { completedAt: submittedAt },
      Date.parse(submittedAt),
    );
    const currentSubmission = readProgress().pddResolutionSubmission || {};
    const followupFlow = {
      ...flow,
      flowCode: 'consumer-negotiation-followup',
      primaryOutcome: expectedOutcome,
      interceptProgressOutcome: expectedOutcome,
    };
    writeProgress({
      step: 'pdd-consumer-negotiation-followup-waiting',
      pddResolutionFlow: followupFlow,
      pddResolutionSubmission: {
        ...currentSubmission,
        status: 'followup-waiting',
        outcome: expectedOutcome,
        flowCode: 'consumer-negotiation-followup',
        interceptProgressOutcome: expectedOutcome,
        interceptProgressSubmittedAt: submittedAt,
        consumerResponseWaitStartedAt: followup.startedAt,
        consumerResponseNextAttemptAt: followup.nextAttemptAt,
      },
      error: null,
      manualReview: null,
    });
    throw new LogisticsRetryRequiredError(
      'pdd-consumer-negotiation-waiting',
      '拼多多已确认快递仍在拦截中，进入消费者协商等待；满 12 小时仍无回复后再自动处理',
      followup.retryAfterMs,
      {
        orderNumber: decision.orderNumber,
        detailUrl: targetPage.url(),
        nextAttemptAt: followup.nextAttemptAt,
      },
    );
  }
  return { ...state, flowCode, expectedOutcome };
};

const isPddDetailUrl = (url) => Boolean(parsePlatformWorkOrderId(url));

const pddListEmptyStatePattern = /(?:暂无数据|暂无工单|暂无待处理|暂无相关|暂时没有|当前没有待处理)/u;

const findVisiblePendingOrder = async (targetPage, orderNumber) => {
  const exactOrder = targetPage.getByText(orderNumber, { exact: true });
  const count = await exactOrder.count().catch(() => 0);
  for (let index = 0; index < count; index++) {
    const candidate = exactOrder.nth(index);
    if (!await candidate.isVisible().catch(() => false)) continue;
    try {
      await locateWorkOrderAction(candidate);
      return candidate;
    } catch { /* the exact text is not a rendered actionable result row */ }
  }
  return null;
};

const completedOrdinaryListRow = async (candidate, orderNumber) => candidate.evaluate((element, expectedOrder) => {
  const visible = (node) => {
    const rect = node.getBoundingClientRect();
    const style = getComputedStyle(node);
    return rect.width > 0 && rect.height > 0
      && style.display !== 'none' && style.visibility !== 'hidden';
  };
  if (!visible(element)) return null;
  for (let row = element.parentElement; row && row !== document.body; row = row.parentElement) {
    const text = String(row.innerText || '');
    const orders = text.match(/\b\d{6}-\d{12,}\b/gu) || [];
    // Never borrow the status from a neighbouring case, including two cases
    // belonging to the same order. This row is only a hint to read exact detail.
    if (orders.length > 1) return null;
    if (orders.length !== 1 || orders[0] !== expectedOrder) continue;
    const actions = [...row.querySelectorAll('a,button,[role="button"],span,div')]
      .filter((node) => visible(node) && /^(?:立即查看|查看详情)$/u.test((node.innerText || '').trim()));
    if (!actions.length) continue;
    if (/(?:处理进度|工单状态|处理结果)[\s\S]{0,100}(?:已完结|已完成|已处理)/u.test(text)
      || /【已完结】/u.test(text)) {
      return { orderNumber: expectedOrder, rowText: text.slice(0, 2500),
        source: 'rendered-single-order-row', requiresExactDetail: true };
    }
  }
  return null;
}, orderNumber).catch(() => null);

const inspectOrdinaryListRenderState = async (targetPage, {
  orderNumber = null,
  previousSignature = null,
} = {}) => {
  if (await hasVisiblePddLoadingState(targetPage)) return null;
  if (orderNumber) {
    const pendingTarget = await findVisiblePendingOrder(targetPage, orderNumber);
    if (pendingTarget) return { kind: 'items', pending: true, target: pendingTarget };

    const exactOrder = targetPage.getByText(orderNumber, { exact: true });
    const exactCount = Math.min(20, await exactOrder.count().catch(() => 0));
    for (let index = 0; index < exactCount; index += 1) {
      const candidate = exactOrder.nth(index);
      if (!await candidate.isVisible().catch(() => false)) continue;
      const completedRow = await completedOrdinaryListRow(candidate, orderNumber);
      if (completedRow) {
        return {
          kind: 'completion-candidate',
          pending: false,
          target: candidate,
          confirmationMethod: 'exact-order-completed',
          completedRow,
        };
      }
    }
  }

  if (orderNumber) {
    const inputs = targetPage.locator('input:visible');
    const inputCount = Math.min(30, await inputs.count().catch(() => 0));
    let exactQueryVisible = false;
    for (let index = 0; index < inputCount; index += 1) {
      if (await inputs.nth(index).inputValue().catch(() => '') === orderNumber) {
        exactQueryVisible = true;
        break;
      }
    }
    if (exactQueryVisible) {
      const pageText = await targetPage.locator('body').innerText({ timeout: 5000 }).catch(() => '');
      if (hasExactPddOrderQueryEmptyResult(pageText)) {
        return { kind: 'empty', pending: false, confirmationMethod: 'exact-order-zero-result' };
      }
    }
    return null;
  }

  const emptyState = await firstVisible([
    targetPage.getByText(pddListEmptyStatePattern),
  ]);
  if (emptyState) return { kind: 'empty', pending: false };

  const signature = await ordinaryListPageSignature(targetPage);
  if (signature && (!previousSignature || signature !== previousSignature)) {
    return { kind: 'items', signature };
  }
  return null;
};

const waitForOrdinaryListRenderState = async (targetPage, {
  stage,
  orderNumber = null,
  previousSignature = null,
  onRefresh = null,
  confirmEmptyAfterRefresh = false,
} = {}) => {
  const refreshTargetUrl = targetPage.url().includes('mms.pinduoduo.com')
    ? targetPage.url()
    : listUrl;
  return waitForPddRenderedResult(targetPage, {
    stage,
    timeoutMs: pddRenderWaitMs,
    onVerification: (page, verificationStage) => checkForHumanVerification(page, verificationStage),
    beforeReload: (page) => clickVisiblePddStalePageRefresh(page, {
      cooldownMs: 0,
      settleMs: 700,
    }),
    inspect: (page) => inspectOrdinaryListRenderState(page, { orderNumber, previousSignature }),
    refreshOnInitialResult: confirmEmptyAfterRefresh
      ? (result) => result?.pending === false
      : null,
    onRefresh: async (page) => {
      await ensurePddLogin(page, context, refreshTargetUrl);
      await closeDeviceAccessIfPrompted(page);
      await checkForHumanVerification(page, `${stage}-after-refresh`);
      if (!orderNumber) {
        await ensurePddPendingListFilter(page, { beforeAction: checkForHumanVerification });
      }
      await onRefresh?.(page);
    },
  });
};

const ensureOrdinaryListQueryControls = async (targetPage, stagePrefix) => {
  await ensurePddLogin(targetPage, context, listUrl);
  if (!targetPage.url().includes('/aftersales/work_order/list')) {
    await pacedAction(
      targetPage,
      `open-${stagePrefix}-ordinary-list`,
       () => navigateSystemPage(targetPage, listUrl, `open-${stagePrefix}-ordinary-list`),
      { retryOnRateLimit: true },
    );
  }
  return waitForPddRenderedResult(targetPage, {
    stage: `${stagePrefix}-ordinary-list-query-controls`,
    timeoutMs: pddRenderWaitMs,
    onVerification: (page, verificationStage) => checkForHumanVerification(
      page,
      verificationStage,
    ),
    beforeReload: (page) => clickVisiblePddStalePageRefresh(page, {
      cooldownMs: 0,
      settleMs: 700,
    }),
    inspect: async (page) => {
      const orderInput = page.getByPlaceholder('请输入订单编号', { exact: true });
      const queryButton = page.getByRole('button', { name: '查询', exact: true });
      const [inputVisible, buttonVisible] = await Promise.all([
        orderInput.isVisible().catch(() => false),
        queryButton.isVisible().catch(() => false),
      ]);
      return inputVisible && buttonVisible ? { ready: true } : null;
    },
    onRefresh: async (page) => {
      await ensurePddLogin(page, context, listUrl);
      if (!page.url().includes('/aftersales/work_order/list')) {
         await navigateSystemPage(page, listUrl, `${stagePrefix}-ordinary-list-refresh`);
      }
      await closeDeviceAccessIfPrompted(page);
      await checkForHumanVerification(page, `${stagePrefix}-ordinary-list-query-controls-after-refresh`);
    },
  });
};

const submitPendingOrderQuery = async (targetPage, orderNumber, stagePrefix) => {
  await ensureOrdinaryListQueryControls(targetPage, stagePrefix);
  await ensurePddAllListStatuses(targetPage, { beforeAction: checkForHumanVerification });
  const orderInput = targetPage.getByPlaceholder('请输入订单编号', { exact: true });
  await pacedAction(targetPage, `fill-${stagePrefix}-order-query`, () => orderInput.fill(orderNumber));
  await pacedAction(
    targetPage,
    `submit-${stagePrefix}-order-query`,
    () => targetPage.getByRole('button', { name: '查询', exact: true }).click(),
    { retryOnRateLimit: true },
  );
};

const queryPendingOrderPresence = async (targetPage, orderNumber) => {
  await ensurePddLogin(targetPage, context, listUrl);
  await submitPendingOrderQuery(targetPage, orderNumber, 'completion');
  const state = await waitForOrdinaryListRenderState(targetPage, {
    stage: '普通工单完结查询渲染',
    orderNumber,
    onRefresh: (page) => submitPendingOrderQuery(page, orderNumber, 'completion-refresh'),
  });
  // A completed list row is still present and needs its own detail proof.
  // It must never become a synthetic zero-result confirmation.
  return state.pending === true || state.confirmationMethod === 'exact-order-completed';
};

const confirmOrderAbsentFromPendingList = async (targetPage, orderNumber) => {
  for (let attempt = 1; attempt <= 2; attempt++) {
    if (await queryPendingOrderPresence(targetPage, orderNumber)) return false;
    if (attempt < 2) await targetPage.waitForTimeout(actionDelayFor(targetPage, 'pdd-completion-query'));
  }
  return true;
};

const completedPddStateFromPendingListAbsence = (orderNumber) => ({
  isCompleted: true,
  isPending: false,
  orderMatches: true,
  orderNumber,
  completedOutcome: null,
  confirmationMethod: 'absent-from-pending-list',
});

const hasConfirmedPendingListAbsence = (progress, orderNumber) => Boolean(
  progress?.pddResolutionPendingListPresence?.orderNumber === orderNumber
  && progress.pddResolutionPendingListPresence.present === false
  && progress.pddResolutionPendingListPresence.refreshed === true
  && progress.pddResolutionPendingListPresence.exactShopIdentity === true
  && [
    'two-pass-exact-order-query',
    'exact-order-zero-result',
  ].includes(progress.pddResolutionPendingListPresence.confirmationMethod),
);

const readCompletedOrdinaryListDetail = async (orderNumber, listState) => {
  const progress = readProgress();
  const detailUrl = verifiedPddDetailRecoveryUrl(progress, orderNumber);
  if (!detailUrl) {
    throw new ManualReviewRequiredError('ordinary-list-completion-unverified',
      '列表显示已完结，但缺少本单平台工单编号，禁止归档或重新提交');
  }
  const detailPage = await openSavedPddDetailPage(detailUrl);
  await closeDeviceAccessIfPrompted(detailPage);
  await checkForHumanVerification(detailPage, 'ordinary-list-completion-detail');
  const state = await waitForPddResolutionDetail(detailPage, orderNumber, {
    readTimeoutMs: 10000,
    settleMs: Math.max(pddDetailSettleMs, 15000),
  });
  const observedAt = new Date().toISOString();
  const proof = legacyResolutionCompletionObservation(
    state, progress.platformWorkOrderId, observedAt,
  );
  if (!proof.valid || proof.observation?.platformCaseMatches !== true
    || state.isExpectedWorkOrderType !== true
    || !await capturePddShopIdentity(detailPage).catch(() => false)) {
    await pauseForManualReview(detailPage, 'ordinary-list-completion-unverified',
      '列表已完结提示未被同店同单同平台工单的完成详情证实，禁止归档或重新提交', {
        ordinaryListCompletionDetailProof: { orderNumber,
          expectedPlatformWorkOrderId: progress.platformWorkOrderId,
          observedPlatformWorkOrderId: state.observedPlatformWorkOrderId || null,
          listRow: listState?.completedRow || null, confirmed: false, observedAt },
      });
  }
  writeProgress({
    detailUrl: detailPage.url(),
    ordinaryListCompletionDetailProof: { orderNumber,
      expectedPlatformWorkOrderId: progress.platformWorkOrderId,
      observedPlatformWorkOrderId: state.observedPlatformWorkOrderId,
      listRow: listState?.completedRow || null, confirmed: true,
      platformCompletionObservation: proof.observation,
      completedOutcome: state.completedOutcome || null,
      workOrderStatus: state.workOrderStatus || null, observedAt },
  });
  return { page: detailPage, state: { ...state,
    confirmationMethod: 'detail-completed', recoveredFromCompletedPage: true } };
};

const refreshPddResolutionStateOnce = async (targetPage, orderNumber) => {
  if (!isPddDetailUrl(targetPage.url())) {
    return readPddResolutionState(targetPage, orderNumber);
  }
  const detailUrl = targetPage.url();
  writeProgress({
    step: 'pdd-resolution-confirmation-refreshing',
    pddResolutionConfirmationRefresh: {
      orderNumber,
      detailUrl,
      refreshedAt: new Date().toISOString(),
    },
  });
  await pacedAction(targetPage, 'refresh-pdd-resolution-confirmation', () => navigateSystemPage(
    targetPage,
    detailUrl,
    'refresh-pdd-resolution-confirmation',
  ), { retryOnRateLimit: true });
  await closeDeviceAccessIfPrompted(targetPage);
  await checkForHumanVerification(targetPage, 'pdd-resolution-confirmation-refresh');
  return waitForPddResolutionDetail(targetPage, orderNumber, {
    readTimeoutMs: 10000,
    settleMs: pddSubmitSettleMs,
  });
};

const confirmPddCompletionWithoutResubmit = async (targetPage, orderNumber, initialState = null) => {
  let state = initialState || await readPddResolutionState(targetPage, orderNumber);
  if (state.isCompleted) {
    return { ...state, confirmationMethod: state.confirmationMethod || 'detail-completed' };
  }

  state = await refreshPddResolutionStateOnce(targetPage, orderNumber);
  if (state.isCompleted) {
    return { ...state, confirmationMethod: 'refreshed-detail-completed' };
  }

  const absent = await confirmOrderAbsentFromPendingList(targetPage, orderNumber);
  if (absent) {
    return {
      ...state,
      isCompleted: true,
      isPending: false,
      orderMatches: true,
      orderNumber,
      confirmationMethod: 'absent-from-pending-list',
    };
  }
  return {
    ...state,
    confirmedNotApplied: true,
    confirmationMethod: 'present-in-pending-list',
  };
};

function buildPddSubmissionReconciliationObservation({
  pageState,
  orderNumber,
  previousSubmission,
  expectedPlatformWorkOrderId = null,
  observedAt = new Date().toISOString(),
}) {
  const submitAttemptCount = Math.max(1, Number(previousSubmission?.submitAttemptCount || 0));
  const maximumAutomaticSubmitAttempts = Math.max(
    1,
    Number(previousSubmission?.maximumAutomaticSubmitAttempts || 2),
  );
  const lastClickAttemptedAtMs = Date.parse(previousSubmission?.lastClickAttemptedAt || '');
  const currentAttemptStartedAtMs = Date.parse(previousSubmission?.startedAt || '');
  const clickAttemptRecorded = previousSubmission?.externalEffectStatus === 'unknown'
    || (Number.isFinite(lastClickAttemptedAtMs)
      ? (!Number.isFinite(currentAttemptStartedAtMs)
        || lastClickAttemptedAtMs >= currentAttemptStartedAtMs)
      : previousSubmission?.submitClicked === true);
  if (pageState.isCompleted) {
    const confirmationMethod = pageState.confirmationMethod || 'detail-completed';
    const detailObservation = pageState.detailReady === true
      && pageState.isExpectedWorkOrderType === true
      && ['detail-completed', 'refreshed-detail-completed'].includes(confirmationMethod)
      ? renderedOrdinaryCompletionObservation(
        { ...pageState, confirmationMethod }, observedAt, expectedPlatformWorkOrderId,
      ) : null;
    return {
      state: 'confirmed',
      effectType: 'pdd-submit',
      orderNumber,
      confirmationMethod,
      completionEvidence: pageState.completedOutcome || null,
      ...(detailObservation?.platformCaseMatches === true
        ? { platformCompletionObservation: detailObservation } : {}),
      observedAt,
      readOnly: true,
    };
  }
  if (pageState.isPending
    && previousSubmission?.outcome
    && pageState.completedOutcome === previousSubmission.outcome) {
    return {
      state: 'confirmed',
      effectType: 'pdd-submit',
      orderNumber,
      confirmationMethod: 'pending-detail-outcome-transition',
      completionEvidence: pageState.completedOutcome,
      transitionedToNextStage: true,
      observedAt,
      readOnly: true,
    };
  }
  if (pageState.confirmedNotApplied
    && !clickAttemptRecorded
    && submitAttemptCount < maximumAutomaticSubmitAttempts) {
    return {
      state: 'not-applied',
      effectType: 'pdd-submit',
      orderNumber,
      confirmationMethod: 'present-in-pending-list',
      submitAttemptCount,
      maximumAutomaticSubmitAttempts,
      pageState,
      observedAt,
      readOnly: true,
    };
  }
  return {
    state: 'unresolved',
    effectType: 'pdd-submit',
    orderNumber,
    confirmationMethod: null,
    pageState,
    submitAttemptCount,
    maximumAutomaticSubmitAttempts,
    automaticRetryExhausted: pageState.confirmedNotApplied
      && submitAttemptCount >= maximumAutomaticSubmitAttempts,
    automaticRetryBlockedByClickAttempt: pageState.confirmedNotApplied
      && clickAttemptRecorded,
    observedAt,
    readOnly: true,
  };
}

function protectPddPostSubmitReadOnlyObservation({
  submissionObservation,
  pageState,
  reconciliationTarget,
}) {
  if (reconciliationTarget?.protectedReadOnly !== true) return submissionObservation;
  const exactCompletedDetail = pageState.isCompleted === true
    && pageState.orderMatches === true
    && pageState.detailReady === true
    && ['detail-completed', 'refreshed-detail-completed']
      .includes(submissionObservation.confirmationMethod);
  const submittedOption = String(reconciliationTarget.submittedOption || '').trim();
  const completedOption = String(submissionObservation.completionEvidence || '').trim();
  if (submissionObservation.state !== 'not-applied'
    && (submissionObservation.state !== 'confirmed'
      || (exactCompletedDetail
        && (!completedOption || completedOption === submittedOption)))) {
    return submissionObservation.state === 'confirmed'
      ? { ...submissionObservation, protectedReadOnlyExactDetail: true }
      : submissionObservation;
  }
  return {
    ...submissionObservation,
    state: 'unresolved',
    confirmationMethod: null,
    protectedReadOnlyReason: 'exact-completed-detail-not-proven-or-outcome-mismatch',
    automaticRetryBlockedByPriorSubmit: true,
  };
}

const reconcileOmsManualAllocationState = async (targetPage, orderNumber) => {
  await ensureOmsOrderManagementPage(targetPage, context);
  const { rowScope, omsApiOrderState } = await queryOmsOrderRow(targetPage, orderNumber);
  const apiOrderStatus = omsOrderStatusFromApiState(omsApiOrderState);
  const orderStatus = apiOrderStatus || await readOmsOrderStatus(targetPage, rowScope);
  const checkedAt = new Date().toISOString();
  const confirmed = omsApiOrderStateHasPassedAllocation(omsApiOrderState)
    || omsOrderStatusHasPassedAllocation(orderStatus);
  const observation = {
    state: confirmed ? 'confirmed' : 'unresolved',
    effectType: 'oms-manual-allocation',
    orderNumber,
    orderStatus,
    omsApiOrderState,
    confirmationMethod: confirmed
      ? (apiOrderStatus ? 'oms-order-api-state-read-back' : 'oms-order-status-read-back')
      : null,
    observedAt: checkedAt,
    readOnly: true,
  };
  const progress = readProgress();
  writeProgress({
    step: confirmed ? 'oms-manual-allocation-reconciled' : 'external-state-unresolved',
    externalStateReconciliation: observation,
    ...(confirmed ? {
      omsAnalysis: {
        ...progress.omsAnalysis,
        orderStatus,
      },
      omsManualAllocation: {
        ...progress.omsManualAllocation,
        shopId,
        orderNumber,
        status: 'succeeded',
        verifiedOrderStatus: orderStatus,
        reconciledAt: checkedAt,
      },
    } : {}),
    currentUrl: targetPage.url(),
    error: null,
  });
  return observation;
};

const reconcileOmsReissueCreateState = async (targetPage, orderNumber) => {
  const progress = readProgress();
  const persistedOriginalCode = String(
    progress.ordinaryReissueCreation?.originalSalesOrderCode || '',
  ).trim();
  const originalSalesOrderCode = /^SO[0-9A-Z-]{6,40}$/u.test(persistedOriginalCode)
    ? persistedOriginalCode
    : null;
  const passes = [];
  let confirmedReissue = null;
  for (let pass = 1; pass <= 2; pass += 1) {
    const observation = await inspectOmsReissueQueryPass(
      targetPage,
      context,
      orderNumber,
      pass,
    );
    passes.push(observation);
    confirmedReissue = observation.reissueRows.find((row) => (
      row.salesOrderCode && row.salesOrderCode !== originalSalesOrderCode
    )) || null;
    if (confirmedReissue) break;
    if (pass < 2) {
      await targetPage.reload({ waitUntil: 'domcontentloaded', timeout: 45_000 }).catch(() => {});
    }
  }

  const soleOriginalCodes = passes.map((pass) => {
    const apiCode = pass.apiRows.length === 1 ? pass.apiRows[0].salesOrderCode : null;
    const domCode = pass.domRows.length === 1 ? pass.domRows[0].salesOrderCode : null;
    if (!apiCode) return null;
    if (pass.domRows.length === 0) return apiCode;
    return pass.domRows.length === 1 && domCode === apiCode ? apiCode : null;
  });
  const stableOriginalCode = soleOriginalCodes.length === 2
    && soleOriginalCodes.every(Boolean)
    && soleOriginalCodes[0] === soleOriginalCodes[1]
    ? soleOriginalCodes[0]
    : null;
  const definitelyNotApplied = !confirmedReissue
    && passes.length === 2
    && passes.every((pass) => (
      pass.queryResponseCaptured
      && pass.queryResponseOk
      && pass.queryInputValue === orderNumber
      && pass.apiRows.length === 1
      && pass.reissueRows.length === 0
      && pass.apiTotal === 1
      && (pass.domRows.length === 0 || (
        pass.domRows.length === 1
        && pass.domRows[0].salesOrderCode === pass.apiRows[0].salesOrderCode
      ))
    ))
    && Boolean(stableOriginalCode)
    && (!originalSalesOrderCode || stableOriginalCode === originalSalesOrderCode);
  const checkedAt = new Date().toISOString();
  const state = confirmedReissue
    ? 'confirmed'
    : definitelyNotApplied
      ? 'not-applied'
      : 'unresolved';
  const resolvedOriginalCode = originalSalesOrderCode || stableOriginalCode || null;
  const reissueOrder = confirmedReissue ? {
    orderNumber,
    salesOrderCode: confirmedReissue.salesOrderCode,
    trackingNumber: confirmedReissue.trackingNumber || null,
    status: confirmedReissue.trackingNumber ? 'tracking-ready' : 'created',
    createdAt: checkedAt,
    reconciledAt: checkedAt,
  } : null;
  if (reissueOrder) {
    updateOrdinaryExecution(orderNumber, ORDINARY_SCENARIO_CODES.DELIVERY_RISK_CONCERN, {
      reissueOrder,
    });
  }
  const observation = {
    state,
    effectType: 'oms-reissue-create',
    orderNumber,
    originalSalesOrderCode: resolvedOriginalCode,
    ...(reissueOrder ? {
      salesOrderCode: reissueOrder.salesOrderCode,
      trackingNumber: reissueOrder.trackingNumber,
      reissueOrder,
    } : {}),
    confirmationMethod: state === 'confirmed'
      ? 'oms-exact-order-reissue-row-read-back'
      : state === 'not-applied'
        ? 'two-pass-exact-oms-order-query-single-original-row'
        : null,
    queryPasses: passes,
    observedAt: checkedAt,
    readOnly: true,
    externalActionsReplayed: false,
  };
  const latestProgress = readProgress();
  writeProgress({
    step: state === 'confirmed'
      ? 'oms-reissue-create-reconciled'
      : state === 'not-applied'
        ? 'oms-reissue-create-not-applied'
        : 'external-state-unresolved',
    externalStateReconciliation: observation,
    ordinaryReissueCreation: {
      ...(latestProgress.ordinaryReissueCreation || {}),
      orderNumber,
      originalSalesOrderCode: resolvedOriginalCode,
      status: state === 'confirmed'
        ? 'succeeded'
        : state === 'not-applied'
          ? 'retry-authorized'
          : 'unresolved',
      ...(reissueOrder ? { reissueOrder } : {}),
      reconciledAt: checkedAt,
    },
    currentUrl: targetPage.url(),
    error: null,
  });
  return observation;
};

const reconcilePddExternalState = async (targetPage, orderNumber) => {
  const checkedAt = new Date().toISOString();
  if (reconcileExternalEffectTypes.has('pdd-note')
    && !reconcileExternalEffectTypes.has('pdd-submit')) {
    const remarkPolicy = pddOrderRemarkPolicyFor(readProgress().scenarioCode || activeScenarioCode);
    let remarkPage = targetPage;
    const inspectRemark = () => inspectPddOrderRemark({
      targetPage: remarkPage,
      orderNumber,
      remarkText: remarkPolicy.text,
      colorLabel: remarkPolicy.color,
      timeoutMs: pddRenderWaitMs,
      action: (name, callback, options) => pacedAction(remarkPage, name, callback, options),
      onVerification: (page) => checkForHumanVerification(
        page,
        'pdd-order-remark-reconciliation',
      ),
    });
    let remarkObservation;
    try {
      remarkObservation = await inspectRemark();
    } catch (error) {
      const retryableRenderFailure = /订单信息区域未找到查看详情|订单详情未在限定时间内完成渲染|locator\.(?:waitFor|click): Timeout/iu
        .test(String(error?.message || error || ''));
      if (!retryableRenderFailure) throw error;
      writeProgress({
        step: 'pdd-note-reconciliation-refreshing',
        pddNoteReconciliationRenderRecovery: {
          orderNumber,
          attempt: 1,
          maxAttempts: 2,
          previousError: error.message,
          refreshedAt: new Date().toISOString(),
        },
        error: null,
      });
      await pacedAction(remarkPage, 'refresh-pdd-note-reconciliation', () => remarkPage.reload({
        waitUntil: 'domcontentloaded',
        timeout: pddRenderWaitMs,
      }));
      await closeDeviceAccessIfPrompted(remarkPage);
      await checkForHumanVerification(remarkPage, 'pdd-order-remark-reconciliation-refreshed');
      if (remarkPage.url().includes('/aftersales/work_order/list')) {
        await ensurePddLogin(remarkPage, context, listUrl);
        await submitPendingOrderQuery(remarkPage, orderNumber, 'note-reconciliation');
        const queryState = await waitForOrdinaryListRenderState(remarkPage, {
          stage: '备注核对普通工单精确查询渲染',
          orderNumber,
          confirmEmptyAfterRefresh: true,
          onRefresh: (page) => submitPendingOrderQuery(
            page,
            orderNumber,
            'note-reconciliation-refresh',
          ),
        });
        const current = readProgress();
        const identity = current.pddShopIdentity || {};
        const actualShopName = normalizePddShopNameCandidate(
          identity.mallName || identity.actualShopName,
        );
        const configuredIdentity = canonicalPddShopIdentityName(expectedShopName);
        const actualIdentity = canonicalPddShopIdentityName(actualShopName);
        const exactShopIdentity = identity.status === 'detected'
          && configuredIdentity
          && actualIdentity
          && pddIdentityMatches(configuredPddIdentityNames, [
            actualShopName,
            identity.mallName,
            identity.headerShopName,
            identity.identityNames,
          ])
          && !isMaskedPddShopIdentityName(actualShopName);
        const confirmationMethod = queryState.confirmationMethod
          || (queryState.refreshed === true ? 'two-pass-exact-order-query' : null);
        const pendingListPresence = {
          orderNumber,
          present: queryState.pending === true,
          refreshed: queryState.refreshed === true,
          confirmationMethod: queryState.pending === true
            ? 'rendered-exact-order-query'
            : confirmationMethod,
          exactShopIdentity: Boolean(exactShopIdentity),
          actualShopName: actualShopName || null,
          expectedShopName: expectedShopName || null,
          confirmedAt: new Date().toISOString(),
        };
        writeProgress({
          ordinaryPendingListPresence: pendingListPresence,
          pddResolutionPendingListPresence: pendingListPresence,
          ...(queryState.pending === true ? {} : { detailUrl: null }),
        });
        if (queryState.pending === true) {
          const exactOrder = queryState.target
            || remarkPage.getByText(orderNumber, { exact: true }).first();
          const action = await locateWorkOrderAction(exactOrder);
          const openedPage = await openPddDetailWithoutForegroundPopup(
            remarkPage,
            action,
            'reopen-pdd-note-reconciliation-work-order',
            { retryOnRateLimit: true },
          );
          remarkPage = openedPage ? await adoptPddDetailPage(openedPage) : remarkPage;
          if (!remarkPage.url().includes('/aftersales/work_order/tododetail')) {
            await remarkPage.waitForURL('**/aftersales/work_order/tododetail**', {
              timeout: pddRenderWaitMs,
            });
          }
          await remarkPage.waitForLoadState('domcontentloaded').catch(() => {});
          writeProgress({
            step: 'pdd-note-reconciliation-detail-reopened',
            detailUrl: remarkPage.url(),
            error: null,
          });
          remarkObservation = await inspectRemark();
        } else {
          if (!exactShopIdentity) {
            throw new Error(`备注核对精确查询为空，但当前拼多多店铺身份未精确确认: ${orderNumber}`);
          }
          if (queryState.refreshed !== true
            || !['two-pass-exact-order-query', 'exact-order-zero-result']
              .includes(confirmationMethod)) {
            throw new Error(`备注核对精确查询为空，但尚未取得刷新后的精确零结果: ${orderNumber}`);
          }
          remarkObservation = {
            state: 'not-applied',
            orderNumber,
            remarkText: remarkPolicy.text,
            colorLabel: remarkPolicy.color,
            observedText: '',
            observedColor: null,
            detailMode: 'refreshed-exact-pending-list-absence',
            confirmationMethod: 'refreshed-exact-pending-list-absence',
            completionDetected: true,
            readOnly: true,
            observedAt: new Date().toISOString(),
          };
        }
      } else {
        remarkObservation = await inspectRemark();
      }
    }
    const observation = {
      ...remarkObservation,
      effectType: 'pdd-note',
      confirmationMethod: remarkObservation.confirmationMethod
        || (remarkObservation.state === 'confirmed'
        ? 'order-remark-read-back'
        : remarkObservation.state === 'not-applied'
          ? 'order-remark-absent'
          : null),
    };
    const reconciledRemark = observation.state === 'confirmed'
      ? {
        ...readProgress().pddOrderRemark,
        shopId,
        orderNumber,
        text: remarkPolicy.text,
        color: remarkPolicy.color,
        status: 'saved',
        detailMode: observation.detailMode || 'reconciled',
        alreadySucceeded: true,
        savedAt: observation.observedAt || checkedAt,
        reconciliationMethod: observation.confirmationMethod,
      }
      : null;
    writeProgress({
      step: observation.state === 'confirmed'
        ? 'pdd-order-remark-reconciled'
        : observation.state === 'not-applied'
          ? 'pdd-order-remark-not-applied'
          : 'external-state-unresolved',
      externalStateReconciliation: observation,
      ...(reconciledRemark ? { pddOrderRemark: reconciledRemark } : {}),
      pddNoteReconciliationRenderRecovery: null,
      currentUrl: remarkPage.url(),
      error: null,
    });
    logRunStep('external-state-reconciled', { orderNumber, externalStateReconciliation: observation });
    return observation;
  }
  let pageState = await ensurePddResolutionDetailReady(targetPage, orderNumber, readProgress(), {
    allowUnresolved: true,
    readTimeoutMs: 5000,
    settleMs: 10000,
  });
  if (!pageState.isCompleted) {
    pageState = await confirmPddCompletionWithoutResubmit(targetPage, orderNumber, pageState);
  }
  const progress = readProgress();
  const evidenceUploadOnlyReconciliation = reconcileExternalEffectTypes.has('evidence-upload')
    && !reconcileExternalEffectTypes.has('pdd-submit');
  const pddStateOnlyReconciliation = reconcileExternalEffectTypes.size === 0;
  const reconciliationTarget = progress.externalStateReconciliationTarget?.effectType === 'pdd-submit'
    ? progress.externalStateReconciliationTarget
    : null;
  const previousSubmission = progress.pddResolutionSubmission?.orderNumber === orderNumber
    ? {
        ...progress.pddResolutionSubmission,
        externalEffectStatus: reconciliationTarget?.status
          || progress.pddResolutionSubmission.externalEffectStatus || null,
      }
    : reconciliationTarget
      ? {
          orderNumber,
          submitAttemptCount: Number(reconciliationTarget.submitAttemptCount || 1),
          maximumAutomaticSubmitAttempts: Number(
            reconciliationTarget.maximumAutomaticSubmitAttempts || 2
          ),
          effectId: reconciliationTarget.effectId || null,
          idempotencyKey: reconciliationTarget.idempotencyKey || null,
          externalEffectStatus: reconciliationTarget.status || null,
        }
      : null;
  const submissionObservation = buildPddSubmissionReconciliationObservation({
      pageState,
      orderNumber,
      previousSubmission,
      expectedPlatformWorkOrderId: progress.platformWorkOrderId,
      observedAt: checkedAt,
    });
  const protectedObservation = protectPddPostSubmitReadOnlyObservation({
    submissionObservation, pageState, reconciliationTarget,
  });
  const observation = {
    ...protectedObservation,
    ...(evidenceUploadOnlyReconciliation ? {
      effectType: 'evidence-upload',
      reconciliationKind: 'pdd-detail-read-only-after-evidence-upload-unknown',
    } : pddStateOnlyReconciliation ? {
      effectType: 'pdd-state',
      reconciliationKind: 'pdd-detail-state-only-read-back',
    } : {}),
    ...(reconciliationTarget ? {
      effectId: reconciliationTarget.effectId || null,
      idempotencyKey: reconciliationTarget.idempotencyKey || null,
    } : {}),
  };
  const submitAttemptCount = observation.submitAttemptCount
    || Math.max(1, Number(previousSubmission?.submitAttemptCount || 0));
  writeProgress({
    step: observation.state === 'confirmed'
      ? 'external-state-confirmed'
      : observation.state === 'not-applied'
        ? evidenceUploadOnlyReconciliation
          ? 'pdd-evidence-not-applied'
          : pddStateOnlyReconciliation
            ? 'pdd-state-not-applied'
          : 'pdd-submit-not-applied'
        : 'external-state-unresolved',
    externalStateReconciliation: observation,
    ...(observation.state === 'confirmed' ? {
      pddResolutionSubmission: {
        shopId,
        orderNumber,
        outcome: pageState.completedOutcome
          || readProgress().pddResolutionSubmission?.outcome
          || readProgress().pddResolutionDecision?.outcome
          || null,
        status: 'succeeded',
        recoveredFromCompletedPage: true,
        completionEvidence: observation.completionEvidence,
        confirmationMethod: observation.confirmationMethod,
        ...(observation.platformCompletionObservation
          ? { platformCompletionObservation: observation.platformCompletionObservation } : {}),
        completedAt: observation.observedAt,
      },
    } : observation.state === 'not-applied'
      ? evidenceUploadOnlyReconciliation
        ? {
            pddEvidenceUpload: {
              ...(progress.pddEvidenceUpload || {}),
              shopId,
              orderNumber,
              status: 'retry-authorized',
              notAppliedAt: observation.observedAt,
              retryAuthorizedAt: observation.observedAt,
              confirmationMethod: observation.confirmationMethod,
              recoverySource: 'cross-shop-pdd-evidence-read-only',
            },
            crossShopPddEvidenceReadOnlyRecovery: {
              ...(progress.crossShopPddEvidenceReadOnlyRecovery || {}),
              status: 'pending-confirmed',
              confirmationMethod: observation.confirmationMethod,
              observedAt: observation.observedAt,
              externalActionsReplayed: false,
            },
            manualReview: null,
          }
        : pddStateOnlyReconciliation
          ? {
              pddResolutionSubmission: null,
              crossShopLegacyPddReadOnlyRecovery: {
                ...(progress.crossShopLegacyPddReadOnlyRecovery || {}),
                status: 'pending-page-confirmed',
                confirmationMethod: observation.confirmationMethod,
                observedAt: observation.observedAt,
                externalActionsReplayed: false,
              },
              manualReview: null,
            }
          : {
              pddResolutionSubmission: {
                ...previousSubmission,
                shopId,
                orderNumber,
                status: 'retry-authorized',
                submitAttemptCount,
                maximumAutomaticSubmitAttempts: observation.maximumAutomaticSubmitAttempts || 2,
                notAppliedAt: observation.observedAt,
                notAppliedRetryAuthorizedAt: observation.observedAt,
                confirmationMethod: observation.confirmationMethod,
              },
              manualReview: null,
            }
      : {}),
    currentUrl: targetPage.url(),
    error: null,
  });
  logRunStep('external-state-reconciled', { orderNumber, externalStateReconciliation: observation });
  return observation;
};

const reopenPddDetailForResolution = async (
  targetPage,
  orderNumber,
  progress,
  { forcePendingList = false } = {},
) => {
  writeProgress({ pddResolutionPendingListPresence: null });
  if (!forcePendingList && isPddDetailUrl(targetPage.url())) {
    const currentState = await ensurePddResolutionDetailReady(
      targetPage,
      orderNumber,
      progress,
      {
        allowUnresolved: true,
        readTimeoutMs: Math.min(pddRenderWaitMs, 10_000),
        settleMs: pddRenderWaitMs,
      },
    );
    if (currentState.detailReady && currentState.orderMatches) {
      writeProgress({
        pddResolutionDetailReuse: {
          orderNumber,
          detailUrl: targetPage.url(),
          confirmationMethod: currentState.confirmationMethod || 'rendered-detail-order-match',
          reusedAt: new Date().toISOString(),
        },
      });
      return targetPage;
    }
    writeProgress({
      pddResolutionDetailReuse: {
        orderNumber,
        detailUrl: targetPage.url(),
        status: 'fallback-to-exact-pending-query',
        checkedAt: new Date().toISOString(),
      },
    });
  }
  if (!forcePendingList && progress.detailUrl && targetPage.url() !== progress.detailUrl) {
    await pacedAction(targetPage, 'return-to-pdd-detail', () => navigateSystemPage(
      targetPage,
      progress.detailUrl,
      'return-to-pdd-detail',
    ));
    await targetPage.waitForLoadState('domcontentloaded', { timeout: 30000 }).catch(() => {});
    const savedState = await waitForPddResolutionDetail(targetPage, orderNumber, {
      settleMs: Math.max(pddDetailSettleMs, 15000),
    });
    if (savedState.detailReady && savedState.orderMatches) return targetPage;
  }

  // A saved detail URL can expire or redirect to the queue. Reopen the exact
  // order from the current pending list instead of trying to click resolution
  // controls on the list page.
  writeProgress({
    step: 'pdd-resolution-detail-reopening',
    pddResolutionDetailReopen: {
      orderNumber,
      staleUrl: targetPage.url(),
      startedAt: new Date().toISOString(),
    },
  });
  if (targetPage !== pddPage && derivedPages.has(targetPage) && !targetPage.isClosed()) {
    await closeDerivedPage(targetPage);
  }
  await focusSystemPage('pdd', pddPage);
  await ensurePddLogin(pddPage, context, listUrl);
  if (!pddPage.url().includes('/aftersales/work_order/list')) {
    await pacedAction(pddPage, 'restore-pdd-list-for-resolution', () => navigateSystemPage(
      pddPage,
      listUrl,
      'restore-pdd-list-for-resolution',
    ));
  }
  await waitForPddRenderedResult(pddPage, {
    stage: '普通工单详情恢复列表渲染',
    timeoutMs: pddRenderWaitMs,
    onVerification: (page, verificationStage) => checkForHumanVerification(
      page,
      verificationStage,
    ),
    beforeReload: (page) => clickVisiblePddStalePageRefresh(page, {
      cooldownMs: 0,
      settleMs: 700,
    }),
    inspect: async (page) => {
      const orderInput = page.getByPlaceholder('请输入订单编号', { exact: true });
      const queryButton = page.getByRole('button', { name: '查询', exact: true });
      const [inputVisible, buttonVisible] = await Promise.all([
        orderInput.isVisible().catch(() => false),
        queryButton.isVisible().catch(() => false),
      ]);
      return inputVisible && buttonVisible ? { ready: true } : null;
    },
    onRefresh: async (page) => {
      await ensurePddLogin(page, context, listUrl);
      await closeDeviceAccessIfPrompted(page);
      await checkForHumanVerification(page, '普通工单详情恢复列表渲染-after-refresh');
    },
  });
  await submitPendingOrderQuery(pddPage, orderNumber, 'resolution');
  const queryState = await waitForOrdinaryListRenderState(pddPage, {
    stage: '普通工单详情恢复查询渲染',
    orderNumber,
    confirmEmptyAfterRefresh: true,
    onRefresh: (page) => submitPendingOrderQuery(
      page,
      orderNumber,
      'resolution-refresh',
    ),
  });
  const current = readProgress();
  const identity = current.pddShopIdentity || {};
  const actualShopName = normalizePddShopNameCandidate(
    identity.mallName || identity.actualShopName,
  );
  const configuredIdentity = canonicalPddShopIdentityName(expectedShopName);
  const actualIdentity = canonicalPddShopIdentityName(actualShopName);
  const exactShopIdentity = identity.status === 'detected'
    && configuredIdentity
    && actualIdentity
    && pddIdentityMatches(configuredPddIdentityNames, [
      actualShopName,
      identity.mallName,
      identity.headerShopName,
      identity.identityNames,
    ])
    && !isMaskedPddShopIdentityName(actualShopName);
  const identityEvidence = {
    exactShopIdentity: Boolean(exactShopIdentity),
    actualShopName: actualShopName || null,
    expectedShopName: expectedShopName || null,
  };
  if (queryState.confirmationMethod === 'exact-order-completed') {
    const completedDetail = await readCompletedOrdinaryListDetail(orderNumber, queryState);
    return completedDetail.page;
  }
  if (queryState.pending !== true) {
    writeProgress({
      step: 'pdd-resolution-absent-from-pending-list',
      pddResolutionPendingListPresence: {
        orderNumber,
        present: false,
        refreshed: queryState.refreshed === true,
        confirmationMethod: queryState.confirmationMethod || 'two-pass-exact-order-query',
        ...identityEvidence,
        confirmedAt: new Date().toISOString(),
      },
    });
    return pddPage;
  }
  const exactOrder = queryState.target
    || pddPage.getByText(orderNumber, { exact: true }).first();
  writeProgress({
    pddResolutionPendingListPresence: {
      orderNumber,
      present: true,
      refreshed: queryState.refreshed === true,
      confirmationMethod: 'rendered-exact-order-query',
      ...identityEvidence,
      confirmedAt: new Date().toISOString(),
    },
  });
  const action = await locateWorkOrderAction(exactOrder);
  const openedPage = await openPddDetailWithoutForegroundPopup(
    pddPage,
    action,
    'reopen-resolution-work-order',
    { retryOnRateLimit: true },
  );
  const detailPage = openedPage ? await adoptPddDetailPage(openedPage) : pddPage;
  await detailPage.waitForURL('**/aftersales/work_order/tododetail**', { timeout: 45000 });
  await detailPage.waitForLoadState('domcontentloaded').catch(() => {});
  return detailPage;
};

const isDefinitivePddStateChangedRejection = (error) => (
  error instanceof PddSubmitRejectedError
  && /工单状态发生变动.*刷新重试/u.test(String(error.errorMsg || error.message || ''))
);

const isTransientPddResolutionStateChangedRejection = (error) => (
  isDefinitivePddStateChangedRejection(error)
  && error.stage === 'subjective-reason'
);

const isRecoverablePddResolutionFormError = (error) => (
  isPddEvidenceUploadAuthorizationError(error)
  || error instanceof PddSubmitButtonRenderError
  || isTransientPddResolutionStateChangedRejection(error)
  || /未找到|未保持选中|无法唯一识别|缺少必选|最终处理结果/.test(String(error?.message || ''))
);

const submitPddResolutionWithRefreshRecovery = async (targetPage, decision) => {
  const existingRecovery = readProgress().pddResolutionRecovery;
  const matchingRecovery = existingRecovery?.orderNumber === decision.orderNumber
    ? existingRecovery
    : null;
  let failures = Array.isArray(matchingRecovery?.failures) ? [...matchingRecovery.failures] : [];
  let maxAttempts = Number(matchingRecovery?.maxAttempts || 2);

  while (true) {
    try {
      targetPage = await preparePddResolutionSubmissionPage(targetPage, decision);
      const result = await submitPddResolution(targetPage, decision, { prepared: true });
      if (failures.length) {
        writeProgress({
          pddResolutionRecovery: {
            ...readProgress().pddResolutionRecovery,
            orderNumber: decision.orderNumber,
            status: 'succeeded',
            attempts: failures.length + 1,
            maxAttempts,
            recoveredAt: new Date().toISOString(),
          },
        });
      }
      return result;
    } catch (error) {
      if (error instanceof PddWorkOrderAlreadyCompletedError
        && error.completedState?.orderMatches) {
        writeProgress({
          step: 'pdd-resolution-completed-while-waiting-submit',
          pddResolutionRecovery: {
            orderNumber: decision.orderNumber,
            status: 'completed-before-submit',
            confirmationMethod: error.completedState.confirmationMethod || 'detail-completed',
            completedAt: new Date().toISOString(),
          },
          error: null,
        });
        return {
          ...error.completedState,
          recoveredFromCompletedPage: true,
        };
      }
      if (!isRecoverablePddResolutionFormError(error)) throw error;
      const progress = readProgress();
      const submission = progress.pddResolutionSubmission;
      const submitClickNotAttempted = error instanceof PddSubmitButtonRenderError
        && error.externalEffectReceipt?.clickAttempted === false;
      const finalSubmitStarted = submission?.orderNumber === decision.orderNumber
        && ['submitting', 'succeeded', 'manual-review-blocked'].includes(submission.status)
        && !submitClickNotAttempted;
      if (finalSubmitStarted) throw error;

      if (submitClickNotAttempted && submission?.orderNumber === decision.orderNumber) {
        writeProgress({
          pddResolutionSubmission: {
            ...submission,
            status: 'render-retry',
            submitButtonRenderFailedAt: new Date().toISOString(),
          },
        });
      }

      if (isPddEvidenceUploadAuthorizationError(error)
        || isTransientPddResolutionStateChangedRejection(error)) {
        maxAttempts = Math.max(maxAttempts, 3);
      }
      failures.push({
        attempt: failures.length + 1,
        code: error.code || 'PDD_RESOLUTION_FORM_ERROR',
        message: error.message,
        failedAt: new Date().toISOString(),
        uploadAuthorizationFailure: error.pddEvidenceUploadAuthorizationFailure || null,
      });
      const canRetry = failures.length < maxAttempts;
      writeProgress({
        step: canRetry ? 'pdd-resolution-recovery-waiting' : 'pdd-resolution-recovery-exhausted',
        pddResolutionRecovery: {
          orderNumber: decision.orderNumber,
          status: canRetry ? 'waiting' : 'exhausted',
          attempts: failures.length,
          maxAttempts,
          failures,
          lastError: error.message,
          lastErrorCode: error.code || null,
          updatedAt: new Date().toISOString(),
        },
      });
      if (!canRetry) {
        const resultStageRenderFailure = error instanceof PddSubmitButtonRenderError
          || /拼多多(?:未找到|处理页面无法唯一识别|缺少必选|最终处理结果)/u
            .test(String(error?.message || error || ''));
        if (resultStageRenderFailure) {
          const transientCode = error instanceof PddSubmitButtonRenderError
            ? 'PDD_ORDINARY_SUBMIT_RENDER_TEMPORARILY_UNAVAILABLE'
            : 'PDD_ORDINARY_RESULT_STAGE_TEMPORARILY_UNAVAILABLE';
          const originalMessage = String(error.message || error);
          error.code = transientCode;
          error.message = `${transientCode}: ${originalMessage}`;
          error.externalEffectStatus = 'failed';
          error.externalEffectReceipt = {
            ...(error.externalEffectReceipt || {}),
            clickAttempted: false,
            reason: 'pdd-resolution-controls-not-rendered-after-refresh',
            attempts: failures.length,
            maxAttempts,
          };
          writeProgress({
            step: 'pdd-resolution-controls-retry-ready',
            pddResolutionRecovery: {
              ...readProgress().pddResolutionRecovery,
              status: 'retry-ready',
              retryAfterMs: 30_000,
              transientCode,
              retryReadyAt: new Date().toISOString(),
            },
            manualReview: null,
            error: null,
          });
        }
        throw error;
      }

      console.warn(`[PDD表单自动恢复] ${decision.orderNumber} 第 ${failures.length}/${maxAttempts} 次处理失败，刷新详情页后重试：${error.message}`);
      const detailUrl = progress.detailUrl || targetPage.url();
      await targetPage.waitForTimeout(Math.min(Math.max(actionDelayFor(targetPage, 'pdd-submit-recovery'), 500), 2000));
      try {
        await targetPage.reload({ waitUntil: 'domcontentloaded', timeout: 45000 });
      } catch {
        await navigateSystemPage(targetPage, detailUrl, 'recover-pdd-resolution-form');
      }
      await closeDeviceAccessIfPrompted(targetPage);
      await checkForHumanVerification(targetPage, 'recover-pdd-resolution-form');
      await ensurePddResolutionDetailReady(targetPage, decision.orderNumber, readProgress());
      writeProgress({
        step: 'pdd-resolution-recovery-retrying',
        pddResolutionRecovery: {
          ...readProgress().pddResolutionRecovery,
          status: 'retrying',
          nextAttempt: failures.length + 1,
          lastRetryAt: new Date().toISOString(),
        },
      });
    }
  }
};

const ordinaryExecutionFor = (orderNumber, scenarioCode) => {
  const current = readProgress().ordinaryScenarioExecution;
  const platformCaseKey = activePlatformCaseKey || readProgress().platformCaseKey || null;
  if (current?.orderNumber !== orderNumber
    || current?.scenarioCode !== scenarioCode
    || (platformCaseKey && current?.platformCaseKey && current.platformCaseKey !== platformCaseKey)) {
    return {
      shopId,
      orderNumber,
      scenarioCode,
      platformCaseKey,
      startedAt: new Date().toISOString(),
    };
  }
  return current;
};

const updateOrdinaryExecution = (orderNumber, scenarioCode, patch) => {
  const updated = {
    ...ordinaryExecutionFor(orderNumber, scenarioCode),
    ...patch,
    shopId,
    orderNumber,
    scenarioCode,
    platformCaseKey: activePlatformCaseKey || readProgress().platformCaseKey || null,
    updatedAt: new Date().toISOString(),
  };
  writeProgress({ ordinaryScenarioExecution: updated });
  return updated;
};

const ordinaryTimelineFromAnalysis = (analysis = {}) => (
  (analysis.timelineRecords || analysis.traceRecords || []).map((record) => ({
    text: record.trace || record.text || '',
    occurredAt: record.timestamp || record.occurredAt || null,
    city: record.city || null,
  }))
);

const capturePddScenarioEvidenceScreenshot = async (targetPage, orderNumber, purpose) => {
  const absolutePath = expectedEvidencePath(orderNumber);
  const relativePath = toPortableRelativePath(workflowDataDir, absolutePath);
  try {
    const pageText = await targetPage.locator('body').innerText({ timeout: 15_000 });
    const pageOrderNumber = parsePddOrderNumber(pageText);
    if (pageOrderNumber !== orderNumber) {
      throw new Error(`场景截图页面订单编号不一致: 期望 ${orderNumber}，实际 ${pageOrderNumber || '未读取到'}`);
    }
    const buffer = await targetPage.screenshot({
      fullPage: false,
      type: 'png',
      animations: 'disabled',
      caret: 'hide',
    });
    const inspection = inspectPngBuffer(buffer, { minWidth: 500, minHeight: 300 });
    fs.mkdirSync(evidenceScreenshotDir, { recursive: true, mode: 0o700 });
    fs.writeFileSync(absolutePath, buffer, { mode: 0o600 });
    fs.chmodSync(absolutePath, 0o600);
    const metadata = {
      shopId,
      orderNumber,
      relativePath,
      mimeType: 'image/png',
      width: inspection.width,
      height: inspection.height,
      sizeBytes: inspection.sizeBytes,
      createdAt: new Date().toISOString(),
      status: 'ready',
      purpose,
    };
    writeProgress({ pddEvidenceScreenshot: metadata, step: 'pdd-scenario-evidence-ready' });
    return metadata;
  } catch (error) {
    writeProgress({
      step: 'pdd-scenario-evidence-failed',
      pddEvidenceScreenshot: {
        shopId,
        orderNumber,
        relativePath,
        mimeType: 'image/png',
        status: 'failed',
        purpose,
        failedAt: new Date().toISOString(),
        error: error.message,
      },
    });
    await saveWorkflowDiagnostics(targetPage, 'pdd-scenario-evidence-failed', error).catch(() => {});
    throw error;
  }
};

const openPddLogisticsKind = async (targetPage, label) => {
  const findTab = () => firstVisible([
    targetPage.getByRole('tab', { name: label, exact: true }),
    targetPage.getByText(label, { exact: true }),
  ]);
  const tabWaitMs = Math.max(1_000, Math.min(30_000, pddRenderWaitMs));
  const waitForTab = async () => {
    const deadline = Date.now() + tabWaitMs;
    do {
      await checkForHumanVerification(targetPage, `pdd-${label}-tab-render`);
      const tab = await findTab();
      if (tab) return tab;
      const remainingMs = deadline - Date.now();
      if (remainingMs > 0) await targetPage.waitForTimeout(Math.min(250, remainingMs));
    } while (Date.now() < deadline);
    return null;
  };
  const waitUntilReady = async (tab, previousBody) => {
    const deadline = Date.now() + Math.min(pddRenderWaitMs, pddLogisticsSettleMs);
    do {
      await checkForHumanVerification(targetPage, `pdd-${label}-render`);
      if (!await hasVisiblePddLoadingState(targetPage)) {
        const [selected, body] = await Promise.all([
          tab.evaluate((element) => {
            const className = String(element.className || '');
            const control = element.matches('input') ? element : element.querySelector('input');
            return element.getAttribute('aria-selected') === 'true'
              || element.getAttribute('data-state') === 'active'
              || /(?:^|[-_\s])(active|selected|checked)(?:$|[-_\s])/i.test(className)
              || Boolean(control?.checked);
          }).catch(() => false),
          targetPage.locator('body').innerText({ timeout: 2_000 }).catch(() => ''),
        ]);
        const hasLogisticsResult = /\u5feb\u9012\u516c\u53f8|\u5feb\u9012\u5355\u53f7|\u7269\u6d41\u8f68\u8ff9|\u6682\u65e0[^\n]{0,12}\u7269\u6d41/u.test(body);
        if (selected || hasLogisticsResult || (previousBody && body !== previousBody)) return true;
      }
      const remainingMs = deadline - Date.now();
      if (remainingMs > 0) await targetPage.waitForTimeout(Math.min(250, remainingMs));
    } while (Date.now() < deadline);
    return false;
  };
  const openOnce = async () => {
    const tab = await waitForTab();
    if (!tab) return { found: false, ready: false };
    const previousBody = await targetPage.locator('body').innerText({ timeout: 2_000 }).catch(() => '');
    await runPddShippingAction(targetPage, `open-${label === '退货物流' ? 'return' : 'shipping'}-logistics`, () => (
      tab.click({ force: true })
    ));
    return { found: true, ready: await waitUntilReady(tab, previousBody) };
  };
  let attempt = await openOnce();
  // The logistics panel is rendered asynchronously and can be replaced after
  // a verification/login refresh. Give the same tab a bounded second chance
  // before classifying the shop as failed; this avoids abandoning otherwise
  // valid shortage/refund work on a transient panel render.
  // PDD occasionally keeps the tab selected while its logistics payload is
  // still being fetched. Allow a few bounded read-only refreshes so a
  // transient render miss does not prematurely pause an otherwise valid
  // work order. Each retry revalidates login/detail identity before reading.
  for (let retry = 0; !attempt.ready && retry < 4; retry += 1) {
    const detailUrl = targetPage.url();
    await targetPage.waitForTimeout(1_000 * (retry + 1));

    // When PDD presents its "page stayed too long" modal, use the modal's
    // central refresh action first. A full reload can discard the currently
    // selected logistics tab and turn a recoverable render delay into a
    // false external-system pause. The existing reload remains the bounded
    // fallback when the modal is absent or its action is unavailable.
    const stalePageRefresh = await clickVisiblePddStalePageRefresh(targetPage, {
      cooldownMs: 0,
      settleMs: 700,
    }).catch(() => ({ handled: false }));
    if (stalePageRefresh.handled) {
      logRunStep('pdd-logistics-stale-page-refresh-clicked', {
        label,
        retry: retry + 1,
        beforeUrl: stalePageRefresh.beforeUrl,
        afterUrl: stalePageRefresh.afterUrl,
      });
      await ensurePddLogin(targetPage, context, detailUrl);
      await ensurePddResolutionDetailReady(targetPage, readProgress().orderNumber, readProgress());
      attempt = await openOnce();
      continue;
    }

    await targetPage.reload({ waitUntil: 'domcontentloaded', timeout: 45_000 });
    await ensurePddLogin(targetPage, context, detailUrl);
    await ensurePddResolutionDetailReady(targetPage, readProgress().orderNumber, readProgress());
    attempt = await openOnce();
  }
  if (!attempt.found) {
    throw new Error(`拼多多刷新并等待 ${tabWaitMs} 毫秒后仍未找到“${label}”标签，已停止读取物流，避免误用其他物流区域`);
  }
  if (!attempt.ready) throw new Error(`拼多多“${label}”在刷新后仍未完成渲染`);
  const expand = await firstVisible([
    targetPage.getByText(/^(查看全部|全部展开|展开全部)$/, { exact: true }),
    targetPage.getByRole('button', { name: /查看全部|全部展开|展开全部/ }),
  ]);
  if (expand) {
    await runPddShippingAction(targetPage, `expand-${label === '退货物流' ? 'return' : 'shipping'}-logistics`, () => (
      expand.click({ force: true })
    ));
  }
  return true;
};

// A PDD detail page can finish its navigation while the selected logistics
// panel is still being replaced. Treat only that render miss as transient so
// the current order is released for a bounded retry instead of being left in
// flow-paused. Verification, login, rate-limit, and business errors keep their
// dedicated handling paths.
const openPddLogisticsKindWithRetry = async (
  targetPage,
  label,
  { orderNumber = null, scenarioCode = null, stagePrefix = 'pdd' } = {},
) => {
  try {
    return await openPddLogisticsKind(targetPage, label);
  } catch (error) {
    if (error instanceof HumanVerificationRequiredError
      || error instanceof PddLoginRequiredError
      || error instanceof RateLimitPauseError
      || error instanceof LogisticsRetryRequiredError) {
      throw error;
    }
    const message = String(error?.message || error || '');
    if (!/(?:物流|渲染|刷新|标签)/u.test(message)) throw error;
    throw new LogisticsRetryRequiredError(
      `${stagePrefix}-${label === '退货物流' ? 'return' : 'shipping'}-logistics-render`,
      `拼多多“${label}”暂未稳定渲染，30 秒后自动重查当前工单：${message}`,
      30_000,
      { orderNumber, scenarioCode, transientSystem: 'PDD' },
    );
  }
};

const collectReverseSignedRefundLogistics = async (readOpenLogistics) => {
  const returned = await readOpenLogistics('退货物流');
  const shipped = returned.hasData ? null : await readOpenLogistics('发货物流');
  const selected = returned.hasData ? returned : shipped || returned;
  return {
    returned,
    shipped,
    selected,
    returnLogisticsTimeline: returned.timeline,
    shippingLogisticsTimeline: shipped?.timeline || [],
    inspection: {
      returnLogisticsChecked: true,
      returnLogisticsHasData: returned.hasData,
      returnLogisticsRawNodeCount: returned.rawTimeline.length,
      returnLogisticsNodeCount: returned.timeline.length,
      returnLogisticsEmptyStateVisible: returned.emptyStateVisible,
      shippingLogisticsChecked: !returned.hasData,
      shippingLogisticsHasData: shipped?.hasData === true,
      shippingLogisticsRawNodeCount: shipped?.rawTimeline.length || 0,
      shippingLogisticsNodeCount: shipped?.timeline.length || 0,
      shippingLogisticsEmptyStateVisible: shipped?.emptyStateVisible === true,
      fallbackApplied: !returned.hasData,
    },
  };
};

let productShortageChatDbPoolPromise = null;
const readLatestChatAnalysis = async (currentShopId, currentOrderNumber, scenarioCode = null) => {
  if (!process.env.DATABASE_URL) return null;
  if (!productShortageChatDbPoolPromise) {
    productShortageChatDbPoolPromise = createPostgresPool(undefined, {
      max: 1,
      applicationName: 'pdd-workflow-chat-read',
    });
  }
  const pool = await productShortageChatDbPoolPromise;
  try {
    const result = await pool.query(`
      SELECT c.id AS "caseId", j.id AS "jobId", j.result,
        j.updated_at AS "updatedAt", x.id AS "snapshotId", x.payload AS "snapshotPayload"
      FROM chat_cases c
      JOIN chat_analysis_jobs j ON j.case_id = c.id AND j.status = 'analyzed'
      JOIN chat_snapshots x ON x.id = j.snapshot_id
      WHERE c.shop_id = $1 AND c.order_number = $2
        AND ($3::text IS NULL OR c.scenario_code = $3)
      ORDER BY j.updated_at DESC
      LIMIT 1`, [currentShopId, currentOrderNumber, scenarioCode]);
    return result.rows[0] || null;
  } finally {
    // A workflow child must be able to terminate after a non-resident run;
    // do not leave a PostgreSQL idle socket keeping the process alive.
    await pool.end().catch(() => {});
    productShortageChatDbPoolPromise = null;
  }
};

const readLatestProductShortageChatAnalysis = (currentShopId, currentOrderNumber) => (
  readLatestChatAnalysis(currentShopId, currentOrderNumber, ORDINARY_SCENARIO_CODES.PRODUCT_SHORTAGE)
);

const requestProductShortageChatRecollection = async (currentShopId, currentOrderNumber) => {
  if (!process.env.DATABASE_URL) return false;
  const pool = await createPostgresPool(undefined, {
    max: 1,
    applicationName: 'pdd-workflow-chat-recollect',
  });
  try {
    const result = await pool.query(`
      UPDATE chat_cases
      SET collect_requested = true, next_collect_at = now(), updated_at = now()
      WHERE shop_id = $1 AND order_number = $2
      RETURNING id`, [currentShopId, currentOrderNumber]);
    return result.rowCount > 0;
  } finally {
    await pool.end().catch(() => {});
  }
};

const ensureChatAnalysisCase = async (
  currentShopId,
  currentOrderNumber,
  { platformCaseKey, platformCaseId, detailUrl, scenarioCode = ORDINARY_SCENARIO_CODES.PRODUCT_SHORTAGE, workOrderType = null } = {},
) => {
  if (!process.env.DATABASE_URL) return false;
  const normalizedOrderNumber = String(currentOrderNumber || '').trim();
  if (!normalizedOrderNumber) return false;
  const normalizedCaseId = String(platformCaseId || '').trim() || null;
  const normalizedCaseKey = String(platformCaseKey || '').trim()
    || (normalizedCaseId ? `pdd-work-order:${normalizedCaseId}` : `pdd-work-order:${normalizedOrderNumber}`);
  const pool = await createPostgresPool(undefined, {
    max: 1,
    applicationName: 'pdd-workflow-chat-case-ensure',
  });
  try {
    const result = await pool.query(`
      INSERT INTO chat_cases(
        id, shop_id, order_number, platform_case_key, platform_case_id, detail_url,
        status, collect_requested, next_collect_at, updated_at, scenario_code, work_order_type
      ) VALUES($1,$2,$3,$4,$5,$6,'pending',true,now(),now(),$7,$8)
      ON CONFLICT(shop_id, platform_case_key) DO UPDATE SET
        detail_url=COALESCE(excluded.detail_url, chat_cases.detail_url),
        platform_case_id=COALESCE(excluded.platform_case_id, chat_cases.platform_case_id),
        collect_requested=CASE
          WHEN chat_cases.status IN ('collecting','analysis-pending','auto-ready','awaiting-owner-approval','owner-review','failed')
            THEN chat_cases.collect_requested
          ELSE true
        END,
        next_collect_at=CASE
          WHEN chat_cases.status IN ('collecting','analysis-pending','auto-ready','awaiting-owner-approval','owner-review','failed')
            THEN chat_cases.next_collect_at
          ELSE now()
        END,
        scenario_code=COALESCE(NULLIF(excluded.scenario_code, ''), chat_cases.scenario_code),
        work_order_type=COALESCE(NULLIF(excluded.work_order_type, ''), chat_cases.work_order_type),
        updated_at=now()
      RETURNING id`, [
      crypto.randomUUID(),
      currentShopId,
      normalizedOrderNumber,
      normalizedCaseKey,
      normalizedCaseId,
      String(detailUrl || '').trim() || null,
      String(scenarioCode || ORDINARY_SCENARIO_CODES.PRODUCT_SHORTAGE).trim(),
      String(workOrderType || '').trim() || null,
    ]);
    return result.rowCount > 0;
  } finally {
    await pool.end().catch(() => {});
  }
};

const ensureProductShortageChatCase = (currentShopId, currentOrderNumber, options = {}) => (
  ensureChatAnalysisCase(currentShopId, currentOrderNumber, {
    ...options,
    scenarioCode: ORDINARY_SCENARIO_CODES.PRODUCT_SHORTAGE,
  })
);

const collectOrdinaryScenarioFacts = async (detailPage, orderNumber, scenarioCode) => {
  recordOrdinaryPlatformIdentity(detailPage.url());
  const orderDetailText = await detailPage.locator('body').innerText({ timeout: 30_000 });
  const reverseSignedRefund = scenarioCode
    === ORDINARY_SCENARIO_CODES.REVERSE_LOGISTICS_SIGNED_REFUND;
  const logisticsEmptyStatePattern = /(?:暂无|无|未查到|查无|没有)(?:有效)?(?:退货|发货)?物流(?:信息|轨迹)?|待快递公司返回物流信息/u;
  let bodyText = '';
  let logisticsAnalysis = null;
  let timeline = [];
  let returnLogisticsTimeline = [];
  let shippingLogisticsTimeline = [];
  let reverseLogisticsInspection = null;
  const readOpenLogistics = async (label) => {
    await openPddLogisticsKindWithRetry(detailPage, label, {
      orderNumber,
      scenarioCode,
      stagePrefix: 'reverse-signed',
    });
    const text = await detailPage.locator('body').innerText({ timeout: 30_000 });
    const analysis = parseShippingAnalysis(text);
    const rawTimeline = ordinaryTimelineFromAnalysis(analysis);
    // body.innerText can contain empty-state text from unrelated order cards.
    // Parsed nodes from the currently selected, expanded logistics tab are the
    // authoritative proof that this logistics direction has usable data.
    const hasData = rawTimeline.length > 0;
    return {
      text,
      analysis,
      rawTimeline,
      timeline: hasData ? rawTimeline : [],
      hasData,
      emptyStateVisible: !hasData && logisticsEmptyStatePattern.test(text),
    };
  };
  if (scenarioCode === ORDINARY_SCENARIO_CODES.PROMISE_REISSUE) {
    // 承诺补寄只按 PDD 倒计时和 OMS 补发子订单判断，不读取发货物流轨迹。
    // 这样补发刚产生、尚无轨迹时也不会被错误阻塞。
    bodyText = orderDetailText;
    logisticsAnalysis = {
      orderNumber,
      carrier: null,
      trackingNumber: null,
      timelineRecords: [],
      recommendedCarriers: [],
      parserVersion: 0,
      source: 'promise-reissue-pdd-detail-only',
    };
  } else if (scenarioCode === ORDINARY_SCENARIO_CODES.PROACTIVE_LOGISTICS_SERVICE) {
    await openPddLogisticsKindWithRetry(detailPage, '退货物流', {
      orderNumber,
      scenarioCode,
      stagePrefix: 'ordinary-facts',
    });
    bodyText = await detailPage.locator('body').innerText({ timeout: 30_000 });
    logisticsAnalysis = parseShippingAnalysis(bodyText);
    timeline = ordinaryTimelineFromAnalysis(logisticsAnalysis);
    returnLogisticsTimeline = timeline;
    // Preserve the legacy generic timeline projection for this established flow.
    shippingLogisticsTimeline = timeline;
  } else if (reverseSignedRefund) {
    const reverseLogistics = await collectReverseSignedRefundLogistics(readOpenLogistics);
    const { selected } = reverseLogistics;
    returnLogisticsTimeline = reverseLogistics.returnLogisticsTimeline;
    shippingLogisticsTimeline = reverseLogistics.shippingLogisticsTimeline;
    bodyText = selected.text;
    logisticsAnalysis = selected.analysis;
    timeline = selected.timeline;
    reverseLogisticsInspection = reverseLogistics.inspection;
  } else {
    await openPddLogisticsKindWithRetry(detailPage, '发货物流', {
      orderNumber,
      scenarioCode,
      stagePrefix: 'ordinary-facts',
    });
    bodyText = await detailPage.locator('body').innerText({ timeout: 30_000 });
    logisticsAnalysis = parseShippingAnalysis(bodyText);
    timeline = ordinaryTimelineFromAnalysis(logisticsAnalysis);
    shippingLogisticsTimeline = timeline;
  }
  const pageOrderNumber = parsePddOrderNumber(bodyText);
  if (pageOrderNumber !== orderNumber) {
    throw new Error(`普通工单详情订单号不一致: 期望 ${orderNumber}，实际 ${pageOrderNumber || '未读取到'}`);
  }
  const execution = ordinaryExecutionFor(orderNumber, scenarioCode);
  const progress = readProgress();
  let chatAnalysis = null;
  if (chatPolicyForScenario(scenarioCode)) {
    try {
      const database = await readLatestChatAnalysis(shopId, orderNumber, scenarioCode);
      if (database) {
        chatAnalysis = {
          status: 'analyzed',
          caseId: database.caseId,
          jobId: database.jobId,
          snapshotId: database.snapshotId,
          messages: Array.isArray(database.snapshotPayload?.messages)
            ? database.snapshotPayload.messages
            : [],
          completeness: database.snapshotPayload?.completeness || null,
          conclusion: database.result?.analysis?.conclusion || 'unknown',
          analysis: database.result?.analysis || null,
          eligible: database.result?.policy?.eligible === true,
          policy: database.result?.policy || null,
          analyzedAt: database.updatedAt || null,
        };
      } else {
        chatAnalysis = { status: 'pending' };
      }
    } catch (error) {
      chatAnalysis = { status: 'pending', error: error.message };
    }
  }
  const omsAnalysis = progress.omsAnalysis?.orderNumber === orderNumber ? progress.omsAnalysis : null;
  const matchedTmsIdentity = progress.tmsDuplicateCheck?.status === 'matched'
    ? progress.tmsDuplicateCheck.identity || {}
    : {};
  const orderStatus = omsAnalysis?.orderStatus || progress.omsOrderStatus || null;
  const recommendedCarriers = (logisticsAnalysis.recommendedCarriers || []).length
    ? logisticsAnalysis.recommendedCarriers
    : logisticsAnalysis.carrier ? [logisticsAnalysis.carrier] : [];
  const visiblePhoneInputs = detailPage.locator('input:visible:not([type="hidden"])');
  let platformPrefilledPhone = execution.platformPrefilledPhone || null;
  for (let index = 0; !platformPrefilledPhone
    && index < await visiblePhoneInputs.count().catch(() => 0); index++) {
    const input = visiblePhoneInputs.nth(index);
    const value = String(await input.inputValue().catch(() => '')).trim();
    if (!isValidPlatformPrefilledPhone(value)) continue;
    const nearbyText = await input.evaluate((element) => (
      String(element.parentElement?.parentElement?.innerText || element.parentElement?.innerText || '')
    )).catch(() => '');
    if (/手机号|手机号码|联系电话/.test(nearbyText)) platformPrefilledPhone = value;
  }
  const explicitWorkOrderCreatedAt = bodyText.match(
    /(?:工单发起时间|工单创建时间|发起时间)\s*[:：]?\s*(20\d{2}[-/.年]\d{1,2}[-/.月]\d{1,2}(?:日)?\s+\d{1,2}:\d{2}(?::\d{2})?)/u,
  )?.[1] || null;
  const deliveryRiskProgress = scenarioCode === ORDINARY_SCENARIO_CODES.DELIVERY_RISK_CONCERN
    ? extractDeliveryRiskServiceProgress(bodyText)
    : null;
  const remainingDurationText = bodyText.match(
    /(?:剩余处理时长|剩余时间|距超时剩余|剩)\s*[:：]?\s*((?:\d+天)?\s*\d+时(?:\d+分)?(?:\d+秒)?|\d+(?:\.\d+)?\s*(?:小时|分钟))/u,
  )?.[1] || null;
  let feedbackPhoneChecked = execution.feedbackPhoneChecked === true;
  if (scenarioCode === ORDINARY_SCENARIO_CODES.GOOD_DEED_EXPEDITED_SHIPPING
    && !feedbackPhoneChecked) {
    const previewTiming = extractOrdinaryWorkOrderTiming({
      logisticsTimeline: timeline,
      remainingDuration: remainingDurationText,
      now: new Date(),
    });
    const pickedUp = detectPickedUpLogistics(timeline);
    if (pickedUp.status !== 'picked-up'
      && (previewTiming.remainingDurationMs === null
        || previewTiming.remainingDurationMs < 2 * 60 * 60_000)) {
      await closePddLogisticsOverlay(detailPage);
      const feedback = await prepareGoodDeedFeedback(detailPage, orderNumber, scenarioCode);
      platformPrefilledPhone = feedback.platformPrefilledPhone;
      feedbackPhoneChecked = true;
    }
  }
  const facts = {
    // The detail identity was verified above; downstream scenario guards need
    // the expected order as well as the rendered text to compare identities.
    orderNumber,
    bodyText,
    pageText: bodyText,
    orderDetailText,
    logisticsTimeline: timeline,
    shippingLogisticsTimeline,
    returnLogisticsTimeline,
    reverseLogisticsInspection,
    workOrderCreatedAt: execution.workOrderCreatedAt
      || progress.workOrderCreatedAt
      || explicitWorkOrderCreatedAt,
    workOrderFirstDiscoveredAt: activeWorkOrderFirstDiscoveredAt
      || progress.workOrderFirstDiscoveredAt
      || progress.latestDiscovery?.discoveredAt
      || progress.discoveredAt
      || null,
    remainingDuration: remainingDurationText,
    logisticsContactedAt: execution.logisticsContactedAt
      || deliveryRiskProgress?.logisticsContactedAt
      || null,
    logisticsPromiseAt: execution.logisticsPromiseAt
      || deliveryRiskProgress?.logisticsPromiseAt
      || null,
    deliveryRiskReminderResultRequired: deliveryRiskProgress?.resultRequired === true,
    deliveryRiskFinalResultRequired: deliveryRiskProgress?.finalResultRequired === true,
    deliveryRiskFinalResultPromptedAt: deliveryRiskProgress?.finalResultPromptedAt || null,
    warehouse: omsAnalysis?.shippingWarehouse || null,
    warehouseName: omsAnalysis?.shippingWarehouse || null,
    carrier: logisticsAnalysis.carrier || null,
    expressCompany: logisticsAnalysis.carrier || null,
    trackingNumber: logisticsAnalysis.trackingNumber || null,
    logisticsAnalysis,
    logisticsText: bodyText,
    omsLookupCompleted: Boolean(omsAnalysis),
    tmsLookupCompleted: execution.tmsLookupCompleted === true,
    omsTmsFlowCompleted: execution.omsTmsFlowCompleted === true,
    commonOmsTmsCompleted: execution.omsTmsFlowCompleted === true,
    completedPddStages: Array.isArray(execution.completedPddStages)
      ? execution.completedPddStages : [],
    consumerRefusalConfirmed: scenarioCode === ORDINARY_SCENARIO_CODES.CONSUMER_REFUSAL,
    tmsRecallCompleted: execution.tmsRecallCompleted === true,
    recallCompleted: execution.tmsRecallCompleted === true,
    tmsEvidenceReady: Boolean(progress.tmsEvidenceScreenshot?.status === 'ready'
      && progress.tmsEvidenceScreenshot.orderNumber === orderNumber),
    tmsEvidencePath: progress.tmsEvidenceScreenshot?.relativePath || null,
    tmsReplyResult: progress.tmsWorkOrder?.replyResult || null,
    tmsQuickReplyResult: progress.tmsWorkOrder?.quickReplyResult || null,
    tmsCarrierReply: progress.tmsWorkOrder?.carrierReply || null,
    tmsMatchedReplyResult: matchedTmsIdentity.values?.快递回复结果 || null,
    tmsMatchedTaskStatus: matchedTmsIdentity.values?.任务状态 || null,
    productShortageTmsResultText: execution.productShortageTmsResultText || null,
    productShortageTmsTaskStatus: execution.productShortageTmsTaskStatus || null,
    productShortageTmsResultCheckedAt: execution.productShortageTmsResultCheckedAt || null,
    omsAllocated: orderStatus
      ? omsOrderStatusHasPassedAllocation(orderStatus)
      : undefined,
    manualAllocationSupported: scenarioCode === ORDINARY_SCENARIO_CODES.GOOD_DEED_EXPEDITED_SHIPPING
      || recommendedCarriers.length > 0,
    carrierRuleDeterministic: scenarioCode === ORDINARY_SCENARIO_CODES.GOOD_DEED_EXPEDITED_SHIPPING
      || recommendedCarriers.length > 0,
    allowFirstAvailableCarrier: scenarioCode === ORDINARY_SCENARIO_CODES.GOOD_DEED_EXPEDITED_SHIPPING,
    reissueOrderCreated: execution.reissueOrder?.status === 'created'
      || execution.reissueOrder?.status === 'allocated'
      || execution.reissueOrder?.status === 'tracking-ready',
    reissueCreatedAt: execution.reissueOrder?.createdAt || null,
    reissueTrackingNumber: execution.reissueOrder?.trackingNumber || null,
    reissueTrackingLookupCompleted: execution.reissueTrackingLookupCompleted === true,
    reissueTrackingCheckedAt: execution.reissueOrder?.trackingCheckedAt || null,
    promiseReissueOms: progress.promiseReissueOms?.orderNumber === orderNumber
      ? progress.promiseReissueOms : null,
    platformLogisticsUpdateRejection: execution.platformLogisticsUpdateRejection || null,
    platformPrefilledPhone,
    feedbackPhoneChecked,
    pddEvidenceUploadFailed: execution.pddEvidenceUploadFailed === true
      || progress.ordinaryEvidenceUpload?.status === 'failed',
    chatAnalysis,
    pddFeedbackEntryAvailable: /(?:对此订单有疑问\s*[？?]?\s*点此反馈后自行处理|点此反馈自行处理)/u.test(orderDetailText),
    chatFollowupCheckedAt: execution.chatFollowupCheckedAt || null,
    orderAmount: (() => {
      const match = orderDetailText.match(/(?:订单金额|实付金额|支付金额|合计)\s*[:：]?\s*[¥￥]?(\d+(?:\.\d{1,2})?)/u);
      return match ? Number(match[1]) : null;
    })(),
  };
  const timing = extractOrdinaryWorkOrderTiming({ ...facts, now: new Date() });
  const nextExecution = updateOrdinaryExecution(orderNumber, scenarioCode, {
    workOrderCreatedAt: execution.workOrderCreatedAt || timing.workOrderCreatedAt || null,
    logisticsContactedAt: execution.logisticsContactedAt
      || deliveryRiskProgress?.logisticsContactedAt
      || null,
    logisticsPromiseAt: execution.logisticsPromiseAt
      || deliveryRiskProgress?.logisticsPromiseAt
      || null,
    remainingDuration: timing.remainingDurationMs,
    latestLogisticsAt: timing.latestLogisticsAt,
    earliestLogisticsAt: timing.earliestLogisticsAt,
    logisticsNodeCount: timing.logisticsNodeCount,
    platformPrefilledPhone,
    feedbackPhoneChecked,
  });
  const persistedFacts = {
    ...facts,
    workOrderCreatedAt: nextExecution.workOrderCreatedAt,
    remainingDurationMs: nextExecution.remainingDuration,
  };
  writeProgress({
    logisticsAnalysis: { ...logisticsAnalysis, orderNumber },
    ordinaryScenarioFacts: persistedFacts,
    step: 'ordinary-scenario-facts-collected',
  });
  return { facts: persistedFacts, logisticsAnalysis, timing };
};

const ordinaryFormScope = async (targetPage) => {
  const submit = await firstVisible([
    targetPage.locator('button').filter({ hasText: /^\s*提交\s*$/ }),
    targetPage.getByRole('button', { name: '提交', exact: true }),
  ]);
  if (!submit) return targetPage.locator('body');
  const form = submit.locator(
    'xpath=ancestor::*[.//*[@role="radio"] or .//input[@type="radio"] or .//textarea or .//input][1]',
  ).first();
  return await form.count().catch(() => 0) ? form : targetPage.locator('body');
};

const ordinaryPddDecisionEntryPattern = /^(?:立即处理|我已知晓|处理工单|开始处理|去处理|继续处理)$/u;

const normalizeOrdinaryPddOptionText = (value) => String(value || '')
  .normalize('NFKC')
  .replace(/[\s，,。；;：:、]/gu, '')
  .trim();

function ordinaryPddSelectionContextStore() {
  if (!ordinaryPddSelectionContextStore.contexts) {
    ordinaryPddSelectionContextStore.contexts = new WeakMap();
  }
  return ordinaryPddSelectionContextStore.contexts;
}

function rememberOrdinaryPddSelectionContext(targetPage, label, scope, frame, source) {
  const normalized = normalizeOrdinaryPddOptionText(label);
  if (!normalized || !targetPage) return;
  const store = ordinaryPddSelectionContextStore();
  const contexts = store.get(targetPage) || new Map();
  contexts.set(normalized, {
    label,
    scope,
    frame,
    source,
    frameUrl: String(frame?.url?.() || targetPage.url?.() || '').slice(0, 1000),
    selectedAt: new Date().toISOString(),
  });
  store.set(targetPage, contexts);
}

function findOrdinaryPddSelectionContext(targetPage, label) {
  const normalized = normalizeOrdinaryPddOptionText(label);
  if (!normalized || !targetPage) return null;
  return ordinaryPddSelectionContextStore().get(targetPage)?.get(normalized) || null;
}

function pddSubmitButtonContextStore() {
  if (!pddSubmitButtonContextStore.contexts) {
    pddSubmitButtonContextStore.contexts = new WeakMap();
  }
  return pddSubmitButtonContextStore.contexts;
}

function rememberPddSubmitButtonContext(locator, context) {
  if (locator) pddSubmitButtonContextStore().set(locator, context);
}

function readPddSubmitButtonContext(locator) {
  return locator ? pddSubmitButtonContextStore().get(locator) || null : null;
}

async function isOrdinaryPddOptionSelectedInContext(targetPage, label) {
  const context = findOrdinaryPddSelectionContext(targetPage, label);
  if (context?.scope
    && await isPddOptionSelected(context.scope, label).catch(() => false)) return true;
  for (const frame of targetPage.frames()) {
    if (await isPddOptionSelected(frame.locator('body'), label).catch(() => false)) return true;
  }
  return false;
}

async function findTrustedPddSubmitConfirmation(targetPage, selectedPddOption, submitContext = null) {
  const expected = normalizeOrdinaryPddOptionText(selectedPddOption);
  if (!expected) return null;
  for (const frame of targetPage.frames()) {
    const dialogs = frame.locator(
      '[role="dialog"]:visible, .beast-core-modal:visible, .ant-modal:visible',
    );
    for (let index = 0; index < await dialogs.count().catch(() => 0); index += 1) {
      const dialog = dialogs.nth(index);
      const dialogText = String(await dialog.innerText().catch(() => '')).trim();
      if (!dialogText || !/(?:确认|确定|提交|处理结果|退款)/u.test(dialogText)) continue;
      const frameUrl = String(frame.url() || '').slice(0, 1000);
      const optionNamed = normalizeOrdinaryPddOptionText(dialogText).includes(expected);
      const sameSubmitFrame = Boolean(submitContext?.frameUrl && submitContext.frameUrl === frameUrl);
      const optionStillSelected = sameSubmitFrame
        && await isPddOptionSelected(frame.locator('body'), selectedPddOption).catch(() => false);
      if (!optionNamed && !optionStillSelected) continue;
      const buttons = dialog.locator('button').filter({
        hasText: /^\s*(?:确认|确定|确认提交)\s*$/,
      });
      const button = await firstVisible([buttons]);
      if (!button || !await button.isEnabled().catch(() => false)) continue;
      return { button, dialogText, frameUrl };
    }
  }
  return null;
}

const findNormalizedOrdinaryPddOption = async (scope, label) => {
  const expected = normalizeOrdinaryPddOptionText(label);
  if (!expected) return null;
  const candidates = scope.locator('label, [role="radio"], input[type="radio"]');
  const count = Math.min(300, await candidates.count().catch(() => 0));
  for (let index = 0; index < count; index += 1) {
    const candidate = candidates.nth(index);
    if (!await candidate.isVisible().catch(() => false)) continue;
    const matches = await candidate.evaluate((element, expectedText) => {
      const normalize = (value) => String(value || '')
        .normalize('NFKC')
        .replace(/[\s，,。；;：:、]/gu, '')
        .trim();
      let current = element;
      for (let depth = 0; current && depth < 5; depth++, current = current.parentElement) {
        const values = [
          current.innerText,
          current.getAttribute?.('aria-label'),
          current.getAttribute?.('value'),
        ];
        if (values.some((value) => normalize(value) === expectedText)) return true;
      }
      return false;
    }, expected).catch(() => false);
    if (matches) return candidate;
  }
  return null;
};

const listVisibleOrdinaryPddOptions = async (scopes) => {
  const options = [];
  const seen = new Set();
  for (const scope of scopes) {
    const controls = scope.locator(
      'label:has(input[type="radio"]), [role="radio"], input[type="radio"]',
    );
    const count = Math.min(300, await controls.count().catch(() => 0));
    for (let index = 0; index < count; index += 1) {
      const control = controls.nth(index);
      if (!await control.isVisible().catch(() => false)
        || !await control.isEnabled().catch(() => true)) continue;
      const label = String(await control.evaluate((element) => {
        const associated = element.matches('input[type="radio"]')
          ? element.labels?.[0] || element.closest('label') || element.parentElement
          : element;
        return associated?.innerText
          || associated?.getAttribute?.('aria-label')
          || element.getAttribute?.('aria-label')
          || element.getAttribute?.('value')
          || '';
      }).catch(() => '')).replace(/\s+/gu, ' ').trim();
      const normalized = normalizeOrdinaryPddOptionText(label);
      if (!normalized || label.length > 160 || seen.has(normalized)) continue;
      seen.add(normalized);
      options.push(label);
    }
  }
  return options;
};

const findOrdinaryPddDecisionEntryAction = async (targetPage) => {
  const candidates = targetPage.locator('button, a, [role="button"], [role="link"]').filter({
    hasText: ordinaryPddDecisionEntryPattern,
  });
  const visible = [];
  for (let index = 0; index < await candidates.count().catch(() => 0); index += 1) {
    const candidate = candidates.nth(index);
    if (!await candidate.isVisible().catch(() => false)
      || !await candidate.isEnabled().catch(() => true)) continue;
    const text = String(await candidate.innerText().catch(() => '')).replace(/\s+/gu, '').trim();
    if (!ordinaryPddDecisionEntryPattern.test(text)) continue;
    visible.push({ candidate, text });
  }
  return visible.length === 1 ? visible[0] : null;
};

const selectOrdinaryPddOption = async (
  targetPage,
  labels,
  {
    required: isRequired = true,
    waitMs = pddRenderWaitMs,
    allowJudgment = true,
    scopeOverride = null,
  } = {},
) => {
  const candidates = expandOrdinaryPddOptionAliases(labels);
  const boundedWaitMs = Math.max(0, Math.min(pddRenderWaitMs, Number(waitMs) || 0));
  const deadline = Date.now() + boundedWaitMs;
  const currentScopes = async () => {
    const mainFrame = targetPage.mainFrame();
    if (scopeOverride) {
      return [{ scope: scopeOverride, frame: mainFrame, source: 'explicit-dialog' }];
    }
    return [
      { scope: await ordinaryFormScope(targetPage), frame: mainFrame, source: 'main-form' },
      { scope: targetPage.locator('body'), frame: mainFrame, source: 'main-body' },
      ...targetPage.frames()
        .filter((frame) => frame !== mainFrame)
        .map((frame) => ({ scope: frame.locator('body'), frame, source: 'child-frame' })),
    ];
  };
  let lastSelectionError = null;
  let decisionEntryAttempted = false;
  let semanticOptionsSignature = null;
  let semanticOptionsStableSince = 0;
  do {
    await checkForHumanVerification(targetPage, `wait-ordinary-options-${candidates.join('-')}`);
    const scopes = await currentScopes();
    for (const label of candidates) {
      for (const { scope: currentScope, frame, source } of scopes) {
        if (await isPddOptionSelected(currentScope, label).catch(() => false)) {
          rememberOrdinaryPddSelectionContext(targetPage, label, currentScope, frame, source);
          return label;
        }
        try {
          if (await selectPddRadioOnce(targetPage, currentScope, label, { required: false })) {
            if (await waitForPddOptionSelected(targetPage, currentScope, label, 2500)) {
              rememberOrdinaryPddSelectionContext(targetPage, label, currentScope, frame, source);
              return label;
            }
          }
        } catch (error) {
          if (error instanceof HumanVerificationRequiredError
            || error instanceof PddLoginRequiredError
            || error instanceof RateLimitPauseError) throw error;
          lastSelectionError = error;
          if (await selectPddRadio(targetPage, currentScope, label, { required: false }).catch((retryError) => {
            if (retryError instanceof HumanVerificationRequiredError
              || retryError instanceof PddLoginRequiredError
              || retryError instanceof RateLimitPauseError) throw retryError;
            return false;
          })) {
            rememberOrdinaryPddSelectionContext(targetPage, label, currentScope, frame, source);
            return label;
          }
        }
      }
    }
    if (!decisionEntryAttempted) {
      decisionEntryAttempted = true;
      const entry = await findOrdinaryPddDecisionEntryAction(targetPage);
      if (entry) {
        await pacedAction(targetPage, 'open-ordinary-pdd-decision-form', () => (
          entry.candidate.click({ force: true })
        ), { retryOnRateLimit: true });
        writeProgress({
          step: 'ordinary-pdd-decision-form-opening',
          ordinaryPddDecisionFormEntry: {
            orderNumber: readProgress().orderNumber || null,
            actionText: entry.text,
            openedAt: new Date().toISOString(),
          },
        });
      }
    }
    const visibleOptions = await listVisibleOrdinaryPddOptions(
      scopes.map(({ scope }) => scope),
    );
    const semanticSignature = visibleOptions
      .map((label) => normalizeOrdinaryPddOptionText(label))
      .sort()
      .join('|');
    if (semanticSignature && semanticSignature !== semanticOptionsSignature) {
      semanticOptionsSignature = semanticSignature;
      semanticOptionsStableSince = Date.now();
    } else if (semanticSignature
      && Date.now() - semanticOptionsStableSince >= 400) {
      const semanticMatch = resolveOrdinaryPddSemanticOption(candidates, visibleOptions);
      const judgmentMatch = semanticMatch || !allowJudgment
        ? null
        : resolveOrdinaryPddJudgmentOption(candidates, visibleOptions);
      const selectedMatch = semanticMatch || judgmentMatch;
      if (selectedMatch) {
        for (const { scope: currentScope, frame, source } of scopes) {
          try {
            const clicked = await selectPddRadioOnce(
              targetPage,
              currentScope,
              selectedMatch.label,
              { required: false },
            );
            if (!clicked || !await waitForPddOptionSelected(
              targetPage,
              currentScope,
              selectedMatch.label,
              2500,
            )) continue;
            const selectionAudit = {
              orderNumber: readProgress().orderNumber || null,
              requestedLabels: candidates,
              visibleOptions,
              selectedLabel: selectedMatch.label,
              requestedLabel: selectedMatch.requestedLabel,
              intent: selectedMatch.intent,
              confidence: selectedMatch.confidence,
              reason: selectedMatch.reason,
              selectedAt: new Date().toISOString(),
            };
            writeProgress({
              step: semanticMatch
                ? 'ordinary-pdd-semantic-option-selected'
                : 'ordinary-pdd-judgment-option-selected',
              ...(semanticMatch
                ? { ordinaryPddSemanticOptionSelection: selectionAudit }
                : {
                  ordinaryPddJudgmentOptionSelection: {
                    ...selectionAudit,
                    score: judgmentMatch.score,
                    matchedFeatures: judgmentMatch.matchedFeatures,
                    representsRequestedIntent: judgmentMatch.representsRequestedIntent,
                    rejectedOptions: judgmentMatch.rejectedOptions,
                  },
                }),
            });
            rememberOrdinaryPddSelectionContext(
              targetPage,
              selectedMatch.label,
              currentScope,
              frame,
              source,
            );
            return selectedMatch.label;
          } catch (error) {
            if (error instanceof HumanVerificationRequiredError
              || error instanceof PddLoginRequiredError
              || error instanceof RateLimitPauseError) throw error;
            lastSelectionError = error;
          }
        }
      }
    }
    const remainingMs = deadline - Date.now();
    if (remainingMs > 0) await targetPage.waitForTimeout(Math.min(500, remainingMs));
  } while (Date.now() < deadline);
  if (!isRequired) return null;
  const message = `拼多多未找到场景选项（已等待 ${Math.ceil(boundedWaitMs / 1000)} 秒）: ${candidates.join(' / ')}`
    + (lastSelectionError?.message ? `；最近一次选择错误：${lastSelectionError.message}` : '');
  const frameDiagnostics = [];
  for (const frame of targetPage.frames()) {
    const snapshot = await frame.locator('body').evaluate((body) => {
      const relevantPattern = /物流|承诺|补发|召回|拦截|处理|退款|提交|知晓/u;
      const relevantLines = String(body.innerText || '')
        .split(/\r?\n/u)
        .map((line) => line.trim())
        .filter((line) => line && relevantPattern.test(line))
        .slice(0, 120);
      const controls = [...body.querySelectorAll(
        'input, button, label, select, option, textarea, [role="radio"], [role="option"], [role="combobox"]',
      )].map((element) => ({
        tag: element.tagName.toLowerCase(),
        role: element.getAttribute('role'),
        type: element.getAttribute('type'),
        text: String(element.innerText || element.getAttribute('aria-label') || '').trim().slice(0, 300),
        value: String(element.value || element.getAttribute('value') || '').trim().slice(0, 300),
        checked: element.checked ?? element.getAttribute('aria-checked'),
        disabled: element.disabled ?? element.getAttribute('aria-disabled'),
        associatedText: String(
          element.labels?.[0]?.innerText
          || element.closest?.('label')?.innerText
          || element.parentElement?.innerText
          || '',
        ).trim().slice(0, 300),
      })).filter((control) => (
        relevantPattern.test(`${control.text} ${control.value} ${control.associatedText}`)
        || ['radio', 'select', 'option'].includes(control.type || control.tag)
        || ['radio', 'option', 'combobox'].includes(control.role)
      )).slice(0, 200);
      return { relevantLines, controls };
    }).catch((error) => ({ error: error.message, relevantLines: [], controls: [] }));
    frameDiagnostics.push({ url: frame.url(), ...snapshot });
  }
  const lookupFailure = {
    labels: candidates,
    url: targetPage.url(),
    frames: frameDiagnostics,
    failedAt: new Date().toISOString(),
  };
  writeProgress({ ordinaryPddOptionLookupFailure: lookupFailure });
  await saveWorkflowDiagnostics(targetPage, 'ordinary-pdd-option-missing', new Error(message)).catch(() => {});
  throw new Error(message);
};

const ordinaryPddMessageButtonPattern = /^(?:发送话术|发送消息|发送回复|提交)$/u;

const findOrdinaryPddMessageStage = async (targetPage) => {
  const buttons = targetPage.locator('button').filter({ hasText: ordinaryPddMessageButtonPattern });
  for (let index = 0; index < await buttons.count().catch(() => 0); index += 1) {
    const button = buttons.nth(index);
    if (!await button.isVisible().catch(() => false)
      || !await button.isEnabled().catch(() => false)) continue;
    const buttonText = String(await button.innerText().catch(() => '')).replace(/\s+/gu, '').trim();
    if (!ordinaryPddMessageButtonPattern.test(buttonText)) continue;
    const form = button.locator('xpath=ancestor::*[.//textarea][1]').first();
    const scope = await form.count().catch(() => 0) ? form : targetPage.locator('body');
    const textareas = scope.locator('textarea');
    for (let textIndex = 0; textIndex < await textareas.count().catch(() => 0); textIndex += 1) {
      const textarea = textareas.nth(textIndex);
      if (!await textarea.isVisible().catch(() => false)) continue;
      const message = String(await textarea.inputValue().catch(() => '') || '').trim();
      const scopeText = String(await scope.innerText().catch(() => '') || '').trim();
      const hasDecisionControls = await hasVisibleOrdinaryPddDecisionControls(scope);
      const mode = classifyOrdinaryPddMessageStage({
        buttonText,
        message,
        scopeText,
        hasDecisionControls,
      });
      if (!mode) continue;
      return {
        button,
        buttonText,
        message,
        mode,
      };
    }
  }
  return null;
};

const hasVisibleOrdinaryPddDecisionControls = async (targetPage) => {
  const controls = targetPage.locator('input[type="radio"], [role="radio"]');
  for (let index = 0; index < await controls.count().catch(() => 0); index += 1) {
    if (await controls.nth(index).isVisible().catch(() => false)) return true;
  }
  return false;
};

const waitForOrdinaryPddMessageTransition = async (
  targetPage,
  orderNumber,
  timeoutMs = pddRenderWaitMs,
) => {
  const deadline = Date.now() + Math.max(0, Number(timeoutMs) || 0);
  do {
    await checkForHumanVerification(targetPage, 'ordinary-pdd-message-postcondition');
    const decisionControlsVisible = await hasVisibleOrdinaryPddDecisionControls(targetPage);
    const state = await readPddResolutionState(targetPage, orderNumber).catch(() => null);
    const orderCompleted = Boolean(state?.isCompleted && state?.orderMatches);
    if (isPddMessageTransitionComplete({ decisionControlsVisible, orderCompleted })) {
      return { committed: true, decisionControlsVisible, orderCompleted, state };
    }
    const remainingMs = deadline - Date.now();
    if (remainingMs > 0) await targetPage.waitForTimeout(Math.min(500, remainingMs));
  } while (Date.now() < deadline);
  return {
    committed: false,
    decisionControlsVisible: false,
    orderCompleted: false,
    state: null,
  };
};

const advanceOrdinaryPddMessageStageIfPresent = async (
  targetPage,
  orderNumber,
  scenarioCode,
  decision,
) => {
  if (await hasVisibleOrdinaryPddDecisionControls(targetPage)) return null;
  const messageStage = await findOrdinaryPddMessageStage(targetPage);
  if (!messageStage) return null;
  if (!messageStage.message) {
    throw new Error('拼多多“发送话术”步骤没有可发送的预填话术');
  }

  const messageSha256 = crypto.createHash('sha256').update(messageStage.message).digest('hex');
  const directPrefilledSubmit = messageStage.mode === 'prefilled-reply-submit';
  const actionLabel = directPrefilledSubmit ? '预填回复提交' : '发送话术';
  const effectStage = directPrefilledSubmit
    ? `ordinary-${scenarioCode}-submit-prefilled-reply-v1`
    : `ordinary-${scenarioCode}-send-script-v1`;
  let transition = null;
  const result = await guardedExternalEffect({
    effectType: 'pdd-submit',
    orderNumber,
    stage: effectStage,
    request: {
      scenarioCode,
      reasonCode: decision.reasonCode || null,
      messageSha256,
      mode: messageStage.mode,
    },
  }, async () => {
    const responsePromise = targetPage.waitForResponse(
      (response) => response.request().method() === 'POST'
        && response.url().includes('/latitude/mallTicket/submitForm'),
      { timeout: 30000 },
    ).catch(() => null);
    writeProgress({
      ordinaryPddMessageStage: {
        orderNumber,
        scenarioCode,
        mode: messageStage.mode,
        status: 'submitting',
        messageSha256,
        lastClickAttemptedAt: new Date().toISOString(),
      },
    });
    await pacedAction(
      targetPage,
      directPrefilledSubmit ? 'submit-ordinary-pdd-prefilled-reply' : 'send-ordinary-pdd-script',
      () => messageStage.button.click(),
      { retryOnRateLimit: true },
    );
    const response = await responsePromise;
    let submitReceipt = null;
    if (response) {
      const responseText = await response.text().catch(() => '');
      let responsePayload = null;
      try { responsePayload = JSON.parse(responseText); } catch { /* retain raw response */ }
      submitReceipt = {
        httpStatus: response.status(),
        success: responsePayload?.success ?? response.ok(),
        errorCode: responsePayload?.errorCode ?? null,
        errorMsg: responsePayload?.errorMsg || null,
        responseText: responseText.slice(0, 2000),
        clickAttempted: true,
        responseCaptured: true,
      };
      if (!response.ok() || responsePayload?.success === false) {
        throw new PddSubmitRejectedError(effectStage, submitReceipt);
      }
    }
    transition = await waitForOrdinaryPddMessageTransition(targetPage, orderNumber);
    if (!transition.committed && submitReceipt?.success !== true) {
      const error = new Error(`拼多多“${actionLabel}”后未确认进入下一处理阶段`);
      error.externalEffectReceipt = submitReceipt;
      throw error;
    }
    return {
      messageSha256,
      responseConfirmed: submitReceipt?.success === true,
      decisionControlsVisible: transition.decisionControlsVisible,
      orderCompleted: transition.orderCompleted,
      mode: messageStage.mode,
    };
  });

  if (!transition?.committed) {
    transition = await waitForOrdinaryPddMessageTransition(
      targetPage,
      orderNumber,
      Math.min(pddRenderWaitMs, 5000),
    );
  }
  writeProgress({
    step: transition.committed
      ? 'ordinary-pdd-message-stage-complete'
      : 'ordinary-pdd-message-stage-response-confirmed',
    ordinaryPddMessageStage: {
      orderNumber,
      scenarioCode,
      mode: messageStage.mode,
      status: transition.committed ? 'transition-confirmed' : 'response-confirmed',
      alreadySucceeded: Boolean(result?.alreadySucceeded),
      decisionControlsVisible: transition.decisionControlsVisible,
      orderCompleted: transition.orderCompleted,
      messageSha256,
      completedAt: new Date().toISOString(),
    },
  });
  if (transition.orderCompleted) {
    return {
      ...transition.state,
      messageStageSubmitted: true,
      messageStageMode: messageStage.mode,
      responseConfirmed: result?.responseConfirmed === true,
      alreadySucceeded: Boolean(result?.alreadySucceeded),
    };
  }
  return {
    isCompleted: false,
    isPending: true,
    orderMatches: true,
    messageStageSubmitted: true,
    messageStageMode: messageStage.mode,
    responseConfirmed: result?.responseConfirmed === true,
    alreadySucceeded: Boolean(result?.alreadySucceeded),
    confirmationMethod: transition.committed
      ? 'message-stage-transition'
      : 'message-submit-response-confirmed',
  };
};

const ordinaryPddDateParts = (value) => {
  const normalized = String(value ?? '').normalize('NFKC').trim();
  const fullDate = normalized.match(
    /(?:^|[^\d])(\d{4})\D{0,3}(\d{1,2})\D{0,3}(\d{1,2})(?:[^\d]|$)/u,
  );
  if (fullDate) {
    return {
      year: Number(fullDate[1]),
      month: Number(fullDate[2]),
      day: Number(fullDate[3]),
      hasYear: true,
    };
  }
  const monthDay = normalized.match(
    /(?:^|[^\d])(\d{1,2})\s*(?:月|[-/.])\s*(\d{1,2})(?:\s*日|[^\d]|$)/u,
  );
  if (!monthDay) return null;
  return {
    year: null,
    month: Number(monthDay[1]),
    day: Number(monthDay[2]),
    hasYear: false,
  };
};

const ordinaryPddDateValueMatches = (value, expectedSource) => {
  const expected = ordinaryPddDateParts(expectedSource);
  const actual = ordinaryPddDateParts(value);
  if (!expected || !actual) return false;
  if (actual.hasYear && actual.year !== expected.year) return false;
  return actual.month === expected.month && actual.day === expected.day;
};

const ordinaryPddDateControlSnapshot = async (field) => field.evaluate((element) => ({
  value: 'value' in element ? String(element.value || '') : '',
  type: element.getAttribute('type') || '',
  placeholder: element.getAttribute('placeholder') || '',
  className: String(element.className || '').slice(0, 200),
  readOnly: Boolean(element.readOnly),
  ariaLabel: element.getAttribute('aria-label') || '',
  title: element.getAttribute('title') || '',
  dataValue: element.getAttribute('data-value') || '',
  dataDate: element.getAttribute('data-date') || '',
})).catch(() => ({
  value: '', type: '', placeholder: '', className: '', readOnly: false,
  ariaLabel: '', title: '', dataValue: '', dataDate: '',
}));

const waitForOrdinaryPddDateHeld = async (targetPage, field, source, timeoutMs = 5_000) => {
  const deadline = Date.now() + timeoutMs;
  let snapshot = await ordinaryPddDateControlSnapshot(field);
  do {
    if (Object.values(snapshot).some((value) => ordinaryPddDateValueMatches(value, source))) {
      return { matched: true, snapshot };
    }
    if (Date.now() >= deadline) break;
    await targetPage.waitForTimeout(200);
    snapshot = await ordinaryPddDateControlSnapshot(field);
  } while (Date.now() < deadline);
  return { matched: false, snapshot };
};

const selectOrdinaryPddDateField = async (targetPage, field, source, labelPattern) => {
  await pacedAction(targetPage, 'open-pdd-date-picker', () => field.click({ force: true }));
  await targetPage.waitForTimeout(300);
  const [year, month, day] = source.split('-').map(Number);
  const exactDateSelectors = [
    `[data-date="${source}"]:not(input)`,
    `[data-value="${source}"]:not(input)`,
    `[title="${source}"]:not(input)`,
    `[aria-label="${source}"]:not(input)`,
    `[aria-label*="${source}"]:not(input)`,
  ];
  const candidateLocators = [
    ...exactDateSelectors.map((selector) => targetPage.locator(selector)),
    targetPage.getByRole('gridcell', { name: new RegExp(`^${day}$`) }),
    targetPage.getByText(String(day), { exact: true }),
  ];
  let selected = false;
  for (const locator of candidateLocators) {
    for (let index = 0; index < await locator.count().catch(() => 0); index++) {
      const candidate = locator.nth(index);
      if (!await candidate.isVisible().catch(() => false)) continue;
      const eligible = await candidate.evaluate((element, expected) => {
        const control = element.closest('button, [role="gridcell"], td, [role="option"]') || element;
        const calendar = control.closest(
          '[role="dialog"], [role="grid"], [data-testid*="datePicker"], '
          + '[class*="datePicker"], [class*="DatePicker"], [class*="calendar"], [class*="Calendar"], '
          + '[class*="picker"], [class*="Picker"]',
        );
        if (!calendar) return false;
        const disabled = control.matches(':disabled, [aria-disabled="true"]')
          || /disabled|outside|other-month|prev-month|next-month/iu.test(String(control.className || ''));
        if (disabled) return false;
        const attributes = [
          control.getAttribute('data-date'), control.getAttribute('data-value'),
          control.getAttribute('title'), control.getAttribute('aria-label'),
        ].filter(Boolean).join(' ');
        if (/\d{4}[-/]\d{1,2}[-/]\d{1,2}/u.test(attributes)) {
          const normalized = attributes.replaceAll('/', '-');
          if (!normalized.includes(expected.source)) return false;
        }
        return true;
      }, { source, year, month, day }).catch(() => false);
      if (!eligible) continue;
      await pacedAction(targetPage, 'select-pdd-date-picker-day', () => candidate.click({ force: true }));
      selected = true;
      break;
    }
    if (selected) break;
  }

  let heldDate = null;
  if (selected) {
    heldDate = await waitForOrdinaryPddDateHeld(targetPage, field, source);
    if (heldDate.matched) return true;
  }

  // Some Beast date-picker builds expose only a readonly input and no stable
  // day attributes. Removing readonly lets Playwright emit the same input and
  // change events that the component consumes, while verification below
  // prevents advancing unless the rendered control retained the target date.
  await field.evaluate((element) => element.removeAttribute('readonly')).catch(() => {});
  await pacedAction(targetPage, 'fill-pdd-date-picker-fallback', () => field.fill(source));
  await field.press('Tab').catch(() => {});
  heldDate = await waitForOrdinaryPddDateHeld(targetPage, field, source);
  if (heldDate.matched) return true;
  throw new Error(
    `拼多多“${labelPattern}”日期选择后未保持目标日期 ${source}`
    + `（控件值: ${JSON.stringify(heldDate.snapshot)}）`,
  );
};

const collectOrdinaryPddDateFieldLookupDiagnostics = async (
  targetPage,
  labelPattern,
  expectedDate,
) => {
  const mainFrame = typeof targetPage.mainFrame === 'function' ? targetPage.mainFrame() : null;
  const frames = typeof targetPage.frames === 'function'
    ? targetPage.frames()
    : [targetPage];
  const frameDiagnostics = [];
  for (let frameIndex = 0; frameIndex < frames.length; frameIndex += 1) {
    const frame = frames[frameIndex];
    const snapshot = await frame.locator('body').evaluate((body) => {
      const relevantPattern = /核实|日期|时间|话术|提交|去核实|已核实/u;
      const classPattern = /date|time|picker|calendar/iu;
      const controls = [...body.querySelectorAll([
        'input', 'textarea', 'button', 'label', '[role]', '[contenteditable="true"]',
        '[class*="date"]', '[class*="Date"]', '[class*="time"]', '[class*="Time"]',
        '[class*="picker"]', '[class*="Picker"]',
      ].join(', '))].map((element) => {
        const rect = element.getBoundingClientRect();
        const style = element.ownerDocument.defaultView.getComputedStyle(element);
        const text = String(
          element.innerText
          || element.getAttribute('aria-label')
          || element.getAttribute('placeholder')
          || '',
        ).replace(/\s+/gu, ' ').trim();
        const value = 'value' in element ? String(element.value || '') : '';
        const parentText = String(
          element.labels?.[0]?.innerText
          || element.closest?.('label')?.innerText
          || element.parentElement?.innerText
          || '',
        ).replace(/\s+/gu, ' ').trim();
        return {
          tag: element.tagName.toLowerCase(),
          type: element.getAttribute('type') || '',
          role: element.getAttribute('role') || '',
          className: String(element.className || '').slice(0, 240),
          placeholder: element.getAttribute('placeholder') || '',
          ariaLabel: element.getAttribute('aria-label') || '',
          title: element.getAttribute('title') || '',
          value: value.slice(0, 300),
          text: text.slice(0, 500),
          parentText: parentText.slice(0, 500),
          readOnly: Boolean(element.readOnly),
          disabled: Boolean(element.disabled) || element.getAttribute('aria-disabled') === 'true',
          contentEditable: element.getAttribute('contenteditable') || '',
          visible: style.display !== 'none'
            && style.visibility !== 'hidden'
            && rect.width > 0
            && rect.height > 0,
          outerHtml: String(element.outerHTML || '').slice(0, 1200),
        };
      }).filter((control) => (
        relevantPattern.test([
          control.text, control.value, control.parentText, control.placeholder,
          control.ariaLabel, control.title,
        ].join(' '))
        || classPattern.test(control.className)
        || ['date', 'datetime-local', 'time'].includes(control.type)
      )).slice(0, 200);
      const relevantLines = String(body.innerText || '')
        .split(/\r?\n/u)
        .map((line) => line.replace(/\s+/gu, ' ').trim())
        .filter((line) => line && relevantPattern.test(line))
        .slice(0, 160);
      return { controls, relevantLines };
    }).catch((error) => ({ controls: [], relevantLines: [], error: error.message }));
    frameDiagnostics.push({
      frameIndex,
      mainFrame: frame === mainFrame,
      url: String(frame.url?.() || '').slice(0, 1000),
      ...snapshot,
    });
  }
  return {
    orderNumber: readProgress().orderNumber || null,
    field: String(labelPattern),
    expectedDate,
    currentUrl: String(targetPage.url?.() || '').slice(0, 1000),
    frames: frameDiagnostics,
    failedAt: new Date().toISOString(),
  };
};

const fillOrdinaryPddField = async (targetPage, labelPattern, value, {
  textarea = false,
  textareaPreferred = false,
  required: isRequired = true,
  datePicker = false,
  scopeOverride = null,
} = {}) => {
  const source = String(value ?? '').trim();
  if (!source && isRequired) throw new Error(`拼多多“${labelPattern}”待填写内容为空`);
  const editableInputSelector = [
    'input:not([type]):not([placeholder*="搜索"]):not([placeholder*="课程"]):not([placeholder*="规则"])',
    'input[type="text"]:not([placeholder*="搜索"]):not([placeholder*="课程"]):not([placeholder*="规则"])',
    'input[type="tel"]',
    'input[type="number"]',
    'input[type="url"]',
  ].join(',');
  const datePickerInputSelector = [
    'input:not([type="radio"]):not([type="checkbox"]):not([type="hidden"]):not([disabled])',
    ':not([placeholder*="搜索"]):not([placeholder*="课程"]):not([placeholder*="规则"])',
    ':not([placeholder*="话术"]):not([value*="话术"])',
  ].join('');
  const editableFieldSelectors = datePicker
    ? [datePickerInputSelector]
    : textarea
    ? ['textarea:not([disabled])']
    : textareaPreferred
      ? ['textarea:not([disabled])', editableInputSelector]
      : [editableInputSelector];
  const editableFieldSelector = editableFieldSelectors.join(',');
  let field = null;
  let fieldSurface = targetPage;
  const deadline = Date.now() + pddRenderWaitMs;
  do {
    const mainFrame = datePicker && typeof targetPage.mainFrame === 'function'
      ? targetPage.mainFrame()
      : null;
    const fieldSurfaces = scopeOverride
      ? [scopeOverride]
      : datePicker && typeof targetPage.frames === 'function'
      ? [targetPage, ...targetPage.frames().filter((frame) => frame !== mainFrame)]
      : [targetPage];
    for (const surface of fieldSurfaces) {
      const labels = surface.getByText(labelPattern);
      for (let index = 0; index < await labels.count().catch(() => 0); index++) {
        const label = labels.nth(index);
        if (!await label.isVisible().catch(() => false)) continue;
        if (datePicker) {
          const labelText = String(await label.innerText().catch(() => ''))
            .replace(/\s+/gu, '')
            .trim();
          if (/(?:去核实|已核实|填写核实(?:时间|日期|结果)?)/u.test(labelText)) continue;
        }
        const localContainer = label.locator(
          'xpath=ancestor::*[self::label or self::div or self::li or self::td][1]',
        );
        const formItem = label.locator(
          'xpath=ancestor::*[contains(@class,"form") or contains(@class,"item") or self::label][1]',
        );
        field = await firstVisible([
          ...editableFieldSelectors.map((selector) => localContainer.locator(selector).first()),
          ...editableFieldSelectors.map((selector) => formItem.locator(selector).first()),
          ...(textarea || textareaPreferred
            ? [label.locator('xpath=following::textarea[not(@disabled)][1]')]
            : []),
          ...(!textarea
            ? [label.locator(`xpath=following::input[
                not(@type="radio") and not(@type="checkbox") and not(@type="hidden")
                and not(@disabled) and not(contains(@placeholder,"搜索"))
                and not(contains(@placeholder,"话术")) and not(contains(@value,"话术"))
              ][1]`)]
            : []),
        ]);
        if (field) {
          fieldSurface = surface;
          break;
        }
      }
      if (field) break;
    }
    if (!field && Date.now() < deadline) await targetPage.waitForTimeout(250);
  } while (!field && Date.now() < deadline);
  if (!field) {
    if (!isRequired) return false;
    if (!datePicker) {
      field = await firstVisible([
        targetPage.locator(editableFieldSelector).first(),
      ]);
    }
  }
  if (!field) {
    const message = `拼多多未找到“${labelPattern}”输入框`;
    if (datePicker) {
      const lookupFailure = await collectOrdinaryPddDateFieldLookupDiagnostics(
        targetPage,
        labelPattern,
        source,
      );
      writeProgress({
        step: 'ordinary-pdd-date-field-lookup-failed',
        ordinaryPddDateFieldLookupFailure: lookupFailure,
      });
      const error = new Error(message);
      Object.defineProperty(error, 'ordinaryPddRecoveryTargetPage', {
        value: targetPage,
        enumerable: false,
      });
      await saveWorkflowDiagnostics(
        targetPage,
        'ordinary-pdd-date-field-missing',
        error,
      ).catch(() => {});
      throw error;
    }
    throw new Error(message);
  }
  if (datePicker) {
    return selectOrdinaryPddDateField(fieldSurface, field, source, labelPattern);
  }
  await pacedAction(targetPage, `fill-pdd-${String(labelPattern).replace(/[^a-z0-9\u4e00-\u9fff]+/gi, '-')}`, () => (
    field.fill(source)
  ));
  const waitForRetainedValue = async (candidate, timeoutMs) => {
    const deadline = Date.now() + timeoutMs;
    let stableReads = 0;
    do {
      const retained = (await candidate.inputValue().catch(() => '')).trim() === source;
      stableReads = retained ? stableReads + 1 : 0;
      if (stableReads >= 2) return true;
      const remainingMs = deadline - Date.now();
      if (remainingMs > 0) await targetPage.waitForTimeout(Math.min(100, remainingMs));
    } while (Date.now() < deadline);
    return false;
  };
  if (await waitForRetainedValue(field, 500)) {
    const previousRecovery = readProgress().ordinaryPddFieldRecovery;
    const previousField = String(previousRecovery?.field || '');
    const currentField = String(labelPattern);
    const sameRecoveredField = previousField === currentField
      || (previousField.includes('送达地址') && currentField.includes('送达地址'));
    if (previousRecovery?.status === 'failed' && sameRecoveredField) {
      const selectedControl = await field.evaluate((element) => ({
        tagName: String(element.tagName || '').toLowerCase(),
        type: String(element.getAttribute('type') || ''),
        placeholder: String(element.getAttribute('placeholder') || ''),
      })).catch(() => null);
      writeProgress({
        ordinaryPddFieldRecovery: {
          orderNumber: readProgress().orderNumber || null,
          field: currentField,
          valueLength: source.length,
          status: 'succeeded',
          strategy: textareaPreferred ? 'preferred-multiline-control' : 'primary-labeled-control',
          selectedControl,
          recoveredAt: new Date().toISOString(),
        },
      });
    }
    return true;
  }

  const describeControl = (candidate) => candidate.evaluate((element) => {
    const ancestry = [];
    let context = element;
    for (let depth = 0; depth < 6 && context; depth += 1, context = context.parentElement) {
      ancestry.push({
        tagName: String(context.tagName || '').toLowerCase(),
        className: String(context.className || '').slice(0, 160),
        text: String(context.innerText || '').replace(/\s+/gu, ' ').trim().slice(0, 240),
      });
    }
    return {
      tagName: String(element.tagName || '').toLowerCase(),
      type: String(element.getAttribute('type') || ''),
      name: String(element.getAttribute('name') || ''),
      placeholder: String(element.getAttribute('placeholder') || ''),
      inputMode: String(element.getAttribute('inputmode') || ''),
      pattern: String(element.getAttribute('pattern') || ''),
      maxLength: Number(element.maxLength ?? -1),
      observedValueLength: String(element.value || '').trim().length,
      ancestry,
    };
  }).catch(() => null);
  const visibleEditableFields = targetPage.locator(editableFieldSelector);
  const candidateControls = [];
  for (let index = 0; index < await visibleEditableFields.count().catch(() => 0); index += 1) {
    const candidate = visibleEditableFields.nth(index);
    if (!await candidate.isVisible().catch(() => false)) continue;
    candidateControls.push(await describeControl(candidate));
  }

  const recovery = {
    orderNumber: readProgress().orderNumber || null,
    field: String(labelPattern),
    valueLength: source.length,
    control: await describeControl(field),
    candidateControls: candidateControls.filter(Boolean),
    status: 'keyboard-retrying',
    startedAt: new Date().toISOString(),
  };
  writeProgress({
    step: 'ordinary-pdd-field-recovering',
    ordinaryPddFieldRecovery: recovery,
  });
  await pacedAction(targetPage, 'recover-pdd-controlled-field-keyboard', async () => {
    await field.click({ force: true });
    await field.press('Control+A');
    await field.press('Backspace');
    await field.type(source, { delay: 5 });
    await field.press('Tab').catch(() => {});
  });
  if (await waitForRetainedValue(field, 800)) {
    writeProgress({
      ordinaryPddFieldRecovery: {
        ...recovery,
        status: 'succeeded',
        strategy: 'keyboard-input',
        recoveredAt: new Date().toISOString(),
      },
    });
    return true;
  }

  writeProgress({
    ordinaryPddFieldRecovery: {
      ...recovery,
      status: 'native-setter-retrying',
      keyboardFailedAt: new Date().toISOString(),
    },
  });
  await pacedAction(targetPage, 'recover-pdd-controlled-field-native-setter', () => field.evaluate(
    (element, nextValue) => {
      const view = element.ownerDocument.defaultView;
      const prototype = element instanceof view.HTMLTextAreaElement
        ? view.HTMLTextAreaElement.prototype
        : view.HTMLInputElement.prototype;
      const valueSetter = Object.getOwnPropertyDescriptor(prototype, 'value')?.set;
      if (!valueSetter) throw new Error('input-value-setter-unavailable');
      element.focus();
      valueSetter.call(element, nextValue);
      element.dispatchEvent(new view.InputEvent('input', {
        bubbles: true,
        composed: true,
        data: nextValue,
        inputType: 'insertText',
      }));
      element.dispatchEvent(new view.Event('change', { bubbles: true, composed: true }));
      element.blur();
    },
    source,
  ));
  if (await waitForRetainedValue(field, 800)) {
    writeProgress({
      ordinaryPddFieldRecovery: {
        ...recovery,
        status: 'succeeded',
        strategy: 'native-value-setter',
        recoveredAt: new Date().toISOString(),
      },
    });
    return true;
  }

  const rejectedValue = await field.inputValue().catch(() => '');
  if (rejectedValue && rejectedValue.trim() !== source) {
    await field.fill('').catch(() => {});
    await field.press('Tab').catch(() => {});
  }
  for (let index = 0; index < await visibleEditableFields.count().catch(() => 0); index += 1) {
    const candidate = visibleEditableFields.nth(index);
    if (!await candidate.isVisible().catch(() => false)) continue;
    const existingValue = String(await candidate.inputValue().catch(() => '')).trim();
    if (existingValue && existingValue !== source) continue;
    await pacedAction(targetPage, 'recover-pdd-controlled-field-alternate', () => (
      candidate.fill(source)
    )).catch(() => {});
    await candidate.press('Tab').catch(() => {});
    if (await waitForRetainedValue(candidate, 800)) {
      field = candidate;
      writeProgress({
        ordinaryPddFieldRecovery: {
          ...recovery,
          status: 'succeeded',
          strategy: 'alternate-empty-field',
          rejectedValue,
          selectedControl: await describeControl(candidate),
          recoveredAt: new Date().toISOString(),
        },
      });
      return true;
    }
    const attemptedValue = String(await candidate.inputValue().catch(() => '')).trim();
    if (attemptedValue && attemptedValue !== existingValue) {
      await candidate.fill(existingValue).catch(() => {});
      await candidate.press('Tab').catch(() => {});
    }
  }
  writeProgress({
    ordinaryPddFieldRecovery: {
      ...recovery,
      status: 'failed',
      rejectedValue,
      observedValue: await field.inputValue().catch(() => null),
      failedAt: new Date().toISOString(),
    },
  });
  const error = new Error(`拼多多“${labelPattern}”填写后未保持内容`);
  Object.defineProperty(error, 'ordinaryPddRecoveryTargetPage', {
    value: targetPage,
    enumerable: false,
  });
  await saveWorkflowDiagnostics(
    targetPage,
    'ordinary-pdd-field-not-retained',
    error,
  ).catch(() => {});
  throw error;
};

const verifyOrdinaryPddGeneratedMessage = async (
  targetPage,
  requiredTerms = [],
  { fallbackMessage = null, acceptedMessages = [] } = {},
) => {
  const normalizeMessage = (value) => String(value || '')
    .normalize('NFKC')
    .replace(/\s+/gu, '')
    .trim();
  const expected = requiredTerms.map(normalizeMessage).filter(Boolean);
  const accepted = acceptedMessages.map(normalizeMessage).filter(Boolean);
  const matchesGeneratedMessage = (message) => accepted.includes(message)
    || expected.every((term) => message.includes(term));
  const fallback = String(fallbackMessage || '').trim();
  const normalizedFallback = normalizeMessage(fallback);
  if (fallback && !expected.every((term) => normalizedFallback.includes(term))) {
    throw new Error('拼多多推荐话术兜底内容未包含全部必需信息');
  }
  const deadline = Date.now() + pddRenderWaitMs;
  const fallbackEligibleAt = Date.now()
    + Math.min(2_000, Math.max(500, Math.floor(pddRenderWaitMs / 10)));
  let messages = [];
  let fallbackAttempted = false;
  const tryFallback = async () => {
    if (!fallback || fallbackAttempted) return false;
    fallbackAttempted = true;
    const formScope = await ordinaryFormScope(targetPage);
    const textareas = formScope.locator('textarea:not([readonly]):not([disabled])');
    const candidates = [];
    for (let index = 0; index < await textareas.count().catch(() => 0); index += 1) {
      const textarea = textareas.nth(index);
      if (!await textarea.isVisible().catch(() => false)
        || !await textarea.isEnabled().catch(() => false)) continue;
      const value = String(await textarea.inputValue().catch(() => '')).trim();
      if (value) candidates.push({ textarea, value });
    }
    if (candidates.length !== 1) {
      writeProgress({
        ordinaryPddGeneratedMessageRecovery: {
          orderNumber: readProgress().orderNumber || null,
          status: 'skipped-ambiguous-control',
          candidateCount: candidates.length,
          requiredTermCount: expected.length,
          skippedAt: new Date().toISOString(),
        },
      });
      return false;
    }
    const [{ textarea, value: originalMessage }] = candidates;
    writeProgress({
      step: 'ordinary-pdd-generated-message-recovering',
      ordinaryPddGeneratedMessageRecovery: {
        orderNumber: readProgress().orderNumber || null,
        status: 'recovering',
        strategy: 'unique-editable-recommendation-textarea',
        originalLength: originalMessage.length,
        fallbackLength: fallback.length,
        requiredTermCount: expected.length,
        startedAt: new Date().toISOString(),
      },
    });
    await pacedAction(targetPage, 'repair-pdd-generated-message', () => textarea.fill(fallback));
    await textarea.press('Tab').catch(() => {});
    const retainedDeadline = Date.now() + 1_500;
    let stableReads = 0;
    let retainedMessage = '';
    do {
      retainedMessage = String(await textarea.inputValue().catch(() => '')).trim();
      const retained = retainedMessage === fallback
        && expected.every((term) => normalizeMessage(retainedMessage).includes(term));
      stableReads = retained ? stableReads + 1 : 0;
      if (stableReads >= 2) {
        messages = [retainedMessage];
        writeProgress({
          step: 'ordinary-pdd-generated-message-recovered',
          ordinaryPddGeneratedMessageRecovery: {
            orderNumber: readProgress().orderNumber || null,
            status: 'succeeded',
            strategy: 'unique-editable-recommendation-textarea',
            originalLength: originalMessage.length,
            fallbackLength: fallback.length,
            requiredTermCount: expected.length,
            recoveredAt: new Date().toISOString(),
          },
        });
        return true;
      }
      const remainingMs = retainedDeadline - Date.now();
      if (remainingMs > 0) await targetPage.waitForTimeout(Math.min(100, remainingMs));
    } while (Date.now() < retainedDeadline);
    writeProgress({
      ordinaryPddGeneratedMessageRecovery: {
        orderNumber: readProgress().orderNumber || null,
        status: 'failed-not-retained',
        strategy: 'unique-editable-recommendation-textarea',
        observedLength: retainedMessage.length,
        requiredTermCount: expected.length,
        failedAt: new Date().toISOString(),
      },
    });
    return false;
  };
  do {
    messages = [];
    const textareas = targetPage.locator('textarea:visible');
    for (let index = 0; index < await textareas.count().catch(() => 0); index += 1) {
      const textarea = textareas.nth(index);
      const value = String(await textarea.inputValue().catch(() => '') || '').trim();
      if (value) messages.push(value);
    }
    const normalizedMessages = messages.map(normalizeMessage);
    if (normalizedMessages.length
      && normalizedMessages.some((message) => matchesGeneratedMessage(message))) {
      return messages;
    }
    if (Date.now() >= fallbackEligibleAt && await tryFallback()) return messages;
    if (Date.now() < deadline) await targetPage.waitForTimeout(250);
  } while (Date.now() < deadline);
  if (await tryFallback()) return messages;
  const error = !messages.length
    ? new Error('拼多多未生成可发送给消费者的话术')
    : new Error(`拼多多自动话术未包含必需内容: ${expected.join(' / ')}`);
  Object.defineProperty(error, 'ordinaryPddRecoveryTargetPage', {
    value: targetPage,
    enumerable: false,
  });
  await saveWorkflowDiagnostics(
    targetPage,
    'ordinary-pdd-generated-message-invalid',
    error,
  ).catch(() => {});
  throw error;
};

const selectOrdinaryPddDropdownOption = async (
  targetPage,
  labelPattern,
  optionLabels,
  { matchAll = [], required: isRequired = true } = {},
) => {
  const normalizeOptionText = (value) => String(value || '').replace(/\s+/gu, '').trim();
  const candidates = [...new Set(optionLabels.map(normalizeOptionText).filter(Boolean))];
  const requiredTerms = [...new Set(matchAll.map(normalizeOptionText).filter(Boolean))];
  const matches = (value) => {
    const normalized = normalizeOptionText(value);
    return candidates.includes(normalized)
      || (requiredTerms.length > 0 && requiredTerms.every((term) => normalized.includes(term)));
  };
  const deadline = Date.now() + pddRenderWaitMs;
  let formItem = null;
  let dropdown = null;
  do {
    const labels = targetPage.getByText(labelPattern);
    for (let index = 0; index < await labels.count().catch(() => 0); index++) {
      const label = labels.nth(index);
      if (!await label.isVisible().catch(() => false)) continue;
      const candidateForm = label.locator(
        'xpath=ancestor::*[.//*[@role="combobox"] or .//select or .//*[contains(@class,"select")]][1]',
      );
      const candidateDropdown = await firstVisible([
        candidateForm.getByRole('combobox').first(),
        candidateForm.locator('select').first(),
        candidateForm.locator('.ant-select-selector, .el-select, [class*="select-selector"]').first(),
        label.locator('xpath=following::*[@role="combobox" or self::select or contains(@class,"select")][1]'),
      ]);
      if (!candidateDropdown) continue;
      formItem = candidateForm;
      dropdown = candidateDropdown;
      break;
    }
    if (!dropdown && Date.now() < deadline) await targetPage.waitForTimeout(250);
  } while (!dropdown && Date.now() < deadline);
  let fallbackDiagnostics = [];
  if (!dropdown) {
    const formScope = await ordinaryFormScope(targetPage);
    const fallbackCandidates = formScope.locator([
      '[role="combobox"]',
      'select',
      '.ant-select-selector',
      '.el-select',
      '[class*="select-selector"]',
    ].join(', '));
    const visibleFallbacks = [];
    for (let index = 0; index < await fallbackCandidates.count().catch(() => 0); index++) {
      const candidate = fallbackCandidates.nth(index);
      if (!await candidate.isVisible().catch(() => false)
        || !await candidate.isEnabled().catch(() => false)) continue;
      const contextText = await candidate.evaluate((element) => {
        const segments = [];
        let current = element;
        for (let depth = 0; current && depth < 5; depth++, current = current.parentElement) {
          const text = String(current.innerText || '').trim();
          if (text && text.length <= 800) segments.push(text);
        }
        return segments.join('\n');
      }).catch(() => '');
      const normalizedContext = contextText.normalize('NFKC').replace(/\s+/gu, '');
      labelPattern.lastIndex = 0;
      const labelMatched = labelPattern.test(contextText);
      const semanticMatched = normalizedContext.includes('未更新')
        && /(?:承诺|补发|退款)/u.test(normalizedContext);
      const metadata = {
        index,
        tag: await candidate.evaluate((element) => element.tagName.toLowerCase()).catch(() => null),
        role: await candidate.getAttribute('role').catch(() => null),
        text: contextText.slice(0, 500),
        labelMatched,
        semanticMatched,
      };
      fallbackDiagnostics.push(metadata);
      visibleFallbacks.push({ candidate, metadata });
    }
    const semanticFallbacks = visibleFallbacks.filter(({ metadata }) => (
      metadata.labelMatched || metadata.semanticMatched
    ));
    const fallback = semanticFallbacks.length === 1
      ? semanticFallbacks[0]
      : semanticFallbacks.length === 0 && visibleFallbacks.length === 1
        ? visibleFallbacks[0]
        : null;
    if (fallback) {
      dropdown = fallback.candidate;
      const candidateForm = dropdown.locator(
        'xpath=ancestor::*[.//*[@role="combobox"] or .//select or .//*[contains(@class,"select")]][1]',
      ).first();
      formItem = await candidateForm.count().catch(() => 0) ? candidateForm : formScope;
      writeProgress({
        ordinaryPddDropdownRecovery: {
          orderNumber: readProgress().orderNumber || null,
          field: String(labelPattern),
          status: 'located',
          strategy: fallback.metadata.labelMatched
            ? 'form-context-label'
            : fallback.metadata.semanticMatched
              ? 'form-context-semantics'
              : 'sole-form-combobox',
          candidateCount: visibleFallbacks.length,
          locatedAt: new Date().toISOString(),
        },
      });
    }
  }
  if (!dropdown) {
    if (!isRequired) return null;
    const message = `拼多多未找到“${labelPattern}”下拉框`;
    writeProgress({
      ordinaryPddDropdownLookupFailure: {
        orderNumber: readProgress().orderNumber || null,
        field: String(labelPattern),
        status: 'failed',
        candidates: fallbackDiagnostics,
        failedAt: new Date().toISOString(),
      },
    });
    await saveWorkflowDiagnostics(targetPage, 'ordinary-pdd-dropdown-missing', new Error(message))
      .catch(() => {});
    throw new Error(message);
  }

  const tagName = await dropdown.evaluate((element) => element.tagName.toLowerCase()).catch(() => '');
  let selectedText = '';
  if (tagName === 'select') {
    const nativeOptions = dropdown.locator('option');
    for (let index = 0; index < await nativeOptions.count().catch(() => 0); index++) {
      const text = await nativeOptions.nth(index).innerText().catch(() => '');
      if (matches(text)) { selectedText = text.trim(); break; }
    }
    if (selectedText) await dropdown.selectOption({ label: selectedText });
  } else {
    await pacedAction(targetPage, 'open-pdd-unupdated-promise-dropdown', () => dropdown.click({ force: true }));
    await targetPage.waitForTimeout(300);
    const optionDeadline = Date.now() + pddRenderWaitMs;
    do {
      const options = targetPage.locator([
        '[role="option"]:visible',
        '.ant-select-item-option:visible',
        '.el-select-dropdown__item:visible',
        '[class*="select-option"]:visible',
      ].join(', '));
      for (let index = 0; index < await options.count().catch(() => 0); index++) {
        const option = options.nth(index);
        const text = await option.innerText().catch(() => '');
        if (!matches(text)) continue;
        selectedText = text.trim();
        await pacedAction(targetPage, 'select-pdd-unupdated-promise', () => option.click({ force: true }));
        break;
      }
      if (!selectedText && Date.now() < optionDeadline) await targetPage.waitForTimeout(250);
    } while (!selectedText && Date.now() < optionDeadline);
  }
  if (!selectedText) {
    if (!isRequired) return null;
    throw new Error(`拼多多“${labelPattern}”下拉框未找到补发且退款的承诺选项`);
  }
  await targetPage.waitForTimeout(250);
  const retainedText = [
    await formItem?.innerText().catch(() => ''),
    await dropdown.innerText().catch(() => ''),
    await dropdown.inputValue().catch(() => ''),
    await dropdown.getAttribute('title').catch(() => ''),
  ].join(' ');
  if (!matches(retainedText)) {
    throw new Error(`拼多多“${labelPattern}”选择“${selectedText}”后未保持`);
  }
  return selectedText;
};

const beijingDateAfterDays = (days) => {
  const date = new Date(Date.now() + days * 24 * 60 * 60_000 + 8 * 60 * 60_000);
  return `${date.getUTCFullYear()}-${String(date.getUTCMonth() + 1).padStart(2, '0')}-${String(date.getUTCDate()).padStart(2, '0')}`;
};

const closePddLogisticsOverlay = async (targetPage) => {
  const close = await firstVisible([
    targetPage.getByRole('button', { name: '知道了', exact: true }),
    targetPage.getByText('知道了', { exact: true }),
    targetPage.locator('[role="dialog"] button').filter({ hasText: /^(知道了|关闭)$/ }),
  ]);
  if (!close) return false;
  await pacedAction(targetPage, 'close-pdd-logistics-overlay', () => close.click({ force: true }));
  return true;
};

const ordinaryEvidenceSource = (decision) => (
  decision?.evidence?.required?.find((item) => item?.required !== false)?.source || null
);

const ordinaryEvidenceSources = (decision) => {
  const required = Array.isArray(decision?.evidence?.required)
    ? decision.evidence.required
      .filter((item) => item?.required !== false && String(item?.source || '').trim())
      .map((item) => String(item.source).trim())
    : [];
  return [...new Set(required.length ? required : [ordinaryEvidenceSource(decision)].filter(Boolean))];
};

const expectedChatEvidencePath = (orderNumber) => {
  if (!/^[0-9]+(?:-[0-9]+)+$/.test(orderNumber || '')) {
    throw new Error(`聊天截图订单编号格式不安全: ${orderNumber}`);
  }
  return path.join(evidenceScreenshotDir, `${orderNumber}-chat.png`);
};

const capturePddChatEvidenceScreenshot = async (targetPage, orderNumber, decision) => {
  const chat = decision?.evidence?.chatAnalysis || {};
  const messages = new Map((chat.messages || []).map((message) => [message.id, message]));
  const references = (chat.analysis?.evidence || [])
    .filter((item) => item?.messageId && item?.quote)
    .map((item) => {
      const message = messages.get(item.messageId);
      if (!message || !String(message.text || message.rawText || '').includes(String(item.quote))) {
        throw new Error('模型聊天证据无法与采集原文对应，禁止上传无关截图');
      }
      if (!Number.isInteger(Number(message.source?.page)) || Number(message.source.page) < 1) {
        throw new Error('聊天证据原消息缺少可核验分页位置');
      }
      const range = message.source?.range;
      const validDate = (value) => /^\d{4}-\d{2}-\d{2}$/u.test(String(value || ''))
        && Number.isFinite(Date.parse(value)) && new Date(value).toISOString().slice(0, 10) === value;
      if (!validDate(range?.from) || !validDate(range?.to) || range.from > range.to) {
        throw new Error('聊天证据原消息缺少可核验查询日期范围');
      }
      // The model returns message IDs and quotes, not trusted UI coordinates.
      // The collector's original message is the authority for its page.
      return { ...item, source: message.source };
    });
  if (!references.length) throw new Error('模型没有提供可定位的聊天原话证据，禁止上传聊天截图');
  const absolutePath = expectedChatEvidencePath(orderNumber);
  const relativePath = toPortableRelativePath(workflowDataDir, absolutePath);
  let page = reusableChatPage && !reusableChatPage.isClosed() ? reusableChatPage : null;
  let ownedPage = false;
  let keepSuspendedPage = false;
  try {
    if (!page) { page = registerDerivedPage(await createBackgroundPage(), 'pdd-chat-evidence'); ownedPage = true; }
    await checkForHumanVerification(page, 'chat-evidence-open');
    if (!page.url().includes('/mms-chat/search')) {
      await navigateSystemPage(
        page,
        'https://mms.pinduoduo.com/mms-chat/search?msfrom=mms_sidenav',
        'chat-evidence-open',
      );
      await ensurePddLogin(page, context, page.url());
    }
    const firstVisiblePage = async (locators) => {
      for (const locator of locators) {
        if (!locator) continue;
        for (let index = 0; index < await locator.count().catch(() => 0); index += 1) {
          const candidate = locator.nth(index);
          if (await candidate.isVisible().catch(() => false)) return candidate;
        }
      }
      return null;
    };
    const radio = await firstVisiblePage([
      page.getByText(/按订单[\/／]违规会话编号查询/),
      page.getByRole('radio', { name: /按订单/ }),
      page.locator('label').filter({ hasText: /按订单[\/／]违规会话编号/ }),
    ]);
    if (radio) {
      await radio.click({ force: true });
      // The chat page re-renders the form after changing the query mode. Give
      // the controlled input time to settle before resolving it again; using
      // a locator captured before that render can silently target a stale node.
      await page.waitForTimeout(300);
    }
    const findChatOrderInput = () => firstVisiblePage([
      page.getByRole('textbox', { name: /订单.*违规会话编号/ }),
      page.locator('input[placeholder*="订单"],input[placeholder*="会话"]'),
    ]);
    let input = await findChatOrderInput();
    if (!input) throw new Error('聊天证据页面未找到订单查询输入框');
    await checkForHumanVerification(page, 'chat-evidence-order-input');
    const orderInputDeadline = Date.now() + 5_000;
    let observedOrderValue = '';
    let lastOrderInputError = null;
    while (Date.now() < orderInputDeadline) {
      input = await findChatOrderInput();
      if (!input) {
        await page.waitForTimeout(150);
        continue;
      }
      try {
        if (!await input.isEditable().catch(() => false)) {
          lastOrderInputError = new Error('聊天证据订单查询输入框当前不可编辑');
        } else {
          const currentValue = String(await input.inputValue().catch(() => '')).trim();
          if (currentValue !== orderNumber) {
            await input.click({ force: true });
            await input.fill(orderNumber);
            await input.press('Tab').catch(() => {});
          }
          observedOrderValue = String(await input.inputValue().catch(() => '')).trim();
          if (observedOrderValue === orderNumber) break;
          // Ant-design controlled inputs can restore their previous value when
          // a form transition finishes. A real keyboard replacement gives the
          // page another input event sequence before we yield the workflow.
          await input.click({ force: true });
          await input.press('Control+A');
          await input.type(orderNumber, { delay: 20 });
          await input.press('Tab').catch(() => {});
          observedOrderValue = String(await input.inputValue().catch(() => '')).trim();
          if (observedOrderValue === orderNumber) break;
          lastOrderInputError = new Error(
            `聊天证据订单查询输入框值为“${observedOrderValue}”`,
          );
        }
      } catch (error) {
        lastOrderInputError = error;
      }
      await checkForHumanVerification(page, 'chat-evidence-order-input-retry');
      await page.waitForTimeout(150);
    }
    if (observedOrderValue !== orderNumber) {
      throw new Error(
        `聊天证据查询订单号未正确填写${lastOrderInputError ? `：${lastOrderInputError.message}` : ''}`,
      );
    }
    const query = await firstVisiblePage([
      page.getByRole('button', { name: '查询', exact: true }),
      page.getByText('查询', { exact: true }),
    ]);
    if (!query) throw new Error('聊天证据页面未找到查询按钮');
    // A page number is meaningful only inside the original collection range.
    // A reused chat tab may still contain another range, even for this order.
    const groups = new Map();
    for (const reference of references) {
      const { range, page: sourcePage } = reference.source;
      const key = `${range.from}|${range.to}|${Number(sourcePage)}`;
      if (!groups.has(key)) groups.set(key, { range, sourcePage: Number(sourcePage), references: [] });
      groups.get(key).references.push(reference);
    }
    let found = [];
    let appliedRange = null;
    for (const { range, sourcePage, references: groupReferences } of groups.values()) {
      const rangeKey = `${range.from}|${range.to}`;
      if (appliedRange !== rangeKey) {
        await checkForHumanVerification(page, 'chat-evidence-date-range');
        const allInputs = page.locator('input:visible');
        const dateInputs = [];
        for (let index = 0; index < await allInputs.count(); index += 1) {
          const candidate = allInputs.nth(index);
          const value = await candidate.inputValue().catch(() => '');
          const placeholder = await candidate.getAttribute('placeholder') || '';
          if (/20\d\d[-/]\d\d[-/]\d\d/u.test(value) || /开始日期|结束日期/u.test(placeholder)) dateInputs.push(candidate);
        }
        if (dateInputs.length === 2) {
          for (const [index, value] of [range.from, range.to].entries()) {
            if (await dateInputs[index].inputValue() !== value) {
              await dateInputs[index].fill(value); await dateInputs[index].press('Enter');
            }
            if (await dateInputs[index].inputValue() !== value) throw new Error('聊天证据日期范围未正确应用');
          }
        } else if (dateInputs.length === 1) {
          const expected = [range.from, range.to];
          const dates = () => dateInputs[0].inputValue().then((value) => value.match(/20\d\d-\d\d-\d\d/gu) || []);
          if (JSON.stringify(await dates()) !== JSON.stringify(expected)) {
            await dateInputs[0].fill(`${range.from} ~ ${range.to}`); await dateInputs[0].press('Enter');
          }
          if (JSON.stringify(await dates()) !== JSON.stringify(expected)) throw new Error('聊天证据日期范围未正确应用');
        } else throw new Error('聊天证据页面未识别到查询日期范围');
        await checkForHumanVerification(page, 'chat-evidence-query');
        await query.click({ force: true }); await page.waitForTimeout(1200);
        appliedRange = rangeKey;
      }
      await checkForHumanVerification(page, 'chat-evidence-page');
      const pageButton = await firstVisiblePage([
        page.locator(`li.ant-pagination-item-${sourcePage}:visible`),
        page.locator('li:visible,button:visible').filter({ hasText: new RegExp(`^\\s*${sourcePage}\\s*$`, 'u') }),
      ]);
      if (pageButton && await pageButton.isEnabled().catch(() => false)) {
        await pageButton.click({ force: true }); await page.waitForTimeout(700);
      }
      for (const reference of groupReferences) {
        const quote = page.getByText(String(reference.quote), { exact: false }).first();
        if (await quote.isVisible().catch(() => false)) {
          await quote.scrollIntoViewIfNeeded().catch(() => {});
          found.push({ messageId: reference.messageId, quote: reference.quote, page: sourcePage, range });
        }
      }
      if (found.length) break;
    }
    if (!found.length) throw new Error('聊天证据原话未在对应分页中找到，禁止上传无关截图');
    await checkForHumanVerification(page, 'chat-evidence-screenshot');
    const screenshotTarget = await firstVisiblePage([page.locator('main'), page.locator('body')]);
    if (!screenshotTarget) throw new Error('聊天证据页面没有可截图区域');
    const buffer = await screenshotTarget.screenshot({ type: 'png', animations: 'disabled', caret: 'hide' });
    const inspection = inspectPngBuffer(buffer, { minWidth: 500, minHeight: 300 });
    fs.mkdirSync(evidenceScreenshotDir, { recursive: true, mode: 0o700 });
    fs.writeFileSync(absolutePath, buffer, { mode: 0o600 }); fs.chmodSync(absolutePath, 0o600);
    const metadata = {
      shopId, orderNumber, relativePath, mimeType: 'image/png', width: inspection.width,
      height: inspection.height, sizeBytes: inspection.sizeBytes, status: 'ready',
      purpose: 'pdd-chat-evidence', evidence: found, createdAt: new Date().toISOString(),
      chatCaseId: chat.caseId || null, chatJobId: chat.jobId || null, chatSnapshotId: chat.snapshotId || null,
    };
    writeProgress({ chatEvidenceScreenshot: metadata, step: 'pdd-chat-evidence-screenshot-ready' });
    return metadata;
  } catch (error) {
    if (error instanceof HumanVerificationRequiredError
      || error instanceof PddLoginRequiredError
      || error instanceof RateLimitPauseError) {
      keepSuspendedPage = true;
      if (ownedPage && page && !page.isClosed()) reusableChatPage = page;
      throw error;
    }
    writeProgress({
      step: 'pdd-chat-evidence-screenshot-failed',
      chatEvidenceScreenshot: { shopId, orderNumber, relativePath, mimeType: 'image/png', status: 'failed',
        purpose: 'pdd-chat-evidence', failedAt: new Date().toISOString(), error: error.message },
    });
    throw error;
  } finally {
    if (!keepSuspendedPage && ownedPage && page && !page.isClosed()) await closeDerivedPage(page).catch(() => {});
  }
};

const resolveOrdinaryPddEvidence = (orderNumber) => resolveReadyEvidenceScreenshot(
  orderNumber,
  readProgress(),
);

const ensureOrdinaryScenarioEvidence = async (targetPage, orderNumber, scenarioCode, decision) => {
  const source = ordinaryEvidenceSource(decision);
  if (!source) return null;
  if ([
    'tms-recall-evidence',
    'tms-reminder-evidence',
    'tms-delivery-contact-evidence',
    'tms-product-shortage-contact-evidence',
    'tms-delivered-address-change-evidence',
    'tms-address-change-evidence',
  ].includes(source)) {
    return resolveReadyTmsEvidence(orderNumber, readProgress());
  }
  if (source === 'pdd-chat-evidence') {
    const existingChat = readProgress().chatEvidenceScreenshot;
    const chat = decision?.evidence?.chatAnalysis || {};
    if (existingChat?.status === 'ready' && existingChat.shopId === shopId
      && existingChat.orderNumber === orderNumber && existingChat.relativePath
      && chat.caseId && chat.jobId && chat.snapshotId
      && existingChat.chatCaseId === chat.caseId && existingChat.chatJobId === chat.jobId
      && existingChat.chatSnapshotId === chat.snapshotId) {
      const absolutePath = path.resolve(workflowDataDir, existingChat.relativePath);
      if (isPathInside(evidenceScreenshotDir, absolutePath) && exists(absolutePath)) {
        return { absolutePath, metadata: existingChat };
      }
    }
    const metadata = await capturePddChatEvidenceScreenshot(targetPage, orderNumber, decision);
    return { absolutePath: path.resolve(workflowDataDir, metadata.relativePath), metadata };
  }
  const existing = readProgress().pddEvidenceScreenshot;
  if (existing?.status === 'ready'
    && existing.orderNumber === orderNumber
    && existing.relativePath) {
    return resolveOrdinaryPddEvidence(orderNumber);
  }
  await focusSystemPage('pdd', targetPage);
  await openPddLogisticsKindWithRetry(
    targetPage,
    source === 'pdd-return-logistics-screenshot' ? '退货物流' : '发货物流',
    { orderNumber, scenarioCode, stagePrefix: 'ordinary-evidence' },
  );
  await capturePddScenarioEvidenceScreenshot(targetPage, orderNumber, source);
  await closePddLogisticsOverlay(targetPage);
  return resolveOrdinaryPddEvidence(orderNumber);
};

const uploadOrdinaryScenarioEvidence = async (targetPage, orderNumber, scenarioCode, decision) => {
  const sources = ordinaryEvidenceSources(decision);
  if (!sources.length) return null;
  const progress = readProgress();
  const existingUploads = Array.isArray(progress.ordinaryEvidenceUploads)
    ? progress.ordinaryEvidenceUploads
    : progress.ordinaryEvidenceUpload?.source
      ? [progress.ordinaryEvidenceUpload]
      : [];
  const uploadedRecords = [];
  for (const source of sources) {
    const prior = existingUploads.find((item) => item?.source === source
      && item?.status === 'uploaded'
      && item?.orderNumber === orderNumber);
    if (prior) {
      if (!await pddEvidenceUploadedMarkerVisible(targetPage)) {
        throw new ManualReviewRequiredError(
          'pdd-evidence-form-attachment',
          '先前上传的凭证未保留在当前拼多多表单，禁止跳过上传后直接提交',
        );
      }
      uploadedRecords.push(prior);
      continue;
    }
    const sourceDecision = {
      ...decision,
      evidence: {
        ...(decision.evidence || {}),
        required: (decision.evidence?.required || []).filter((item) => item?.source === source),
      },
    };
    const evidence = await ensureOrdinaryScenarioEvidence(
      targetPage,
      orderNumber,
      scenarioCode,
      sourceDecision,
    );
    try {
      const uploaded = await uploadTmsEvidenceToPdd(targetPage, orderNumber, {
        evidence,
        progressField: 'ordinaryEvidenceUpload',
        actionLabel: `ordinary-${scenarioCode}-${source.replace(/[^a-z0-9_-]/gi, '-')}`,
      });
      const recorded = { ...uploaded, source, scenarioCode };
      uploadedRecords.push(recorded);
      writeProgress({ ordinaryEvidenceUpload: recorded, ordinaryEvidenceUploads: uploadedRecords });
      updateOrdinaryExecution(orderNumber, scenarioCode, {
        pddEvidenceUploadFailed: false,
        evidenceUpload: recorded,
      });
    } catch (error) {
      if (shouldOmitOrdinaryRecallEvidence({ scenarioCode, decision: sourceDecision, error })) {
      const semanticSelectedLabel = readProgress()
        .ordinaryPddSemanticOptionSelection?.selectedLabel || null;
      const selectedOptionLabel = semanticSelectedLabel
        && ordinaryPddOptionsSemanticallyEquivalent([sourceDecision.pdd.option], semanticSelectedLabel)
        ? semanticSelectedLabel
        : sourceDecision.pdd.option;
      const optionStillSelected = await isPddOptionSelected(
        targetPage.locator('body'),
        selectedOptionLabel,
      );
      const submitButton = await firstVisible([
        targetPage.locator('button').filter({ hasText: /^\s*提交\s*$/ }),
        targetPage.getByRole('button', { name: '提交', exact: true }),
      ]);
      const submitEnabled = Boolean(submitButton && await submitButton.isEnabled().catch(() => false));
      if (optionStillSelected && submitEnabled) {
        const failedUpload = readProgress().ordinaryEvidenceUpload || {};
        const omission = {
          shopId,
          orderNumber,
          source,
          scenarioCode,
          status: 'omitted',
          reasonCode: 'pdd-upload-authorization-rejected',
          errorCode: error.pddEvidenceUploadAuthorizationFailure?.errorCode || 48143,
          errorMessage: error.pddEvidenceUploadAuthorizationFailure?.errorMessage || error.message,
          failedUploadStatus: failedUpload.status || 'failed',
          omittedAt: new Date().toISOString(),
        };
        writeProgress({
          step: 'ordinary-evidence-upload-omitted',
          ordinaryEvidenceUpload: omission,
          ordinaryEvidenceUploads: [...uploadedRecords, omission],
        });
      updateOrdinaryExecution(orderNumber, scenarioCode, {
        pddEvidenceUploadFailed: false,
        evidenceUpload: omission,
      });
        uploadedRecords.push(omission);
        continue;
      }
      }
      const uploadStatus = error.externalEffectStatus === 'failed' ? 'failed' : 'unknown';
      updateOrdinaryExecution(orderNumber, scenarioCode, {
        pddEvidenceUploadFailed: true,
        evidenceUpload: {
          source,
          status: uploadStatus,
          error: error.message,
          failedAt: new Date().toISOString(),
        },
      });
      throw error;
    }
  }
  const latest = uploadedRecords.at(-1) || null;
  writeProgress({ ordinaryEvidenceUploads: uploadedRecords, ordinaryEvidenceUpload: latest });
  return latest;
};

const applyOrdinaryPddFormDecisionOnce = async (targetPage, decision) => {
  const pdd = decision.pdd || {};
  const optionSelection = { allowJudgment: pdd.strictOptionSelection !== true };
  const primaryLabels = [pdd.option, ...(pdd.optionAliases || [])].filter(Boolean);
  const terminalOption = pdd.completionOption || pdd.resultOption || null;
  const terminalLabels = [
    terminalOption,
    ...(pdd.completionOption ? (pdd.completionOptionAliases || []) : (pdd.resultOptionAliases || [])),
  ].filter(Boolean);
  const expandedTerminalLabels = expandOrdinaryPddOptionAliases(terminalLabels);
  let terminalSelected = false;
  let selectedOption = null;
  let pickupAddressFieldFilled = null;
  const selectedOptions = [];
  if (pdd.option && pdd.option !== '反馈' && terminalOption && terminalOption !== pdd.option) {
    // PDD currently has two live layouts for these work orders. Older pages
    // show the initial action first and render the result in a later follow-up,
    // while newer pages expose the final result immediately. Select whichever
    // stage is actually rendered; never require both on the same page.
    selectedOption = await selectOrdinaryPddOption(
      targetPage,
      [...terminalLabels, ...primaryLabels],
      optionSelection,
    );
    const judgmentSelection = readProgress().ordinaryPddJudgmentOptionSelection;
    const judgmentRepresentsTerminal = judgmentSelection?.selectedLabel === selectedOption
      && judgmentSelection.representsRequestedIntent === true
      && ordinaryPddOptionsSemanticallyEquivalent(
        terminalLabels,
        judgmentSelection.requestedLabel,
      );
    terminalSelected = expandedTerminalLabels.includes(selectedOption)
      || ordinaryPddOptionsSemanticallyEquivalent(terminalLabels, selectedOption)
      || judgmentRepresentsTerminal;
  } else if (pdd.option && pdd.option !== '反馈') {
    selectedOption = await selectOrdinaryPddOption(targetPage, primaryLabels, optionSelection);
  }
  if (terminalOption && !selectedOption) {
    selectedOption = await selectOrdinaryPddOption(targetPage, terminalLabels, optionSelection);
    terminalSelected = true;
  }
  if (selectedOption) selectedOptions.push(selectedOption);
  if (pdd.secondaryOption) {
    const secondaryOption = await selectOrdinaryPddOption(targetPage, [
      pdd.secondaryOption,
      ...(pdd.secondaryOptionAliases || []),
    ], optionSelection);
    selectedOptions.push(secondaryOption);
  }
  if (pdd.reasonOption) {
    selectedOptions.push(await selectOrdinaryPddOption(
      targetPage,
      [pdd.reasonOption],
      optionSelection,
    ));
  }
  if (pdd.deliveryAddress) {
    // Current PDD builds render this as a textarea, while an older layout used
    // an input. Prefer the multiline control so a neighboring phone input can
    // never receive the numeric fragments of an address.
    await fillOrdinaryPddField(
      targetPage,
      /^(?:[*＊]\s*)?送达地址\s*$/,
      pdd.deliveryAddress,
      { textareaPreferred: true },
    );
  }
  if (pdd.courierPhone) {
    await fillOrdinaryPddField(targetPage, /快递员电话|派件员电话|配送员电话/, pdd.courierPhone);
  }
  if (pdd.pickupAddress) {
    pickupAddressFieldFilled = await fillOrdinaryPddField(
      targetPage,
      /^(?:[*＊]\s*)?(?:自取地址|取件地址)\s*$/,
      pdd.pickupAddress,
      { textareaPreferred: true, required: false },
    );
    if (!pickupAddressFieldFilled) {
      const normalizeProofTerm = (value) => String(value || '')
        .normalize('NFKC')
        .replace(/\s+/gu, '')
        .trim();
      const normalizedPickupAddress = normalizeProofTerm(pdd.pickupAddress);
      const generatedMessageProofConfigured = pdd.generatedMessageRequired === true
        && (pdd.generatedMessageMustInclude || []).some((term) => (
          normalizeProofTerm(term).includes(normalizedPickupAddress)
        ));
      if (!normalizedPickupAddress || !generatedMessageProofConfigured) {
        throw new Error('拼多多未找到“自取地址/取件地址”输入框，且未配置包含真实取件地址的自动话术校验');
      }
    }
  }
  if (pdd.trajectoryUpdateDateOffsetDays) {
    await fillOrdinaryPddField(
      targetPage,
      /轨迹更新日期|物流更新日期|预计更新日期/,
      beijingDateAfterDays(pdd.trajectoryUpdateDateOffsetDays),
      { datePicker: true },
    );
  }
  if (Number.isInteger(pdd.expectedContactDateOffsetDays)) {
    await fillOrdinaryPddField(
      targetPage,
      /预计联系时间|预计联系日期|联系时间/,
      beijingDateAfterDays(pdd.expectedContactDateOffsetDays),
      { datePicker: true, required: false },
    );
  }
  if (Number.isInteger(pdd.verificationDateOffsetDays)) {
    const judgmentSelection = readProgress().ordinaryPddJudgmentOptionSelection;
    const configuredOptionReplacedByJudgment = Boolean(
      selectedOption
      && judgmentSelection?.selectedLabel === selectedOption
      && !ordinaryPddOptionsSemanticallyEquivalent(
        [...primaryLabels, ...terminalLabels],
        selectedOption,
      ),
    );
    const verificationDateFilled = await fillOrdinaryPddField(
      targetPage,
      /核实时间|核实日期|预计核实时间|预计核实日期/,
      beijingDateAfterDays(pdd.verificationDateOffsetDays),
      { datePicker: true, required: !configuredOptionReplacedByJudgment },
    );
    if (!verificationDateFilled && configuredOptionReplacedByJudgment) {
      writeProgress({
        ordinaryPddStageVariant: {
          status: 'confirmed',
          configuredOption: pdd.option,
          visibleSelectedOption: selectedOption,
          omittedField: 'verification-date',
          reason: 'judgment-selected-rendered-followup-stage-without-date-field',
          confirmedAt: new Date().toISOString(),
        },
      });
    }
  }
  if (pdd.verificationResult) {
    await fillOrdinaryPddField(
      targetPage,
      /核实结果|核实情况|核实说明/,
      pdd.verificationResult,
      { textarea: true },
    );
  }
  if (pdd.verificationDescription) {
    await fillOrdinaryPddField(
      targetPage,
      /^(?:[*＊]\s*)?说明\s*[:：]?$/u,
      pdd.verificationDescription,
      { textarea: true },
    );
  }
  if (pdd.situationDescription) {
    await fillOrdinaryPddField(
      targetPage,
      /^(?:[*＊]\s*)?(?:情况说明|核实情况说明|说明)\s*[:：]?$/u,
      pdd.situationDescription,
      { textarea: true },
    );
  }
  if (pdd.compensationOption) {
    // The compensation control is rendered as a radio in some builds and a
    // select in others. Try the common radio path first, then the labelled
    // dropdown helper without changing any unrelated controls.
    try {
      await selectOrdinaryPddOption(targetPage, [pdd.compensationOption], optionSelection);
    } catch {
      await selectOrdinaryPddDropdownOption(
        targetPage,
        /补偿方案/u,
        [pdd.compensationOption],
      );
    }
  }
  if (pdd.solutionMessage) {
    await fillOrdinaryPddField(
      targetPage,
      /^(?:[*＊]\s*)?解决方案\s*[:：]?$/u,
      pdd.solutionMessage,
      { textarea: true },
    );
  }
  if (pdd.tertiaryOption) {
    try {
      await selectOrdinaryPddOption(targetPage, [pdd.tertiaryOption], optionSelection);
    } catch {
      await selectOrdinaryPddDropdownOption(
        targetPage,
        /解决方案/u,
        [pdd.tertiaryOption],
      );
    }
  }
  if (pdd.unupdatedPromiseOption) {
    await selectOrdinaryPddDropdownOption(
      targetPage,
      /未更新承诺协商|未更新承诺|物流未更新.*承诺/,
      [pdd.unupdatedPromiseOption, ...(pdd.unupdatedPromiseOptionAliases || [])],
      { matchAll: pdd.unupdatedPromiseMatchAll || [] },
    );
  }
  if (pdd.reissueTrackingNumber) {
    await fillOrdinaryPddField(
      targetPage,
      /补发单号|补发快递单号|新运单号/,
      pdd.reissueTrackingNumber,
    );
    // PDD normally recognizes the carrier from the waybill and renders an
    // option such as “圆通快递 <waybill>”. Select that suggestion when it is
    // present; do not type a carrier alias from OMS into the form.
    const trackingNeedle = String(pdd.reissueTrackingNumber).trim();
    if (trackingNeedle) {
      await targetPage.waitForTimeout(400);
      const suggestionCandidates = targetPage.locator([
        '[role="option"]:visible',
        '.el-select-dropdown__item:visible',
        '.ant-select-item-option:visible',
        'li:visible',
      ].join(', '));
      for (let index = 0; index < await suggestionCandidates.count().catch(() => 0); index += 1) {
        const suggestion = suggestionCandidates.nth(index);
        const text = await suggestion.innerText().catch(() => '');
        if (!String(text).includes(trackingNeedle)) continue;
        await suggestion.click({ force: true });
        break;
      }
    }
  }
  if (pdd.customerMessage) {
    await fillOrdinaryPddField(
      targetPage,
      /回复消费者|沟通内容|处理说明|^(?:[*＊]\s*)?说明\s*[:：]?$|留言|回复内容/,
      pdd.customerMessage,
      { textarea: true, required: pdd.customerMessageOptional !== true },
    );
  }
  let generatedMessages = [];
  if (pdd.generatedMessageRequired) {
    const acceptedMessages = decision.scenarioCode === IN_TRANSIT_ADDRESS_CHANGE_CODE
      && pdd.stageCode === IN_TRANSIT_ADDRESS_CHANGE_STAGE_CODES.contact
      ? [
        ...(pdd.generatedMessageAcceptedVariants || []),
        ...IN_TRANSIT_ADDRESS_CHANGE_MESSAGE_VARIANTS.contact,
      ]
      : (pdd.generatedMessageAcceptedVariants || []);
    generatedMessages = await verifyOrdinaryPddGeneratedMessage(
      targetPage,
      pdd.generatedMessageMustInclude || [],
      {
        fallbackMessage: pdd.pickupAddress && pickupAddressFieldFilled === false
          ? pdd.generatedMessageFallback
          : null,
        acceptedMessages,
      },
    );
  }
  if (pdd.pickupAddress && pickupAddressFieldFilled === false) {
    writeProgress({
      ordinaryPddPickupAddressProof: {
        status: 'verified',
        fieldRendered: false,
        addressLength: String(pdd.pickupAddress).trim().length,
        generatedMessageCount: generatedMessages.length,
        confirmationMethod: 'generated-message-contains-verified-pickup-address',
        verifiedAt: new Date().toISOString(),
      },
    });
  }
  return {
    selectedOption,
    selectedOptions: [...new Set(selectedOptions.filter(Boolean))],
    terminalSelected,
  };
};

const applyOrdinaryPddFormDecision = async (targetPage, decision) => {
  try {
    return await applyOrdinaryPddFormDecisionOnce(targetPage, decision);
  } catch (error) {
    if (!/拼多多.*(?:未找到|未出现|未读取)/u.test(String(error?.message || ''))) throw error;
    const progress = readProgress();
    const orderNumber = decision.orderNumber || progress.orderNumber;
    const detailUrl = progress.detailUrl || targetPage.url();
    const recoverCompletedDuringOptionSelection = (state, detectionStage) => {
      if (!state?.isCompleted || !state.orderMatches) return null;
      const recovered = {
        ...state,
        recoveredFromCompletedPage: true,
        completionDetectedDuring: detectionStage,
      };
      writeProgress({
        step: 'ordinary-pdd-completed-during-option-selection',
        ordinaryPddOptionRecovery: {
          orderNumber,
          status: 'completed-page-detected',
          reason: error.message,
          detectionStage,
          completedOutcome: state.completedOutcome || null,
          confirmationMethod: state.confirmationMethod || 'detail-completed',
          detectedAt: new Date().toISOString(),
        },
        error: null,
      });
      logRunStep('ordinary-completion-reconciled-during-option-selection', {
        orderNumber,
        detectionStage,
        completedOutcome: state.completedOutcome || null,
      });
      return recovered;
    };
    const stateBeforeRefresh = await readPddResolutionState(targetPage, orderNumber, {
      timeoutMs: Math.min(pddRenderWaitMs, 30_000),
    }).catch(() => null);
    const completedBeforeRefresh = recoverCompletedDuringOptionSelection(
      stateBeforeRefresh,
      'before-refresh',
    );
    if (completedBeforeRefresh) return completedBeforeRefresh;
    writeProgress({
      step: 'ordinary-pdd-option-refreshing',
      ordinaryPddOptionRecovery: {
        orderNumber,
        status: 'refreshing',
        reason: error.message,
        refreshCount: 1,
        startedAt: new Date().toISOString(),
      },
    });
    let recoveryNavigation = 'reload';
    try {
      await targetPage.reload({ waitUntil: 'domcontentloaded', timeout: 45_000 });
    } catch {
      recoveryNavigation = 'saved-detail-url-after-reload-error';
      await navigateSystemPage(targetPage, detailUrl, 'ordinary-pdd-option-recovery');
    }
    const expectedPlatformWorkOrderId = parsePlatformWorkOrderId(detailUrl);
    const currentPlatformWorkOrderId = parsePlatformWorkOrderId(targetPage.url());
    if (isPddDetailUrl(detailUrl)
      && (!isPddDetailUrl(targetPage.url())
        || (expectedPlatformWorkOrderId && currentPlatformWorkOrderId !== expectedPlatformWorkOrderId))) {
      recoveryNavigation = 'saved-detail-url';
      await navigateSystemPage(targetPage, detailUrl, 'ordinary-pdd-option-recovery-detail');
    }
    if (targetPage.url().includes('mms.pinduoduo.com/login')) {
      recoveryNavigation = 'login-recovery';
      await ensurePddLogin(targetPage, context, detailUrl);
    }
    await closeDeviceAccessIfPrompted(targetPage);
    const recoveryRenderWaitMs = Math.min(pddRenderWaitMs, 30_000);
    const recoveredDetailState = await waitForPddResolutionDetail(targetPage, orderNumber, {
      readTimeoutMs: recoveryRenderWaitMs,
      settleMs: recoveryRenderWaitMs,
    });
    if (!recoveredDetailState.detailReady || !recoveredDetailState.orderMatches) {
      const reason = recoveredDetailState.detailLoadingReason
        || (recoveredDetailState.orderNumber
          ? `刷新后页面订单号 ${recoveredDetailState.orderNumber} 与当前订单 ${orderNumber} 不一致`
          : `刷新后等待 ${Math.ceil(recoveryRenderWaitMs / 1000)} 秒仍未读取到订单号或工单详情标志`);
      const failedRecovery = {
        ...readProgress().ordinaryPddOptionRecovery,
        status: 'failed',
        recoveryNavigation,
        renderWaitMs: recoveryRenderWaitMs,
        currentUrl: targetPage.url(),
        detailState: recoveredDetailState,
        failedAt: new Date().toISOString(),
      };
      writeProgress({ ordinaryPddOptionRecovery: failedRecovery });
      await pauseForTransientRetry(targetPage, 'pdd-resolution-detail-loading', 'PDD_DETAIL_TEMPORARILY_UNAVAILABLE', reason, {
        ordinaryPddOptionRecovery: failedRecovery,
      });
    }
    const completedAfterRefresh = recoverCompletedDuringOptionSelection(
      recoveredDetailState,
      'after-refresh',
    );
    if (completedAfterRefresh) return completedAfterRefresh;
    writeProgress({
      ordinaryPddOptionRecovery: {
        ...readProgress().ordinaryPddOptionRecovery,
        status: 'detail-ready',
        recoveryNavigation,
        renderWaitMs: recoveryRenderWaitMs,
        currentUrl: targetPage.url(),
        detailReadyAt: new Date().toISOString(),
      },
    });
    await ensurePddOrderRemark(targetPage, orderNumber);
    await closePddLogisticsOverlay(targetPage);
    writeProgress({
      step: 'ordinary-pdd-option-retrying',
      ordinaryPddOptionRecovery: {
        ...readProgress().ordinaryPddOptionRecovery,
        status: 'retrying',
        retriedAt: new Date().toISOString(),
      },
    });
    let result;
    try {
      result = await applyOrdinaryPddFormDecisionOnce(targetPage, decision);
    } catch (retryError) {
      if (!/拼多多.*(?:未找到|未出现|未读取)/u.test(String(retryError?.message || ''))) {
        writeProgress({
          ordinaryPddOptionRecovery: {
            ...readProgress().ordinaryPddOptionRecovery,
            status: 'failed',
            error: retryError.message,
            failedAt: new Date().toISOString(),
          },
        });
        throw retryError;
      }
      writeProgress({
        step: 'ordinary-pdd-option-pending-list-reopening',
        ordinaryPddOptionRecovery: {
          ...readProgress().ordinaryPddOptionRecovery,
          status: 'pending-list-reopening',
          refreshError: retryError.message,
          pendingListReopenStartedAt: new Date().toISOString(),
        },
      });
      const reopenedPage = await reopenPddDetailForResolution(
        targetPage,
        orderNumber,
        readProgress(),
        { forcePendingList: true },
      );
      if (hasConfirmedPendingListAbsence(readProgress(), orderNumber)) {
        const completed = completedPddStateFromPendingListAbsence(orderNumber);
        writeProgress({
          step: 'ordinary-pdd-completed-during-option-selection',
          ordinaryPddOptionRecovery: {
            ...readProgress().ordinaryPddOptionRecovery,
            status: 'completed-page-detected',
            detectionStage: 'forced-pending-list-reopen',
            confirmationMethod: completed.confirmationMethod,
            detectedAt: new Date().toISOString(),
          },
          error: null,
        });
        return completed;
      }
      const reopenedState = await ensurePddResolutionDetailReady(
        reopenedPage,
        orderNumber,
        readProgress(),
        { settleMs: Math.max(pddDetailSettleMs, 30_000) },
      );
      const completedAfterPendingListReopen = recoverCompletedDuringOptionSelection(
        reopenedState,
        'forced-pending-list-reopen',
      );
      if (completedAfterPendingListReopen) return completedAfterPendingListReopen;
      await ensurePddOrderRemark(reopenedPage, orderNumber);
      await closePddLogisticsOverlay(reopenedPage);
      writeProgress({
        step: 'ordinary-pdd-option-pending-list-reopened',
        ordinaryPddOptionRecovery: {
          ...readProgress().ordinaryPddOptionRecovery,
          status: 'pending-list-reopened',
          pendingListReopenedAt: new Date().toISOString(),
          currentUrl: reopenedPage.url(),
        },
      });
      try {
        const reopenedFormState = await applyOrdinaryPddFormDecisionOnce(reopenedPage, decision);
        result = { ...reopenedFormState, targetPage: reopenedPage };
      } catch (reopenedError) {
        Object.defineProperty(reopenedError, 'ordinaryPddRecoveryTargetPage', {
          value: reopenedPage,
          enumerable: false,
        });
        writeProgress({
          ordinaryPddOptionRecovery: {
            ...readProgress().ordinaryPddOptionRecovery,
            status: 'failed',
            error: reopenedError.message,
            failedAt: new Date().toISOString(),
          },
        });
        throw reopenedError;
      }
    }
    writeProgress({
      ordinaryPddOptionRecovery: {
        ...readProgress().ordinaryPddOptionRecovery,
        status: 'succeeded',
        recoveredAt: new Date().toISOString(),
      },
    });
    return result;
  }
};

const readOrdinaryCompletionAfterSubmit = async (targetPage, orderNumber, {
  requireCompleted = true,
  recoverFollowupStage = false,
  scenarioCode = null,
  decision = null,
} = {}) => {
  let state = await readPddResolutionState(targetPage, orderNumber).catch(() => null);
  if (requireCompleted && !state?.isCompleted) {
    state = await confirmPddCompletionWithoutResubmit(targetPage, orderNumber, state).catch(() => state);
  }
  if (requireCompleted && !state?.isCompleted && recoverFollowupStage) {
    // Some ordinary work orders append a prefilled consumer-message stage
    // after the last radio result. The result API has already succeeded at
    // this point, so reopen the same order and advance only that separately
    // guarded follow-up instead of treating the still-pending row as a failed
    // final submission.
    let followupPage = targetPage;
    if (!isPddDetailUrl(followupPage.url())) {
      followupPage = await reopenPddDetailForResolution(
        followupPage,
        orderNumber,
        readProgress(),
        { forcePendingList: true },
      );
    }
    if (hasConfirmedPendingListAbsence(readProgress(), orderNumber)) {
      return completedPddStateFromPendingListAbsence(orderNumber);
    }
    const followupDetailState = await ensurePddResolutionDetailReady(
      followupPage,
      orderNumber,
      readProgress(),
      { allowUnresolved: true },
    );
    if (followupDetailState?.isCompleted && followupDetailState.orderMatches) {
      return {
        ...followupDetailState,
        confirmationMethod: followupDetailState.confirmationMethod || 'post-result-detail-completed',
      };
    }
    const pendingMessageStage = await findOrdinaryPddMessageStage(followupPage);
    if (pendingMessageStage) {
      writeProgress({
        step: 'ordinary-pdd-post-result-followup-starting',
        ordinaryPddPostResultFollowup: {
          orderNumber,
          scenarioCode,
          mode: pendingMessageStage.mode,
          status: 'starting',
          startedAt: new Date().toISOString(),
        },
      });
      const followupState = await advanceOrdinaryPddMessageStageIfPresent(
        followupPage,
        orderNumber,
        scenarioCode,
        decision || {},
      );
      if (followupState?.isCompleted && followupState.orderMatches) {
        return {
          ...followupState,
          confirmationMethod: followupState.confirmationMethod || 'post-result-message-completed',
        };
      }
      state = await confirmPddCompletionWithoutResubmit(
        followupPage,
        orderNumber,
        followupState || followupDetailState,
      ).catch(() => followupState || followupDetailState);
      targetPage = followupPage;
      writeProgress({
        ordinaryPddPostResultFollowup: {
          ...readProgress().ordinaryPddPostResultFollowup,
          status: state?.isCompleted ? 'completed' : 'submitted-unconfirmed',
          confirmationMethod: state?.confirmationMethod || null,
          completedAt: state?.isCompleted ? new Date().toISOString() : null,
          updatedAt: new Date().toISOString(),
        },
      });
      if (followupState?.messageStageSubmitted && !state?.isCompleted) {
        const retryAfterMs = 30_000;
        writeProgress({
          step: 'ordinary-pdd-message-submitted-awaiting-completion',
          ordinaryPddMessageStage: {
            ...readProgress().ordinaryPddMessageStage,
            orderNumber,
            scenarioCode,
            status: 'submitted-awaiting-completion',
            responseConfirmed: followupState.responseConfirmed === true,
            alreadySucceeded: followupState.alreadySucceeded === true,
            retryAfterMs,
            updatedAt: new Date().toISOString(),
          },
          manualReview: null,
          error: null,
        });
        throw new LogisticsRetryRequiredError(
          'ordinary-pdd-message-completion-recheck',
          '拼多多预填话术已提交，等待平台完成状态同步；后续只读复核，禁止重复发送',
          retryAfterMs,
          { messageStageSubmitted: true },
        );
      }
    }
  }
  if (requireCompleted && !state?.isCompleted) {
    const absent = await confirmOrderAbsentFromPendingList(targetPage, orderNumber).catch(() => false);
    if (absent) {
      return {
        isCompleted: true,
        orderMatches: true,
        confirmationMethod: 'absent-from-pending-list',
        completedOutcome: null,
      };
    }
    throw new Error('拼多多提交后未确认当前普通工单已完结，禁止重复提交');
  }
  return state || { isCompleted: false, orderMatches: true };
};

const prepareGoodDeedFeedback = async (targetPage, orderNumber, scenarioCode) => {
  await focusSystemPage('pdd', targetPage);
  const feedbackDialogCandidates = [
    targetPage.getByRole('dialog').filter({ hasText: /问题反馈/ }),
    targetPage.locator('[role="dialog"]:visible').filter({ hasText: /问题反馈/ }),
    targetPage.locator('[data-testid="beast-core-modal"]:visible').filter({ hasText: /问题反馈/ }),
    targetPage.locator('.el-dialog:visible, .ant-modal:visible, .beast-core-modal:visible')
      .filter({ hasText: /问题反馈/ }),
  ];
  let dialog = await waitForFirstVisible(targetPage, feedbackDialogCandidates, {
    timeoutMs: 2500,
    pollIntervalMs: 200,
  });
  const feedbackCandidates = [
    targetPage.getByText(/对此订单有疑问\s*[？?]?\s*点此反馈\s*(?:后\s*)?自行处理/u),
    targetPage.getByText(/点此反馈\s*(?:后\s*)?自行处理/u),
    targetPage.getByRole('link', { name: /点此反馈自行处理|反馈/ }),
    targetPage.getByRole('button', { name: /点此反馈自行处理|反馈/ }),
    targetPage.locator('[data-testid*="feedback" i]:visible, [data-test*="feedback" i]:visible'),
    targetPage.locator('button:visible, a:visible').filter({ hasText: /反馈/ }),
    targetPage.getByText('反馈', { exact: true }),
  ];

  // The stale-page modal can be mounted between the detail read and the
  // feedback click. It intercepts the click and leaves the worker parked even
  // though the order itself is still valid. Handle only that modal's central
  // refresh control, then re-locate the feedback entry. Opening a dialog is
  // safe to retry; submission remains behind the external-effect guard below.
  let lastOpenError = null;
  for (let attempt = 0; !dialog && attempt < 3; attempt += 1) {
    // Keep the extracted form-control self-test usable without loading the
    // full workflow module; production always has the imported helper.
    const stalePageRefresh = typeof clickVisiblePddStalePageRefresh === 'function'
      ? await clickVisiblePddStalePageRefresh(targetPage, {
        cooldownMs: 0,
        settleMs: 700,
      }).catch((error) => ({ handled: false, error: error.message }))
      : { handled: false, reason: 'stale-refresh-helper-unavailable' };
    if (stalePageRefresh.handled) {
      logRunStep('pdd-stale-page-refresh-before-feedback', {
        orderNumber,
        scenarioCode,
        attempt: attempt + 1,
        beforeUrl: stalePageRefresh.beforeUrl,
        afterUrl: stalePageRefresh.afterUrl,
      });
      await targetPage.waitForTimeout(500);
    }

    const feedback = await waitForFirstVisible(targetPage, feedbackCandidates, {
      timeoutMs: attempt === 0 ? 8_000 : 4_000,
      pollIntervalMs: 250,
    });
    if (!feedback) {
      lastOpenError = new Error('好人好事工单未找到“反馈”入口');
      continue;
    }
    try {
      await pacedAction(targetPage, 'open-good-deed-feedback', () => feedback.click({ force: true }));
    } catch (error) {
      // These errors release the assignment through the verification/login
      // hold or rate-limit backoff. Retrying here and replacing the error
      // would lose that state and can close a CAPTCHA tab as a generic failure.
      if (error instanceof HumanVerificationRequiredError
        || error instanceof PddLoginRequiredError
        || error instanceof RateLimitPauseError) throw error;
      lastOpenError = error;
      continue;
    }
    dialog = await waitForFirstVisible(targetPage, feedbackDialogCandidates, {
      timeoutMs: attempt === 0 ? 8_000 : 5_000,
      pollIntervalMs: 200,
    });
    if (!dialog) {
      lastOpenError = new Error('点击反馈后“问题反馈”弹窗未出现');
      await targetPage.waitForTimeout(400 * (attempt + 1));
    }
  }
  if (!dialog) {
    await saveWorkflowDiagnostics(targetPage, 'pdd-feedback-open-unavailable', lastOpenError).catch(() => {});
    throw lastOpenError || new Error('点击反馈后“问题反馈”弹窗未出现');
  }
  const phoneInput = await firstVisible([
    dialog.getByRole('textbox', { name: /手机号|手机号码/ }),
    dialog.locator('input:visible:not([type="hidden"])').last(),
  ]);
  const platformPrefilledPhone = String(await phoneInput?.inputValue().catch(() => '') || '').trim();
  updateOrdinaryExecution(orderNumber, scenarioCode, {
    platformPrefilledPhone,
    feedbackPhoneChecked: true,
  });
  return { dialog, platformPrefilledPhone };
};

const submitGoodDeedFeedback = async (targetPage, orderNumber, scenarioCode, decision) => {
  const { dialog, platformPrefilledPhone } = await prepareGoodDeedFeedback(
    targetPage,
    orderNumber,
    scenarioCode,
  );
  if (!isValidPlatformPrefilledPhone(platformPrefilledPhone)) {
    throw new Error('反馈弹窗的平台预填手机号为空或格式无效');
  }
  await selectOrdinaryPddOption(targetPage, [decision.pdd.reasonOption || '其他原因'], {
    scopeOverride: dialog,
  });
  await fillOrdinaryPddField(
    targetPage,
    /问题描述/,
    decision.pdd.problemDescription,
    { textarea: true, scopeOverride: dialog },
  );
  await uploadOrdinaryScenarioEvidence(targetPage, orderNumber, scenarioCode, decision);
  const confirm = await waitForFirstVisible(targetPage, [
    dialog.getByRole('button', { name: '确认提交', exact: true }),
    dialog.getByText('确认提交', { exact: true }),
  ], { timeoutMs: 12_000, pollIntervalMs: 200 });
  if (!confirm) throw new Error('问题反馈弹窗未找到“确认提交”按钮');
  await guardedExternalEffect({
    effectType: 'pdd-submit',
    orderNumber,
    stage: 'ordinary-good-deed-feedback',
    request: { scenarioCode, decision },
  }, async () => {
    await pacedAction(targetPage, 'submit-good-deed-feedback', async () => {
      await confirm.scrollIntoViewIfNeeded().catch(() => {});
      await confirm.click({ timeout: 10_000 });
    }, {
      retryOnRateLimit: true,
    });
    await waitForPddSubmitTransition(targetPage, 'good-deed-feedback', async () => {
      if (!isPddDetailUrl(targetPage.url())) return true;
      const state = await readPddResolutionState(
        targetPage,
        orderNumber,
        { timeoutMs: 2000 },
      ).catch(() => null);
      return Boolean(state?.isCompleted);
    });
    return { submittedAt: new Date().toISOString() };
  });
  return readOrdinaryCompletionAfterSubmit(targetPage, orderNumber);
};

const submitProductShortageFeedback = async (targetPage, orderNumber, scenarioCode, decision) => {
  const preFeedbackState = await ensurePddResolutionDetailReady(
    targetPage,
    orderNumber,
    readProgress(),
  );
  if (preFeedbackState.isCompleted) {
    return { ...preFeedbackState, recoveredFromCompletedPage: true };
  }
  const { dialog } = await prepareGoodDeedFeedback(targetPage, orderNumber, scenarioCode);
  await selectOrdinaryPddOption(targetPage, [decision.pdd.reasonOption || '其他原因'], {
    scopeOverride: dialog,
  });
  await fillOrdinaryPddField(
    targetPage,
    /问题描述/,
    decision.pdd.feedbackProblemDescription,
    { textarea: true, scopeOverride: dialog },
  );
  const confirm = await waitForFirstVisible(targetPage, [
    dialog.getByRole('button', { name: '确认提交', exact: true }),
    dialog.getByText('确认提交', { exact: true }),
  ], { timeoutMs: 12_000, pollIntervalMs: 200 });
  if (!confirm) throw new Error('问题反馈弹窗未找到“确认提交”按钮');
  const feedbackEffect = await guardedExternalEffect({
    effectType: 'pdd-submit',
    orderNumber,
    stage: 'ordinary-product-shortage-no-shortage-feedback',
    request: { scenarioCode, description: decision.pdd.feedbackProblemDescription },
  }, async () => {
    await pacedAction(targetPage, 'submit-product-shortage-feedback', async () => {
      await confirm.scrollIntoViewIfNeeded().catch(() => {});
      writeProgress({
        ordinaryFeedbackSubmission: {
          orderNumber,
          scenarioCode,
          clickAttempted: true,
          clickAttemptedAt: new Date().toISOString(),
        },
      });
      await confirm.click({ timeout: 10_000 });
    }, {
      retryOnRateLimit: true,
    });
    const postClickTransitionObserved = await waitForPddSubmitTransition(targetPage, 'product-shortage-feedback', async () => {
      if (!isPddDetailUrl(targetPage.url())) return true;
      const state = await readPddResolutionState(targetPage, orderNumber, { timeoutMs: 2000 }).catch(() => null);
      return Boolean(state?.isCompleted);
    });
    return { clickAttempted: true, postClickTransitionObserved, submittedAt: new Date().toISOString() };
  });
  const previousFeedback = readProgress().ordinaryFeedbackSubmission;
  writeProgress({
    ordinaryFeedbackSubmission: {
      ...(previousFeedback?.orderNumber === orderNumber ? previousFeedback : {}),
      orderNumber,
      scenarioCode,
      clickAttempted: feedbackEffect?.clickAttempted === true
        || (previousFeedback?.orderNumber === orderNumber && previousFeedback.clickAttempted === true),
      postClickTransitionObserved: feedbackEffect?.postClickTransitionObserved === true,
      effectAlreadySucceeded: feedbackEffect?.alreadySucceeded === true,
      checkedAt: new Date().toISOString(),
    },
  });
  return readOrdinaryCompletionAfterSubmit(targetPage, orderNumber);
};

const isTransientOrdinaryPddPreSubmitFormError = (error) => {
  if (error instanceof HumanVerificationRequiredError
    || error instanceof PddLoginRequiredError
    || error instanceof RateLimitPauseError
    || error instanceof ManualReviewRequiredError
    || error instanceof PddSubmitRejectedError
    || isPddSessionExpiredError(error)
    || isPddEvidenceUploadAuthorizationError(error)
    || error?.externalEffectReceipt?.clickAttempted === true) return false;
  return error instanceof PddSubmitButtonRenderError
    || /PDD_ORDINARY_FORM_TEMPORARILY_UNAVAILABLE/u.test(String(error?.code || error?.message || ''))
    || /拼多多.*(?:未找到|未出现|未读取|未保持|缺少必选|无法唯一识别|未生成可发送|自动话术未包含)/u
      .test(String(error?.message || error || ''));
};

const resolveOrdinaryPddSubmitEffectStage = (
  baseStage,
  orderNumber,
  progress = readProgress(),
) => {
  const submission = progress.pddResolutionSubmission || {};
  const recoveries = [
    {
      recovery: progress.ordinaryPddFrameSubmitRecovery239 || {},
      source: 'migration-239',
      submissionStatus: 'frame-submit-retry-authorized',
      retrySuffix: '-frame-submit-v3',
    },
    {
      recovery: progress.ordinaryPddFormValidationRecovery263 || {},
      source: 'migration-263',
      submissionStatus: 'form-validation-retry-authorized',
      retrySuffix: '-form-validation-v2',
    },
  ];
  const interruptedRecovery = progress.ordinaryPddInterruptedSubmitRecovery264 || {};
  const reconciliation = progress.externalStateReconciliation || {};
  for (const candidate of recoveries) {
    const recovery = candidate.recovery;
    const retryStage = String(recovery.retryEffectStage || '').trim();
    const normalAuthorization = submission.status === candidate.submissionStatus
      && submission.effectStage === retryStage;
    const interruptedValidationAuthorization = candidate.source === 'migration-263'
      && interruptedRecovery.status === 'read-only-reconciliation-ready'
      && interruptedRecovery.source === 'migration-264'
      && interruptedRecovery.orderNumber === orderNumber
      && interruptedRecovery.effectId === recovery.originalEffectId
      && interruptedRecovery.externalActionsReplayedByMigration === false
      && reconciliation.state === 'not-applied'
      && reconciliation.effectType === 'pdd-submit'
      && reconciliation.effectId === recovery.originalEffectId
      && reconciliation.confirmationMethod === 'present-in-pending-list'
      && submission.status === 'retry-authorized'
      && submission.effectStage === baseStage;
    if (recovery.status !== 'retry-authorized'
      || recovery.source !== candidate.source
      || recovery.confirmedNotApplied !== true
      || recovery.unknownEffectRetried !== false
      || recovery.orderNumber !== orderNumber
      || recovery.originalEffectStage !== baseStage
      || submission.orderNumber !== orderNumber
      || (!normalAuthorization && !interruptedValidationAuthorization)
      || retryStage !== `${baseStage}${candidate.retrySuffix}`) continue;
    return retryStage;
  }
  return baseStage;
};

const countVisibleEditableOrdinaryPddControls = async (targetPage) => {
  let count = 0;
  for (const frame of targetPage.frames()) {
    const controls = frame.locator([
      'input:not([type="hidden"]):not([disabled])',
      'textarea:not([disabled])',
      'select:not([disabled])',
      '[role="radio"]:not([aria-disabled="true"])',
      '[role="combobox"]:not([aria-disabled="true"])',
    ].join(', '));
    for (let index = 0; index < await controls.count().catch(() => 0); index += 1) {
      const control = controls.nth(index);
      if (!await control.isVisible().catch(() => false)
        || !await control.isEnabled().catch(() => false)) continue;
      count += 1;
      if (count >= 20) return count;
    }
  }
  return count;
};

const submitOrdinaryPddAction = async (
  targetPage,
  orderNumber,
  scenarioCode,
  decision,
  { requireCompleted = true, effectStage = null, stagedPhase = null } = {},
) => {
  if (decision.pdd?.feedbackProblemDescription) {
    return submitProductShortageFeedback(targetPage, orderNumber, scenarioCode, decision);
  }
  if (scenarioCode === ORDINARY_SCENARIO_CODES.GOOD_DEED_EXPEDITED_SHIPPING
    && decision.pdd?.option === '反馈') {
    return submitGoodDeedFeedback(targetPage, orderNumber, scenarioCode, decision);
  }
  if (decision.pdd?.resultRequiredAfterPrimary === true && !stagedPhase) {
    const baseStage = effectStage
      || `ordinary-${scenarioCode}-${decision.reasonCode || decision.actionCode}`;
    const terminalOption = decision.pdd.completionOption || decision.pdd.resultOption;
    const terminalAliases = decision.pdd.completionOption
      ? (decision.pdd.completionOptionAliases || [])
      : (decision.pdd.resultOptionAliases || []);
    const terminalLabels = expandOrdinaryPddOptionAliases([
      terminalOption,
      ...terminalAliases,
    ].filter(Boolean));
    if (!terminalOption) {
      throw new Error(`拼多多两阶段工单缺少最终处理选项: ${scenarioCode}`);
    }
    const terminalStageVisible = async (page = targetPage) => {
      const scope = page.locator('body');
      for (const label of terminalLabels) {
        if (await visibleExactText(scope, label)) return true;
      }
      return false;
    };

    let terminalVisible = await terminalStageVisible();
    if (!terminalVisible) {
      const primaryDecision = {
        ...decision,
        evidence: null,
        pdd: {
          option: decision.pdd.option,
          optionAliases: decision.pdd.optionAliases || [],
          resultRequiredAfterPrimary: false,
        },
      };
      const primaryState = await submitOrdinaryPddAction(
        targetPage,
        orderNumber,
        scenarioCode,
        primaryDecision,
        {
          requireCompleted: false,
          effectStage: `${baseStage}:primary`,
          stagedPhase: 'primary',
        },
      );
      if (primaryState?.targetPage) targetPage = primaryState.targetPage;
      if (primaryState?.isCompleted) return primaryState;

      const deadline = Date.now() + 30_000;
      let transitionedState = null;
      do {
        terminalVisible = await terminalStageVisible();
        if (terminalVisible) break;
        transitionedState = await readPddResolutionState(
          targetPage,
          orderNumber,
          { timeoutMs: 1000 },
        ).catch(() => null);
        if (transitionedState?.isCompleted) return transitionedState;
        await targetPage.waitForTimeout(250);
      } while (Date.now() < deadline);
      if (!terminalVisible) {
        let refreshedTransition = null;
        try {
          refreshedTransition = await waitForPddRenderedResult(targetPage, {
            stage: '普通工单最终处理选项渲染',
            timeoutMs: 30_000,
            totalTimeoutMs: 30_000,
            initialWaitMs: 0,
            onVerification: (page, verificationStage) => checkForHumanVerification(
              page,
              verificationStage,
            ),
            beforeReload: (page) => clickVisiblePddStalePageRefresh(page, {
              cooldownMs: 0,
              settleMs: 700,
            }),
            inspect: async (page) => {
              if (await terminalStageVisible(page)) return { terminalVisible: true };
              const state = await readPddResolutionState(
                page,
                orderNumber,
                { timeoutMs: 1_000 },
              ).catch(() => null);
              if (state?.isCompleted) return { completedState: state };
              return null;
            },
            onRefresh: async (page) => {
              await ensurePddLogin(page, context, page.url());
              await closeDeviceAccessIfPrompted(page);
              writeProgress({
                step: 'ordinary-pdd-result-stage-refreshed',
                ordinaryPddStageTransition: {
                  orderNumber,
                  scenarioCode,
                  primaryOption: decision.pdd.option,
                  resultOption: terminalOption,
                  status: 'refreshed-after-initial-render-wait',
                  refreshedAt: new Date().toISOString(),
                },
                manualReview: null,
                error: null,
              });
            },
          });
        } catch (error) {
          if (error?.code !== 'PDD_RENDER_WAIT_TIMEOUT') throw error;
        }
        if (refreshedTransition?.completedState) return refreshedTransition.completedState;
        terminalVisible = refreshedTransition?.terminalVisible === true;
      }
      if (!terminalVisible) {
        const transitionError = new Error(
          `PDD_ORDINARY_RESULT_STAGE_TEMPORARILY_UNAVAILABLE: `
          + `拼多多第一阶段已确认，等待 30 秒并刷新后仍未渲染最终处理选项: ${terminalOption}`,
        );
        transitionError.code = 'PDD_ORDINARY_RESULT_STAGE_TEMPORARILY_UNAVAILABLE';
        writeProgress({
          step: 'ordinary-pdd-result-stage-retry-ready',
          ordinaryPddStageTransition: {
            orderNumber,
            scenarioCode,
            primaryOption: decision.pdd.option,
            resultOption: terminalOption,
            status: 'retry-ready',
            retryAfterMs: 30_000,
            refreshAttempted: true,
            failedAt: new Date().toISOString(),
          },
          manualReview: null,
          error: null,
        });
        throw transitionError;
      }
    }

    const resultDecision = {
      ...decision,
      pdd: {
        ...decision.pdd,
        option: terminalOption,
        optionAliases: terminalAliases,
        completionOption: null,
        completionOptionAliases: [],
        resultOption: null,
        resultOptionAliases: [],
        resultRequiredAfterPrimary: false,
      },
    };
    return submitOrdinaryPddAction(
      targetPage,
      orderNumber,
      scenarioCode,
      resultDecision,
      {
        requireCompleted,
        effectStage: `${baseStage}:result`,
        stagedPhase: 'result',
      },
    );
  }
  const baseStage = effectStage
    || `ordinary-${scenarioCode}-${decision.reasonCode || decision.actionCode}`;
  const stage = resolveOrdinaryPddSubmitEffectStage(baseStage, orderNumber);
  let lastError = null;
  let loginRecoveryCount = 0;
  let submitRenderRecoveryCount = 0;
  let stateChangedRecoveryCount = 0;
  for (let attempt = 1; attempt <= 3; attempt++) {
    try {
      await focusSystemPage('pdd', targetPage);
      const pageState = await ensurePddResolutionDetailReady(targetPage, orderNumber, readProgress());
      if (pageState.isCompleted) {
        logRunStep('ordinary-completion-reconciled-before-submit', {
          orderNumber,
          scenarioCode,
          confirmationMethod: pageState.confirmationMethod || 'detail-completed',
          completedOutcome: pageState.completedOutcome || null,
        });
        return {
          ...pageState,
          recoveredFromCompletedPage: true,
        };
      }
      await ensurePddOrderRemark(targetPage, orderNumber);
      await closePddLogisticsOverlay(targetPage);
      const messageStageState = await advanceOrdinaryPddMessageStageIfPresent(
        targetPage,
        orderNumber,
        scenarioCode,
        decision,
      );
      if (messageStageState?.isCompleted || messageStageState?.messageStageSubmitted) {
        return messageStageState;
      }
      if (decision.pdd?.messageStageRequired === true) {
        const retryAfterMs = 30_000;
        writeProgress({
          step: 'ordinary-pdd-message-stage-retry-ready',
          ordinaryPddMessageStage: {
            orderNumber,
            scenarioCode,
            status: 'retry-ready',
            reason: 'required-prefilled-message-stage-not-rendered',
            retryAfterMs,
            updatedAt: new Date().toISOString(),
          },
          manualReview: null,
          error: null,
        });
        throw new LogisticsRetryRequiredError(
          'ordinary-pdd-message-stage-render',
          '拼多多预填话术步骤暂未渲染，稍后只重查该步骤，不执行普通表单提交',
          retryAfterMs,
        );
      }
      const priorSubmission = readProgress().pddResolutionSubmission;
      const matchingSubmission = priorSubmission?.orderNumber === orderNumber
        && (!priorSubmission.effectStage || priorSubmission.effectStage === stage)
        ? priorSubmission
        : null;
      const previousSubmitAttemptCount = Math.max(
        0,
        Number(matchingSubmission?.submitAttemptCount || 0),
      );
      const oneTimeSubmitRetryAuthorized = stage !== baseStage
        && ['frame-submit-retry-authorized', 'form-validation-retry-authorized']
          .includes(matchingSubmission?.status)
        && previousSubmitAttemptCount === 2;
      if (previousSubmitAttemptCount >= 2 && !oneTimeSubmitRetryAuthorized) {
        throw new ManualReviewRequiredError(
          'pdd-resolution-submit-confirmation',
          '拼多多普通工单提交次数已达到两次，禁止第三次提交',
        );
      }
      let submitAttemptCount = previousSubmitAttemptCount;
      const reservationAttemptCount = Math.max(
        0,
        Number(matchingSubmission?.reservationAttemptCount || 0),
      ) + 1;
      let guardedCompletionState = null;
      const stagedResultRequired = decision.pdd?.resultRequiredAfterPrimary === true;
      let selectedPddOption = matchingSubmission?.selectedOption || null;
      let selectedPddOutcome = matchingSubmission?.outcome
        || (stagedResultRequired
          ? decision.pdd?.option
          : decision.pdd?.completionOption || decision.pdd?.resultOption || decision.pdd?.option)
        || null;
      let submitClickAttempted = false;
      const markOrdinaryPddSubmissionActionAttempt = (trigger) => {
        submitAttemptCount = previousSubmitAttemptCount + 1;
        const attemptedAt = new Date().toISOString();
        writeProgress({
          pddResolutionSubmission: {
            ...readProgress().pddResolutionSubmission,
            submitAttemptCount,
            lastClickAttemptedAt: attemptedAt,
            actionTrigger: trigger,
          },
        });
        return attemptedAt;
      };
      const guardedSubmission = await guardedExternalEffect({
        effectType: 'pdd-submit',
        orderNumber,
        stage,
        // Preserve the previous submit-button guard's request hash so an
        // already-succeeded effect remains authoritative after deployment.
        request: { stage, orderNumber },
      }, async () => {
        writeProgress({
          pddResolutionSubmission: {
            ...(matchingSubmission || {}),
            shopId,
            orderNumber,
            scenarioCode,
            effectStage: stage,
            outcome: selectedPddOutcome,
            selectedOption: selectedPddOption,
            resultOption: stagedResultRequired ? decision.pdd?.resultOption || null : null,
            status: 'submitting',
            submitAttemptCount: previousSubmitAttemptCount,
            reservationAttemptCount,
            externalActionStartedAt: new Date().toISOString(),
          },
        });

        try {
          const formState = await applyOrdinaryPddFormDecision(targetPage, decision);
          if (formState?.targetPage) targetPage = formState.targetPage;
          selectedPddOption = formState?.selectedOption || selectedPddOption;
          if (!stagedResultRequired) selectedPddOutcome = selectedPddOption || selectedPddOutcome;
          writeProgress({
            pddResolutionSubmission: {
              ...readProgress().pddResolutionSubmission,
              outcome: selectedPddOutcome,
              selectedOption: selectedPddOption,
            },
          });
          if (formState?.isCompleted) {
            // Some PDD forms commit when the option is clicked. The external
            // effect was reserved before that click, so this is a guarded
            // automation completion rather than an unowned page recovery.
            markOrdinaryPddSubmissionActionAttempt('option-selection-completed');
            guardedCompletionState = {
              ...formState,
              recoveredFromCompletedPage: false,
              completedDuringGuardedOptionSelection: true,
            };
            return {
              selectedPddOutcome,
              selectedPddOption,
              completionTriggeredDuring: 'option-selection',
              confirmationMethod: formState.confirmationMethod || 'detail-completed',
              completedOutcome: formState.completedOutcome || null,
              completedResultOption: formState.completedResultOption || null,
              completedAt: new Date().toISOString(),
            };
          }

          await uploadOrdinaryScenarioEvidence(targetPage, orderNumber, scenarioCode, decision);
          const submitResult = await clickPddSubmit(targetPage, stage, orderNumber, {
            guard: false,
            selectedPddOption,
            requiredSelectedPddOptions: formState?.selectedOptions || [],
            allowTrustedConfirmation: true,
            beforeClick: () => {
              submitClickAttempted = true;
              markOrdinaryPddSubmissionActionAttempt('submit-button');
            },
            settleUntil: async () => {
              if (!isPddDetailUrl(targetPage.url())) return true;
              const state = await readPddResolutionState(
                targetPage,
                orderNumber,
                { timeoutMs: 2000 },
              ).catch(() => null);
              if (state?.isCompleted) return true;
              if (requireCompleted || !selectedPddOption) return false;
              return !await isOrdinaryPddOptionSelectedInContext(
                targetPage,
                selectedPddOption,
              );
            },
          });
          if (requireCompleted
            && submitResult?.submitReceipt?.success !== true
            && submitResult?.transitionConfirmed !== true) {
            const error = new Error(
              '拼多多最终提交已点击，但未捕获成功回执且页面未确认完成，转入只读对账',
            );
            error.code = 'PDD_SUBMIT_OUTCOME_UNCONFIRMED';
            error.externalEffectReceipt = {
              clickAttempted: true,
              requestCaptured: submitResult?.submitReceipt?.requestCaptured === true,
              responseCaptured: submitResult?.submitReceipt?.responseCaptured === true,
              transitionConfirmed: false,
              selectionProof: submitResult?.selectionProof || null,
              requestCandidates: submitResult?.requestCandidates || [],
              requestFailures: submitResult?.requestFailures || [],
              responseCandidates: submitResult?.responseCandidates || [],
              frameNavigations: submitResult?.frameNavigations || [],
              uiFeedback: submitResult?.uiFeedback || [],
              stage,
              orderNumber,
            };
            throw error;
          }
          return {
            selectedPddOutcome,
            selectedPddOption,
            submitClicked: true,
            submitReceipt: submitResult?.submitReceipt || null,
            transitionConfirmed: submitResult?.transitionConfirmed === true,
            confirmationClicked: submitResult?.confirmationClicked === true,
            selectionProof: submitResult?.selectionProof || null,
            requestCandidates: submitResult?.requestCandidates || [],
            requestFailures: submitResult?.requestFailures || [],
            responseCandidates: submitResult?.responseCandidates || [],
            frameNavigations: submitResult?.frameNavigations || [],
            uiFeedback: submitResult?.uiFeedback || [],
            submittedAt: new Date().toISOString(),
          };
        } catch (error) {
          if (error instanceof PddWorkOrderAlreadyCompletedError
            && error.completedState?.orderMatches) {
            markOrdinaryPddSubmissionActionAttempt(
              'option-selection-or-render-transition-completed',
            );
            guardedCompletionState = {
              ...error.completedState,
              recoveredFromCompletedPage: false,
              completedDuringGuardedOptionSelection: true,
            };
            return {
              selectedPddOutcome,
              selectedPddOption,
              completionTriggeredDuring: 'option-selection-or-render-transition',
              confirmationMethod: error.completedState.confirmationMethod || 'detail-completed',
              completedOutcome: error.completedState.completedOutcome || null,
              completedResultOption: error.completedState.completedResultOption || null,
              completedAt: new Date().toISOString(),
            };
          }
          if (!submitClickAttempted && isTransientOrdinaryPddPreSubmitFormError(error)) {
            const proofPage = error.ordinaryPddRecoveryTargetPage
              && !error.ordinaryPddRecoveryTargetPage.isClosed()
              ? error.ordinaryPddRecoveryTargetPage
              : targetPage;
            const [pageState, editableControlCount] = await Promise.all([
              readPddResolutionState(proofPage, orderNumber, { timeoutMs: 5000 })
                .catch(() => null),
              countVisibleEditableOrdinaryPddControls(proofPage).catch(() => 0),
            ]);
            const notAppliedProof = classifyOrdinaryPddPreSubmitFailure({
              pageState,
              orderNumber,
              clickAttempted: submitClickAttempted,
              editableControlCount,
              selectedOutcome: selectedPddOutcome,
            });
            if (notAppliedProof.state === 'not-applied') {
              targetPage = proofPage;
              const failedAt = new Date().toISOString();
              const currentSubmission = readProgress().pddResolutionSubmission || {};
              writeProgress({
                step: 'ordinary-pdd-form-transient-retry-ready',
                pddResolutionSubmission: {
                  ...currentSubmission,
                  status: 'form-retry',
                  submitAttemptCount: previousSubmitAttemptCount,
                  lastClickAttemptedAt: matchingSubmission?.lastClickAttemptedAt || null,
                  externalActionStartedAt: matchingSubmission?.externalActionStartedAt || null,
                  formFailureNotAppliedAt: failedAt,
                  formFailureConfirmationMethod: notAppliedProof.confirmationMethod,
                },
                ordinaryPddFormRecovery: {
                  orderNumber,
                  scenarioCode,
                  effectStage: stage,
                  status: 'retry-ready',
                  reason: error.message,
                  originalErrorCode: error.code || null,
                  previousSubmitAttemptCount,
                  notAppliedProof,
                  retryAfterMs: 5000,
                  failedAt,
                },
              });
              const originalMessage = String(error.message || error);
              const originalCode = error.code || null;
              error.code = 'PDD_ORDINARY_FORM_TEMPORARILY_UNAVAILABLE';
              error.message = `PDD_ORDINARY_FORM_TEMPORARILY_UNAVAILABLE: ${originalMessage}`;
              error.externalEffectStatus = 'failed';
              error.externalEffectReceipt = {
                clickAttempted: false,
                reason: 'same-order-pending-editable-before-submit',
                originalErrorCode: originalCode,
                notAppliedProof,
                failedAt,
              };
            }
          }
          throw error;
        }
      });
      const terminalDetailProof = verifyProactiveTerminalDetailProof({
        scenarioCode,
        stage,
        orderNumber,
        platformWorkOrderId: activePlatformWorkOrderId || readProgress().platformWorkOrderId,
        selectedOption: guardedSubmission?.selectedPddOption,
        selectionProof: readProgress().pddSubmitSelectionProof,
        submitClicked: guardedSubmission?.submitClicked,
        submitReceipt: guardedSubmission?.submitReceipt,
        transitionConfirmed: guardedSubmission?.transitionConfirmed,
        effectStartedAt: readProgress().pddResolutionSubmission?.externalActionStartedAt,
        submittedAt: guardedSubmission?.submittedAt,
        responseCandidates: guardedSubmission?.responseCandidates,
      });
      if (terminalDetailProof) {
        writeProgress({ pddProactiveTerminalDetailProof: terminalDetailProof });
      }
      const interceptDetailProof = verifyInterceptTerminalDetailProof({
        scenarioCode,
        stage,
        orderNumber,
        platformWorkOrderId: activePlatformWorkOrderId || readProgress().platformWorkOrderId,
        selectedOption: guardedSubmission?.selectedPddOption,
        selectionProof: readProgress().pddSubmitSelectionProof,
        submitClicked: guardedSubmission?.submitClicked,
        submitReceipt: guardedSubmission?.submitReceipt,
        transitionConfirmed: guardedSubmission?.transitionConfirmed,
        effectStartedAt: readProgress().pddResolutionSubmission?.externalActionStartedAt,
        submittedAt: guardedSubmission?.submittedAt,
        responseCandidates: guardedSubmission?.responseCandidates,
      });
      if (interceptDetailProof) {
        writeProgress({ pddInterceptTerminalDetailProof: interceptDetailProof });
      }
      selectedPddOutcome = guardedSubmission?.selectedPddOutcome || selectedPddOutcome;
      selectedPddOption = guardedSubmission?.selectedPddOption || selectedPddOption;
      const submissionAfterAction = readProgress().pddResolutionSubmission;
      if (!oneTimeSubmitRetryAuthorized || submissionAfterAction?.orderNumber !== orderNumber) {
        writeProgress({
          pddResolutionSubmission: {
            ...(submissionAfterAction?.orderNumber === orderNumber ? submissionAfterAction : {}),
            shopId,
            orderNumber,
            scenarioCode,
            effectStage: stage,
            outcome: selectedPddOutcome,
            selectedOption: selectedPddOption,
            resultOption: stagedResultRequired ? decision.pdd?.resultOption || null : null,
            status: 'submitted-unconfirmed',
            submitAttemptCount,
            alreadySucceeded: Boolean(guardedSubmission?.alreadySucceeded),
            submitClicked: guardedSubmission?.submitClicked === true,
            submitReceipt: guardedSubmission?.submitReceipt || null,
            transitionConfirmed: guardedSubmission?.transitionConfirmed === true,
            submittedAt: new Date().toISOString(),
          },
        });
      }
      const finalState = guardedCompletionState || await readOrdinaryCompletionAfterSubmit(
        targetPage,
        orderNumber,
        {
          requireCompleted,
          recoverFollowupStage: requireCompleted,
          scenarioCode,
          decision,
        },
      );
      writeProgress({
        pddResolutionSubmission: {
          ...readProgress().pddResolutionSubmission,
          status: requireCompleted ? 'succeeded' : 'stage-succeeded',
          confirmationMethod: requireCompleted
            ? (finalState?.confirmationMethod || 'detail-completed')
            : 'stage-transition',
          completionEvidence: finalState?.completedOutcome || null,
          completionResultOption: finalState?.completedResultOption || null,
          completedDuringGuardedOptionSelection:
            finalState?.completedDuringGuardedOptionSelection === true,
          completedAt: requireCompleted ? new Date().toISOString() : null,
          stageCompletedAt: requireCompleted ? null : new Date().toISOString(),
        },
      });
      return requireCompleted ? finalState : { ...finalState, targetPage };
    } catch (error) {
      if (error instanceof PddWorkOrderAlreadyCompletedError
        && error.completedState?.orderMatches) {
        logRunStep('ordinary-completion-reconciled-while-waiting-submit', {
          orderNumber,
          scenarioCode,
          confirmationMethod: error.completedState.confirmationMethod || 'detail-completed',
          completedOutcome: error.completedState.completedOutcome || null,
        });
        return {
          ...error.completedState,
          recoveredFromCompletedPage: true,
        };
      }
      lastError = error;
      if (isDefinitivePddStateChangedRejection(error)) {
        stateChangedRecoveryCount += 1;
        const canRetry = stateChangedRecoveryCount < 3 && attempt < 3;
        const rejectedAt = new Date().toISOString();
        writeProgress({
          step: 'ordinary-pdd-state-changed-reconciling',
          pddResolutionSubmission: {
            ...(readProgress().pddResolutionSubmission || {}),
            status: 'rejected-not-applied',
            lastRejectedAt: rejectedAt,
            lastRejectedResponse: error.externalEffectReceipt || null,
          },
          ordinaryPddStateChangedRecovery: {
            orderNumber,
            scenarioCode,
            effectStage: stage,
            status: 'reconciling',
            attempts: stateChangedRecoveryCount,
            maxAttempts: 3,
            reason: error.message,
            updatedAt: rejectedAt,
          },
          manualReview: null,
          error: null,
        });

        await targetPage.waitForTimeout(Math.min(
          Math.max(actionDelayFor(targetPage, 'pdd-state-changed-recovery'), 500),
          2000,
        ));
        targetPage = await reopenPddDetailForResolution(
          targetPage,
          orderNumber,
          readProgress(),
          { forcePendingList: true },
        );
        if (hasConfirmedPendingListAbsence(readProgress(), orderNumber)) {
          return ordinaryCompletionFromPendingListAbsence(orderNumber, scenarioCode, decision);
        }
        const refreshedState = await ensurePddResolutionDetailReady(
          targetPage,
          orderNumber,
          readProgress(),
          { settleMs: Math.max(pddDetailSettleMs, 30_000) },
        );
        if (refreshedState?.isCompleted && refreshedState?.orderMatches) {
          return ordinaryCompletionFromState(orderNumber, scenarioCode, decision, {
            ...refreshedState,
            recoveredFromCompletedPage: true,
          });
        }
        if (!canRetry) {
          const originalMessage = String(error.message || error);
          error.code = 'PDD_ORDINARY_FORM_TEMPORARILY_UNAVAILABLE';
          error.message = `PDD_ORDINARY_FORM_TEMPORARILY_UNAVAILABLE: ${originalMessage}`;
          error.externalEffectStatus = 'failed';
          error.externalEffectReceipt = {
            ...(error.externalEffectReceipt || {}),
            reason: 'pdd-definitive-state-change-rejection-after-refresh',
            attempts: stateChangedRecoveryCount,
            maxAttempts: 3,
          };
          writeProgress({
            step: 'ordinary-pdd-state-changed-retry-ready',
            ordinaryPddStateChangedRecovery: {
              ...readProgress().ordinaryPddStateChangedRecovery,
              status: 'retry-ready',
              retryAfterMs: 30_000,
              retryReadyAt: new Date().toISOString(),
            },
            manualReview: null,
            error: null,
          });
          throw error;
        }
        writeProgress({
          step: 'ordinary-pdd-state-changed-retrying',
          ordinaryPddStateChangedRecovery: {
            ...readProgress().ordinaryPddStateChangedRecovery,
            status: 'retrying',
            nextAttempt: stateChangedRecoveryCount + 1,
            refreshedAt: new Date().toISOString(),
          },
        });
        continue;
      }
      const submissionAfterFailure = readProgress().pddResolutionSubmission;
      if (submissionAfterFailure?.orderNumber === orderNumber
        && Number(submissionAfterFailure.submitAttemptCount || 0) > 0) {
        logRunStep('ordinary-post-click-automatic-retry-blocked', {
          orderNumber,
          scenarioCode,
          submitAttemptCount: submissionAfterFailure.submitAttemptCount,
          reason: error.message,
        });
        throw error;
      }
      if (error instanceof PddSubmitButtonRenderError) {
        submitRenderRecoveryCount += 1;
        const canRetryRender = submitRenderRecoveryCount < 2;
        const progress = readProgress();
        const renderFailureCode = 'PDD_ORDINARY_SUBMIT_RENDER_TEMPORARILY_UNAVAILABLE';
        writeProgress({
          step: canRetryRender
            ? 'ordinary-submit-render-recovery-waiting'
            : 'ordinary-submit-render-retry-ready',
          ordinarySubmitRenderRecovery: {
            orderNumber,
            scenarioCode,
            status: canRetryRender ? 'waiting' : 'retry-ready',
            attempts: submitRenderRecoveryCount,
            maxAttempts: 2,
            timeoutMs: error.externalEffectReceipt?.timeoutMs || 30000,
            clickAttempted: false,
            lastError: error.message,
            retryAfterMs: canRetryRender ? null : 5000,
            updatedAt: new Date().toISOString(),
          },
        });
        if (!canRetryRender) {
          error.code = renderFailureCode;
          error.message = `${renderFailureCode}: ${error.message}`;
          error.externalEffectStatus = 'failed';
          error.externalEffectReceipt = {
            ...(error.externalEffectReceipt || {}),
            clickAttempted: false,
            reason: 'submit-button-not-rendered-after-refresh',
            recoveryAttempts: submitRenderRecoveryCount,
          };
          throw error;
        }
        const detailUrl = progress.detailUrl || targetPage.url();
        try {
          await targetPage.reload({ waitUntil: 'domcontentloaded', timeout: 45000 });
        } catch {
          await navigateSystemPage(targetPage, detailUrl, 'recover-ordinary-submit-render');
        }
        await closeDeviceAccessIfPrompted(targetPage);
        await checkForHumanVerification(targetPage, 'recover-ordinary-submit-render');
        await ensurePddResolutionDetailReady(targetPage, orderNumber, readProgress());
        writeProgress({
          step: 'ordinary-submit-render-recovery-retrying',
          ordinarySubmitRenderRecovery: {
            ...readProgress().ordinarySubmitRenderRecovery,
            status: 'retrying',
            refreshedAt: new Date().toISOString(),
          },
          error: null,
        });
        attempt -= 1;
        continue;
      }
      if (isPddSessionExpiredError(error)) {
        loginRecoveryCount += 1;
        const current = readProgress();
        const previousRecovery = current.ordinaryEvidenceUploadRecovery || {};
        const failure = {
          attempt,
          code: error.code,
          message: error.message,
          sessionExpiry: error.pddSessionExpiry || null,
          failedAt: new Date().toISOString(),
        };
        const failures = [
          ...(Array.isArray(previousRecovery.failures) ? previousRecovery.failures : []),
          failure,
        ].slice(-3);
        const exhausted = loginRecoveryCount > 2;
        writeProgress({
          step: exhausted ? 'ordinary-evidence-upload-exhausted' : 'ordinary-evidence-upload-waiting-login',
          ordinaryEvidenceUploadRecovery: {
            orderNumber,
            scenarioCode,
            attempt,
            attempts: attempt,
            maxAttempts: 3,
            loginRecoveryCount,
            status: exhausted ? 'exhausted' : 'waiting-login',
            error: error.message,
            failures,
            retryAt: null,
            updatedAt: new Date().toISOString(),
          },
          error: null,
        });
        if (exhausted) {
          await pauseForManualReview(
            targetPage,
            'ordinary-scenario-evidence-upload',
            error.message,
            { ordinaryEvidenceUploadRecovery: readProgress().ordinaryEvidenceUploadRecovery },
          );
        }
        const detailUrl = current.detailUrl || targetPage.url();
        await targetPage.reload({ waitUntil: 'domcontentloaded', timeout: 45_000 }).catch(async () => {
          await navigateSystemPage(targetPage, detailUrl, 'ordinary-upload-session-recovery');
        });
        await ensurePddLogin(targetPage, context, detailUrl);
        writeProgress({
          step: 'ordinary-evidence-upload-retrying',
          ordinaryEvidenceUpload: null,
          ordinaryEvidenceUploadRecovery: {
            ...readProgress().ordinaryEvidenceUploadRecovery,
            status: 'retrying',
            retryAt: new Date().toISOString(),
            loginRecoveredAt: new Date().toISOString(),
            updatedAt: new Date().toISOString(),
          },
          error: null,
        });
        updateOrdinaryExecution(orderNumber, scenarioCode, { pddEvidenceUploadFailed: false });
        attempt -= 1;
        continue;
      }
      if (error instanceof HumanVerificationRequiredError
        || error instanceof PddLoginRequiredError
        || error instanceof RateLimitPauseError
        || error instanceof ManualReviewRequiredError
        || !/上传|凭证|非法请求|upload/i.test(error.message)) throw error;
      const previousRecovery = readProgress().ordinaryEvidenceUploadRecovery || {};
      const failure = {
        attempt,
        code: error.code || null,
        message: error.message,
        uploadAuthorizationFailure: error.pddEvidenceUploadAuthorizationFailure || null,
        failedAt: new Date().toISOString(),
      };
      const failures = [
        ...(Array.isArray(previousRecovery.failures) ? previousRecovery.failures : []),
        failure,
      ].slice(-3);
      const definitiveAuthorizationFailure = isDefinitivePddEvidenceAuthorizationFailure(error);
      const maxUploadAttempts = definitiveAuthorizationFailure ? 1 : 3;
      const exhausted = attempt >= maxUploadAttempts;
      writeProgress({
        step: exhausted ? 'ordinary-evidence-upload-exhausted' : 'ordinary-evidence-upload-retrying',
        ordinaryEvidenceUploadRecovery: {
          orderNumber,
          scenarioCode,
          attempt,
          attempts: attempt,
          maxAttempts: maxUploadAttempts,
          definitiveAuthorizationFailure,
          status: exhausted ? 'exhausted' : 'retrying',
          error: error.message,
          failures,
          retryAt: exhausted ? null : new Date().toISOString(),
          updatedAt: new Date().toISOString(),
        },
      });
      if (exhausted) throw error;
      await targetPage.reload({ waitUntil: 'domcontentloaded', timeout: 45_000 }).catch(async () => {
        await navigateSystemPage(targetPage, readProgress().detailUrl, 'ordinary-upload-recovery');
      });
      writeProgress({ ordinaryEvidenceUpload: null });
      updateOrdinaryExecution(orderNumber, scenarioCode, { pddEvidenceUploadFailed: false });
    }
  }
  throw lastError || new Error('普通工单拼多多提交失败');
};

const deleteOrdinaryEvidenceFile = (metadata, allowedRoot) => {
  if (!metadata?.relativePath) return false;
  const absolutePath = path.resolve(workflowDataDir, ...String(metadata.relativePath).split('/'));
  if (!isPathInside(allowedRoot, absolutePath)) {
    throw new Error(`普通工单临时证据路径越界: ${metadata.relativePath}`);
  }
  if (exists(absolutePath)) fs.unlinkSync(absolutePath);
  return true;
};

const finalizeOrdinaryEvidence = (orderNumber, completion) => {
  if (completion?.status !== 'succeeded' || completion.orderNumber !== orderNumber) {
    throw new Error('普通工单未确认完成，禁止清理临时证据');
  }
  const progress = readProgress();
  deleteOrdinaryEvidenceFile(progress.pddEvidenceScreenshot, evidenceScreenshotDir);
  deleteOrdinaryEvidenceFile(progress.tmsEvidenceScreenshot, tmsEvidenceScreenshotDir);
  const deletedAt = new Date().toISOString();
  writeProgress({
    pddEvidenceScreenshot: {
      ...(progress.pddEvidenceScreenshot || { shopId, orderNumber }),
      relativePath: null,
      status: 'deleted',
      deletedAt,
    },
    tmsEvidenceScreenshot: {
      ...(progress.tmsEvidenceScreenshot || { shopId, orderNumber }),
      relativePath: null,
      status: 'deleted',
      deletedAt,
    },
    tmsEvidenceDisposition: {
      ...(progress.tmsEvidenceDisposition || { shopId, orderNumber, usage: 'unused' }),
      status: 'deleted',
      deletedAt,
      pddCompletedAt: completion.completedAt || deletedAt,
    },
  });
};

const ordinaryCompletionFromState = (orderNumber, scenarioCode, decision, state) => {
  const inTransitCompletionProof = scenarioCode === IN_TRANSIT_ADDRESS_CHANGE_CODE
    ? completedInTransitAddressChangeProof(state, orderNumber)
    : null;
  if (inTransitCompletionProof && !inTransitCompletionProof.confirmed) {
    const reason = '平台完成页未证明在途改地址两个阶段均由同一订单完成，禁止归档或重新提交';
    const requiredAt = new Date().toISOString();
    writeProgress({
      step: 'manual-review-required',
      inTransitAddressChangeCompletionProof: inTransitCompletionProof,
      manualReview: {
        stage: 'in-transit-address-change-completion-unverified',
        reason,
        orderNumber,
        requiredAt,
      },
      error: null,
    });
    throw new ManualReviewRequiredError('in-transit-address-change-completion-unverified', reason);
  }
  const submission = readProgress().pddResolutionSubmission || {};
  const feedbackClickAttempted = readProgress().ordinaryFeedbackSubmission?.orderNumber === orderNumber
    && readProgress().ordinaryFeedbackSubmission?.clickAttempted === true;
  const outcome = inTransitCompletionProof?.confirmed
    ? '已联系快递公司修改'
    : (decision.pdd?.completionOption
    || decision.pdd?.option
    || decision.pdd?.resultOption
    || decision.reasonCode);
  const terminalDetailProof = readProgress().pddProactiveTerminalDetailProof;
  const verifiedProactiveHierarchy = verifiedProactiveSummaryMatchesCompletion({
    proof: terminalDetailProof,
    progress: readProgress(),
    completion: {
      orderNumber,
      submitClicked: submission.submitClicked,
      submitReceipt: submission.submitReceipt,
      transitionConfirmed: submission.transitionConfirmed,
      confirmationMethod: state?.confirmationMethod || 'detail-completed',
      platformDetailProof: terminalDetailProof,
    },
    scenarioCode,
    expectedOutcome: outcome,
    observedOutcome: state?.completedOutcome,
    observedResultOption: state?.completedResultOption,
  });
  const interceptDetailProof = readProgress().pddInterceptTerminalDetailProof;
  const verifiedInterceptDetail = verifiedInterceptSummaryMatchesCompletion({
    proof: interceptDetailProof,
    progress: readProgress(),
    completion: {
      orderNumber,
      submitClicked: submission.submitClicked,
      submitReceipt: submission.submitReceipt,
      transitionConfirmed: submission.transitionConfirmed,
      confirmationMethod: state?.confirmationMethod || 'detail-completed',
      platformDetailProof: interceptDetailProof,
    },
    scenarioCode,
    expectedOutcome: outcome,
    observedOutcome: state?.completedOutcome,
    observedResultOption: state?.completedResultOption,
  });
  const verifiedPlatformHierarchy = verifiedProactiveHierarchy || verifiedInterceptDetail;
  if ((submission.orderNumber === orderNumber && submission.submitClicked === true
    || feedbackClickAttempted)
    && ordinaryTerminalOutcomeConflicts({
      scenarioCode,
      expectedOutcome: outcome,
      observedOutcome: state?.completedOutcome,
    }) && !verifiedPlatformHierarchy) {
    const reason = `拼多多完成页结果“${state.completedOutcome}”与本单已提交选项“${outcome}”不一致，禁止归档或重复提交`;
    const detectedAt = new Date().toISOString();
    writeProgress({
      step: 'manual-review-required',
      pddResolutionSubmission: {
        ...submission,
        status: 'manual-review-blocked',
        completionEvidence: state.completedOutcome,
        completionResultOption: state.completedResultOption || null,
        confirmationMethod: state.confirmationMethod || 'detail-completed',
      },
      pddResolutionOutcomeMismatch: {
        status: 'manual-review-blocked',
        policy: 'exact-terminal-result-after-own-submit',
        orderNumber,
        scenarioCode,
        expectedOutcome: outcome,
        completedOutcome: state.completedOutcome,
        detectedAt,
      },
      manualReview: {
        stage: 'pdd-resolution-outcome-mismatch',
        reason,
        orderNumber,
        requiredAt: detectedAt,
      },
      error: null,
    });
    throw new ManualReviewRequiredError('pdd-resolution-outcome-mismatch', reason);
  }
  const platformCompletionObservation = renderedOrdinaryCompletionObservation(
    state, new Date().toISOString(), readProgress().platformWorkOrderId,
  );
  const completion = {
    shopId,
    orderNumber,
    scenarioCode,
    outcome,
    status: 'succeeded',
    recoveredFromCompletedPage: Boolean(state?.recoveredFromCompletedPage),
    completionEvidence: state?.completedOutcome || null,
    ...(inTransitCompletionProof?.confirmed
      ? { completionServiceEvidence: inTransitCompletionProof }
      : state?.completedServiceEvidence
        ? { completionServiceEvidence: state.completedServiceEvidence } : {}),
    completionResultOption: state?.completedResultOption || null,
    ...(verifiedPlatformHierarchy ? {
      platformDetailProof: verifiedProactiveHierarchy ? terminalDetailProof : interceptDetailProof,
    } : {}),
    submitClicked: submission.submitClicked === true || feedbackClickAttempted,
    submitReceipt: submission.submitReceipt || null,
    transitionConfirmed: submission.transitionConfirmed === true,
    completedDuringGuardedOptionSelection:
      state?.completedDuringGuardedOptionSelection === true,
    confirmationMethod: state?.confirmationMethod || 'detail-completed',
    ...(platformCompletionObservation ? { platformCompletionObservation } : {}),
    completedAt: new Date().toISOString(),
  };
  writeProgress({
    step: 'pdd-resolution-succeeded',
    pddResolutionDecision: {
      ...decision,
      status: 'ready',
      outcome,
      flowCode: scenarioCode,
    },
    pddResolutionSubmission: completion,
    ordinaryScenarioDecision: decision,
    error: null,
  });
  finalizeOrdinaryEvidence(orderNumber, completion);
  return completion;
};

const ordinaryCompletionFromPendingListAbsence = (
  orderNumber,
  scenarioCode,
  previousDecision = {},
  { confirmationMethod = 'absent-from-pending-list', completedState = null } = {},
) => {
  const progress = readProgress();
  if (rejectedSubmitPendingListAbsenceNeedsReview(progress, orderNumber)) {
    throw new ManualReviewRequiredError(
      'pdd-resolution-rejected-absent-from-pending',
      '拼多多已明确拒绝本单提交，待办列表消失不能证明计划处理结果；禁止自动归档或重复提交，请人工核对平台终态',
    );
  }
  const exactOrderCompleted = confirmationMethod === 'exact-order-completed';
  if (exactOrderCompleted && (completedState?.detailReady !== true
    || completedState.isCompleted !== true || completedState.orderMatches !== true
    || String(completedState.observedPlatformWorkOrderId || '')
      !== String(progress.platformWorkOrderId || '')
    || !/^\d{6,30}$/u.test(String(progress.platformWorkOrderId || '')))) {
    throw new ManualReviewRequiredError('ordinary-list-completion-unverified',
      '仅有列表已完结提示，尚无同平台工单的完成详情，禁止归档或重新提交');
  }
  const localSubmitAttempted = (progress.pddResolutionSubmission?.orderNumber === orderNumber
    && progress.pddResolutionSubmission.submitClicked === true)
    || (progress.ordinaryFeedbackSubmission?.orderNumber === orderNumber
      && progress.ordinaryFeedbackSubmission.clickAttempted === true);
  const decision = {
    ...previousDecision,
    scenarioCode,
    outcome: exactOrderCompleted ? 'read-only-completed' : 'auto-submit',
    actionCode: 'pdd-completion-recovered',
    reasonCode: exactOrderCompleted
      ? (localSubmitAttempted ? previousDecision.reasonCode
        : completedState.completedOutcome || 'read-only-completed')
      : 'refreshed-exact-empty-pending-list',
    reason: exactOrderCompleted
      ? '已从同店同订单同平台工单的详情页确认完结'
      : '精确订单查询经刷新后仍为零条，平台普通工单已不在待处理列表',
    // A read-only completed row does not prove that this worker selected the
    // previously planned PDD option. Preserve the plan only for legacy zero-result handling.
    pdd: exactOrderCompleted && !localSubmitAttempted ? {} : previousDecision?.pdd || {},
  };
  return ordinaryCompletionFromState(
    orderNumber,
    scenarioCode,
    decision,
    {
      ...(exactOrderCompleted ? completedState : completedPddStateFromPendingListAbsence(orderNumber)),
      confirmationMethod: exactOrderCompleted
        ? 'detail-completed' : 'absent-from-pending-list',
      recoveredFromCompletedPage: true,
    },
  );
};

const ordinaryRetryDelayMs = (decision) => {
  const dueAt = Date.parse(decision.nextAttemptAt || decision.retryAfterAt || '');
  if (!Number.isFinite(dueAt)) return 60_000;
  return Math.max(60_000, dueAt - Date.now());
};

const ensureOrdinaryPddEvidenceForTms = async (
  detailPage,
  orderNumber,
  scenarioCode,
  purpose,
) => {
  const current = readProgress().pddEvidenceScreenshot;
  if (current?.status === 'ready' && current.orderNumber === orderNumber && current.relativePath) {
    return resolveReadyEvidenceScreenshot(orderNumber, readProgress());
  }
  await focusSystemPage('pdd', detailPage);
  await openPddLogisticsKindWithRetry(
    detailPage,
    scenarioCode === ORDINARY_SCENARIO_CODES.PROACTIVE_LOGISTICS_SERVICE
      ? '退货物流' : '发货物流',
    { orderNumber, scenarioCode, stagePrefix: 'ordinary-tms-evidence' },
  );
  await capturePddScenarioEvidenceScreenshot(detailPage, orderNumber, purpose);
  await closePddLogisticsOverlay(detailPage);
  return resolveReadyEvidenceScreenshot(orderNumber, readProgress());
};

const ordinaryTmsFormDecision = (orderNumber, problemType, customerRemark, reasonCode) => ({
  orderNumber,
  status: 'ready',
  problemType,
  customerRemark,
  reason: reasonCode,
  precedence: 'ordinary-scenario-explicit-rule',
  decidedAt: new Date().toISOString(),
});

const ensureOrdinaryOmsAnalysis = async (orderNumber, scenarioCode) => {
  await ensureScenarioSystemDependencies(scenarioCode, ['OMS']);
  const current = readProgress().omsAnalysis;
  const currentOrderStatusReadable = current?.orderNumber === orderNumber
    && String(current.orderStatus || '').trim();
  if (currentOrderStatusReadable
    && (scenarioCode === ORDINARY_SCENARIO_CODES.GOOD_DEED_EXPEDITED_SHIPPING
      || isValidOmsWarehouseValue(current.shippingWarehouse))) return current;
  await focusSystemPage('oms', omsPage);
  return analyzeOmsOrder(omsPage, context, orderNumber);
};

const runOrdinaryTmsAction = async (
  detailPage,
  orderNumber,
  scenarioCode,
  {
    effectStage,
    problemType = null,
    customerRemark = null,
    purpose,
    ignoreUnrelatedExistingTickets = true,
  },
) => {
  const existingProgress = readProgress();
  const existingWorkOrder = existingProgress.tmsWorkOrder;
  const existingEvidence = existingProgress.tmsEvidenceScreenshot;
  if (existingWorkOrder?.status === 'created'
    && existingWorkOrder.orderNumber === orderNumber
    && existingWorkOrder.effectStage === effectStage
    && existingEvidence?.status === 'ready'
    && existingEvidence.orderNumber === orderNumber
    && hasConsumableTmsEvidence(existingProgress, orderNumber)) {
    initializeTmsEvidenceDisposition(orderNumber, existingWorkOrder, existingEvidence);
    if (existingProgress.pddEvidenceScreenshot?.status === 'ready') {
      consumePddEvidenceAfterTmsSuccess(orderNumber, existingWorkOrder, existingEvidence);
    }
    logRunStep('ordinary-tms-stage-reused', {
      orderNumber,
      scenarioCode,
      effectStage,
      ticketId: existingWorkOrder.ticketId || null,
      ticketNo: existingWorkOrder.ticketNo || null,
      externalActionsReplayed: false,
    });
    return existingWorkOrder;
  }
  await ensureOrdinaryOmsAnalysis(orderNumber, scenarioCode);
  await ensureOmsWarehouseMutationAllowed(
    detailPage,
    orderNumber,
    'TMS 建单或拼多多后续提交',
  );
  await ensureOrdinaryPddEvidenceForTms(
    detailPage,
    orderNumber,
    scenarioCode,
    purpose || effectStage,
  );
  await ensureScenarioSystemDependencies(scenarioCode, ['TMS']);
  await focusSystemPage('tms', tmsPage);
  return runTmsWorkflow(tmsPage, context, orderNumber, {
    allowConditionalScenario: true,
    effectStage,
    ignoreUnrelatedExistingTickets,
    formDecisionOverride: problemType
      ? ordinaryTmsFormDecision(orderNumber, problemType, customerRemark, effectStage)
      : null,
  });
};

const refreshProductShortageTmsResult = async (
  detailPage,
  orderNumber,
  scenarioCode,
) => {
  await ensureScenarioSystemDependencies(scenarioCode, ['TMS']);
  await focusSystemPage('tms', tmsPage);
  await openTmsCustomerRegistration(tmsPage, context);
  let progress = readProgress();
  let workOrder = progress.tmsWorkOrder;
  if (workOrder?.status !== 'created' || workOrder.orderNumber !== orderNumber) {
    workOrder = await runOrdinaryTmsAction(detailPage, orderNumber, scenarioCode, {
      effectStage: 'ordinary-product-shortage-verification-v1',
      problemType: '签收未收到',
      customerRemark: '消费者反馈商品少发，请核实包裹发出重量、签收重量及是否存在仓库漏发，核实结果请明确回复',
      purpose: 'ordinary-product-shortage-verification',
      ignoreUnrelatedExistingTickets: false,
    });
    progress = readProgress();
    workOrder = progress.tmsWorkOrder || workOrder;
    await focusSystemPage('tms', tmsPage);
    await openTmsCustomerRegistration(tmsPage, context);
  }
  if (workOrder?.status !== 'created' || workOrder.orderNumber !== orderNumber) {
    await pauseForManualReview(
      detailPage,
      'product-shortage-tms-result-check',
      '商品少发核实缺少本流程创建或复用的 TMS 工单标识，禁止读取其他问题类型记录',
    );
  }
  const rowSelection = await selectKnownTmsRow(tmsPage, orderNumber, workOrder);
  if (!rowSelection.row) {
    throw new LogisticsRetryRequiredError(
      'product-shortage-tms-row-render',
      '商品少发 TMS 核实记录暂未稳定显示，30 秒后只读重查',
      30_000,
      { orderNumber, scenarioCode, transientSystem: 'TMS' },
    );
  }
  const existing = await identifyExistingTmsTicket(rowSelection, orderNumber, progress, {
    allowMissingExpectedLogistics: true,
    allowReadableUnmappedValues: true,
    formDecision: progress.tmsFormDecision || null,
    knownTicket: workOrder,
  });
  const { row: _row, ...duplicateCheck } = existing;
  writeProgress({
    tmsDuplicateCheck: {
      ...duplicateCheck,
      orderNumber,
      checkedAt: new Date().toISOString(),
      reconciliation: 'product-shortage-read-only-result-check',
    },
  });
  if (existing.status !== 'matched') {
    await pauseForManualReview(
      detailPage,
      'product-shortage-tms-result-check',
      existing.reason || '商品少发 TMS 核实记录身份不一致，禁止回填拼多多',
      { tmsDuplicateCheck: readProgress().tmsDuplicateCheck },
    );
  }
  const resultText = String(existing.identity?.values?.快递回复结果 || '').trim() || null;
  const taskStatus = String(existing.identity?.values?.任务状态 || '').trim() || null;
  const checkedAt = new Date().toISOString();
  updateOrdinaryExecution(orderNumber, scenarioCode, {
    productShortageTmsResultText: resultText,
    productShortageTmsTaskStatus: taskStatus,
    productShortageTmsResultCheckedAt: checkedAt,
  });
  return { resultText, taskStatus, checkedAt };
};

const submitOrdinaryStageAndWait = async (
  detailPage,
  orderNumber,
  scenarioCode,
  decision,
  executionPatch,
) => {
  const reminderExtensionCount = Number(executionPatch.reminderExtensionCount || 0);
  const effectStage = decision.actionCode === 'pdd-reminder-extension'
    && Number.isInteger(reminderExtensionCount)
    && reminderExtensionCount > 0
    ? `ordinary-${scenarioCode}-reminder-extension-${reminderExtensionCount}`
    : null;
  const state = await submitOrdinaryPddAction(
    detailPage,
    orderNumber,
    scenarioCode,
    decision,
    { requireCompleted: false, effectStage },
  );
  const submittedAt = new Date().toISOString();
  updateOrdinaryExecution(orderNumber, scenarioCode, {
    ...executionPatch,
    logisticsContactedAt: submittedAt,
    lastStageSubmission: {
      actionCode: decision.actionCode,
      reasonCode: decision.reasonCode,
      submittedAt,
      confirmationMethod: state?.confirmationMethod || null,
    },
  });
  if (state?.isCompleted && state?.orderMatches) {
    logRunStep('ordinary-stage-completed-directly', {
      orderNumber,
      scenarioCode,
      actionCode: decision.actionCode,
      confirmationMethod: state.confirmationMethod || 'detail-completed',
    });
    return ordinaryCompletionFromState(orderNumber, scenarioCode, decision, state);
  }
  const nextAttemptAt = new Date(Date.parse(submittedAt) + 2 * 24 * 60 * 60_000).toISOString();
  writeProgress({
    step: 'ordinary-scenario-stage-waiting',
    ordinaryScenarioDecision: decision,
    // A later two-day extension renders a new PDD form and must upload the
    // retained TMS evidence again. The prior form's upload receipt is not
    // proof that the new form already contains an attachment.
    ordinaryEvidenceUpload: null,
    logisticsWait: {
      reason: decision.reason,
      reasonCode: decision.reasonCode,
      nextAttemptAt,
      retryAfterMs: Math.max(60_000, Date.parse(nextAttemptAt) - Date.now()),
    },
  });
  throw new LogisticsRetryRequiredError(
    decision.reasonCode,
    decision.reason,
    Math.max(60_000, Date.parse(nextAttemptAt) - Date.now()),
  );
};

const executeConsumerAddressChange = async (detailPage, orderNumber) => {
  const scenarioCode = CONSUMER_ADDRESS_CHANGE_CODE;
  await focusSystemPage('pdd', detailPage);
  const identity = ordinaryIdentityFromDetailUrl(detailPage.url());
  const expectedCaseKey = activePlatformCaseKey || readProgress().platformCaseKey;
  if (!identity.platformCaseKey || (expectedCaseKey && expectedCaseKey !== identity.platformCaseKey)) {
    await pauseForManualReview(detailPage, 'ordinary-scenario-manual-review',
      '改地址工单详情身份与当前任务不一致，禁止操作');
  }
  recordOrdinaryPlatformIdentity(detailPage.url());
  try {
    const state = await runConsumerAddressChange({
      orderNumber,
      timeoutMs: Math.max(30_000, pddRenderWaitMs),
      assertIdentity: async () => {
        if (ordinaryIdentityFromDetailUrl(detailPage.url()).platformCaseKey !== identity.platformCaseKey) {
          throw new ConsumerAddressChangeReviewError('address-change-case-changed',
            '改地址工单页面已离开当前工单，禁止继续提交');
        }
      },
      read: () => readConsumerAddressChangeSnapshot(detailPage),
      guard: (stage, action) => guardedExternalEffect({
        effectType: 'pdd-submit', orderNumber, stage, request: { stage, orderNumber },
      }, action),
      apply: (decision) => applyOrdinaryPddFormDecisionOnce(detailPage, decision),
      submit: ({ decision, effectStage, beforeClick, settleUntil }) => clickPddSubmit(
        detailPage, effectStage, orderNumber, {
          guard: false,
          selectedPddOption: decision.pdd.option,
          requiredSelectedPddOptions: [decision.pdd.option, decision.pdd.reasonOption].filter(Boolean),
          beforeClick, settleUntil,
        },
      ),
      record: (event) => {
        const previous = readProgress().consumerAddressChange || {};
        writeProgress({
          step: event.stageSucceeded ? 'address-change-stage-verified' : 'address-change-processing',
          ordinaryScenarioDecision: event.decision,
          consumerAddressChange: {
            ...previous, orderNumber, platformCaseKey: identity.platformCaseKey,
            currentStage: event.decision?.pdd?.stageCode || event.state?.stage,
            lastVerifiedState: event.state || previous.lastVerifiedState,
            completedStages: event.stageSucceeded ? [...new Set([
              ...(previous.platformCaseKey === identity.platformCaseKey ? previous.completedStages || [] : []),
              event.decision.pdd.stageCode,
            ])] : previous.completedStages || [],
            updatedAt: new Date().toISOString(),
          },
          ...(event.effectStage ? { pddResolutionSubmission: {
            shopId, orderNumber, scenarioCode, effectStage: event.effectStage,
            outcome: event.decision.pdd.option,
            status: event.stageSucceeded ? 'stage-succeeded' : 'submitting',
            submitClicked: event.clickAttempted === true || event.stageSucceeded === true,
            transitionConfirmed: event.stageSucceeded === true,
            alreadySucceeded: event.alreadySucceeded === true,
            submittedAt: new Date().toISOString(),
          } } : {}),
        });
      },
    });
    return ordinaryCompletionFromState(orderNumber, scenarioCode, state.decision, state);
  } catch (error) {
    if (error instanceof ConsumerAddressChangeReviewError) {
      await pauseForManualReview(detailPage, 'ordinary-scenario-manual-review', error.message, {
        consumerAddressChangeReview: { reasonCode: error.reasonCode, orderNumber,
          platformCaseKey: identity.platformCaseKey, observedAt: new Date().toISOString() },
      });
    }
    throw error;
  }
};

const executeExtendedOrdinaryScenario = async (
  detailPage,
  orderNumber,
  scenarioCode,
) => {
  if (!isExtendedOrdinaryScenario(scenarioCode)) {
    throw new Error(`不支持的新增普通工单场景: ${scenarioCode}`);
  }
  if (scenarioDefinitionFor(scenarioCode)?.processingEnabled === false) {
    throw new Error(`普通工单场景已暂停处理，禁止执行外部操作: ${scenarioCode}`);
  }
  if (scenarioCode === CONSUMER_ADDRESS_CHANGE_CODE) {
    return executeConsumerAddressChange(detailPage, orderNumber);
  }
  // A claimed order can have been discovered by an older worker or from a
  // stale list row. Validate the rendered detail title once before collecting
  // facts so a different PDD scenario can never receive this flow's action.
  // This is intentionally limited to extended ordinary scenarios; the
  // dedicated return-refund path has its own state and effect guards.
  let detailIdentityValidated = false;
  for (let iteration = 1; iteration <= 12; iteration++) {
    await focusSystemPage('pdd', detailPage);
    if (!detailIdentityValidated) {
      const detailState = await waitForPddResolutionDetail(
        detailPage,
        orderNumber,
        { readTimeoutMs: 10_000, settleMs: Math.min(pddDetailSettleMs, 15_000) },
      );
      if (detailState.detailReady && detailState.orderMatches && detailState.detailWorkOrderType) {
        const expectedType = readProgress().workOrderType || activeWorkOrderType;
        if (!ordinaryWorkOrderTypesEquivalent(expectedType, detailState.detailWorkOrderType)) {
          await pauseForManualReview(
            detailPage,
            'ordinary-scenario-manual-review',
            `拼多多详情页真实工单类型“${detailState.detailWorkOrderType}”与当前队列类型“${expectedType || 'unknown'}”不一致，禁止沿用原业务流程`,
            {
              pddDetailIdentityMismatch: {
                expectedWorkOrderType: expectedType || null,
                observedWorkOrderType: detailState.detailWorkOrderType,
                orderNumber,
                scenarioCode,
                checkedAt: new Date().toISOString(),
              },
            },
          );
        }
      }
      detailIdentityValidated = true;
    }
    const { facts } = await collectOrdinaryScenarioFacts(detailPage, orderNumber, scenarioCode);
    if (chatPolicyForScenario(scenarioCode) && facts.chatAnalysis?.status === 'pending') {
      const currentProgress = readProgress();
      const discovery = currentProgress.latestDiscovery || {};
      await ensureChatAnalysisCase(shopId, orderNumber, {
        platformCaseKey: discovery.platformCaseKey
          || currentProgress.platformCaseKey
          || activePlatformCaseKey,
        platformCaseId: discovery.platformWorkOrderId
          || currentProgress.platformWorkOrderId,
        detailUrl: discovery.detailUrl || detailPage.url(),
        scenarioCode,
        workOrderType: currentProgress.workOrderType || activeWorkOrderType,
      }).catch(() => false);
    }
    const decision = evaluateOrdinaryWorkOrderScenario(scenarioCode, facts, { now: new Date() });
    writeProgress({
      step: 'ordinary-scenario-decision-ready',
      ordinaryScenarioDecision: decision,
      ordinaryScenarioIteration: iteration,
      error: null,
    });
    logRunStep('ordinary-scenario-decision-ready', {
      orderNumber,
      scenarioCode,
      iteration,
      outcome: decision.outcome,
      actionCode: decision.actionCode,
      reasonCode: decision.reasonCode,
    });

    if (decision.outcome === 'manual-review') {
      await pauseForManualReview(
        detailPage,
        'ordinary-scenario-manual-review',
        decision.reason,
        { ordinaryScenarioDecision: decision },
      );
    }
    if (decision.outcome === 'wait') {
      const retryAfterMs = ordinaryRetryDelayMs(decision);
      writeProgress({
        step: 'ordinary-scenario-waiting',
        ordinaryScenarioDecision: decision,
        logisticsWait: {
          reason: decision.reason,
          reasonCode: decision.reasonCode,
          nextAttemptAt: decision.nextAttemptAt,
          retryAfterMs,
        },
      });
      throw new LogisticsRetryRequiredError(decision.reasonCode, decision.reason, retryAfterMs);
    }
    if (decision.outcome === 'auto-submit') {
      if (decision.actionCode === 'pdd-stage-submit') {
        const stageCode = String(decision.pdd?.stageCode || '').trim();
        if (!stageCode) throw new Error(`普通工单多阶段提交缺少阶段代码: ${scenarioCode}`);
        const state = await submitOrdinaryPddAction(
          detailPage,
          orderNumber,
          scenarioCode,
          decision,
          {
            requireCompleted: false,
            effectStage: `ordinary-${scenarioCode}-${stageCode}-v1`,
          },
        );
        if (state?.isCompleted && state?.orderMatches) {
          return ordinaryCompletionFromState(orderNumber, scenarioCode, decision, state);
        }
        const completedPddStages = [...new Set([
          ...(Array.isArray(facts.completedPddStages) ? facts.completedPddStages : []),
          stageCode,
        ])];
        updateOrdinaryExecution(orderNumber, scenarioCode, {
          completedPddStages,
          lastStageSubmission: {
            stageCode,
            reasonCode: decision.reasonCode,
            submittedAt: new Date().toISOString(),
          },
        });
        if (state?.messageStageSubmitted) {
          let completionState = state;
          try {
            completionState = await readOrdinaryCompletionAfterSubmit(
              detailPage,
              orderNumber,
              { requireCompleted: true },
            );
          } catch (error) {
            if (!/拼多多提交后未确认当前普通工单已完结，禁止重复提交/u.test(
              String(error?.message || ''),
            )) throw error;
          }
          if (completionState?.isCompleted && completionState?.orderMatches) {
            return ordinaryCompletionFromState(
              orderNumber,
              scenarioCode,
              decision,
              completionState,
            );
          }
          const retryAfterMs = 30_000;
          writeProgress({
            step: 'ordinary-pdd-message-submitted-awaiting-completion',
            ordinaryScenarioDecision: decision,
            ordinaryPddMessageStage: {
              ...readProgress().ordinaryPddMessageStage,
              orderNumber,
              scenarioCode,
              status: 'submitted-awaiting-completion',
              responseConfirmed: state.responseConfirmed === true,
              alreadySucceeded: state.alreadySucceeded === true,
              retryAfterMs,
              updatedAt: new Date().toISOString(),
            },
            manualReview: null,
            error: null,
          });
          throw new LogisticsRetryRequiredError(
            'ordinary-pdd-message-completion-recheck',
            '拼多多预填话术已提交，等待平台完成状态同步；后续只读复核，禁止重复发送',
            retryAfterMs,
            { messageStageSubmitted: true },
          );
        }
        const waitAfterSubmitMs = Number(decision.pdd?.waitAfterSubmitMs || 0);
        if (waitAfterSubmitMs > 0) {
          const nextAttemptAt = decision.nextAttemptAt
            || new Date(Date.now() + waitAfterSubmitMs).toISOString();
          writeProgress({
            step: 'ordinary-scenario-stage-waiting',
            ordinaryScenarioDecision: decision,
            logisticsWait: {
              reason: decision.reason,
              reasonCode: decision.reasonCode,
              nextAttemptAt,
              retryAfterMs: Math.max(60_000, Date.parse(nextAttemptAt) - Date.now()),
            },
          });
          throw new LogisticsRetryRequiredError(
            decision.reasonCode,
            decision.reason,
            Math.max(60_000, Date.parse(nextAttemptAt) - Date.now()),
          );
        }
        writeProgress({
          step: 'ordinary-scenario-stage-advanced',
          ordinaryScenarioDecision: decision,
          ordinaryEvidenceUpload: null,
          error: null,
        });
        continue;
      }
      if (decision.actionCode === 'pdd-reminder-extension') {
        const completion = await submitOrdinaryStageAndWait(
          detailPage,
          orderNumber,
          scenarioCode,
          decision,
          { reminderExtensionCount: Number(facts.reminderExtensionCount || 0) + 1 },
        );
        if (completion) return completion;
      }
      let state;
      try {
        state = await submitOrdinaryPddAction(
          detailPage,
          orderNumber,
          scenarioCode,
          decision,
        );
      } catch (error) {
        const selectedOption = String(
          decision.pdd?.completionOption
            || decision.pdd?.resultOption
            || decision.pdd?.option
            || '',
        ).normalize('NFKC').trim();
        const rejectedLogisticsUpdate = scenarioCode === ORDINARY_SCENARIO_CODES.DELIVERY_RISK_CONCERN
          && error instanceof PddSubmitRejectedError
          && (Number(error.errorCode) === 190001
            || /物流轨迹未更新[，,]请如实填写/u.test(String(error.errorMsg || '')))
          && /^(?:物流已更新|物流已恢复更新|物流已正常更新|物流恢复|轨迹已更新)$/u
            .test(selectedOption);
        if (!rejectedLogisticsUpdate) throw error;
        const rejectedAt = new Date().toISOString();
        const rejection = {
          errorCode: Number(error.errorCode) || null,
          errorMessage: error.errorMsg || error.message,
          option: selectedOption,
          effectStage: error.stage || null,
          latestLogisticsAt: decision.evidence?.logistics?.latestLogisticsAt || null,
          responseCaptured: error.externalEffectReceipt?.responseCaptured === true,
          rejectedAt,
        };
        updateOrdinaryExecution(orderNumber, scenarioCode, {
          platformLogisticsUpdateRejection: rejection,
        });
        writeProgress({
          step: 'ordinary-platform-logistics-update-rejected-reevaluating',
          platformLogisticsUpdateRejection: rejection,
          pddResolutionSubmission: {
            ...(readProgress().pddResolutionSubmission || {}),
            status: 'rejected-not-applied',
            lastRejectedAt: rejectedAt,
            lastRejectedResponse: error.externalEffectReceipt || null,
          },
          error: null,
        });
        continue;
      }
      return ordinaryCompletionFromState(orderNumber, scenarioCode, decision, state);
    }
    if (decision.outcome !== 'external-action') {
      throw new Error(`普通工单规则返回未知结果: ${decision.outcome}`);
    }

    if (decision.actionCode === 'product-shortage-chat-analysis-required'
      || decision.actionCode === 'delivered-address-change-chat-analysis-required'
      || decision.actionCode === 'in-transit-address-change-chat-analysis-required') {
      // Release the claim so the resident worker can run its independent
      // chat collector.  No PDD/OMS/TMS mutation is performed here.
      const currentProgress = readProgress();
      const discovery = currentProgress.latestDiscovery || {};
      await ensureChatAnalysisCase(shopId, orderNumber, {
        platformCaseKey: discovery.platformCaseKey
          || currentProgress.platformCaseKey
          || activePlatformCaseKey,
        platformCaseId: discovery.platformWorkOrderId
          || currentProgress.platformWorkOrderId,
        detailUrl: discovery.detailUrl || detailPage.url(),
        scenarioCode,
        workOrderType: currentProgress.workOrderType || activeWorkOrderType,
      }).catch(() => false);
      writeProgress({
        step: decision.actionCode === 'delivered-address-change-chat-analysis-required'
          ? 'delivered-address-change-chat-analysis-waiting'
          : decision.actionCode === 'in-transit-address-change-chat-analysis-required'
            ? 'in-transit-address-change-chat-analysis-waiting'
            : 'product-shortage-chat-analysis-waiting',
        ordinaryScenarioDecision: decision,
        chatAnalysis: { status: 'pending', requestedAt: new Date().toISOString() },
        error: null,
      });
      throw new LogisticsRetryRequiredError(
        decision.reasonCode,
        decision.reason,
        120_000,
      );
    }
    if (decision.actionCode === 'promise-reissue-oms-query') {
      await focusSystemPage('oms', omsPage);
      await analyzeOmsOrder(omsPage, context, orderNumber);
      // Re-collect the PDD countdown and the persisted OMS read-only result on
      // the next iteration before selecting the final PDD option.
      continue;
    }
    if (decision.actionCode === 'product-shortage-chat-followup-check') {
      const checkedAt = new Date().toISOString();
      await requestProductShortageChatRecollection(shopId, orderNumber).catch(() => false);
      updateOrdinaryExecution(orderNumber, scenarioCode, {
        chatFollowupCheckedAt: checkedAt,
      });
      writeProgress({
        step: 'product-shortage-chat-followup-waiting',
        ordinaryScenarioDecision: decision,
        chatFollowupCheckRequestedAt: checkedAt,
        chatFollowupCheckedAt: checkedAt,
        error: null,
      });
      throw new LogisticsRetryRequiredError(
        decision.reasonCode,
        decision.reason,
        30_000,
      );
    }

    if (decision.actionCode === 'oms-warehouse-query'
      || decision.actionCode === 'oms-allocation-check') {
      await ensureOrdinaryOmsAnalysis(orderNumber, scenarioCode);
      continue;
    }

    if (decision.actionCode === 'oms-manual-allocation') {
      await ensureOrdinaryOmsAnalysis(orderNumber, scenarioCode);
      const recommendedCarriers = (readProgress().logisticsAnalysis?.recommendedCarriers || [])
        .map((value) => String(value || '').trim()).filter(Boolean);
      await focusSystemPage('oms', omsPage);
      await runOmsManualAllocation(
        omsPage,
        context,
        orderNumber,
        recommendedCarriers,
        {
          effectStage: `ordinary-${scenarioCode}-manual-allocation-v1`,
          allowFirstAvailableCarrier:
            scenarioCode === ORDINARY_SCENARIO_CODES.GOOD_DEED_EXPEDITED_SHIPPING,
        },
      );
      continue;
    }

    if (decision.actionCode === 'tms-reminder') {
      const ticket = await runOrdinaryTmsAction(detailPage, orderNumber, scenarioCode, {
        effectStage: 'ordinary-delivery-risk-reminder-v1',
        problemType: '催件',
        customerRemark: '物流长时间未更新，请核实并尽快更新物流',
        purpose: 'ordinary-delivery-risk-reminder',
      });
      const completion = await submitOrdinaryStageAndWait(
        detailPage,
        orderNumber,
        scenarioCode,
        decision,
        {
          tmsLookupCompleted: true,
          firstReminderTicket: ticket,
        },
      );
      if (completion) return completion;
    }

    if (decision.actionCode === 'delivered-not-received-oms-tms-flow'
      || decision.actionCode === 'consumer-refusal-oms-tms-flow') {
      const deliveredNotReceived = decision.actionCode === 'delivered-not-received-oms-tms-flow';
      const ticket = await runOrdinaryTmsAction(detailPage, orderNumber, scenarioCode, {
        effectStage: deliveredNotReceived
          ? 'ordinary-delivered-not-received-contact-v1'
          : 'ordinary-consumer-refusal-intercept-v1',
        problemType: deliveredNotReceived ? '签收未收到' : '拦截退回',
        customerRemark: deliveredNotReceived
          ? '签收未收到，请提供签字底单，24小时未处理请反馈'
          : '消费者明确拒收，请拦截退回包裹',
        purpose: deliveredNotReceived
          ? 'ordinary-delivered-not-received-contact'
          : 'ordinary-consumer-refusal-intercept',
      });
      updateOrdinaryExecution(orderNumber, scenarioCode, {
        omsTmsFlowCompleted: true,
        tmsLookupCompleted: true,
        commonFlowTicket: ticket,
      });
      continue;
    }

    if (decision.actionCode === 'delivered-address-change-oms-tms-flow') {
      const ticket = await runOrdinaryTmsAction(detailPage, orderNumber, scenarioCode, {
        effectStage: 'ordinary-delivered-address-change-v1',
        problemType: '拦截退回',
        customerRemark: '消费者填错地址，包裹已签收或代收，无法修改地址，请核实拦截退回并反馈',
        purpose: 'ordinary-delivered-address-change',
      });
      updateOrdinaryExecution(orderNumber, scenarioCode, {
        omsTmsFlowCompleted: true,
        tmsLookupCompleted: true,
        commonFlowTicket: ticket,
      });
      continue;
    }

    if (decision.actionCode === 'in-transit-address-change-oms-tms-flow') {
      const ticket = await runOrdinaryTmsAction(detailPage, orderNumber, scenarioCode, {
        effectStage: 'ordinary-in-transit-address-change-v1',
        problemType: '改地址',
        customerRemark: '客户申请改地址',
        purpose: 'ordinary-in-transit-address-change',
      });
      updateOrdinaryExecution(orderNumber, scenarioCode, {
        omsTmsFlowCompleted: true,
        tmsLookupCompleted: true,
        commonFlowTicket: ticket,
      });
      continue;
    }

    if (decision.actionCode === 'product-shortage-verification-flow') {
      const ticket = await runOrdinaryTmsAction(detailPage, orderNumber, scenarioCode, {
        effectStage: 'ordinary-product-shortage-verification-v1',
        problemType: '签收未收到',
        customerRemark: '消费者反馈商品少发，请核实包裹发出重量、签收重量及是否存在仓库漏发，核实结果请明确回复',
        purpose: 'ordinary-product-shortage-verification',
        ignoreUnrelatedExistingTickets: false,
      });
      const current = readProgress();
      const identity = current.tmsDuplicateCheck?.status === 'matched'
        ? current.tmsDuplicateCheck.identity || {}
        : {};
      updateOrdinaryExecution(orderNumber, scenarioCode, {
        omsTmsFlowCompleted: true,
        tmsLookupCompleted: true,
        commonFlowTicket: ticket,
        productShortageTmsResultText:
          String(identity.values?.快递回复结果 || '').trim() || null,
        productShortageTmsTaskStatus:
          String(identity.values?.任务状态 || '').trim() || null,
        productShortageTmsResultCheckedAt: new Date().toISOString(),
      });
      continue;
    }

    if (decision.actionCode === 'product-shortage-tms-result-check') {
      await refreshProductShortageTmsResult(detailPage, orderNumber, scenarioCode);
      continue;
    }

    if (decision.actionCode === 'oms-tms-common-flow') {
      const unsigned = decision.pdd?.pendingOption === '已进行召回';
      const ticket = await runOrdinaryTmsAction(detailPage, orderNumber, scenarioCode, {
        effectStage: unsigned
          ? 'ordinary-intercept-recall-v1'
          : 'ordinary-intercept-common-flow-v1',
        problemType: unsigned ? '拦截退回' : null,
        customerRemark: unsigned ? '消费者申请退款，需召回快递' : null,
        purpose: 'ordinary-intercept-common-flow',
      });
      updateOrdinaryExecution(orderNumber, scenarioCode, {
        omsTmsFlowCompleted: true,
        tmsLookupCompleted: true,
        tmsRecallCompleted: unsigned,
        commonFlowTicket: ticket,
      });
      continue;
    }

    if (decision.actionCode === 'tms-recall') {
      const current = ordinaryExecutionFor(orderNumber, scenarioCode);
      let ticket = current.commonFlowTicket || null;
      if (!current.tmsRecallCompleted || !readProgress().tmsEvidenceScreenshot?.relativePath) {
        ticket = await runOrdinaryTmsAction(detailPage, orderNumber, scenarioCode, {
          effectStage: 'ordinary-intercept-recall-v1',
          problemType: '拦截退回',
          customerRemark: '消费者申请退款，需召回快递',
          purpose: 'ordinary-intercept-recall',
        });
      }
      updateOrdinaryExecution(orderNumber, scenarioCode, {
        omsTmsFlowCompleted: true,
        tmsLookupCompleted: true,
        tmsRecallCompleted: true,
        commonFlowTicket: ticket,
      });
      continue;
    }

    if (decision.actionCode === 'tms-lost-and-oms-reissue') {
      const lostTicket = await runOrdinaryTmsAction(detailPage, orderNumber, scenarioCode, {
        effectStage: 'ordinary-delivery-risk-lost-v1',
        problemType: '丢件',
        customerRemark: '物流超48小时未更新，记丢件并补发',
        purpose: 'ordinary-delivery-risk-lost',
      });
      await ensureScenarioSystemDependencies(scenarioCode, ['OMS']);
      await focusSystemPage('oms', omsPage);
      const reissueOrder = await runOmsReissueCreation(omsPage, context, orderNumber);
      updateOrdinaryExecution(orderNumber, scenarioCode, {
        lostTicket,
        tmsLookupCompleted: true,
        reissueOrder,
      });
      continue;
    }

    if (decision.actionCode === 'oms-reissue-tracking-check') {
      await ensureScenarioSystemDependencies(scenarioCode, ['OMS']);
      await focusSystemPage('oms', omsPage);
      await checkOmsReissueTrackingNumber(omsPage, context, orderNumber);
      continue;
    }

    await pauseForManualReview(
      detailPage,
      'ordinary-scenario-external-action',
      `普通工单外部动作尚无安全执行器: ${decision.actionCode}`,
      { ordinaryScenarioDecision: decision },
    );
  }
  throw new Error(`普通工单场景在单次会话内超过安全推进次数: ${scenarioCode}`);
};

const confirmLegacyResolutionCompletionDetail = async (targetPage, orderNumber, state) => {
  const progress = readProgress();
  const expectedPlatformWorkOrderId = progress.platformWorkOrderId
    || parsePlatformWorkOrderId(progress.detailUrl);
  const proof = legacyResolutionCompletionObservation(
    state, expectedPlatformWorkOrderId, new Date().toISOString(),
  );
  if (!proof.valid) {
    await pauseForManualReview(
      targetPage,
      'pdd-resolution-validation',
      `拼多多已完结详情未能证明是当前工单，禁止归档: ${proof.reason}`,
      { orderNumber, expectedPlatformWorkOrderId, observedPlatformWorkOrderId: state?.observedPlatformWorkOrderId || null },
    );
  }
  return proof.observation;
};

const runPddResolutionWorkflow = async (targetPage, orderNumber) => {
  let progress = readProgress();
  if (targetPage === pddPage && !targetPage.url().includes('/aftersales/work_order/tododetail')) {
    targetPage = progress.detailUrl ? await openSavedPddDetailPage(progress.detailUrl) : pddPage;
  }
  await focusSystemPage('pdd', targetPage);
  targetPage = await reopenPddDetailForResolution(targetPage, orderNumber, progress);
  await focusSystemPage('pdd', targetPage);
  await closeDeviceAccessIfPrompted(targetPage);
  let pageState = hasConfirmedPendingListAbsence(readProgress(), orderNumber)
    ? completedPddStateFromPendingListAbsence(orderNumber)
    : await ensurePddResolutionDetailReady(targetPage, orderNumber, progress);

  // If PDD already says the work order is complete, do not re-enter the form
  // or click submit again. The existing TMS evidence is still disposed of only
  // after this completion is persisted and verified.
  if (pageState.isCompleted) {
    const platformCompletionObservation = await confirmLegacyResolutionCompletionDetail(
      targetPage, orderNumber, pageState,
    );
    const expectedOutcome = expectedPddCompletionOutcome(progress);
    if (pddCompletionOutcomeMismatchForProgress(
      progress,
      expectedOutcome,
      pageState.completedOutcome,
      pageState.completedResultOption,
    )) {
      recordAcceptedPddTerminalOutcomeMismatch({
        progress,
        orderNumber,
        expectedOutcome,
        completedOutcome: pageState.completedOutcome,
        completedResultOption: pageState.completedResultOption,
        source: 'completed-before-resolution',
      });
    }
    const currentDisposition = readProgress().tmsEvidenceDisposition;
    if (currentDisposition?.usage === 'pending') {
      markTmsEvidenceUnused(orderNumber, progress.workOrderType || targetWorkOrderTitle);
    }
    const completion = {
      shopId,
      orderNumber,
      outcome: pageState.completedOutcome || expectedOutcome || null,
      status: 'succeeded',
      recoveredFromCompletedPage: true,
      completionEvidence: pageState.completedOutcome || null,
      confirmationMethod: pageState.confirmationMethod || 'detail-completed',
      ...(platformCompletionObservation ? { platformCompletionObservation } : {}),
      completedAt: new Date().toISOString(),
    };
    writeProgress({
      step: 'pdd-resolution-succeeded',
      pddResolutionSubmission: completion,
      currentUrl: targetPage.url(),
      error: null,
    });
    finalizeEvidenceAfterPddCompletion(orderNumber, completion);
    logRunStep('full-business-flow-complete', {
      orderNumber,
      pddResolutionSubmission: completion,
      currentUrl: targetPage.url(),
      error: null,
    });
    persistSystemTabs('pdd');
    if (targetPage !== pddPage && derivedPages.has(targetPage)) await closeDerivedPage(targetPage);
    return completion;
  }

  const consumerNegotiationResume = resolvePddConsumerNegotiationResume(progress, orderNumber);
  const inTransitOutcomeFallbackResume = resolvePddInTransitOutcomeFallbackResume(
    progress,
    orderNumber,
  );
  let decision;
  if (consumerNegotiationResume) {
    if (!consumerNegotiationResume.ready) {
      throw new LogisticsRetryRequiredError(
        'pdd-consumer-negotiation-waiting',
        '拼多多正在等待消费者确认拦截后退款方案，满 12 小时仍无回复后再自动处理',
        consumerNegotiationResume.retryAfterMs,
        {
          orderNumber,
          detailUrl: targetPage.url(),
          nextAttemptAt: consumerNegotiationResume.nextAttemptAt,
        },
      );
    }
    decision = consumerNegotiationResume.decision;
    writeProgress({
      step: 'pdd-consumer-negotiation-followup-ready',
      pddResolutionSubmission: {
        ...progress.pddResolutionSubmission,
        status: 'followup-ready',
        consumerResponseNextAttemptAt: consumerNegotiationResume.nextAttemptAt,
      },
      consumerNegotiationFollowupRecovery: {
        strategy: 'resume-pdd-followup-without-oms-or-tms-replay',
        recoveredAt: new Date().toISOString(),
      },
      error: null,
      manualReview: null,
    });
  } else if (inTransitOutcomeFallbackResume) {
    decision = inTransitOutcomeFallbackResume.decision;
    writeProgress({
      step: 'pdd-in-transit-outcome-fallback-ready',
      inTransitOutcomeFallbackRecovery: {
        strategy: 'resume-pdd-outcome-fallback-without-oms-or-tms-replay',
        rejectedOutcomeLabels: inTransitOutcomeFallbackResume.rejectedOutcomeLabels,
        nextOutcome: inTransitOutcomeFallbackResume.nextOutcome,
        recoveredAt: new Date().toISOString(),
      },
      error: null,
      manualReview: null,
    });
  } else {
    // A verified completed PDD detail is terminal even if a restarted worker no
    // longer has the pre-completion TMS artifacts. Require those artifacts only
    // while the PDD work order is still pending and an external action may run.
    if (scenarioRequiresTms(progress.scenarioCode) || progress.tmsWorkOrder?.status === 'created') {
      try {
        resolveReadyTmsEvidence(orderNumber, progress);
      } catch (error) {
        if (error?.message !== 'TMS 截图元数据存在但文件已丢失') throw error;
        await recoverMissingTmsEvidence(orderNumber, progress);
        progress = readProgress();
      }
    } else if (progress.scenarioCode === 'abnormal-network-warning'
      && !hasCompletedTmsBypass(progress, orderNumber)) {
      throw new Error('异常网点预警尚未记录 TMS 跳过状态');
    }

    decision = decidePddResolution({
      orderNumber,
      scenarioCode: progress.scenarioCode || activeScenarioCode,
      workOrderType: progress.workOrderType || targetWorkOrderTitle,
      logisticsAnalysis: progress.logisticsAnalysis,
      omsAnalysis: progress.omsAnalysis,
      omsManualAllocation: progress.omsManualAllocation,
      tmsWorkOrder: progress.tmsWorkOrder,
      tmsEvidenceScreenshot: progress.tmsEvidenceScreenshot,
    });
  }
  writeProgress({ pddResolutionDecision: decision });
  if (decision.status !== 'ready') {
    if (decision.status === 'retry-ready') {
      throw new LogisticsRetryRequiredError('pdd-logistics-waiting', decision.reason, decision.retryAfterMs);
    }
    await pauseForManualReview(targetPage, 'pdd-resolution-decision', decision.reason, {
      pddResolutionDecision: decision,
    });
  }
  // A prior submit is always reconciled read-only before another click. The
  // database owns the succeeded -> failed -> reserved transition that permits
  // the one and only retry.
  const previousSubmission = readProgress().pddResolutionSubmission;
  const matchingPreviousSubmission = previousSubmission?.orderNumber === orderNumber
    ? previousSubmission
    : null;
  if (['submitting', 'manual-review-blocked'].includes(matchingPreviousSubmission?.status)
    && !pageState.isCompleted) {
    pageState = await confirmPddCompletionWithoutResubmit(targetPage, orderNumber, pageState);
    const observation = buildPddSubmissionReconciliationObservation({
      pageState,
      orderNumber,
      previousSubmission: matchingPreviousSubmission,
    });
    if (observation.state === 'confirmed') {
      writeProgress({
        pddResolutionSubmission: {
          ...matchingPreviousSubmission,
          status: 'succeeded',
          confirmationMethod: observation.confirmationMethod,
          completionEvidence: observation.completionEvidence,
          completedAt: observation.observedAt,
        },
        step: 'pdd-resolution-recovered',
        externalStateReconciliation: observation,
      });
    } else {
      writeProgress({
        step: observation.state === 'not-applied'
          ? 'pdd-submit-not-applied'
          : 'external-state-unresolved',
        externalStateReconciliation: observation,
        pddResolutionSubmission: {
          ...matchingPreviousSubmission,
          status: 'manual-review-blocked',
          blockedAt: observation.observedAt,
        },
      });
      await pauseForManualReview(
        targetPage,
        'pdd-resolution-submit-confirmation',
        observation.state === 'not-applied'
          ? '已确认上一次提交未生效，等待数据库完成幂等协调后仅重试一次'
          : observation.automaticRetryExhausted
            ? '拼多多两次提交均未生效，已禁止第三次提交'
            : '上一次提交结果仍无法确认，禁止重复提交',
      );
    }
  }

  let completion;
  const flowCode = readProgress().pddResolutionFlow?.flowCode;
  const currentDisposition = readProgress().tmsEvidenceDisposition;
  if (flowCode === 'primary-refund'
    || flowCode === 'shipped-no-tracking-refund'
    || flowCode === 'intercept-progress'
    || flowCode === 'consumer-negotiation-followup'
    || (!flowCode && currentDisposition?.usage === 'pending')) {
    if (currentDisposition && currentDisposition.status !== 'deleted') {
      markTmsEvidenceUnused(orderNumber, decision.workOrderType);
    }
  }
  const latestProgress = readProgress();
  const savedSubmission = latestProgress.pddResolutionSubmission;
  let expectedCompletionOutcome = expectedPddCompletionOutcome(latestProgress)
    || (flowCode === 'subjective-intercept' ? pddSubjectiveDirectRefundOutcome : decision.outcome);
  if (pageState.isCompleted) {
    const platformCompletionObservation = await confirmLegacyResolutionCompletionDetail(
      targetPage, orderNumber, pageState,
    );
    if (pddCompletionOutcomeMismatchForProgress(
      readProgress(),
      expectedCompletionOutcome,
      pageState.completedOutcome,
      pageState.completedResultOption,
    )) {
      recordAcceptedPddTerminalOutcomeMismatch({
        progress: readProgress(),
        orderNumber,
        expectedOutcome: expectedCompletionOutcome,
        completedOutcome: pageState.completedOutcome,
        completedResultOption: pageState.completedResultOption,
        source: 'completed-before-submit',
      });
    }
    completion = {
      shopId,
      orderNumber,
      outcome: pageState.completedOutcome || expectedCompletionOutcome,
      status: 'succeeded',
      recoveredFromCompletedPage: true,
      confirmationMethod: pageState.confirmationMethod || 'detail-completed',
      ...(platformCompletionObservation ? { platformCompletionObservation } : {}),
      completedAt: new Date().toISOString(),
    };
  } else {
    if (!pageState.isPending) {
      const absent = await confirmOrderAbsentFromPendingList(targetPage, orderNumber);
      if (!absent) {
        await pauseForManualReview(targetPage, 'pdd-resolution-state', '拼多多工单仍在待处理列表，禁止重复提交');
      }
      completion = {
        shopId,
        orderNumber,
        outcome: expectedCompletionOutcome,
        status: 'succeeded',
        recoveredFromCompletedPage: true,
        confirmationMethod: 'absent-from-pending-list',
        completedAt: new Date().toISOString(),
      };
    } else {
      const preSubmitSubmission = readProgress().pddResolutionSubmission;
      if (preSubmitSubmission?.orderNumber === orderNumber
        && Number(preSubmitSubmission.submitAttemptCount || 0) >= 2
        && !preSubmitSubmission.historicalEvidenceRefundFallbackAuthorizedAt) {
        await pauseForManualReview(
          targetPage,
          'pdd-resolution-submit-confirmation',
          '拼多多提交次数已达到两次，禁止第三次提交',
        );
      }
      let finalState;
      try {
        finalState = await submitPddResolutionWithRefreshRecovery(targetPage, decision);
      } catch (error) {
        if (error instanceof HumanVerificationRequiredError
          || error instanceof PddLoginRequiredError
          || error instanceof RateLimitPauseError
          || error instanceof ManualReviewRequiredError
          || error instanceof LogisticsRetryRequiredError
          || error?.code === 'PDD_ORDINARY_SUBMIT_RENDER_TEMPORARILY_UNAVAILABLE'
          || error?.code === 'PDD_ORDINARY_RESULT_STAGE_TEMPORARILY_UNAVAILABLE') throw error;
        await pauseForManualReview(
          targetPage,
          'pdd-resolution-submit',
          error.message,
        );
      }
      if (finalState.isPending && !finalState.isCompleted) {
        const currentSubmission = readProgress().pddResolutionSubmission || {};
        writeProgress({
          pddResolutionSubmission: {
            ...currentSubmission,
            status: 'submitting',
            retryCount: 1,
            lastRetryAt: new Date().toISOString(),
          },
          step: 'pdd-resolution-submit-recheck-waiting',
        });
        await waitForPddSubmitTransition(targetPage, 'resolution-recheck', async () => {
          if (!isPddDetailUrl(targetPage.url())) return true;
          const observed = await readPddResolutionState(
            targetPage,
            decision.orderNumber,
            { timeoutMs: 2_000 },
          ).catch(() => null);
          return Boolean(observed?.isCompleted || !observed?.isPending);
        });
        finalState = await readPddResolutionState(targetPage, decision.orderNumber);
        if (!finalState.isCompleted) {
          finalState = await confirmPddCompletionWithoutResubmit(
            targetPage,
            decision.orderNumber,
            finalState,
          );
        }
        if (!finalState.isCompleted) {
          const currentSubmission = readProgress().pddResolutionSubmission || {};
          const observation = buildPddSubmissionReconciliationObservation({
            pageState: finalState,
            orderNumber: decision.orderNumber,
            previousSubmission: currentSubmission,
          });
          writeProgress({
            pddResolutionSubmission: {
              ...currentSubmission,
              status: 'manual-review-blocked',
              retryCount: 1,
              blockedAt: observation.observedAt,
            },
            step: observation.state === 'not-applied'
              ? 'pdd-submit-not-applied'
              : 'external-state-unresolved',
            externalStateReconciliation: observation,
          });
          await pauseForManualReview(
            targetPage,
            'pdd-resolution-submit-confirmation',
            observation.state === 'not-applied'
              ? '已确认本次提交未生效，等待数据库完成幂等协调后仅重试一次'
              : observation.automaticRetryExhausted
                ? '拼多多两次提交均未生效，已禁止第三次提交'
                : '提交结果仍无法确认，禁止重复提交',
          );
        }
      }
      expectedCompletionOutcome = finalState.expectedOutcome
        || readProgress().pddResolutionSubmission?.outcome
        || expectedCompletionOutcome;
      if (finalState.isCompleted) {
        const platformCompletionObservation = await confirmLegacyResolutionCompletionDetail(
          targetPage, orderNumber, finalState,
        );
        if (pddCompletionOutcomeMismatchForProgress(
          readProgress(),
          expectedCompletionOutcome,
          finalState.completedOutcome,
          finalState.completedResultOption,
        )) {
          recordAcceptedPddTerminalOutcomeMismatch({
            progress: readProgress(),
            orderNumber,
            expectedOutcome: expectedCompletionOutcome,
            completedOutcome: finalState.completedOutcome,
            completedResultOption: finalState.completedResultOption,
            source: 'completed-after-submit',
          });
        }
        completion = {
          shopId,
          orderNumber,
          outcome: finalState.completedOutcome || expectedCompletionOutcome,
          status: 'succeeded',
          recoveredFromCompletedPage: finalState.recoveredFromCompletedPage === true,
          completionEvidence: finalState.completedOutcome,
          confirmationMethod: finalState.confirmationMethod || 'detail-completed',
          ...(platformCompletionObservation ? { platformCompletionObservation } : {}),
          completedAt: new Date().toISOString(),
        };
      } else {
        const absent = await confirmOrderAbsentFromPendingList(targetPage, orderNumber);
        if (!absent) {
          await pauseForManualReview(targetPage, 'pdd-resolution-submit', '提交后工单仍在待处理列表，禁止再次提交');
        }
        completion = {
          shopId,
          orderNumber,
          outcome: expectedCompletionOutcome,
          status: 'succeeded',
          recoveredFromCompletedPage: false,
          completionEvidence: null,
          confirmationMethod: 'absent-from-pending-list',
          completedAt: new Date().toISOString(),
        };
      }
    }
  }
  writeProgress({
    step: 'pdd-resolution-succeeded',
    pddResolutionSubmission: completion,
    currentUrl: targetPage.url(),
    error: null,
  });
  finalizeEvidenceAfterPddCompletion(orderNumber, completion);
  logRunStep('full-business-flow-complete', {
    orderNumber,
    pddResolutionSubmission: completion,
    currentUrl: targetPage.url(),
    error: null,
  });
  persistSystemTabs('pdd');
  if (targetPage !== pddPage && derivedPages.has(targetPage)) {
    await closeDerivedPage(targetPage);
    persistSystemTabs('pdd');
  }
  return completion;
};

const completedArchivePath = ({ orderNumber, platformCaseKey, detailUrl }) => {
  const platformWorkOrderId = String(platformCaseKey || '').match(/^pdd-work-order:(\d{6,30})$/)?.[1]
    || parsePlatformWorkOrderId(detailUrl);
  if (platformWorkOrderId) return path.join(completedWorkOrdersDir, `pdd-work-order-${platformWorkOrderId}.json`);
  const legacyFingerprint = crypto.createHash('sha256')
    .update(`${orderNumber || 'unknown'}:${detailUrl || 'no-detail-url'}`)
    .digest('hex').slice(0, 16);
  return path.join(completedWorkOrdersDir, `legacy-${orderNumber || 'unknown'}-${legacyFingerprint}.json`);
};

const archivedPlatformCaseKeys = () => new Set(
  fs.readdirSync(completedWorkOrdersDir, { withFileTypes: true })
    .filter((entry) => entry.isFile() && entry.name.endsWith('.json'))
    .map((entry) => {
      try {
        const archive = JSON.parse(fs.readFileSync(path.join(completedWorkOrdersDir, entry.name), 'utf8'));
        return archive.completionArchive?.platformCaseKey || archive.platformCaseKey || null;
      } catch {
        return null;
      }
    })
    .filter(Boolean),
);

const archiveAndResetCompletedOrder = async (completion) => {
  const progress = readProgress();
  const readiness = archiveReadiness(progress, completion);
  if (!readiness.ready) throw new Error(`当前订单禁止归档和清空进度: ${readiness.reason}`);
  await persistBrowserAuth(context);
  const platformIdentity = {
    platformWorkOrderId: progress.platformWorkOrderId || completion.platformWorkOrderId || null,
    platformCaseKey: progress.platformCaseKey || completion.platformCaseKey || null,
  };
  const archivePath = completedArchivePath({
    orderNumber: completion.orderNumber,
    platformCaseKey: platformIdentity.platformCaseKey,
    detailUrl: progress.detailUrl,
  });
  const archivedAt = new Date().toISOString();
  const archive = {
    ...progress,
    completionArchive: {
      shopId,
      orderNumber: completion.orderNumber,
      ...platformIdentity,
      outcome: completion.outcome,
      confirmationMethod: completion.confirmationMethod,
      recoveredFromCompletedPage: completion.recoveredFromCompletedPage === true,
      completedAt: completion.completedAt,
      archivedAt,
    },
  };
  if (exists(archivePath)) {
    const existing = JSON.parse(fs.readFileSync(archivePath, 'utf8'));
    if (existing.completionArchive?.orderNumber !== completion.orderNumber
      || existing.completionArchive?.platformCaseKey !== platformIdentity.platformCaseKey
      || existing.completionArchive?.outcome !== completion.outcome) {
      throw new Error(`已存在冲突的完成归档: ${completion.orderNumber}`);
    }
  } else {
    writeJsonAtomic(archivePath, archive);
  }
  const completedCount = fs.readdirSync(completedWorkOrdersDir, { withFileTypes: true })
    .filter((entry) => entry.isFile() && entry.name.endsWith('.json')).length;
  const nextProgress = nextProgressAfterCompletion({
    progress,
    completion,
    targetWorkOrderTitle,
    browserMode,
    workflowDataDir,
    completedCount,
    archivedAt,
  });
  replaceProgress(nextProgress);
  await closeCompletedPddDetailTabs();
  return nextProgress.lastCompletedOrder;
};

const resetCurrentOrderForRerun = () => {
  const progress = readProgress();
  // Persist the applied order number as the guard. A worker restart must not
  // delete/rebuild the same order's evidence a second time.
  if (!rerunCurrentOrder || !progress.orderNumber
    || currentOrderRerunApplied === progress.orderNumber
    || (!forceRerunCurrentOrder
      && progress.rerunCurrentOrder?.orderNumber === progress.orderNumber
      && progress.rerunCurrentOrder?.parserVersion >= logisticsAnalysisVersion)) return false;
  const orderNumber = progress.orderNumber;
  const oldEvidence = progress.pddEvidenceScreenshot;
  if (oldEvidence?.status === 'ready' && oldEvidence.relativePath) {
    const oldPath = path.resolve(workflowDataDir, ...oldEvidence.relativePath.split('/'));
    if (isPathInside(evidenceScreenshotDir, oldPath) && exists(oldPath)) fs.unlinkSync(oldPath);
  }
  writeProgress({
    rerunCurrentOrder: {
      orderNumber,
      appliedAt: new Date().toISOString(),
      parserVersion: logisticsAnalysisVersion,
      mode: 'reload-pdd-logistics-and-reuse-or-create-tms',
    },
    pddEvidenceScreenshot: null,
    logisticsAnalysis: null,
    omsAnalysis: null,
    omsManualAllocation: null,
    omsGridCells: null,
    omsMarkText: null,
    isLowValue: null,
    isReissueOrder: null,
    tmsRoutingDecision: null,
    tmsFormDecision: null,
    tmsAutofillVerification: null,
    tmsAttachmentTransfer: null,
    tmsEvidenceScreenshot: null,
    tmsEvidenceDisposition: null,
    tmsBypass: null,
    pddResolutionDecision: null,
    pddResolutionSubmission: null,
    pddResolutionRecovery: null,
    manualReview: null,
    error: null,
    step: 'rerun-current-order-reset',
  });
  console.log(`受控重跑已清理订单级旧分析，保留详情地址并重新读取: ${orderNumber}`);
  currentOrderRerunApplied = orderNumber;
  return true;
};

const findNextPendingWorkOrder = async (
  targetPage,
  skippedSelectionKeys = new Set(),
  { refresh = true, pageNumber = 1 } = {},
) => {
  await ensurePddLogin(targetPage, context, listUrl);
  const submitUnfilteredListQuery = async (page, stageSuffix = '') => {
    const orderInput = page.getByPlaceholder('请输入订单编号', { exact: true });
    if (!await orderInput.count().catch(() => 0)) return;
    await pacedAction(page, `clear-order-query${stageSuffix}`, () => orderInput.fill(''));
    const filter = await ensurePddPendingListFilter(page, { beforeAction: checkForHumanVerification });
    logRunStep('ordinary-pending-filter-confirmed', filter);
    await pacedAction(
      page,
      `refresh-pending-work-orders${stageSuffix}`,
      () => page.getByRole('button', { name: '查询', exact: true }).click(),
      { retryOnRateLimit: true },
    );
  };
  if (refresh) {
    await submitUnfilteredListQuery(targetPage);
  }
  await waitForOrdinaryListRenderState(targetPage, {
    stage: `普通工单第${pageNumber}页渲染`,
    onRefresh: refresh
      ? (page) => submitUnfilteredListQuery(page, '-after-render-timeout')
      : null,
  });
  const candidates = [];
  const candidateKeys = new Set();
  for (const titleText of configuredWorkOrderTitles()) {
    // PDD often adds the prefix "订单问题：" and the suffix "处理". Exact
    // text matching therefore skipped valid "已发货无轨迹退款处理" rows even
    // though the scenario matcher could identify them. Collect exact and
    // contains matches, then let the row/action locator perform the unique
    // control check.
    const matchLocators = [
      targetPage.getByText(titleText, { exact: true }),
      targetPage.getByText(new RegExp(escapeRegex(titleText))),
    ];
    for (const matches of matchLocators) {
      for (let index = 0; index < await matches.count().catch(() => 0); index++) {
        const candidate = matches.nth(index);
        const key = `${titleText}:${index}`;
        if (candidateKeys.has(key)) continue;
        candidateKeys.add(key);
        candidates.push(candidate);
      }
    }
  }
  const seenRowFingerprints = new Set();
  const scenarioCandidateCounts = new Map();
  const stableCandidateCounts = new Map();
  for (const title of candidates) {
    if (!await title.isVisible().catch(() => false)) continue;
    let action;
    try {
      action = await locateWorkOrderAction(title);
    } catch {
      continue;
    }
    const row = title.locator('xpath=ancestor::*[@data-codex-pdd-work-order-row="true"][1]');
    if (!await row.count().catch(() => 0) || !action) continue;
    const rowText = await row.innerText().catch(() => '');
    const discoveredTitle = configuredWorkOrderTitles().find((candidate) => rowText.includes(candidate))
      || await title.innerText().catch(() => targetWorkOrderTitle);
    const scenario = matchingScenarioForTitle(discoveredTitle);
    if (!scenario) continue;
    const rowFingerprint = logisticsRowFingerprint(rowText, discoveredTitle);
    if (seenRowFingerprints.has(rowFingerprint)) continue;
    seenRowFingerprints.add(rowFingerprint);
    const scenarioCandidateNumber = scenarioCandidateCounts.get(scenario.code) || 0;
    scenarioCandidateCounts.set(scenario.code, scenarioCandidateNumber + 1);
    const rowOrderNumber = parseOrderNumber(rowText);
    const workOrderCreatedAt = extractOrdinaryListCreatedAt(rowText);
    const stableCandidateIdentity = rowOrderNumber
      ? `${scenario.code}\n${rowOrderNumber}\n${workOrderCreatedAt || ''}`
      : null;
    const duplicateNumber = stableCandidateIdentity
      ? (stableCandidateCounts.get(stableCandidateIdentity) || 0)
      : 0;
    if (stableCandidateIdentity) {
      stableCandidateCounts.set(stableCandidateIdentity, duplicateNumber + 1);
    }
    const discoveryKey = buildDiscoverySelectionKey({
      pageNumber,
      scenarioCode: scenario.code,
      rowOrderNumber,
      workOrderCreatedAt,
      scenarioCandidateNumber,
      duplicateNumber,
    });
    if (skippedSelectionKeys.has(discoveryKey)) continue;
    if (skippedSelectionKeys.has(rowFingerprint)) continue;
    if (!isLogisticsRetryDue(rowOrderNumber, rowFingerprint)) continue;
    return {
      title,
      row,
      action,
      rowOrderNumber,
      workOrderCreatedAt,
      workOrderType: discoveredTitle,
      scenarioCode: scenario.code,
      discoveryKey,
      rowFingerprint,
    };
  }
  return null;
};

const ordinaryListPageSignature = async (targetPage) => targetPage
  .getByText('立即处理', { exact: true })
  .evaluateAll((elements) => elements.slice(0, 8).map((element) => {
    let cursor = element;
    for (let depth = 0; cursor && depth < 12; depth += 1, cursor = cursor.parentElement) {
      const text = String(cursor.innerText || cursor.textContent || '').replace(/\s+/g, ' ').trim();
      const orderNumber = text.match(/\b\d{6}-\d{12,}\b/u)?.[0];
      if (orderNumber) return orderNumber;
    }
    return String(element.parentElement?.innerText || element.textContent || '')
      .replace(/\s+/g, ' ').trim();
  }).join('|'))
  .catch(() => '');

const findNextOrdinaryListPageAction = async (targetPage) => {
  const candidates = [
    targetPage.getByRole('button', { name: /下一页/u }),
    targetPage.locator([
      '[aria-label="下一页"]',
      '[title="下一页"]',
      '[data-testid*="pagination-next"]',
      '[class*="pagination"] [class*="next"]',
      '[class*="Pagination"] [class*="next"]',
    ].join(', ')),
  ];
  for (const locator of candidates) {
    const count = await locator.count().catch(() => 0);
    for (let index = 0; index < count; index++) {
      const candidate = locator.nth(index);
      if (!await candidate.isVisible().catch(() => false)) continue;
      if (!await candidate.isEnabled().catch(() => true)) continue;
      const ariaDisabled = await candidate.getAttribute('aria-disabled').catch(() => null);
      const disabled = await candidate.getAttribute('disabled').catch(() => null);
      const className = await candidate.getAttribute('class').catch(() => '');
      if (ariaDisabled === 'true' || disabled != null
        || /(?:^|[-_\s])disabled(?:$|[-_\s])/iu.test(className || '')) continue;
      return candidate;
    }
  }
  return null;
};

const findNextPendingWorkOrderAcrossPages = async (
  targetPage,
  skippedSelectionKeys = new Set(),
  { maxPages = 100 } = {},
) => {
  for (let pageNumber = 1; pageNumber <= maxPages; pageNumber++) {
    const selection = await findNextPendingWorkOrder(
      targetPage,
      skippedSelectionKeys,
      { refresh: pageNumber === 1, pageNumber },
    );
    if (selection) return selection;
    const nextPage = await findNextOrdinaryListPageAction(targetPage);
    if (!nextPage) return null;
    const before = await ordinaryListPageSignature(targetPage);
    await pacedAction(targetPage, 'ordinary-list-next-page', () => nextPage.click({ force: true }), {
      retryOnRateLimit: true,
    });
    await waitForOrdinaryListRenderState(targetPage, {
      stage: `普通工单第${pageNumber + 1}页渲染`,
      previousSignature: before || null,
    });
  }
  throw new Error(`拼多多普通工单列表超过 ${maxPages} 页，已停止本轮扫描以避免遗漏或无限循环`);
};

const waitForOpenedPddWorkOrder = async (detailPage, {
  stage,
  expectedOrderNumber = null,
} = {}) => waitForPddRenderedResult(detailPage, {
  stage,
  timeoutMs: pddRenderWaitMs,
  onVerification: (page, verificationStage) => checkForHumanVerification(page, verificationStage),
  beforeReload: (page) => clickVisiblePddStalePageRefresh(page, {
    cooldownMs: 0,
    settleMs: 700,
  }),
  inspect: async (page) => {
    if (await hasVisiblePddLoadingState(page)) return null;
    const body = await page.locator('body').innerText({ timeout: 2_000 }).catch(() => '');
    const orderNumber = parsePddOrderNumber(body);
    if (expectedOrderNumber && orderNumber && orderNumber !== expectedOrderNumber) {
      throw new Error(`PDD detail order mismatch: expected ${expectedOrderNumber}, observed ${orderNumber}`);
    }
    const meaningfulDetail = orderNumber || (
      body.length >= 80
      && /\u5de5\u5355\u8be6\u60c5|\u8ba2\u5355\u4fe1\u606f|\u5904\u7406\u7ed3\u679c/u.test(body)
    );
    return meaningfulDetail ? {
      orderNumber: orderNumber || expectedOrderNumber || null,
      detailWorkOrderType: extractPddDetailWorkOrderType(body),
    } : null;
  },
  onRefresh: async (page) => {
    await ensurePddLogin(page, context, page.url());
    await closeDeviceAccessIfPrompted(page);
  },
});

const openPendingWorkOrder = async (selection) => {
  const openedPage = await openPddDetailWithoutForegroundPopup(
    pddPage,
    selection.action,
    'open-work-order',
    { retryOnRateLimit: true },
  );
  let detailPage = openedPage ? await adoptPddDetailPage(openedPage) : pddPage;
  if (!detailPage.url().includes('/aftersales/work_order/tododetail')) {
    await detailPage.waitForURL('**/aftersales/work_order/tododetail**', { timeout: 30000 });
  }
  if (detailPage === pddPage) detailPage = await adoptPddDetailPage(pddPage);
  await detailPage.waitForLoadState('domcontentloaded');
  const renderedDetail = await waitForOpenedPddWorkOrder(detailPage, {
    stage: 'ordinary-work-order-detail-render',
    expectedOrderNumber: selection.rowOrderNumber || null,
  });
  const detailWorkOrderType = renderedDetail.detailWorkOrderType;
  const detailScenario = matchingScenarioForTitle(detailWorkOrderType);
  const detailTypeMismatch = Boolean(detailWorkOrderType
    && !ordinaryWorkOrderTypesEquivalent(selection.workOrderType, detailWorkOrderType));
  if (detailTypeMismatch && !detailScenario) {
    assertPddDetailWorkOrderType({
      workOrderType: selection.workOrderType,
      detailWorkOrderType,
      isExpectedWorkOrderType: false,
    });
  }
  const resolvedWorkOrderType = detailTypeMismatch
    ? detailWorkOrderType : selection.workOrderType || targetWorkOrderTitle;
  const resolvedScenarioCode = detailTypeMismatch
    ? detailScenario.code
    : selection.scenarioCode || matchingScenarioForTitle(selection.workOrderType)?.code || null;
  await persistBrowserAuth(context);
  writeProgress({
    detailUrl: detailPage.url(),
    workOrderType: resolvedWorkOrderType,
    scenarioCode: resolvedScenarioCode,
    ...(detailTypeMismatch ? {
      pddDetailIdentityCorrection: {
        listWorkOrderType: selection.workOrderType || null,
        listScenarioCode: selection.scenarioCode || null,
        detailWorkOrderType,
        detailScenarioCode: detailScenario.code,
        correctedAt: new Date().toISOString(),
      },
    } : {}),
    rowFingerprint: selection.rowFingerprint || null,
    workOrderCreatedAt: selection.workOrderCreatedAt || null,
    step: 'work-order-opened',
    loopState: {
      ...(readProgress().loopState || {}),
      status: 'processing',
      currentOrderNumber: selection.rowOrderNumber || null,
      nextPollAt: null,
    },
  });
  logRunStep('target-work-order-opened', { detailUrl: detailPage.url() });
  return detailPage;
};

const finishCurrentRun = async ({ failed = false } = {}) => {
  // Keep the visible browser for deliberate human-review/verification pauses.
  // A real worker failure must instead close cleanly so run-shops can restart
  // the child and resume from the progress checkpoint.
  if (browserKeepsAlive && !failed) {
    await new Promise(() => {});
    return;
  }
  workflowStopping = true;
  clearInterval(checkpointTimer);
  clearInterval(healthTimer);
  await persistBrowserAuth(context).catch(() => {});
  await browser.close().catch(() => {});
  await markChromiumProfileClean();
  releaseWorkflowLock();
  if (failed) process.exitCode = 1;
};

const finishDiscoveryRun = async () => {
  workflowStopping = true;
  clearInterval(checkpointTimer);
  clearInterval(healthTimer);
  await persistBrowserAuth(context).catch(() => {});
  await browser.close().catch(() => {});
  await markChromiumProfileClean();
  releaseOmsSessionLock();
  releaseWorkflowLock();
};

const discoverNextPlatformWorkOrder = async ({ maxCandidates = 100 } = {}) => {
  const skippedSelectionKeys = new Set();
  const archivedKeys = archivedPlatformCaseKeys();
  const excludedKeys = new Set([...archivedKeys, ...discoveryExcludedPlatformCaseKeys]);
  for (let candidateNumber = 1; candidateNumber <= maxCandidates; candidateNumber += 1) {
    const selection = await findNextPendingWorkOrderAcrossPages(pddPage, skippedSelectionKeys);
    if (!selection) return null;
    const rowFingerprint = String(selection.rowFingerprint || '').trim();
    const discoveryKey = String(selection.discoveryKey || rowFingerprint || '').trim();
    const knownListCandidate = findKnownOrdinaryDiscoveryExclusion(
      selection,
      discoveryExcludedOrdinaryCandidates,
    );
    if (knownListCandidate && excludedKeys.has(knownListCandidate.platformCaseKey)) {
      const skippedKeys = rememberDiscoverySelection(skippedSelectionKeys, selection);
      console.log(JSON.stringify({
        status: 'discovery-skipped',
        shopId,
        orderNumber: selection.rowOrderNumber,
        platformCaseKey: knownListCandidate.platformCaseKey,
        discoveryKey: discoveryKey || null,
        rowFingerprint: selection.rowFingerprint || null,
        workOrderCreatedAt: selection.workOrderCreatedAt || null,
        skippedKeys,
        reason: 'excluded-known-list-candidate',
      }));
      if (!skippedKeys.length) return null;
      continue;
    }
    const openedPage = await openPddDetailWithoutForegroundPopup(
      pddPage,
      selection.action,
      'open-discovery-work-order',
      { retryOnRateLimit: true },
    );
    const detail = openedPage ? await adoptPddDetailPage(openedPage) : pddPage;
    await detail.waitForLoadState('domcontentloaded').catch(() => {});
    const renderedDetail = await waitForOpenedPddWorkOrder(detail, {
      stage: 'ordinary-work-order-discovery-detail-render',
      expectedOrderNumber: selection.rowOrderNumber || null,
    });
    const body = await detail.locator('body').innerText().catch(() => '');
    const detailUrl = detail.url();
    const platformIdentity = ordinaryIdentityFromDetailUrl(detailUrl);
    const orderNumber = renderedDetail.orderNumber || parsePddOrderNumber(body) || selection.rowOrderNumber || null;
    const detailWorkOrderType = renderedDetail.detailWorkOrderType
      || extractPddDetailWorkOrderType(body);
    const detailScenario = matchingScenarioForTitle(detailWorkOrderType);
    const detailTypeMismatch = Boolean(detailWorkOrderType
      && !ordinaryWorkOrderTypesEquivalent(selection.workOrderType, detailWorkOrderType));
    if (detail !== pddPage) await detail.close().catch(() => {});
      await pacedAction(pddPage, 'return-from-discovery-detail', () => navigateSystemPage(
        pddPage,
        listUrl,
        'return-from-discovery-detail',
      ));
    if (!orderNumber || !platformIdentity.platformWorkOrderId || !platformIdentity.platformCaseKey) {
      const skippedKeys = rememberDiscoverySelection(skippedSelectionKeys, selection);
      console.log(JSON.stringify({
        status: 'discovery-skipped',
        shopId,
        orderNumber,
        platformCaseKey: platformIdentity.platformCaseKey,
        discoveryKey: discoveryKey || null,
        rowFingerprint: selection.rowFingerprint || null,
        skippedKeys,
        reason: orderNumber
          ? 'platform-work-order-identity-unavailable'
          : 'order-number-unavailable',
        detailUrl: detailUrl || null,
      }));
      if (!skippedKeys.length) return null;
      continue;
    }
    if (detailTypeMismatch && !detailScenario) {
      excludedKeys.add(platformIdentity.platformCaseKey);
      const skippedKeys = rememberDiscoverySelection(skippedSelectionKeys, selection);
      console.log(JSON.stringify({
        status: 'discovery-skipped',
        shopId,
        orderNumber,
        platformCaseKey: platformIdentity.platformCaseKey,
        discoveryKey: discoveryKey || null,
        rowFingerprint: selection.rowFingerprint || null,
        skippedKeys,
        reason: 'unsupported-detail-work-order-type',
        listWorkOrderType: selection.workOrderType || null,
        listScenarioCode: selection.scenarioCode || null,
        detailWorkOrderType,
        detailUrl: detailUrl || null,
      }));
      if (!skippedKeys.length) return null;
      continue;
    }
    if (platformIdentity.platformCaseKey && excludedKeys.has(platformIdentity.platformCaseKey)) {
      const skippedKeys = rememberDiscoverySelection(skippedSelectionKeys, selection);
      console.log(JSON.stringify({
        status: 'discovery-skipped',
        shopId,
        orderNumber,
        platformCaseKey: platformIdentity.platformCaseKey,
        discoveryKey: discoveryKey || null,
        rowFingerprint: selection.rowFingerprint || null,
        workOrderCreatedAt: selection.workOrderCreatedAt || null,
        knownListCandidateKey: knownListCandidate?.platformCaseKey || null,
        knownListCandidateFirstDiscoveredAt: knownListCandidate?.firstDiscoveredAt || null,
        excludedOrdinaryCandidateCount: discoveryExcludedOrdinaryCandidates.length,
        excludedPlatformCaseCount: excludedKeys.size,
        skippedKeys,
        reason: 'excluded-platform-work-order-instance',
      }));
      if (!skippedKeys.length) return null;
      continue;
    }
    const resolvedSelection = detailTypeMismatch ? {
      ...selection,
      workOrderType: detailWorkOrderType,
      scenarioCode: detailScenario.code,
      detailIdentityCorrection: {
        listWorkOrderType: selection.workOrderType || null,
        listScenarioCode: selection.scenarioCode || null,
        detailWorkOrderType,
        detailScenarioCode: detailScenario.code,
      },
    } : selection;
    return {
      selection: resolvedSelection,
      orderNumber,
      detailUrl,
      ...platformIdentity,
    };
  }
  return null;
};

const writePddDiscoveryOutput = (payload) => {
  const outputFile = process.env.PDD_DISCOVERY_FILE;
  if (!outputFile) return;
  writeJsonAtomic(path.resolve(outputFile), payload);
};

const runPddDiscoveryOnly = async () => {
  await focusSystemPage('pdd', pddPage);
  await pacedAction(pddPage, 'open-pinduoduo-discovery', () => navigateSystemPage(
    pddPage,
    listUrl,
    'open-pinduoduo-discovery',
  ));
  await closeDeviceAccessIfPrompted(pddPage);
  await ensurePddLogin(pddPage, context, listUrl);
  const discovery = await discoverNextPlatformWorkOrder();
  const selection = discovery?.selection || null;
  const requestId = residentCommandMode
    ? readProgress().residentCommand?.requestId || null
    : null;
  const result = discovery?.orderNumber
    ? {
      requestId,
      status: 'discovered',
      shopId,
      orderNumber: discovery.orderNumber,
      workOrderType: selection.workOrderType || targetWorkOrderTitle,
      scenarioCode: selection.scenarioCode || null,
      detailUrl: discovery.detailUrl,
      platformWorkOrderId: discovery.platformWorkOrderId || null,
      platformCaseKey: discovery.platformCaseKey || null,
      identityStatus: discovery.identityStatus,
      detailIdentityCorrection: selection.detailIdentityCorrection || null,
      workOrderCreatedAt: selection.workOrderCreatedAt || null,
      discoveredAt: new Date().toISOString(),
    }
    : { requestId, status: 'queue-empty', shopId, discoveredAt: new Date().toISOString() };
  writePddDiscoveryOutput(result);
  console.log(JSON.stringify({ status: result.status, shopId, orderNumber: result.orderNumber || null }));
  return result;
};

// Read-only side channel: shortage observation never enters the paused legacy
// OMS/TMS flow and never creates an ordinary completion or notification event.
let reusableChatPage = null;
let reusableChatDetailPage = null;
const runChatCollectionOnly = async () => {
  const { collectConversation, orderDate } = await import('./packages/adapters/src/chat-analysis/collector.mjs');
  const command = chatCollectionCommand || {};
  const requestId = command.requestId;
  try {
    chatDiscoveryActive = true;
    const discovered = command.target ? { ...command.target, status: 'discovered', shopId }
      : await runPddDiscoveryOnly();
    if (discovered.status !== 'discovered') { writePddDiscoveryOutput({ ...discovered, requestId, status: 'chat-empty' }); return; }
    const scenarioCode = String(discovered.scenarioCode || command.target?.scenarioCode || '').trim();
    const chatPolicy = chatPolicyForScenario(scenarioCode);
    if (!chatPolicy) {
      writePddDiscoveryOutput({ ...discovered, requestId, status: 'chat-unsupported', scenarioCode });
      return;
    }
    if (!discovered.orderNumber || !discovered.platformCaseKey || !discovered.platformWorkOrderId
      || new URL(discovered.detailUrl).origin !== 'https://mms.pinduoduo.com') throw new Error('CHAT_CASE_IDENTITY_MISSING');
    if (!reusableChatDetailPage || reusableChatDetailPage.isClosed()) reusableChatDetailPage = await createBackgroundPage();
    const detail = reusableChatDetailPage;
    await pacedAction(detail, 'chat-order-detail', () => navigateSystemPage(
      detail,
      discovered.detailUrl,
      'chat-order-detail',
    ));
    await ensurePddLogin(detail, context, discovered.detailUrl);
    await waitForOpenedPddWorkOrder(detail, { expectedOrderNumber: discovered.orderNumber, stage: 'chat-order-identity' });
    const body = await detail.locator('body').innerText();
    const detailWorkOrderType = extractPddDetailWorkOrderType(body);
    if (parsePddOrderNumber(body) !== discovered.orderNumber
      || (discovered.workOrderType && !ordinaryWorkOrderTypesEquivalent(discovered.workOrderType, detailWorkOrderType))
      || ordinaryIdentityFromDetailUrl(detail.url()).platformCaseKey !== discovered.platformCaseKey) throw new Error('CHAT_ORDER_IDENTITY_MISMATCH');
    const orderInfoStart = body.indexOf('订单信息');
    const orderDetailText = orderInfoStart >= 0 ? body.slice(orderInfoStart).split(/收货信息|物流轨迹/)[0].trim() : '';
    const orderFacts = { orderNumber: discovered.orderNumber, orderDate: orderDate(discovered.orderNumber), orderDetailText };
    if (!reusableChatPage || reusableChatPage.isClosed()) reusableChatPage = await createBackgroundPage();
    const collection = await collectConversation({ page: reusableChatPage, shopId, orderNumber: discovered.orderNumber,
      expectedShopName,
      platformCaseKey: discovered.platformCaseKey, scenarioCode, workOrderType: discovered.workOrderType || detailWorkOrderType, orderFacts,
      beforeAction: async (page, stage) => { await checkForHumanVerification(page, stage); await ensurePddLogin(page, context, page.url()); },
      onProgress: async (stage) => writeProgress({ chatCollection: { orderNumber: discovered.orderNumber, stage, updatedAt: new Date().toISOString() } }) });
    writePddDiscoveryOutput({ ...discovered, requestId, status: 'chat-collected', scenarioCode,
      workOrderType: discovered.workOrderType || detailWorkOrderType, ...collection });
  } finally { chatDiscoveryActive = false; }
};

const writeReturnRefundOutput = (payload) => {
  writeJsonAtomic(returnRefundOutputPath, payload);
};

const returnRefundVisibleStep = async (stage, metadata = {}) => {
  logRunStep(stage, {
    orderNumber: requestedOrderNumber,
    scenarioCode: 'return-refund',
    aftersaleNumber: activeReturnRefundCommand?.aftersaleNumber || null,
    ...metadata,
  });
};

let returnRefundScanPage = null;
let returnRefundScanResumeProof = null;
let returnRefundResumeTimeDiagnosticSaved = false;
const closeOrdinaryLogisticsDerivedPages = async () => {
  for (const page of [...derivedPages]) {
    if (page.isClosed()) continue;
    let retainedScanList = false;
    if (residentCommandMode && !activeReturnRefundCommand
      && page === returnRefundScanPage && page !== pddPage
      && derivedPageMeta.get(page)?.purpose === 'return-refund-scan-list'
      && returnRefundScanResumeProof
      && (Number(returnRefundScanResumeProof.nextCursor?.page || 1) > 1
        || Number(returnRefundScanResumeProof.nextCursor?.itemOffset || 0) > 0)) {
      try {
        const url = new URL(page.url());
        retainedScanList = url.origin === 'https://mms.pinduoduo.com'
          && url.pathname === '/aftersales/aftersale_list'
          && crypto.createHash('sha256').update(page.url()).digest('hex')
            === returnRefundScanResumeProof.urlSha256;
      } catch { /* Unrecognized pages keep the existing cleanup behavior. */ }
    }
    // Ordinary logistics waiting does not finish the separate refund scan.
    // The collector still revalidates the rows, page, age, and cursor on reuse.
    if (retainedScanList) {
      console.log(`[return-refund-scan-list-retained] ${shopId} ${JSON.stringify({
        reason: 'ordinary-logistics-wait', cursor: returnRefundScanResumeProof.nextCursor,
      })}`);
      continue;
    }
    await closeDerivedPage(page);
  }
};

const runReturnRefundScanOnly = async () => {
  const command = activeReturnRefundCommand || {};
  let verificationHandledCount = 0;
  await focusSystemPage('pdd', pddPage);
  await ensurePddLogin(pddPage, context, pddPage.url().includes('mms.pinduoduo.com') ? pddPage.url() : listUrl);
  // Keep a verified list tab for any partial scan, including page one. The
  // ordinary work-order tab may navigate away between batches; reopening the
  // refund workbench for every page-one batch repeats list requests and clicks.
  const resumableCursor = Number(command.scanCursor?.page || 1) > 1
    || Number(command.scanCursor?.itemOffset || 0) > 0;
  let scanPage = pddPage;
  if (resumableCursor) {
    // Login recovery can promote the retained refund list into the permanent
    // PDD anchor. Give scanning its own page again before ordinary navigation
    // can move that anchor away; a new page must not reuse the old row proof.
    if (!returnRefundScanPage || returnRefundScanPage.isClosed()
      || returnRefundScanPage === pddPage) {
      returnRefundScanPage = registerDerivedPage(
        await createBackgroundPage(), 'return-refund-scan-list',
      );
      returnRefundScanResumeProof = null;
    }
    scanPage = returnRefundScanPage;
    if (scanPage.url() === 'about:blank') {
      await navigateSystemPage(scanPage, RETURN_REFUND_WORKBENCH_URL, 'return-refund-scan-list-open');
    }
    await focusSystemPage('pdd', scanPage);
  } else {
    returnRefundScanResumeProof = null;
  }
  let collection;
  try {
    collection = await collectReturnRefundCandidates(scanPage, context, {
      maxItems: command.maxItems || 10,
      maxKnownSkippedItems: command.maxKnownSkippedItems || 0,
      maxDurationMs: command.maxDurationMs || 120_000,
      scanCursor: command.scanCursor,
      deferredRefunds: command.deferredRefunds || [],
      completedRefunds: command.completedRefunds || [],
      resumeProof: resumableCursor ? returnRefundScanResumeProof : null,
      protectedPages: [pddPage, omsPage, tmsPage],
      createBackgroundDetailPage: async () => registerDerivedPage(
        await createBackgroundPage(), 'return-refund-scan-detail',
      ),
      renderWaitMs: pddRenderWaitMs,
      delayMs: Math.max(700, Number(process.env.RETURN_REFUND_VISIBLE_STEP_DELAY_MS || 1200)),
      onStep: async (stage, metadata = {}) => {
        await returnRefundVisibleStep(stage, metadata);
        // Keep one real list-page sample when time text alone prevented reuse.
        // This is diagnostic only: the collector must still reject the proof.
        if (!returnRefundResumeTimeDiagnosticSaved
          && stage === 'return-refund-resume-rejected'
          && metadata.reason === 'proof-mismatch'
          && metadata.sameUrl === true && metadata.sameCursor === true
          && metadata.previousPage === metadata.observedPage
          && metadata.previousRowCount === metadata.observedRowCount
          && metadata.rowTextComparison?.sameOrderSequence === true
          && metadata.rowTextComparison?.sameRowsWithoutTimeTokens === true) {
          returnRefundResumeTimeDiagnosticSaved = true;
          await saveWorkflowDiagnostics(
            scanPage,
            'return-refund-resume-time-text-mismatch',
          ).catch(() => {});
        }
      },
      onVerification: async (targetPage, stage) => {
        const handled = await checkForHumanVerification(targetPage, stage);
        if (handled) verificationHandledCount += 1;
        return handled;
      },
    });
  } catch (error) {
    // A slider can interrupt a detail opened from a deep list page. Keep a
    // proof of that still-open list page so the same Worker can resume at its
    // durable cursor after verification, without replaying all prior pages.
    // The collector rechecks URL, page, rows, and cursor before using it.
    if (resumableCursor && error instanceof HumanVerificationRequiredError) {
      const proof = await readReturnRefundScanResumeProof(scanPage, command.scanCursor)
        .catch(() => null);
      if (proof?.page === Number(command.scanCursor.page)) {
        returnRefundScanResumeProof = proof;
        logRunStep('return-refund-resume-proof-retained-after-verification', {
          page: proof.page,
          itemOffset: proof.nextCursor.itemOffset,
          rowCount: proof.rowCount,
        });
      }
    }
    throw error;
  }
  const scan = { ...collection.scan, verificationHandledCount };
  returnRefundScanResumeProof = resumableCursor ? collection.scan?.resumeProof || null : null;
  if (returnRefundScanPage && !returnRefundScanPage.isClosed()
    && collection.scan?.nextCursor?.page === 1
    && collection.scan?.nextCursor?.itemOffset === 0) {
    await closeDerivedPage(returnRefundScanPage);
    returnRefundScanPage = null;
    returnRefundScanResumeProof = null;
  }
  const items = collection.items.map((item) => ({
    ...item,
    decision: evaluateReturnRefundRules(item),
  }));
  const result = {
    requestId: command.requestId || null,
    mode: 'scan',
    status: 'completed',
    shopId,
    items,
    scan,
    scannedAt: new Date().toISOString(),
  };
  writeReturnRefundOutput(result);
  logRunStep('return-refund-scan-complete', {
    itemCount: items.length,
    scan,
    error: null,
  });
  return result;
};

const residentCommandFailureStatus = (error) => {
  if (error instanceof HumanVerificationTimeoutError
    || error?.code === 'HUMAN_VERIFICATION_TIMEOUT') return 'verification-timeout';
  if (error instanceof HumanVerificationRequiredError) return 'verification-required';
  if (error instanceof PddLoginRequiredError || error?.code === 'PDD_LOGIN_REQUIRED') return 'login-required';
  if (error instanceof RateLimitPauseError) return 'rate-limited';
  return 'retryable-error';
};

const resetPddAfterResidentDiscoveryFailure = async (failure) => {
  if (workflowStopping || browserFailureExiting) return false;
  if (!browser.isConnected()) {
    exitForBrowserFailure('resident-discovery-reset-context-unavailable', failure);
    return false;
  }
  try {
    for (const page of [...derivedPages]) {
      if (!page.isClosed()) await closeDerivedPage(page).catch(() => {});
    }
    if (pddPage.isClosed()) {
      pddPage = monitorSystemPage('pdd', await createBackgroundPage());
      crashedSystems.delete('pdd');
    }
    if (!pddPage.isClosed() && !pddPage.url().includes('/aftersales/work_order/list')) {
      await navigateSystemPage(pddPage, listUrl, 'resident-discovery-reset').catch(() => {});
    }
    if (!pddPage.isClosed() && !await hasHumanVerification(pddPage).catch(() => true)) {
      const progress = readProgress();
      const authHealth = { ...(progress.authHealth || {}) };
      authHealth.pdd = mergeSystemAuthHealth(authHealth.pdd, {
        status: 'unknown',
        stage: null,
        url: pddPage.url(),
        checkedAt: new Date().toISOString(),
        confidence: 'weak',
        source: 'resident-discovery-reset',
        evidence: 'post-failure-list-url-only',
      });
      writeProgress({
        step: 'resident-discovery-reset',
        verificationStage: null,
        verificationLocation: null,
        verificationFocus: null,
        verificationRecheck: {
          trigger: 'resident-command-restart',
          status: 'cleared',
          completedAt: new Date().toISOString(),
        },
        authHealth,
        manualReview: null,
        currentUrl: pddPage.url(),
        error: null,
      });
    }
    persistSystemTabs('pdd');
    return true;
  } catch (error) {
    if (workflowStopping || browserFailureExiting) return false;
    if (!browser.isConnected() || browserContextUnavailableFailure(error)) {
      exitForBrowserFailure('resident-discovery-reset-context-unavailable', error);
      return false;
    }
    throw error;
  }
};

const completeFailedResidentCommand = async (action, error) => {
  const status = residentCommandFailureStatus(error);
  const progress = readProgress();
  const result = {
    requestId: progress.residentCommand?.requestId || activeReturnRefundCommand?.requestId || null,
    mode: action === 'refund-scan' ? 'scan' : 'discovery',
    status,
    shopId,
    error: error.message,
    retryAfterAt: progress.retryAfterAt || null,
    failedAt: new Date().toISOString(),
  };
  if (action === 'discover' || action === 'chat-collect') writePddDiscoveryOutput(result);
  else writeReturnRefundOutput(result);

  // A verification wait owns its visible challenge tab. Resetting discovery
  // here would close every derived PDD tab and erase its verification location
  // before the operator can complete it. Only repair an ordinary page failure.
  if (action === 'discover' && status === 'retryable-error') {
    await resetPddAfterResidentDiscoveryFailure(error);
  } else if (status === 'retryable-error') {
    const activePage = currentSystemPage();
    writeProgress({ step: 'flow-paused', error: error.message, currentUrl: activePage.url() });
    await saveWorkflowDiagnostics(activePage, `resident-${action}-failed`, error).catch(() => {});
  }
  await persistBrowserAuth(context).catch(() => {});
  resetResidentAssignment({ outcome: status });
};

const restoredVerificationStablePasses = 3;
const restoredVerificationStableDelayMs = 1_000;

const validatedPddVerificationRecoveryUrl = (value) => {
  try {
    const parsed = new URL(String(value || '').trim());
    if (parsed.protocol !== 'https:' || parsed.hostname !== 'mms.pinduoduo.com') return null;
    return parsed.toString();
  } catch {
    return null;
  }
};

const writeRestoredVerificationRecovery = (command, values = {}) => {
  const current = readProgress();
  const {
    status = 'restoring',
    startedAt: requestedStartedAt = null,
    authenticatedAt = null,
    completedAt = null,
    observedUrl = null,
    recoveryError = null,
    error = null,
    ...progressValues
  } = values;
  const startedAt = current.verificationRecovery?.trigger === 'resident-browser-restart-recovery'
    && current.verificationRecovery?.verificationId === command.verificationId
    && current.verificationRecovery?.workOrderId === command.workOrderId
    && current.verificationRecovery?.requestId === command.requestId
    ? current.verificationRecovery.startedAt
    : null;
  return writeProgress({
    ...progressValues,
    verificationRecovery: {
      trigger: 'resident-browser-restart-recovery',
      status,
      requestId: command.requestId,
      verificationId: command.verificationId,
      workOrderId: command.workOrderId,
      orderNumber: command.orderNumber,
      scenarioCode: command.scenarioCode,
      stage: command.stage,
      verificationUrl: command.url,
      detectedAt: command.detectedAt,
      startedAt: startedAt || requestedStartedAt || new Date().toISOString(),
      authenticatedAt,
      completedAt,
      observedUrl,
      error: recoveryError,
      externalActionsReplayed: false,
    },
    error,
  });
};

const waitForRestoredVerificationClear = async (targetPage, command) => {
  while (!targetPage.isClosed()) {
    const detection = await detectHumanVerification(targetPage);
    if (detection) {
      const progress = readProgress();
      // The resident observer may already have released this exact challenge
      // after its wait budget. The normal check then skips the cooldown
      // surface and returns false, while this raw detector still sees it.
      // Exit the recovery command without recreating the gate or claiming
      // verification succeeded; keep the page intact for the operator/plugin.
      if (verificationTimeoutSuppressesSurface(progress, {
        system: 'pdd', page: targetPage, detection,
      })) {
        throw new HumanVerificationTimeoutError(
          command.stage,
          targetPage.url(),
          progress.verificationTimeout.closeResult || null,
          progress.verificationTimeout.timeoutMs || humanVerificationMaxTimeoutMs,
        );
      }
      const currentUrl = targetPage.url();
      writeRestoredVerificationRecovery(command, {
        step: 'human-verification-required',
        status: 'waiting-human',
        observedUrl: currentUrl,
        verificationStage: command.stage,
        verificationLocation: {
          id: command.verificationId,
          shopId,
          system: 'pdd',
          stage: command.stage,
          status: 'waiting-human',
          url: currentUrl,
          selector: detection.selector,
          frameUrl: detection.frameUrl || undefined,
          boundingBox: detection.boundingBox,
          confidence: detection.confidence,
          detectedAt: command.detectedAt || new Date().toISOString(),
          lastSeenAt: new Date().toISOString(),
        },
      });
      await checkForHumanVerification(targetPage, command.stage);
      continue;
    }
    let stable = true;
    for (let pass = 1; pass < restoredVerificationStablePasses; pass += 1) {
      await targetPage.waitForTimeout(restoredVerificationStableDelayMs);
      if (targetPage.isClosed() || await detectHumanVerification(targetPage)) {
        stable = false;
        break;
      }
    }
    if (stable) return;
  }
  throw new Error('验证码恢复页面在确认解除前已关闭');
};

const runRestoredVerificationRecoveryOnly = async () => {
  const command = activeVerificationRecoveryCommand;
  if (!command) throw new Error('验证码恢复任务上下文不存在');
  const verificationUrl = validatedPddVerificationRecoveryUrl(command.url);
  if (!verificationUrl) throw new Error('验证码恢复任务页面不是可信的拼多多页面');
  command.url = verificationUrl;
  const recoveryAuthenticationTargetUrl = isSystemLoginUrl('pdd', verificationUrl)
    ? listUrl
    : verificationUrl;

  writeRestoredVerificationRecovery(command, {
    step: 'verification-recovery-opening',
    status: 'restoring',
    startedAt: new Date().toISOString(),
    observedUrl: null,
    verificationStage: command.stage,
    verificationLocation: null,
    verificationFocus: null,
  });

  // If the permanent PDD anchor still has a business URL, reuse it for the
  // stable-clear check instead of reopening the persisted login URL. Its URL
  // alone does not prove the session is valid, so keep a live login tab until
  // authentication has been checked and the recovery command has ended.
  // A business-detail challenge must use its exact live tab. A different
  // authenticated anchor does not prove that challenge has cleared.
  const authenticatedAnchor = !pddPage.isClosed()
    && isSystemLoginUrl('pdd', verificationUrl)
    && isAuthenticatedSystemUrl('pdd', pddPage.url())
    ? pddPage
    : null;
  let recoveryPage = authenticatedAnchor || context.pages().find((page) => (
    !page.isClosed() && page.url() === verificationUrl
  ));
  if (!recoveryPage) {
    recoveryPage = registerDerivedPage(
      await createBackgroundPage(),
      'pdd-verification-restart-recovery',
    );
    activeVerificationRecoveryPage = recoveryPage;
    protectVerificationRecoveryPage(recoveryPage, command.verificationId);
    await navigateSystemPage(recoveryPage, verificationUrl, 'pdd-verification-recovery-open');
  } else {
    activeVerificationRecoveryPage = recoveryPage;
    protectVerificationRecoveryPage(recoveryPage, command.verificationId);
  }
  await closeDeviceAccessIfPrompted(recoveryPage);
  persistSystemTabs('pdd');

  await waitForRestoredVerificationClear(recoveryPage, command);
  recoveryPage = await ensurePddLogin(
    recoveryPage,
    context,
    recoveryAuthenticationTargetUrl,
  );
  activeVerificationRecoveryPage = recoveryPage;
  protectVerificationRecoveryPage(recoveryPage, command.verificationId);
  await waitForRestoredVerificationClear(recoveryPage, command);
  if (!isAuthenticatedSystemUrl('pdd', recoveryPage.url())
    || recoveryPage.url().includes('/login')) {
    throw new PddLoginRequiredError(
      'restore-verification-authentication',
      recoveryPage.url(),
      '验证码解除后未确认拼多多登录态',
    );
  }

  const authenticatedProgress = readProgress();
  const authenticatedAt = new Date().toISOString();
  const completedAt = new Date().toISOString();
  const observedUrl = recoveryPage.url();
  writeRestoredVerificationRecovery(command, {
    step: 'verification-recovery-cleared',
    status: 'cleared',
    authenticatedAt,
    completedAt,
    observedUrl,
    verificationStage: null,
    verificationLocation: null,
    verificationFocus: null,
    authHealth: {
      ...(authenticatedProgress.authHealth || {}),
      pdd: {
        ...(authenticatedProgress.authHealth?.pdd || {}),
        status: 'authenticated',
        url: observedUrl,
        checkedAt: authenticatedAt,
        confidence: 'confirmed',
        source: 'resident-browser-restart-recovery',
        evidence: 'rendered-business-session',
      },
    },
    verificationRecheck: {
      trigger: 'resident-browser-restart-recovery',
      status: 'cleared',
      verificationId: command.verificationId,
      workOrderId: command.workOrderId,
      stage: command.stage,
      detectedAt: command.detectedAt,
      verificationUrl,
      observedUrl,
      startedAt: readProgress().verificationRecovery?.startedAt || null,
      authenticatedAt,
      completedAt,
      externalActionsReplayed: false,
    },
    manualReview: null,
    error: null,
  });
  pddPostLoginRecoveryPacing.start();
  await persistBrowserAuth(context).catch(() => {});

  releaseVerificationRecoveryPages(command.verificationId);
  if (recoveryPage !== pddPage && derivedPages.has(recoveryPage)) {
    await closeDerivedPage(recoveryPage, { allowVerificationRecoveryClose: true });
  } else if (recoveryPage === pddPage && isPddDetailUrl(recoveryPage.url())) {
    await navigateSystemPage(recoveryPage, listUrl, 'pdd-verification-recovery-list').catch(() => {});
  }
  persistSystemTabs('pdd');
};

const completeFailedVerificationRecoveryCommand = async (error) => {
  const command = activeVerificationRecoveryCommand;
  const outcome = residentCommandFailureStatus(error);
  if (command) {
    protectVerificationRecoveryPage(activeVerificationRecoveryPage, command.verificationId);
    for (const page of context.pages()) {
      if (page.isClosed()) continue;
      let url = '';
      try { url = page.url(); } catch { continue; }
      if (isSystemLoginUrl('pdd', url)) {
        protectVerificationRecoveryPage(page, command.verificationId);
      }
    }
    const progress = readProgress();
    writeRestoredVerificationRecovery(command, {
      step: outcome === 'verification-required'
        ? 'human-verification-required'
        : outcome === 'login-required'
          ? 'manual-login-required'
          : 'verification-recovery-retryable',
      status: outcome === 'verification-required' ? 'waiting-human' : 'retryable-error',
      observedUrl: progress.currentUrl || progress.verificationLocation?.url || null,
      recoveryError: error.message,
      error: outcome === 'retryable-error' ? error.message : null,
    });
  }
  await persistBrowserAuth(context).catch(() => {});
  resetResidentAssignment({ outcome });
};

const runReturnRefundClaimOnly = async () => {
  const command = activeReturnRefundCommand || {};
  assertActiveResidentCommandIdentity('run-return-refund');
  let activeRefundEffectId = null;
  let result;
  try {
    // Preflight can yield for login or verification before the refund reader
    // starts. Publish that failure through the same request-bound result;
    // otherwise the resident command becomes idle with no output to consume.
    await focusSystemPage('pdd', pddPage);
    await ensurePddLogin(pddPage, context, command.detailUrl || listUrl);
    result = await processReturnRefund(pddPage, context, {
      detailUrl: command.detailUrl,
      orderNumber: requestedOrderNumber,
      aftersaleNumber: command.aftersaleNumber,
      firstDiscoveredAt: command.firstDiscoveredAt,
      autoApproveEnabled: command.autoApproveEnabled,
      readOnlyReview: command.readOnlyReview,
      existingEffectStatus: command.existingEffectStatus,
      existingEffectReceipt: command.existingEffectReceipt,
      existingEffectError: command.existingEffectError,
      existingEffectReservedAt: command.existingEffectReservedAt,
      confirmLivePddSession: pddBusinessPageMatchesExpectedMall,
      delayMs: Math.max(700, Number(process.env.RETURN_REFUND_VISIBLE_STEP_DELAY_MS || 1200)),
      rateLimitRetryMs: rateLimitWaitMs,
      onStep: returnRefundVisibleStep,
      onVerification: (targetPage, stage) => checkForHumanVerification(targetPage, stage),
      reserveEffect: async ({ effectType, idempotencyKey, requestHash }) => {
        const reservation = await sendExternalEffectRequest('reserve', {
          effectType,
          orderNumber: requestedOrderNumber,
          stage: 'return-refund-approve',
          idempotencyKey,
          requestHash,
        });
        activeRefundEffectId = reservation.effectId || null;
        return {
          ...reservation,
          reserved: Boolean(reservation.effectId && !reservation.alreadySucceeded),
        };
      },
      completeEffect: async ({ status, receipt = null, error = null }) => {
        if (!activeRefundEffectId) return null;
        return sendExternalEffectRequest('complete', {
          effectId: activeRefundEffectId,
          effectType: 'pdd-return-refund',
          orderNumber: requestedOrderNumber,
          stage: 'return-refund-approve',
          status,
          receipt,
          error,
        });
      },
    });
  } catch (error) {
    result = {
      ...classifyReturnRefundUnexpectedFailure(error, {
        externalEffectStarted: Boolean(activeRefundEffectId),
      }),
      facts: {
        orderNumber: requestedOrderNumber,
        aftersaleNumber: command.aftersaleNumber,
        detailUrl: command.detailUrl,
      },
    };
  }
  const output = {
    requestId: command.requestId || null,
    mode: 'claim',
    status: 'completed',
    shopId,
    orderNumber: requestedOrderNumber,
    aftersaleNumber: command.aftersaleNumber,
    result,
    completedAt: new Date().toISOString(),
  };
  writeReturnRefundOutput(output);
  logRunStep('return-refund-claim-complete', {
    orderNumber: requestedOrderNumber,
    aftersaleNumber: command.aftersaleNumber,
    outcome: result.outcome,
    error: result.error || null,
  });
  return output;
};

let residentOmsWarmupPromise = null;
let residentOmsWarmupExpedited = false;
let residentOmsWarmupExpediteResolver = null;
let residentTmsWarmupPromise = null;

const updateResidentSystemWarmup = (system, patch) => {
  const progress = readProgress();
  return writeProgress({
    residentSystemWarmup: {
      ...(progress.residentSystemWarmup || {}),
      [system]: {
        ...(progress.residentSystemWarmup?.[system] || {}),
        ...patch,
      },
    },
  });
};

const residentOmsWarmupDelayMs = () => {
  const fallbackSlot = Number.parseInt(
    crypto.createHash('sha256').update(shopId).digest('hex').slice(0, 8),
    16,
  ) % 17;
  const slot = Number.isInteger(workflowShopDisplaySlot) && workflowShopDisplaySlot >= 0
    ? workflowShopDisplaySlot
    : fallbackSlot;
  return Math.min(residentOmsWarmupMaxStaggerMs, slot * residentOmsWarmupStaggerMs);
};

const waitForResidentOmsWarmupTurn = async () => {
  const delayMs = residentOmsWarmupDelayMs();
  if (delayMs > 0 && !residentOmsWarmupExpedited) {
    await new Promise((resolve) => {
      let settled = false;
      const finish = () => {
        if (settled) return;
        settled = true;
        clearTimeout(timer);
        if (residentOmsWarmupExpediteResolver === finish) {
          residentOmsWarmupExpediteResolver = null;
        }
        resolve();
      };
      const timer = setTimeout(finish, delayMs);
      timer.unref?.();
      residentOmsWarmupExpediteResolver = finish;
    });
  }
  while (activeAssignmentId && !residentOmsWarmupExpedited && !workflowStopping) {
    await new Promise((resolve) => setTimeout(resolve, 250));
  }
};

const markResidentOmsWarmupFailure = async (error) => {
  systemLoginAttempts.oms = 0;
  const currentHealth = readProgress().authHealth?.oms;
  if (!['verification-required', 'expired'].includes(currentHealth?.status)) {
    const appState = omsPage.isClosed()
      ? null
      : await readOmsAppState(omsPage).catch(() => null);
    const loginObserved = Boolean(
      appState?.loggedOut
        || appState?.loginForm
        || (!omsPage.isClosed() && isSystemLoginUrl('oms', omsPage.url())),
    );
    updateAuthHealth('oms', loginObserved ? 'expired' : 'unreachable', omsPage, {
      stage: 'resident-oms-startup-warmup',
      source: 'resident-oms-startup-warmup',
      evidence: loginObserved ? 'rendered-login-form' : 'business-shell-unavailable',
      lastError: error.message,
    });
  }
  updateResidentSystemWarmup('oms', {
    status: 'deferred',
    completedAt: new Date().toISOString(),
    url: omsPage.isClosed() ? null : omsPage.url(),
    error: error.message,
    blocksPddDiscovery: false,
    performsBusinessSubmission: false,
  });
  persistSystemTabs('pdd');
  return false;
};

const initializeResidentSystemsForDiscovery = async () => {
  // Discovery and return-refund only depend on PDD. Warm the permanent OMS
  // and TMS anchors in parallel so ordinary claims can reuse them without
  // making either external system a prerequisite for PDD discovery.
  const progress = readProgress();
  const targets = restoredSystemTargets(progress);

  // When an existing business tab survives a worker restart, pace the first
  // restore navigation too. The guard skips a manual login surface.
  pddPostLoginRecoveryPacing.start();
  await navigateSystemPage(pddPage, targets.pdd, 'discovery-restore-pdd-tab');
  persistSystemTabs('pdd');

  if (!returnRefundPddOnlyMode) {
    if (omsMode === 'per-shop') {
      residentOmsWarmupPromise = (async () => {
        const startedAt = new Date().toISOString();
        updateResidentSystemWarmup('oms', {
          status: 'scheduled',
          startedAt,
          delayMs: residentOmsWarmupDelayMs(),
          blocksPddDiscovery: false,
          performsBusinessSubmission: false,
        });
        await waitForResidentOmsWarmupTurn();
        updateResidentSystemWarmup('oms', {
          status: 'warming',
          navigationStartedAt: new Date().toISOString(),
        });
        await navigateSystemPage(omsPage, targets.oms, 'resident-warm-oms-tab');
        await ensureOmsLogin(omsPage, context, {
          residentWarmup: true,
          manualLoginTimeoutMs: residentOmsWarmupManualWaitMs,
        });
        await confirmOmsBusinessPage(omsPage, 'resident-oms-business-confirm');
        updateAuthHealth('oms', 'authenticated', omsPage, {
          stage: 'resident-oms-startup-login',
          source: 'resident-oms-startup-warmup',
          evidence: 'rendered-business-session',
        });
        updateResidentSystemWarmup('oms', {
          status: 'authenticated',
          completedAt: new Date().toISOString(),
          url: omsPage.url(),
          error: null,
        });
        persistSystemTabs('pdd');
        return true;
      })().catch((error) => {
        console.warn(`[resident-oms] ${shopId}: warmup deferred: ${error.message}`);
        return markResidentOmsWarmupFailure(error);
      });
    }

    residentTmsWarmupPromise = navigateSystemPage(tmsPage, targets.tms, 'resident-warm-tms-tab')
      .then(async () => {
        await ensureTmsLoginOnce(tmsPage, context);
        updateAuthHealth('tms', 'authenticated', tmsPage, {
          stage: 'resident-tms-startup-login',
        });
        persistSystemTabs('pdd');
        return true;
      })
      .catch((error) => {
        console.warn(`[resident-tms] ${shopId}: warmup deferred: ${error.message}`);
        updateManagedBrowserTitle('tms', 'checking', tmsPage);
        persistSystemTabs('pdd');
        return false;
      });
  }

  await focusSystemPage('pdd', pddPage);
  await ensurePddLogin(pddPage, context, targets.pdd);
  updateAuthHealth('pdd', 'authenticated', pddPage);
  // A restarted resident worker can inherit an authenticated browser. Ease
  // its first business navigations back into the existing session as well.
  pddPostLoginRecoveryPacing.start();

  await focusSystemPage('pdd', pddPage);
  persistSystemTabs('pdd');
  return {
    targets,
    omsWarmup: residentOmsWarmupPromise,
    tmsWarmup: residentTmsWarmupPromise,
  };
};

let pageCrashRecoveryAttempts = 0;
const recoverCrashedSystemPages = async (error) => {
  if (!/page crashed|target page, context or browser has been closed|(?:pdd|oms|tms) 标签页不可用/iu
    .test(error.message || '')
    && !/Chromium context is unavailable before creating a background tab/iu.test(error.message || '')
    && crashedSystems.size === 0) return false;
  // A shutdown/restart can race with the recovery loop. In that window the
  // browser process may still report connected while the context is already
  // unavailable; attempting to create another tab only throws the same error
  // and leaves the claimed order in a tight retry loop.
  if (workflowStopping || browserFailureExiting || !browser.isConnected()) return false;

  const progress = readProgress();
  const activeCrashScenarioCode = progress.scenarioCode
    || activeScenarioCode
    || matchingScenarioForTitle(progress.workOrderType || activeWorkOrderType)?.code
    || null;
  const scenarioDependencies = activeCrashScenarioCode
    ? scenarioSystemDependencies(activeCrashScenarioCode)
    : null;
  const pddOnlyOrdinaryRecovery = Boolean(
    requestedOrderNumber
      && scenarioDependencies?.pdd === true
      && scenarioDependencies?.oms !== true
      && scenarioDependencies?.tms !== true,
  );
  const pddOnlyRecovery = Boolean(activeReturnRefundCommand)
    || pddOnlyOrdinaryRecovery
    || (process.env.PDD_DISCOVER_ONLY === 'true'
      && !requestedOrderNumber
      && !reconcileExternalStateOnly);
  const systemsToRecover = new Set(crashedSystems);
  const candidates = pddOnlyRecovery
    ? [['pdd', pddPage]]
    : [
      ['pdd', pddPage],
      ['oms', omsPage],
      ['tms', tmsPage],
    ];
  if (pddOnlyRecovery) {
    systemsToRecover.delete('oms');
    systemsToRecover.delete('tms');
  }
  for (const [system, targetPage] of candidates) {
    if (targetPage.isClosed()) {
      systemsToRecover.add(system);
      continue;
    }
    await targetPage.title().catch(() => systemsToRecover.add(system));
  }
  if (!systemsToRecover.size) {
    const verificationSystem = pddOnlyRecovery ? 'pdd' : Object.entries(progress.authHealth || {})
      .find(([, health]) => health?.status === 'verification-required')?.[0];
    systemsToRecover.add(verificationSystem || progress.systemTabs?.activeSystem || 'pdd');
  }

  pageCrashRecoveryAttempts++;
  if (pageCrashRecoveryAttempts > 3) return false;
  writeProgress({
    step: 'page-crash-recovering',
    pageCrashRecovery: {
      systems: [...systemsToRecover],
      attempt: pageCrashRecoveryAttempts,
      error: error.message,
      recoveredAt: null,
    },
    error: null,
  });

  for (const system of systemsToRecover) {
    if (system === 'pdd') {
      await pddPage.close().catch(() => {});
      assignRecoveredSystemPage('pdd', await createBackgroundPage());
    } else if (system === 'oms') {
      await omsPage.close().catch(() => {});
      assignRecoveredSystemPage('oms', await createBackgroundPage());
    } else if (system === 'tms') {
      await tmsPage.close().catch(() => {});
      assignRecoveredSystemPage('tms', await createBackgroundPage());
    }
    crashedSystems.delete(system);
  }
  if (!reconcileExternalStateOnly) {
    if (pddOnlyRecovery) await initializeResidentSystemsForDiscovery();
    else await restoreAndAuthenticateSystemTabs(readProgress(), [...systemsToRecover]);
  }
  writeProgress({
    step: 'page-crash-recovered',
    pageCrashRecovery: {
      systems: [...systemsToRecover],
      attempt: pageCrashRecoveryAttempts,
      error: error.message,
      recoveredAt: new Date().toISOString(),
    },
    error: null,
  });
  return true;
};

let currentOrderRerunApplied = null;

const runScenarioStagesAfterOms = async (orderNumber) => {
  const { scenarioCode } = currentScenarioIdentityForOrder(orderNumber, { persist: true });
  if (!scenarioRequiresTms(scenarioCode)) {
    if (isExtendedOrdinaryScenario(scenarioCode)) {
      throw new Error(`新增普通工单场景必须由独立决策执行器处理: ${scenarioCode}`);
    }
    const progress = readProgress();
    if (scenarioCode === 'abnormal-network-warning'
      && hasReusableAbnormalNetworkAllocation(progress, orderNumber)
      && hasCompletedTmsBypass(progress, orderNumber)) {
      writeProgress({
        step: 'oms-allocation-checkpoint-reused',
        abnormalNetworkShipmentWait: {
          ...(progress.abnormalNetworkShipmentWait || {}),
          orderNumber,
          status: 'pdd-shipment-rechecked',
          strategy: 'refresh-pdd-and-reuse-confirmed-oms-allocation',
          resumedAt: new Date().toISOString(),
        },
        error: null,
      });
      console.log(`复用异常网点已确认的 OMS 配货结果，仅复查拼多多实际发货状态: ${orderNumber}`);
      return progress.tmsBypass;
    }
    await focusSystemPage('oms', omsPage);
    await ensureOmsScenarioPreparation(omsPage, context, orderNumber);
    return skipTmsForAbnormalNetwork(orderNumber);
  }
  await focusSystemPage('tms', tmsPage);
  return runTmsWorkflow(tmsPage, context, orderNumber);
};

const processOneWorkOrder = async () => {
  assertActiveResidentCommandIdentity('process-one-work-order');
  let progress = readProgress();
  if (progress.ordinaryListCompletionReadOnlyRecovery?.protectedReadOnly === true
    && (!reconcileExternalStateOnly || !reconcileExternalEffectTypes.has('pdd-list-completion-proof'))) {
    throw new ManualReviewRequiredError('ordinary-list-completion-read-only',
      '该单仅允许读取平台完结证明，禁止重新执行或提交');
  }
  // Only a new queue claim needs the three-system preflight. During a retry of
  // an existing order (especially PDD resolution/manual review), navigating
  // OMS/TMS again can reset their forms and create an apparent retry loop.
  if (!reconcileExternalStateOnly && !progress.orderNumber) {
    const claimedScenarioCode = activeScenarioCode
      || matchingScenarioForTitle(activeWorkOrderType)?.code
      || null;
    if (isExtendedOrdinaryScenario(claimedScenarioCode)) {
      await ensureScenarioSystemDependencies(claimedScenarioCode, ['PDD']);
    } else {
      await ensureOmsLogin(omsPage, context);
      await openTmsCustomerRegistration(tmsPage, context);
      assertAuthenticatedSystemTabs();
    }
  }
  persistSystemTabs('pdd');
  resetCurrentOrderForRerun();
  progress = readProgress();
  if (reconcileExternalStateOnly && reconcileExternalEffectTypes.has('pdd-list-completion-proof')) {
    const orderNumber = requestedOrderNumber || progress.orderNumber;
    const guard = progress.ordinaryListCompletionReadOnlyRecovery;
    if (guard?.protectedReadOnly !== true || guard.ordinaryInstanceId !== progress.ordinaryInstanceId
      || guard.platformWorkOrderId !== progress.platformWorkOrderId) {
      throw new Error('list-completion-reconciliation-identity-mismatch');
    }
    const { state } = await readCompletedOrdinaryListDetail(orderNumber, null);
    const fresh = readProgress();
    if (fresh.pddShopIdentity?.mallId !== guard.mallId) {
      throw new Error('list-completion-reconciliation-mall-mismatch');
    }
    const observation = {
      state: 'confirmed', effectType: 'pdd-list-completion-proof',
      orderNumber, ordinaryInstanceId: progress.ordinaryInstanceId,
      observedPlatformWorkOrderId: state.observedPlatformWorkOrderId,
      observedMallId: fresh.pddShopIdentity.mallId,
      completionEvidence: state.completedOutcome || null,
      confirmationMethod: 'detail-completed', readOnly: true,
      externalActionsReplayed: false, observedAt: new Date().toISOString(),
    };
    writeProgress({ step: 'external-state-confirmed', externalStateReconciliation: observation,
      pddResolutionSubmission: {
        shopId, orderNumber, status: 'succeeded', outcome: state.completedOutcome || 'read-only-completed',
        completionEvidence: state.completedOutcome || null, confirmationMethod: 'detail-completed',
        platformCompletionObservation: fresh.ordinaryListCompletionDetailProof.platformCompletionObservation,
        recoveredFromCompletedPage: true, submitClicked: false, completedAt: observation.observedAt,
      }, error: null });
    return { reconciled: true, orderNumber, observation };
  }
  if (reconcileExternalStateOnly && reconcileExternalEffectTypes.has('oms-reissue-create')) {
    await focusSystemPage('oms', omsPage);
    const observation = await reconcileOmsReissueCreateState(
      omsPage,
      requestedOrderNumber || progress.orderNumber,
    );
    return { reconciled: true, orderNumber: observation.orderNumber, observation };
  }
  if (reconcileExternalStateOnly && reconcileExternalEffectTypes.has('oms-manual-allocation')) {
    await focusSystemPage('oms', omsPage);
    const observation = await reconcileOmsManualAllocationState(
      omsPage,
      requestedOrderNumber || progress.orderNumber,
    );
    return { reconciled: true, orderNumber: observation.orderNumber, observation };
  }
  if (reconcileExternalStateOnly && reconcileExternalEffectTypes.has('tms-create')) {
    await focusSystemPage('tms', tmsPage);
    const observation = await reconcileTmsCreateState(
      tmsPage,
      requestedOrderNumber || progress.orderNumber,
    );
    return { reconciled: true, orderNumber: observation.orderNumber, observation };
  }
  let detailPage = pddPage;
  let resumedExistingDetail = false;
  let recoveredExactDetail = false;
  const pddArtifactComplete = Boolean(!forceEvidenceRecapture
    && progress.orderNumber
    && hasCompleteScenarioLogisticsAnalysis(
      progress.logisticsAnalysis,
      progress.orderNumber,
      progress.scenarioCode,
    )
    && hasConsumablePddEvidence(progress, progress.orderNumber));
  const createdTmsStageComplete = Boolean(progress.orderNumber
    && hasCompleteLogisticsAnalysis(progress.logisticsAnalysis, progress.orderNumber)
    && progress.tmsWorkOrder?.status === 'created'
    && progress.tmsWorkOrder.orderNumber === progress.orderNumber
    && progress.tmsEvidenceScreenshot?.status === 'ready'
    && progress.tmsEvidenceScreenshot.orderNumber === progress.orderNumber
    && hasConsumableTmsEvidence(progress, progress.orderNumber)
    && progress.pddEvidenceScreenshot?.status === 'deleted');
  const bypassedTmsStageComplete = Boolean(progress.orderNumber
    && hasCompleteScenarioLogisticsAnalysis(
      progress.logisticsAnalysis,
      progress.orderNumber,
      progress.scenarioCode,
    )
    && hasCompletedTmsBypass(progress, progress.orderNumber)
    && progress.pddEvidenceScreenshot?.status === 'ready');
  const tmsStageComplete = createdTmsStageComplete || bypassedTmsStageComplete;
  const resumeAllowed = !requestedOrderNumber || progress.orderNumber === requestedOrderNumber;

  if (!reconcileExternalStateOnly && resumeAllowed && progress.pddResolutionSubmission?.status === 'succeeded') {
    finalizeEvidenceAfterPddCompletion(progress.orderNumber, progress.pddResolutionSubmission);
    logRunStep('full-business-flow-complete', {
      orderNumber: progress.orderNumber,
      pddResolutionSubmission: progress.pddResolutionSubmission,
      error: null,
    });
    await archiveAndResetCompletedOrder(progress.pddResolutionSubmission);
    return { completed: true, orderNumber: progress.orderNumber };
  }

  const consumerNegotiationResume = !reconcileExternalStateOnly && resumeAllowed
    ? resolvePddConsumerNegotiationResume(progress, progress.orderNumber)
    : null;
  const inTransitOutcomeFallbackResume = !reconcileExternalStateOnly && resumeAllowed
    ? resolvePddInTransitOutcomeFallbackResume(progress, progress.orderNumber)
    : null;
  if (inTransitOutcomeFallbackResume) {
    console.log(`退款选项已被平台明确拒绝，直接返回拼多多尝试下一固定选项，不重跑 OMS/TMS: ${progress.orderNumber}`);
    writeProgress({
      inTransitOutcomeFallbackRecovery: {
        strategy: 'resume-pdd-outcome-fallback-without-oms-or-tms-replay',
        rejectedOutcomeLabels: inTransitOutcomeFallbackResume.rejectedOutcomeLabels,
        nextOutcome: inTransitOutcomeFallbackResume.nextOutcome,
        resumedAt: new Date().toISOString(),
      },
      error: null,
      manualReview: null,
    });
    const completion = await runPddResolutionWorkflow(pddPage, progress.orderNumber);
    await archiveAndResetCompletedOrder(completion);
    return { completed: true, orderNumber: progress.orderNumber };
  }
  if (consumerNegotiationResume) {
    if (!consumerNegotiationResume.ready) {
      throw new LogisticsRetryRequiredError(
        'pdd-consumer-negotiation-waiting',
        '拼多多正在等待消费者确认拦截后退款方案，满 12 小时仍无回复后再自动处理',
        consumerNegotiationResume.retryAfterMs,
        {
          orderNumber: progress.orderNumber,
          detailUrl: progress.detailUrl,
          nextAttemptAt: consumerNegotiationResume.nextAttemptAt,
        },
      );
    }
    console.log(`消费者协商等待已到期，直接返回拼多多处理，不重跑 OMS/TMS: ${progress.orderNumber}`);
    writeProgress({
      consumerNegotiationFollowupRecovery: {
        strategy: 'resume-pdd-followup-without-oms-or-tms-replay',
        resumedAt: new Date().toISOString(),
      },
    });
    const completion = await runPddResolutionWorkflow(pddPage, progress.orderNumber);
    await archiveAndResetCompletedOrder(completion);
    return { completed: true, orderNumber: progress.orderNumber };
  }

  if (!reconcileExternalStateOnly && resumeAllowed && tmsStageComplete
    && !isExtendedOrdinaryScenario(progress.scenarioCode)) {
    if (bypassedTmsStageComplete) {
      console.log(`异常网点预警已跳过 TMS，返回拼多多处理: ${progress.orderNumber}`);
    } else {
      console.log(`复用已创建的 TMS 工单和截图，返回拼多多处理: ${progress.tmsWorkOrder.ticketNo}`);
      initializeTmsEvidenceDisposition(
        progress.orderNumber,
        progress.tmsWorkOrder,
        progress.tmsEvidenceScreenshot,
      );
    }
    const completion = await runPddResolutionWorkflow(pddPage, progress.orderNumber);
    await archiveAndResetCompletedOrder(completion);
    return { completed: true, orderNumber: progress.orderNumber };
  }

  if (!reconcileExternalStateOnly && resumeAllowed && pddArtifactComplete
    && !isExtendedOrdinaryScenario(progress.scenarioCode)) {
    // A saved logistics screenshot is not proof that the PDD case is still
    // actionable. Reconcile the exact detail before any OMS/TMS mutation.
    detailPage = await reopenPddDetailForResolution(detailPage, progress.orderNumber, progress);
    const currentState = hasConfirmedPendingListAbsence(readProgress(), progress.orderNumber)
      ? completedPddStateFromPendingListAbsence(progress.orderNumber)
      : await ensurePddResolutionDetailReady(detailPage, progress.orderNumber, readProgress());
    if (currentState.isCompleted && currentState.orderMatches) {
      const completion = await runPddResolutionWorkflow(detailPage, progress.orderNumber);
      await archiveAndResetCompletedOrder(completion);
      return { completed: true, orderNumber: progress.orderNumber };
    }
    console.log(`复用已验证的拼多多截图和物流结果: ${progress.orderNumber}`);
    if (!hasCompleteScenarioOmsAnalysis(
      progress.omsAnalysis,
      progress.logisticsAnalysis,
      progress.orderNumber,
      progress.scenarioCode,
    ) || forceOmsRecheck) {
      await focusSystemPage('oms', omsPage);
      await analyzeOmsOrder(omsPage, context, progress.orderNumber);
    } else {
      console.log(`复用已保存的 OMS 结果: ${progress.orderNumber}`);
    }
    await runScenarioStagesAfterOms(progress.orderNumber);
    const completion = await runPddResolutionWorkflow(pddPage, progress.orderNumber);
    await archiveAndResetCompletedOrder(completion);
    return { completed: true, orderNumber: progress.orderNumber };
  }

  const hasUnconsumedDifferentOrder = requestedOrderNumber
    && progress.orderNumber
    && progress.orderNumber !== requestedOrderNumber
    && (progress.pddEvidenceScreenshot?.status === 'ready'
      || progress.tmsEvidenceScreenshot?.status === 'ready');
  if (hasUnconsumedDifferentOrder) {
    throw new Error(`订单 ${progress.orderNumber} 仍有未消费临时截图，禁止覆盖为新订单 ${requestedOrderNumber}`);
  }

  await focusSystemPage('pdd', pddPage);
  const canResumeSavedDetail = Boolean(isPddDetailUrl(progress.detailUrl)
    && !pddSavedDetailNeedsFreshLookup(progress)
    && (!requestedOrderNumber || progress.orderNumber === requestedOrderNumber));
  if (canResumeSavedDetail) {
    resumedExistingDetail = true;
  } else if (requestedOrderNumber) {
    writeProgress({
      orderNumber: requestedOrderNumber,
      detailUrl: null,
      workOrderType: activeWorkOrderType,
      scenarioCode: activeScenarioCode,
      logisticsAnalysis: null,
      pddEvidenceScreenshot: null,
      omsAnalysis: null,
      omsManualAllocation: null,
      tmsRoutingDecision: null,
      tmsFormDecision: null,
      tmsAutofillVerification: null,
      tmsAttachmentTransfer: null,
      tmsWorkOrder: null,
      tmsEvidenceScreenshot: null,
      tmsEvidenceDisposition: null,
      tmsBypass: null,
      pddResolutionDecision: null,
      pddResolutionSubmission: null,
      pddResolutionRecovery: null,
      ordinaryScenarioFacts: null,
      ordinaryScenarioDecision: null,
      ordinaryScenarioExecution: null,
      step: 'order-query-started',
    });
    await pacedAction(pddPage, 'open-pinduoduo', () => navigateSystemPage(
      pddPage,
      exists(statePath) ? listUrl : loginUrl,
      'open-pinduoduo',
    ));
  } else {
    await pacedAction(pddPage, 'open-pinduoduo', () => navigateSystemPage(
      pddPage,
      exists(statePath) ? listUrl : loginUrl,
      'open-pinduoduo',
    ));
  }
  await closeDeviceAccessIfPrompted(pddPage);
  persistSystemTabs('pdd');
  logRunStep('pinduoduo-page-opened', { url: pddPage.url() });
  await ensurePddLogin(
    pddPage,
    context,
    listUrl,
  );

  if (resumedExistingDetail && progress.detailUrl) {
    detailPage = await openSavedPddDetailPage(progress.detailUrl);
    await detailPage.waitForLoadState('domcontentloaded').catch(() => {});
    await closeDeviceAccessIfPrompted(detailPage);
    console.log(`Resumed unfinished workflow in derived PDD detail tab: ${detailPage.url()}`);
    logRunStep('resume-existing-detail', { detailUrl: detailPage.url() });
  } else if (!pddPage.url().includes('/aftersales/work_order/tododetail')) {
    if (pddPage.url().includes('/login')) {
      const pddAccount = pddLoginMode === 'auto' ? process.env.PDD_ACCOUNT : null;
      const pddPassword = pddLoginMode === 'auto' ? process.env.PDD_PASSWORD : null;
      if (!pddAccount || !pddPassword) {
        const loginRequired = recordPddLoginRequired(pddPage);
        await focusManualLoginPage(pddPage);
        await saveWorkflowDiagnostics(pddPage, 'manual-login-pinduoduo');
        if (browserHeadless) {
          console.error('\n[需要人工登录] 拼多多登录状态已失效；无头服务器没有可操作窗口，流程已停止。');
          console.error('[需要人工登录] 请在本地有界面环境恢复认证状态后再续跑。\n');
          throw loginRequired;
        }
        console.error('\n[需要人工登录] 拼多多登录状态已失效，请在当前可视化浏览器中手动登录。');
        console.error(`[需要人工登录] 登录成功后流程会自动返回原工单详情。URL: ${pddPage.url()}\n`);
        pddPage = await waitForLoginExit(pddPage, (url) => url.includes('/login'), 'pdd-manual-login');
      } else {
        const tab = pddPage.getByText('\u8d26\u53f7\u767b\u5f55', { exact: true });
        if (await tab.isVisible().catch(() => false)) {
          await pacedAction(pddPage, 'select-account-login', () => tab.click({ force: true }));
        }
        const accountInput = await firstVisible([
          pddPage.getByPlaceholder('\u8bf7\u8f93\u5165\u8d26\u53f7\u540d/\u624b\u673a\u53f7', { exact: true }),
          pddPage.locator('input[placeholder*="账号名"], input[placeholder*="手机号"]'),
          pddPage.getByRole('textbox', { name: /账号名|手机号/ }),
        ]);
        const passwordInput = await firstVisible([
          pddPage.getByPlaceholder('\u8bf7\u8f93\u5165\u5bc6\u7801', { exact: true }),
          pddPage.locator('input[type="password"], input[placeholder*="密码"]'),
        ]);
        if (!accountInput || !passwordInput) throw new Error('拼多多账号登录页未找到账号或密码输入框');
        await pacedAction(pddPage, 'fill-account', () => accountInput.fill(pddAccount));
        await pacedAction(pddPage, 'fill-password', () => passwordInput.fill(pddPassword));
        await pacedAction(pddPage, 'submit-login', () => pddPage.getByRole('button', { name: '\u767b\u5f55' }).click(), { retryOnRateLimit: true });
        const otp = pddPage.getByRole('textbox', { name: '\u8bf7\u8f93\u5165\u77ed\u4fe1\u9a8c\u8bc1\u7801' });
        if (await otp.isVisible().catch(() => false)) {
          await checkForHumanVerification(pddPage, 'sms-verification');
        }
        pddPage = await waitForLoginExit(pddPage, (url) => url.includes('/login'), 'pdd-login-result');
      }
      updateAuthHealth('pdd', 'authenticated', pddPage);
      await persistBrowserAuth(context, { pddAuthenticated: true });
      await pacedAction(pddPage, 'open-post-login-target', () => navigateSystemPage(
        pddPage,
        listUrl,
        'open-post-login-target',
      ));
      await closeDeviceAccessIfPrompted(pddPage);
    }
    if (pddPage.url().includes('/aftersales/work_order/tododetail')) {
      detailPage = pddPage;
      console.log(`已恢复未完成流程，跳过重复领取工单: ${pddPage.url()}`);
      logRunStep('resume-existing-detail', { detailUrl: pddPage.url() });
    } else {
      if (!pddPage.url().includes('/aftersales/work_order/list')) {
        throw new Error(`未进入工单列表: ${pddPage.url()}`);
      }
      logRunStep('work-order-management-opened', { url: pddPage.url() });
      if (!requestedOrderNumber) {
        const selection = await findNextPendingWorkOrder(pddPage);
        if (!selection) return { queueEmpty: true };
        detailPage = await openPendingWorkOrder(selection);
      } else {
      let target;
      let requestedOrderQueryState = null;
      if (requestedOrderNumber) {
        await submitPendingOrderQuery(pddPage, requestedOrderNumber, 'requested');
        requestedOrderQueryState = await waitForOrdinaryListRenderState(pddPage, {
          stage: '指定普通工单查询渲染',
          orderNumber: requestedOrderNumber,
          confirmEmptyAfterRefresh: true,
          onRefresh: (page) => submitPendingOrderQuery(
            page,
            requestedOrderNumber,
            'requested-refresh',
          ),
        });
        target = requestedOrderQueryState.target
          || pddPage.getByText(requestedOrderNumber, { exact: true }).first();
        logRunStep('order-query-submitted', { orderNumber: requestedOrderNumber });
      } else {
        const titles = configuredWorkOrderTitles();
        target = pddPage.getByText(titles[0] || targetWorkOrderTitle, { exact: true }).first();
      }
      const selectedType = requestedOrderNumber
        ? activeWorkOrderType
        : await target.innerText().catch(() => targetWorkOrderTitle);
      const selectedScenarioCode = requestedOrderNumber
        ? (activeScenarioCode || matchingScenarioForTitle(activeWorkOrderType)?.code || null)
        : matchingScenarioForTitle(selectedType)?.code || null;
      const targetVisible = requestedOrderQueryState
        ? requestedOrderQueryState.pending === true
          && await target.isVisible().catch(() => false)
        : await target.waitFor({ state: 'visible', timeout: pddRenderWaitMs })
          .then(() => true)
          .catch(() => false);
      recoveredExactDetail = false;
      if (!targetVisible) {
        const recoveryUrl = verifiedPddDetailRecoveryUrl(readProgress(), requestedOrderNumber);
        const current = readProgress();
        const identity = current.pddShopIdentity || {};
        const configuredIdentity = canonicalPddShopIdentityName(expectedShopName);
        const actualShopName = normalizePddShopNameCandidate(
          identity.mallName || identity.actualShopName,
        );
        const actualIdentity = canonicalPddShopIdentityName(actualShopName);
        const exactShopIdentity = identity.status === 'detected'
          && configuredIdentity
          && actualIdentity
          && pddIdentityMatches(configuredPddIdentityNames, [
            actualShopName,
            identity.mallName,
            identity.headerShopName,
            identity.identityNames,
          ])
          && !isMaskedPddShopIdentityName(actualShopName);
        const confirmedAt = new Date().toISOString();
        const confirmationMethod = requestedOrderQueryState?.confirmationMethod || null;
        const refreshedExactEmpty = requestedOrderQueryState?.refreshed === true
          && ['two-pass-exact-order-query', 'exact-order-zero-result']
            .includes(confirmationMethod);
        const pendingListPresence = {
          orderNumber: requestedOrderNumber,
          present: false,
          confirmationMethod,
          refreshed: requestedOrderQueryState?.refreshed === true,
          exactShopIdentity: Boolean(exactShopIdentity),
          actualShopName: actualShopName || null,
          expectedShopName: expectedShopName || null,
          confirmedAt,
        };
        writeProgress({
          step: 'requested-order-pending-absence-confirmed',
          ordinaryPendingListPresence: pendingListPresence,
          pddResolutionPendingListPresence: pendingListPresence,
          error: null,
        });
        if (exactShopIdentity && confirmationMethod === 'exact-order-completed'
          && selectedScenarioCode) {
          const completedDetail = await readCompletedOrdinaryListDetail(
            requestedOrderNumber, requestedOrderQueryState,
          );
          if (reconcileExternalStateOnly) {
            const observation = await reconcilePddExternalState(completedDetail.page, requestedOrderNumber);
            return { reconciled: true, orderNumber: requestedOrderNumber, observation };
          }
          const completion = ordinaryCompletionFromPendingListAbsence(
            requestedOrderNumber, selectedScenarioCode,
            readProgress().ordinaryScenarioDecision || {},
            { confirmationMethod, completedState: completedDetail.state },
          );
          await archiveAndResetCompletedOrder(completion);
          return { completed: true, orderNumber: requestedOrderNumber };
        }
        // A stale detail deep link must not override a refreshed exact zero
        // result for the verified shop. PDD has already removed the case from
        // the merchant's actionable queue, so reopening that old route only
        // creates an expensive render-retry loop.
        if (exactShopIdentity && refreshedExactEmpty && selectedScenarioCode) {
          const completion = ordinaryCompletionFromPendingListAbsence(
            requestedOrderNumber,
            selectedScenarioCode,
            readProgress().ordinaryScenarioDecision || {},
            { confirmationMethod },
          );
          await archiveAndResetCompletedOrder(completion);
          return { completed: true, orderNumber: requestedOrderNumber };
        }
        if (!recoveryUrl) {
          if (!exactShopIdentity) {
            throw new Error(`目标工单查询为空，但当前拼多多店铺身份未精确确认: ${requestedOrderNumber}`);
          }
          if (!refreshedExactEmpty) {
            throw new Error(`目标工单查询为空，但尚未取得刷新后的精确零结果: ${requestedOrderNumber}`);
          }
          if (!selectedScenarioCode) {
            throw new Error(`目标工单查询为空，但缺少已确认的普通工单场景: ${requestedOrderNumber}`);
          }
        }
        detailPage = await openSavedPddDetailPage(recoveryUrl);
        await detailPage.waitForLoadState('domcontentloaded').catch(() => {});
        await closeDeviceAccessIfPrompted(detailPage);
        const recoveredState = await waitForPddResolutionDetail(detailPage, requestedOrderNumber, {
          readTimeoutMs: 10000,
          settleMs: Math.max(pddDetailSettleMs, 15000),
        });
        if (!recoveredState.detailReady || !recoveredState.orderMatches) {
          throw new Error(`目标工单不在待处理列表，且已验证详情无法确认订单号: ${requestedOrderNumber}`);
        }
        recoveredExactDetail = true;
        logRunStep('verified-detail-recovered-after-pending-miss', {
          orderNumber: requestedOrderNumber,
          detailUrl: detailPage.url(),
          platformWorkOrderId: readProgress().platformWorkOrderId,
          completed: recoveredState.isCompleted,
        });
      } else {
        const action = await locateWorkOrderAction(target);
        const openedPage = await openPddDetailWithoutForegroundPopup(
          pddPage,
          action,
          'open-work-order',
          { retryOnRateLimit: true },
        );
        detailPage = openedPage ? await adoptPddDetailPage(openedPage) : pddPage;
        if (!detailPage.url().includes('/aftersales/work_order/tododetail')) {
          await detailPage.waitForURL('**/aftersales/work_order/tododetail**', { timeout: 30000 });
        }
        if (detailPage === pddPage) detailPage = await adoptPddDetailPage(pddPage);
        await detailPage.waitForLoadState('domcontentloaded');
      }
      await persistBrowserAuth(context, { pddAuthenticated: true });
      writeProgress({
        detailUrl: detailPage.url(),
        workOrderType: selectedType,
        scenarioCode: selectedScenarioCode,
        step: recoveredExactDetail ? 'verified-detail-recovered-after-pending-miss' : 'work-order-opened',
      });
      logRunStep('target-work-order-opened', { detailUrl: detailPage.url() });
      console.log(`已进入目标工单详情: ${detailPage.url()}`);
      }
    }
  } else {
    console.log(`已恢复未完成流程，跳过登录和重复点击: ${pddPage.url()}`);
    logRunStep('resume-existing-detail', { detailUrl: pddPage.url() });
  }
  persistSystemTabs('pdd');
  const completionRecoveryRequested = !reconcileExternalStateOnly && (
    recoveredExactDetail
    || (Boolean(requestedOrderNumber)
      && !isExtendedOrdinaryScenario(readProgress().scenarioCode || activeScenarioCode))
    || readProgress().pddResolutionSubmission?.recoveredFromCompletedPage === true
    || Boolean(readProgress().completedPageArchiveRecovery)
    || Boolean(readProgress().tmsPostalCarrierAliasRecovery)
  );
  if (completionRecoveryRequested && requestedOrderNumber) {
    detailPage = await reopenPddDetailForResolution(
      detailPage,
      requestedOrderNumber,
      readProgress(),
    );
    const recoveredState = hasConfirmedPendingListAbsence(readProgress(), requestedOrderNumber)
      ? completedPddStateFromPendingListAbsence(requestedOrderNumber)
      : await ensurePddResolutionDetailReady(
        detailPage,
        requestedOrderNumber,
        readProgress(),
        {
          readTimeoutMs: Math.min(pddRenderWaitMs, 10_000),
          settleMs: pddRenderWaitMs,
        },
      );
    if (recoveredState.isCompleted && recoveredState.orderMatches) {
      const completion = await runPddResolutionWorkflow(detailPage, requestedOrderNumber);
      await archiveAndResetCompletedOrder(completion);
      return { completed: true, orderNumber: requestedOrderNumber };
    }
  }
  if (reconcileExternalStateOnly) {
    const observation = await reconcilePddExternalState(detailPage, requestedOrderNumber || readProgress().orderNumber);
    return { reconciled: true, orderNumber: observation.orderNumber, observation };
  }
  const extendedProgress = readProgress();
  const extendedScenarioCode = extendedProgress.scenarioCode
    || activeScenarioCode
    || matchingScenarioForTitle(extendedProgress.workOrderType || activeWorkOrderType)?.code
    || null;
  if (isExtendedOrdinaryScenario(extendedScenarioCode)) {
    let bodyText;
    try {
      bodyText = await detailPage.locator('body').innerText({ timeout: 30_000 });
    } catch (error) {
      await pauseForTransientRetry(
        detailPage,
        'ordinary-scenario-order-identity',
        'PDD_ORDER_IDENTITY_TEMPORARILY_UNAVAILABLE',
        `新增普通工单详情页正文等待 30 秒后仍未完成渲染: ${error.message}`,
      );
    }
    const extendedOrderNumber = requestedOrderNumber
      || extendedProgress.orderNumber
      || parsePddOrderNumber(bodyText);
    if (!extendedOrderNumber) {
      await pauseForTransientRetry(
        detailPage,
        'ordinary-scenario-order-identity',
        'PDD_ORDER_IDENTITY_TEMPORARILY_UNAVAILABLE',
        '新增普通工单详情页未读取到订单编号，禁止执行外部操作',
      );
    }
    detailPage = await reopenPddDetailForResolution(
      detailPage,
      extendedOrderNumber,
      readProgress(),
    );
    const extendedPageState = hasConfirmedPendingListAbsence(
      readProgress(),
      extendedOrderNumber,
    )
      ? completedPddStateFromPendingListAbsence(extendedOrderNumber)
      : await ensurePddResolutionDetailReady(
        detailPage,
        extendedOrderNumber,
        readProgress(),
        { settleMs: Math.max(pddDetailSettleMs, 30_000) },
      );
    if (extendedPageState.isCompleted && extendedPageState.orderMatches
      && extendedScenarioCode !== CONSUMER_ADDRESS_CHANGE_CODE) {
      const inTransitCompletionProof = extendedScenarioCode === IN_TRANSIT_ADDRESS_CHANGE_CODE
        ? completedInTransitAddressChangeProof(extendedPageState, extendedOrderNumber)
        : null;
      if (inTransitCompletionProof && !inTransitCompletionProof.confirmed) {
        await pauseForManualReview(
          detailPage,
          'in-transit-address-change-completion-unverified',
          '平台显示工单已完结，但未在同单完成页核实在途改地址两个阶段的完整记录；禁止归档或重新提交',
          { inTransitAddressChangeCompletionProof: inTransitCompletionProof },
        );
      }
      const recoveredDecision = {
        ...(readProgress().ordinaryScenarioDecision || {}),
        scenarioCode: extendedScenarioCode,
        outcome: 'auto-submit',
        actionCode: 'pdd-completion-recovered',
        reasonCode: 'refreshed-exact-empty-pending-list',
        reason: '精确订单查询经刷新后仍为零条，平台普通工单已不在待处理列表',
        pdd: inTransitCompletionProof?.confirmed
          ? { option: '已联系快递公司修改',
            stageCode: IN_TRANSIT_ADDRESS_CHANGE_STAGE_CODES.result }
          : (readProgress().ordinaryScenarioDecision?.pdd || {}),
      };
      const completion = ordinaryCompletionFromState(
        extendedOrderNumber,
        extendedScenarioCode,
        recoveredDecision,
        { ...extendedPageState, recoveredFromCompletedPage: true,
          ...(inTransitCompletionProof
            ? { completedServiceEvidence: inTransitCompletionProof } : {}) },
      );
      await archiveAndResetCompletedOrder(completion);
      return { completed: true, orderNumber: extendedOrderNumber };
    }
    writeProgress({
      orderNumber: extendedOrderNumber,
      scenarioCode: extendedScenarioCode,
      workOrderType: extendedProgress.workOrderType || activeWorkOrderType,
      step: 'ordinary-scenario-starting',
    });
    const completion = await executeExtendedOrdinaryScenario(
      detailPage,
      extendedOrderNumber,
      extendedScenarioCode,
    );
    await archiveAndResetCompletedOrder(completion);
    return { completed: true, orderNumber: extendedOrderNumber };
  }
  let completedOrderNumber;
  if (resumedExistingDetail
    && progress.orderNumber
    && hasCompleteScenarioLogisticsAnalysis(
      progress.logisticsAnalysis,
      progress.orderNumber,
      progress.scenarioCode,
    )
    && !forceEvidenceRecapture
    && (!requestedOrderNumber || progress.orderNumber === requestedOrderNumber)) {
    if (progress.pddEvidenceOrderParsingRecovery) {
      detailPage = await reopenPddDetailForResolution(
        detailPage,
        progress.orderNumber,
        readProgress(),
        { forcePendingList: true },
      );
      const recoveryProgress = readProgress();
      if (hasConfirmedPendingListAbsence(recoveryProgress, progress.orderNumber)) {
        const completion = ordinaryCompletionFromPendingListAbsence(
          progress.orderNumber,
          progress.scenarioCode,
          recoveryProgress.ordinaryScenarioDecision || {},
        );
        await archiveAndResetCompletedOrder(completion);
        return { completed: true, orderNumber: progress.orderNumber };
      }
    }
    console.log(`复用已保存的订单编号和物流分析结果: ${progress.orderNumber}`);
    console.log(JSON.stringify(progress.logisticsAnalysis, null, 2));
    await openExpandedShippingLogistics(detailPage);
    await capturePddEvidenceScreenshot(detailPage, progress.orderNumber);
    completedOrderNumber = progress.orderNumber;
  } else {
    completedOrderNumber = (await analyzeWorkOrderShipping(detailPage)).orderNumber;
  }
  logRunStep('pdd-flow-complete', { orderNumber: completedOrderNumber });
  const afterPdd = readProgress();
  if (!hasCompleteScenarioOmsAnalysis(
    afterPdd.omsAnalysis,
    afterPdd.logisticsAnalysis,
    completedOrderNumber,
    afterPdd.scenarioCode,
  ) || forceOmsRecheck) {
    await focusSystemPage('oms', omsPage);
    await analyzeOmsOrder(omsPage, context, completedOrderNumber);
  } else {
    console.log(`复用已保存的 OMS 结果: ${completedOrderNumber}`);
  }
  await runScenarioStagesAfterOms(completedOrderNumber);
  // Keep using the already rendered and identity-checked detail tab. Re-entering
  // through the permanent list anchor can reopen the same case and trigger a
  // second verification challenge before the remark/submit stages.
  const completion = await runPddResolutionWorkflow(detailPage, completedOrderNumber);
  await archiveAndResetCompletedOrder(completion);
  return { completed: true, orderNumber: completedOrderNumber };
};

let workflowBusy = false;
let maintenanceBusy = false;
const runtimeObservationIntervalMs = 5_000;
const runtimeObservationPersistMs = 15_000;
let runtimeObservationBusy = false;
let lastRuntimeObservationSignature = '';
let lastRuntimeObservationPersistedAt = 0;
// A PDD challenge iframe can disappear briefly while the page redraws or
// processes a slider gesture. Keep the resident verification gate closed
// until the same challenge surface has been absent for the full grace period.
const residentVerificationAbsence = new Map();
const residentVerificationClearGraceMs = Math.max(
  humanVerificationAbsenceGraceMs,
  verificationPageRebindGraceMs,
);
const stableLoginObservedAt = new Map();
const idleSystemLoginAttemptAt = new Map();
const idleSystemLoginRetryMs = 60_000;

const idleSystemLoginCredentialsConfigured = (system) => (
  system === 'oms'
    ? omsMode === 'per-shop' && Boolean(process.env.JEOMS_ACCOUNT && process.env.JEOMS_PASSWORD)
    : system === 'tms' && Boolean(process.env.TMS_ACCOUNT && process.env.TMS_PASSWORD)
);

const recoverIdleSystemLogin = async (system, page) => {
  if (!idleSystemLoginCredentialsConfigured(system)) return false;
  const previousAttemptAt = idleSystemLoginAttemptAt.get(system) || 0;
  if (Date.now() - previousAttemptAt < idleSystemLoginRetryMs) return false;
  idleSystemLoginAttemptAt.set(system, Date.now());
  maintenanceBusy = true;
  try {
    if (system === 'oms') {
      await ensureOmsLogin(page, context, { residentWarmup: true });
      await confirmOmsBusinessPage(page, 'resident-idle-auto-login-confirm');
    } else {
      await ensureTmsLoginOnce(page, context);
    }
    updateAuthHealth(system, 'authenticated', page, {
      stage: `${system}-resident-auto-login`,
      source: 'resident-idle-auto-login',
      evidence: 'rendered-business-session',
    });
    await persistBrowserAuth(context).catch(() => {});
    persistSystemTabs(system);
    stableLoginObservedAt.delete(system);
    return true;
  } catch (error) {
    const verificationRequired = readProgress().authHealth?.[system]?.status === 'verification-required'
      || await hasHumanVerification(page).catch(() => false);
    updateAuthHealth(system, verificationRequired ? 'verification-required' : 'expired', page, {
      stage: `${system}-resident-auto-login`,
      source: 'resident-idle-auto-login',
      evidence: verificationRequired ? 'verification-required' : 'automatic-login-failed',
      lastError: error.message,
    });
    console.warn(`[runtime-observer] ${shopId}: ${system} automatic login deferred: ${error.message}`);
    return false;
  } finally {
    maintenanceBusy = false;
  }
};

// The PDD shell can retain the shop label after its live mall-info cache has
// disappeared. Once a challenge is absent, refresh an idle business page once
// to let PDD repopulate that cache. Never substitute the saved profile's mall
// ID, and never refresh a page that is processing a command or showing a gate.
const recoverMissingPddMallAfterVerification = async (targetPage, verificationId) => {
  const progress = readProgress();
  const identity = progress.pddShopIdentity || {};
  if (!residentCommandMode || workflowBusy || maintenanceBusy
    || activeAssignmentId || activeReturnRefundCommand || activeVerificationRecoveryCommand
    || pddManualLoginWaits > 0 || pddPostLoginStabilityWaits > 0
    || progress.residentCommand?.status === 'active'
    || !verificationId || !normalizePddMallId(expectedMallId)
    || !isPddBusinessPageForBarrier(targetPage)
    || identity.source !== 'confirmed-mall-id-unavailable' || identity.mallId
    || !pddIdentityMatches(configuredPddIdentityNames, identity.headerShopName)) return false;
  const previous = progress.pddMissingMallRecovery;
  if (previous?.verificationId === verificationId
    && previous.expectedMallId === expectedMallId) return false;
  if (await hasHumanVerification(targetPage).catch(() => true)) return false;
  const recovery = {
    verificationId,
    expectedMallId,
    url: targetPage.url(),
    status: 'refreshing',
    attemptedAt: new Date().toISOString(),
    externalActionsReplayed: false,
  };
  writeProgress({ pddMissingMallRecovery: recovery });
  try {
    await pacedAction(targetPage, 'pdd-missing-mall-readonly-refresh', () => targetPage.reload({
      waitUntil: 'domcontentloaded', timeout: 45_000,
    }));
    await targetPage.waitForTimeout(1_000);
    const confirmed = isPddBusinessPageForBarrier(targetPage)
      && !await hasHumanVerification(targetPage).catch(() => true)
      && await capturePddShopIdentity(targetPage).catch(() => false);
    writeProgress({ pddMissingMallRecovery: {
      ...recovery,
      status: confirmed ? 'identity-confirmed' : 'identity-unconfirmed',
      completedAt: new Date().toISOString(),
    } });
    return confirmed;
  } catch (error) {
    writeProgress({ pddMissingMallRecovery: {
      ...recovery, status: 'refresh-failed',
      error: error.message, completedAt: new Date().toISOString(),
    } });
    return false;
  }
};

const observeResidentRuntimeState = async () => {
  // The login owner alone resumes the workflow, after waiting on the same page.
  if (pddManualLoginWaits > 0 || pddPostLoginStabilityWaits > 0) return;
  if (runtimeObservationBusy || workflowStopping || browserFailureExiting || !browser.isConnected()) return;
  runtimeObservationBusy = true;
  try {
    let progress = readProgress();
    if (isPddBusinessPageForBarrier(pddPage)
      && (pddPostLoginBarrier?.deadlineAt > Date.now()
        || pddPostLoginBarrierPendingFromProgress(pddPage, progress))) {
      await waitForPddPostLoginBarrier(pddPage, 'resident-post-login-stability', {
        source: 'resident-runtime-observer',
      });
      return;
    }
    let blockedSystem = progress.verificationLocation?.system
      || Object.entries(progress.authHealth || {})
        .find(([, health]) => ['expired', 'verification-required'].includes(health?.status))?.[0]
      || (/^(?:manual-login-required|human-verification-required)$/u.test(String(progress.step || ''))
        ? progress.systemTabs?.activeSystem || 'pdd'
        : null);
    // Reconcile every system anchor from live pages. The persisted progress can
    // itself be stale, so it cannot be the prerequisite for observing reality.
    for (const system of ['pdd', 'oms', 'tms']) {
      const currentPage = system === 'pdd'
        ? pddPage
        : system === 'oms'
          ? (omsMode === 'shared' ? activeSharedOmsPage : omsPage)
          : tmsPage;
      // A shared OMS page belongs to a different persistent context. Its
      // workflow owner validates it while holding the global OMS lock; never
      // replace the resident shop's placeholder tab with an unrelated page.
      if (system === 'oms' && omsMode === 'shared') continue;
      const currentUrl = !currentPage || currentPage.isClosed() ? '' : currentPage.url();
      if (!isAuthenticatedSystemUrl(system, currentUrl)) {
        await adoptLiveSystemAnchor(system);
      }
    }
    progress = readProgress();
    const observableOmsPage = omsMode === 'shared'
      ? (activeSharedOmsPage && !activeSharedOmsPage.isClosed() ? activeSharedOmsPage : null)
      : omsPage;
    const pages = { pdd: pddPage, oms: observableOmsPage, tms: tmsPage };
    const urls = {
      pdd: !pddPage || pddPage.isClosed() ? null : pddPage.url(),
      oms: observableOmsPage
        ? observableOmsPage.url()
        : progress.authHealth?.oms?.url || progress.systemTabs?.oms?.url || null,
      tms: !tmsPage || tmsPage.isClosed() ? null : tmsPage.url(),
    };
    const observedAt = new Date().toISOString();
    const signature = JSON.stringify(urls);

    // A successful login may leave its derived login/QR tab alive beside the
    // authenticated permanent anchor. Remove only those stale login tabs
    // before challenge discovery; otherwise their obsolete CAPTCHA can put an
    // already authenticated shop back into human-verification-required.
    for (const [system, page] of Object.entries(pages)) {
      if (!page || page.isClosed() || !isAuthenticatedSystemUrl(system, urls[system])) continue;
      await closeStaleSystemLoginPages(
        page,
        system,
        (url) => isSystemLoginUrl(system, url),
        `${system}-resident-authenticated-anchor-cleanup`,
      );
    }

    // Observe every live tab. A challenge in a derived tab pauses the shop;
    // the resident focus keeper selects its actual tab until it clears.
    const crossTabVerifications = [];
    for (const [system, page] of Object.entries(pages)) {
      if (!page || page.isClosed()) continue;
      const located = await locateHumanVerificationAcrossPages(
        page,
        system,
        `${system}-resident-cross-tab-observer`,
        { requireStable: true },
      );
      if (located) crossTabVerifications.push({ system, ...located });
    }
    const discoveredVerification = crossTabVerifications.find((entry) => entry.system === blockedSystem)
      || crossTabVerifications[0]
      || null;
    for (const system of ['pdd', 'oms', 'tms']) {
      if (crossTabVerifications.some((entry) => entry.system === system)) {
        // A fresh rendered challenge cancels any pending absence timer. The
        // original tab remains authoritative until a later stable clear.
        residentVerificationAbsence.delete(system);
      }
    }
    if (discoveredVerification) {
      const discoveredSystem = discoveredVerification.system;
      // Prefer the system with a live challenge over a stale persisted
      // blockedSystem value; the next observation will reconcile any other
      // system independently.
      blockedSystem = discoveredSystem;
      const existingLocation = progress.verificationLocation;
      const locationStage = existingLocation?.system === discoveredSystem
        && existingLocation.stage
        ? existingLocation.stage
        : `${discoveredSystem}-resident-cross-tab-observer`;
      const location = await locateHumanVerification(
        discoveredVerification.page,
        discoveredSystem,
        locationStage,
        null,
        discoveredVerification.detection,
        {
          source: 'cross-tab-runtime-observer',
          pageRole: discoveredVerification.pageRole,
          originUrl: existingLocation?.originUrl || discoveredVerification.page.url(),
          originPageRole: existingLocation?.originPageRole || discoveredVerification.pageRole,
        },
      );
      const locationChanged = !existingLocation
        || existingLocation.id !== location.id
        || existingLocation.url !== location.url
        || existingLocation.pageRole !== location.pageRole;
      const healthStatus = progress.authHealth?.[discoveredSystem]?.status;
      if (locationChanged || healthStatus !== 'verification-required') {
        updateAuthHealth(discoveredSystem, 'verification-required', discoveredVerification.page, {
          stage: locationStage,
          source: 'cross-tab-runtime-observer',
          evidence: 'challenge-rendered-in-derived-tab',
        });
        writeProgress({
          step: 'human-verification-required',
          verificationStage: locationStage,
          currentUrl: discoveredVerification.page.url(),
          verificationLocation: location,
          verificationFocus: existingLocation?.id === location.id
            ? progress.verificationFocus
            : {
              status: 'queued',
              stage: locationStage,
              queuedAt: observedAt,
            },
          runtimeObservation: {
            observedAt,
            recoveredSystem: null,
            source: 'cross-tab-runtime-observer',
            urls,
            verificationPageRole: discoveredVerification.pageRole,
          },
          error: null,
        });
        progress = readProgress();
      }
      if (isImageClickVerificationDetection(discoveredVerification.detection)) {
        const closeResult = await releaseImageClickVerificationAfterClose({
          system: discoveredSystem,
          stage: locationStage,
          page: discoveredVerification.page,
          detection: discoveredVerification.detection,
          location,
        }).catch((error) => ({
          closed: false,
          released: false,
          reason: error.message,
        }));
        if (closeResult.released) {
          lastRuntimeObservationSignature = signature;
          lastRuntimeObservationPersistedAt = Date.now();
          return;
        }
      }
      // The resident cross-tab observer can be the first and only path that
      // sees a business-page slider/puzzle while the ordinary workflow is
      // waiting on another action.  Close the challenge immediately through
      // its own X and release the current order back to the queue; otherwise
      // this observer would hold the shop for the two-minute timeout. Login
      // pages stay excluded so a real authentication challenge remains for
      // the operator.
      if (businessVerificationAutoCloseEnabled
        && !isSystemLoginUrl(discoveredSystem, discoveredVerification.page.url())) {
        const closeResult = await releaseImageClickVerificationAfterClose({
          system: discoveredSystem,
          stage: locationStage,
          page: discoveredVerification.page,
          detection: discoveredVerification.detection,
          location,
          allowBusinessVerification: true,
        }).catch((error) => ({
          closed: false,
          released: false,
          reason: error.message,
        }));
        if (closeResult.released) {
          lastRuntimeObservationSignature = signature;
          lastRuntimeObservationPersistedAt = Date.now();
          return;
        }
      }
      const persistedLocation = progress.verificationLocation;
      const persistedDetectedAtMs = Date.parse(String(persistedLocation?.detectedAt || ''));
      const livePersistedVerification = persistedLocation
        && crossTabVerifications.find((entry) => (
          entry.system === persistedLocation.system
          && (!persistedLocation.url || entry.page.url() === persistedLocation.url)
        ));
      if (livePersistedVerification
        && Number.isFinite(persistedDetectedAtMs)
        && Date.now() - persistedDetectedAtMs >= humanVerificationMaxTimeoutMs) {
        const expired = await expireResidentVerificationIfOverdue({
          system: persistedLocation.system,
          stage: persistedLocation.stage || locationStage,
          located: livePersistedVerification,
          progress,
          observedAt,
        });
        if (expired) {
          lastRuntimeObservationSignature = signature;
          lastRuntimeObservationPersistedAt = Date.now();
          return;
        }
      }
      const timeoutState = progress.verificationTimeout;
      const currentVerificationFingerprint = verificationSurfaceFingerprint({
        system: discoveredSystem,
        page: discoveredVerification.page,
        detection: discoveredVerification.detection,
        pageRole: discoveredVerification.pageRole,
      });
      const pluginStillOwnsChallenge = timeoutState?.status === 'waiting'
        && timeoutState.fingerprint === currentVerificationFingerprint;
      if (!pluginStillOwnsChallenge) {
        void ensureResidentVerificationFocus({
          page: discoveredVerification.page,
          system: discoveredSystem,
          stage: locationStage,
        }).catch((error) => {
          console.warn(`[验证码标签驻留] ${shopId}: ${error.message}`);
        });
      }
    }

    if (blockedSystem
      // The cross-tab scan above is the freshest rendered-page evidence. A
      // derived PDD detail tab can be classified as a generic workflow page
      // by the narrower cleanup scan below; never clear and recreate the same
      // live challenge in one observation cycle.
      && !crossTabVerifications.some((entry) => entry.system === blockedSystem)
      && pages[blockedSystem]
      && isAuthenticatedSystemUrl(blockedSystem, urls[blockedSystem])) {
      const targetPage = pages[blockedSystem];
      // A challenge can live in a derived detail tab while the permanent
      // system anchor is already back on an authenticated list page. Do not
      // clear the persisted verification state until every live page for the
      // blocked system is clear.
      const blockedContext = blockedSystem === 'oms' && omsMode === 'shared'
        ? activeSharedOmsContext
        : context;
      const blockedSystemPages = (blockedContext?.pages() || []).filter((page) => (
        !page.isClosed() && workflowSystemForAction(page) === blockedSystem
      ));
      // No live page is not proof that a challenge disappeared. Treat the
      // scan as blocked until the resident anchor and its derived tabs exist.
      let verificationPresent = blockedSystemPages.length === 0;
      for (const candidate of blockedSystemPages) {
        if (await hasHumanVerification(candidate).catch(() => true)) {
          verificationPresent = true;
          break;
        }
      }
      const persistedVerificationForSystem = progress.verificationLocation?.system === blockedSystem
        || progress.authHealth?.[blockedSystem]?.status === 'verification-required';
      if (persistedVerificationForSystem && verificationPresent) {
        residentVerificationAbsence.delete(blockedSystem);
        // Do not let the idle observer adopt, clean up, or recover a queue
        // while a challenge is still visible in any live tab.
        return;
      }
      if (!verificationPresent) {
        if (persistedVerificationForSystem) {
          const persistedUrl = String(progress.verificationLocation?.url || '').trim();
          const observedUrl = persistedUrl || targetPage.url();
          const absenceKey = [
            blockedSystem,
            progress.verificationLocation?.id || '',
            persistedUrl,
          ].join('|');
          const previousAbsence = residentVerificationAbsence.get(blockedSystem);
          if (!previousAbsence
            || previousAbsence.key !== absenceKey
            || previousAbsence.url !== observedUrl) {
            residentVerificationAbsence.set(blockedSystem, {
              key: absenceKey,
              url: observedUrl,
              startedAt: Date.now(),
            });
            console.warn(
              `[验证码驻留] ${shopId}: ${blockedSystem} 验证码检测短暂消失，` +
              `保持原状态 ${residentVerificationClearGraceMs / 1000} 秒后再确认，不恢复队列。`,
            );
            return;
          }
          const absentForMs = Date.now() - previousAbsence.startedAt;
          if (absentForMs < residentVerificationClearGraceMs) return;
          // Require an authenticated, non-error business page before clearing
          // the old checkpoint. A URL alone is insufficient after a redraw.
          if (!isAuthenticatedSystemUrl(blockedSystem, urls[blockedSystem])
            || (blockedSystem === 'pdd' && (
              !isPddBusinessPageForBarrier(targetPage)
              || isBrowserNetworkErrorUrl(urls.pdd)
            ))) return;
          if (blockedSystem === 'pdd') {
            let identityConfirmed = await capturePddShopIdentity(targetPage).catch(() => false);
            if (!identityConfirmed) {
              identityConfirmed = await recoverMissingPddMallAfterVerification(
                targetPage, progress.verificationLocation?.id,
              );
            }
            if (!identityConfirmed) {
              console.warn(`[验证码驻留] ${shopId}: 业务页身份尚未稳定确认，继续保持验证闸门。`);
              return;
            }
          }
          residentVerificationAbsence.delete(blockedSystem);
        }
        if (blockedSystem === 'pdd') {
          await waitForPddPostLoginBarrier(targetPage, 'resident-session-recovery', {
            source: 'resident-session-recovery',
          });
        }
        const clearedVerification = progress.verificationLocation?.system === blockedSystem
          || progress.authHealth?.[blockedSystem]?.status === 'verification-required';
        const clearedVerificationId = progress.verificationLocation?.id || null;
        const verificationDetectedAt = progress.verificationLocation?.detectedAt || null;
        if (blockedSystem === 'pdd'
          && !await capturePddShopIdentity(targetPage).catch(() => false)) return;
        if (blockedSystem === 'pdd' && clearedVerification) {
          pddPostLoginRecoveryPacing.start();
        }
        updateAuthHealth(blockedSystem, 'authenticated', targetPage, { stage: null });
        progress = readProgress();
        writeProgress({
          step: /^(?:manual-login-required|human-verification-required)$/u.test(String(progress.step || ''))
              ? `${blockedSystem}-session-recovered` : progress.step,
          verificationStage: progress.verificationLocation?.system === blockedSystem ? null : progress.verificationStage,
          verificationLocation: progress.verificationLocation?.system === blockedSystem ? null : progress.verificationLocation,
          verificationFocus: progress.verificationLocation?.system === blockedSystem ? null : progress.verificationFocus,
          verificationRecovery: progress.verificationLocation?.system === blockedSystem ? null : progress.verificationRecovery,
          verificationRecheck: clearedVerification ? {
            trigger: 'resident-browser-live-pages',
            status: 'cleared',
            verificationId: clearedVerificationId,
            detectedAt: verificationDetectedAt,
            completedAt: observedAt,
          } : progress.verificationRecheck,
          manualReview: null,
          ...(blockedSystem === 'pdd' ? { systemLogin: null } : {}),
          systemTabs: {
            pdd: { url: urls.pdd },
            oms: { url: urls.oms },
            tms: { url: urls.tms },
            activeSystem: blockedSystem,
            checkedAt: observedAt,
          },
          runtimeObservation: {
            observedAt,
            recoveredSystem: blockedSystem,
            source: 'resident-browser-live-pages',
            urls,
          },
          currentUrl: urls[blockedSystem],
          error: null,
        });
        await persistBrowserAuth(blockedContext || context).catch(() => {});
        lastRuntimeObservationSignature = signature;
        lastRuntimeObservationPersistedAt = Date.now();
        stableLoginObservedAt.delete(blockedSystem);
        return;
      }
    }

    if (!workflowBusy) {
      for (const [system, page] of Object.entries(pages)) {
        const url = urls[system];
        if (!page || page.isClosed() || !url) continue;
        const health = readProgress().authHealth?.[system];
        const stage = `${system}-idle-session-observer`;
        const priorObservation = health?.lastObservation || health;
        const legacyWeakExpiry = health?.status === 'expired'
          && health?.stage === stage
          && isWeakAuthHealthEvidence(health);
        if (!isSystemLoginUrl(system, url)) {
          stableLoginObservedAt.delete(system);
          if (!isAuthenticatedSystemUrl(system, url)
            && (legacyWeakExpiry
              || priorObservation?.stage !== stage
              || priorObservation?.url !== url)) {
            updateAuthHealth(system, 'unknown', page, {
              stage,
              confidence: 'weak',
              source: 'resident-idle-url-observer',
              evidence: url === 'about:blank' ? 'about:blank' : 'unprobed-page',
            });
          }
          continue;
        }
        const firstObservedAt = stableLoginObservedAt.get(system) || Date.now();
        stableLoginObservedAt.set(system, firstObservedAt);
        if (Date.now() - firstObservedAt < 10_000) continue;
        const renderedLoginState = system === 'oms'
          ? await readOmsAppState(page)
          : null;
        const pddSessionExpired = system === 'pdd';
        const renderedLoginConfirmed = Boolean(
          pddSessionExpired || system === 'tms'
          || renderedLoginState?.loginForm || renderedLoginState?.loggedOut,
        );
        if (renderedLoginConfirmed) {
          const confirmedStage = pddSessionExpired
            ? 'pdd-rendered-login-route'
            : system === 'tms' ? `${system}-stable-login-route`
              : `${system}-rendered-login-confirmation`;
          const confirmedIdleExpiry = health?.status === 'expired'
            && health?.stage === confirmedStage
            && !isWeakAuthHealthEvidence(health)
            && health?.url === url;
          if (!confirmedIdleExpiry) {
            updateAuthHealth(system, 'expired', page, {
              stage: confirmedStage,
              confidence: 'confirmed',
              source: pddSessionExpired ? 'resident-login-route-observer'
                : system === 'tms' ? 'resident-login-route-observer'
                  : 'resident-login-dom-observer',
              evidence: pddSessionExpired ? 'rendered-login-url'
                : system === 'tms' ? 'stable-login-route'
                  : renderedLoginState.loggedOut
                    ? 'rendered-logged-out-state'
                    : 'rendered-login-form',
            });
          }
          if (pddSessionExpired && (health?.status === 'verification-required'
            || progress.verificationLocation?.system === 'pdd')) {
            const observed = readProgress();
            writeProgress({
              step: 'manual-login-required',
              verificationStage: null,
              verificationLocation: null,
              verificationFocus: null,
              verificationRecovery: null,
              systemLogin: {
                system: 'pdd',
                status: 'required',
                stage: confirmedStage,
                url,
                reason: '拼多多页面已返回登录入口，请重新登录',
                detectedAt: observedAt,
              },
              verificationRecheck: {
                trigger: 'resident-login-route-observer',
                status: 'login-required',
                verificationId: observed.verificationLocation?.id || null,
                completedAt: observedAt,
              },
            });
          }
          await recoverIdleSystemLogin(system, page);
          continue;
        }
        if (!legacyWeakExpiry
          && priorObservation?.stage === stage && priorObservation?.url === url) continue;
        updateAuthHealth(system, 'unknown', page, {
          stage,
          confidence: 'weak',
          source: 'resident-idle-url-observer',
          evidence: url === 'about:blank' ? 'about:blank' : 'login-url-only',
        });
      }
    }
    if (signature !== lastRuntimeObservationSignature
      || Date.now() - lastRuntimeObservationPersistedAt >= runtimeObservationPersistMs) {
      progress = readProgress();
      writeProgress({
        systemTabs: {
          pdd: { url: urls.pdd },
          oms: { url: urls.oms },
          tms: { url: urls.tms },
          activeSystem: progress.systemTabs?.activeSystem || null,
          checkedAt: observedAt,
        },
        runtimeObservation: {
          observedAt,
          recoveredSystem: null,
          source: 'resident-browser-live-pages',
          urls,
        },
      });
      lastRuntimeObservationSignature = signature;
      lastRuntimeObservationPersistedAt = Date.now();
    }
  } finally {
    runtimeObservationBusy = false;
  }
};

const checkpointTimer = setInterval(() => {
  persistBrowserAuth(context).catch((error) => {
    console.error(`认证检查点保存失败: ${error.message}`);
  });
}, authCheckpointMs);
// The business loop validates the active system immediately before use. A
// periodic cross-system refresh used to navigate OMS/TMS away from their
// working pages and repeatedly reopen the TMS menu, so it is intentionally
// disabled for the resident browser process.
if (browserStartupHealthTimer) {
  clearInterval(browserStartupHealthTimer);
  browserStartupHealthTimer = null;
}
const healthTimer = setInterval(() => {
  probeBrowserHealth().catch((error) => exitForBrowserFailure('browser-health-probe-crashed', error));
}, browserHealthIntervalMs);
healthTimer.unref?.();
const runtimeObservationTimer = setInterval(() => {
  observeResidentRuntimeState().catch((error) => {
    console.error(`[runtime-observer] ${shopId}: ${error.message}`);
  });
}, runtimeObservationIntervalMs);
runtimeObservationTimer.unref?.();
probeBrowserHealth().catch((error) => exitForBrowserFailure('browser-health-probe-crashed', error));

const stopWorkflow = async () => {
  workflowStopping = true;
  clearInterval(checkpointTimer);
  if (browserStartupHealthTimer) clearInterval(browserStartupHealthTimer);
  if (healthTimer) clearInterval(healthTimer);
  if (runtimeObservationTimer) clearInterval(runtimeObservationTimer);
  verificationFocusCoordinator.release();
  await persistBrowserAuth(context).catch(() => {});
  await browser.close().catch(() => {});
  await markChromiumProfileClean();
  releaseWorkflowLock();
};
// The supervisor uses IPC for shutdown on Windows.  `child.kill()` can be
// forceful there and leaves Chromium's profile marked as crashed, so always
// let the workflow close its persistent context first.
process.on('message', (message) => {
  if (message?.type === 'browser-health-restart') {
    exitForBrowserFailure(message.reason || 'runner-requested-browser-restart');
    return;
  }
  if (message?.type !== 'shutdown') return;
  stopWorkflow().finally(() => process.exit(0));
});
process.once('SIGINT', () => { stopWorkflow().finally(() => process.exit(0)); });
process.once('SIGTERM', () => { stopWorkflow().finally(() => process.exit(0)); });

let residentSystemsInitialized = false;
try {
  const browserStarted = {
    browserUrl: pddPage.url() === 'about:blank' ? 'persistent-context-starting' : pddPage.url(),
    browserMode,
    workflowDataDir,
    targetWorkOrderTitle,
  };
  if (activeAssignmentId || !residentCommandMode) {
    logRunStep('browser-started', browserStarted);
  } else {
    writeProgress({
      browserRuntime: {
        state: 'started',
        startedAt: new Date().toISOString(),
        browserMode,
        workflowDataDir,
        targetWorkOrderTitle,
      },
      browserUrl: browserStarted.browserUrl,
    });
  }
  if (process.env.PDD_DISCOVER_ONLY === 'true') {
    // A resident browser is command-driven. Do not signal readiness until the
    // permanent PDD/OMS/TMS anchors have finished their startup work. The old
    // ordering allowed the supervisor to send `discover` while initialization
    // was still blocking the command loop; after the apply timeout it recycled
    // a healthy browser, which looked like a window flicker and lost progress.
    await initializeResidentSystemsForDiscovery();
    residentSystemsInitialized = true;
    if (residentCommandMode) {
      resetResidentAssignment();
      await new Promise((resolve, reject) => {
        process.send({
          type: 'workflow-resident-ready',
          shopId,
          url: pddPage.url(),
          readyAt: new Date().toISOString(),
          sourceSha256: workflowSourceSha256,
          returnRefundAdapterSha256: returnRefundAdapterSourceSha256,
        }, (error) => {
          if (error) reject(error);
          else resolve();
        });
      });
    }
    if (!residentCommandMode) {
      await runPddDiscoveryOnly();
      if (process.env.WORKFLOW_DISCOVERY_KEEP_ALIVE === 'true' && browserKeepsAlive) {
        await finishCurrentRun();
      } else {
        await finishDiscoveryRun();
      }
      process.exit(0);
    }
  }
  if (!reconcileExternalStateOnly && !residentSystemsInitialized) {
    await restoreAndAuthenticateSystemTabs(readProgress());
    residentSystemsInitialized = true;
  }
  while (true) {
    if (residentCommandMode && !requestedOrderNumber && !reconcileExternalStateOnly) {
      const action = await applyResidentCommand(await nextResidentCommand());
      if (action === 'chat-collect') {
        try {
          await runChatCollectionOnly();
          resetResidentAssignment();
        } catch (error) {
          await completeFailedResidentCommand(action, error);
        }
        continue;
      }
      if (action === 'discover') {
        try {
          await runPddDiscoveryOnly();
          resetResidentAssignment();
        } catch (error) {
          await completeFailedResidentCommand(action, error);
        }
        continue;
      }
      if (action === 'refund-scan') {
        try {
          await runReturnRefundScanOnly();
          resetResidentAssignment();
        } catch (error) {
          await completeFailedResidentCommand(action, error);
        }
        continue;
      }
      if (action === 'restore-verification') {
        try {
          await runRestoredVerificationRecoveryOnly();
          resetResidentAssignment({ outcome: 'verification-cleared' });
        } catch (error) {
          await completeFailedVerificationRecoveryCommand(error);
        }
        continue;
      }
    }
    try {
      while (maintenanceBusy) await pddPage.waitForTimeout(1000);
      await waitForPddPostLoginBarrier(pddPage, 'resident-workflow-start', {
        source: 'resident-workflow-start',
      });
      workflowBusy = true;
      if (activeReturnRefundCommand?.action === 'run-refund') {
        await runReturnRefundClaimOnly();
        workflowBusy = false;
        resetResidentAssignment();
        continue;
      }
      const result = await processOneWorkOrder();
      workflowBusy = false;
      pageCrashRecoveryAttempts = 0;
      if (requestedOrderNumber && result.completed) {
        writeProgress({
          step: 'requested-order-complete',
          loopState: {
            ...(readProgress().loopState || {}),
            status: 'waiting',
            currentOrderNumber: null,
            nextPollAt: null,
          },
        });
        if (residentCommandMode) {
          resetResidentAssignment();
          continue;
        }
        await finishCurrentRun();
        break;
      }
      if (requestedOrderNumber && result.reconciled) {
        if (residentCommandMode) {
          resetResidentAssignment();
          continue;
        }
        await finishDiscoveryRun();
        break;
      }
      if (result.queueEmpty) {
        const nextPollAt = calculateNextPollAt(Date.now(), emptyQueuePollMs);
        writeProgress({
          step: 'queue-empty-waiting',
          manualReview: null,
          loopState: {
            ...(readProgress().loopState || {}),
            status: 'waiting',
            currentOrderNumber: null,
            nextPollAt,
          },
          currentUrl: pddPage.url(),
          error: null,
        });
        await persistBrowserAuth(context);
        console.log(`当前无目标待处理工单，将在 ${Math.ceil(emptyQueuePollMs / 60000)} 分钟后重新查询。`);
        await pddPage.waitForTimeout(emptyQueuePollMs);
      }
    } catch (error) {
      workflowBusy = false;
      if (await recoverCrashedSystemPages(error)) continue;
      if (error instanceof ManualReviewRequiredError) {
        if (nonRetryableManualReviewStages.has(error.stage)) {
          blockManualReview(error);
          console.error(`[人工复核暂停] ${error.message}；该阶段不会自动重复判断，浏览器保持打开。`);
          await persistBrowserAuth(context).catch(() => {});
          if (residentCommandMode) {
            resetResidentAssignment({ outcome: 'manual-review-blocked' });
            continue;
          }
          await finishCurrentRun({ failed: false });
          break;
        }
        const current = readProgress();
        writeProgress({
          step: 'manual-review-waiting',
          manualReview: {
            ...(current.manualReview || {}),
            status: 'waiting',
            lastRetryAt: new Date().toISOString(),
          },
          error: null,
        });
        console.error(`[人工复核等待] ${error.message}；${Math.ceil(manualReviewPollMs / 1000)} 秒后重新检查。`);
        await persistBrowserAuth(context).catch(() => {});
        await pddPage.waitForTimeout(manualReviewPollMs);
        // Retry only the current business stage. The three resident system
        // tabs must not be navigated or rebuilt during manual-review polling.
        continue;
      }
      if (error instanceof LogisticsRetryRequiredError) {
        const current = readProgress();
        const waitEntry = releaseCurrentOrderForLogisticsWait({
          orderNumber: error.orderNumber || current.orderNumber,
          detailUrl: error.detailUrl || current.detailUrl,
          scenarioCode: error.scenarioCode || current.scenarioCode,
          workOrderType: error.workOrderType || current.workOrderType,
          rowFingerprint: error.rowFingerprint || current.rowFingerprint,
          retryAfterMs: error.retryAfterMs,
          waitKind: error.stage === 'pdd-consumer-negotiation-waiting'
            ? 'consumer-response'
            : 'logistics',
          reason: error.message,
        });
        await closeOrdinaryLogisticsDerivedPages();
        persistSystemTabs('pdd');
        const releaseAction = externalEffectGuardEnabled ? '已交还数据库队列' : '继续扫描下一单';
        const waitLabel = waitEntry?.waitKind === 'consumer-response' ? '消费者回复等待' : '物流等待';
        console.log(`[${waitLabel}] ${waitEntry?.orderNumber || current.orderNumber} 已释放当前单，下一轮在 ${waitEntry?.retryAfterAt || '稍后'} 重新检查；${releaseAction}。`);
        await persistBrowserAuth(context).catch(() => {});
        if (externalEffectGuardEnabled) {
          if (residentCommandMode) {
            resetResidentAssignment();
            continue;
          }
          await finishDiscoveryRun();
          break;
        }
        continue;
      }
      if (residentCommandMode
        && (error instanceof HumanVerificationRequiredError
          || error instanceof PddLoginRequiredError
          || error instanceof RateLimitPauseError)) {
        const outcome = residentCommandFailureStatus(error);
        const verificationPause = outcome === 'verification-required';
        const verificationTimeout = outcome === 'verification-timeout';
        const loginPause = outcome === 'login-required';
        console.error(verificationTimeout
          ? `[人工验证超时] 验证码已关闭，当前工单释放为可重试，不计入成功。`
          : verificationPause
          ? `[人工验证等待] ${error.message}；验证码页保持打开，当前工单已释放等待后续恢复。`
          : loginPause
            ? `[登录等待] ${error.message}；登录页保持打开，当前工单已释放等待登录恢复。`
            : `[平台限流等待] ${error.message}；当前工单已释放等待后续恢复。`);
        await persistBrowserAuth(context).catch(() => {});
        if (!verificationPause && !verificationTimeout && !loginPause) {
          for (const page of [...derivedPages]) {
            if (!page.isClosed()) await closeDerivedPage(page);
          }
        }
        persistSystemTabs('pdd');
        resetResidentAssignment({ outcome });
        continue;
      }
      if (residentCommandMode) {
        const activePage = currentSystemPage();
        writeProgress({ step: 'flow-paused', error: error.message, currentUrl: activePage.url() });
        await saveWorkflowDiagnostics(activePage, 'flow-paused', error).catch(() => {});
        console.error(error.stack || error.message);
        console.error(`流程暂停，浏览器保持打开: ${error.message}`);
        await persistBrowserAuth(context).catch(() => {});
        for (const page of [...derivedPages]) {
          if (!page.isClosed()) await closeDerivedPage(page);
        }
        persistSystemTabs('pdd');
        resetResidentAssignment({ outcome: 'flow-paused' });
        continue;
      }
      throw error;
    }
  }
} catch (error) {
  workflowBusy = false;
  const activePage = currentSystemPage();
  if (!(error instanceof HumanVerificationRequiredError)
    && !(error instanceof PddLoginRequiredError)
    && !(error instanceof RateLimitPauseError)
    && !(error instanceof ManualReviewRequiredError)) {
    writeProgress({ step: 'flow-paused', error: error.message, currentUrl: activePage.url() });
    await saveWorkflowDiagnostics(activePage, 'flow-paused', error).catch(() => {});
  }
  console.error(browserHeadless
    ? `流程暂停，已保存状态和诊断信息: ${error.message}`
    : `流程暂停，浏览器保持打开: ${error.message}`);
  console.error(error.stack || error.message);
  await finishCurrentRun({
    failed: !(error instanceof HumanVerificationRequiredError
      || error instanceof PddLoginRequiredError
      || error instanceof RateLimitPauseError
      || error instanceof ManualReviewRequiredError),
  });
}
